/* 播放清单：期号、考点、行 id、音频路径与时长（五册；外壳与页面按册过滤）。由 build.py 生成，请勿手改。 */
var PLAYLIST = [{"ep":"bx1-01","n":"BX1-01","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-01/in1.mp3","sec":7.992,"t":"同学们好！这节课梳理人教版必修一第一章第一节——细胞是生命活动的基本单位。"},{"ep":"bx1-01","n":"BX1-01","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-01/in2.mp3","sec":7.416,"t":"高考常考细胞学说的建立过程和意义、归纳法，以及生命系统的结构层次。"},{"ep":"bx1-01","n":"BX1-01","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-01/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-01","n":"BX1-01","p":1,"a":"p1","id":"hi1","src":"assets/audio/BX1-01/hi1.mp3","sec":11.064,"t":"考点一，细胞学说的建立过程。比利时的维萨里揭示了人体在器官水平的结构，法国的比夏指出器官由组织构成。"},{"ep":"bx1-01","n":"BX1-01","p":1,"a":"p1","id":"hi2","src":"assets/audio/BX1-01/hi2.mp3","sec":9.12,"t":"1665年，英国的胡克观察软木薄片，看到许多“小室”，把它们命名为细胞。"},{"ep":"bx1-01","n":"BX1-01","p":1,"a":"p1","id":"hi3","src":"assets/audio/BX1-01/hi3.mp3","sec":7.032,"t":"荷兰的列文虎克用自制显微镜观察到了细菌、红细胞和精子等活细胞。"},{"ep":"bx1-01","n":"BX1-01","p":1,"a":"p1","id":"hi4","src":"assets/audio/BX1-01/hi4.mp3","sec":7.752,"t":"十九世纪三十年代，德国的施莱登和施旺分别研究植物和动物，建立了细胞学说。"},{"ep":"bx1-01","n":"BX1-01","p":1,"a":"p1","id":"hi5","src":"assets/audio/BX1-01/hi5.mp3","sec":5.856,"t":"后来，德国的魏尔肖总结出：细胞通过分裂产生新细胞。"},{"ep":"bx1-01","n":"BX1-01","p":1,"a":"p1","id":"hi6","src":"assets/audio/BX1-01/hi6.mp3","sec":8.4,"t":"易错：胡克看到的是死细胞，只是细胞的命名者；细胞学说的建立者是施莱登和施旺。"},{"ep":"bx1-01","n":"BX1-01","p":2,"a":"p2","id":"co1","src":"assets/audio/BX1-01/co1.mp3","sec":4.296,"t":"考点二，细胞学说的主要内容，一共三点。"},{"ep":"bx1-01","n":"BX1-01","p":2,"a":"p2","id":"co2","src":"assets/audio/BX1-01/co2.mp3","sec":8.424,"t":"第一，细胞是一个有机体，一切动植物都由细胞发育而来，并由细胞和细胞产物所构成。"},{"ep":"bx1-01","n":"BX1-01","p":2,"a":"p2","id":"co3","src":"assets/audio/BX1-01/co3.mp3","sec":9.072,"t":"第二，细胞是一个相对独立的单位，既有它自己的生命，又对与其他细胞共同组成的整体生命起作用。"},{"ep":"bx1-01","n":"BX1-01","p":2,"a":"p2","id":"co4","src":"assets/audio/BX1-01/co4.mp3","sec":7.944,"t":"第三，新细胞是由老细胞分裂产生的，这一点是在魏尔肖的观点基础上修正补充的。"},{"ep":"bx1-01","n":"BX1-01","p":2,"a":"p2","id":"co5","src":"assets/audio/BX1-01/co5.mp3","sec":9.576,"t":"易错：细胞学说说的是一切动植物，不是一切生物——病毒没有细胞，细菌等原核生物也不在其中。"},{"ep":"bx1-01","n":"BX1-01","p":3,"a":"p3","id":"me1","src":"assets/audio/BX1-01/me1.mp3","sec":8.28,"t":"考点三，细胞学说的意义。它揭示了动物和植物的统一性，从而阐明了生物界的统一性。"},{"ep":"bx1-01","n":"BX1-01","p":3,"a":"p3","id":"me2","src":"assets/audio/BX1-01/me2.mp3","sec":8.592,"t":"它使生物学研究由器官、组织水平进入细胞水平，并为后来进入分子水平打下基础。"},{"ep":"bx1-01","n":"BX1-01","p":3,"a":"p3","id":"me3","src":"assets/audio/BX1-01/me3.mp3","sec":8.376,"t":"它还为生物进化论的确立埋下了伏笔：既然都由细胞构成，生物之间就可能有共同的祖先。"},{"ep":"bx1-01","n":"BX1-01","p":3,"a":"p3","id":"me4","src":"assets/audio/BX1-01/me4.mp3","sec":9.456,"t":"考法：判断说法是否正确。易错：细胞学说没有揭示多样性，也没有揭示动植物细胞的区别。"},{"ep":"bx1-01","n":"BX1-01","p":4,"a":"p4","id":"id1","src":"assets/audio/BX1-01/id1.mp3","sec":8.592,"t":"考点四，科学方法——归纳法。归纳法是由一系列具体事实推出一般结论的思维方法。"},{"ep":"bx1-01","n":"BX1-01","p":4,"a":"p4","id":"id2","src":"assets/audio/BX1-01/id2.mp3","sec":6.864,"t":"完全归纳法，是考察了某类事物的全部对象后得出结论，结论是可信的。"},{"ep":"bx1-01","n":"BX1-01","p":4,"a":"p4","id":"id3","src":"assets/audio/BX1-01/id3.mp3","sec":8.424,"t":"不完全归纳法，只考察了部分对象就得出结论，结论可能有例外，但可以用来预测和判断。"},{"ep":"bx1-01","n":"BX1-01","p":4,"a":"p4","id":"id4","src":"assets/audio/BX1-01/id4.mp3","sec":8.592,"t":"施莱登和施旺只观察了部分动植物，就得出一切动植物都由细胞构成，用的是不完全归纳法。"},{"ep":"bx1-01","n":"BX1-01","p":4,"a":"p4","id":"id5","src":"assets/audio/BX1-01/id5.mp3","sec":10.464,"t":"解题方法：看是否考察了全部对象——没有穷尽的，就是不完全归纳法。科学研究中经常运用不完全归纳法。"},{"ep":"bx1-01","n":"BX1-01","p":5,"a":"p5","id":"li1","src":"assets/audio/BX1-01/li1.mp3","sec":10.704,"t":"考点五，生命活动离不开细胞。单细胞生物如草履虫，一个细胞就能完成运动、摄食、繁殖等全部生命活动。"},{"ep":"bx1-01","n":"BX1-01","p":5,"a":"p5","id":"li2","src":"assets/audio/BX1-01/li2.mp3","sec":7.92,"t":"多细胞生物依赖各种分化的细胞密切合作，比如缩手反射需要多种细胞协调配合。"},{"ep":"bx1-01","n":"BX1-01","p":5,"a":"p5","id":"li3","src":"assets/audio/BX1-01/li3.mp3","sec":5.592,"t":"病毒没有细胞结构，但它必须寄生在活细胞中才能增殖。"},{"ep":"bx1-01","n":"BX1-01","p":5,"a":"p5","id":"li4","src":"assets/audio/BX1-01/li4.mp3","sec":10.032,"t":"易错：病毒不能用普通培养基直接培养，要用活细胞培养；病毒是生物，但不属于生命系统的任何层次。"},{"ep":"bx1-01","n":"BX1-01","p":6,"a":"p6","id":"lv1","src":"assets/audio/BX1-01/lv1.mp3","sec":10.776,"t":"考点六，生命系统的结构层次：细胞、组织、器官、系统、个体、种群、群落、生态系统、生物圈。"},{"ep":"bx1-01","n":"BX1-01","p":6,"a":"p6","id":"lv2","src":"assets/audio/BX1-01/lv2.mp3","sec":6.84,"t":"细胞是基本的生命系统，是最基本的层次；生物圈是最大的生命系统。"},{"ep":"bx1-01","n":"BX1-01","p":6,"a":"p6","id":"lv3","src":"assets/audio/BX1-01/lv3.mp3","sec":7.608,"t":"植物没有“系统”这一层次；单细胞生物的一个细胞，既是细胞层次，又是个体层次。"},{"ep":"bx1-01","n":"BX1-01","p":6,"a":"p6","id":"lv4","src":"assets/audio/BX1-01/lv4.mp3","sec":8.544,"t":"一定区域内同种生物的所有个体是种群；所有生物是群落；再加上无机环境就是生态系统。"},{"ep":"bx1-01","n":"BX1-01","p":6,"a":"p6","id":"lv5","src":"assets/audio/BX1-01/lv5.mp3","sec":11.64,"t":"考法：判断实例属于哪个层次。解题方法：抓关键词——同种是种群，所有生物是群落；“池塘里所有的鱼”两者都不是。"},{"ep":"bx1-01","n":"BX1-01","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-01/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-01","n":"BX1-01","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-01/rv2.mp3","sec":9.264,"t":"判断一？错，细胞学说主要由施莱登和施旺建立。判断二？错，只揭示了统一性。"},{"ep":"bx1-01","n":"BX1-01","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-01/rv3.mp3","sec":6.744,"t":"判断三？对。判断四？错，他们用的是不完全归纳法。"},{"ep":"bx1-01","n":"BX1-01","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-01/rv4.mp3","sec":8.88,"t":"判断五？错，病毒必须寄生在活细胞中。判断六？对，植物没有系统层次。"},{"ep":"bx1-01","n":"BX1-01","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-01/rv5.mp3","sec":7.968,"t":"六个考点串成一条线：记准人名和年代，分清统一性与多样性。我们下期再见！"},{"ep":"bx1-02","n":"BX1-02","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-02/in1.mp3","sec":7.68,"t":"同学们好！这节课梳理人教版必修一第一章第二节——细胞的多样性和统一性。"},{"ep":"bx1-02","n":"BX1-02","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-02/in2.mp3","sec":7.44,"t":"高考常考高倍显微镜的使用和相关计算，以及原核细胞与真核细胞的比较。"},{"ep":"bx1-02","n":"BX1-02","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-02/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-02","n":"BX1-02","p":1,"a":"p1","id":"sc1","src":"assets/audio/BX1-02/sc1.mp3","sec":7.392,"t":"考点一，高倍显微镜的使用。第一步，先在低倍镜下找到要观察的物像。"},{"ep":"bx1-02","n":"BX1-02","p":1,"a":"p1","id":"sc2","src":"assets/audio/BX1-02/sc2.mp3","sec":6.912,"t":"第二步，把物像移到视野中央；第三步，转动转换器，换上高倍物镜。"},{"ep":"bx1-02","n":"BX1-02","p":1,"a":"p1","id":"sc3","src":"assets/audio/BX1-02/sc3.mp3","sec":7.992,"t":"第四步，视野变暗时调大光圈或换凹面镜，再转动细准焦螺旋，直到物像清晰。"},{"ep":"bx1-02","n":"BX1-02","p":1,"a":"p1","id":"sc4","src":"assets/audio/BX1-02/sc4.mp3","sec":7.248,"t":"易错：换高倍镜前不用升高镜筒，换高倍镜后不能再动粗准焦螺旋。"},{"ep":"bx1-02","n":"BX1-02","p":2,"a":"p2","id":"im1","src":"assets/audio/BX1-02/im1.mp3","sec":8.88,"t":"考点二，显微镜成像的特点。显微镜成的是放大的倒像，相当于把图像旋转180度。"},{"ep":"bx1-02","n":"BX1-02","p":2,"a":"p2","id":"im2","src":"assets/audio/BX1-02/im2.mp3","sec":8.736,"t":"所以物像在视野的左下方，实际物体在右上方；要把物像移到中央，装片要向左下方移动。"},{"ep":"bx1-02","n":"BX1-02","p":2,"a":"p2","id":"im3","src":"assets/audio/BX1-02/im3.mp3","sec":7.704,"t":"放大倍数等于目镜倍数乘物镜倍数，指的是物体长度或宽度的放大，不是面积。"},{"ep":"bx1-02","n":"BX1-02","p":2,"a":"p2","id":"im4","src":"assets/audio/BX1-02/im4.mp3","sec":7.728,"t":"解题方法：移装片记住“偏哪移哪”；判断实物形状时，把图像旋转180度。"},{"ep":"bx1-02","n":"BX1-02","p":3,"a":"p3","id":"ct1","src":"assets/audio/BX1-02/ct1.mp3","sec":6.936,"t":"考点三，放大倍数改变后视野中细胞数目的计算。分两种情况。"},{"ep":"bx1-02","n":"BX1-02","p":3,"a":"p3","id":"ct2","src":"assets/audio/BX1-02/ct2.mp3","sec":9.864,"t":"细胞排成一行：放大倍数变为原来的4倍，看到的细胞数变为原来的四分之一。比如8个变成2个。"},{"ep":"bx1-02","n":"BX1-02","p":3,"a":"p3","id":"ct3","src":"assets/audio/BX1-02/ct3.mp3","sec":10.8,"t":"细胞充满视野：长和宽都放大4倍，面积放大16倍，细胞数变为十六分之一。比如64个变成4个。"},{"ep":"bx1-02","n":"BX1-02","p":3,"a":"p3","id":"ct4","src":"assets/audio/BX1-02/ct4.mp3","sec":6.24,"t":"解题方法：放大n倍，一行的除以n，充满视野的除以n的平方。"},{"ep":"bx1-02","n":"BX1-02","p":4,"a":"p4","id":"pe1","src":"assets/audio/BX1-02/pe1.mp3","sec":8.664,"t":"考点四，原核细胞与真核细胞。两者最根本的区别：有无以核膜为界限的细胞核。"},{"ep":"bx1-02","n":"BX1-02","p":4,"a":"p4","id":"pe2","src":"assets/audio/BX1-02/pe2.mp3","sec":8.976,"t":"原核细胞没有成形的细胞核，DNA集中在拟核区域，是裸露的环状DNA，不形成染色体。"},{"ep":"bx1-02","n":"BX1-02","p":4,"a":"p4","id":"pe3","src":"assets/audio/BX1-02/pe3.mp3","sec":8.592,"t":"原核细胞只有核糖体一种细胞器；真核细胞有线粒体、叶绿体、内质网等多种细胞器。"},{"ep":"bx1-02","n":"BX1-02","p":4,"a":"p4","id":"pe4","src":"assets/audio/BX1-02/pe4.mp3","sec":9.288,"t":"易错：有无细胞壁不是区别——细菌也有细胞壁，但成分是肽聚糖，植物细胞壁是纤维素和果胶。"},{"ep":"bx1-02","n":"BX1-02","p":5,"a":"p5","id":"pk1","src":"assets/audio/BX1-02/pk1.mp3","sec":9.48,"t":"考点五，常见的原核生物。第一类是细菌：球菌、杆菌、螺旋菌，比如大肠杆菌、乳酸菌。"},{"ep":"bx1-02","n":"BX1-02","p":5,"a":"p5","id":"pk2","src":"assets/audio/BX1-02/pk2.mp3","sec":7.056,"t":"第二类是蓝细菌：色球蓝细菌、颤蓝细菌、念珠蓝细菌，还有发菜。"},{"ep":"bx1-02","n":"BX1-02","p":5,"a":"p5","id":"pk3","src":"assets/audio/BX1-02/pk3.mp3","sec":7.464,"t":"蓝细菌没有叶绿体，但含有藻蓝素和叶绿素，能进行光合作用，是自养生物。"},{"ep":"bx1-02","n":"BX1-02","p":5,"a":"p5","id":"pk4","src":"assets/audio/BX1-02/pk4.mp3","sec":7.152,"t":"还有支原体，它没有细胞壁，课本说它可能是最小、最简单的单细胞生物。"},{"ep":"bx1-02","n":"BX1-02","p":5,"a":"p5","id":"pk5","src":"assets/audio/BX1-02/pk5.mp3","sec":10.224,"t":"易错：能光合作用的不一定有叶绿体，蓝细菌就是例子；水体富营养化时的“水华”，就有蓝细菌大量繁殖。"},{"ep":"bx1-02","n":"BX1-02","p":6,"a":"p6","id":"un1","src":"assets/audio/BX1-02/un1.mp3","sec":6.816,"t":"考点六，原核细胞与真核细胞的统一性。它们都有细胞膜和细胞质。"},{"ep":"bx1-02","n":"BX1-02","p":6,"a":"p6","id":"un2","src":"assets/audio/BX1-02/un2.mp3","sec":4.464,"t":"都有核糖体这种细胞器，用来合成蛋白质。"},{"ep":"bx1-02","n":"BX1-02","p":6,"a":"p6","id":"un3","src":"assets/audio/BX1-02/un3.mp3","sec":7.992,"t":"遗传物质都是DNA。这体现了细胞的统一性，也说明生物之间存在亲缘关系。"},{"ep":"bx1-02","n":"BX1-02","p":6,"a":"p6","id":"un4","src":"assets/audio/BX1-02/un4.mp3","sec":10.296,"t":"考法：问原核细胞和真核细胞的共同点。解题方法：记住四个“都有”——膜、质、核糖体、DNA。"},{"ep":"bx1-02","n":"BX1-02","p":7,"a":"p7","id":"cf1","src":"assets/audio/BX1-02/cf1.mp3","sec":10.176,"t":"考点七，易混生物辨析。名字带“菌”的不一定是细菌：酵母菌、霉菌和蘑菇都是真菌，属于真核生物。"},{"ep":"bx1-02","n":"BX1-02","p":7,"a":"p7","id":"cf2","src":"assets/audio/BX1-02/cf2.mp3","sec":7.896,"t":"名字里带杆、球、弧、螺旋的菌，以及乳酸菌，才是细菌，属于原核生物。"},{"ep":"bx1-02","n":"BX1-02","p":7,"a":"p7","id":"cf3","src":"assets/audio/BX1-02/cf3.mp3","sec":7.608,"t":"衣藻、水绵、黑藻这些绿藻和植物是真核生物，而蓝细菌是原核生物。"},{"ep":"bx1-02","n":"BX1-02","p":7,"a":"p7","id":"cf4","src":"assets/audio/BX1-02/cf4.mp3","sec":5.4,"t":"病毒没有细胞结构，既不是原核生物，也不是真核生物。"},{"ep":"bx1-02","n":"BX1-02","p":7,"a":"p7","id":"cf5","src":"assets/audio/BX1-02/cf5.mp3","sec":8.904,"t":"解题方法：先排除病毒，再看有没有成形的细胞核；记住常见的几种真菌和蓝细菌就够用了。"},{"ep":"bx1-02","n":"BX1-02","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-02/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-02","n":"BX1-02","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-02/rv2.mp3","sec":9.552,"t":"判断一？错，应调光圈或反光镜，只能用细准焦螺旋。判断二？对，偏哪移哪。"},{"ep":"bx1-02","n":"BX1-02","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-02/rv3.mp3","sec":10.392,"t":"判断三？错，根本区别是有无以核膜为界限的细胞核。判断四？错，蓝细菌能光合作用。"},{"ep":"bx1-02","n":"BX1-02","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-02/rv4.mp3","sec":6.504,"t":"判断五？对。判断六？错，酵母菌是真核生物。"},{"ep":"bx1-02","n":"BX1-02","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-02/rv5.mp3","sec":6.576,"t":"七个考点串成一条线：先看有没有成形的细胞核。我们下期再见！"},{"ep":"bx1-03","n":"BX1-03","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-03/in1.mp3","sec":7.8,"t":"同学们好！这节课梳理人教版必修一第二章第一节——细胞中的元素和化合物。"},{"ep":"bx1-03","n":"BX1-03","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-03/in2.mp3","sec":7.08,"t":"高考常考元素的种类和含量，以及还原糖、脂肪和蛋白质的检测实验。"},{"ep":"bx1-03","n":"BX1-03","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-03/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-03","n":"BX1-03","p":1,"a":"p1","id":"un1","src":"assets/audio/BX1-03/un1.mp3","sec":9.744,"t":"考点一，生物界与非生物界的统一性和差异性。组成细胞的化学元素，在无机自然界中都能找到。"},{"ep":"bx1-03","n":"BX1-03","p":1,"a":"p1","id":"un2","src":"assets/audio/BX1-03/un2.mp3","sec":6.456,"t":"没有一种元素是细胞所特有的，这体现了生物界与非生物界的统一性。"},{"ep":"bx1-03","n":"BX1-03","p":1,"a":"p1","id":"un3","src":"assets/audio/BX1-03/un3.mp3","sec":7.032,"t":"但细胞中各种元素的相对含量与无机自然界大不相同，这体现了差异性。"},{"ep":"bx1-03","n":"BX1-03","p":1,"a":"p1","id":"un4","src":"assets/audio/BX1-03/un4.mp3","sec":5.784,"t":"解题方法：看元素种类说统一性，看元素含量说差异性。"},{"ep":"bx1-03","n":"BX1-03","p":2,"a":"p2","id":"ma1","src":"assets/audio/BX1-03/ma1.mp3","sec":9.504,"t":"考点二，大量元素和微量元素。大量元素有C、H、O、N、P、S、K、Ca、Mg。"},{"ep":"bx1-03","n":"BX1-03","p":2,"a":"p2","id":"ma2","src":"assets/audio/BX1-03/ma2.mp3","sec":7.248,"t":"微量元素有Fe、Mn、Zn、Cu、B、Mo，含量很少，但同样必不可少。"},{"ep":"bx1-03","n":"BX1-03","p":2,"a":"p2","id":"ma3","src":"assets/audio/BX1-03/ma3.mp3","sec":7.224,"t":"微量元素可以用口诀记：“铁猛碰新木桶”——铁、锰、硼、锌、钼、铜。"},{"ep":"bx1-03","n":"BX1-03","p":2,"a":"p2","id":"ma4","src":"assets/audio/BX1-03/ma4.mp3","sec":9.816,"t":"易错：大量、微量是按含量分的，不是按作用大小；Mg、Ca是大量元素，常被混进微量元素里。"},{"ep":"bx1-03","n":"BX1-03","p":3,"a":"p3","id":"cb1","src":"assets/audio/BX1-03/cb1.mp3","sec":9.024,"t":"考点三，碳是核心元素。生物大分子以碳链为基本骨架，所以说碳是生命的核心元素。"},{"ep":"bx1-03","n":"BX1-03","p":3,"a":"p3","id":"cb2","src":"assets/audio/BX1-03/cb2.mp3","sec":5.568,"t":"细胞鲜重中，含量最多的元素是O，因为细胞里水最多。"},{"ep":"bx1-03","n":"BX1-03","p":3,"a":"p3","id":"cb3","src":"assets/audio/BX1-03/cb3.mp3","sec":8.208,"t":"人体细胞干重中，含量最多的元素是C；不过课本表里玉米细胞干重中O略多于C。"},{"ep":"bx1-03","n":"BX1-03","p":3,"a":"p3","id":"cb4","src":"assets/audio/BX1-03/cb4.mp3","sec":8.136,"t":"鲜重中从多到少是O、C、H、N；人体细胞干重中是C、O、N、H。"},{"ep":"bx1-03","n":"BX1-03","p":3,"a":"p3","id":"cb5","src":"assets/audio/BX1-03/cb5.mp3","sec":10.128,"t":"考法：给柱形图判断是鲜重还是干重。解题方法：O远多于C是鲜重；C排第一，一般是干重。"},{"ep":"bx1-03","n":"BX1-03","p":4,"a":"p4","id":"cp1","src":"assets/audio/BX1-03/cp1.mp3","sec":10.896,"t":"考点四，细胞中的化合物。分为无机化合物——水和无机盐，和有机化合物——糖类、脂质、蛋白质和核酸。"},{"ep":"bx1-03","n":"BX1-03","p":4,"a":"p4","id":"cp2","src":"assets/audio/BX1-03/cp2.mp3","sec":3.504,"t":"细胞中含量最多的化合物是水。"},{"ep":"bx1-03","n":"BX1-03","p":4,"a":"p4","id":"cp3","src":"assets/audio/BX1-03/cp3.mp3","sec":7.392,"t":"含量最多的有机化合物是蛋白质；占细胞干重最多的化合物，也是蛋白质。"},{"ep":"bx1-03","n":"BX1-03","p":4,"a":"p4","id":"cp4","src":"assets/audio/BX1-03/cp4.mp3","sec":8.328,"t":"易错：问“化合物”答水，问“有机物”答蛋白质；问“元素”，还要先分清鲜重还是干重。"},{"ep":"bx1-03","n":"BX1-03","p":5,"a":"p5","id":"su1","src":"assets/audio/BX1-03/su1.mp3","sec":10.176,"t":"考点五，检测还原糖。葡萄糖、果糖、麦芽糖等还原糖，与斐林试剂发生作用，生成砖红色沉淀。"},{"ep":"bx1-03","n":"BX1-03","p":5,"a":"p5","id":"su2","src":"assets/audio/BX1-03/su2.mp3","sec":7.608,"t":"斐林试剂由甲液NaOH和乙液CuSO4等量混匀而成，要现配现用。"},{"ep":"bx1-03","n":"BX1-03","p":5,"a":"p5","id":"su3","src":"assets/audio/BX1-03/su3.mp3","sec":6.984,"t":"加入后要50～65℃水浴加热约2分钟，才会出现砖红色沉淀。"},{"ep":"bx1-03","n":"BX1-03","p":5,"a":"p5","id":"su4","src":"assets/audio/BX1-03/su4.mp3","sec":10.8,"t":"材料要选含还原糖多、颜色浅的，如苹果、梨；甘蔗、甜菜主要含蔗糖，西瓜汁颜色太深，都不合适。"},{"ep":"bx1-03","n":"BX1-03","p":5,"a":"p5","id":"su5","src":"assets/audio/BX1-03/su5.mp3","sec":6.864,"t":"易错：蔗糖和淀粉不是还原糖；不水浴加热就看不到砖红色沉淀。"},{"ep":"bx1-03","n":"BX1-03","p":6,"a":"p6","id":"ft1","src":"assets/audio/BX1-03/ft1.mp3","sec":6.048,"t":"考点六，检测脂肪。脂肪被苏丹Ⅲ染液染成橘黄色。"},{"ep":"bx1-03","n":"BX1-03","p":6,"a":"p6","id":"ft2","src":"assets/audio/BX1-03/ft2.mp3","sec":6.192,"t":"材料用花生种子的子叶，切成薄片，染色后制成临时装片。"},{"ep":"bx1-03","n":"BX1-03","p":6,"a":"p6","id":"ft3","src":"assets/audio/BX1-03/ft3.mp3","sec":5.04,"t":"染色后用体积分数为50%的酒精洗去浮色。"},{"ep":"bx1-03","n":"BX1-03","p":6,"a":"p6","id":"ft4","src":"assets/audio/BX1-03/ft4.mp3","sec":5.064,"t":"在显微镜下，可以看到被染成橘黄色的脂肪颗粒。"},{"ep":"bx1-03","n":"BX1-03","p":6,"a":"p6","id":"ft5","src":"assets/audio/BX1-03/ft5.mp3","sec":9.432,"t":"易错：这里酒精的作用是洗去浮色；观察切片中的脂肪颗粒才要用显微镜，检测组织样液不用。"},{"ep":"bx1-03","n":"BX1-03","p":7,"a":"p7","id":"pr1","src":"assets/audio/BX1-03/pr1.mp3","sec":7.632,"t":"考点七，检测蛋白质。蛋白质与双缩脲试剂发生作用，产生紫色反应。"},{"ep":"bx1-03","n":"BX1-03","p":7,"a":"p7","id":"pr2","src":"assets/audio/BX1-03/pr2.mp3","sec":8.304,"t":"使用时先加A液NaOH 1 mL，摇匀；再加B液CuSO4 4滴，摇匀。"},{"ep":"bx1-03","n":"BX1-03","p":7,"a":"p7","id":"pr3","src":"assets/audio/BX1-03/pr3.mp3","sec":6.984,"t":"双缩脲试剂不需要加热，和斐林试剂的“等量混匀、水浴加热”正好不同。"},{"ep":"bx1-03","n":"BX1-03","p":7,"a":"p7","id":"pr4","src":"assets/audio/BX1-03/pr4.mp3","sec":10.08,"t":"两者CuSO4的浓度也不同：斐林试剂乙液是0.05 g/mL，双缩脲试剂B液是0.01 g/mL。"},{"ep":"bx1-03","n":"BX1-03","p":7,"a":"p7","id":"pr5","src":"assets/audio/BX1-03/pr5.mp3","sec":6.744,"t":"解题方法：斐林试剂“混合、加热”，双缩脲试剂“分开加、不加热”。"},{"ep":"bx1-03","n":"BX1-03","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-03/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-03","n":"BX1-03","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-03/rv2.mp3","sec":8.736,"t":"判断一？错，没有一种元素是细胞特有的。判断二？错，Mg是大量元素。"},{"ep":"bx1-03","n":"BX1-03","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-03/rv3.mp3","sec":6.192,"t":"判断三？错，鲜重中O最多。判断四？对。"},{"ep":"bx1-03","n":"BX1-03","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-03/rv4.mp3","sec":8.664,"t":"判断五？错，蔗糖不是还原糖。判断六？错，要先加A液，再加B液。"},{"ep":"bx1-03","n":"BX1-03","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-03/rv5.mp3","sec":9.096,"t":"七个考点串成一条线：元素看种类和含量，检测记准试剂、条件和颜色。我们下期再见！"},{"ep":"bx1-04","n":"BX1-04","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-04/in1.mp3","sec":7.056,"t":"同学们好！这节课梳理人教版必修一第二章第二节——细胞中的无机物。"},{"ep":"bx1-04","n":"BX1-04","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-04/in2.mp3","sec":7.224,"t":"高考常考自由水与结合水、无机盐的功能，以及验证必需元素的实验设计。"},{"ep":"bx1-04","n":"BX1-04","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-04/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-04","n":"BX1-04","p":1,"a":"p1","id":"wc1","src":"assets/audio/BX1-04/wc1.mp3","sec":10.056,"t":"考点一，水的含量特点。水是细胞中含量最多的化合物，一般占细胞鲜重的70%～90%。"},{"ep":"bx1-04","n":"BX1-04","p":1,"a":"p1","id":"wc2","src":"assets/audio/BX1-04/wc2.mp3","sec":8.376,"t":"不同生物含水量不同：一般水生生物多于陆生生物，水母的含水量可达97%。"},{"ep":"bx1-04","n":"BX1-04","p":1,"a":"p1","id":"wc3","src":"assets/audio/BX1-04/wc3.mp3","sec":7.992,"t":"同一生物的不同时期、不同器官也不同：幼儿多于成年人，代谢旺盛的器官含水量高。"},{"ep":"bx1-04","n":"BX1-04","p":1,"a":"p1","id":"wc4","src":"assets/audio/BX1-04/wc4.mp3","sec":9.312,"t":"考法：比较不同生物、不同器官含水量的高低。解题方法：一般代谢越旺盛，含水量越高。"},{"ep":"bx1-04","n":"BX1-04","p":2,"a":"p2","id":"sv1","src":"assets/audio/BX1-04/sv1.mp3","sec":9.744,"t":"考点二，水为什么是良好的溶剂。水分子是极性分子，带电荷的分子或离子都容易与水结合。"},{"ep":"bx1-04","n":"BX1-04","p":2,"a":"p2","id":"sv2","src":"assets/audio/BX1-04/sv2.mp3","sec":9.672,"t":"水分子之间会形成氢键，氢键不断断裂又不断形成，使水在常温下呈液体状态，具有流动性。"},{"ep":"bx1-04","n":"BX1-04","p":2,"a":"p2","id":"sv3","src":"assets/audio/BX1-04/sv3.mp3","sec":7.752,"t":"氢键还使水具有较高的比热容，水的温度不容易改变，有利于维持生命系统的稳定。"},{"ep":"bx1-04","n":"BX1-04","p":2,"a":"p2","id":"sv4","src":"assets/audio/BX1-04/sv4.mp3","sec":8.856,"t":"易错：水是良好溶剂，靠的是极性；水的比热容高、能流动，靠的是氢键，不要张冠李戴。"},{"ep":"bx1-04","n":"BX1-04","p":3,"a":"p3","id":"fw1","src":"assets/audio/BX1-04/fw1.mp3","sec":9.552,"t":"考点三，自由水与结合水。细胞中绝大部分的水以游离的形式存在，可以自由流动，叫作自由水。"},{"ep":"bx1-04","n":"BX1-04","p":3,"a":"p3","id":"fw2","src":"assets/audio/BX1-04/fw2.mp3","sec":8.352,"t":"自由水是细胞内良好的溶剂，参与许多生物化学反应，还能运送营养物质和代谢废物。"},{"ep":"bx1-04","n":"BX1-04","p":3,"a":"p3","id":"fw3","src":"assets/audio/BX1-04/fw3.mp3","sec":7.848,"t":"一部分水与细胞内的其他物质相结合，叫作结合水，是细胞结构的重要组成部分。"},{"ep":"bx1-04","n":"BX1-04","p":3,"a":"p3","id":"fw4","src":"assets/audio/BX1-04/fw4.mp3","sec":4.92,"t":"在一定条件下，自由水和结合水可以相互转化。"},{"ep":"bx1-04","n":"BX1-04","p":3,"a":"p3","id":"fw5","src":"assets/audio/BX1-04/fw5.mp3","sec":10.128,"t":"易错：只有自由水能作溶剂、参与反应和运输；结合水失去了流动性和溶解性，是细胞结构的组成成分。"},{"ep":"bx1-04","n":"BX1-04","p":4,"a":"p4","id":"rt1","src":"assets/audio/BX1-04/rt1.mp3","sec":6.96,"t":"考点四，自由水与结合水的比值。比值越高，细胞代谢越旺盛。"},{"ep":"bx1-04","n":"BX1-04","p":4,"a":"p4","id":"rt2","src":"assets/audio/BX1-04/rt2.mp3","sec":5.64,"t":"比值越低，代谢越慢，但抗寒、抗旱等抗逆性越强。"},{"ep":"bx1-04","n":"BX1-04","p":4,"a":"p4","id":"rt3","src":"assets/audio/BX1-04/rt3.mp3","sec":7.08,"t":"比如冬季来临，冬小麦细胞中结合水的比例逐渐升高，抗寒能力增强。"},{"ep":"bx1-04","n":"BX1-04","p":4,"a":"p4","id":"rt4","src":"assets/audio/BX1-04/rt4.mp3","sec":9.912,"t":"种子晒干时失去的主要是自由水，代谢减弱，便于储存；种子烘烤时失去结合水，就失去活性了。"},{"ep":"bx1-04","n":"BX1-04","p":4,"a":"p4","id":"rt5","src":"assets/audio/BX1-04/rt5.mp3","sec":10.824,"t":"考法：结合种子萌发、储存和越冬考比值的变化。解题方法：代谢旺盛看自由水，抗逆性强看结合水。"},{"ep":"bx1-04","n":"BX1-04","p":5,"a":"p5","id":"sa1","src":"assets/audio/BX1-04/sa1.mp3","sec":7.776,"t":"考点五，无机盐的存在形式和功能。细胞中大多数无机盐以离子的形式存在。"},{"ep":"bx1-04","n":"BX1-04","p":5,"a":"p5","id":"sa2","src":"assets/audio/BX1-04/sa2.mp3","sec":9.096,"t":"有些无机盐是复杂化合物的重要组成成分：Mg是叶绿素的组成成分，Fe是血红素的组成成分。"},{"ep":"bx1-04","n":"BX1-04","p":5,"a":"p5","id":"sa3","src":"assets/audio/BX1-04/sa3.mp3","sec":7.08,"t":"I是合成甲状腺激素的原料；P是磷脂、核酸、ATP等的组成元素。"},{"ep":"bx1-04","n":"BX1-04","p":5,"a":"p5","id":"sa4","src":"assets/audio/BX1-04/sa4.mp3","sec":12.312,"t":"考法：缺Mg叶片发黄，缺Fe会贫血，缺I易患地方性甲状腺肿。解题方法：先说它组成了哪种化合物，再推缺乏的后果。"},{"ep":"bx1-04","n":"BX1-04","p":6,"a":"p6","id":"sb1","src":"assets/audio/BX1-04/sb1.mp3","sec":9.648,"t":"考点六，无机盐对维持生命活动的作用。哺乳动物血液中Ca2+含量太低，会出现抽搐等症状。"},{"ep":"bx1-04","n":"BX1-04","p":6,"a":"p6","id":"sb2","src":"assets/audio/BX1-04/sb2.mp3","sec":8.568,"t":"人体内Na+缺乏，会引起神经、肌肉细胞的兴奋性降低，最终引发肌肉酸痛、无力等。"},{"ep":"bx1-04","n":"BX1-04","p":6,"a":"p6","id":"sb3","src":"assets/audio/BX1-04/sb3.mp3","sec":9.72,"t":"无机盐还能维持细胞的酸碱平衡和渗透压，比如生理盐水是质量分数为0.9%的NaCl溶液。"},{"ep":"bx1-04","n":"BX1-04","p":6,"a":"p6","id":"sb4","src":"assets/audio/BX1-04/sb4.mp3","sec":8.232,"t":"易错：无机盐不能为细胞提供能量；大量出汗后，要补充的是淡盐水，而不只是水。"},{"ep":"bx1-04","n":"BX1-04","p":7,"a":"p7","id":"ds1","src":"assets/audio/BX1-04/ds1.mp3","sec":10.824,"t":"考点七，验证某种无机盐是植物生长所必需的。以镁为例：完全培养液为对照组，缺镁培养液为实验组。"},{"ep":"bx1-04","n":"BX1-04","p":7,"a":"p7","id":"ds2","src":"assets/audio/BX1-04/ds2.mp3","sec":6.984,"t":"把长势相同的幼苗分别放入两组中培养，结果缺镁组的幼苗叶片发黄。"},{"ep":"bx1-04","n":"BX1-04","p":7,"a":"p7","id":"ds3","src":"assets/audio/BX1-04/ds3.mp3","sec":8.424,"t":"还要做二次对照：向缺镁组中补充镁，症状消失、恢复正常，才能说明镁是必需的。"},{"ep":"bx1-04","n":"BX1-04","p":7,"a":"p7","id":"ds4","src":"assets/audio/BX1-04/ds4.mp3","sec":10.728,"t":"解题方法：自变量是有无这种无机盐；对照组用完全培养液，不能用土壤；再用“缺素—补素”前后对照增强说服力。"},{"ep":"bx1-04","n":"BX1-04","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-04/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-04","n":"BX1-04","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-04/rv2.mp3","sec":10.56,"t":"判断一？错，自由水才是良好溶剂。判断二？错，比值越高，代谢越旺盛，抗逆性越弱。"},{"ep":"bx1-04","n":"BX1-04","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-04/rv3.mp3","sec":4.656,"t":"判断三？对。判断四？对。"},{"ep":"bx1-04","n":"BX1-04","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-04/rv4.mp3","sec":8.856,"t":"判断五？错，无机盐不能提供能量。判断六？错，对照组要用完全培养液。"},{"ep":"bx1-04","n":"BX1-04","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-04/rv5.mp3","sec":9.408,"t":"七个考点串成一条线：代谢看自由水，抗逆看结合水，无机盐看组成和功能。我们下期再见！"},{"ep":"bx1-05","n":"BX1-05","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-05/in1.mp3","sec":7.728,"t":"同学们好！这节课梳理人教版必修一第二章第三节——细胞中的糖类和脂质。"},{"ep":"bx1-05","n":"BX1-05","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-05/in2.mp3","sec":5.904,"t":"高考常考糖类的种类、分布和功能，以及脂肪与糖类的比较。"},{"ep":"bx1-05","n":"BX1-05","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-05/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-05","n":"BX1-05","p":1,"a":"p1","id":"sg1","src":"assets/audio/BX1-05/sg1.mp3","sec":7.752,"t":"考点一，糖类的元素组成与功能。糖类一般由C、H、O三种元素构成。"},{"ep":"bx1-05","n":"BX1-05","p":1,"a":"p1","id":"sg2","src":"assets/audio/BX1-05/sg2.mp3","sec":9.792,"t":"糖类是细胞的重要能源物质，其中葡萄糖是细胞生命活动所需要的主要能源物质，常被称为“生命的燃料”。"},{"ep":"bx1-05","n":"BX1-05","p":1,"a":"p1","id":"sg3","src":"assets/audio/BX1-05/sg3.mp3","sec":6.216,"t":"糖类还能构成细胞结构，比如纤维素是植物细胞壁的主要成分。"},{"ep":"bx1-05","n":"BX1-05","p":1,"a":"p1","id":"sg4","src":"assets/audio/BX1-05/sg4.mp3","sec":9.552,"t":"易错：糖类不都是能源物质——纤维素、核糖、脱氧核糖都不为细胞供能；几丁质还含有N。"},{"ep":"bx1-05","n":"BX1-05","p":2,"a":"p2","id":"mo1","src":"assets/audio/BX1-05/mo1.mp3","sec":6.408,"t":"考点二，单糖。单糖是不能水解的糖，可以被细胞直接吸收。"},{"ep":"bx1-05","n":"BX1-05","p":2,"a":"p2","id":"mo2","src":"assets/audio/BX1-05/mo2.mp3","sec":6.504,"t":"六碳糖有葡萄糖、果糖、半乳糖；五碳糖有核糖和脱氧核糖。"},{"ep":"bx1-05","n":"BX1-05","p":2,"a":"p2","id":"mo3","src":"assets/audio/BX1-05/mo3.mp3","sec":8.904,"t":"核糖是RNA的组成成分，脱氧核糖是DNA的组成成分；葡萄糖是动植物细胞共有的单糖。"},{"ep":"bx1-05","n":"BX1-05","p":2,"a":"p2","id":"mo4","src":"assets/audio/BX1-05/mo4.mp3","sec":8.64,"t":"考法：判断动植物细胞共有的糖。解题方法：共有的是葡萄糖、核糖、脱氧核糖。"},{"ep":"bx1-05","n":"BX1-05","p":3,"a":"p3","id":"di1","src":"assets/audio/BX1-05/di1.mp3","sec":8.64,"t":"考点三，二糖。二糖由两分子单糖脱水缩合而成，必须水解成单糖才能被吸收。"},{"ep":"bx1-05","n":"BX1-05","p":3,"a":"p3","id":"di2","src":"assets/audio/BX1-05/di2.mp3","sec":8.904,"t":"植物细胞中的二糖：蔗糖水解成一分子葡萄糖和一分子果糖；麦芽糖水解成两分子葡萄糖。"},{"ep":"bx1-05","n":"BX1-05","p":3,"a":"p3","id":"di3","src":"assets/audio/BX1-05/di3.mp3","sec":9.12,"t":"动物细胞中的二糖：乳糖，水解成一分子葡萄糖和一分子半乳糖，人和动物乳汁中含量丰富。"},{"ep":"bx1-05","n":"BX1-05","p":3,"a":"p3","id":"di4","src":"assets/audio/BX1-05/di4.mp3","sec":8.4,"t":"易错：蔗糖不是还原糖，麦芽糖和乳糖是还原糖；二糖的水解产物都含有葡萄糖。"},{"ep":"bx1-05","n":"BX1-05","p":4,"a":"p4","id":"po1","src":"assets/audio/BX1-05/po1.mp3","sec":10.848,"t":"考点四，多糖。淀粉是植物细胞中的储能物质，糖原是人和动物细胞中的储能物质，主要分布在肝脏和肌肉中。"},{"ep":"bx1-05","n":"BX1-05","p":4,"a":"p4","id":"po2","src":"assets/audio/BX1-05/po2.mp3","sec":10.32,"t":"纤维素是植物细胞壁的主要成分，很难被人体消化；一些科学家把纤维素等其他糖类称为人类的“第七类营养素”。"},{"ep":"bx1-05","n":"BX1-05","p":4,"a":"p4","id":"po3","src":"assets/audio/BX1-05/po3.mp3","sec":8.304,"t":"淀粉、糖原、纤维素的基本单位都是葡萄糖，但葡萄糖的连接方式不同，所以性质不同。"},{"ep":"bx1-05","n":"BX1-05","p":4,"a":"p4","id":"po4","src":"assets/audio/BX1-05/po4.mp3","sec":8.712,"t":"几丁质广泛存在于甲壳类动物和昆虫的外骨骼中，能与重金属离子结合，可用于废水处理。"},{"ep":"bx1-05","n":"BX1-05","p":4,"a":"p4","id":"po5","src":"assets/audio/BX1-05/po5.mp3","sec":8.856,"t":"易错：肝糖原能分解补充血糖，肌糖原不能直接分解成葡萄糖；纤维素不是储能物质。"},{"ep":"bx1-05","n":"BX1-05","p":5,"a":"p5","id":"lp1","src":"assets/audio/BX1-05/lp1.mp3","sec":11.376,"t":"考点五，脂质的种类与功能。脂质主要含C、H、O，有的还含有N和P；通常不溶于水，而溶于脂溶性有机溶剂。"},{"ep":"bx1-05","n":"BX1-05","p":5,"a":"p5","id":"lp2","src":"assets/audio/BX1-05/lp2.mp3","sec":6.168,"t":"脂肪是细胞内良好的储能物质，还有保温、缓冲和减压的作用。"},{"ep":"bx1-05","n":"BX1-05","p":5,"a":"p5","id":"lp3","src":"assets/audio/BX1-05/lp3.mp3","sec":4.896,"t":"磷脂是构成细胞膜和多种细胞器膜的重要成分。"},{"ep":"bx1-05","n":"BX1-05","p":5,"a":"p5","id":"lp4","src":"assets/audio/BX1-05/lp4.mp3","sec":11.856,"t":"固醇包括胆固醇、性激素和维生素D：胆固醇构成动物细胞膜，还参与血液中脂质的运输；维生素D促进钙和磷的吸收。"},{"ep":"bx1-05","n":"BX1-05","p":5,"a":"p5","id":"lp5","src":"assets/audio/BX1-05/lp5.mp3","sec":8.208,"t":"易错：性激素是固醇，不是蛋白质；所有细胞都含磷脂，因为所有细胞都有细胞膜。"},{"ep":"bx1-05","n":"BX1-05","p":6,"a":"p6","id":"fa1","src":"assets/audio/BX1-05/fa1.mp3","sec":9.456,"t":"考点六，脂肪的组成。脂肪是由三分子脂肪酸与一分子甘油发生反应形成的酯，叫三酰甘油。"},{"ep":"bx1-05","n":"BX1-05","p":6,"a":"p6","id":"fa2","src":"assets/audio/BX1-05/fa2.mp3","sec":6.216,"t":"植物脂肪大多含不饱和脂肪酸，熔点较低，室温时呈液态。"},{"ep":"bx1-05","n":"BX1-05","p":6,"a":"p6","id":"fa3","src":"assets/audio/BX1-05/fa3.mp3","sec":6.12,"t":"大多数动物脂肪含饱和脂肪酸，熔点较高，室温时呈固态。"},{"ep":"bx1-05","n":"BX1-05","p":6,"a":"p6","id":"fa4","src":"assets/audio/BX1-05/fa4.mp3","sec":7.008,"t":"易错：脂肪只含C、H、O，不含N、P；含N、P的是磷脂。"},{"ep":"bx1-05","n":"BX1-05","p":7,"a":"p7","id":"cm1","src":"assets/audio/BX1-05/cm1.mp3","sec":9.648,"t":"考点七，糖类与脂肪的比较。两者都由C、H、O组成，但脂肪中H的含量高，O的含量低。"},{"ep":"bx1-05","n":"BX1-05","p":7,"a":"p7","id":"cm2","src":"assets/audio/BX1-05/cm2.mp3","sec":7.752,"t":"所以等质量的脂肪氧化分解时，消耗的氧气多，释放的能量多，产生的水也多。"},{"ep":"bx1-05","n":"BX1-05","p":7,"a":"p7","id":"cm3","src":"assets/audio/BX1-05/cm3.mp3","sec":5.976,"t":"因此，脂肪是良好的储能物质；而糖类是主要的能源物质。"},{"ep":"bx1-05","n":"BX1-05","p":7,"a":"p7","id":"cm4","src":"assets/audio/BX1-05/cm4.mp3","sec":10.344,"t":"考法：油料种子萌发时耗氧多，或比较呼吸熵。解题方法：抓住“脂肪含H多、含O少”这一条往下推。"},{"ep":"bx1-05","n":"BX1-05","p":8,"a":"p8","id":"cv1","src":"assets/audio/BX1-05/cv1.mp3","sec":10.344,"t":"考点八，糖类和脂质的相互转化。血液中的葡萄糖除供细胞利用外，多余的部分可以合成糖原储存起来。"},{"ep":"bx1-05","n":"BX1-05","p":8,"a":"p8","id":"cv2","src":"assets/audio/BX1-05/cv2.mp3","sec":9.312,"t":"如果葡萄糖还有富余，就可以转变成脂肪和某些氨基酸；糖类供应充足时，可以大量转化为脂肪。"},{"ep":"bx1-05","n":"BX1-05","p":8,"a":"p8","id":"cv3","src":"assets/audio/BX1-05/cv3.mp3","sec":7.584,"t":"而脂肪一般只在糖类供能不足时，才会分解供能，而且不能大量转化为糖类。"},{"ep":"bx1-05","n":"BX1-05","p":8,"a":"p8","id":"cv4","src":"assets/audio/BX1-05/cv4.mp3","sec":10.68,"t":"考法：解释“吃糖多也会发胖”。解题方法：记住转化是不对称的——糖能大量变脂肪，脂肪不能大量变糖。"},{"ep":"bx1-05","n":"BX1-05","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-05/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-05","n":"BX1-05","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-05/rv2.mp3","sec":9.456,"t":"判断一？错，纤维素、核糖等不供能。判断二？错，蔗糖水解为葡萄糖和果糖。"},{"ep":"bx1-05","n":"BX1-05","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-05/rv3.mp3","sec":4.656,"t":"判断三？对。判断四？对。"},{"ep":"bx1-05","n":"BX1-05","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-05/rv4.mp3","sec":9.096,"t":"判断五？错，脂肪释放能量更多。判断六？错，脂肪不能大量转化为糖类。"},{"ep":"bx1-05","n":"BX1-05","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-05/rv5.mp3","sec":6.528,"t":"八个考点串成一条线：分清种类、分布和功能。我们下期再见！"},{"ep":"bx1-06","n":"BX1-06","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-06/in1.mp3","sec":8.544,"t":"同学们好！这节课梳理人教版必修一第二章第四节——蛋白质是生命活动的主要承担者。"},{"ep":"bx1-06","n":"BX1-06","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-06/in2.mp3","sec":7.104,"t":"高考常考氨基酸的结构通式、脱水缩合的相关计算，以及蛋白质的变性。"},{"ep":"bx1-06","n":"BX1-06","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-06/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-06","n":"BX1-06","p":1,"a":"p1","id":"fn1","src":"assets/audio/BX1-06/fn1.mp3","sec":9.048,"t":"考点一，蛋白质的功能。一切生命活动都离不开蛋白质，蛋白质是生命活动的主要承担者。"},{"ep":"bx1-06","n":"BX1-06","p":1,"a":"p1","id":"fn2","src":"assets/audio/BX1-06/fn2.mp3","sec":8.688,"t":"结构蛋白：构成细胞和生物体，如羽毛、肌肉、头发；催化：绝大多数酶是蛋白质。"},{"ep":"bx1-06","n":"BX1-06","p":1,"a":"p1","id":"fn3","src":"assets/audio/BX1-06/fn3.mp3","sec":7.128,"t":"运输：血红蛋白运输氧气；信息传递和调节：如胰岛素调节血糖。"},{"ep":"bx1-06","n":"BX1-06","p":1,"a":"p1","id":"fn4","src":"assets/audio/BX1-06/fn4.mp3","sec":5.832,"t":"免疫：抗体可以帮助人体抵御病菌和病毒等抗原的侵害。"},{"ep":"bx1-06","n":"BX1-06","p":1,"a":"p1","id":"fn5","src":"assets/audio/BX1-06/fn5.mp3","sec":7.896,"t":"易错：激素不都是蛋白质，性激素是固醇；酶也不都是蛋白质，少数是RNA。"},{"ep":"bx1-06","n":"BX1-06","p":2,"a":"p2","id":"aa1","src":"assets/audio/BX1-06/aa1.mp3","sec":7.296,"t":"考点二，氨基酸的结构。每种氨基酸分子至少都含有一个氨基和一个羧基。"},{"ep":"bx1-06","n":"BX1-06","p":2,"a":"p2","id":"aa2","src":"assets/audio/BX1-06/aa2.mp3","sec":10.056,"t":"并且都有一个氨基和一个羧基连接在同一个碳原子上，这个碳原子还连着一个氢原子和一个侧链基团，叫R基。"},{"ep":"bx1-06","n":"BX1-06","p":2,"a":"p2","id":"aa3","src":"assets/audio/BX1-06/aa3.mp3","sec":4.2,"t":"各种氨基酸之间的区别，在于R基的不同。"},{"ep":"bx1-06","n":"BX1-06","p":2,"a":"p2","id":"aa4","src":"assets/audio/BX1-06/aa4.mp3","sec":8.4,"t":"解题方法：判断是不是组成蛋白质的氨基酸，看同一个碳上，是否既有氨基又有羧基。"},{"ep":"bx1-06","n":"BX1-06","p":3,"a":"p3","id":"kd1","src":"assets/audio/BX1-06/kd1.mp3","sec":4.872,"t":"考点三，组成人体蛋白质的氨基酸有21种。"},{"ep":"bx1-06","n":"BX1-06","p":3,"a":"p3","id":"kd2","src":"assets/audio/BX1-06/kd2.mp3","sec":7.296,"t":"其中8种是人体细胞不能合成的，必须从外界环境中获取，叫必需氨基酸。"},{"ep":"bx1-06","n":"BX1-06","p":3,"a":"p3","id":"kd3","src":"assets/audio/BX1-06/kd3.mp3","sec":4.896,"t":"另外13种人体细胞能够合成，叫非必需氨基酸。"},{"ep":"bx1-06","n":"BX1-06","p":3,"a":"p3","id":"kd4","src":"assets/audio/BX1-06/kd4.mp3","sec":12.48,"t":"必需氨基酸可以用口诀记：“甲携来一本亮色书”——甲硫氨酸、缬氨酸、赖氨酸、异亮氨酸、苯丙氨酸、亮氨酸、色氨酸、苏氨酸。"},{"ep":"bx1-06","n":"BX1-06","p":3,"a":"p3","id":"kd5","src":"assets/audio/BX1-06/kd5.mp3","sec":10.656,"t":"考法：评价食物的营养价值。解题方法：看必需氨基酸的种类和含量，比如玉米等谷类蛋白质缺少赖氨酸。"},{"ep":"bx1-06","n":"BX1-06","p":4,"a":"p4","id":"dh1","src":"assets/audio/BX1-06/dh1.mp3","sec":9.048,"t":"考点四，脱水缩合。一个氨基酸的羧基和另一个氨基酸的氨基相连接，同时脱去一分子水。"},{"ep":"bx1-06","n":"BX1-06","p":4,"a":"p4","id":"dh2","src":"assets/audio/BX1-06/dh2.mp3","sec":10.728,"t":"连接两个氨基酸的化学键叫肽键。两个氨基酸形成二肽，多个氨基酸形成多肽，多肽通常呈链状，叫肽链。"},{"ep":"bx1-06","n":"BX1-06","p":4,"a":"p4","id":"dh3","src":"assets/audio/BX1-06/dh3.mp3","sec":8.448,"t":"易错：脱去的水中，H来自氨基和羧基，O来自羧基；脱水缩合的场所是核糖体。"},{"ep":"bx1-06","n":"BX1-06","p":5,"a":"p5","id":"ca1","src":"assets/audio/BX1-06/ca1.mp3","sec":11.232,"t":"考点五，肽键数和相对分子质量的计算。n个氨基酸形成m条肽链：肽键数 = 脱去的水分子数 = n − m。"},{"ep":"bx1-06","n":"BX1-06","p":5,"a":"p5","id":"ca2","src":"assets/audio/BX1-06/ca2.mp3","sec":4.896,"t":"如果形成的是环状肽，肽键数就等于氨基酸数n。"},{"ep":"bx1-06","n":"BX1-06","p":5,"a":"p5","id":"ca3","src":"assets/audio/BX1-06/ca3.mp3","sec":8.784,"t":"蛋白质的相对分子质量 = 氨基酸数 × 平均相对分子质量 − 脱去水分子数 × 18。"},{"ep":"bx1-06","n":"BX1-06","p":5,"a":"p5","id":"ca4","src":"assets/audio/BX1-06/ca4.mp3","sec":11.496,"t":"例：100个氨基酸形成2条肽链，平均相对分子质量是128，那么蛋白质的相对分子质量是11036。"},{"ep":"bx1-06","n":"BX1-06","p":5,"a":"p5","id":"ca5","src":"assets/audio/BX1-06/ca5.mp3","sec":8.808,"t":"易错：减的是脱去的水分子数98，不是100；如果有二硫键，每形成一个还要再减去2。"},{"ep":"bx1-06","n":"BX1-06","p":6,"a":"p6","id":"cb1","src":"assets/audio/BX1-06/cb1.mp3","sec":10.08,"t":"考点六，游离的氨基、羧基和原子数的计算。每条肽链的两端，各有一个游离的氨基和一个游离的羧基。"},{"ep":"bx1-06","n":"BX1-06","p":6,"a":"p6","id":"cb2","src":"assets/audio/BX1-06/cb2.mp3","sec":9.216,"t":"所以m条肽链，至少含有m个游离的氨基和m个游离的羧基；R基中的氨基和羧基要另外加上。"},{"ep":"bx1-06","n":"BX1-06","p":6,"a":"p6","id":"cb3","src":"assets/audio/BX1-06/cb3.mp3","sec":5.976,"t":"N原子数 = 肽键数 + 肽链数 + R基中的N原子数。"},{"ep":"bx1-06","n":"BX1-06","p":6,"a":"p6","id":"cb4","src":"assets/audio/BX1-06/cb4.mp3","sec":6.408,"t":"O原子数 = 肽键数 + 2 × 肽链数 + R基中的O原子数。"},{"ep":"bx1-06","n":"BX1-06","p":6,"a":"p6","id":"cb5","src":"assets/audio/BX1-06/cb5.mp3","sec":9.432,"t":"解题方法：数“肽键 + 链端 + R基”——每个肽键含1个N、1个O，每条链的末端多1个N、2个O。"},{"ep":"bx1-06","n":"BX1-06","p":7,"a":"p7","id":"dv1","src":"assets/audio/BX1-06/dv1.mp3","sec":10.176,"t":"考点七，蛋白质结构多样性的原因。从氨基酸看：种类不同、数目成百上千、排列顺序千变万化。"},{"ep":"bx1-06","n":"BX1-06","p":7,"a":"p7","id":"dv2","src":"assets/audio/BX1-06/dv2.mp3","sec":6.984,"t":"从肽链看：肽链的盘曲、折叠方式及其形成的空间结构千差万别。"},{"ep":"bx1-06","n":"BX1-06","p":7,"a":"p7","id":"dv3","src":"assets/audio/BX1-06/dv3.mp3","sec":5.952,"t":"结构的多样性决定了功能的多样性，体现了结构与功能相适应。"},{"ep":"bx1-06","n":"BX1-06","p":7,"a":"p7","id":"dv4","src":"assets/audio/BX1-06/dv4.mp3","sec":8.616,"t":"易错：氨基酸之间脱水缩合的方式都相同，肽键的结构也都一样，它们不是多样性的原因。"},{"ep":"bx1-06","n":"BX1-06","p":8,"a":"p8","id":"dn1","src":"assets/audio/BX1-06/dn1.mp3","sec":11.4,"t":"考点八，蛋白质的变性。在高温、过酸、过碱或重金属盐等作用下，蛋白质的空间结构被破坏，失去生物活性。"},{"ep":"bx1-06","n":"BX1-06","p":8,"a":"p8","id":"dn2","src":"assets/audio/BX1-06/dn2.mp3","sec":7.992,"t":"变性时肽键没有断裂，所以变性后的蛋白质仍能与双缩脲试剂发生紫色反应。"},{"ep":"bx1-06","n":"BX1-06","p":8,"a":"p8","id":"dn3","src":"assets/audio/BX1-06/dn3.mp3","sec":9.408,"t":"吃熟鸡蛋、熟肉容易消化，是因为高温使蛋白质的空间结构变得伸展、松散，容易被蛋白酶水解。"},{"ep":"bx1-06","n":"BX1-06","p":8,"a":"p8","id":"dn4","src":"assets/audio/BX1-06/dn4.mp3","sec":8.784,"t":"易错：变性一般不可逆；而盐析是加盐使蛋白质析出，空间结构没有改变，是可逆的。"},{"ep":"bx1-06","n":"BX1-06","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-06/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-06","n":"BX1-06","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-06/rv2.mp3","sec":8.784,"t":"判断一？错，性激素是固醇。判断二？错，是至少含有一个氨基和一个羧基。"},{"ep":"bx1-06","n":"BX1-06","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-06/rv3.mp3","sec":4.656,"t":"判断三？对。判断四？对。"},{"ep":"bx1-06","n":"BX1-06","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-06/rv4.mp3","sec":9.528,"t":"判断五？错，肽键没有断裂，仍能变紫。判断六？错，脱水缩合的方式都相同。"},{"ep":"bx1-06","n":"BX1-06","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-06/rv5.mp3","sec":6.264,"t":"八个考点串成一条线：脱一个水，成一个肽键。我们下期再见！"},{"ep":"bx1-07","n":"BX1-07","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-07/in1.mp3","sec":8.016,"t":"同学们好！这节课梳理人教版必修一第二章第五节——核酸是遗传信息的携带者。"},{"ep":"bx1-07","n":"BX1-07","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-07/in2.mp3","sec":9.0,"t":"高考常考DNA与RNA的比较、不同生物所含碱基和核苷酸的种类，以及生物大分子的单体。"},{"ep":"bx1-07","n":"BX1-07","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-07/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-07","n":"BX1-07","p":1,"a":"p1","id":"kn1","src":"assets/audio/BX1-07/kn1.mp3","sec":9.84,"t":"考点一，核酸的种类和分布。核酸包括两大类：脱氧核糖核酸，DNA，和核糖核酸，RNA。"},{"ep":"bx1-07","n":"BX1-07","p":1,"a":"p1","id":"kn2","src":"assets/audio/BX1-07/kn2.mp3","sec":7.68,"t":"真核细胞的DNA主要分布在细胞核中，线粒体、叶绿体内也含有少量的DNA。"},{"ep":"bx1-07","n":"BX1-07","p":1,"a":"p1","id":"kn3","src":"assets/audio/BX1-07/kn3.mp3","sec":3.12,"t":"RNA主要分布在细胞质中。"},{"ep":"bx1-07","n":"BX1-07","p":1,"a":"p1","id":"kn4","src":"assets/audio/BX1-07/kn4.mp3","sec":7.224,"t":"易错：是“主要”分布，不是“只”分布；原核细胞没有细胞核，DNA在拟核中。"},{"ep":"bx1-07","n":"BX1-07","p":2,"a":"p2","id":"nt1","src":"assets/audio/BX1-07/nt1.mp3","sec":5.736,"t":"考点二，核苷酸的组成。核酸的基本单位是核苷酸。"},{"ep":"bx1-07","n":"BX1-07","p":2,"a":"p2","id":"nt2","src":"assets/audio/BX1-07/nt2.mp3","sec":6.744,"t":"一分子核苷酸由一分子磷酸、一分子五碳糖和一分子含氮碱基组成。"},{"ep":"bx1-07","n":"BX1-07","p":2,"a":"p2","id":"nt3","src":"assets/audio/BX1-07/nt3.mp3","sec":10.896,"t":"核苷酸连接成长链构成核酸：DNA通常由两条脱氧核苷酸链构成，RNA通常由一条核糖核苷酸链构成。"},{"ep":"bx1-07","n":"BX1-07","p":2,"a":"p2","id":"nt4","src":"assets/audio/BX1-07/nt4.mp3","sec":7.896,"t":"易错：核酸初步水解得到核苷酸，彻底水解得到磷酸、五碳糖和含氮碱基。"},{"ep":"bx1-07","n":"BX1-07","p":3,"a":"p3","id":"cm1","src":"assets/audio/BX1-07/cm1.mp3","sec":10.704,"t":"考点三，DNA与RNA的比较。基本单位：DNA是脱氧核苷酸，RNA是核糖核苷酸，各有4种。"},{"ep":"bx1-07","n":"BX1-07","p":3,"a":"p3","id":"cm2","src":"assets/audio/BX1-07/cm2.mp3","sec":4.992,"t":"五碳糖：DNA含脱氧核糖，RNA含核糖。"},{"ep":"bx1-07","n":"BX1-07","p":3,"a":"p3","id":"cm3","src":"assets/audio/BX1-07/cm3.mp3","sec":8.64,"t":"碱基：两者都有A、G、C；DNA特有T，胸腺嘧啶；RNA特有U，尿嘧啶。"},{"ep":"bx1-07","n":"BX1-07","p":3,"a":"p3","id":"cm4","src":"assets/audio/BX1-07/cm4.mp3","sec":7.056,"t":"解题方法：区分DNA和RNA，看五碳糖，或者看含T还是含U。"},{"ep":"bx1-07","n":"BX1-07","p":4,"a":"p4","id":"ct1","src":"assets/audio/BX1-07/ct1.mp3","sec":8.28,"t":"考点四，不同生物的碱基和核苷酸种类。细胞生物同时含有DNA和RNA。"},{"ep":"bx1-07","n":"BX1-07","p":4,"a":"p4","id":"ct2","src":"assets/audio/BX1-07/ct2.mp3","sec":5.712,"t":"所以细胞生物有5种碱基、8种核苷酸、2种五碳糖。"},{"ep":"bx1-07","n":"BX1-07","p":4,"a":"p4","id":"ct3","src":"assets/audio/BX1-07/ct3.mp3","sec":7.584,"t":"病毒只含有一种核酸，DNA或RNA，所以只有4种碱基、4种核苷酸。"},{"ep":"bx1-07","n":"BX1-07","p":4,"a":"p4","id":"ct4","src":"assets/audio/BX1-07/ct4.mp3","sec":10.08,"t":"易错：碱基5种、核苷酸却有8种，因为A、G、C各对应两种核苷酸，T和U只各对应一种。"},{"ep":"bx1-07","n":"BX1-07","p":5,"a":"p5","id":"gm1","src":"assets/audio/BX1-07/gm1.mp3","sec":8.232,"t":"考点五，生物的遗传物质。细胞生物，无论真核还是原核，遗传物质都是DNA。"},{"ep":"bx1-07","n":"BX1-07","p":5,"a":"p5","id":"gm2","src":"assets/audio/BX1-07/gm2.mp3","sec":10.512,"t":"病毒的遗传物质是DNA或RNA：噬菌体是DNA；HIV、烟草花叶病毒、新冠病毒是RNA。"},{"ep":"bx1-07","n":"BX1-07","p":5,"a":"p5","id":"gm3","src":"assets/audio/BX1-07/gm3.mp3","sec":7.608,"t":"易错：“细胞质中的遗传物质是RNA”是错的，细胞生物的遗传物质只有DNA。"},{"ep":"bx1-07","n":"BX1-07","p":6,"a":"p6","id":"fc1","src":"assets/audio/BX1-07/fc1.mp3","sec":11.568,"t":"考点六，核酸的功能。核酸是细胞内携带遗传信息的物质，在遗传、变异和蛋白质的生物合成中有极其重要的作用。"},{"ep":"bx1-07","n":"BX1-07","p":6,"a":"p6","id":"fc2","src":"assets/audio/BX1-07/fc2.mp3","sec":8.352,"t":"遗传信息储存在核苷酸的排列顺序中；对DNA来说，就是脱氧核苷酸的排列顺序。"},{"ep":"bx1-07","n":"BX1-07","p":6,"a":"p6","id":"fc3","src":"assets/audio/BX1-07/fc3.mp3","sec":8.952,"t":"核苷酸虽然只有4种，但数量多、排列顺序千变万化，所以DNA能储存大量的遗传信息。"},{"ep":"bx1-07","n":"BX1-07","p":6,"a":"p6","id":"fc4","src":"assets/audio/BX1-07/fc4.mp3","sec":10.032,"t":"考法：DNA指纹用于刑侦和亲子鉴定。解题方法：原理是不同个体DNA的脱氧核苷酸序列不同。"},{"ep":"bx1-07","n":"BX1-07","p":7,"a":"p7","id":"mm1","src":"assets/audio/BX1-07/mm1.mp3","sec":10.992,"t":"考点七，生物大分子以碳链为骨架。多糖、蛋白质、核酸都是生物大分子，由许多单体连接成多聚体。"},{"ep":"bx1-07","n":"BX1-07","p":7,"a":"p7","id":"mm2","src":"assets/audio/BX1-07/mm2.mp3","sec":6.504,"t":"多糖的单体是单糖，蛋白质的单体是氨基酸，核酸的单体是核苷酸。"},{"ep":"bx1-07","n":"BX1-07","p":7,"a":"p7","id":"mm3","src":"assets/audio/BX1-07/mm3.mp3","sec":8.424,"t":"每个单体都以若干个相连的碳原子构成的碳链为基本骨架，所以说“碳是生命的核心元素”。"},{"ep":"bx1-07","n":"BX1-07","p":7,"a":"p7","id":"mm4","src":"assets/audio/BX1-07/mm4.mp3","sec":8.4,"t":"易错：脂肪不是生物大分子，没有单体；淀粉、糖原、纤维素的单体都是葡萄糖。"},{"ep":"bx1-07","n":"BX1-07","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-07/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-07","n":"BX1-07","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-07/rv2.mp3","sec":8.256,"t":"判断一？错，DNA主要分布在细胞核。判断二？错，五碳糖也不同。"},{"ep":"bx1-07","n":"BX1-07","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-07/rv3.mp3","sec":7.512,"t":"判断三？对。判断四？错，细胞生物的遗传物质都是DNA。"},{"ep":"bx1-07","n":"BX1-07","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-07/rv4.mp3","sec":8.112,"t":"判断五？错，彻底水解得到磷酸、五碳糖和碱基。判断六？对。"},{"ep":"bx1-07","n":"BX1-07","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-07/rv5.mp3","sec":8.376,"t":"七个考点串成一条线：看五碳糖和碱基，分清DNA和RNA。我们下期再见！"},{"ep":"bx1-08","n":"BX1-08","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-08/in1.mp3","sec":7.608,"t":"同学们好！这节课梳理人教版必修一第三章第一节——细胞膜的结构和功能。"},{"ep":"bx1-08","n":"BX1-08","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-08/in2.mp3","sec":6.84,"t":"高考常考细胞膜的三大功能、膜结构的探索历程，以及流动镶嵌模型。"},{"ep":"bx1-08","n":"BX1-08","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-08/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-08","n":"BX1-08","p":1,"a":"p1","id":"fn1","src":"assets/audio/BX1-08/fn1.mp3","sec":9.192,"t":"考点一，细胞膜的功能。第一，将细胞与外界环境分隔开，保障细胞内部环境的相对稳定。"},{"ep":"bx1-08","n":"BX1-08","p":1,"a":"p1","id":"fn2","src":"assets/audio/BX1-08/fn2.mp3","sec":8.352,"t":"第二，控制物质进出细胞；但这种控制作用是相对的，有些病毒、病菌也能侵入细胞。"},{"ep":"bx1-08","n":"BX1-08","p":1,"a":"p1","id":"fn3","src":"assets/audio/BX1-08/fn3.mp3","sec":3.48,"t":"第三，进行细胞间的信息交流。"},{"ep":"bx1-08","n":"BX1-08","p":1,"a":"p1","id":"fn4","src":"assets/audio/BX1-08/fn4.mp3","sec":10.128,"t":"考法：用台盼蓝染色鉴别死活细胞，死细胞被染色，活细胞不着色，体现了细胞膜控制物质进出的功能。"},{"ep":"bx1-08","n":"BX1-08","p":2,"a":"p2","id":"sg1","src":"assets/audio/BX1-08/sg1.mp3","sec":11.976,"t":"考点二，细胞间信息交流的三种方式。第一，通过化学物质传递：如激素随血液到达全身，与靶细胞膜表面的受体结合。"},{"ep":"bx1-08","n":"BX1-08","p":2,"a":"p2","id":"sg2","src":"assets/audio/BX1-08/sg2.mp3","sec":7.68,"t":"第二，相邻两个细胞的细胞膜直接接触：如精子和卵细胞之间的识别和结合。"},{"ep":"bx1-08","n":"BX1-08","p":2,"a":"p2","id":"sg3","src":"assets/audio/BX1-08/sg3.mp3","sec":7.008,"t":"第三，相邻两个细胞之间形成通道：如高等植物细胞之间的胞间连丝。"},{"ep":"bx1-08","n":"BX1-08","p":2,"a":"p2","id":"sg4","src":"assets/audio/BX1-08/sg4.mp3","sec":8.544,"t":"易错：信息交流不一定需要膜上的受体，胞间连丝就不需要；有些激素的受体在细胞内。"},{"ep":"bx1-08","n":"BX1-08","p":3,"a":"p3","id":"co1","src":"assets/audio/BX1-08/co1.mp3","sec":11.904,"t":"考点三，对细胞膜成分的探索。欧文顿发现，溶于脂质的物质更容易穿过细胞膜，推测细胞膜的主要组成成分中有脂质。"},{"ep":"bx1-08","n":"BX1-08","p":3,"a":"p3","id":"co2","src":"assets/audio/BX1-08/co2.mp3","sec":4.344,"t":"进一步分析得知，膜中的脂质主要是磷脂。"},{"ep":"bx1-08","n":"BX1-08","p":3,"a":"p3","id":"co3","src":"assets/audio/BX1-08/co3.mp3","sec":11.232,"t":"科学家从人的红细胞中提取脂质，铺成单分子层，面积恰为红细胞表面积的2倍，推断磷脂分子排列为连续的两层。"},{"ep":"bx1-08","n":"BX1-08","p":3,"a":"p3","id":"co4","src":"assets/audio/BX1-08/co4.mp3","sec":7.728,"t":"人们又发现细胞的表面张力明显低于油—水界面，推测细胞膜中还附有蛋白质。"},{"ep":"bx1-08","n":"BX1-08","p":3,"a":"p3","id":"co5","src":"assets/audio/BX1-08/co5.mp3","sec":11.256,"t":"考法：为什么用哺乳动物成熟的红细胞制备细胞膜？解题方法：它没有细胞核和众多的细胞器，得到的膜比较纯净。"},{"ep":"bx1-08","n":"BX1-08","p":4,"a":"p4","id":"st1","src":"assets/audio/BX1-08/st1.mp3","sec":9.792,"t":"考点四，对细胞膜结构的探索。罗伯特森在电镜下看到细胞膜呈清晰的暗—亮—暗三层结构。"},{"ep":"bx1-08","n":"BX1-08","p":4,"a":"p4","id":"st2","src":"assets/audio/BX1-08/st2.mp3","sec":11.568,"t":"他提出细胞膜由蛋白质—脂质—蛋白质三层构成，是静态的统一结构；但这无法解释细胞的生长、变形虫的运动等现象。"},{"ep":"bx1-08","n":"BX1-08","p":4,"a":"p4","id":"st3","src":"assets/audio/BX1-08/st3.mp3","sec":9.456,"t":"1970年，科学家用荧光染料分别标记小鼠细胞和人细胞表面的蛋白质，再让两种细胞融合。"},{"ep":"bx1-08","n":"BX1-08","p":4,"a":"p4","id":"st4","src":"assets/audio/BX1-08/st4.mp3","sec":12.0,"t":"刚融合时，一半发红色荧光，一半发绿色荧光；37℃下经过40分钟，两种颜色均匀分布，说明细胞膜具有流动性。"},{"ep":"bx1-08","n":"BX1-08","p":4,"a":"p4","id":"st5","src":"assets/audio/BX1-08/st5.mp3","sec":8.616,"t":"易错：人鼠细胞融合实验证明膜蛋白可以运动，用的是荧光标记法，不是同位素标记法。"},{"ep":"bx1-08","n":"BX1-08","p":5,"a":"p5","id":"md1","src":"assets/audio/BX1-08/md1.mp3","sec":8.112,"t":"考点五，流动镶嵌模型。1972年，辛格和尼科尔森提出了流动镶嵌模型。"},{"ep":"bx1-08","n":"BX1-08","p":5,"a":"p5","id":"md2","src":"assets/audio/BX1-08/md2.mp3","sec":6.648,"t":"磷脂双分子层是膜的基本支架，磷脂分子的头部亲水，尾部疏水。"},{"ep":"bx1-08","n":"BX1-08","p":5,"a":"p5","id":"md3","src":"assets/audio/BX1-08/md3.mp3","sec":9.312,"t":"蛋白质分子有的镶在磷脂双分子层表面，有的部分或全部嵌入其中，有的贯穿整个磷脂双分子层。"},{"ep":"bx1-08","n":"BX1-08","p":5,"a":"p5","id":"md4","src":"assets/audio/BX1-08/md4.mp3","sec":6.096,"t":"磷脂分子可以侧向自由移动，大多数蛋白质分子也能运动。"},{"ep":"bx1-08","n":"BX1-08","p":5,"a":"p5","id":"md5","src":"assets/audio/BX1-08/md5.mp3","sec":10.944,"t":"易错：是大多数蛋白质能运动，不是全部；膜的功能主要由蛋白质承担，功能越复杂，蛋白质的种类和数量越多。"},{"ep":"bx1-08","n":"BX1-08","p":6,"a":"p6","id":"gl1","src":"assets/audio/BX1-08/gl1.mp3","sec":12.36,"t":"考点六，糖被。细胞膜外表面的糖类分子，与蛋白质结合形成糖蛋白，与脂质结合形成糖脂，这些糖类分子叫作糖被。"},{"ep":"bx1-08","n":"BX1-08","p":6,"a":"p6","id":"gl2","src":"assets/audio/BX1-08/gl2.mp3","sec":6.144,"t":"糖被与细胞表面的识别、细胞间的信息传递等功能有密切关系。"},{"ep":"bx1-08","n":"BX1-08","p":6,"a":"p6","id":"gl3","src":"assets/audio/BX1-08/gl3.mp3","sec":8.424,"t":"解题方法：糖被只分布在细胞膜的外侧，有糖被的一侧是细胞外，可以用来判断膜的内外。"},{"ep":"bx1-08","n":"BX1-08","p":7,"a":"p7","id":"pp1","src":"assets/audio/BX1-08/pp1.mp3","sec":7.488,"t":"考点七，结构特点和功能特性。细胞膜的结构特点是具有一定的流动性。"},{"ep":"bx1-08","n":"BX1-08","p":7,"a":"p7","id":"pp2","src":"assets/audio/BX1-08/pp2.mp3","sec":6.792,"t":"实例有变形虫的变形运动、胞吞和胞吐、细胞融合、质壁分离等。"},{"ep":"bx1-08","n":"BX1-08","p":7,"a":"p7","id":"pp3","src":"assets/audio/BX1-08/pp3.mp3","sec":7.056,"t":"细胞膜的功能特性是选择透过性，这与膜上转运蛋白的种类和数量有关。"},{"ep":"bx1-08","n":"BX1-08","p":7,"a":"p7","id":"pp4","src":"assets/audio/BX1-08/pp4.mp3","sec":9.408,"t":"易错：流动性是结构特点，选择透过性是功能特性，别颠倒；流动性是选择透过性的基础。"},{"ep":"bx1-08","n":"BX1-08","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-08/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-08","n":"BX1-08","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-08/rv2.mp3","sec":8.256,"t":"判断一？错，控制作用是相对的。判断二？错，胞间连丝不需要受体。"},{"ep":"bx1-08","n":"BX1-08","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-08/rv3.mp3","sec":6.408,"t":"判断三？对。判断四？错，用的是荧光标记法。"},{"ep":"bx1-08","n":"BX1-08","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-08/rv4.mp3","sec":8.544,"t":"判断五？错，糖被只在外侧。判断六？错，功能特性是选择透过性。"},{"ep":"bx1-08","n":"BX1-08","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-08/rv5.mp3","sec":8.544,"t":"七个考点串成一条线：结构决定功能，流动性是选择透过性的基础。我们下期再见！"},{"ep":"bx1-09","n":"BX1-09","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-09/in1.mp3","sec":10.464,"t":"同学们好！这节课梳理人教版必修一第三章第二节——细胞器之间的分工合作的上半部分：细胞器之间的分工。"},{"ep":"bx1-09","n":"BX1-09","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-09/in2.mp3","sec":7.176,"t":"高考常考各种细胞器的结构和功能，以及按膜、成分和分布给细胞器归类。"},{"ep":"bx1-09","n":"BX1-09","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-09/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-09","n":"BX1-09","p":1,"a":"p1","id":"cf1","src":"assets/audio/BX1-09/cf1.mp3","sec":10.704,"t":"考点一，分离细胞器的方法——差速离心法。先破坏细胞膜，形成由各种细胞器和细胞中其他物质组成的匀浆。"},{"ep":"bx1-09","n":"BX1-09","p":1,"a":"p1","id":"cf2","src":"assets/audio/BX1-09/cf2.mp3","sec":7.248,"t":"再用逐渐提高离心速率的方法分离不同大小的颗粒：颗粒越大，越先沉降。"},{"ep":"bx1-09","n":"BX1-09","p":1,"a":"p1","id":"cf3","src":"assets/audio/BX1-09/cf3.mp3","sec":8.832,"t":"易错：差速离心是逐渐提高转速；要和证明DNA半保留复制用的密度梯度离心区分开。"},{"ep":"bx1-09","n":"BX1-09","p":2,"a":"p2","id":"mt1","src":"assets/audio/BX1-09/mt1.mp3","sec":8.136,"t":"考点二，线粒体。线粒体是细胞进行有氧呼吸的主要场所，是细胞的“动力车间”。"},{"ep":"bx1-09","n":"BX1-09","p":2,"a":"p2","id":"mt2","src":"assets/audio/BX1-09/mt2.mp3","sec":7.392,"t":"线粒体具有双层膜，内膜的某些部位向内腔折叠形成嵴，增大了膜面积。"},{"ep":"bx1-09","n":"BX1-09","p":2,"a":"p2","id":"mt3","src":"assets/audio/BX1-09/mt3.mp3","sec":6.912,"t":"线粒体中含有少量的DNA和RNA，能合成一部分自身需要的蛋白质。"},{"ep":"bx1-09","n":"BX1-09","p":2,"a":"p2","id":"mt4","src":"assets/audio/BX1-09/mt4.mp3","sec":11.256,"t":"考法：代谢旺盛的细胞，如心肌细胞，线粒体多。易错：线粒体不能直接分解葡萄糖，进入线粒体的是丙酮酸。"},{"ep":"bx1-09","n":"BX1-09","p":3,"a":"p3","id":"cl1","src":"assets/audio/BX1-09/cl1.mp3","sec":9.048,"t":"考点三，叶绿体。叶绿体是光合作用的场所，是植物细胞的“养料制造车间”和“能量转换站”。"},{"ep":"bx1-09","n":"BX1-09","p":3,"a":"p3","id":"cl2","src":"assets/audio/BX1-09/cl2.mp3","sec":7.944,"t":"叶绿体也有双层膜，内部有许多基粒，每个基粒由一个个圆饼状的类囊体堆叠而成。"},{"ep":"bx1-09","n":"BX1-09","p":3,"a":"p3","id":"cl3","src":"assets/audio/BX1-09/cl3.mp3","sec":7.416,"t":"类囊体的薄膜上分布着光合色素；叶绿体中也含有少量的DNA和RNA。"},{"ep":"bx1-09","n":"BX1-09","p":3,"a":"p3","id":"cl4","src":"assets/audio/BX1-09/cl4.mp3","sec":9.288,"t":"易错：植物细胞不一定都有叶绿体，如根尖细胞；能光合作用的也不一定有叶绿体，如蓝细菌。"},{"ep":"bx1-09","n":"BX1-09","p":4,"a":"p4","id":"er1","src":"assets/audio/BX1-09/er1.mp3","sec":11.64,"t":"考点四，内质网和高尔基体。内质网是由膜连接而成的网状结构，是蛋白质等大分子的合成、加工场所和运输通道。"},{"ep":"bx1-09","n":"BX1-09","p":4,"a":"p4","id":"er2","src":"assets/audio/BX1-09/er2.mp3","sec":6.504,"t":"粗面内质网上附着有核糖体；光面内质网是脂质合成的场所。"},{"ep":"bx1-09","n":"BX1-09","p":4,"a":"p4","id":"er3","src":"assets/audio/BX1-09/er3.mp3","sec":7.968,"t":"高尔基体主要对来自内质网的蛋白质进行加工、分类和包装，是“车间”及“发送站”。"},{"ep":"bx1-09","n":"BX1-09","p":4,"a":"p4","id":"er4","src":"assets/audio/BX1-09/er4.mp3","sec":8.592,"t":"易错：高尔基体在植物细胞中与细胞壁的形成有关，在动物细胞中与分泌物的形成有关。"},{"ep":"bx1-09","n":"BX1-09","p":5,"a":"p5","id":"ly1","src":"assets/audio/BX1-09/ly1.mp3","sec":7.776,"t":"考点五，溶酶体和液泡。溶酶体内部含有多种水解酶，是细胞的“消化车间”。"},{"ep":"bx1-09","n":"BX1-09","p":5,"a":"p5","id":"ly2","src":"assets/audio/BX1-09/ly2.mp3","sec":6.888,"t":"它能分解衰老、损伤的细胞器，吞噬并杀死侵入细胞的病毒或细菌。"},{"ep":"bx1-09","n":"BX1-09","p":5,"a":"p5","id":"ly3","src":"assets/audio/BX1-09/ly3.mp3","sec":12.216,"t":"液泡主要存在于植物细胞中，内有细胞液，含糖类、无机盐、色素和蛋白质等，可以调节细胞内的环境，使植物细胞保持坚挺。"},{"ep":"bx1-09","n":"BX1-09","p":5,"a":"p5","id":"ly4","src":"assets/audio/BX1-09/ly4.mp3","sec":8.424,"t":"易错：溶酶体的水解酶是在核糖体上合成的；花瓣、果实的颜色来自液泡中的色素。"},{"ep":"bx1-09","n":"BX1-09","p":6,"a":"p6","id":"nm1","src":"assets/audio/BX1-09/nm1.mp3","sec":11.664,"t":"考点六，核糖体、中心体和细胞骨架。核糖体是“生产蛋白质的机器”，有的附着在内质网上，有的游离在细胞质中。"},{"ep":"bx1-09","n":"BX1-09","p":6,"a":"p6","id":"nm2","src":"assets/audio/BX1-09/nm2.mp3","sec":9.864,"t":"中心体见于动物和某些低等植物细胞，由两个互相垂直的中心粒及周围物质组成，与细胞的有丝分裂有关。"},{"ep":"bx1-09","n":"BX1-09","p":6,"a":"p6","id":"nm3","src":"assets/audio/BX1-09/nm3.mp3","sec":8.664,"t":"细胞骨架是由蛋白质纤维组成的网架结构，维持细胞的形态，锚定并支撑着许多细胞器。"},{"ep":"bx1-09","n":"BX1-09","p":6,"a":"p6","id":"nm4","src":"assets/audio/BX1-09/nm4.mp3","sec":7.56,"t":"易错：细胞骨架的成分是蛋白质，不是纤维素；高等植物细胞没有中心体。"},{"ep":"bx1-09","n":"BX1-09","p":7,"a":"p7","id":"sm1","src":"assets/audio/BX1-09/sm1.mp3","sec":10.2,"t":"考点七，细胞器的归纳。双层膜：线粒体、叶绿体；无膜：核糖体、中心体；其余是单层膜。"},{"ep":"bx1-09","n":"BX1-09","p":7,"a":"p7","id":"sm2","src":"assets/audio/BX1-09/sm2.mp3","sec":7.152,"t":"含核酸的：线粒体、叶绿体含DNA和RNA，核糖体只含RNA。"},{"ep":"bx1-09","n":"BX1-09","p":7,"a":"p7","id":"sm3","src":"assets/audio/BX1-09/sm3.mp3","sec":13.896,"t":"含色素的：叶绿体和液泡。叶绿体存在于绿色植物能进行光合作用的细胞中，液泡主要存在于植物细胞中；中心体见于动物和某些低等植物细胞。"},{"ep":"bx1-09","n":"BX1-09","p":7,"a":"p7","id":"sm4","src":"assets/audio/BX1-09/sm4.mp3","sec":9.408,"t":"解题方法：按膜层数、含核酸、含色素、分布四个维度列表记忆，题目问哪个维度就查哪一列。"},{"ep":"bx1-09","n":"BX1-09","p":8,"a":"p8","id":"ob1","src":"assets/audio/BX1-09/ob1.mp3","sec":11.04,"t":"考点八，用高倍显微镜观察叶绿体和细胞质的流动。常用藓类的叶或黑藻的叶，叶片薄，可以直接制成装片。"},{"ep":"bx1-09","n":"BX1-09","p":8,"a":"p8","id":"ob2","src":"assets/audio/BX1-09/ob2.mp3","sec":9.288,"t":"用菠菜叶时，要撕取稍带些叶肉的下表皮，因为靠近下表皮的叶肉细胞中，叶绿体大而数目少。"},{"ep":"bx1-09","n":"BX1-09","p":8,"a":"p8","id":"ob3","src":"assets/audio/BX1-09/ob3.mp3","sec":7.776,"t":"观察细胞质的流动，以叶绿体的运动作为标志；临时装片要随时保持有水的状态。"},{"ep":"bx1-09","n":"BX1-09","p":8,"a":"p8","id":"ob4","src":"assets/audio/BX1-09/ob4.mp3","sec":7.68,"t":"易错：视野中细胞质环流的方向与实际方向相同；观察叶绿体不需要染色。"},{"ep":"bx1-09","n":"BX1-09","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-09/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-09","n":"BX1-09","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-09/rv2.mp3","sec":8.52,"t":"判断一？错，是逐渐提高转速。判断二？错，进入线粒体的是丙酮酸。"},{"ep":"bx1-09","n":"BX1-09","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-09/rv3.mp3","sec":9.048,"t":"判断三？错，根尖细胞就没有叶绿体。判断四？错，水解酶在核糖体上合成。"},{"ep":"bx1-09","n":"BX1-09","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-09/rv4.mp3","sec":6.048,"t":"判断五？对。判断六？对，环流方向不变。"},{"ep":"bx1-09","n":"BX1-09","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-09/rv5.mp3","sec":9.504,"t":"八个考点串成一条线：膜层数、核酸、色素、分布，四个维度归纳细胞器。我们下期再见！"},{"ep":"bx1-10","n":"BX1-10","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-10/in1.mp3","sec":10.368,"t":"同学们好！这节课梳理人教版必修一第三章第二节的下半部分——细胞器之间的协调配合和细胞的生物膜系统。"},{"ep":"bx1-10","n":"BX1-10","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-10/in2.mp3","sec":7.8,"t":"高考常考分泌蛋白的合成和运输途径，以及放射性出现的顺序和膜面积的变化。"},{"ep":"bx1-10","n":"BX1-10","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-10/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-10","n":"BX1-10","p":1,"a":"p1","id":"se1","src":"assets/audio/BX1-10/se1.mp3","sec":8.784,"t":"考点一，分泌蛋白。在细胞内合成后，分泌到细胞外起作用的蛋白质，叫作分泌蛋白。"},{"ep":"bx1-10","n":"BX1-10","p":1,"a":"p1","id":"se2","src":"assets/audio/BX1-10/se2.mp3","sec":5.28,"t":"常见的有消化酶、抗体和一部分激素，比如胰岛素。"},{"ep":"bx1-10","n":"BX1-10","p":1,"a":"p1","id":"se3","src":"assets/audio/BX1-10/se3.mp3","sec":8.568,"t":"易错：血红蛋白、呼吸酶在细胞内起作用，不是分泌蛋白；性激素是固醇，也不是。"},{"ep":"bx1-10","n":"BX1-10","p":2,"a":"p2","id":"lb1","src":"assets/audio/BX1-10/lb1.mp3","sec":9.264,"t":"考点二，研究方法——同位素标记法。科学家向豚鼠的胰腺腺泡细胞中注射3H标记的亮氨酸。"},{"ep":"bx1-10","n":"BX1-10","p":2,"a":"p2","id":"lb2","src":"assets/audio/BX1-10/lb2.mp3","sec":7.152,"t":"然后追踪放射性依次出现的位置，就知道了分泌蛋白合成和运输的途径。"},{"ep":"bx1-10","n":"BX1-10","p":2,"a":"p2","id":"lb3","src":"assets/audio/BX1-10/lb3.mp3","sec":10.656,"t":"易错：标记的是亮氨酸——蛋白质的原料；如果标记胸腺嘧啶或尿嘧啶，追踪的就是DNA或RNA的合成了。"},{"ep":"bx1-10","n":"BX1-10","p":3,"a":"p3","id":"ro1","src":"assets/audio/BX1-10/ro1.mp3","sec":11.832,"t":"考点三，分泌蛋白的合成和运输。先在游离的核糖体上合成一段肽链，再与核糖体一起转移到粗面内质网上继续合成。"},{"ep":"bx1-10","n":"BX1-10","p":3,"a":"p3","id":"ro2","src":"assets/audio/BX1-10/ro2.mp3","sec":9.168,"t":"肽链在内质网腔内加工、折叠，形成有一定空间结构的蛋白质，再由囊泡包裹着运到高尔基体。"},{"ep":"bx1-10","n":"BX1-10","p":3,"a":"p3","id":"ro3","src":"assets/audio/BX1-10/ro3.mp3","sec":9.672,"t":"高尔基体对蛋白质做进一步的修饰加工，再由囊泡运到细胞膜，与细胞膜融合，把蛋白质分泌到细胞外。"},{"ep":"bx1-10","n":"BX1-10","p":3,"a":"p3","id":"ro4","src":"assets/audio/BX1-10/ro4.mp3","sec":3.912,"t":"整个过程需要的能量，主要来自线粒体。"},{"ep":"bx1-10","n":"BX1-10","p":3,"a":"p3","id":"ro5","src":"assets/audio/BX1-10/ro5.mp3","sec":8.064,"t":"解题方法：记住路线——核糖体 → 内质网 → 高尔基体 → 细胞膜，线粒体全程供能。"},{"ep":"bx1-10","n":"BX1-10","p":4,"a":"p4","id":"cv1","src":"assets/audio/BX1-10/cv1.mp3","sec":12.24,"t":"考点四，放射性和膜面积的变化。放射性依次出现在附着有核糖体的内质网、高尔基体、靠近细胞膜的囊泡，最后到细胞外。"},{"ep":"bx1-10","n":"BX1-10","p":4,"a":"p4","id":"cv2","src":"assets/audio/BX1-10/cv2.mp3","sec":7.776,"t":"膜面积：内质网膜减少，高尔基体膜先增加后减少、基本不变，细胞膜增加。"},{"ep":"bx1-10","n":"BX1-10","p":4,"a":"p4","id":"cv3","src":"assets/audio/BX1-10/cv3.mp3","sec":8.208,"t":"解题方法：看柱形图，减少的是内质网，前后不变的是高尔基体，增加的是细胞膜。"},{"ep":"bx1-10","n":"BX1-10","p":5,"a":"p5","id":"sy1","src":"assets/audio/BX1-10/sy1.mp3","sec":9.456,"t":"考点五，细胞的生物膜系统。细胞膜、核膜和细胞器膜等结构，共同构成细胞的生物膜系统。"},{"ep":"bx1-10","n":"BX1-10","p":5,"a":"p5","id":"sy2","src":"assets/audio/BX1-10/sy2.mp3","sec":6.456,"t":"这些生物膜的组成成分和结构很相似，在结构和功能上紧密联系。"},{"ep":"bx1-10","n":"BX1-10","p":5,"a":"p5","id":"sy3","src":"assets/audio/BX1-10/sy3.mp3","sec":9.312,"t":"功能一，使细胞具有相对稳定的内部环境，在物质运输、能量转化和信息传递中起决定性作用。"},{"ep":"bx1-10","n":"BX1-10","p":5,"a":"p5","id":"sy4","src":"assets/audio/BX1-10/sy4.mp3","sec":11.4,"t":"功能二，广阔的膜面积为多种酶提供了附着位点；功能三，把细胞器分隔开，使多种化学反应同时进行而互不干扰。"},{"ep":"bx1-10","n":"BX1-10","p":5,"a":"p5","id":"sy5","src":"assets/audio/BX1-10/sy5.mp3","sec":8.88,"t":"易错：生物膜系统指细胞内的膜，小肠黏膜不属于；原核细胞只有细胞膜，没有生物膜系统。"},{"ep":"bx1-10","n":"BX1-10","p":6,"a":"p6","id":"tp1","src":"assets/audio/BX1-10/tp1.mp3","sec":7.008,"t":"考点六，易错辨析。分泌蛋白通过胞吐出细胞，穿过的膜是0层。"},{"ep":"bx1-10","n":"BX1-10","p":6,"a":"p6","id":"tp2","src":"assets/audio/BX1-10/tp2.mp3","sec":7.632,"t":"囊泡与膜融合，体现了生物膜的流动性，也说明不同生物膜之间可以相互转化。"},{"ep":"bx1-10","n":"BX1-10","p":6,"a":"p6","id":"tp3","src":"assets/audio/BX1-10/tp3.mp3","sec":7.704,"t":"内质网膜可以直接与核膜、细胞膜相连；与高尔基体膜则通过囊泡间接联系。"},{"ep":"bx1-10","n":"BX1-10","p":6,"a":"p6","id":"tp4","src":"assets/audio/BX1-10/tp4.mp3","sec":6.912,"t":"解题方法：问“穿过几层膜”，凡是囊泡运输、胞吞和胞吐，都答0层。"},{"ep":"bx1-10","n":"BX1-10","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-10/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-10","n":"BX1-10","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-10/rv2.mp3","sec":6.48,"t":"判断一？错，它们在细胞内起作用。判断二？对。"},{"ep":"bx1-10","n":"BX1-10","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-10/rv3.mp3","sec":9.6,"t":"判断三？错，先在游离的核糖体上合成。判断四？错，高尔基体膜面积基本不变。"},{"ep":"bx1-10","n":"BX1-10","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-10/rv4.mp3","sec":7.008,"t":"判断五？错，生物膜系统指细胞内的膜。判断六？对。"},{"ep":"bx1-10","n":"BX1-10","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-10/rv5.mp3","sec":9.264,"t":"六个考点串成一条线：核糖体、内质网、高尔基体、细胞膜，线粒体供能。我们下期再见！"},{"ep":"bx1-11","n":"BX1-11","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-11/in1.mp3","sec":7.68,"t":"同学们好！这节课梳理人教版必修一第三章第三节——细胞核的结构和功能。"},{"ep":"bx1-11","n":"BX1-11","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-11/in2.mp3","sec":6.936,"t":"高考常考探究细胞核功能的实验、细胞核的结构，以及三类模型的判断。"},{"ep":"bx1-11","n":"BX1-11","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-11/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-11","n":"BX1-11","p":1,"a":"p1","id":"fn1","src":"assets/audio/BX1-11/fn1.mp3","sec":8.016,"t":"考点一，细胞核的功能。细胞核是遗传信息库，是细胞代谢和遗传的控制中心。"},{"ep":"bx1-11","n":"BX1-11","p":1,"a":"p1","id":"fn2","src":"assets/audio/BX1-11/fn2.mp3","sec":6.288,"t":"原因是DNA主要存在于细胞核中，DNA上储存着遗传信息。"},{"ep":"bx1-11","n":"BX1-11","p":1,"a":"p1","id":"fn3","src":"assets/audio/BX1-11/fn3.mp3","sec":8.664,"t":"易错：细胞核是代谢的控制中心，不是代谢的中心；细胞代谢的主要场所是细胞质基质。"},{"ep":"bx1-11","n":"BX1-11","p":2,"a":"p2","id":"am1","src":"assets/audio/BX1-11/am1.mp3","sec":12.552,"t":"考点二，美西螈核移植实验。把黑色美西螈胚胎细胞的细胞核，移植到白色美西螈的去核卵细胞中，发育成的美西螈全是黑色的。"},{"ep":"bx1-11","n":"BX1-11","p":2,"a":"p2","id":"am2","src":"assets/audio/BX1-11/am2.mp3","sec":4.776,"t":"说明美西螈皮肤颜色的遗传是由细胞核控制的。"},{"ep":"bx1-11","n":"BX1-11","p":2,"a":"p2","id":"am3","src":"assets/audio/BX1-11/am3.mp3","sec":10.176,"t":"蝾螈受精卵横缢实验：有核的一半能分裂，无核的一半停止分裂；挤入一个细胞核后，无核的一半也开始分裂。"},{"ep":"bx1-11","n":"BX1-11","p":2,"a":"p2","id":"am4","src":"assets/audio/BX1-11/am4.mp3","sec":3.984,"t":"说明细胞核控制着细胞的分裂、分化。"},{"ep":"bx1-11","n":"BX1-11","p":2,"a":"p2","id":"am5","src":"assets/audio/BX1-11/am5.mp3","sec":5.832,"t":"解题方法：看后代性状和谁的细胞核一致，就由谁控制。"},{"ep":"bx1-11","n":"BX1-11","p":3,"a":"p3","id":"ag1","src":"assets/audio/BX1-11/ag1.mp3","sec":12.288,"t":"考点三，变形虫切割实验：有核的一半能摄食、对刺激有反应、生长和分裂，无核的一半不能，说明细胞核控制着细胞的生命活动。"},{"ep":"bx1-11","n":"BX1-11","p":3,"a":"p3","id":"ag2","src":"assets/audio/BX1-11/ag2.mp3","sec":8.28,"t":"伞藻嫁接实验：把菊花形帽伞藻的柄嫁接到伞形帽伞藻的假根上，长出的是伞形帽。"},{"ep":"bx1-11","n":"BX1-11","p":3,"a":"p3","id":"ag3","src":"assets/audio/BX1-11/ag3.mp3","sec":8.4,"t":"但细胞核在假根中，嫁接不能排除假根中细胞质的影响，所以还要做伞藻核移植实验。"},{"ep":"bx1-11","n":"BX1-11","p":3,"a":"p3","id":"ag4","src":"assets/audio/BX1-11/ag4.mp3","sec":8.04,"t":"解题方法：嫁接只能说明伞帽形状与假根有关，核移植才能说明与细胞核有关。"},{"ep":"bx1-11","n":"BX1-11","p":4,"a":"p4","id":"st1","src":"assets/audio/BX1-11/st1.mp3","sec":7.272,"t":"考点四，细胞核的结构。核膜是双层膜，把核内物质与细胞质分开。"},{"ep":"bx1-11","n":"BX1-11","p":4,"a":"p4","id":"st2","src":"assets/audio/BX1-11/st2.mp3","sec":4.944,"t":"核孔实现核质之间频繁的物质交换和信息交流。"},{"ep":"bx1-11","n":"BX1-11","p":4,"a":"p4","id":"st3","src":"assets/audio/BX1-11/st3.mp3","sec":4.992,"t":"核仁与某种RNA的合成以及核糖体的形成有关。"},{"ep":"bx1-11","n":"BX1-11","p":4,"a":"p4","id":"st4","src":"assets/audio/BX1-11/st4.mp3","sec":6.384,"t":"染色质主要由DNA和蛋白质组成，DNA是遗传信息的载体。"},{"ep":"bx1-11","n":"BX1-11","p":4,"a":"p4","id":"st5","src":"assets/audio/BX1-11/st5.mp3","sec":9.264,"t":"易错：核孔具有选择性，DNA不能通过核孔出细胞核；代谢旺盛的细胞，核孔多、核仁大。"},{"ep":"bx1-11","n":"BX1-11","p":5,"a":"p5","id":"ch1","src":"assets/audio/BX1-11/ch1.mp3","sec":8.424,"t":"考点五，染色质与染色体。染色质是细胞核中容易被碱性染料染成深色的物质。"},{"ep":"bx1-11","n":"BX1-11","p":5,"a":"p5","id":"ch2","src":"assets/audio/BX1-11/ch2.mp3","sec":11.952,"t":"细胞分裂时，细丝状的染色质高度螺旋化、缩短变粗，成为圆柱状或杆状的染色体；分裂结束时，又解螺旋成为染色质。"},{"ep":"bx1-11","n":"BX1-11","p":5,"a":"p5","id":"ch3","src":"assets/audio/BX1-11/ch3.mp3","sec":8.712,"t":"解题方法：染色质和染色体是同一种物质在细胞不同时期的两种存在状态，成分相同。"},{"ep":"bx1-11","n":"BX1-11","p":6,"a":"p6","id":"md1","src":"assets/audio/BX1-11/md1.mp3","sec":8.52,"t":"考点六，科学方法——建构模型。模型是对认识对象所作的一种简化的概括性描述。"},{"ep":"bx1-11","n":"BX1-11","p":6,"a":"p6","id":"md2","src":"assets/audio/BX1-11/md2.mp3","sec":10.872,"t":"物理模型以实物或图画形式直观表达认识对象的特征，比如真核细胞的三维结构模型、DNA双螺旋结构模型。"},{"ep":"bx1-11","n":"BX1-11","p":6,"a":"p6","id":"md3","src":"assets/audio/BX1-11/md3.mp3","sec":11.304,"t":"概念模型用文字、箭头等表示概念之间的关系，如概念图；数学模型用公式、曲线等表示，如种群增长曲线。"},{"ep":"bx1-11","n":"BX1-11","p":6,"a":"p6","id":"md4","src":"assets/audio/BX1-11/md4.mp3","sec":9.168,"t":"易错：照片不是模型，电镜照片是实物的真实记录；画出的细胞结构模式图才是物理模型。"},{"ep":"bx1-11","n":"BX1-11","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-11/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-11","n":"BX1-11","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-11/rv2.mp3","sec":5.784,"t":"判断一？错，是控制中心。判断二？对。"},{"ep":"bx1-11","n":"BX1-11","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-11/rv3.mp3","sec":7.968,"t":"判断三？错，还要做核移植实验。判断四？错，核孔具有选择性。"},{"ep":"bx1-11","n":"BX1-11","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-11/rv4.mp3","sec":7.44,"t":"判断五？错，是同一种物质。判断六？错，照片不是模型。"},{"ep":"bx1-11","n":"BX1-11","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-11/rv5.mp3","sec":8.736,"t":"六个考点串成一条线：细胞核是遗传信息库，是代谢和遗传的控制中心。我们下期再见！"},{"ep":"bx1-12","n":"BX1-12","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-12/in1.mp3","sec":6.552,"t":"同学们好！这节课梳理人教版必修一第四章第一节——被动运输。"},{"ep":"bx1-12","n":"BX1-12","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-12/in2.mp3","sec":8.52,"t":"高考常考渗透装置的分析、质壁分离及复原实验，以及自由扩散和协助扩散的比较。"},{"ep":"bx1-12","n":"BX1-12","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-12/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-12","n":"BX1-12","p":1,"a":"p1","id":"os1","src":"assets/audio/BX1-12/os1.mp3","sec":11.208,"t":"考点一，渗透作用。水分子等溶剂分子透过半透膜，从低浓度溶液一侧向高浓度溶液一侧扩散，叫作渗透作用。"},{"ep":"bx1-12","n":"BX1-12","p":1,"a":"p1","id":"os2","src":"assets/audio/BX1-12/os2.mp3","sec":7.968,"t":"发生渗透作用有两个条件：一是要有半透膜，二是半透膜两侧的溶液具有浓度差。"},{"ep":"bx1-12","n":"BX1-12","p":1,"a":"p1","id":"os3","src":"assets/audio/BX1-12/os3.mp3","sec":10.656,"t":"易错：这里的浓度是物质的量浓度；质量分数相同的葡萄糖溶液和蔗糖溶液，葡萄糖溶液的物质的量浓度更大。"},{"ep":"bx1-12","n":"BX1-12","p":2,"a":"p2","id":"dv1","src":"assets/audio/BX1-12/dv1.mp3","sec":9.288,"t":"考点二，渗透装置的分析。漏斗内装蔗糖溶液，烧杯中是清水，漏斗口封着一层半透膜。"},{"ep":"bx1-12","n":"BX1-12","p":2,"a":"p2","id":"dv2","src":"assets/audio/BX1-12/dv2.mp3","sec":6.096,"t":"单位时间内进入漏斗的水分子多于出来的，漏斗内液面上升。"},{"ep":"bx1-12","n":"BX1-12","p":2,"a":"p2","id":"dv3","src":"assets/audio/BX1-12/dv3.mp3","sec":9.744,"t":"液面上升到一定高度后停止：此时液柱的压力与浓度差的作用相互平衡，水分子进出达到动态平衡。"},{"ep":"bx1-12","n":"BX1-12","p":2,"a":"p2","id":"dv4","src":"assets/audio/BX1-12/dv4.mp3","sec":10.416,"t":"易错：平衡时漏斗内外浓度并不相等，漏斗内仍高于烧杯；水分子仍在双向移动，只是进出速率相等。"},{"ep":"bx1-12","n":"BX1-12","p":3,"a":"p3","id":"an1","src":"assets/audio/BX1-12/an1.mp3","sec":7.416,"t":"考点三，动物细胞的吸水和失水。动物细胞的细胞膜相当于一层半透膜。"},{"ep":"bx1-12","n":"BX1-12","p":3,"a":"p3","id":"an2","src":"assets/audio/BX1-12/an2.mp3","sec":10.728,"t":"外界溶液浓度低于细胞质浓度时，细胞吸水膨胀，甚至涨破；外界浓度高于细胞质浓度时，细胞失水皱缩。"},{"ep":"bx1-12","n":"BX1-12","p":3,"a":"p3","id":"an3","src":"assets/audio/BX1-12/an3.mp3","sec":8.544,"t":"两者浓度相同时，水分子进出平衡，细胞形态不变，所以静脉输液要用生理盐水。"},{"ep":"bx1-12","n":"BX1-12","p":3,"a":"p3","id":"an4","src":"assets/audio/BX1-12/an4.mp3","sec":9.792,"t":"考法：红细胞放入不同浓度溶液中的形态变化。解题方法：水往浓处流，先比较细胞内外的浓度。"},{"ep":"bx1-12","n":"BX1-12","p":4,"a":"p4","id":"pp1","src":"assets/audio/BX1-12/pp1.mp3","sec":8.352,"t":"考点四，原生质层。成熟的植物细胞有中央大液泡，液泡内的液体叫细胞液。"},{"ep":"bx1-12","n":"BX1-12","p":4,"a":"p4","id":"pp2","src":"assets/audio/BX1-12/pp2.mp3","sec":7.848,"t":"细胞膜和液泡膜，以及两层膜之间的细胞质，称为原生质层，相当于一层半透膜。"},{"ep":"bx1-12","n":"BX1-12","p":4,"a":"p4","id":"pp3","src":"assets/audio/BX1-12/pp3.mp3","sec":5.04,"t":"细胞壁是全透性的，而且伸缩性比原生质层小。"},{"ep":"bx1-12","n":"BX1-12","p":4,"a":"p4","id":"pp4","src":"assets/audio/BX1-12/pp4.mp3","sec":9.72,"t":"易错：原生质层不包括细胞液，也不能把细胞壁算进去；起半透膜作用的是原生质层，不是细胞壁。"},{"ep":"bx1-12","n":"BX1-12","p":5,"a":"p5","id":"pl1","src":"assets/audio/BX1-12/pl1.mp3","sec":9.624,"t":"考点五，探究植物细胞的吸水和失水。常用紫色洋葱鳞片叶的外表皮，液泡有颜色，便于观察。"},{"ep":"bx1-12","n":"BX1-12","p":5,"a":"p5","id":"pl2","src":"assets/audio/BX1-12/pl2.mp3","sec":10.248,"t":"滴加0.3 g/mL的蔗糖溶液，原生质层与细胞壁逐渐分离，出现质壁分离，液泡变小、颜色变深。"},{"ep":"bx1-12","n":"BX1-12","p":5,"a":"p5","id":"pl3","src":"assets/audio/BX1-12/pl3.mp3","sec":5.304,"t":"再滴加清水，液泡逐渐变大，出现质壁分离复原。"},{"ep":"bx1-12","n":"BX1-12","p":5,"a":"p5","id":"pl4","src":"assets/audio/BX1-12/pl4.mp3","sec":5.424,"t":"整个实验用低倍镜观察三次，形成前后自身对照。"},{"ep":"bx1-12","n":"BX1-12","p":5,"a":"p5","id":"pl5","src":"assets/audio/BX1-12/pl5.mp3","sec":9.816,"t":"解题方法：质壁分离的内因是原生质层的伸缩性大于细胞壁，外因是外界溶液浓度大于细胞液浓度。"},{"ep":"bx1-12","n":"BX1-12","p":6,"a":"p6","id":"ap1","src":"assets/audio/BX1-12/ap1.mp3","sec":10.296,"t":"考点六，质壁分离的应用。可以判断细胞的死活，死细胞不发生质壁分离；还可以估测细胞液浓度的范围。"},{"ep":"bx1-12","n":"BX1-12","p":6,"a":"p6","id":"ap2","src":"assets/audio/BX1-12/ap2.mp3","sec":7.2,"t":"把细胞放入一定浓度的KNO3溶液中，先发生质壁分离，随后会自动复原。"},{"ep":"bx1-12","n":"BX1-12","p":6,"a":"p6","id":"ap3","src":"assets/audio/BX1-12/ap3.mp3","sec":11.952,"t":"因为K+和NO3-可以被细胞主动吸收，细胞液浓度升高，细胞又吸水；尿素、甘油、乙二醇溶液中也会自动复原。"},{"ep":"bx1-12","n":"BX1-12","p":6,"a":"p6","id":"ap4","src":"assets/audio/BX1-12/ap4.mp3","sec":10.176,"t":"易错：外界溶液浓度过高，细胞失水过多而死亡，就不能复原；动物细胞没有细胞壁，不会发生质壁分离。"},{"ep":"bx1-12","n":"BX1-12","p":7,"a":"p7","id":"df1","src":"assets/audio/BX1-12/df1.mp3","sec":11.496,"t":"考点七，被动运输。物质以扩散方式进出细胞，不需要消耗细胞内化学反应释放的能量，包括自由扩散和协助扩散。"},{"ep":"bx1-12","n":"BX1-12","p":7,"a":"p7","id":"df2","src":"assets/audio/BX1-12/df2.mp3","sec":8.616,"t":"自由扩散：通过简单的扩散作用进出细胞，如O2、CO2、甘油、乙醇、苯等。"},{"ep":"bx1-12","n":"BX1-12","p":7,"a":"p7","id":"df3","src":"assets/audio/BX1-12/df3.mp3","sec":9.96,"t":"协助扩散：借助膜上的转运蛋白进出细胞，如葡萄糖进入红细胞，水分子更多地借助水通道蛋白进出。"},{"ep":"bx1-12","n":"BX1-12","p":7,"a":"p7","id":"df4","src":"assets/audio/BX1-12/df4.mp3","sec":7.104,"t":"解题方法：两者都顺浓度梯度、不耗能，区别在于是否需要转运蛋白。"},{"ep":"bx1-12","n":"BX1-12","p":8,"a":"p8","id":"pt1","src":"assets/audio/BX1-12/pt1.mp3","sec":5.304,"t":"考点八，转运蛋白分为载体蛋白和通道蛋白两类。"},{"ep":"bx1-12","n":"BX1-12","p":8,"a":"p8","id":"pt2","src":"assets/audio/BX1-12/pt2.mp3","sec":9.504,"t":"载体蛋白只容许与自身结合部位相适应的分子或离子通过，每次转运时都会发生自身构象的改变。"},{"ep":"bx1-12","n":"BX1-12","p":8,"a":"p8","id":"pt3","src":"assets/audio/BX1-12/pt3.mp3","sec":10.176,"t":"通道蛋白只容许大小、形状和电荷相适宜的分子或离子通过，分子或离子通过时不需要与通道蛋白结合。"},{"ep":"bx1-12","n":"BX1-12","p":8,"a":"p8","id":"pt4","src":"assets/audio/BX1-12/pt4.mp3","sec":9.792,"t":"易错：协助扩散的速率除了受浓度差影响，还受转运蛋白数量的限制，所以曲线最后会趋于平缓。"},{"ep":"bx1-12","n":"BX1-12","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-12/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-12","n":"BX1-12","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-12/rv2.mp3","sec":10.128,"t":"判断一？错，漏斗内浓度仍然更高。判断二？错，原生质层是两层膜及其间的细胞质。"},{"ep":"bx1-12","n":"BX1-12","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-12/rv3.mp3","sec":6.48,"t":"判断三？对。判断四？错，动物细胞没有细胞壁。"},{"ep":"bx1-12","n":"BX1-12","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-12/rv4.mp3","sec":7.176,"t":"判断五？错，是协助扩散。判断六？错，不需要结合。"},{"ep":"bx1-12","n":"BX1-12","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-12/rv5.mp3","sec":8.568,"t":"八个考点串成一条线：水往浓处流，被动运输顺浓度梯度、不耗能。我们下期再见！"},{"ep":"bx1-13","n":"BX1-13","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-13/in1.mp3","sec":7.968,"t":"同学们好！这节课梳理人教版必修一第四章第二节——主动运输与胞吞、胞吐。"},{"ep":"bx1-13","n":"BX1-13","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-13/in2.mp3","sec":7.848,"t":"高考常考三种跨膜运输方式的比较、影响运输速率的曲线，以及运输方式的判断。"},{"ep":"bx1-13","n":"BX1-13","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-13/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-13","n":"BX1-13","p":1,"a":"p1","id":"ac1","src":"assets/audio/BX1-13/ac1.mp3","sec":11.52,"t":"考点一，主动运输。物质逆浓度梯度进行跨膜运输，需要载体蛋白的协助，同时还要消耗细胞内化学反应释放的能量。"},{"ep":"bx1-13","n":"BX1-13","p":1,"a":"p1","id":"ac2","src":"assets/audio/BX1-13/ac2.mp3","sec":9.144,"t":"载体蛋白与离子或分子结合后，在能量的推动下空间结构发生变化，把物质转运到膜的另一侧。"},{"ep":"bx1-13","n":"BX1-13","p":1,"a":"p1","id":"ac3","src":"assets/audio/BX1-13/ac3.mp3","sec":7.368,"t":"易错：主动运输用的是载体蛋白，不是通道蛋白；能量主要来自细胞呼吸。"},{"ep":"bx1-13","n":"BX1-13","p":2,"a":"p2","id":"mn1","src":"assets/audio/BX1-13/mn1.mp3","sec":11.76,"t":"考点二，主动运输的意义。它保证细胞按照生命活动的需要，主动选择吸收所需要的营养物质，排出代谢废物和有害物质。"},{"ep":"bx1-13","n":"BX1-13","p":2,"a":"p2","id":"mn2","src":"assets/audio/BX1-13/mn2.mp3","sec":12.312,"t":"实例：小肠上皮细胞吸收葡萄糖、氨基酸；植物根细胞吸收矿质离子；轮藻细胞中K+浓度比周围水环境高63倍。"},{"ep":"bx1-13","n":"BX1-13","p":2,"a":"p2","id":"mn3","src":"assets/audio/BX1-13/mn3.mp3","sec":12.744,"t":"考法：用呼吸抑制剂处理后，某物质吸收速率下降，说明是主动运输。解题方法：受能量影响的，只有主动运输和胞吞、胞吐。"},{"ep":"bx1-13","n":"BX1-13","p":3,"a":"p3","id":"cm1","src":"assets/audio/BX1-13/cm1.mp3","sec":8.976,"t":"考点三，三种跨膜运输方式的比较。自由扩散：顺浓度梯度，不需要转运蛋白，不耗能。"},{"ep":"bx1-13","n":"BX1-13","p":3,"a":"p3","id":"cm2","src":"assets/audio/BX1-13/cm2.mp3","sec":5.136,"t":"协助扩散：顺浓度梯度，需要转运蛋白，不耗能。"},{"ep":"bx1-13","n":"BX1-13","p":3,"a":"p3","id":"cm3","src":"assets/audio/BX1-13/cm3.mp3","sec":5.232,"t":"主动运输：逆浓度梯度，需要载体蛋白，消耗能量。"},{"ep":"bx1-13","n":"BX1-13","p":3,"a":"p3","id":"cm4","src":"assets/audio/BX1-13/cm4.mp3","sec":6.72,"t":"解题方法：三问——方向如何？要不要转运蛋白？耗不耗能？"},{"ep":"bx1-13","n":"BX1-13","p":4,"a":"p4","id":"cc1","src":"assets/audio/BX1-13/cc1.mp3","sec":9.912,"t":"考点四，物质浓度对运输速率的影响。自由扩散的速率与浓度差成正比，曲线是一条过原点的直线。"},{"ep":"bx1-13","n":"BX1-13","p":4,"a":"p4","id":"cc2","src":"assets/audio/BX1-13/cc2.mp3","sec":9.024,"t":"协助扩散和主动运输的速率先随浓度增大而增大，后来受转运蛋白数量的限制，不再增加。"},{"ep":"bx1-13","n":"BX1-13","p":4,"a":"p4","id":"cc3","src":"assets/audio/BX1-13/cc3.mp3","sec":10.224,"t":"解题方法：直线是自由扩散；出现平台的，限制因素是转运蛋白的数量，主动运输还可能受能量限制。"},{"ep":"bx1-13","n":"BX1-13","p":5,"a":"p5","id":"ox1","src":"assets/audio/BX1-13/ox1.mp3","sec":10.536,"t":"考点五，O2浓度对运输速率的影响。自由扩散和协助扩散不耗能，速率与O2浓度无关，是一条水平线。"},{"ep":"bx1-13","n":"BX1-13","p":5,"a":"p5","id":"ox2","src":"assets/audio/BX1-13/ox2.mp3","sec":8.736,"t":"主动运输消耗能量：O2浓度为0时，无氧呼吸也能提供能量，所以曲线不从原点开始。"},{"ep":"bx1-13","n":"BX1-13","p":5,"a":"p5","id":"ox3","src":"assets/audio/BX1-13/ox3.mp3","sec":6.984,"t":"O2浓度增大，速率增大；最后受载体蛋白数量的限制，趋于平稳。"},{"ep":"bx1-13","n":"BX1-13","p":5,"a":"p5","id":"ox4","src":"assets/audio/BX1-13/ox4.mp3","sec":8.016,"t":"易错：哺乳动物成熟红细胞只进行无氧呼吸，它的主动运输速率与O2浓度无关。"},{"ep":"bx1-13","n":"BX1-13","p":6,"a":"p6","id":"en1","src":"assets/audio/BX1-13/en1.mp3","sec":6.888,"t":"考点六，胞吞和胞吐。大分子物质进出细胞，靠的是胞吞和胞吐。"},{"ep":"bx1-13","n":"BX1-13","p":6,"a":"p6","id":"en2","src":"assets/audio/BX1-13/en2.mp3","sec":10.968,"t":"胞吞时，大分子先与膜上的蛋白质结合，细胞膜内陷形成小囊，包围着大分子，再分离下来形成囊泡进入细胞。"},{"ep":"bx1-13","n":"BX1-13","p":6,"a":"p6","id":"en3","src":"assets/audio/BX1-13/en3.mp3","sec":8.424,"t":"胞吐时，囊泡移到细胞膜处，与细胞膜融合，把大分子排出细胞，比如分泌蛋白的分泌。"},{"ep":"bx1-13","n":"BX1-13","p":6,"a":"p6","id":"en4","src":"assets/audio/BX1-13/en4.mp3","sec":7.944,"t":"易错：胞吞、胞吐需要消耗能量，也需要膜上蛋白质的参与，依赖于膜的流动性。"},{"ep":"bx1-13","n":"BX1-13","p":7,"a":"p7","id":"jd1","src":"assets/audio/BX1-13/jd1.mp3","sec":8.208,"t":"考点七，判断物质运输方式。一看分子大小：大分子、颗粒物走胞吞、胞吐。"},{"ep":"bx1-13","n":"BX1-13","p":7,"a":"p7","id":"jd2","src":"assets/audio/BX1-13/jd2.mp3","sec":5.112,"t":"二看浓度梯度：逆浓度梯度运输的，是主动运输。"},{"ep":"bx1-13","n":"BX1-13","p":7,"a":"p7","id":"jd3","src":"assets/audio/BX1-13/jd3.mp3","sec":8.808,"t":"三看转运蛋白和能量：要蛋白不耗能是协助扩散，都需要是主动运输，都不需要是自由扩散。"},{"ep":"bx1-13","n":"BX1-13","p":7,"a":"p7","id":"jd4","src":"assets/audio/BX1-13/jd4.mp3","sec":10.416,"t":"易错：同一种物质可能有不同的运输方式，葡萄糖进入红细胞是协助扩散，进入小肠上皮细胞是主动运输。"},{"ep":"bx1-13","n":"BX1-13","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-13/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-13","n":"BX1-13","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-13/rv2.mp3","sec":6.6,"t":"判断一？错，主动运输用载体蛋白。判断二？对。"},{"ep":"bx1-13","n":"BX1-13","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-13/rv3.mp3","sec":7.968,"t":"判断三？错，与浓度差成正比。判断四？错，无氧呼吸也能供能。"},{"ep":"bx1-13","n":"BX1-13","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-13/rv4.mp3","sec":6.84,"t":"判断五？错，胞吞、胞吐消耗能量。判断六？对。"},{"ep":"bx1-13","n":"BX1-13","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-13/rv5.mp3","sec":7.656,"t":"七个考点串成一条线：方向、蛋白、能量，三问定方式。我们下期再见！"},{"ep":"bx1-14","n":"BX1-14","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-14/in1.mp3","sec":7.896,"t":"同学们好！这节课梳理人教版必修一第五章第一节的上半部分——酶的作用和本质。"},{"ep":"bx1-14","n":"BX1-14","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-14/in2.mp3","sec":6.792,"t":"高考常考比较过氧化氢分解的实验、变量的判断，以及活化能示意图。"},{"ep":"bx1-14","n":"BX1-14","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-14/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-14","n":"BX1-14","p":1,"a":"p1","id":"mb1","src":"assets/audio/BX1-14/mb1.mp3","sec":8.376,"t":"考点一，细胞代谢。细胞中每时每刻都进行着许多化学反应，统称为细胞代谢。"},{"ep":"bx1-14","n":"BX1-14","p":1,"a":"p1","id":"mb2","src":"assets/audio/BX1-14/mb2.mp3","sec":7.512,"t":"细胞代谢离不开酶的催化，酶使细胞代谢能在温和条件下快速有序地进行。"},{"ep":"bx1-14","n":"BX1-14","p":1,"a":"p1","id":"mb3","src":"assets/audio/BX1-14/mb3.mp3","sec":8.712,"t":"易错：细胞代谢的主要场所是细胞质基质，细胞代谢的控制中心是细胞核，两者别混。"},{"ep":"bx1-14","n":"BX1-14","p":2,"a":"p2","id":"hp1","src":"assets/audio/BX1-14/hp1.mp3","sec":16.32,"t":"考点二，比较过氧化氢在不同条件下的分解。四支试管各加2 mL H2O2溶液：1号常温，2号90℃水浴，3号滴加FeCl3溶液，4号滴加肝脏研磨液。"},{"ep":"bx1-14","n":"BX1-14","p":2,"a":"p2","id":"hp2","src":"assets/audio/BX1-14/hp2.mp3","sec":10.896,"t":"结果：4号产生气泡最多、最快，带火星的卫生香复燃最猛烈；3号次之，2号也有气泡，1号几乎没有。"},{"ep":"bx1-14","n":"BX1-14","p":2,"a":"p2","id":"hp3","src":"assets/audio/BX1-14/hp3.mp3","sec":8.04,"t":"说明加热、Fe3+和过氧化氢酶都能加快H2O2分解，而酶的催化效率更高。"},{"ep":"bx1-14","n":"BX1-14","p":2,"a":"p2","id":"hp4","src":"assets/audio/BX1-14/hp4.mp3","sec":9.84,"t":"易错：肝脏要新鲜，久置的肝脏中过氧化氢酶会因微生物作用而被破坏；研磨是为了让酶充分释放。"},{"ep":"bx1-14","n":"BX1-14","p":3,"a":"p3","id":"vb1","src":"assets/audio/BX1-14/vb1.mp3","sec":9.096,"t":"考点三，变量与对照实验。实验中人为改变的变量叫自变量，比如温度、催化剂的种类。"},{"ep":"bx1-14","n":"BX1-14","p":3,"a":"p3","id":"vb2","src":"assets/audio/BX1-14/vb2.mp3","sec":9.816,"t":"随自变量变化而变化的叫因变量，比如H2O2的分解速率，用气泡多少、卫生香复燃程度来检测。"},{"ep":"bx1-14","n":"BX1-14","p":3,"a":"p3","id":"vb3","src":"assets/audio/BX1-14/vb3.mp3","sec":9.312,"t":"其他对实验结果有影响的可变因素叫无关变量，比如H2O2的浓度和用量，各组要相同且适宜。"},{"ep":"bx1-14","n":"BX1-14","p":3,"a":"p3","id":"vb4","src":"assets/audio/BX1-14/vb4.mp3","sec":7.632,"t":"除自变量外，其他因素都保持不变的实验叫对照实验，包括对照组和实验组。"},{"ep":"bx1-14","n":"BX1-14","p":3,"a":"p3","id":"vb5","src":"assets/audio/BX1-14/vb5.mp3","sec":9.24,"t":"解题方法：看题目“探究甲对乙的影响”——甲是自变量，乙是因变量；本实验的1号试管是对照组。"},{"ep":"bx1-14","n":"BX1-14","p":4,"a":"p4","id":"av1","src":"assets/audio/BX1-14/av1.mp3","sec":9.912,"t":"考点四，酶的作用原理。分子从常态转变为容易发生化学反应的活跃状态所需要的能量，叫活化能。"},{"ep":"bx1-14","n":"BX1-14","p":4,"a":"p4","id":"av2","src":"assets/audio/BX1-14/av2.mp3","sec":7.224,"t":"加热是为反应提供能量；而酶和无机催化剂都是降低化学反应的活化能。"},{"ep":"bx1-14","n":"BX1-14","p":4,"a":"p4","id":"av3","src":"assets/audio/BX1-14/av3.mp3","sec":7.056,"t":"同无机催化剂相比，酶降低活化能的作用更显著，所以催化效率更高。"},{"ep":"bx1-14","n":"BX1-14","p":4,"a":"p4","id":"av4","src":"assets/audio/BX1-14/av4.mp3","sec":7.104,"t":"易错：酶不为反应提供能量，也不改变反应的平衡点，只是加快反应速率。"},{"ep":"bx1-14","n":"BX1-14","p":5,"a":"p5","id":"dg1","src":"assets/audio/BX1-14/dg1.mp3","sec":9.216,"t":"考点五，活化能示意图。纵轴是能量，曲线最高点与反应物所处能量之差，就是活化能。"},{"ep":"bx1-14","n":"BX1-14","p":5,"a":"p5","id":"dg2","src":"assets/audio/BX1-14/dg2.mp3","sec":6.912,"t":"没有催化剂时活化能最大；无机催化剂降低一部分；酶降低得更多。"},{"ep":"bx1-14","n":"BX1-14","p":5,"a":"p5","id":"dg3","src":"assets/audio/BX1-14/dg3.mp3","sec":10.008,"t":"解题方法：酶降低的活化能 = 无催化剂时的活化能 − 有酶时的活化能，也就是两条曲线最高点之差。"},{"ep":"bx1-14","n":"BX1-14","p":6,"a":"p6","id":"hs1","src":"assets/audio/BX1-14/hs1.mp3","sec":14.976,"t":"考点六，关于酶本质的探索。巴斯德认为发酵与活细胞有关；李比希认为引起发酵的是酵母菌细胞中的某些物质，但只有在细胞死亡并裂解后才能发挥作用。"},{"ep":"bx1-14","n":"BX1-14","p":6,"a":"p6","id":"hs2","src":"assets/audio/BX1-14/hs2.mp3","sec":10.416,"t":"毕希纳把酵母菌细胞研磨、过滤得到提取液，提取液也能使糖液变成酒，他把其中引起发酵的物质称为酿酶。"},{"ep":"bx1-14","n":"BX1-14","p":6,"a":"p6","id":"hs3","src":"assets/audio/BX1-14/hs3.mp3","sec":6.36,"t":"萨姆纳从刀豆种子中提取到脲酶结晶，并证明脲酶是蛋白质。"},{"ep":"bx1-14","n":"BX1-14","p":6,"a":"p6","id":"hs4","src":"assets/audio/BX1-14/hs4.mp3","sec":7.368,"t":"20世纪80年代，切赫和奥尔特曼发现少数RNA也具有生物催化功能。"},{"ep":"bx1-14","n":"BX1-14","p":6,"a":"p6","id":"hs5","src":"assets/audio/BX1-14/hs5.mp3","sec":11.568,"t":"考法：判断各位科学家的结论。易错：毕希纳证明了酿酶离开活细胞也能起作用，证明酶是蛋白质的是萨姆纳。"},{"ep":"bx1-14","n":"BX1-14","p":7,"a":"p7","id":"cn1","src":"assets/audio/BX1-14/cn1.mp3","sec":10.68,"t":"考点七，酶的概念。酶是活细胞产生的、具有催化作用的有机物，其中绝大多数是蛋白质，少数是RNA。"},{"ep":"bx1-14","n":"BX1-14","p":7,"a":"p7","id":"cn2","src":"assets/audio/BX1-14/cn2.mp3","sec":4.728,"t":"所以酶的基本单位是氨基酸或核糖核苷酸。"},{"ep":"bx1-14","n":"BX1-14","p":7,"a":"p7","id":"cn3","src":"assets/audio/BX1-14/cn3.mp3","sec":9.84,"t":"易错：酶在细胞内外都能起作用，比如消化酶在消化道中起作用；酶只有催化作用，没有调节作用。"},{"ep":"bx1-14","n":"BX1-14","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-14/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-14","n":"BX1-14","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-14/rv2.mp3","sec":7.992,"t":"判断一？错，酶是降低活化能。判断二？错，加热是提供能量。"},{"ep":"bx1-14","n":"BX1-14","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-14/rv3.mp3","sec":4.656,"t":"判断三？对。判断四？对。"},{"ep":"bx1-14","n":"BX1-14","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-14/rv4.mp3","sec":9.12,"t":"判断五？错，酶在细胞内外都能起作用。判断六？错，少数酶是RNA。"},{"ep":"bx1-14","n":"BX1-14","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-14/rv5.mp3","sec":6.72,"t":"七个考点串成一条线：酶不供能，只降低活化能。我们下期再见！"},{"ep":"bx1-15","n":"BX1-15","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-15/in1.mp3","sec":7.344,"t":"同学们好！这节课梳理人教版必修一第五章第一节的下半部分——酶的特性。"},{"ep":"bx1-15","n":"BX1-15","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-15/in2.mp3","sec":8.736,"t":"高考常考酶特性的实验设计、温度和pH的影响曲线，以及实验材料和检测试剂的选择。"},{"ep":"bx1-15","n":"BX1-15","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-15/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-15","n":"BX1-15","p":1,"a":"p1","id":"ef1","src":"assets/audio/BX1-15/ef1.mp3","sec":8.424,"t":"考点一，高效性。酶的催化效率大约是无机催化剂的107～1013倍。"},{"ep":"bx1-15","n":"BX1-15","p":1,"a":"p1","id":"ef2","src":"assets/audio/BX1-15/ef2.mp3","sec":7.392,"t":"证明高效性，要用酶和无机催化剂作对照，比如过氧化氢酶和FeCl3。"},{"ep":"bx1-15","n":"BX1-15","p":1,"a":"p1","id":"ef3","src":"assets/audio/BX1-15/ef3.mp3","sec":8.928,"t":"易错：酶与无机催化剂比较才体现高效性；酶与不加催化剂比较，只能说明酶有催化作用。"},{"ep":"bx1-15","n":"BX1-15","p":2,"a":"p2","id":"sp1","src":"assets/audio/BX1-15/sp1.mp3","sec":6.312,"t":"考点二，专一性。每一种酶只能催化一种或一类化学反应。"},{"ep":"bx1-15","n":"BX1-15","p":2,"a":"p2","id":"sp2","src":"assets/audio/BX1-15/sp2.mp3","sec":10.128,"t":"实验：用淀粉酶分别作用于淀粉和蔗糖，再用斐林试剂检测——淀粉组出现砖红色沉淀，蔗糖组没有。"},{"ep":"bx1-15","n":"BX1-15","p":2,"a":"p2","id":"sp3","src":"assets/audio/BX1-15/sp3.mp3","sec":7.176,"t":"易错：这个实验不能用碘液检测，因为碘液无法检测蔗糖是否被水解。"},{"ep":"bx1-15","n":"BX1-15","p":2,"a":"p2","id":"sp4","src":"assets/audio/BX1-15/sp4.mp3","sec":7.776,"t":"解题方法：验证专一性，可以同一种酶、不同底物，也可以同一种底物、不同的酶。"},{"ep":"bx1-15","n":"BX1-15","p":3,"a":"p3","id":"md1","src":"assets/audio/BX1-15/md1.mp3","sec":9.744,"t":"考点三，酶的作用条件较温和。酶需要适宜的温度和pH，在最适温度和最适pH下活性最高。"},{"ep":"bx1-15","n":"BX1-15","p":3,"a":"p3","id":"md2","src":"assets/audio/BX1-15/md2.mp3","sec":7.152,"t":"过酸、过碱或温度过高，会使酶的空间结构遭到破坏，使酶永久失活。"},{"ep":"bx1-15","n":"BX1-15","p":3,"a":"p3","id":"md3","src":"assets/audio/BX1-15/md3.mp3","sec":7.008,"t":"低温只是抑制酶的活性，酶的空间结构稳定，温度适宜时活性可以恢复。"},{"ep":"bx1-15","n":"BX1-15","p":3,"a":"p3","id":"md4","src":"assets/audio/BX1-15/md4.mp3","sec":6.744,"t":"考法：酶适宜在低温下保存。易错：低温不会使酶变性失活。"},{"ep":"bx1-15","n":"BX1-15","p":4,"a":"p4","id":"tm1","src":"assets/audio/BX1-15/tm1.mp3","sec":10.776,"t":"考点四，温度对酶活性的影响。在一定范围内，随温度升高，酶活性增强；超过最适温度后，酶活性降低。"},{"ep":"bx1-15","n":"BX1-15","p":4,"a":"p4","id":"tm2","src":"assets/audio/BX1-15/tm2.mp3","sec":7.488,"t":"低温时酶活性很低，但没有失活；温度过高，酶会变性失活，曲线降到零。"},{"ep":"bx1-15","n":"BX1-15","p":4,"a":"p4","id":"tm3","src":"assets/audio/BX1-15/tm3.mp3","sec":11.952,"t":"解题方法：同一活性对应两个温度时，高温一侧的酶已部分失活，降回最适温度，活性也不能恢复到最高；低温一侧可以恢复。"},{"ep":"bx1-15","n":"BX1-15","p":5,"a":"p5","id":"ph1","src":"assets/audio/BX1-15/ph1.mp3","sec":9.528,"t":"考点五，pH对酶活性的影响。每种酶都有最适pH，偏离最适pH，酶活性都会降低。"},{"ep":"bx1-15","n":"BX1-15","p":5,"a":"p5","id":"ph2","src":"assets/audio/BX1-15/ph2.mp3","sec":6.144,"t":"过酸、过碱都会使酶变性失活，所以曲线两端都降到零。"},{"ep":"bx1-15","n":"BX1-15","p":5,"a":"p5","id":"ph3","src":"assets/audio/BX1-15/ph3.mp3","sec":11.016,"t":"不同的酶最适pH不同：胃蛋白酶的最适pH约为1.5，动物体内的酶最适pH大多在6.5～8.0之间。"},{"ep":"bx1-15","n":"BX1-15","p":5,"a":"p5","id":"ph4","src":"assets/audio/BX1-15/ph4.mp3","sec":8.664,"t":"易错：pH从过碱调回最适，酶活性不能恢复；改变温度不影响酶的最适pH。"},{"ep":"bx1-15","n":"BX1-15","p":6,"a":"p6","id":"te1","src":"assets/audio/BX1-15/te1.mp3","sec":8.448,"t":"考点六，探究温度对酶活性的影响。常用淀粉和淀粉酶，用碘液检测淀粉的剩余量。"},{"ep":"bx1-15","n":"BX1-15","p":6,"a":"p6","id":"te2","src":"assets/audio/BX1-15/te2.mp3","sec":8.496,"t":"要先把酶和底物分别保温到相应温度，再混合，保证反应一开始就在设定的温度下进行。"},{"ep":"bx1-15","n":"BX1-15","p":6,"a":"p6","id":"te3","src":"assets/audio/BX1-15/te3.mp3","sec":11.112,"t":"易错：不能用斐林试剂检测，因为它要水浴加热，会改变温度；也不能用过氧化氢酶，因为H2O2受热本身会分解。"},{"ep":"bx1-15","n":"BX1-15","p":7,"a":"p7","id":"pe1","src":"assets/audio/BX1-15/pe1.mp3","sec":9.768,"t":"考点七，探究pH对酶活性的影响。常用过氧化氢和过氧化氢酶，观察气泡产生的多少。"},{"ep":"bx1-15","n":"BX1-15","p":7,"a":"p7","id":"pe2","src":"assets/audio/BX1-15/pe2.mp3","sec":4.92,"t":"要先用不同pH的缓冲液处理酶，再与底物混合。"},{"ep":"bx1-15","n":"BX1-15","p":7,"a":"p7","id":"pe3","src":"assets/audio/BX1-15/pe3.mp3","sec":8.184,"t":"易错：一般不用淀粉和淀粉酶，因为淀粉在酸性条件下也会水解，干扰实验结果。"},{"ep":"bx1-15","n":"BX1-15","p":8,"a":"p8","id":"sb1","src":"assets/audio/BX1-15/sb1.mp3","sec":10.464,"t":"考点八，底物浓度和酶浓度的影响。底物浓度增大，反应速率先增大，后来受酶浓度限制，不再增加。"},{"ep":"bx1-15","n":"BX1-15","p":8,"a":"p8","id":"sb2","src":"assets/audio/BX1-15/sb2.mp3","sec":8.088,"t":"在底物充足时，反应速率与酶浓度成正比；酶浓度提高，曲线的平台也随之升高。"},{"ep":"bx1-15","n":"BX1-15","p":8,"a":"p8","id":"sb3","src":"assets/audio/BX1-15/sb3.mp3","sec":10.656,"t":"解题方法：曲线拐点之前，限制因素是横坐标表示的因素；拐点之后，限制因素是其他因素，比如酶的数量。"},{"ep":"bx1-15","n":"BX1-15","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-15/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-15","n":"BX1-15","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-15/rv2.mp3","sec":9.264,"t":"判断一？错，要和无机催化剂对照。判断二？错，碘液检测不了蔗糖是否水解。"},{"ep":"bx1-15","n":"BX1-15","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-15/rv3.mp3","sec":8.352,"t":"判断三？错，低温只是抑制。判断四？错，H2O2受热会分解。"},{"ep":"bx1-15","n":"BX1-15","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-15/rv4.mp3","sec":4.68,"t":"判断五？对。判断六？对。"},{"ep":"bx1-15","n":"BX1-15","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-15/rv5.mp3","sec":8.616,"t":"八个考点串成一条线：高温、过酸、过碱使酶失活，低温只是抑制。我们下期再见！"},{"ep":"bx1-16","n":"BX1-16","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-16/in1.mp3","sec":7.896,"t":"同学们好！这节课梳理人教版必修一第五章第二节——细胞的能量“货币”ATP。"},{"ep":"bx1-16","n":"BX1-16","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-16/in2.mp3","sec":7.8,"t":"高考常考ATP的结构、ATP与ADP的相互转化，以及吸能反应和放能反应。"},{"ep":"bx1-16","n":"BX1-16","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-16/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-16","n":"BX1-16","p":1,"a":"p1","id":"st1","src":"assets/audio/BX1-16/st1.mp3","sec":9.984,"t":"考点一，ATP的结构。ATP是腺苷三磷酸的英文名称缩写，结构简式是A—P~P~P。"},{"ep":"bx1-16","n":"BX1-16","p":1,"a":"p1","id":"st2","src":"assets/audio/BX1-16/st2.mp3","sec":6.432,"t":"其中A代表腺苷，由腺嘌呤和核糖组成；P代表磷酸基团。"},{"ep":"bx1-16","n":"BX1-16","p":1,"a":"p1","id":"st3","src":"assets/audio/BX1-16/st3.mp3","sec":4.968,"t":"ATP由C、H、O、N、P五种元素组成。"},{"ep":"bx1-16","n":"BX1-16","p":1,"a":"p1","id":"st4","src":"assets/audio/BX1-16/st4.mp3","sec":8.088,"t":"易错：ATP中的“A”是腺苷，而DNA和RNA中的“A”是腺嘌呤，两者不同。"},{"ep":"bx1-16","n":"BX1-16","p":2,"a":"p2","id":"bd1","src":"assets/audio/BX1-16/bd1.mp3","sec":11.976,"t":"考点二，特殊的化学键。ATP中相邻磷酸基团之间的化学键是一种特殊的化学键，用“~”表示，一个ATP中有2个。"},{"ep":"bx1-16","n":"BX1-16","p":2,"a":"p2","id":"bd2","src":"assets/audio/BX1-16/bd2.mp3","sec":8.856,"t":"磷酸基团都带负电荷而相互排斥，使这种化学键不稳定，末端磷酸基团有较高的转移势能。"},{"ep":"bx1-16","n":"BX1-16","p":2,"a":"p2","id":"bd3","src":"assets/audio/BX1-16/bd3.mp3","sec":6.144,"t":"ATP水解时，远离A的那个特殊化学键容易断裂，释放能量。"},{"ep":"bx1-16","n":"BX1-16","p":2,"a":"p2","id":"bd4","src":"assets/audio/BX1-16/bd4.mp3","sec":8.688,"t":"易错：一个ATP有2个特殊化学键、3个磷酸基团；水解时一般只断裂末端那一个。"},{"ep":"bx1-16","n":"BX1-16","p":3,"a":"p3","id":"cv1","src":"assets/audio/BX1-16/cv1.mp3","sec":12.528,"t":"考点三，ATP与ADP的相互转化。ATP在酶的作用下水解，远离A的特殊化学键断裂，形成ADP和Pi，释放能量。"},{"ep":"bx1-16","n":"BX1-16","p":3,"a":"p3","id":"cv2","src":"assets/audio/BX1-16/cv2.mp3","sec":6.624,"t":"ADP在酶的作用下接受能量，与Pi结合，重新形成ATP。"},{"ep":"bx1-16","n":"BX1-16","p":3,"a":"p3","id":"cv3","src":"assets/audio/BX1-16/cv3.mp3","sec":5.136,"t":"这种转化时刻不停地发生，并且处于动态平衡之中。"},{"ep":"bx1-16","n":"BX1-16","p":3,"a":"p3","id":"cv4","src":"assets/audio/BX1-16/cv4.mp3","sec":7.488,"t":"易错：这种转化不是可逆反应，因为两个方向的酶不同、能量来源和去路不同。"},{"ep":"bx1-16","n":"BX1-16","p":4,"a":"p4","id":"sr1","src":"assets/audio/BX1-16/sr1.mp3","sec":9.912,"t":"考点四，合成ATP的能量来源。对于动物、人、真菌和大多数细菌来说，能量来自细胞呼吸。"},{"ep":"bx1-16","n":"BX1-16","p":4,"a":"p4","id":"sr2","src":"assets/audio/BX1-16/sr2.mp3","sec":5.328,"t":"对于绿色植物来说，能量来自细胞呼吸和光合作用。"},{"ep":"bx1-16","n":"BX1-16","p":4,"a":"p4","id":"sr3","src":"assets/audio/BX1-16/sr3.mp3","sec":8.28,"t":"所以合成ATP的场所：动物细胞是细胞质基质和线粒体；植物细胞还有叶绿体。"},{"ep":"bx1-16","n":"BX1-16","p":4,"a":"p4","id":"sr4","src":"assets/audio/BX1-16/sr4.mp3","sec":8.04,"t":"易错：叶绿体光反应产生的ATP，主要用于暗反应，一般不用于细胞的其他生命活动。"},{"ep":"bx1-16","n":"BX1-16","p":5,"a":"p5","id":"rx1","src":"assets/audio/BX1-16/rx1.mp3","sec":10.536,"t":"考点五，ATP的利用。许多吸能反应与ATP水解相联系，比如蛋白质的合成、主动运输、肌肉收缩。"},{"ep":"bx1-16","n":"BX1-16","p":5,"a":"p5","id":"rx2","src":"assets/audio/BX1-16/rx2.mp3","sec":8.928,"t":"许多放能反应与ATP的合成相联系，释放的能量储存在ATP中，比如葡萄糖的氧化分解。"},{"ep":"bx1-16","n":"BX1-16","p":5,"a":"p5","id":"rx3","src":"assets/audio/BX1-16/rx3.mp3","sec":9.048,"t":"能量通过ATP分子在吸能反应和放能反应之间流通，所以ATP被称为细胞的能量“货币”。"},{"ep":"bx1-16","n":"BX1-16","p":5,"a":"p5","id":"rx4","src":"assets/audio/BX1-16/rx4.mp3","sec":8.496,"t":"解题方法：看反应耗能还是放能——耗能的伴随ATP水解，放能的伴随ATP合成。"},{"ep":"bx1-16","n":"BX1-16","p":6,"a":"p6","id":"tp1","src":"assets/audio/BX1-16/tp1.mp3","sec":8.136,"t":"考点六，易错辨析。ATP在细胞中含量很少，但与ADP的转化非常迅速。"},{"ep":"bx1-16","n":"BX1-16","p":6,"a":"p6","id":"tp2","src":"assets/audio/BX1-16/tp2.mp3","sec":8.28,"t":"ATP脱去两个磷酸基团后，就是腺嘌呤核糖核苷酸，是组成RNA的基本单位之一。"},{"ep":"bx1-16","n":"BX1-16","p":6,"a":"p6","id":"tp3","src":"assets/audio/BX1-16/tp3.mp3","sec":8.736,"t":"安静和运动时，细胞中ATP的含量都相对稳定，变化的是ATP与ADP的转化速率。"},{"ep":"bx1-16","n":"BX1-16","p":6,"a":"p6","id":"tp4","src":"assets/audio/BX1-16/tp4.mp3","sec":7.368,"t":"解题方法：看到“ATP含量大量增加”“ATP大量储存”这类说法，一般是错的。"},{"ep":"bx1-16","n":"BX1-16","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-16/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-16","n":"BX1-16","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-16/rv2.mp3","sec":6.864,"t":"判断一？错，A代表腺苷。判断二？错，只有2个。"},{"ep":"bx1-16","n":"BX1-16","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-16/rv3.mp3","sec":6.0,"t":"判断三？错，不是可逆反应。判断四？对。"},{"ep":"bx1-16","n":"BX1-16","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-16/rv4.mp3","sec":6.696,"t":"判断五？错，ATP含量相对稳定。判断六？对。"},{"ep":"bx1-16","n":"BX1-16","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-16/rv5.mp3","sec":9.168,"t":"六个考点串成一条线：ATP含量少、转化快，连接吸能反应和放能反应。我们下期再见！"},{"ep":"bx1-17","n":"BX1-17","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-17/in1.mp3","sec":10.008,"t":"同学们好！这节课梳理人教版必修一第五章第三节的上半部分——探究酵母菌细胞呼吸的方式和有氧呼吸。"},{"ep":"bx1-17","n":"BX1-17","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-17/in2.mp3","sec":7.296,"t":"高考常考实验装置和产物检测，以及有氧呼吸三个阶段的场所和物质变化。"},{"ep":"bx1-17","n":"BX1-17","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-17/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-17","n":"BX1-17","p":1,"a":"p1","id":"dv1","src":"assets/audio/BX1-17/dv1.mp3","sec":9.312,"t":"考点一，探究酵母菌细胞呼吸的方式。酵母菌是兼性厌氧菌，有氧和无氧条件下都能生存。"},{"ep":"bx1-17","n":"BX1-17","p":1,"a":"p1","id":"dv2","src":"assets/audio/BX1-17/dv2.mp3","sec":10.68,"t":"有氧装置：空气先通过质量分数为10%的NaOH溶液，再通入酵母菌培养液，最后连接澄清石灰水。"},{"ep":"bx1-17","n":"BX1-17","p":1,"a":"p1","id":"dv3","src":"assets/audio/BX1-17/dv3.mp3","sec":9.768,"t":"无氧装置：酵母菌培养液封口放置一段时间后，再连通澄清石灰水，目的是消耗掉瓶中原有的O2。"},{"ep":"bx1-17","n":"BX1-17","p":1,"a":"p1","id":"dv4","src":"assets/audio/BX1-17/dv4.mp3","sec":12.216,"t":"解题方法：NaOH的作用是吸收空气中的CO2，排除干扰；无氧组先放置，保证进入石灰水的CO2都来自无氧呼吸。"},{"ep":"bx1-17","n":"BX1-17","p":2,"a":"p2","id":"dt1","src":"assets/audio/BX1-17/dt1.mp3","sec":10.368,"t":"考点二，产物的检测。CO2使澄清石灰水变浑浊，也可使溴麝香草酚蓝溶液由蓝变绿再变黄。"},{"ep":"bx1-17","n":"BX1-17","p":2,"a":"p2","id":"dt2","src":"assets/audio/BX1-17/dt2.mp3","sec":9.312,"t":"根据石灰水的浑浊程度，或者溴麝香草酚蓝溶液变黄所需的时间，可以判断CO2产生的多少。"},{"ep":"bx1-17","n":"BX1-17","p":2,"a":"p2","id":"dt3","src":"assets/audio/BX1-17/dt3.mp3","sec":6.264,"t":"酒精在酸性条件下，与橙色的重铬酸钾溶液反应，变成灰绿色。"},{"ep":"bx1-17","n":"BX1-17","p":2,"a":"p2","id":"dt4","src":"assets/audio/BX1-17/dt4.mp3","sec":9.528,"t":"易错：葡萄糖也能与酸性重铬酸钾反应，所以要适当延长培养时间，耗尽葡萄糖后再检测酒精。"},{"ep":"bx1-17","n":"BX1-17","p":3,"a":"p3","id":"ct1","src":"assets/audio/BX1-17/ct1.mp3","sec":11.088,"t":"考点三，科学方法——对比实验。设置两个或两个以上的实验组，通过比较结果，探究某种因素对实验对象的影响。"},{"ep":"bx1-17","n":"BX1-17","p":3,"a":"p3","id":"ct2","src":"assets/audio/BX1-17/ct2.mp3","sec":5.328,"t":"本实验中，有氧组和无氧组都是实验组，相互对比。"},{"ep":"bx1-17","n":"BX1-17","p":3,"a":"p3","id":"ct3","src":"assets/audio/BX1-17/ct3.mp3","sec":8.544,"t":"易错：对比实验没有单独的空白对照组；鲁宾和卡门的同位素标记实验，也是对比实验。"},{"ep":"bx1-17","n":"BX1-17","p":4,"a":"p4","id":"tt1","src":"assets/audio/BX1-17/tt1.mp3","sec":12.936,"t":"考点四，有氧呼吸。细胞在O2的参与下，把葡萄糖等有机物彻底氧化分解，产生CO2和水，释放能量，生成大量ATP。"},{"ep":"bx1-17","n":"BX1-17","p":4,"a":"p4","id":"tt2","src":"assets/audio/BX1-17/tt2.mp3","sec":11.184,"t":"总反应式：葡萄糖、水和O2，在酶的作用下，生成CO2、水和能量。"},{"ep":"bx1-17","n":"BX1-17","p":4,"a":"p4","id":"tt3","src":"assets/audio/BX1-17/tt3.mp3","sec":11.88,"t":"1 mol葡萄糖彻底氧化分解，释放2870 kJ能量，约977.28 kJ储存在ATP中，其余以热能形式散失。"},{"ep":"bx1-17","n":"BX1-17","p":4,"a":"p4","id":"tt4","src":"assets/audio/BX1-17/tt4.mp3","sec":8.112,"t":"解题方法：写反应式时两边都有水，箭头上注明“酶”，最后写“能量”而不是ATP。"},{"ep":"bx1-17","n":"BX1-17","p":5,"a":"p5","id":"sg1","src":"assets/audio/BX1-17/sg1.mp3","sec":12.648,"t":"考点五，有氧呼吸的三个阶段。第一阶段在细胞质基质：1分子葡萄糖分解成2分子丙酮酸，产生少量[H]，释放少量能量。"},{"ep":"bx1-17","n":"BX1-17","p":5,"a":"p5","id":"sg2","src":"assets/audio/BX1-17/sg2.mp3","sec":8.4,"t":"第二阶段在线粒体基质：丙酮酸和水彻底分解成CO2和[H]，释放少量能量。"},{"ep":"bx1-17","n":"BX1-17","p":5,"a":"p5","id":"sg3","src":"assets/audio/BX1-17/sg3.mp3","sec":8.616,"t":"第三阶段在线粒体内膜：前两个阶段产生的[H]与O2结合生成水，释放大量能量。"},{"ep":"bx1-17","n":"BX1-17","p":5,"a":"p5","id":"sg4","src":"assets/audio/BX1-17/sg4.mp3","sec":9.768,"t":"解题方法：水在第二阶段消耗、第三阶段生成；O2只在第三阶段参与；CO2在第二阶段产生。"},{"ep":"bx1-17","n":"BX1-17","p":6,"a":"p6","id":"en1","src":"assets/audio/BX1-17/en1.mp3","sec":7.896,"t":"考点六，能量与元素去向。三个阶段都能产生ATP，第三阶段产生的最多。"},{"ep":"bx1-17","n":"BX1-17","p":6,"a":"p6","id":"en2","src":"assets/audio/BX1-17/en2.mp3","sec":10.584,"t":"用18O追踪：葡萄糖中的O进入CO2；O2中的O进入生成的水；反应物水中的O也进入CO2。"},{"ep":"bx1-17","n":"BX1-17","p":6,"a":"p6","id":"en3","src":"assets/audio/BX1-17/en3.mp3","sec":5.592,"t":"解题方法：追踪元素时记住，O2中的氧只进入水。"},{"ep":"bx1-17","n":"BX1-17","p":7,"a":"p7","id":"tp1","src":"assets/audio/BX1-17/tp1.mp3","sec":9.84,"t":"考点七，易错辨析。线粒体不能直接分解葡萄糖，葡萄糖要先在细胞质基质中分解为丙酮酸。"},{"ep":"bx1-17","n":"BX1-17","p":7,"a":"p7","id":"tp2","src":"assets/audio/BX1-17/tp2.mp3","sec":9.648,"t":"原核生物没有线粒体，但有的也能进行有氧呼吸，比如醋酸菌、蓝细菌，它们含有与有氧呼吸有关的酶。"},{"ep":"bx1-17","n":"BX1-17","p":7,"a":"p7","id":"tp3","src":"assets/audio/BX1-17/tp3.mp3","sec":8.184,"t":"真核细胞也不一定都能有氧呼吸：哺乳动物成熟红细胞没有线粒体，只进行无氧呼吸。"},{"ep":"bx1-17","n":"BX1-17","p":7,"a":"p7","id":"tp4","src":"assets/audio/BX1-17/tp4.mp3","sec":8.664,"t":"解题方法：判断能否进行有氧呼吸，看有没有与有氧呼吸有关的酶，不能只看有没有线粒体。"},{"ep":"bx1-17","n":"BX1-17","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-17/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-17","n":"BX1-17","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-17/rv2.mp3","sec":7.344,"t":"判断一？错，吸收的是空气中的CO2。判断二？对。"},{"ep":"bx1-17","n":"BX1-17","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-17/rv3.mp3","sec":8.28,"t":"判断三？错，水在第二阶段参与。判断四？错，O2中的氧进入水。"},{"ep":"bx1-17","n":"BX1-17","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-17/rv4.mp3","sec":6.936,"t":"判断五？错，进入线粒体的是丙酮酸。判断六？对。"},{"ep":"bx1-17","n":"BX1-17","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-17/rv5.mp3","sec":7.536,"t":"七个考点串成一条线：水二耗三生，O2只在第三阶段。我们下期再见！"},{"ep":"bx1-18","n":"BX1-18","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-18/in1.mp3","sec":9.672,"t":"同学们好！这节课梳理人教版必修一第五章第三节的下半部分——无氧呼吸和细胞呼吸原理的应用。"},{"ep":"bx1-18","n":"BX1-18","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-18/in2.mp3","sec":8.016,"t":"高考常考根据气体变化判断呼吸方式、相关计算，以及影响因素和生产应用。"},{"ep":"bx1-18","n":"BX1-18","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-18/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-18","n":"BX1-18","p":1,"a":"p1","id":"pr1","src":"assets/audio/BX1-18/pr1.mp3","sec":6.72,"t":"考点一，无氧呼吸。无氧呼吸的两个阶段都在细胞质基质中进行。"},{"ep":"bx1-18","n":"BX1-18","p":1,"a":"p1","id":"pr2","src":"assets/audio/BX1-18/pr2.mp3","sec":9.528,"t":"第一阶段与有氧呼吸的第一阶段完全相同：葡萄糖分解为丙酮酸和少量[H]，释放少量能量。"},{"ep":"bx1-18","n":"BX1-18","p":1,"a":"p1","id":"pr3","src":"assets/audio/BX1-18/pr3.mp3","sec":10.08,"t":"第二阶段：丙酮酸在不同酶的催化下，分解成酒精和CO2，或者转化成乳酸；这一阶段不释放能量。"},{"ep":"bx1-18","n":"BX1-18","p":1,"a":"p1","id":"pr4","src":"assets/audio/BX1-18/pr4.mp3","sec":8.328,"t":"易错：无氧呼吸只在第一阶段释放少量能量，大部分能量还储存在酒精或乳酸中。"},{"ep":"bx1-18","n":"BX1-18","p":2,"a":"p2","id":"fm1","src":"assets/audio/BX1-18/fm1.mp3","sec":10.728,"t":"考点二，两种无氧呼吸。产生酒精的无氧呼吸：葡萄糖分解为酒精和CO2，如酵母菌、多数植物细胞。"},{"ep":"bx1-18","n":"BX1-18","p":2,"a":"p2","id":"fm2","src":"assets/audio/BX1-18/fm2.mp3","sec":11.328,"t":"产生乳酸的无氧呼吸：葡萄糖分解为乳酸，如乳酸菌、人和动物的骨骼肌细胞，以及马铃薯块茎、甜菜块根、玉米胚。"},{"ep":"bx1-18","n":"BX1-18","p":2,"a":"p2","id":"fm3","src":"assets/audio/BX1-18/fm3.mp3","sec":8.232,"t":"无氧呼吸释放的能量少，1 mol葡萄糖只有约61.08 kJ的能量储存在ATP中。"},{"ep":"bx1-18","n":"BX1-18","p":2,"a":"p2","id":"fm4","src":"assets/audio/BX1-18/fm4.mp3","sec":10.128,"t":"易错：人体骨骼肌无氧呼吸产生乳酸，不产生CO2，所以人体产生的CO2只来自有氧呼吸。"},{"ep":"bx1-18","n":"BX1-18","p":3,"a":"p3","id":"cm1","src":"assets/audio/BX1-18/cm1.mp3","sec":9.024,"t":"考点三，有氧呼吸与无氧呼吸的比较。条件：有氧呼吸需要O2，无氧呼吸不需要O2。"},{"ep":"bx1-18","n":"BX1-18","p":3,"a":"p3","id":"cm2","src":"assets/audio/BX1-18/cm2.mp3","sec":7.32,"t":"场所：有氧呼吸在细胞质基质和线粒体；无氧呼吸只在细胞质基质。"},{"ep":"bx1-18","n":"BX1-18","p":3,"a":"p3","id":"cm3","src":"assets/audio/BX1-18/cm3.mp3","sec":11.208,"t":"产物：有氧呼吸是CO2和水；无氧呼吸是酒精和CO2，或者乳酸。能量：有氧大量，无氧少量。"},{"ep":"bx1-18","n":"BX1-18","p":3,"a":"p3","id":"cm4","src":"assets/audio/BX1-18/cm4.mp3","sec":7.032,"t":"解题方法：两者第一阶段完全相同，实质都是分解有机物、释放能量。"},{"ep":"bx1-18","n":"BX1-18","p":4,"a":"p4","id":"jd1","src":"assets/audio/BX1-18/jd1.mp3","sec":11.688,"t":"考点四，根据气体变化判断呼吸方式，以葡萄糖为底物。只释放CO2、不吸收O2：只进行产酒精的无氧呼吸。"},{"ep":"bx1-18","n":"BX1-18","p":4,"a":"p4","id":"jd2","src":"assets/audio/BX1-18/jd2.mp3","sec":9.432,"t":"CO2释放量等于O2吸收量：只进行有氧呼吸，或有氧呼吸和产乳酸的无氧呼吸同时进行。"},{"ep":"bx1-18","n":"BX1-18","p":4,"a":"p4","id":"jd3","src":"assets/audio/BX1-18/jd3.mp3","sec":7.68,"t":"CO2释放量大于O2吸收量：有氧呼吸和产酒精的无氧呼吸同时进行。"},{"ep":"bx1-18","n":"BX1-18","p":4,"a":"p4","id":"jd4","src":"assets/audio/BX1-18/jd4.mp3","sec":8.04,"t":"既不吸收O2，也不释放CO2：只进行产乳酸的无氧呼吸，或者细胞已经死亡。"},{"ep":"bx1-18","n":"BX1-18","p":4,"a":"p4","id":"jd5","src":"assets/audio/BX1-18/jd5.mp3","sec":7.968,"t":"易错：以脂肪为底物时，O2消耗量大于CO2释放量，不能套用上面的结论。"},{"ep":"bx1-18","n":"BX1-18","p":5,"a":"p5","id":"ca1","src":"assets/audio/BX1-18/ca1.mp3","sec":9.216,"t":"考点五，相关计算。有氧呼吸：1分子葡萄糖消耗6分子O2，产生6分子CO2。"},{"ep":"bx1-18","n":"BX1-18","p":5,"a":"p5","id":"ca2","src":"assets/audio/BX1-18/ca2.mp3","sec":7.104,"t":"产酒精的无氧呼吸：1分子葡萄糖产生2分子CO2，不消耗O2。"},{"ep":"bx1-18","n":"BX1-18","p":5,"a":"p5","id":"ca3","src":"assets/audio/BX1-18/ca3.mp3","sec":12.84,"t":"例：酵母菌吸收O2 6 mol，释放CO2 10 mol：有氧呼吸消耗葡萄糖1 mol；无氧呼吸产生CO2 4 mol，消耗葡萄糖2 mol。"},{"ep":"bx1-18","n":"BX1-18","p":5,"a":"p5","id":"ca4","src":"assets/audio/BX1-18/ca4.mp3","sec":7.872,"t":"解题方法：先用O2吸收量算出有氧呼吸，再用剩下的CO2算无氧呼吸。"},{"ep":"bx1-18","n":"BX1-18","p":6,"a":"p6","id":"fc1","src":"assets/audio/BX1-18/fc1.mp3","sec":7.08,"t":"考点六，影响细胞呼吸的因素。温度主要通过影响呼吸酶的活性起作用。"},{"ep":"bx1-18","n":"BX1-18","p":6,"a":"p6","id":"fc2","src":"assets/audio/BX1-18/fc2.mp3","sec":13.152,"t":"O2浓度：为0时只进行无氧呼吸；随O2浓度增大，无氧呼吸受抑制，有氧呼吸增强；CO2释放总量最少时，有机物消耗最少。"},{"ep":"bx1-18","n":"BX1-18","p":6,"a":"p6","id":"fc3","src":"assets/audio/BX1-18/fc3.mp3","sec":9.384,"t":"水：一定范围内，自由水含量越高，细胞呼吸越旺盛；CO2浓度升高，会抑制细胞呼吸。"},{"ep":"bx1-18","n":"BX1-18","p":6,"a":"p6","id":"fc4","src":"assets/audio/BX1-18/fc4.mp3","sec":7.776,"t":"考法：储存果蔬选低温、低氧、适宜湿度；储存种子选低温、低氧、干燥。"},{"ep":"bx1-18","n":"BX1-18","p":7,"a":"p7","id":"ap1","src":"assets/audio/BX1-18/ap1.mp3","sec":10.176,"t":"考点七，细胞呼吸原理的应用。包扎伤口选用透气的消毒纱布，抑制破伤风芽孢杆菌等厌氧菌的繁殖。"},{"ep":"bx1-18","n":"BX1-18","p":7,"a":"p7","id":"ap2","src":"assets/audio/BX1-18/ap2.mp3","sec":8.28,"t":"酿酒先通气、后密封：先让酵母菌有氧呼吸、大量繁殖，再无氧呼吸、产生酒精。"},{"ep":"bx1-18","n":"BX1-18","p":7,"a":"p7","id":"ap3","src":"assets/audio/BX1-18/ap3.mp3","sec":11.28,"t":"土壤板结要及时松土透气，促进根的有氧呼吸，利于吸收无机盐；提倡慢跑等有氧运动，避免肌细胞产生大量乳酸。"},{"ep":"bx1-18","n":"BX1-18","p":7,"a":"p7","id":"ap4","src":"assets/audio/BX1-18/ap4.mp3","sec":7.152,"t":"易错：稻田要定期排水，防止根进行无氧呼吸产生酒精，导致烂根。"},{"ep":"bx1-18","n":"BX1-18","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-18/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-18","n":"BX1-18","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-18/rv2.mp3","sec":9.0,"t":"判断一？错，只有第一阶段释放能量。判断二？错，人无氧呼吸只产生乳酸。"},{"ep":"bx1-18","n":"BX1-18","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-18/rv3.mp3","sec":7.944,"t":"判断三？对。判断四？错，也可能同时进行产乳酸的无氧呼吸。"},{"ep":"bx1-18","n":"BX1-18","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-18/rv4.mp3","sec":6.288,"t":"判断五？对。判断六？错，是为了抑制厌氧菌。"},{"ep":"bx1-18","n":"BX1-18","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-18/rv5.mp3","sec":8.28,"t":"七个考点串成一条线：先用O2算有氧，剩下的CO2算无氧。我们下期再见！"},{"ep":"bx1-19","n":"BX1-19","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-19/in1.mp3","sec":8.52,"t":"同学们好！这节课梳理人教版必修一第五章第四节的第一部分——捕获光能的色素和结构。"},{"ep":"bx1-19","n":"BX1-19","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-19/in2.mp3","sec":8.112,"t":"高考常考色素提取和分离实验、色素带和异常结果分析，以及色素的吸收光谱。"},{"ep":"bx1-19","n":"BX1-19","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-19/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-19","n":"BX1-19","p":1,"a":"p1","id":"pc1","src":"assets/audio/BX1-19/pc1.mp3","sec":8.856,"t":"考点一，绿叶中色素的提取和分离。提取的原理：色素能够溶解在有机溶剂无水乙醇中。"},{"ep":"bx1-19","n":"BX1-19","p":1,"a":"p1","id":"pc2","src":"assets/audio/BX1-19/pc2.mp3","sec":9.648,"t":"分离的原理：不同色素在层析液中的溶解度不同，溶解度高的随层析液在滤纸上扩散得快，反之则慢。"},{"ep":"bx1-19","n":"BX1-19","p":1,"a":"p1","id":"pc3","src":"assets/audio/BX1-19/pc3.mp3","sec":7.488,"t":"易错：提取用无水乙醇，分离用层析液，别混；分离的方法叫纸层析法。"},{"ep":"bx1-19","n":"BX1-19","p":2,"a":"p2","id":"sp1","src":"assets/audio/BX1-19/sp1.mp3","sec":10.656,"t":"考点二，实验步骤。研磨时加入SiO2，有助于研磨充分；加入CaCO3，防止研磨中色素被破坏。"},{"ep":"bx1-19","n":"BX1-19","p":2,"a":"p2","id":"sp2","src":"assets/audio/BX1-19/sp2.mp3","sec":4.224,"t":"研磨后用单层尼龙布过滤，收集滤液。"},{"ep":"bx1-19","n":"BX1-19","p":2,"a":"p2","id":"sp3","src":"assets/audio/BX1-19/sp3.mp3","sec":7.224,"t":"画滤液细线要细、直、齐，待滤液干后再画一两次，使色素多而集中。"},{"ep":"bx1-19","n":"BX1-19","p":2,"a":"p2","id":"sp4","src":"assets/audio/BX1-19/sp4.mp3","sec":6.6,"t":"层析时，层析液不能没及滤液细线，否则色素会溶解到层析液中。"},{"ep":"bx1-19","n":"BX1-19","p":2,"a":"p2","id":"sp5","src":"assets/audio/BX1-19/sp5.mp3","sec":9.792,"t":"解题方法：一种试剂一个作用——SiO2助研磨，CaCO3护色素，无水乙醇溶色素，层析液分色素。"},{"ep":"bx1-19","n":"BX1-19","p":3,"a":"p3","id":"rs1","src":"assets/audio/BX1-19/rs1.mp3","sec":9.216,"t":"考点三，实验结果。滤纸条上从上到下依次是：胡萝卜素，橙黄色；叶黄素，黄色；"},{"ep":"bx1-19","n":"BX1-19","p":3,"a":"p3","id":"rs2","src":"assets/audio/BX1-19/rs2.mp3","sec":4.488,"t":"叶绿素a，蓝绿色；叶绿素b，黄绿色。"},{"ep":"bx1-19","n":"BX1-19","p":3,"a":"p3","id":"rs3","src":"assets/audio/BX1-19/rs3.mp3","sec":9.48,"t":"最宽的是叶绿素a，含量最多；最窄的是胡萝卜素；胡萝卜素在层析液中溶解度最高，扩散最快。"},{"ep":"bx1-19","n":"BX1-19","p":3,"a":"p3","id":"rs4","src":"assets/audio/BX1-19/rs4.mp3","sec":10.848,"t":"解题方法：顺序记“胡、黄、a、b”；宽度看含量：叶绿素a、叶绿素b、叶黄素、胡萝卜素依次减少。"},{"ep":"bx1-19","n":"BX1-19","p":4,"a":"p4","id":"ab1","src":"assets/audio/BX1-19/ab1.mp3","sec":12.12,"t":"考点四，异常结果分析。色素带颜色都很浅：可能是研磨不充分、未加SiO2、无水乙醇加得过多，或画线次数太少。"},{"ep":"bx1-19","n":"BX1-19","p":4,"a":"p4","id":"ab2","src":"assets/audio/BX1-19/ab2.mp3","sec":8.256,"t":"叶绿素带很窄甚至没有：可能是未加CaCO3，叶绿素被破坏；或者选用了发黄的叶片。"},{"ep":"bx1-19","n":"BX1-19","p":4,"a":"p4","id":"ab3","src":"assets/audio/BX1-19/ab3.mp3","sec":6.84,"t":"没有色素带：可能是层析液没及了滤液细线，或者用水代替了无水乙醇。"},{"ep":"bx1-19","n":"BX1-19","p":4,"a":"p4","id":"ab4","src":"assets/audio/BX1-19/ab4.mp3","sec":5.88,"t":"解题方法：对照每一步的作用，缺了哪一步，就出现哪种异常。"},{"ep":"bx1-19","n":"BX1-19","p":5,"a":"p5","id":"sc1","src":"assets/audio/BX1-19/sc1.mp3","sec":7.608,"t":"考点五，色素的吸收光谱。叶绿素a和叶绿素b主要吸收蓝紫光和红光。"},{"ep":"bx1-19","n":"BX1-19","p":5,"a":"p5","id":"sc2","src":"assets/audio/BX1-19/sc2.mp3","sec":5.736,"t":"胡萝卜素和叶黄素，也就是类胡萝卜素，主要吸收蓝紫光。"},{"ep":"bx1-19","n":"BX1-19","p":5,"a":"p5","id":"sc3","src":"assets/audio/BX1-19/sc3.mp3","sec":6.408,"t":"色素对绿光吸收最少，绿光被反射出来，所以叶片呈绿色。"},{"ep":"bx1-19","n":"BX1-19","p":5,"a":"p5","id":"sc4","src":"assets/audio/BX1-19/sc4.mp3","sec":8.256,"t":"考法：温室补光选红光或蓝紫光，不用绿光。易错：类胡萝卜素不吸收红光。"},{"ep":"bx1-19","n":"BX1-19","p":6,"a":"p6","id":"cl1","src":"assets/audio/BX1-19/cl1.mp3","sec":10.776,"t":"考点六，叶绿体的结构适于进行光合作用。叶绿体有双层膜，内部有许多基粒，每个基粒由类囊体堆叠而成。"},{"ep":"bx1-19","n":"BX1-19","p":6,"a":"p6","id":"cl2","src":"assets/audio/BX1-19/cl2.mp3","sec":4.848,"t":"吸收光能的四种色素，都分布在类囊体的薄膜上。"},{"ep":"bx1-19","n":"BX1-19","p":6,"a":"p6","id":"cl3","src":"assets/audio/BX1-19/cl3.mp3","sec":6.672,"t":"类囊体薄膜上和叶绿体基质中，含有许多进行光合作用所必需的酶。"},{"ep":"bx1-19","n":"BX1-19","p":6,"a":"p6","id":"cl4","src":"assets/audio/BX1-19/cl4.mp3","sec":7.464,"t":"解题方法：基粒和类囊体极大地扩展了受光面积，体现了结构与功能相适应。"},{"ep":"bx1-19","n":"BX1-19","p":7,"a":"p7","id":"eg1","src":"assets/audio/BX1-19/eg1.mp3","sec":10.704,"t":"考点七，恩格尔曼的实验。把载有水绵和需氧细菌的临时装片，放在没有空气的黑暗环境里，用极细的光束照射。"},{"ep":"bx1-19","n":"BX1-19","p":7,"a":"p7","id":"eg2","src":"assets/audio/BX1-19/eg2.mp3","sec":10.248,"t":"需氧细菌只向叶绿体被光束照射到的部位集中；如果完全暴露在光下，细菌就分布在叶绿体所有受光的部位。"},{"ep":"bx1-19","n":"BX1-19","p":7,"a":"p7","id":"eg3","src":"assets/audio/BX1-19/eg3.mp3","sec":9.24,"t":"结论：叶绿体能吸收光能用于光合作用放氧；结合其他证据，得出叶绿体是光合作用的场所。"},{"ep":"bx1-19","n":"BX1-19","p":7,"a":"p7","id":"eg4","src":"assets/audio/BX1-19/eg4.mp3","sec":7.2,"t":"他还用透过三棱镜的光照射水绵，发现细菌主要聚集在红光和蓝紫光区域。"},{"ep":"bx1-19","n":"BX1-19","p":7,"a":"p7","id":"eg5","src":"assets/audio/BX1-19/eg5.mp3","sec":10.32,"t":"解题方法：选水绵是因为它的叶绿体呈螺旋带状，便于观察；黑暗、无空气是为了排除光和氧气的干扰。"},{"ep":"bx1-19","n":"BX1-19","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-19/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-19","n":"BX1-19","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-19/rv2.mp3","sec":9.648,"t":"判断一？错，提取用无水乙醇，分离用层析液。判断二？错，助研磨的是SiO2。"},{"ep":"bx1-19","n":"BX1-19","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-19/rv3.mp3","sec":7.368,"t":"判断三？对。判断四？错，类胡萝卜素主要吸收蓝紫光。"},{"ep":"bx1-19","n":"BX1-19","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-19/rv4.mp3","sec":6.84,"t":"判断五？错，色素在类囊体薄膜上。判断六？对。"},{"ep":"bx1-19","n":"BX1-19","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-19/rv5.mp3","sec":7.368,"t":"七个考点串成一条线：从上到下，胡、黄、a、b。我们下期再见！"},{"ep":"bx1-20","n":"BX1-20","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-20/in1.mp3","sec":7.968,"t":"同学们好！这节课梳理人教版必修一第五章第四节的第二部分——光合作用的原理。"},{"ep":"bx1-20","n":"BX1-20","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-20/in2.mp3","sec":8.472,"t":"高考常考探索历程中的经典实验、光反应和暗反应，以及条件骤变时物质含量的变化。"},{"ep":"bx1-20","n":"BX1-20","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-20/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-20","n":"BX1-20","p":1,"a":"p1","id":"hs1","src":"assets/audio/BX1-20/hs1.mp3","sec":12.432,"t":"考点一，探索光合作用原理的实验。希尔发现，离体叶绿体悬浮液中加入铁盐等氧化剂，光照下能释放氧气，这叫希尔反应。"},{"ep":"bx1-20","n":"BX1-20","p":1,"a":"p1","id":"hs2","src":"assets/audio/BX1-20/hs2.mp3","sec":8.448,"t":"鲁宾和卡门用18O分别标记H2O和CO2，证明光合作用释放的氧气全部来自水。"},{"ep":"bx1-20","n":"BX1-20","p":1,"a":"p1","id":"hs3","src":"assets/audio/BX1-20/hs3.mp3","sec":8.088,"t":"阿尔农发现，光照下叶绿体可以合成ATP，并且这一过程总是与水的光解相伴随。"},{"ep":"bx1-20","n":"BX1-20","p":1,"a":"p1","id":"hs4","src":"assets/audio/BX1-20/hs4.mp3","sec":9.552,"t":"卡尔文用14C标记的CO2，探明了CO2中的碳转化为有机物中碳的途径，叫卡尔文循环。"},{"ep":"bx1-20","n":"BX1-20","p":1,"a":"p1","id":"hs5","src":"assets/audio/BX1-20/hs5.mp3","sec":6.264,"t":"易错：18O是稳定同位素，没有放射性；14C有放射性。"},{"ep":"bx1-20","n":"BX1-20","p":2,"a":"p2","id":"tt1","src":"assets/audio/BX1-20/tt1.mp3","sec":9.288,"t":"考点二，光合作用的总反应式：CO2和H2O，在光能和叶绿体的作用下，生成糖类和O2。"},{"ep":"bx1-20","n":"BX1-20","p":2,"a":"p2","id":"tt2","src":"assets/audio/BX1-20/tt2.mp3","sec":10.08,"t":"也就是绿色植物通过叶绿体，利用光能，把CO2和水转化成储存着能量的有机物，并且释放出O2。"},{"ep":"bx1-20","n":"BX1-20","p":2,"a":"p2","id":"tt3","src":"assets/audio/BX1-20/tt3.mp3","sec":7.056,"t":"解题方法：箭头上注明光能和叶绿体；产物O2中的氧全部来自水。"},{"ep":"bx1-20","n":"BX1-20","p":3,"a":"p3","id":"lt1","src":"assets/audio/BX1-20/lt1.mp3","sec":7.248,"t":"考点三，光反应。场所：类囊体薄膜；条件：光、色素和酶。"},{"ep":"bx1-20","n":"BX1-20","p":3,"a":"p3","id":"lt2","src":"assets/audio/BX1-20/lt2.mp3","sec":10.776,"t":"物质变化：水的光解，产生O2和H+；NADP+与H+结合形成NADPH；ADP和Pi形成ATP。"},{"ep":"bx1-20","n":"BX1-20","p":3,"a":"p3","id":"lt3","src":"assets/audio/BX1-20/lt3.mp3","sec":5.232,"t":"能量变化：光能转化为ATP和NADPH中的化学能。"},{"ep":"bx1-20","n":"BX1-20","p":3,"a":"p3","id":"lt4","src":"assets/audio/BX1-20/lt4.mp3","sec":8.112,"t":"易错：光反应产生的O2释放到外界或用于呼吸；ATP和NADPH则用于暗反应。"},{"ep":"bx1-20","n":"BX1-20","p":4,"a":"p4","id":"dk1","src":"assets/audio/BX1-20/dk1.mp3","sec":9.72,"t":"考点四，暗反应。场所：叶绿体基质；有光无光都能进行，但需要光反应提供的ATP和NADPH。"},{"ep":"bx1-20","n":"BX1-20","p":4,"a":"p4","id":"dk2","src":"assets/audio/BX1-20/dk2.mp3","sec":6.12,"t":"CO2的固定：CO2与C5结合，形成两个C3分子。"},{"ep":"bx1-20","n":"BX1-20","p":4,"a":"p4","id":"dk3","src":"assets/audio/BX1-20/dk3.mp3","sec":7.968,"t":"C3的还原：在ATP和NADPH的作用下，C3被还原为糖类，同时再生出C5。"},{"ep":"bx1-20","n":"BX1-20","p":4,"a":"p4","id":"dk4","src":"assets/audio/BX1-20/dk4.mp3","sec":7.728,"t":"能量变化：ATP和NADPH中的化学能，转化为储存在糖类等有机物中的化学能。"},{"ep":"bx1-20","n":"BX1-20","p":4,"a":"p4","id":"dk5","src":"assets/audio/BX1-20/dk5.mp3","sec":8.136,"t":"易错：暗反应不是只在黑暗中进行；没有光，光反应停止，暗反应也会很快停止。"},{"ep":"bx1-20","n":"BX1-20","p":5,"a":"p5","id":"lk1","src":"assets/audio/BX1-20/lk1.mp3","sec":12.264,"t":"考点五，光反应与暗反应的联系。光反应为暗反应提供ATP和NADPH；暗反应为光反应提供ADP、Pi和NADP+。"},{"ep":"bx1-20","n":"BX1-20","p":5,"a":"p5","id":"lk2","src":"assets/audio/BX1-20/lk2.mp3","sec":4.776,"t":"两者相互依存、紧密联系，是一个统一的整体。"},{"ep":"bx1-20","n":"BX1-20","p":5,"a":"p5","id":"lk3","src":"assets/audio/BX1-20/lk3.mp3","sec":10.992,"t":"解题方法：记住物质流向——ATP、NADPH从类囊体流向基质；ADP、Pi、NADP+从基质流回类囊体。"},{"ep":"bx1-20","n":"BX1-20","p":6,"a":"p6","id":"sd1","src":"assets/audio/BX1-20/sd1.mp3","sec":12.264,"t":"考点六，条件骤变时物质含量的变化。光照减弱：ATP和NADPH减少，C3的还原变慢，所以C3增加、C5减少。"},{"ep":"bx1-20","n":"BX1-20","p":6,"a":"p6","id":"sd2","src":"assets/audio/BX1-20/sd2.mp3","sec":10.104,"t":"CO2供应减少：CO2的固定变慢，C3减少、C5增加；ATP和NADPH消耗减少，含量增加。"},{"ep":"bx1-20","n":"BX1-20","p":6,"a":"p6","id":"sd3","src":"assets/audio/BX1-20/sd3.mp3","sec":10.248,"t":"解题方法：抓住C3和C5的来路和去路——条件改变只影响其中一条路，另一条暂时不变，就能推出增减。"},{"ep":"bx1-20","n":"BX1-20","p":7,"a":"p7","id":"ch1","src":"assets/audio/BX1-20/ch1.mp3","sec":11.496,"t":"考点七，化能合成作用。少数细菌利用体外环境中某些无机物氧化时释放的能量来制造有机物，叫化能合成作用。"},{"ep":"bx1-20","n":"BX1-20","p":7,"a":"p7","id":"ch2","src":"assets/audio/BX1-20/ch2.mp3","sec":10.992,"t":"例如硝化细菌，能将土壤中的氨氧化成亚硝酸，进而氧化成硝酸，利用释放的化学能，把CO2和水合成糖类。"},{"ep":"bx1-20","n":"BX1-20","p":7,"a":"p7","id":"ch3","src":"assets/audio/BX1-20/ch3.mp3","sec":11.592,"t":"能用无机物合成有机物的是自养生物，如绿色植物、硝化细菌；只能利用现成有机物的是异养生物，如人、动物、真菌。"},{"ep":"bx1-20","n":"BX1-20","p":7,"a":"p7","id":"ch4","src":"assets/audio/BX1-20/ch4.mp3","sec":8.952,"t":"易错：硝化细菌是自养生物，但利用的是化学能，不是光能；它是原核生物，没有叶绿体。"},{"ep":"bx1-20","n":"BX1-20","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-20/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-20","n":"BX1-20","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-20/rv2.mp3","sec":9.312,"t":"判断一？错，O2中的氧全部来自水。判断二？错，光反应在类囊体薄膜上。"},{"ep":"bx1-20","n":"BX1-20","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-20/rv3.mp3","sec":7.032,"t":"判断三？错，暗反应有光无光都能进行。判断四？对。"},{"ep":"bx1-20","n":"BX1-20","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-20/rv4.mp3","sec":6.192,"t":"判断五？对。判断六？错，利用的是化学能。"},{"ep":"bx1-20","n":"BX1-20","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-20/rv5.mp3","sec":7.8,"t":"七个考点串成一条线：看来路和去路，推C3、C5的增减。我们下期再见！"},{"ep":"bx1-21","n":"BX1-21","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-21/in1.mp3","sec":8.952,"t":"同学们好！这节课梳理人教版必修一第五章第四节的第三部分——影响光合作用的因素及应用。"},{"ep":"bx1-21","n":"BX1-21","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-21/in2.mp3","sec":8.184,"t":"高考常考光照强度、CO2浓度等因素的曲线分析，以及总光合与净光合的计算。"},{"ep":"bx1-21","n":"BX1-21","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-21/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-21","n":"BX1-21","p":1,"a":"p1","id":"it1","src":"assets/audio/BX1-21/it1.mp3","sec":8.088,"t":"考点一，光合作用强度。指植物在单位时间内通过光合作用制造糖类的数量。"},{"ep":"bx1-21","n":"BX1-21","p":1,"a":"p1","id":"it2","src":"assets/audio/BX1-21/it2.mp3","sec":10.488,"t":"可以用单位时间内原料的消耗量，如CO2的吸收量，或产物的生成量，如O2的释放量、有机物的积累量来表示。"},{"ep":"bx1-21","n":"BX1-21","p":1,"a":"p1","id":"it3","src":"assets/audio/BX1-21/it3.mp3","sec":9.384,"t":"易错：实际测得的CO2吸收量或O2释放量是净光合速率，因为同时还在进行呼吸作用。"},{"ep":"bx1-21","n":"BX1-21","p":2,"a":"p2","id":"dk1","src":"assets/audio/BX1-21/dk1.mp3","sec":12.264,"t":"考点二，探究光照强度对光合作用强度的影响。用打孔器打出圆形小叶片，用注射器抽出叶片内的气体，叶片沉到水底。"},{"ep":"bx1-21","n":"BX1-21","p":2,"a":"p2","id":"dk2","src":"assets/audio/BX1-21/dk2.mp3","sec":8.64,"t":"把小叶片放入富含CO2的清水中，用不同强度的光照射，比如调节光源与烧杯的距离。"},{"ep":"bx1-21","n":"BX1-21","p":2,"a":"p2","id":"dk3","src":"assets/audio/BX1-21/dk3.mp3","sec":7.992,"t":"光合作用产生O2，叶片会浮起；单位时间内浮起的叶片越多，光合作用越强。"},{"ep":"bx1-21","n":"BX1-21","p":2,"a":"p2","id":"dk4","src":"assets/audio/BX1-21/dk4.mp3","sec":10.344,"t":"解题方法：自变量是光照强度，因变量是叶片上浮的数量或时间；抽气是为了排除叶片内原有气体的干扰。"},{"ep":"bx1-21","n":"BX1-21","p":3,"a":"p3","id":"lc1","src":"assets/audio/BX1-21/lc1.mp3","sec":10.8,"t":"考点三，光照强度的影响曲线。纵轴是CO2吸收量，光照为0时只进行呼吸作用，曲线在横轴以下。"},{"ep":"bx1-21","n":"BX1-21","p":3,"a":"p3","id":"lc2","src":"assets/audio/BX1-21/lc2.mp3","sec":5.232,"t":"光合速率等于呼吸速率时的光照强度，叫光补偿点。"},{"ep":"bx1-21","n":"BX1-21","p":3,"a":"p3","id":"lc3","src":"assets/audio/BX1-21/lc3.mp3","sec":7.368,"t":"光照增强到一定程度后，光合速率不再增加，这时的光照强度叫光饱和点。"},{"ep":"bx1-21","n":"BX1-21","p":3,"a":"p3","id":"lc4","src":"assets/audio/BX1-21/lc4.mp3","sec":12.168,"t":"考法：阴生植物的光补偿点和光饱和点都比阳生植物低。易错：光补偿点时，叶肉细胞的光合速率大于它自身的呼吸速率。"},{"ep":"bx1-21","n":"BX1-21","p":4,"a":"p4","id":"gn1","src":"assets/audio/BX1-21/gn1.mp3","sec":8.424,"t":"考点四，总光合速率与净光合速率。总光合速率 = 净光合速率 + 呼吸速率。"},{"ep":"bx1-21","n":"BX1-21","p":4,"a":"p4","id":"gn2","src":"assets/audio/BX1-21/gn2.mp3","sec":12.048,"t":"表示总光合的词：产生、制造O2或有机物，固定CO2；表示净光合的词：释放O2、吸收CO2、积累有机物。"},{"ep":"bx1-21","n":"BX1-21","p":4,"a":"p4","id":"gn3","src":"assets/audio/BX1-21/gn3.mp3","sec":4.68,"t":"黑暗中测得的CO2释放量，就是呼吸速率。"},{"ep":"bx1-21","n":"BX1-21","p":4,"a":"p4","id":"gn4","src":"assets/audio/BX1-21/gn4.mp3","sec":8.712,"t":"解题方法：先看关键词判断是总还是净；植物能否生长，看净光合速率是否大于0。"},{"ep":"bx1-21","n":"BX1-21","p":5,"a":"p5","id":"cc1","src":"assets/audio/BX1-21/cc1.mp3","sec":11.976,"t":"考点五，CO2浓度的影响。一定范围内，光合作用强度随CO2浓度增大而增大，达到CO2饱和点后不再增加。"},{"ep":"bx1-21","n":"BX1-21","p":5,"a":"p5","id":"cc2","src":"assets/audio/BX1-21/cc2.mp3","sec":9.6,"t":"CO2浓度过低时，光合速率小于呼吸速率；两者相等时的CO2浓度，叫CO2补偿点。"},{"ep":"bx1-21","n":"BX1-21","p":5,"a":"p5","id":"cc3","src":"assets/audio/BX1-21/cc3.mp3","sec":8.952,"t":"考法：温室中增施有机肥，微生物分解有机物产生CO2；也可以通风补充CO2。"},{"ep":"bx1-21","n":"BX1-21","p":6,"a":"p6","id":"ot1","src":"assets/audio/BX1-21/ot1.mp3","sec":9.288,"t":"考点六，温度、水和矿质元素。温度通过影响酶的活性影响光合作用，曲线先升后降。"},{"ep":"bx1-21","n":"BX1-21","p":6,"a":"p6","id":"ot2","src":"assets/audio/BX1-21/ot2.mp3","sec":6.384,"t":"缺水时叶片气孔关闭，CO2吸收减少，光合作用减弱。"},{"ep":"bx1-21","n":"BX1-21","p":6,"a":"p6","id":"ot3","src":"assets/audio/BX1-21/ot3.mp3","sec":7.464,"t":"矿质元素：如Mg是叶绿素的组成成分，N是酶、ATP、NADPH的组成元素。"},{"ep":"bx1-21","n":"BX1-21","p":6,"a":"p6","id":"ot4","src":"assets/audio/BX1-21/ot4.mp3","sec":10.152,"t":"解题方法：多因素曲线中，上升段的限制因素是横坐标所示因素；到达平台后，限制因素是其他因素。"},{"ep":"bx1-21","n":"BX1-21","p":7,"a":"p7","id":"cv1","src":"assets/audio/BX1-21/cv1.mp3","sec":13.608,"t":"考点七，两类典型曲线。夏季晴天中午，温度高、蒸腾作用强，气孔部分关闭，CO2吸收减少，光合速率下降，出现“午休”现象。"},{"ep":"bx1-21","n":"BX1-21","p":7,"a":"p7","id":"cv2","src":"assets/audio/BX1-21/cv2.mp3","sec":9.312,"t":"密闭容器中一昼夜的CO2浓度：曲线的最高点和最低点，对应光合速率等于呼吸速率的时刻。"},{"ep":"bx1-21","n":"BX1-21","p":7,"a":"p7","id":"cv3","src":"assets/audio/BX1-21/cv3.mp3","sec":10.464,"t":"最高点之前，呼吸大于光合，CO2浓度上升；之后光合大于呼吸，CO2浓度下降，直到最低点。"},{"ep":"bx1-21","n":"BX1-21","p":7,"a":"p7","id":"cv4","src":"assets/audio/BX1-21/cv4.mp3","sec":9.168,"t":"解题方法：比较一昼夜首尾的CO2浓度，终点低于起点，说明有机物有积累，植物能生长。"},{"ep":"bx1-21","n":"BX1-21","p":8,"a":"p8","id":"ap1","src":"assets/audio/BX1-21/ap1.mp3","sec":8.376,"t":"考点八，光合作用原理的应用。合理密植：充分利用光能，又避免叶片相互遮挡。"},{"ep":"bx1-21","n":"BX1-21","p":8,"a":"p8","id":"ap2","src":"assets/audio/BX1-21/ap2.mp3","sec":6.768,"t":"间作套种，充分利用光能；温室中适当增加光照、补充CO2。"},{"ep":"bx1-21","n":"BX1-21","p":8,"a":"p8","id":"ap3","src":"assets/audio/BX1-21/ap3.mp3","sec":9.192,"t":"适当提高昼夜温差：白天温度适宜，光合作用强；夜晚温度低，呼吸作用弱，有机物积累多。"},{"ep":"bx1-21","n":"BX1-21","p":8,"a":"p8","id":"ap4","src":"assets/audio/BX1-21/ap4.mp3","sec":9.144,"t":"易错：温室补光用红光或蓝紫光；阴天光照弱时，温室应适当降低温度，减少呼吸消耗。"},{"ep":"bx1-21","n":"BX1-21","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-21/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-21","n":"BX1-21","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-21/rv2.mp3","sec":8.64,"t":"判断一？错，代表净光合速率。判断二？错，阴生植物的光补偿点较低。"},{"ep":"bx1-21","n":"BX1-21","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-21/rv3.mp3","sec":6.192,"t":"判断三？对。判断四？错，是气孔部分关闭。"},{"ep":"bx1-21","n":"BX1-21","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-21/rv4.mp3","sec":6.36,"t":"判断五？对。判断六？错，夜间应适当降温。"},{"ep":"bx1-21","n":"BX1-21","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-21/rv5.mp3","sec":7.632,"t":"八个考点串成一条线：能不能生长，看净光合是否大于零。我们下期再见！"},{"ep":"bx1-22","n":"BX1-22","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-22/in1.mp3","sec":8.616,"t":"同学们好！这节课梳理人教版必修一第六章第一节的上半部分——细胞周期与有丝分裂。"},{"ep":"bx1-22","n":"BX1-22","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-22/in2.mp3","sec":8.352,"t":"高考常考细胞周期的判断、有丝分裂各时期的特点，以及染色体和核DNA数目的变化。"},{"ep":"bx1-22","n":"BX1-22","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-22/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-22","n":"BX1-22","p":1,"a":"p1","id":"sz1","src":"assets/audio/BX1-22/sz1.mp3","sec":11.904,"t":"考点一，细胞增殖。细胞通过细胞分裂增加细胞数量，叫细胞增殖，它是生物体生长、发育、繁殖和遗传的基础。"},{"ep":"bx1-22","n":"BX1-22","p":1,"a":"p1","id":"sz2","src":"assets/audio/BX1-22/sz2.mp3","sec":7.68,"t":"细胞不能无限长大：细胞体积越大，相对表面积越小，物质运输的效率就越低。"},{"ep":"bx1-22","n":"BX1-22","p":1,"a":"p1","id":"sz3","src":"assets/audio/BX1-22/sz3.mp3","sec":10.848,"t":"细胞增殖包括物质准备和细胞分裂两个连续的过程；真核细胞的分裂方式有有丝分裂、无丝分裂和减数分裂。"},{"ep":"bx1-22","n":"BX1-22","p":1,"a":"p1","id":"sz4","src":"assets/audio/BX1-22/sz4.mp3","sec":7.08,"t":"易错：细胞也不是越小越好，细胞内还要容纳酶、核糖体等物质和结构。"},{"ep":"bx1-22","n":"BX1-22","p":2,"a":"p2","id":"cy1","src":"assets/audio/BX1-22/cy1.mp3","sec":10.728,"t":"考点二，细胞周期。连续分裂的细胞，从一次分裂完成时开始，到下一次分裂完成时为止，为一个细胞周期。"},{"ep":"bx1-22","n":"BX1-22","p":2,"a":"p2","id":"cy2","src":"assets/audio/BX1-22/cy2.mp3","sec":9.096,"t":"一个细胞周期包括分裂间期和分裂期，间期在前，大约占细胞周期的90%～95%。"},{"ep":"bx1-22","n":"BX1-22","p":2,"a":"p2","id":"cy3","src":"assets/audio/BX1-22/cy3.mp3","sec":11.256,"t":"易错：只有连续分裂的细胞才有细胞周期，如分生区细胞；高度分化的神经细胞、进行减数分裂的细胞没有细胞周期。"},{"ep":"bx1-22","n":"BX1-22","p":3,"a":"p3","id":"rp1","src":"assets/audio/BX1-22/rp1.mp3","sec":10.68,"t":"考点三，细胞周期的表示方法。线段图：间期长、分裂期短，一个周期要从间期开始，到分裂期结束。"},{"ep":"bx1-22","n":"BX1-22","p":3,"a":"p3","id":"rp2","src":"assets/audio/BX1-22/rp2.mp3","sec":7.152,"t":"扇形图：按顺时针方向，从间期到分裂期，回到起点为一个细胞周期。"},{"ep":"bx1-22","n":"BX1-22","p":3,"a":"p3","id":"rp3","src":"assets/audio/BX1-22/rp3.mp3","sec":8.544,"t":"解题方法：判断哪段是一个细胞周期，看先间期、后分裂期，而且两段首尾相接。"},{"ep":"bx1-22","n":"BX1-22","p":4,"a":"p4","id":"ip1","src":"assets/audio/BX1-22/ip1.mp3","sec":12.624,"t":"考点四，分裂间期。为分裂期进行活跃的物质准备，完成DNA分子的复制和有关蛋白质的合成，同时细胞有适度的生长。"},{"ep":"bx1-22","n":"BX1-22","p":4,"a":"p4","id":"ip2","src":"assets/audio/BX1-22/ip2.mp3","sec":9.072,"t":"DNA复制后，每条染色体含有两条姐妹染色单体，核DNA数目加倍，但染色体数目不变。"},{"ep":"bx1-22","n":"BX1-22","p":4,"a":"p4","id":"ip3","src":"assets/audio/BX1-22/ip3.mp3","sec":9.096,"t":"易错：间期遗传物质呈染色质状态，显微镜下看不到染色体；间期不属于分裂期的前期。"},{"ep":"bx1-22","n":"BX1-22","p":5,"a":"p5","id":"ea1","src":"assets/audio/BX1-22/ea1.mp3","sec":14.832,"t":"考点五，前期和中期，以高等植物细胞为例。前期：染色质丝螺旋化成为染色体；核仁解体、核膜消失；细胞两极发出纺锤丝，形成纺锤体。"},{"ep":"bx1-22","n":"BX1-22","p":5,"a":"p5","id":"ea2","src":"assets/audio/BX1-22/ea2.mp3","sec":11.616,"t":"中期：纺锤丝附着在着丝粒两侧，着丝粒排列在赤道板上；染色体形态稳定、数目清晰，是观察染色体的最佳时期。"},{"ep":"bx1-22","n":"BX1-22","p":5,"a":"p5","id":"ea3","src":"assets/audio/BX1-22/ea3.mp3","sec":8.136,"t":"易错：赤道板是一个假想的平面，不是真实结构；末期出现的细胞板才是真实结构。"},{"ep":"bx1-22","n":"BX1-22","p":6,"a":"p6","id":"lt1","src":"assets/audio/BX1-22/lt1.mp3","sec":11.856,"t":"考点六，后期和末期。后期：着丝粒分裂，姐妹染色单体分开成为两条染色体，移向细胞两极，染色体数目加倍。"},{"ep":"bx1-22","n":"BX1-22","p":6,"a":"p6","id":"lt2","src":"assets/audio/BX1-22/lt2.mp3","sec":12.408,"t":"末期：染色体变成染色质丝，纺锤丝消失，出现新的核膜和核仁；植物细胞在赤道板位置出现细胞板，扩展形成新的细胞壁。"},{"ep":"bx1-22","n":"BX1-22","p":6,"a":"p6","id":"lt3","src":"assets/audio/BX1-22/lt3.mp3","sec":9.6,"t":"解题方法：记口诀——膜仁消失显两体，形定数晰赤道齐，点裂数增均两极，两消两现重开始。"},{"ep":"bx1-22","n":"BX1-22","p":7,"a":"p7","id":"ct1","src":"assets/audio/BX1-22/ct1.mp3","sec":12.432,"t":"考点七，数目的变化，设体细胞染色体数为2N。核DNA：间期复制，由2N变为4N；末期细胞一分为二，恢复为2N。"},{"ep":"bx1-22","n":"BX1-22","p":7,"a":"p7","id":"ct2","src":"assets/audio/BX1-22/ct2.mp3","sec":6.576,"t":"染色体：后期着丝粒分裂，由2N变为4N；末期恢复为2N。"},{"ep":"bx1-22","n":"BX1-22","p":7,"a":"p7","id":"ct3","src":"assets/audio/BX1-22/ct3.mp3","sec":7.44,"t":"染色单体：间期复制后出现，为4N；后期着丝粒分裂后消失，变为0。"},{"ep":"bx1-22","n":"BX1-22","p":7,"a":"p7","id":"ct4","src":"assets/audio/BX1-22/ct4.mp3","sec":11.904,"t":"解题方法：有染色单体时，染色单体数 = 核DNA数 = 染色体数的2倍；没有染色单体时，核DNA数等于染色体数。"},{"ep":"bx1-22","n":"BX1-22","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-22/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-22","n":"BX1-22","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-22/rv2.mp3","sec":8.88,"t":"判断一？错，细胞越大，运输效率越低。判断二？错，神经细胞不再分裂。"},{"ep":"bx1-22","n":"BX1-22","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-22/rv3.mp3","sec":6.24,"t":"判断三？对。判断四？错，染色体数目不变。"},{"ep":"bx1-22","n":"BX1-22","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-22/rv4.mp3","sec":5.736,"t":"判断五？错，是赤道板。判断六？对。"},{"ep":"bx1-22","n":"BX1-22","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-22/rv5.mp3","sec":8.424,"t":"七个考点串成一条线：间期复制，前中后末，数目跟着着丝粒走。我们下期再见！"},{"ep":"bx1-23","n":"BX1-23","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-23/in1.mp3","sec":11.616,"t":"同学们好！这节课梳理人教版必修一第六章第一节的下半部分——动植物细胞有丝分裂的比较和观察根尖细胞有丝分裂的实验。"},{"ep":"bx1-23","n":"BX1-23","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-23/in2.mp3","sec":7.344,"t":"高考常考动植物细胞分裂的区别、实验步骤，以及柱形图和曲线图的识别。"},{"ep":"bx1-23","n":"BX1-23","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-23/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-23","n":"BX1-23","p":1,"a":"p1","id":"cm1","src":"assets/audio/BX1-23/cm1.mp3","sec":5.52,"t":"考点一，动植物细胞有丝分裂的区别，在前期和末期。"},{"ep":"bx1-23","n":"BX1-23","p":1,"a":"p1","id":"cm2","src":"assets/audio/BX1-23/cm2.mp3","sec":10.584,"t":"前期纺锤体的形成：植物细胞从细胞两极发出纺锤丝；动物细胞由中心体发出星射线，中心粒在间期倍增。"},{"ep":"bx1-23","n":"BX1-23","p":1,"a":"p1","id":"cm3","src":"assets/audio/BX1-23/cm3.mp3","sec":12.384,"t":"末期细胞质的分裂：植物细胞在赤道板位置形成细胞板，扩展成细胞壁；动物细胞的细胞膜从中部向内凹陷，缢裂成两个子细胞。"},{"ep":"bx1-23","n":"BX1-23","p":1,"a":"p1","id":"cm4","src":"assets/audio/BX1-23/cm4.mp3","sec":9.864,"t":"易错：低等植物细胞也有中心体；判断动物还是植物，最可靠的是看有无细胞壁和末期的分裂方式。"},{"ep":"bx1-23","n":"BX1-23","p":2,"a":"p2","id":"mn1","src":"assets/audio/BX1-23/mn1.mp3","sec":9.36,"t":"考点二，有丝分裂的意义。将亲代细胞的染色体经过复制后，精确地平均分配到两个子细胞中。"},{"ep":"bx1-23","n":"BX1-23","p":2,"a":"p2","id":"mn2","src":"assets/audio/BX1-23/mn2.mp3","sec":3.744,"t":"保持了亲子代细胞之间遗传的稳定性。"},{"ep":"bx1-23","n":"BX1-23","p":2,"a":"p2","id":"mn3","src":"assets/audio/BX1-23/mn3.mp3","sec":10.464,"t":"易错：平均分配的是细胞核中的DNA；细胞质中的DNA，如线粒体DNA，是随机、不均等分配的。"},{"ep":"bx1-23","n":"BX1-23","p":3,"a":"p3","id":"am1","src":"assets/audio/BX1-23/am1.mp3","sec":8.52,"t":"考点三，无丝分裂。分裂过程中没有出现纺锤丝和染色体的变化，所以叫无丝分裂。"},{"ep":"bx1-23","n":"BX1-23","p":3,"a":"p3","id":"am2","src":"assets/audio/BX1-23/am2.mp3","sec":10.032,"t":"过程：细胞核先延长，核的中部向内凹进，缢裂成两个细胞核；接着整个细胞从中部缢裂成两个子细胞。"},{"ep":"bx1-23","n":"BX1-23","p":3,"a":"p3","id":"am3","src":"assets/audio/BX1-23/am3.mp3","sec":2.976,"t":"实例：蛙的红细胞的分裂。"},{"ep":"bx1-23","n":"BX1-23","p":3,"a":"p3","id":"am4","src":"assets/audio/BX1-23/am4.mp3","sec":10.752,"t":"易错：无丝分裂也有DNA的复制；它是真核细胞的分裂方式，原核细胞进行的是二分裂；人的成熟红细胞不分裂。"},{"ep":"bx1-23","n":"BX1-23","p":4,"a":"p4","id":"st1","src":"assets/audio/BX1-23/st1.mp3","sec":11.736,"t":"考点四，观察根尖分生区组织细胞的有丝分裂。解离：用盐酸和酒精1∶1混合的解离液，使组织中的细胞相互分离。"},{"ep":"bx1-23","n":"BX1-23","p":4,"a":"p4","id":"st2","src":"assets/audio/BX1-23/st2.mp3","sec":6.648,"t":"漂洗：用清水漂洗，洗去解离液，防止解离过度，也便于染色。"},{"ep":"bx1-23","n":"BX1-23","p":4,"a":"p4","id":"st3","src":"assets/audio/BX1-23/st3.mp3","sec":6.504,"t":"染色：用甲紫溶液或醋酸洋红液等碱性染料，使染色体着色。"},{"ep":"bx1-23","n":"BX1-23","p":4,"a":"p4","id":"st4","src":"assets/audio/BX1-23/st4.mp3","sec":7.2,"t":"制片：压片使细胞分散开，再用低倍镜找到分生区，换高倍镜观察。"},{"ep":"bx1-23","n":"BX1-23","p":4,"a":"p4","id":"st5","src":"assets/audio/BX1-23/st5.mp3","sec":10.416,"t":"易错：顺序是解离、漂洗、染色、制片，漂洗一定在染色之前；分生区细胞呈正方形、排列紧密。"},{"ep":"bx1-23","n":"BX1-23","p":5,"a":"p5","id":"rs1","src":"assets/audio/BX1-23/rs1.mp3","sec":10.2,"t":"考点五，实验结果分析。视野中大多数细胞处于分裂间期，因为间期在细胞周期中占的时间最长。"},{"ep":"bx1-23","n":"BX1-23","p":5,"a":"p5","id":"rs2","src":"assets/audio/BX1-23/rs2.mp3","sec":8.28,"t":"解离后细胞已经死亡，所以不能看到一个细胞连续分裂的过程，要寻找处于不同时期的细胞。"},{"ep":"bx1-23","n":"BX1-23","p":5,"a":"p5","id":"rs3","src":"assets/audio/BX1-23/rs3.mp3","sec":9.888,"t":"解题方法：某时期细胞数占总数的比例，等于这一时期占细胞周期时间的比例，可以用来估算各时期的时长。"},{"ep":"bx1-23","n":"BX1-23","p":6,"a":"p6","id":"gr1","src":"assets/audio/BX1-23/gr1.mp3","sec":6.888,"t":"考点六，柱形图和曲线图。柱形图中，会变成0的是染色单体。"},{"ep":"bx1-23","n":"BX1-23","p":6,"a":"p6","id":"gr2","src":"assets/audio/BX1-23/gr2.mp3","sec":7.8,"t":"染色单体为0时，染色体数等于核DNA数，对应间期复制前、后期和末期。"},{"ep":"bx1-23","n":"BX1-23","p":6,"a":"p6","id":"gr3","src":"assets/audio/BX1-23/gr3.mp3","sec":8.688,"t":"染色单体不为0时，染色体∶核DNA∶染色单体 = 1∶2∶2，对应前期和中期。"},{"ep":"bx1-23","n":"BX1-23","p":6,"a":"p6","id":"gr4","src":"assets/audio/BX1-23/gr4.mp3","sec":10.992,"t":"曲线图中，核DNA是斜线上升，因为DNA复制需要时间；染色体是垂直上升，因为着丝粒是一下子分裂的。"},{"ep":"bx1-23","n":"BX1-23","p":6,"a":"p6","id":"gr5","src":"assets/audio/BX1-23/gr5.mp3","sec":8.376,"t":"解题方法：先找能变成0的是染色单体，再看有没有斜线区分核DNA和染色体。"},{"ep":"bx1-23","n":"BX1-23","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-23/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-23","n":"BX1-23","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-23/rv2.mp3","sec":6.48,"t":"判断一？错，区别在前期和末期。判断二？对。"},{"ep":"bx1-23","n":"BX1-23","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-23/rv3.mp3","sec":8.832,"t":"判断三？错，无丝分裂也有DNA复制。判断四？错，要先漂洗再染色。"},{"ep":"bx1-23","n":"BX1-23","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-23/rv4.mp3","sec":6.888,"t":"判断五？错，解离后细胞已经死亡。判断六？对。"},{"ep":"bx1-23","n":"BX1-23","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-23/rv5.mp3","sec":8.064,"t":"六个考点串成一条线：前期末期看区别，解离漂洗染色制片。我们下期再见！"},{"ep":"bx1-24","n":"BX1-24","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-24/in1.mp3","sec":6.744,"t":"同学们好！这节课梳理人教版必修一第六章第二节——细胞的分化。"},{"ep":"bx1-24","n":"BX1-24","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-24/in2.mp3","sec":6.744,"t":"高考常考细胞分化的实质、全能性的判断，以及干细胞的类型和应用。"},{"ep":"bx1-24","n":"BX1-24","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-24/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-24","n":"BX1-24","p":1,"a":"p1","id":"cn1","src":"assets/audio/BX1-24/cn1.mp3","sec":12.816,"t":"考点一，细胞分化的概念。在个体发育中，由一个或一种细胞增殖产生的后代，在形态、结构和生理功能上发生稳定性差异的过程。"},{"ep":"bx1-24","n":"BX1-24","p":1,"a":"p1","id":"cn2","src":"assets/audio/BX1-24/cn2.mp3","sec":10.512,"t":"特点一，持久性：细胞分化是一种持久性的变化。特点二，普遍性：它是生物界普遍存在的生命现象。"},{"ep":"bx1-24","n":"BX1-24","p":1,"a":"p1","id":"cn3","src":"assets/audio/BX1-24/cn3.mp3","sec":7.992,"t":"特点三，稳定性：一般来说，分化了的细胞将一直保持分化后的状态，直到死亡。"},{"ep":"bx1-24","n":"BX1-24","p":1,"a":"p1","id":"cn4","src":"assets/audio/BX1-24/cn4.mp3","sec":7.344,"t":"易错：细胞分化使细胞的种类增加，细胞分裂使细胞的数目增加，别混。"},{"ep":"bx1-24","n":"BX1-24","p":2,"a":"p2","id":"es1","src":"assets/audio/BX1-24/es1.mp3","sec":4.752,"t":"考点二，细胞分化的实质：基因的选择性表达。"},{"ep":"bx1-24","n":"BX1-24","p":2,"a":"p2","id":"es2","src":"assets/audio/BX1-24/es2.mp3","sec":8.952,"t":"同一个体的不同细胞，遗传物质相同，但表达的基因不同，所以mRNA和蛋白质不完全相同。"},{"ep":"bx1-24","n":"BX1-24","p":2,"a":"p2","id":"es3","src":"assets/audio/BX1-24/es3.mp3","sec":12.6,"t":"比如，红细胞中表达血红蛋白基因，胰岛B细胞中表达胰岛素基因；而呼吸酶基因、ATP合成酶基因在几乎所有细胞中都表达。"},{"ep":"bx1-24","n":"BX1-24","p":2,"a":"p2","id":"es4","src":"assets/audio/BX1-24/es4.mp3","sec":11.064,"t":"解题方法：判断细胞是否分化，看是否合成了特定的蛋白质，比如血红蛋白、胰岛素、抗体；呼吸酶不能作为依据。"},{"ep":"bx1-24","n":"BX1-24","p":3,"a":"p3","id":"mn1","src":"assets/audio/BX1-24/mn1.mp3","sec":6.576,"t":"考点三，细胞分化的意义。细胞分化是生物个体发育的基础。"},{"ep":"bx1-24","n":"BX1-24","p":3,"a":"p3","id":"mn2","src":"assets/audio/BX1-24/mn2.mp3","sec":6.648,"t":"它使多细胞生物体中的细胞趋向专门化，有利于提高生理功能的效率。"},{"ep":"bx1-24","n":"BX1-24","p":3,"a":"p3","id":"mn3","src":"assets/audio/BX1-24/mn3.mp3","sec":10.008,"t":"考法：分化形成不同的组织和器官。易错：分化后细胞的核遗传物质不变，分化不会改变细胞数目。"},{"ep":"bx1-24","n":"BX1-24","p":4,"a":"p4","id":"tp1","src":"assets/audio/BX1-24/tp1.mp3","sec":11.016,"t":"考点四，细胞的全能性。细胞经分裂和分化后，仍具有产生完整有机体或分化成其他各种细胞的潜能和特性。"},{"ep":"bx1-24","n":"BX1-24","p":4,"a":"p4","id":"tp2","src":"assets/audio/BX1-24/tp2.mp3","sec":7.536,"t":"植物细胞具有全能性：比如胡萝卜韧皮部细胞经组织培养，发育成完整的植株。"},{"ep":"bx1-24","n":"BX1-24","p":4,"a":"p4","id":"tp3","src":"assets/audio/BX1-24/tp3.mp3","sec":9.552,"t":"动物细胞的细胞核具有全能性：比如克隆羊多莉，是把体细胞的细胞核移植到去核卵细胞中培育而成的。"},{"ep":"bx1-24","n":"BX1-24","p":4,"a":"p4","id":"tp4","src":"assets/audio/BX1-24/tp4.mp3","sec":9.456,"t":"全能性大小：受精卵 > 生殖细胞 > 体细胞；一般细胞分化程度越高，全能性越难以实现。"},{"ep":"bx1-24","n":"BX1-24","p":4,"a":"p4","id":"tp5","src":"assets/audio/BX1-24/tp5.mp3","sec":7.2,"t":"易错：多莉说明的是动物细胞的细胞核具有全能性，不是整个动物细胞。"},{"ep":"bx1-24","n":"BX1-24","p":5,"a":"p5","id":"st1","src":"assets/audio/BX1-24/st1.mp3","sec":7.752,"t":"考点五，干细胞。动物和人体内少数具有分裂和分化能力的细胞，叫干细胞。"},{"ep":"bx1-24","n":"BX1-24","p":5,"a":"p5","id":"st2","src":"assets/audio/BX1-24/st2.mp3","sec":5.352,"t":"胚胎干细胞：可以分化成各种组织和器官，全能性高。"},{"ep":"bx1-24","n":"BX1-24","p":5,"a":"p5","id":"st3","src":"assets/audio/BX1-24/st3.mp3","sec":9.648,"t":"造血干细胞：存在于骨髓中，能分化成红细胞、白细胞和血小板等各种血细胞，可用于治疗白血病。"},{"ep":"bx1-24","n":"BX1-24","p":5,"a":"p5","id":"st4","src":"assets/audio/BX1-24/st4.mp3","sec":7.584,"t":"易错：造血干细胞分化出各种血细胞，没有发育成完整个体，不体现全能性。"},{"ep":"bx1-24","n":"BX1-24","p":6,"a":"p6","id":"tr1","src":"assets/audio/BX1-24/tr1.mp3","sec":9.912,"t":"考点六，怎样才算体现了全能性。起点必须是单个细胞或细胞核，终点必须是完整个体或各种细胞。"},{"ep":"bx1-24","n":"BX1-24","p":6,"a":"p6","id":"tr2","src":"assets/audio/BX1-24/tr2.mp3","sec":7.032,"t":"种子萌发长成植株：种子是器官，属于正常的个体发育，不体现全能性。"},{"ep":"bx1-24","n":"BX1-24","p":6,"a":"p6","id":"tr3","src":"assets/audio/BX1-24/tr3.mp3","sec":6.456,"t":"造血干细胞形成血细胞：没有发育成完整个体，也不体现全能性。"},{"ep":"bx1-24","n":"BX1-24","p":6,"a":"p6","id":"tr4","src":"assets/audio/BX1-24/tr4.mp3","sec":8.904,"t":"解题方法：看“起点是不是细胞，终点是不是个体”；植物组织培养、克隆动物才体现全能性。"},{"ep":"bx1-24","n":"BX1-24","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-24/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-24","n":"BX1-24","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-24/rv2.mp3","sec":8.304,"t":"判断一？错，遗传物质不变。判断二？错，细胞分化是持久性的变化。"},{"ep":"bx1-24","n":"BX1-24","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-24/rv3.mp3","sec":7.392,"t":"判断三？对。判断四？错，种子是器官，不体现全能性。"},{"ep":"bx1-24","n":"BX1-24","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-24/rv4.mp3","sec":6.648,"t":"判断五？对。判断六？错，受精卵的全能性最高。"},{"ep":"bx1-24","n":"BX1-24","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-24/rv5.mp3","sec":7.296,"t":"六个考点串成一条线：遗传物质不变，基因选择性表达。我们下期再见！"},{"ep":"bx1-25","n":"BX1-25","p":0,"a":"intro","id":"in1","src":"assets/audio/BX1-25/in1.mp3","sec":9.408,"t":"同学们好！这节课梳理人教版必修一第六章第三节——细胞的衰老和死亡，也是必修一的最后一节。"},{"ep":"bx1-25","n":"BX1-25","p":0,"a":"intro","id":"in2","src":"assets/audio/BX1-25/in2.mp3","sec":7.272,"t":"高考常考衰老细胞的特征、细胞凋亡与细胞坏死的区别，以及细胞自噬。"},{"ep":"bx1-25","n":"BX1-25","p":0,"a":"intro","id":"in3","src":"assets/audio/BX1-25/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx1-25","n":"BX1-25","p":1,"a":"p1","id":"ag1","src":"assets/audio/BX1-25/ag1.mp3","sec":9.696,"t":"考点一，个体衰老与细胞衰老的关系。单细胞生物：细胞的衰老或死亡就是个体的衰老或死亡。"},{"ep":"bx1-25","n":"BX1-25","p":1,"a":"p1","id":"ag2","src":"assets/audio/BX1-25/ag2.mp3","sec":10.128,"t":"多细胞生物：个体衰老与细胞衰老不是一回事；但个体衰老的过程，也是组成个体的细胞普遍衰老的过程。"},{"ep":"bx1-25","n":"BX1-25","p":1,"a":"p1","id":"ag3","src":"assets/audio/BX1-25/ag3.mp3","sec":9.12,"t":"易错：幼年个体中也有衰老的细胞，老年个体中也有新生的细胞，比如造血干细胞仍在分裂。"},{"ep":"bx1-25","n":"BX1-25","p":2,"a":"p2","id":"ft1","src":"assets/audio/BX1-25/ft1.mp3","sec":9.528,"t":"考点二，衰老细胞的主要特征。细胞内水分减少，细胞萎缩，体积变小，新陈代谢速率减慢。"},{"ep":"bx1-25","n":"BX1-25","p":2,"a":"p2","id":"ft2","src":"assets/audio/BX1-25/ft2.mp3","sec":9.288,"t":"细胞内多种酶的活性降低，比如酪氨酸酶活性降低，黑色素合成减少，所以老年人头发变白。"},{"ep":"bx1-25","n":"BX1-25","p":2,"a":"p2","id":"ft3","src":"assets/audio/BX1-25/ft3.mp3","sec":5.784,"t":"细胞内的色素逐渐积累，比如老年斑；细胞呼吸速率减慢。"},{"ep":"bx1-25","n":"BX1-25","p":2,"a":"p2","id":"ft4","src":"assets/audio/BX1-25/ft4.mp3","sec":9.792,"t":"细胞核的体积增大，核膜内折，染色质收缩、染色加深；细胞膜通透性改变，物质运输功能降低。"},{"ep":"bx1-25","n":"BX1-25","p":2,"a":"p2","id":"ft5","src":"assets/audio/BX1-25/ft5.mp3","sec":12.288,"t":"易错：衰老细胞的细胞体积变小，但细胞核体积变大；“白头发”是酶活性降低，“白化病”是基因异常、不能合成酪氨酸酶，别混。"},{"ep":"bx1-25","n":"BX1-25","p":3,"a":"p3","id":"th1","src":"assets/audio/BX1-25/th1.mp3","sec":11.64,"t":"考点三，细胞衰老的原因。自由基学说：细胞代谢产生的自由基，会攻击和破坏细胞内各种执行正常功能的生物分子。"},{"ep":"bx1-25","n":"BX1-25","p":3,"a":"p3","id":"th2","src":"assets/audio/BX1-25/th2.mp3","sec":9.264,"t":"比如攻击磷脂产生更多自由基，攻击DNA可能引起基因突变，攻击蛋白质使其活性下降。"},{"ep":"bx1-25","n":"BX1-25","p":3,"a":"p3","id":"th3","src":"assets/audio/BX1-25/th3.mp3","sec":10.32,"t":"端粒学说：端粒是每条染色体两端的一段特殊序列的DNA—蛋白质复合体，每次细胞分裂后会缩短一截。"},{"ep":"bx1-25","n":"BX1-25","p":3,"a":"p3","id":"th4","src":"assets/audio/BX1-25/th4.mp3","sec":9.912,"t":"解题方法：端粒内侧的正常基因受到损伤后，细胞活动逐渐异常；原核细胞没有染色体，也就没有端粒。"},{"ep":"bx1-25","n":"BX1-25","p":4,"a":"p4","id":"ap1","src":"assets/audio/BX1-25/ap1.mp3","sec":9.48,"t":"考点四，细胞凋亡。由基因所决定的细胞自动结束生命的过程，也常被称为细胞编程性死亡。"},{"ep":"bx1-25","n":"BX1-25","p":4,"a":"p4","id":"ap2","src":"assets/audio/BX1-25/ap2.mp3","sec":8.352,"t":"实例：蝌蚪尾的消失、人胚胎发育中手指间细胞的凋亡、被病原体感染的细胞的清除。"},{"ep":"bx1-25","n":"BX1-25","p":4,"a":"p4","id":"ap3","src":"assets/audio/BX1-25/ap3.mp3","sec":8.856,"t":"意义：保证多细胞生物体完成正常发育，维持内部环境的稳定，抵御外界各种因素的干扰。"},{"ep":"bx1-25","n":"BX1-25","p":4,"a":"p4","id":"ap4","src":"assets/audio/BX1-25/ap4.mp3","sec":8.4,"t":"易错：细胞凋亡对生物体是有利的；被病原体感染的细胞的清除属于凋亡，不是坏死。"},{"ep":"bx1-25","n":"BX1-25","p":5,"a":"p5","id":"nc1","src":"assets/audio/BX1-25/nc1.mp3","sec":8.904,"t":"考点五，细胞凋亡与细胞坏死的比较。细胞凋亡是基因控制的主动死亡，对机体有利。"},{"ep":"bx1-25","n":"BX1-25","p":5,"a":"p5","id":"nc2","src":"assets/audio/BX1-25/nc2.mp3","sec":11.592,"t":"细胞坏死是在种种不利因素的影响下，由于细胞正常代谢活动受损或中断引起的细胞损伤和死亡，是被动的，对机体有害。"},{"ep":"bx1-25","n":"BX1-25","p":5,"a":"p5","id":"nc3","src":"assets/audio/BX1-25/nc3.mp3","sec":11.856,"t":"解题方法：看原因——自然的、程序性的是凋亡；由极端物理、化学因素或严重病理刺激引起的是坏死，比如烫伤、缺氧。"},{"ep":"bx1-25","n":"BX1-25","p":6,"a":"p6","id":"au1","src":"assets/audio/BX1-25/au1.mp3","sec":10.512,"t":"考点六，细胞自噬。在一定条件下，细胞会将受损或功能退化的细胞结构等，通过溶酶体降解后再利用。"},{"ep":"bx1-25","n":"BX1-25","p":6,"a":"p6","id":"au2","src":"assets/audio/BX1-25/au2.mp3","sec":13.416,"t":"营养缺乏时，细胞通过自噬获得维持生存所需的物质和能量；自噬还能清除受损的细胞器和感染的微生物、毒素，维持细胞内部环境的稳定。"},{"ep":"bx1-25","n":"BX1-25","p":6,"a":"p6","id":"au3","src":"assets/audio/BX1-25/au3.mp3","sec":4.2,"t":"有些激烈的细胞自噬，可能诱导细胞凋亡。"},{"ep":"bx1-25","n":"BX1-25","p":6,"a":"p6","id":"au4","src":"assets/audio/BX1-25/au4.mp3","sec":7.32,"t":"易错：细胞自噬不一定导致细胞死亡；参与自噬的主要细胞器是溶酶体。"},{"ep":"bx1-25","n":"BX1-25","p":"review","a":"review","id":"rv1","src":"assets/audio/BX1-25/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx1-25","n":"BX1-25","p":"review","a":"review","id":"rv2","src":"assets/audio/BX1-25/rv2.mp3","sec":10.296,"t":"判断一？错，个体衰老与细胞衰老不同步。判断二？错，是多种酶活性降低，并非所有酶。"},{"ep":"bx1-25","n":"BX1-25","p":"review","a":"review","id":"rv3","src":"assets/audio/BX1-25/rv3.mp3","sec":6.456,"t":"判断三？对。判断四？错，凋亡对生物体有利。"},{"ep":"bx1-25","n":"BX1-25","p":"review","a":"review","id":"rv4","src":"assets/audio/BX1-25/rv4.mp3","sec":6.504,"t":"判断五？对。判断六？错，自噬不一定导致死亡。"},{"ep":"bx1-25","n":"BX1-25","p":"review","a":"review","id":"rv5","src":"assets/audio/BX1-25/rv5.mp3","sec":10.44,"t":"六个考点串成一条线：凋亡由基因决定，坏死是被动的损伤。必修一到这里就全部梳理完了，我们下期再见！"},{"ep":"bx2-01","n":"BX2-01","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-01/in1.mp3","sec":8.88,"t":"同学们好！这节课梳理人教版必修二第一章第一节的上半部分——一对相对性状的杂交实验。"},{"ep":"bx2-01","n":"BX2-01","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-01/in2.mp3","sec":6.84,"t":"高考常考豌豆杂交的操作、对分离现象的解释、测交和假说—演绎法。"},{"ep":"bx2-01","n":"BX2-01","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-01/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-01","n":"BX2-01","p":1,"a":"p1","id":"pe1","src":"assets/audio/BX2-01/pe1.mp3","sec":10.68,"t":"考点一，豌豆作遗传材料的优点。第一，豌豆是自花传粉、闭花受粉的植物，自然状态下一般都是纯种。"},{"ep":"bx2-01","n":"BX2-01","p":1,"a":"p1","id":"pe2","src":"assets/audio/BX2-01/pe2.mp3","sec":8.328,"t":"第二，豌豆有许多易于区分的相对性状，比如高茎和矮茎，实验结果容易观察和分析。"},{"ep":"bx2-01","n":"BX2-01","p":1,"a":"p1","id":"pe3","src":"assets/audio/BX2-01/pe3.mp3","sec":6.936,"t":"第三，豌豆花比较大，便于人工操作；子代数量多，便于统计分析。"},{"ep":"bx2-01","n":"BX2-01","p":1,"a":"p1","id":"pe4","src":"assets/audio/BX2-01/pe4.mp3","sec":8.784,"t":"易错：闭花受粉是指花还没开放就已经完成受粉，所以人工杂交必须在花蕾期去雄。"},{"ep":"bx2-01","n":"BX2-01","p":2,"a":"p2","id":"po1","src":"assets/audio/BX2-01/po1.mp3","sec":7.752,"t":"考点二，人工异花传粉。提供花粉的植株叫父本，接受花粉的植株叫母本。"},{"ep":"bx2-01","n":"BX2-01","p":2,"a":"p2","id":"po2","src":"assets/audio/BX2-01/po2.mp3","sec":8.232,"t":"第一步去雄：在花蕾期，除去母本花的全部雄蕊。第二步套袋，防止外来花粉干扰。"},{"ep":"bx2-01","n":"BX2-01","p":2,"a":"p2","id":"po3","src":"assets/audio/BX2-01/po3.mp3","sec":7.92,"t":"第三步人工授粉：采集父本的花粉，涂在去雄花的雌蕊柱头上。第四步再套袋。"},{"ep":"bx2-01","n":"BX2-01","p":2,"a":"p2","id":"po4","src":"assets/audio/BX2-01/po4.mp3","sec":11.184,"t":"考法：问步骤顺序和目的。易错：去雄要在花粉成熟前、要彻底；两次套袋的目的都是避免外来花粉的干扰。"},{"ep":"bx2-01","n":"BX2-01","p":3,"a":"p3","id":"te1","src":"assets/audio/BX2-01/te1.mp3","sec":7.848,"t":"考点三，几个基本概念。相对性状，是一种生物的同一种性状的不同表现类型。"},{"ep":"bx2-01","n":"BX2-01","p":3,"a":"p3","id":"te2","src":"assets/audio/BX2-01/te2.mp3","sec":7.032,"t":"杂种子一代显现出来的性状叫显性性状，没有显现出来的叫隐性性状。"},{"ep":"bx2-01","n":"BX2-01","p":3,"a":"p3","id":"te3","src":"assets/audio/BX2-01/te3.mp3","sec":6.72,"t":"杂种后代中同时出现显性性状和隐性性状的现象，叫性状分离。"},{"ep":"bx2-01","n":"BX2-01","p":3,"a":"p3","id":"te4","src":"assets/audio/BX2-01/te4.mp3","sec":10.824,"t":"解题方法：判断相对性状抓三个关键词——同种生物、同一性状、不同表现。狗的长毛和兔的短毛就不是。"},{"ep":"bx2-01","n":"BX2-01","p":4,"a":"p4","id":"cr1","src":"assets/audio/BX2-01/cr1.mp3","sec":8.736,"t":"考点四，一对相对性状的杂交实验。纯种高茎和纯种矮茎杂交，F1 全是高茎。"},{"ep":"bx2-01","n":"BX2-01","p":4,"a":"p4","id":"cr2","src":"assets/audio/BX2-01/cr2.mp3","sec":9.24,"t":"F1 自交，F2 中既有高茎又有矮茎，787 株对 277 株，数量比接近 3∶1。"},{"ep":"bx2-01","n":"BX2-01","p":4,"a":"p4","id":"cr3","src":"assets/audio/BX2-01/cr3.mp3","sec":6.264,"t":"无论高茎作母本还是作父本，也就是正交和反交，结果都一样。"},{"ep":"bx2-01","n":"BX2-01","p":4,"a":"p4","id":"cr4","src":"assets/audio/BX2-01/cr4.mp3","sec":5.616,"t":"孟德尔研究的其他六对相对性状，F2 也都接近 3∶1。"},{"ep":"bx2-01","n":"BX2-01","p":4,"a":"p4","id":"cr5","src":"assets/audio/BX2-01/cr5.mp3","sec":11.568,"t":"考法：F1 只表现显性性状，F2 出现性状分离，比例 3∶1；3∶1 是大量统计的结果，株数少时不一定符合。"},{"ep":"bx2-01","n":"BX2-01","p":5,"a":"p5","id":"ex1","src":"assets/audio/BX2-01/ex1.mp3","sec":12.864,"t":"考点五，孟德尔对分离现象的解释，一共四点。第一，生物的性状是由遗传因子决定的：显性用大写字母、隐性用小写字母表示。"},{"ep":"bx2-01","n":"BX2-01","p":5,"a":"p5","id":"ex2","src":"assets/audio/BX2-01/ex2.mp3","sec":12.168,"t":"第二，在体细胞中，遗传因子是成对存在的。纯种高茎是 DD，纯种矮茎是 dd，F1 是 Dd。"},{"ep":"bx2-01","n":"BX2-01","p":5,"a":"p5","id":"ex3","src":"assets/audio/BX2-01/ex3.mp3","sec":9.312,"t":"第三，形成配子时，成对的遗传因子彼此分离，分别进入不同的配子中，配子只含每对中的一个。"},{"ep":"bx2-01","n":"BX2-01","p":5,"a":"p5","id":"ex4","src":"assets/audio/BX2-01/ex4.mp3","sec":13.248,"t":"第四，受精时，雌雄配子的结合是随机的。所以 F2 是 DD∶Dd∶dd = 1∶2∶1，高茎∶矮茎 = 3∶1。"},{"ep":"bx2-01","n":"BX2-01","p":5,"a":"p5","id":"ex5","src":"assets/audio/BX2-01/ex5.mp3","sec":11.832,"t":"易错：F1 产生的雌配子和雄配子数量并不相等，雄配子远多于雌配子；相等的是 D 和 d 两种配子的比例，1∶1。"},{"ep":"bx2-01","n":"BX2-01","p":6,"a":"p6","id":"si1","src":"assets/audio/BX2-01/si1.mp3","sec":10.704,"t":"考点六，性状分离比的模拟实验。两个小桶分别代表雌、雄生殖器官，桶里的彩球代表雌、雄配子。"},{"ep":"bx2-01","n":"BX2-01","p":6,"a":"p6","id":"si2","src":"assets/audio/BX2-01/si2.mp3","sec":6.96,"t":"从两个桶里各随机抓取一个彩球组合在一起，模拟雌雄配子的随机结合。"},{"ep":"bx2-01","n":"BX2-01","p":6,"a":"p6","id":"si3","src":"assets/audio/BX2-01/si3.mp3","sec":6.792,"t":"每次抓取后要放回原来的小桶并摇匀，重复多次，统计组合的比例。"},{"ep":"bx2-01","n":"BX2-01","p":6,"a":"p6","id":"si4","src":"assets/audio/BX2-01/si4.mp3","sec":9.432,"t":"易错：每个桶内两种彩球数量必须相等；但两个桶的彩球总数可以不同，因为雄配子比雌配子多。"},{"ep":"bx2-01","n":"BX2-01","p":7,"a":"p7","id":"tc1","src":"assets/audio/BX2-01/tc1.mp3","sec":9.864,"t":"考点七，测交实验。测交就是让 F1 与隐性纯合子杂交，也就是 Dd 乘 dd。"},{"ep":"bx2-01","n":"BX2-01","p":7,"a":"p7","id":"tc2","src":"assets/audio/BX2-01/tc2.mp3","sec":9.84,"t":"隐性纯合子只产生一种配子 d，所以后代的表型和比例，直接反映了 F1 产生的配子种类和比例。"},{"ep":"bx2-01","n":"BX2-01","p":7,"a":"p7","id":"tc3","src":"assets/audio/BX2-01/tc3.mp3","sec":9.912,"t":"预期高茎∶矮茎 = 1∶1；实际得到 87 株高茎、79 株矮茎，接近 1∶1，证明解释是正确的。"},{"ep":"bx2-01","n":"BX2-01","p":7,"a":"p7","id":"tc4","src":"assets/audio/BX2-01/tc4.mp3","sec":10.728,"t":"考法：测交能检验 F1 的遗传因子组成，也能检验 F1 产生的配子类型和比例，不能证明雌雄配子数量相等。"},{"ep":"bx2-01","n":"BX2-01","p":8,"a":"p8","id":"me1","src":"assets/audio/BX2-01/me1.mp3","sec":9.096,"t":"考点八，假说—演绎法。第一步，在观察和分析的基础上提出问题：F2 为什么出现 3∶1？"},{"ep":"bx2-01","n":"BX2-01","p":8,"a":"p8","id":"me2","src":"assets/audio/BX2-01/me2.mp3","sec":5.784,"t":"第二步，通过推理和想象提出假说，就是刚才的四点解释。"},{"ep":"bx2-01","n":"BX2-01","p":8,"a":"p8","id":"me3","src":"assets/audio/BX2-01/me3.mp3","sec":10.056,"t":"第三步，演绎推理：如果假说正确，测交后代应该是 1∶1。第四步，实验检验：真的去做测交。"},{"ep":"bx2-01","n":"BX2-01","p":8,"a":"p8","id":"me4","src":"assets/audio/BX2-01/me4.mp3","sec":5.616,"t":"第五步，实验结果和预期相符，得出结论：分离定律。"},{"ep":"bx2-01","n":"BX2-01","p":8,"a":"p8","id":"me5","src":"assets/audio/BX2-01/me5.mp3","sec":8.904,"t":"易错：“演绎推理”是设计测交实验并预测结果，是纸上推理；真正做测交属于实验检验。"},{"ep":"bx2-01","n":"BX2-01","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-01/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-01","n":"BX2-01","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-01/rv2.mp3","sec":6.216,"t":"判断一？对。判断二？错，应在花蕾期去雄。"},{"ep":"bx2-01","n":"BX2-01","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-01/rv3.mp3","sec":9.72,"t":"判断三？对。判断四？错，雄配子远多于雌配子，D 和 d 的比例才是 1∶1。"},{"ep":"bx2-01","n":"BX2-01","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-01/rv4.mp3","sec":10.464,"t":"判断五？错，两个桶的总数可以不同。判断六？错，演绎推理是设计并预测，做实验是检验。"},{"ep":"bx2-01","n":"BX2-01","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-01/rv5.mp3","sec":8.064,"t":"八个考点串成一条线：记住 3∶1 和 1∶1，分清“演绎”和“检验”。我们下期再见！"},{"ep":"bx2-02","n":"BX2-02","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-02/in1.mp3","sec":7.848,"t":"同学们好！这节课梳理人教版必修二第一章第一节的下半部分——分离定律的应用。"},{"ep":"bx2-02","n":"BX2-02","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-02/in2.mp3","sec":7.632,"t":"高考常考显隐性和纯合子的判断、连续自交、自由交配和致死问题的计算。"},{"ep":"bx2-02","n":"BX2-02","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-02/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-02","n":"BX2-02","p":1,"a":"p1","id":"la1","src":"assets/audio/BX2-02/la1.mp3","sec":9.216,"t":"考点一，分离定律的内容：在生物的体细胞中，控制同一性状的遗传因子成对存在，不相融合；"},{"ep":"bx2-02","n":"BX2-02","p":1,"a":"p1","id":"la2","src":"assets/audio/BX2-02/la2.mp3","sec":8.544,"t":"在形成配子时，成对的遗传因子发生分离，分别进入不同的配子中，随配子遗传给后代。"},{"ep":"bx2-02","n":"BX2-02","p":1,"a":"p1","id":"la3","src":"assets/audio/BX2-02/la3.mp3","sec":7.32,"t":"适用范围：真核生物、有性生殖、细胞核遗传，研究的是一对相对性状。"},{"ep":"bx2-02","n":"BX2-02","p":1,"a":"p1","id":"la4","src":"assets/audio/BX2-02/la4.mp3","sec":9.888,"t":"易错：原核生物、病毒和细胞质遗传都不遵循分离定律；分离发生在形成配子时，不是受精时。"},{"ep":"bx2-02","n":"BX2-02","p":2,"a":"p2","id":"do1","src":"assets/audio/BX2-02/do1.mp3","sec":9.528,"t":"考点二，显隐性的判断。定义法：相对性状的纯合亲本杂交，F1 表现出来的就是显性性状。"},{"ep":"bx2-02","n":"BX2-02","p":2,"a":"p2","id":"do2","src":"assets/audio/BX2-02/do2.mp3","sec":8.64,"t":"性状分离法：两个性状相同的亲本交配，后代出现了新的性状，新出现的就是隐性性状。"},{"ep":"bx2-02","n":"BX2-02","p":2,"a":"p2","id":"do3","src":"assets/audio/BX2-02/do3.mp3","sec":5.04,"t":"比例法：后代出现 3∶1，占 3 的是显性性状。"},{"ep":"bx2-02","n":"BX2-02","p":2,"a":"p2","id":"do4","src":"assets/audio/BX2-02/do4.mp3","sec":7.536,"t":"解题方法：一句口诀——无中生有为隐性。“无”是亲本没有，“有”是子代出现。"},{"ep":"bx2-02","n":"BX2-02","p":3,"a":"p3","id":"pu1","src":"assets/audio/BX2-02/pu1.mp3","sec":9.576,"t":"考点三，纯合子与杂合子的鉴定。自交法：后代出现性状分离的是杂合子，不出现的是纯合子。"},{"ep":"bx2-02","n":"BX2-02","p":3,"a":"p3","id":"pu2","src":"assets/audio/BX2-02/pu2.mp3","sec":7.968,"t":"测交法：与隐性纯合子杂交，后代全是显性的是纯合子，出现隐性的是杂合子。"},{"ep":"bx2-02","n":"BX2-02","p":3,"a":"p3","id":"pu3","src":"assets/audio/BX2-02/pu3.mp3","sec":8.52,"t":"花粉鉴定法：比如糯性和非糯性，花粉遇碘呈两种颜色，各占一半，说明是杂合子。"},{"ep":"bx2-02","n":"BX2-02","p":3,"a":"p3","id":"pu4","src":"assets/audio/BX2-02/pu4.mp3","sec":10.32,"t":"考法：问最简便的方法。植物用自交最简便；动物多用测交，并且要多找几只隐性个体，后代才够多。"},{"ep":"bx2-02","n":"BX2-02","p":4,"a":"p4","id":"if1","src":"assets/audio/BX2-02/if1.mp3","sec":8.952,"t":"考点四，由子代推亲代。子代显性∶隐性 = 3∶1，亲代是 Aa × Aa。"},{"ep":"bx2-02","n":"BX2-02","p":4,"a":"p4","id":"if2","src":"assets/audio/BX2-02/if2.mp3","sec":6.048,"t":"子代 1∶1，亲代是 Aa × aa，相当于测交。"},{"ep":"bx2-02","n":"BX2-02","p":4,"a":"p4","id":"if3","src":"assets/audio/BX2-02/if3.mp3","sec":8.184,"t":"子代全是显性，至少一方是 AA；子代全是隐性，双亲都是 aa。"},{"ep":"bx2-02","n":"BX2-02","p":4,"a":"p4","id":"if4","src":"assets/audio/BX2-02/if4.mp3","sec":10.032,"t":"解题方法：隐性纯合突破法——子代出现 aa，说明双亲各提供了一个 a，先把能确定的 a 填进去。"},{"ep":"bx2-02","n":"BX2-02","p":5,"a":"p5","id":"sf1","src":"assets/audio/BX2-02/sf1.mp3","sec":11.112,"t":"考点五，杂合子连续自交。Aa 每自交一代，杂合子就减少一半，Fn 中杂合子占 (1/2)n。"},{"ep":"bx2-02","n":"BX2-02","p":5,"a":"p5","id":"sf2","src":"assets/audio/BX2-02/sf2.mp3","sec":8.736,"t":"纯合子占 1 − (1/2)n，越来越接近 1；显性纯合子和隐性纯合子各占一半。"},{"ep":"bx2-02","n":"BX2-02","p":5,"a":"p5","id":"sf3","src":"assets/audio/BX2-02/sf3.mp3","sec":7.872,"t":"所以三条曲线：杂合子趋近 0，纯合子趋近 1，显性纯合子趋近 1/2。"},{"ep":"bx2-02","n":"BX2-02","p":5,"a":"p5","id":"sf4","src":"assets/audio/BX2-02/sf4.mp3","sec":13.32,"t":"考法：杂交育种靠连续自交提高纯合度。易错：如果每代淘汰隐性个体，Fn 中显性纯合子占 (2n−1)/(2n+1)。"},{"ep":"bx2-02","n":"BX2-02","p":6,"a":"p6","id":"ra1","src":"assets/audio/BX2-02/ra1.mp3","sec":13.32,"t":"考点六，自交与自由交配。例：一个群体中 AA∶Aa = 1∶2，也就是 AA 占 1/3，Aa 占 2/3。"},{"ep":"bx2-02","n":"BX2-02","p":6,"a":"p6","id":"ra2","src":"assets/audio/BX2-02/ra2.mp3","sec":11.52,"t":"自交：只有 Aa 自交会产生 aa，aa = 2/3 × 1/4 = 1/6，后代 AA∶Aa∶aa = 3∶2∶1。"},{"ep":"bx2-02","n":"BX2-02","p":6,"a":"p6","id":"ra3","src":"assets/audio/BX2-02/ra3.mp3","sec":13.2,"t":"自由交配用配子法：A 配子占 2/3，a 配子占 1/3，aa = 1/3 × 1/3 = 1/9，后代 4∶4∶1。"},{"ep":"bx2-02","n":"BX2-02","p":6,"a":"p6","id":"ra4","src":"assets/audio/BX2-02/ra4.mp3","sec":10.008,"t":"易错：自交是同种基因型之间交配；自由交配是所有个体随机交配，用配子法最快，不要逐对相加。"},{"ep":"bx2-02","n":"BX2-02","p":7,"a":"p7","id":"le1","src":"assets/audio/BX2-02/le1.mp3","sec":15.384,"t":"考点七，异常分离比。正常 Aa × Aa 后代是 1∶2∶1。如果显性纯合致死，AA 死掉，剩下 Aa∶aa = 2∶1。"},{"ep":"bx2-02","n":"BX2-02","p":7,"a":"p7","id":"le2","src":"assets/audio/BX2-02/le2.mp3","sec":8.304,"t":"不完全显性：杂合子表现为中间性状，比如红花、粉红花、白花 = 1∶2∶1。"},{"ep":"bx2-02","n":"BX2-02","p":7,"a":"p7","id":"le3","src":"assets/audio/BX2-02/le3.mp3","sec":7.152,"t":"隐性纯合致死：后代只有显性个体，AA∶Aa = 1∶2。"},{"ep":"bx2-02","n":"BX2-02","p":7,"a":"p7","id":"le4","src":"assets/audio/BX2-02/le4.mp3","sec":10.032,"t":"配子致死：比如含 a 的花粉不育，Aa 自交后代 AA∶Aa = 1∶1，全是显性。"},{"ep":"bx2-02","n":"BX2-02","p":7,"a":"p7","id":"le5","src":"assets/audio/BX2-02/le5.mp3","sec":7.296,"t":"解题方法：先按正常的 1∶2∶1 写出来，再划掉致死的部分，重新算比例。"},{"ep":"bx2-02","n":"BX2-02","p":8,"a":"p8","id":"pr1","src":"assets/audio/BX2-02/pr1.mp3","sec":8.664,"t":"考点八，遗传概率计算。系谱图中，双亲正常，生了一个患病女儿——无中生有为隐性。"},{"ep":"bx2-02","n":"BX2-02","p":8,"a":"p8","id":"pr2","src":"assets/audio/BX2-02/pr2.mp3","sec":7.32,"t":"女儿患病而父亲正常，所以是常染色体隐性遗传，双亲都是 Aa。"},{"ep":"bx2-02","n":"BX2-02","p":8,"a":"p8","id":"pr3","src":"assets/audio/BX2-02/pr3.mp3","sec":12.84,"t":"那么她的正常弟弟，是 AA 还是 Aa？在正常个体中 AA∶Aa = 1∶2，所以是携带者的概率是 2/3。"},{"ep":"bx2-02","n":"BX2-02","p":8,"a":"p8","id":"pr4","src":"assets/audio/BX2-02/pr4.mp3","sec":8.448,"t":"如果他和患者 aa 结婚，生出患病孩子的概率是 2/3 × 1/2 = 1/3。"},{"ep":"bx2-02","n":"BX2-02","p":8,"a":"p8","id":"pr5","src":"assets/audio/BX2-02/pr5.mp3","sec":9.288,"t":"易错：已知表型正常时，要在正常个体里算比例，是 2/3，不是 1/2，也不是 1/4。"},{"ep":"bx2-02","n":"BX2-02","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-02/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-02","n":"BX2-02","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-02/rv2.mp3","sec":9.912,"t":"判断一？错，只适用于真核生物有性生殖的细胞核遗传。判断二？错，最简便的是自交。"},{"ep":"bx2-02","n":"BX2-02","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-02/rv3.mp3","sec":10.344,"t":"判断三？对，(1/2)3 = 1/8。判断四？错，自由交配 aa 占 1/9。"},{"ep":"bx2-02","n":"BX2-02","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-02/rv4.mp3","sec":8.208,"t":"判断五？对。判断六？错，正常弟弟是携带者的概率是 2/3。"},{"ep":"bx2-02","n":"BX2-02","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-02/rv5.mp3","sec":7.776,"t":"八个考点串成一条线：先判显隐，再写配子，最后算比例。我们下期再见！"},{"ep":"bx2-03","n":"BX2-03","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-03/in1.mp3","sec":7.752,"t":"同学们好！这节课梳理人教版必修二第一章第二节的上半部分——自由组合定律。"},{"ep":"bx2-03","n":"BX2-03","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-03/in2.mp3","sec":8.016,"t":"高考常考 9∶3∶3∶1 的由来、F2 中各类型的比例、测交验证和定律的实质。"},{"ep":"bx2-03","n":"BX2-03","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-03/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-03","n":"BX2-03","p":1,"a":"p1","id":"ex1","src":"assets/audio/BX2-03/ex1.mp3","sec":9.84,"t":"考点一，两对相对性状的杂交实验。纯种黄色圆粒和纯种绿色皱粒杂交，F1 全是黄色圆粒。"},{"ep":"bx2-03","n":"BX2-03","p":1,"a":"p1","id":"ex2","src":"assets/audio/BX2-03/ex2.mp3","sec":9.504,"t":"F1 自交，F2 出现四种表型：黄圆、黄皱、绿圆、绿皱，数量比接近 9∶3∶3∶1。"},{"ep":"bx2-03","n":"BX2-03","p":1,"a":"p1","id":"ex3","src":"assets/audio/BX2-03/ex3.mp3","sec":5.4,"t":"其中黄皱和绿圆是亲本没有的新组合，叫重组类型。"},{"ep":"bx2-03","n":"BX2-03","p":1,"a":"p1","id":"ex4","src":"assets/audio/BX2-03/ex4.mp3","sec":9.48,"t":"单独看每一对：黄∶绿 = 416∶140，圆∶皱 = 423∶133，都接近 3∶1。"},{"ep":"bx2-03","n":"BX2-03","p":1,"a":"p1","id":"ex5","src":"assets/audio/BX2-03/ex5.mp3","sec":10.536,"t":"考法：每对性状仍遵循分离定律；9∶3∶3∶1 就是 (3∶1) 的平方，说明两对性状的遗传互不干扰。"},{"ep":"bx2-03","n":"BX2-03","p":2,"a":"p2","id":"el1","src":"assets/audio/BX2-03/el1.mp3","sec":16.488,"t":"考点二，对自由组合现象的解释。粒色由 Y 和 y 控制，粒形由 R 和 r 控制，亲本是 YYRR 和 yyrr，F1 是 YyRr。"},{"ep":"bx2-03","n":"BX2-03","p":2,"a":"p2","id":"el2","src":"assets/audio/BX2-03/el2.mp3","sec":7.104,"t":"F1 形成配子时，每对遗传因子彼此分离，不同对的遗传因子自由组合。"},{"ep":"bx2-03","n":"BX2-03","p":2,"a":"p2","id":"el3","src":"assets/audio/BX2-03/el3.mp3","sec":9.912,"t":"所以 F1 产生 YR、Yr、yR、yr 四种配子，比例是 1∶1∶1∶1。"},{"ep":"bx2-03","n":"BX2-03","p":2,"a":"p2","id":"el4","src":"assets/audio/BX2-03/el4.mp3","sec":6.432,"t":"受精时雌雄配子随机结合，结合方式有 4 × 4 = 16 种。"},{"ep":"bx2-03","n":"BX2-03","p":2,"a":"p2","id":"el5","src":"assets/audio/BX2-03/el5.mp3","sec":7.488,"t":"易错：16 是配子的结合方式，不是基因型的种类；F2 的基因型只有 9 种。"},{"ep":"bx2-03","n":"BX2-03","p":3,"a":"p3","id":"f21","src":"assets/audio/BX2-03/f21.mp3","sec":7.08,"t":"考点三，F2 的基因型和表型。用棋盘法把 16 种结合方式列出来。"},{"ep":"bx2-03","n":"BX2-03","p":3,"a":"p3","id":"f22","src":"assets/audio/BX2-03/f22.mp3","sec":9.816,"t":"表型 4 种：双显性黄圆占 9/16，黄皱和绿圆各占 3/16，双隐性绿皱占 1/16。"},{"ep":"bx2-03","n":"BX2-03","p":3,"a":"p3","id":"f23","src":"assets/audio/BX2-03/f23.mp3","sec":10.608,"t":"基因型 9 种：纯合子 4 种，各占 1/16，一共 4/16；双杂合子 YyRr 占 4/16。"},{"ep":"bx2-03","n":"BX2-03","p":3,"a":"p3","id":"f24","src":"assets/audio/BX2-03/f24.mp3","sec":6.0,"t":"黄色圆粒中，纯合子 YYRR 只占 1/9。"},{"ep":"bx2-03","n":"BX2-03","p":3,"a":"p3","id":"f25","src":"assets/audio/BX2-03/f25.mp3","sec":11.808,"t":"易错：重组类型要看亲本。亲本是黄圆和绿皱，重组类型占 3/8；亲本是黄皱和绿圆，重组类型占 5/8。"},{"ep":"bx2-03","n":"BX2-03","p":4,"a":"p4","id":"tc1","src":"assets/audio/BX2-03/tc1.mp3","sec":9.528,"t":"考点四，测交验证。让 F1 YyRr 与双隐性纯合子 yyrr 杂交。"},{"ep":"bx2-03","n":"BX2-03","p":4,"a":"p4","id":"tc2","src":"assets/audio/BX2-03/tc2.mp3","sec":10.128,"t":"yyrr 只产生 yr 一种配子，所以测交后代的表型，就反映了 F1 产生的四种配子。"},{"ep":"bx2-03","n":"BX2-03","p":4,"a":"p4","id":"tc3","src":"assets/audio/BX2-03/tc3.mp3","sec":9.792,"t":"预期黄圆∶黄皱∶绿圆∶绿皱 = 1∶1∶1∶1。孟德尔做了正交和反交，结果都接近 1∶1∶1∶1。"},{"ep":"bx2-03","n":"BX2-03","p":4,"a":"p4","id":"tc4","src":"assets/audio/BX2-03/tc4.mp3","sec":10.488,"t":"考法：测交结果证明 F1 产生了四种比例相等的配子，也就证明了形成配子时不同对的遗传因子自由组合。"},{"ep":"bx2-03","n":"BX2-03","p":5,"a":"p5","id":"lw1","src":"assets/audio/BX2-03/lw1.mp3","sec":7.416,"t":"考点五，自由组合定律：控制不同性状的遗传因子的分离和组合是互不干扰的。"},{"ep":"bx2-03","n":"BX2-03","p":5,"a":"p5","id":"lw2","src":"assets/audio/BX2-03/lw2.mp3","sec":9.096,"t":"在形成配子时，决定同一性状的成对的遗传因子彼此分离，决定不同性状的遗传因子自由组合。"},{"ep":"bx2-03","n":"BX2-03","p":5,"a":"p5","id":"lw3","src":"assets/audio/BX2-03/lw3.mp3","sec":7.2,"t":"分离和组合是同时进行的；自由组合的对象，是控制不同性状的遗传因子。"},{"ep":"bx2-03","n":"BX2-03","p":5,"a":"p5","id":"lw4","src":"assets/audio/BX2-03/lw4.mp3","sec":10.128,"t":"易错：自由组合发生在形成配子时，不是受精时雌雄配子的随机结合；受精时的随机结合不叫自由组合。"},{"ep":"bx2-03","n":"BX2-03","p":6,"a":"p6","id":"su1","src":"assets/audio/BX2-03/su1.mp3","sec":7.152,"t":"考点六，孟德尔获得成功的原因。第一，正确选用实验材料——豌豆。"},{"ep":"bx2-03","n":"BX2-03","p":6,"a":"p6","id":"su2","src":"assets/audio/BX2-03/su2.mp3","sec":5.712,"t":"第二，由一对相对性状到多对相对性状，从简单到复杂。"},{"ep":"bx2-03","n":"BX2-03","p":6,"a":"p6","id":"su3","src":"assets/audio/BX2-03/su3.mp3","sec":4.224,"t":"第三，对实验结果进行统计学分析。"},{"ep":"bx2-03","n":"BX2-03","p":6,"a":"p6","id":"su4","src":"assets/audio/BX2-03/su4.mp3","sec":5.424,"t":"第四，科学地设计了实验程序，运用了假说—演绎法。"},{"ep":"bx2-03","n":"BX2-03","p":6,"a":"p6","id":"su5","src":"assets/audio/BX2-03/su5.mp3","sec":9.216,"t":"考法：常以选择题出现。易错：孟德尔当时并不知道基因和染色体，他提出的是“遗传因子”。"},{"ep":"bx2-03","n":"BX2-03","p":7,"a":"p7","id":"rd1","src":"assets/audio/BX2-03/rd1.mp3","sec":10.344,"t":"考点七，孟德尔遗传规律的再发现。1866 年孟德尔发表论文，1900 年被三位科学家重新发现。"},{"ep":"bx2-03","n":"BX2-03","p":7,"a":"p7","id":"rd2","src":"assets/audio/BX2-03/rd2.mp3","sec":8.136,"t":"1909 年，丹麦的约翰逊把遗传因子改名为基因，并提出了表型和基因型的概念。"},{"ep":"bx2-03","n":"BX2-03","p":7,"a":"p7","id":"rd3","src":"assets/audio/BX2-03/rd3.mp3","sec":9.552,"t":"表型是生物个体表现出来的性状；基因型是与表型有关的基因组成；控制相对性状的基因叫等位基因。"},{"ep":"bx2-03","n":"BX2-03","p":7,"a":"p7","id":"rd4","src":"assets/audio/BX2-03/rd4.mp3","sec":11.496,"t":"易错：表型是基因型和环境共同作用的结果，基因型相同，表型不一定相同；D 和 D 是相同基因，不是等位基因。"},{"ep":"bx2-03","n":"BX2-03","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-03/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-03","n":"BX2-03","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-03/rv2.mp3","sec":12.264,"t":"判断一？错，亲本是黄皱和绿圆时，重组类型占 5/8。判断二？错，配子各 4 种，结合方式才是 16 种。"},{"ep":"bx2-03","n":"BX2-03","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-03/rv3.mp3","sec":7.392,"t":"判断三？错，自由组合发生在形成配子时。判断四？对。"},{"ep":"bx2-03","n":"BX2-03","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-03/rv4.mp3","sec":6.504,"t":"判断五？对。判断六？错，表型还受环境影响。"},{"ep":"bx2-03","n":"BX2-03","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-03/rv5.mp3","sec":7.68,"t":"七个考点串成一条线：两对性状拆开看，每对都是 3∶1。我们下期再见！"},{"ep":"bx2-04","n":"BX2-04","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-04/in1.mp3","sec":8.28,"t":"同学们好！这节课梳理人教版必修二第一章第二节的下半部分——自由组合定律的应用。"},{"ep":"bx2-04","n":"BX2-04","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-04/in2.mp3","sec":8.136,"t":"高考遗传大题几乎都要用它：拆分法、9∶3∶3∶1 的变式、致死和两病概率。"},{"ep":"bx2-04","n":"BX2-04","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-04/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-04","n":"BX2-04","p":1,"a":"p1","id":"sp1","src":"assets/audio/BX2-04/sp1.mp3","sec":13.296,"t":"考点一，拆分法。例：AaBbCc × AaBbcc，求子代中 AAbbCc 的比例。"},{"ep":"bx2-04","n":"BX2-04","p":1,"a":"p1","id":"sp2","src":"assets/audio/BX2-04/sp2.mp3","sec":10.176,"t":"第一步，拆成三个一对相对性状：Aa × Aa，Bb × Bb，Cc × cc。"},{"ep":"bx2-04","n":"BX2-04","p":1,"a":"p1","id":"sp3","src":"assets/audio/BX2-04/sp3.mp3","sec":8.664,"t":"第二步，分别求：AA 占 1/4，bb 占 1/4，Cc 占 1/2。"},{"ep":"bx2-04","n":"BX2-04","p":1,"a":"p1","id":"sp4","src":"assets/audio/BX2-04/sp4.mp3","sec":6.84,"t":"第三步，相乘：1/4 × 1/4 × 1/2 = 1/32。"},{"ep":"bx2-04","n":"BX2-04","p":1,"a":"p1","id":"sp5","src":"assets/audio/BX2-04/sp5.mp3","sec":8.76,"t":"解题方法：先拆后乘。前提是各对基因独立遗传，也就是位于不同对的同源染色体上。"},{"ep":"bx2-04","n":"BX2-04","p":2,"a":"p2","id":"co1","src":"assets/audio/BX2-04/co1.mp3","sec":11.88,"t":"考点二，种类和比例的计算。AaBbCc 产生的配子种类是 23 = 8 种，n 是杂合基因的对数。"},{"ep":"bx2-04","n":"BX2-04","p":2,"a":"p2","id":"co2","src":"assets/audio/BX2-04/co2.mp3","sec":8.928,"t":"某种配子的比例也是相乘：ABC 占 1/2 × 1/2 × 1/2 = 1/8。"},{"ep":"bx2-04","n":"BX2-04","p":2,"a":"p2","id":"co3","src":"assets/audio/BX2-04/co3.mp3","sec":12.024,"t":"AaBbCc × AaBbcc，子代基因型 3 × 3 × 2 = 18 种，表型 2 × 2 × 2 = 8 种。"},{"ep":"bx2-04","n":"BX2-04","p":2,"a":"p2","id":"co4","src":"assets/audio/BX2-04/co4.mp3","sec":12.168,"t":"易错：2n 中的 n 只数杂合的那几对；纯合的一对只产生一种配子，比如 AaBbcc 只有 4 种配子。"},{"ep":"bx2-04","n":"BX2-04","p":3,"a":"p3","id":"if1","src":"assets/audio/BX2-04/if1.mp3","sec":12.264,"t":"考点三，由子代比例推亲代。9∶3∶3∶1 拆成 (3∶1)(3∶1)，亲本是 AaBb × AaBb。"},{"ep":"bx2-04","n":"BX2-04","p":3,"a":"p3","id":"if2","src":"assets/audio/BX2-04/if2.mp3","sec":12.864,"t":"1∶1∶1∶1 拆成 (1∶1)(1∶1)，亲本是 AaBb × aabb 或 Aabb × aaBb。"},{"ep":"bx2-04","n":"BX2-04","p":3,"a":"p3","id":"if3","src":"assets/audio/BX2-04/if3.mp3","sec":13.152,"t":"3∶3∶1∶1 拆成 (3∶1)(1∶1)，亲本是 AaBb × Aabb 或 AaBb × aaBb。"},{"ep":"bx2-04","n":"BX2-04","p":3,"a":"p3","id":"if4","src":"assets/audio/BX2-04/if4.mp3","sec":8.712,"t":"解题方法：把子代比例拆成每对性状的比例，分别反推，再组合；注意可能有两种答案。"},{"ep":"bx2-04","n":"BX2-04","p":4,"a":"p4","id":"va1","src":"assets/audio/BX2-04/va1.mp3","sec":9.336,"t":"考点四，9∶3∶3∶1 的变式，都是 AaBb 自交的结果，只是把某几项合并了。"},{"ep":"bx2-04","n":"BX2-04","p":4,"a":"p4","id":"va2","src":"assets/audio/BX2-04/va2.mp3","sec":10.992,"t":"9∶7：双显性表现一种性状，其余 3 + 3 + 1 合并；9∶6∶1：两种单显性表现相同，3 + 3 合并。"},{"ep":"bx2-04","n":"BX2-04","p":4,"a":"p4","id":"va3","src":"assets/audio/BX2-04/va3.mp3","sec":11.304,"t":"15∶1：只要有显性基因就表现，9 + 3 + 3 合并；12∶3∶1 和 9∶3∶4，分别是 9 + 3、3 + 1 合并。"},{"ep":"bx2-04","n":"BX2-04","p":4,"a":"p4","id":"va4","src":"assets/audio/BX2-04/va4.mp3","sec":14.376,"t":"解题方法：比例之和是 16，就说明是 AaBb 自交、遵循自由组合；测交时按同样方式合并 1∶1∶1∶1，比如 9∶7 对应 1∶3。"},{"ep":"bx2-04","n":"BX2-04","p":5,"a":"p5","id":"le1","src":"assets/audio/BX2-04/le1.mp3","sec":11.592,"t":"考点五，致死问题。AaBb 自交，如果 AA 致死：A 这一对变成 2∶1，B 这一对还是 3∶1。"},{"ep":"bx2-04","n":"BX2-04","p":5,"a":"p5","id":"le2","src":"assets/audio/BX2-04/le2.mp3","sec":4.92,"t":"相乘：(2∶1)(3∶1) = 6∶3∶2∶1。"},{"ep":"bx2-04","n":"BX2-04","p":5,"a":"p5","id":"le3","src":"assets/audio/BX2-04/le3.mp3","sec":7.824,"t":"如果 AA 和 BB 都致死：(2∶1)(2∶1) = 4∶2∶2∶1。"},{"ep":"bx2-04","n":"BX2-04","p":5,"a":"p5","id":"le4","src":"assets/audio/BX2-04/le4.mp3","sec":10.752,"t":"解题方法：看到 6∶3∶2∶1 或 4∶2∶2∶1，就想到显性纯合致死；仍然是先拆成一对一对，再相乘。"},{"ep":"bx2-04","n":"BX2-04","p":6,"a":"p6","id":"tw1","src":"assets/audio/BX2-04/tw1.mp3","sec":9.048,"t":"考点六，两种遗传病的概率。父亲多指，母亲正常，生了一个手指正常但患白化病的孩子。"},{"ep":"bx2-04","n":"BX2-04","p":6,"a":"p6","id":"tw2","src":"assets/audio/BX2-04/tw2.mp3","sec":10.728,"t":"推出父亲 TtAa，母亲 ttAa。再生一个孩子：患多指 1/2，患白化病 1/4。"},{"ep":"bx2-04","n":"BX2-04","p":6,"a":"p6","id":"tw3","src":"assets/audio/BX2-04/tw3.mp3","sec":9.792,"t":"两病兼患 = 1/2 × 1/4 = 1/8；完全正常 = 1/2 × 3/4 = 3/8。"},{"ep":"bx2-04","n":"BX2-04","p":6,"a":"p6","id":"tw4","src":"assets/audio/BX2-04/tw4.mp3","sec":5.544,"t":"只患一种病 = 1 − 3/8 − 1/8 = 1/2。"},{"ep":"bx2-04","n":"BX2-04","p":6,"a":"p6","id":"tw5","src":"assets/audio/BX2-04/tw5.mp3","sec":12.192,"t":"解题方法：先求每种病的患病概率 m 和 n。兼患 = mn，正常 = (1−m)(1−n)，只患一种 = m + n − 2mn。"},{"ep":"bx2-04","n":"BX2-04","p":7,"a":"p7","id":"id1","src":"assets/audio/BX2-04/id1.mp3","sec":14.256,"t":"考点七，判断两对基因是否位于两对同源染色体上。自交法：AaBb 自交，后代 9∶3∶3∶1 或比例之和为 16，就是独立遗传。"},{"ep":"bx2-04","n":"BX2-04","p":7,"a":"p7","id":"id2","src":"assets/audio/BX2-04/id2.mp3","sec":9.0,"t":"测交法：AaBb 测交，后代 1∶1∶1∶1，说明产生了四种比例相等的配子。"},{"ep":"bx2-04","n":"BX2-04","p":7,"a":"p7","id":"id3","src":"assets/audio/BX2-04/id3.mp3","sec":9.456,"t":"如果自交后代是 3∶1 或 1∶2∶1，测交后代是 1∶1，说明两对基因位于一对同源染色体上。"},{"ep":"bx2-04","n":"BX2-04","p":7,"a":"p7","id":"id4","src":"assets/audio/BX2-04/id4.mp3","sec":8.856,"t":"易错：位于一对同源染色体上的两对基因，不遵循自由组合定律，但每一对仍然遵循分离定律。"},{"ep":"bx2-04","n":"BX2-04","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-04/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-04","n":"BX2-04","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-04/rv2.mp3","sec":8.136,"t":"判断一？错，cc 只产生一种配子，共 4 种。判断二？对。"},{"ep":"bx2-04","n":"BX2-04","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-04/rv3.mp3","sec":9.624,"t":"判断三？对。判断四？错，也可能是 AaBb × aaBb。"},{"ep":"bx2-04","n":"BX2-04","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-04/rv4.mp3","sec":10.752,"t":"判断五？错，只患一种是 m + n − 2mn。判断六？错，同源染色体上的非等位基因不遵循。"},{"ep":"bx2-04","n":"BX2-04","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-04/rv5.mp3","sec":6.84,"t":"七个考点串成一条线：先拆成一对一对，再相乘。我们下期再见！"},{"ep":"bx2-05","n":"BX2-05","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-05/in1.mp3","sec":7.464,"t":"同学们好！这节课梳理人教版必修二第二章第一节的上半部分——减数分裂。"},{"ep":"bx2-05","n":"BX2-05","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-05/in2.mp3","sec":8.256,"t":"高考常考同源染色体和四分体、各时期的特点、数量变化曲线和分裂图像的辨析。"},{"ep":"bx2-05","n":"BX2-05","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-05/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-05","n":"BX2-05","p":1,"a":"p1","id":"mc1","src":"assets/audio/BX2-05/mc1.mp3","sec":11.208,"t":"考点一，减数分裂的概念。它是进行有性生殖的生物，在产生成熟生殖细胞时进行的染色体数目减半的细胞分裂。"},{"ep":"bx2-05","n":"BX2-05","p":1,"a":"p1","id":"mc2","src":"assets/audio/BX2-05/mc2.mp3","sec":5.352,"t":"特点：染色体只复制一次，而细胞连续分裂两次。"},{"ep":"bx2-05","n":"BX2-05","p":1,"a":"p1","id":"mc3","src":"assets/audio/BX2-05/mc3.mp3","sec":6.552,"t":"结果：成熟生殖细胞中的染色体数目，比原始生殖细胞减少一半。"},{"ep":"bx2-05","n":"BX2-05","p":1,"a":"p1","id":"mc4","src":"assets/audio/BX2-05/mc4.mp3","sec":11.976,"t":"易错：原核生物和只进行无性生殖的生物不进行减数分裂；产生的生殖细胞不再连续分裂，所以减数分裂没有细胞周期。"},{"ep":"bx2-05","n":"BX2-05","p":2,"a":"p2","id":"ho1","src":"assets/audio/BX2-05/ho1.mp3","sec":12.432,"t":"考点二，同源染色体和四分体。同源染色体是配对的两条染色体，形状和大小一般相同，一条来自父方，一条来自母方。"},{"ep":"bx2-05","n":"BX2-05","p":2,"a":"p2","id":"ho2","src":"assets/audio/BX2-05/ho2.mp3","sec":5.424,"t":"减数分裂Ⅰ前期，同源染色体两两配对，这叫联会。"},{"ep":"bx2-05","n":"BX2-05","p":2,"a":"p2","id":"ho3","src":"assets/audio/BX2-05/ho3.mp3","sec":5.928,"t":"联会后的每对同源染色体含有四条染色单体，叫作四分体。"},{"ep":"bx2-05","n":"BX2-05","p":2,"a":"p2","id":"ho4","src":"assets/audio/BX2-05/ho4.mp3","sec":8.664,"t":"1 个四分体 = 1 对同源染色体 = 2 条染色体 = 4 条染色单体 = 4 个 DNA 分子。"},{"ep":"bx2-05","n":"BX2-05","p":2,"a":"p2","id":"ho5","src":"assets/audio/BX2-05/ho5.mp3","sec":10.704,"t":"易错：同源染色体不是复制形成的，复制形成的是姐妹染色单体；X 和 Y 大小不同，但也是同源染色体。"},{"ep":"bx2-05","n":"BX2-05","p":3,"a":"p3","id":"m11","src":"assets/audio/BX2-05/m11.mp3","sec":12.288,"t":"考点三，减数分裂Ⅰ。间期染色体复制。前期Ⅰ，同源染色体联会形成四分体，非姐妹染色单体之间常发生互换。"},{"ep":"bx2-05","n":"BX2-05","p":3,"a":"p3","id":"m12","src":"assets/audio/BX2-05/m12.mp3","sec":4.968,"t":"中期Ⅰ，同源染色体成对排列在赤道板两侧。"},{"ep":"bx2-05","n":"BX2-05","p":3,"a":"p3","id":"m13","src":"assets/audio/BX2-05/m13.mp3","sec":7.32,"t":"后期Ⅰ，同源染色体分离，非同源染色体自由组合，分别移向细胞两极。"},{"ep":"bx2-05","n":"BX2-05","p":3,"a":"p3","id":"m14","src":"assets/audio/BX2-05/m14.mp3","sec":6.6,"t":"末期Ⅰ，细胞一分为二，形成两个次级精母细胞，染色体数目减半。"},{"ep":"bx2-05","n":"BX2-05","p":3,"a":"p3","id":"m15","src":"assets/audio/BX2-05/m15.mp3","sec":11.688,"t":"易错：染色体数目减半发生在减数分裂Ⅰ，原因是同源染色体分离；减数分裂Ⅰ结束后，细胞中就没有同源染色体了。"},{"ep":"bx2-05","n":"BX2-05","p":4,"a":"p4","id":"m21","src":"assets/audio/BX2-05/m21.mp3","sec":8.664,"t":"考点四，减数分裂Ⅱ。两次分裂之间通常没有间期或间期很短，染色体不再复制。"},{"ep":"bx2-05","n":"BX2-05","p":4,"a":"p4","id":"m22","src":"assets/audio/BX2-05/m22.mp3","sec":4.896,"t":"中期Ⅱ，每条染色体的着丝粒排列在赤道板上。"},{"ep":"bx2-05","n":"BX2-05","p":4,"a":"p4","id":"m23","src":"assets/audio/BX2-05/m23.mp3","sec":6.84,"t":"后期Ⅱ，着丝粒分裂，姐妹染色单体分开，染色体数目暂时加倍。"},{"ep":"bx2-05","n":"BX2-05","p":4,"a":"p4","id":"m24","src":"assets/audio/BX2-05/m24.mp3","sec":5.184,"t":"末期Ⅱ，形成四个精细胞，再经过变形成为精子。"},{"ep":"bx2-05","n":"BX2-05","p":4,"a":"p4","id":"m25","src":"assets/audio/BX2-05/m25.mp3","sec":10.512,"t":"考法：减数分裂Ⅱ和有丝分裂很像，区别是没有同源染色体；后期Ⅱ细胞中的染色体数和体细胞相同。"},{"ep":"bx2-05","n":"BX2-05","p":5,"a":"p5","id":"eg1","src":"assets/audio/BX2-05/eg1.mp3","sec":9.144,"t":"考点五，精子和卵细胞形成的比较。场所：精子在睾丸中形成，卵细胞在卵巢中形成。"},{"ep":"bx2-05","n":"BX2-05","p":5,"a":"p5","id":"eg2","src":"assets/audio/BX2-05/eg2.mp3","sec":7.056,"t":"初级卵母细胞和次级卵母细胞的细胞质不均等分裂，大的那个继续发育。"},{"ep":"bx2-05","n":"BX2-05","p":5,"a":"p5","id":"eg3","src":"assets/audio/BX2-05/eg3.mp3","sec":8.064,"t":"结果：一个精原细胞形成四个精子；一个卵原细胞只形成一个卵细胞和三个极体。"},{"ep":"bx2-05","n":"BX2-05","p":5,"a":"p5","id":"eg4","src":"assets/audio/BX2-05/eg4.mp3","sec":5.448,"t":"精细胞要经过变形才成为精子，卵细胞不需要变形。"},{"ep":"bx2-05","n":"BX2-05","p":5,"a":"p5","id":"eg5","src":"assets/audio/BX2-05/eg5.mp3","sec":12.336,"t":"解题方法：看到细胞质不均等分裂，一定是卵细胞的形成过程；均等分裂的减数分裂Ⅱ细胞，可能是次级精母细胞，也可能是第一极体。"},{"ep":"bx2-05","n":"BX2-05","p":6,"a":"p6","id":"cv1","src":"assets/audio/BX2-05/cv1.mp3","sec":10.584,"t":"考点六，染色体数和核 DNA 数的变化。间期 DNA 复制，核 DNA 由 2n 变为 4n，染色体数不变。"},{"ep":"bx2-05","n":"BX2-05","p":6,"a":"p6","id":"cv2","src":"assets/audio/BX2-05/cv2.mp3","sec":8.496,"t":"减数分裂Ⅰ结束，细胞一分为二：染色体数由 2n 变为 n，核 DNA 由 4n 变为 2n。"},{"ep":"bx2-05","n":"BX2-05","p":6,"a":"p6","id":"cv3","src":"assets/audio/BX2-05/cv3.mp3","sec":9.888,"t":"后期Ⅱ着丝粒分裂，染色体数暂时恢复到 2n；减数分裂Ⅱ结束，染色体数和核 DNA 数都是 n。"},{"ep":"bx2-05","n":"BX2-05","p":6,"a":"p6","id":"cv4","src":"assets/audio/BX2-05/cv4.mp3","sec":11.232,"t":"解题方法：曲线斜着上升是 DNA 复制，竖直下降是细胞一分为二；染色体曲线在后期Ⅱ有一个先升后降的台阶。"},{"ep":"bx2-05","n":"BX2-05","p":7,"a":"p7","id":"id1","src":"assets/audio/BX2-05/id1.mp3","sec":8.832,"t":"考点七，分裂图像的辨析，用“三看”。一看有没有同源染色体：没有，就是减数分裂Ⅱ。"},{"ep":"bx2-05","n":"BX2-05","p":7,"a":"p7","id":"id2","src":"assets/audio/BX2-05/id2.mp3","sec":9.384,"t":"二看有没有同源染色体的特殊行为——联会、四分体、同源染色体分离：有，就是减数分裂Ⅰ。"},{"ep":"bx2-05","n":"BX2-05","p":7,"a":"p7","id":"id3","src":"assets/audio/BX2-05/id3.mp3","sec":6.168,"t":"三看：有同源染色体，但没有这些特殊行为，就是有丝分裂。"},{"ep":"bx2-05","n":"BX2-05","p":7,"a":"p7","id":"id4","src":"assets/audio/BX2-05/id4.mp3","sec":9.744,"t":"易错：有丝分裂全程都有同源染色体，只是不联会；判断时先找形状、大小相同的两条染色体。"},{"ep":"bx2-05","n":"BX2-05","p":8,"a":"p8","id":"ga1","src":"assets/audio/BX2-05/ga1.mp3","sec":14.736,"t":"考点八，配子的种类。一个 AaBb 的精原细胞，不考虑互换，产生 4 个精子，只有 2 种：AB 和 ab，或 Ab 和 aB。"},{"ep":"bx2-05","n":"BX2-05","p":8,"a":"p8","id":"ga2","src":"assets/audio/BX2-05/ga2.mp3","sec":4.656,"t":"一个卵原细胞只产生 1 个卵细胞，所以只有 1 种。"},{"ep":"bx2-05","n":"BX2-05","p":8,"a":"p8","id":"ga3","src":"assets/audio/BX2-05/ga3.mp3","sec":9.816,"t":"而一个 AaBb 的个体有许多精原细胞，可以产生 4 种配子；n 对杂合基因就是 2n 种。"},{"ep":"bx2-05","n":"BX2-05","p":8,"a":"p8","id":"ga4","src":"assets/audio/BX2-05/ga4.mp3","sec":7.992,"t":"易错：分清“一个细胞”和“一个个体”；如果考虑互换，一个精原细胞可以产生 4 种精子。"},{"ep":"bx2-05","n":"BX2-05","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-05/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-05","n":"BX2-05","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-05/rv2.mp3","sec":11.16,"t":"判断一？错，四分体是一对同源染色体，含四条染色单体。判断二？错，减半发生在减数分裂Ⅰ。"},{"ep":"bx2-05","n":"BX2-05","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-05/rv3.mp3","sec":6.312,"t":"判断三？对。判断四？错，也可能是第一极体。"},{"ep":"bx2-05","n":"BX2-05","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-05/rv4.mp3","sec":8.952,"t":"判断五？错，只产生 2 种。判断六？对，有丝分裂全程都有同源染色体。"},{"ep":"bx2-05","n":"BX2-05","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-05/rv5.mp3","sec":6.768,"t":"八个考点串成一条线：减Ⅰ分同源，减Ⅱ分姐妹。我们下期再见！"},{"ep":"bx2-06","n":"BX2-06","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-06/in1.mp3","sec":8.568,"t":"同学们好！这节课梳理人教版必修二第二章第一节的下半部分——观察实验与受精作用。"},{"ep":"bx2-06","n":"BX2-06","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-06/in2.mp3","sec":7.488,"t":"高考常考实验材料的选择、受精作用、配子多样性的原因和异常配子的分析。"},{"ep":"bx2-06","n":"BX2-06","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-06/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-06","n":"BX2-06","p":1,"a":"p1","id":"ob1","src":"assets/audio/BX2-06/ob1.mp3","sec":7.368,"t":"考点一，观察蝗虫精母细胞减数分裂装片。材料选雄性蝗虫的精巢。"},{"ep":"bx2-06","n":"BX2-06","p":1,"a":"p1","id":"ob2","src":"assets/audio/BX2-06/ob2.mp3","sec":11.208,"t":"原因：精巢中进行减数分裂的细胞数量多；而卵巢中卵原细胞少，减数分裂Ⅱ要受精时才完成，过程不完整。"},{"ep":"bx2-06","n":"BX2-06","p":1,"a":"p1","id":"ob3","src":"assets/audio/BX2-06/ob3.mp3","sec":8.4,"t":"步骤：先在低倍镜下找到初级精母细胞、次级精母细胞和精细胞，再换高倍镜观察。"},{"ep":"bx2-06","n":"BX2-06","p":1,"a":"p1","id":"ob4","src":"assets/audio/BX2-06/ob4.mp3","sec":5.712,"t":"依据染色体的形态、位置和数目，判断细胞处于哪个时期。"},{"ep":"bx2-06","n":"BX2-06","p":1,"a":"p1","id":"ob5","src":"assets/audio/BX2-06/ob5.mp3","sec":9.6,"t":"易错：装片中的细胞已经死亡，看不到一个细胞连续分裂的动态过程，只能观察不同细胞所处的不同时期。"},{"ep":"bx2-06","n":"BX2-06","p":2,"a":"p2","id":"mo1","src":"assets/audio/BX2-06/mo1.mp3","sec":10.56,"t":"考点二，建立减数分裂中染色体变化的模型。用橡皮泥做染色体，两种颜色分别代表来自父方和母方。"},{"ep":"bx2-06","n":"BX2-06","p":2,"a":"p2","id":"mo2","src":"assets/audio/BX2-06/mo2.mp3","sec":9.696,"t":"长短不同的代表非同源染色体；两条同样颜色、同样长短的并在一起，代表复制后的姐妹染色单体。"},{"ep":"bx2-06","n":"BX2-06","p":2,"a":"p2","id":"mo3","src":"assets/audio/BX2-06/mo3.mp3","sec":9.168,"t":"在纸上画出纺锤体，把模型摆在上面，依次模拟联会、同源染色体分离、着丝粒分裂等变化。"},{"ep":"bx2-06","n":"BX2-06","p":2,"a":"p2","id":"mo4","src":"assets/audio/BX2-06/mo4.mp3","sec":8.088,"t":"考法：模拟非同源染色体的自由组合，至少需要两对同源染色体；这是物理模型。"},{"ep":"bx2-06","n":"BX2-06","p":3,"a":"p3","id":"fe1","src":"assets/audio/BX2-06/fe1.mp3","sec":7.272,"t":"考点三，受精作用：卵细胞和精子相互识别、融合成为受精卵的过程。"},{"ep":"bx2-06","n":"BX2-06","p":3,"a":"p3","id":"fe2","src":"assets/audio/BX2-06/fe2.mp3","sec":10.536,"t":"精子的头部进入卵细胞，卵细胞膜立即发生反应，阻止其他精子进入；然后精子的细胞核与卵细胞的细胞核融合。"},{"ep":"bx2-06","n":"BX2-06","p":3,"a":"p3","id":"fe3","src":"assets/audio/BX2-06/fe3.mp3","sec":8.424,"t":"受精卵中的染色体，一半来自精子，一半来自卵细胞，染色体数目恢复到体细胞的数目。"},{"ep":"bx2-06","n":"BX2-06","p":3,"a":"p3","id":"fe4","src":"assets/audio/BX2-06/fe4.mp3","sec":12.192,"t":"易错：受精卵中的细胞质几乎全部来自卵细胞，所以说遗传物质“一半来自父方、一半来自母方”是错的，只能说核遗传物质各一半。"},{"ep":"bx2-06","n":"BX2-06","p":4,"a":"p4","id":"me1","src":"assets/audio/BX2-06/me1.mp3","sec":11.856,"t":"考点四，减数分裂和受精作用的意义。亲代 2n 经减数分裂产生 n 的配子，配子经受精作用形成 2n 的受精卵。"},{"ep":"bx2-06","n":"BX2-06","p":4,"a":"p4","id":"me2","src":"assets/audio/BX2-06/me2.mp3","sec":6.48,"t":"所以二者共同维持了每种生物前后代体细胞中染色体数目的恒定。"},{"ep":"bx2-06","n":"BX2-06","p":4,"a":"p4","id":"me3","src":"assets/audio/BX2-06/me3.mp3","sec":10.128,"t":"同时，减数分裂产生多样的配子，受精时配子随机结合，使后代呈现多样性，有利于适应多变的环境。"},{"ep":"bx2-06","n":"BX2-06","p":4,"a":"p4","id":"me4","src":"assets/audio/BX2-06/me4.mp3","sec":10.416,"t":"考法：对生物的遗传和变异都十分重要。易错：受精卵之后的个体发育靠的是有丝分裂，不是减数分裂。"},{"ep":"bx2-06","n":"BX2-06","p":5,"a":"p5","id":"dv1","src":"assets/audio/BX2-06/dv1.mp3","sec":12.0,"t":"考点五，配子多样性的原因。第一，减数分裂Ⅰ后期，非同源染色体自由组合。两对同源染色体就有两种排列方式。"},{"ep":"bx2-06","n":"BX2-06","p":5,"a":"p5","id":"dv2","src":"assets/audio/BX2-06/dv2.mp3","sec":8.52,"t":"n 对同源染色体，就能产生 2n 种配子，人有 23 对，就是 223 种。"},{"ep":"bx2-06","n":"BX2-06","p":5,"a":"p5","id":"dv3","src":"assets/audio/BX2-06/dv3.mp3","sec":9.312,"t":"第二，减数分裂Ⅰ前期，四分体中的非姐妹染色单体之间常发生互换，进一步增加了配子的种类。"},{"ep":"bx2-06","n":"BX2-06","p":5,"a":"p5","id":"dv4","src":"assets/audio/BX2-06/dv4.mp3","sec":11.52,"t":"易错：互换发生在非姐妹染色单体之间，不是姐妹染色单体；再加上受精时卵细胞和精子随机结合，后代就更加多样。"},{"ep":"bx2-06","n":"BX2-06","p":6,"a":"p6","id":"ab1","src":"assets/audio/BX2-06/ab1.mp3","sec":13.68,"t":"考点六，异常配子分析，以 XXY 为例。父方减数分裂Ⅰ时 X 和 Y 没有分离，产生 XY 精子，与 X 卵细胞结合，得到 XXY。"},{"ep":"bx2-06","n":"BX2-06","p":6,"a":"p6","id":"ab2","src":"assets/audio/BX2-06/ab2.mp3","sec":8.832,"t":"母方减数分裂Ⅰ或减数分裂Ⅱ异常，产生 XX 卵细胞，与 Y 精子结合，也得到 XXY。"},{"ep":"bx2-06","n":"BX2-06","p":6,"a":"p6","id":"ab3","src":"assets/audio/BX2-06/ab3.mp3","sec":12.288,"t":"例：色觉正常的夫妇生了一个色盲的 X[b]X[b]Y 男孩，X[b]X[b] 只能来自母亲 X[B]X[b] 的减数分裂Ⅱ异常。"},{"ep":"bx2-06","n":"BX2-06","p":6,"a":"p6","id":"ab4","src":"assets/audio/BX2-06/ab4.mp3","sec":7.296,"t":"而 XYY 的男孩，多出来的是两条相同的 Y，来自父方的减数分裂Ⅱ异常。"},{"ep":"bx2-06","n":"BX2-06","p":6,"a":"p6","id":"ab5","src":"assets/audio/BX2-06/ab5.mp3","sec":14.832,"t":"解题方法：异常配子含一对同源染色体，比如 XY、Aa，是减数分裂Ⅰ异常；含两条相同染色体，比如 YY、AA，是减数分裂Ⅱ异常。"},{"ep":"bx2-06","n":"BX2-06","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-06/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-06","n":"BX2-06","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-06/rv2.mp3","sec":8.592,"t":"判断一？错，应选雄性的精巢。判断二？错，细胞质几乎都来自卵细胞。"},{"ep":"bx2-06","n":"BX2-06","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-06/rv3.mp3","sec":6.624,"t":"判断三？对。判断四？错，是非姐妹染色单体。"},{"ep":"bx2-06","n":"BX2-06","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-06/rv4.mp3","sec":8.544,"t":"判断五？对。判断六？错，YY 精子来自父方减数分裂Ⅱ异常。"},{"ep":"bx2-06","n":"BX2-06","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-06/rv5.mp3","sec":7.608,"t":"六个考点串成一条线：一对同源看减Ⅰ，两条相同看减Ⅱ。我们下期再见！"},{"ep":"bx2-07","n":"BX2-07","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-07/in1.mp3","sec":7.224,"t":"同学们好！这节课梳理人教版必修二第二章第二节——基因在染色体上。"},{"ep":"bx2-07","n":"BX2-07","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-07/in2.mp3","sec":7.32,"t":"高考常考萨顿的假说、摩尔根的果蝇杂交实验和孟德尔遗传规律的现代解释。"},{"ep":"bx2-07","n":"BX2-07","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-07/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-07","n":"BX2-07","p":1,"a":"p1","id":"su1","src":"assets/audio/BX2-07/su1.mp3","sec":8.088,"t":"考点一，萨顿的假说。他发现，基因和染色体的行为存在着明显的平行关系。"},{"ep":"bx2-07","n":"BX2-07","p":1,"a":"p1","id":"su2","src":"assets/audio/BX2-07/su2.mp3","sec":9.168,"t":"基因在杂交中保持完整性和独立性，染色体在配子形成和受精中也有相对稳定的形态结构。"},{"ep":"bx2-07","n":"BX2-07","p":1,"a":"p1","id":"su3","src":"assets/audio/BX2-07/su3.mp3","sec":10.536,"t":"在体细胞中，基因成对存在，染色体也成对；在配子中，只有成对基因中的一个，也只有成对染色体中的一条。"},{"ep":"bx2-07","n":"BX2-07","p":1,"a":"p1","id":"su4","src":"assets/audio/BX2-07/su4.mp3","sec":11.304,"t":"成对的基因一个来自父方、一个来自母方，同源染色体也是；非等位基因和非同源染色体在形成配子时都自由组合。"},{"ep":"bx2-07","n":"BX2-07","p":1,"a":"p1","id":"su5","src":"assets/audio/BX2-07/su5.mp3","sec":8.472,"t":"所以萨顿推论：基因是由染色体携带着从亲代传递给下一代的，也就是基因在染色体上。"},{"ep":"bx2-07","n":"BX2-07","p":2,"a":"p2","id":"mt1","src":"assets/audio/BX2-07/mt1.mp3","sec":10.152,"t":"考点二，两种科学方法。萨顿用的是类比推理：根据两类事物的相似之处，推出它们在其他方面也相似。"},{"ep":"bx2-07","n":"BX2-07","p":2,"a":"p2","id":"mt2","src":"assets/audio/BX2-07/mt2.mp3","sec":5.184,"t":"类比推理得出的结论不一定正确，还需要实验来检验。"},{"ep":"bx2-07","n":"BX2-07","p":2,"a":"p2","id":"mt3","src":"assets/audio/BX2-07/mt3.mp3","sec":6.984,"t":"摩尔根用的是假说—演绎法，通过果蝇杂交实验，证明了基因在染色体上。"},{"ep":"bx2-07","n":"BX2-07","p":2,"a":"p2","id":"mt4","src":"assets/audio/BX2-07/mt4.mp3","sec":10.824,"t":"考法：判断科学家用的方法。易错：萨顿提出假说，摩尔根证明假说；摩尔根起初并不相信孟德尔和萨顿。"},{"ep":"bx2-07","n":"BX2-07","p":3,"a":"p3","id":"mg1","src":"assets/audio/BX2-07/mg1.mp3","sec":10.44,"t":"考点三，摩尔根的果蝇杂交实验。果蝇易饲养、繁殖快、子代多，相对性状易区分，染色体只有 4 对。"},{"ep":"bx2-07","n":"BX2-07","p":3,"a":"p3","id":"mg2","src":"assets/audio/BX2-07/mg2.mp3","sec":7.128,"t":"红眼雌果蝇和白眼雄果蝇杂交，F1 全是红眼，说明红眼是显性。"},{"ep":"bx2-07","n":"BX2-07","p":3,"a":"p3","id":"mg3","src":"assets/audio/BX2-07/mg3.mp3","sec":6.216,"t":"F1 雌雄交配，F2 红眼∶白眼 = 3∶1，符合分离定律。"},{"ep":"bx2-07","n":"BX2-07","p":3,"a":"p3","id":"mg4","src":"assets/audio/BX2-07/mg4.mp3","sec":9.648,"t":"但奇怪的是，F2 的白眼果蝇全是雄性——眼色的遗传与性别相关联。这就是摩尔根要解释的问题。"},{"ep":"bx2-07","n":"BX2-07","p":4,"a":"p4","id":"ex1","src":"assets/audio/BX2-07/ex1.mp3","sec":9.816,"t":"考点四，摩尔根的解释：控制白眼的基因 w 位于 X 染色体上，而 Y 染色体上没有它的等位基因。"},{"ep":"bx2-07","n":"BX2-07","p":4,"a":"p4","id":"ex2","src":"assets/audio/BX2-07/ex2.mp3","sec":11.064,"t":"亲本是 X[W]X[W] 和 X[w]Y，F1 是 X[W]X[w] 和 X[W]Y，都是红眼。"},{"ep":"bx2-07","n":"BX2-07","p":4,"a":"p4","id":"ex3","src":"assets/audio/BX2-07/ex3.mp3","sec":9.432,"t":"F1 雌雄交配，F2 中雌果蝇都是红眼，雄果蝇一半红眼、一半白眼，白眼只出现在雄性中。"},{"ep":"bx2-07","n":"BX2-07","p":4,"a":"p4","id":"ex4","src":"assets/audio/BX2-07/ex4.mp3","sec":11.832,"t":"考法：写遗传图解时，伴性遗传的基因要写成 X 的右上角，比如 X[W]，雄性写成 X[w]Y，Y 上没有基因。"},{"ep":"bx2-07","n":"BX2-07","p":5,"a":"p5","id":"tc1","src":"assets/audio/BX2-07/tc1.mp3","sec":11.616,"t":"考点五，测交验证。F1 红眼雌蝇和白眼雄蝇测交，后代红眼雌、白眼雌、红眼雄、白眼雄各占四分之一。"},{"ep":"bx2-07","n":"BX2-07","p":5,"a":"p5","id":"tc2","src":"assets/audio/BX2-07/tc2.mp3","sec":9.0,"t":"这个结果分不清基因在常染色体上还是 X 染色体上，因为常染色体遗传也是 1∶1∶1∶1。"},{"ep":"bx2-07","n":"BX2-07","p":5,"a":"p5","id":"tc3","src":"assets/audio/BX2-07/tc3.mp3","sec":11.688,"t":"关键的一组：白眼雌蝇和红眼雄蝇杂交，X[w]X[w] 乘 X[W]Y，后代雌蝇全红眼、雄蝇全白眼。"},{"ep":"bx2-07","n":"BX2-07","p":5,"a":"p5","id":"tc4","src":"assets/audio/BX2-07/tc4.mp3","sec":10.584,"t":"解题方法：判断基因在 X 上还是常染色体上，选隐性雌性 × 显性雄性，看子代性状是否与性别相关联。"},{"ep":"bx2-07","n":"BX2-07","p":6,"a":"p6","id":"li1","src":"assets/audio/BX2-07/li1.mp3","sec":12.888,"t":"考点六，基因在染色体上呈线性排列。摩尔根和他的学生发明了测定基因位置的方法，绘出了果蝇各种基因在染色体上的相对位置图。"},{"ep":"bx2-07","n":"BX2-07","p":6,"a":"p6","id":"li2","src":"assets/audio/BX2-07/li2.mp3","sec":10.68,"t":"比如果蝇的 X 染色体上，有黄身、白眼、红宝石眼、截翅、朱红眼、深红眼、棒状眼、短硬毛等基因。"},{"ep":"bx2-07","n":"BX2-07","p":6,"a":"p6","id":"li3","src":"assets/audio/BX2-07/li3.mp3","sec":6.384,"t":"现代技术还可以用荧光标记，直接看到基因在染色体上的位置。"},{"ep":"bx2-07","n":"BX2-07","p":6,"a":"p6","id":"li4","src":"assets/audio/BX2-07/li4.mp3","sec":9.432,"t":"易错：一条染色体上有许多基因；同一条染色体上的这些基因是非等位基因，它们不能自由组合。"},{"ep":"bx2-07","n":"BX2-07","p":7,"a":"p7","id":"mo1","src":"assets/audio/BX2-07/mo1.mp3","sec":12.144,"t":"考点七，孟德尔遗传规律的现代解释。分离定律的实质：杂合子细胞中，位于一对同源染色体上的等位基因具有一定的独立性；"},{"ep":"bx2-07","n":"BX2-07","p":7,"a":"p7","id":"mo2","src":"assets/audio/BX2-07/mo2.mp3","sec":8.112,"t":"减数分裂形成配子时，等位基因随同源染色体的分开而分离，分别进入两个配子中。"},{"ep":"bx2-07","n":"BX2-07","p":7,"a":"p7","id":"mo3","src":"assets/audio/BX2-07/mo3.mp3","sec":7.92,"t":"自由组合定律的实质：位于非同源染色体上的非等位基因的分离或组合是互不干扰的；"},{"ep":"bx2-07","n":"BX2-07","p":7,"a":"p7","id":"mo4","src":"assets/audio/BX2-07/mo4.mp3","sec":9.216,"t":"减数分裂中，同源染色体上的等位基因彼此分离的同时，非同源染色体上的非等位基因自由组合。"},{"ep":"bx2-07","n":"BX2-07","p":7,"a":"p7","id":"mo5","src":"assets/audio/BX2-07/mo5.mp3","sec":8.928,"t":"易错：两个定律都发生在减数分裂Ⅰ后期；同源染色体上的非等位基因不遵循自由组合定律。"},{"ep":"bx2-07","n":"BX2-07","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-07/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-07","n":"BX2-07","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-07/rv2.mp3","sec":7.656,"t":"判断一？错，萨顿只是提出假说，摩尔根证明。判断二？对。"},{"ep":"bx2-07","n":"BX2-07","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-07/rv3.mp3","sec":7.8,"t":"判断三？对，雌全红、雄全白。判断四？错，有许多基因。"},{"ep":"bx2-07","n":"BX2-07","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-07/rv4.mp3","sec":9.888,"t":"判断五？错，只有非同源染色体上的非等位基因才能。判断六？错，是减数分裂Ⅰ后期。"},{"ep":"bx2-07","n":"BX2-07","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-07/rv5.mp3","sec":6.576,"t":"七个考点串成一条线：萨顿提出，摩尔根证明。我们下期再见！"},{"ep":"bx2-08","n":"BX2-08","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-08/in1.mp3","sec":6.696,"t":"同学们好！这节课梳理人教版必修二第二章第三节——伴性遗传。"},{"ep":"bx2-08","n":"BX2-08","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-08/in2.mp3","sec":7.608,"t":"这是遗传大题的重点：伴性遗传的特点、系谱图判断、概率计算和实验设计。"},{"ep":"bx2-08","n":"BX2-08","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-08/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-08","n":"BX2-08","p":1,"a":"p1","id":"sd1","src":"assets/audio/BX2-08/sd1.mp3","sec":8.592,"t":"考点一，伴性遗传：位于性染色体上的基因控制的性状，在遗传上总是和性别相关联。"},{"ep":"bx2-08","n":"BX2-08","p":1,"a":"p1","id":"sd2","src":"assets/audio/BX2-08/sd2.mp3","sec":8.88,"t":"XY 型性别决定：雌性是 XX，雄性是 XY，比如人、果蝇和大多数雌雄异株的植物。"},{"ep":"bx2-08","n":"BX2-08","p":1,"a":"p1","id":"sd3","src":"assets/audio/BX2-08/sd3.mp3","sec":7.344,"t":"ZW 型性别决定：雌性是 ZW，雄性是 ZZ，比如鸟类和蛾蝶类。"},{"ep":"bx2-08","n":"BX2-08","p":1,"a":"p1","id":"sd4","src":"assets/audio/BX2-08/sd4.mp3","sec":8.808,"t":"易错：性染色体上的基因不一定决定性别，比如色盲基因；雌雄同株的植物没有性染色体。"},{"ep":"bx2-08","n":"BX2-08","p":2,"a":"p2","id":"cb1","src":"assets/audio/BX2-08/cb1.mp3","sec":9.672,"t":"考点二，人类红绿色盲。色盲基因 b 是隐性的，位于 X 染色体上，Y 上没有它的等位基因。"},{"ep":"bx2-08","n":"BX2-08","p":2,"a":"p2","id":"cb2","src":"assets/audio/BX2-08/cb2.mp3","sec":10.464,"t":"女性有三种基因型：X[B]X[B] 正常，X[B]X[b] 正常但是携带者，X[b]X[b] 色盲。"},{"ep":"bx2-08","n":"BX2-08","p":2,"a":"p2","id":"cb3","src":"assets/audio/BX2-08/cb3.mp3","sec":5.28,"t":"男性只有两种：X[B]Y 正常，X[b]Y 色盲。"},{"ep":"bx2-08","n":"BX2-08","p":2,"a":"p2","id":"cb4","src":"assets/audio/BX2-08/cb4.mp3","sec":8.304,"t":"例：携带者女性和正常男性婚配，女儿全部正常，一半是携带者；儿子一半色盲。"},{"ep":"bx2-08","n":"BX2-08","p":2,"a":"p2","id":"cb5","src":"assets/audio/BX2-08/cb5.mp3","sec":7.848,"t":"考法：写遗传图解、算概率。易错：色盲男孩的致病基因一定来自母亲。"},{"ep":"bx2-08","n":"BX2-08","p":3,"a":"p3","id":"xr1","src":"assets/audio/BX2-08/xr1.mp3","sec":9.672,"t":"考点三，伴 X 隐性遗传的特点。第一，男性患者多于女性，因为男性只要一个 X[b] 就患病。"},{"ep":"bx2-08","n":"BX2-08","p":3,"a":"p3","id":"xr2","src":"assets/audio/BX2-08/xr2.mp3","sec":10.224,"t":"第二，交叉遗传：男性的致病基因只能来自母亲，以后只能传给女儿。常常外祖父患病，外孙患病。"},{"ep":"bx2-08","n":"BX2-08","p":3,"a":"p3","id":"xr3","src":"assets/audio/BX2-08/xr3.mp3","sec":9.432,"t":"第三，女病，父子必病：女患者是 X[b]X[b]，一个 X[b] 来自父亲，又一定传给儿子。"},{"ep":"bx2-08","n":"BX2-08","p":3,"a":"p3","id":"xr4","src":"assets/audio/BX2-08/xr4.mp3","sec":8.016,"t":"解题方法：系谱图中，如果有女患者的父亲或儿子正常，就一定不是伴 X 隐性遗传。"},{"ep":"bx2-08","n":"BX2-08","p":4,"a":"p4","id":"xd1","src":"assets/audio/BX2-08/xd1.mp3","sec":8.616,"t":"考点四，伴 X 显性遗传，例如抗维生素 D 佝偻病，致病基因 D 位于 X 染色体上。"},{"ep":"bx2-08","n":"BX2-08","p":4,"a":"p4","id":"xd2","src":"assets/audio/BX2-08/xd2.mp3","sec":13.416,"t":"特点一：女性患者多于男性，因为女性只要有一个 X[D] 就患病；但部分女性患者病症较轻，X[D]X[d] 比 X[D]X[D] 发病轻。"},{"ep":"bx2-08","n":"BX2-08","p":4,"a":"p4","id":"xd3","src":"assets/audio/BX2-08/xd3.mp3","sec":4.464,"t":"特点二：往往连续遗传，代代都有患者。"},{"ep":"bx2-08","n":"BX2-08","p":4,"a":"p4","id":"xd4","src":"assets/audio/BX2-08/xd4.mp3","sec":8.376,"t":"特点三：男病，母女必病：男患者 X[D]Y 的 X[D] 来自母亲，又一定传给女儿。"},{"ep":"bx2-08","n":"BX2-08","p":4,"a":"p4","id":"xd5","src":"assets/audio/BX2-08/xd5.mp3","sec":8.016,"t":"解题方法：系谱图中，如果有男患者的母亲或女儿正常，就一定不是伴 X 显性遗传。"},{"ep":"bx2-08","n":"BX2-08","p":5,"a":"p5","id":"yl1","src":"assets/audio/BX2-08/yl1.mp3","sec":9.144,"t":"考点五，伴 Y 遗传。致病基因只位于 Y 染色体上，患者全是男性，父传子、子传孙。"},{"ep":"bx2-08","n":"BX2-08","p":5,"a":"p5","id":"yl2","src":"assets/audio/BX2-08/yl2.mp3","sec":7.392,"t":"X 和 Y 大小不同：有同源区段，上面有等位基因；也有各自的非同源区段。"},{"ep":"bx2-08","n":"BX2-08","p":5,"a":"p5","id":"yl3","src":"assets/audio/BX2-08/yl3.mp3","sec":12.864,"t":"位于 X、Y 同源区段上的基因，遗传也和性别相关联。例：X[a]X[a] 乘 X[a]Y[A]，后代雄性全显性、雌性全隐性。"},{"ep":"bx2-08","n":"BX2-08","p":5,"a":"p5","id":"yl4","src":"assets/audio/BX2-08/yl4.mp3","sec":13.2,"t":"易错：同源区段上的基因，男性的基因型要在 X 和 Y 上各写一个，如 X[a]Y[A]；它的遗传也和性别相关联，不等同于常染色体遗传。"},{"ep":"bx2-08","n":"BX2-08","p":6,"a":"p6","id":"ch1","src":"assets/audio/BX2-08/ch1.mp3","sec":9.672,"t":"考点六，伴性遗传在实践中的应用。鸡是 ZW 型，芦花基因 B 是显性，位于 Z 染色体上。"},{"ep":"bx2-08","n":"BX2-08","p":6,"a":"p6","id":"ch2","src":"assets/audio/BX2-08/ch2.mp3","sec":6.096,"t":"选非芦花雄鸡 Z[b]Z[b] 和芦花雌鸡 Z[B]W 杂交。"},{"ep":"bx2-08","n":"BX2-08","p":6,"a":"p6","id":"ch3","src":"assets/audio/BX2-08/ch3.mp3","sec":11.256,"t":"子代雄鸡都是 Z[B]Z[b]，全是芦花；雌鸡都是 Z[b]W，全是非芦花。雏鸡时就能按羽毛分出雌雄。"},{"ep":"bx2-08","n":"BX2-08","p":6,"a":"p6","id":"ch4","src":"assets/audio/BX2-08/ch4.mp3","sec":8.328,"t":"解题方法：ZW 型选“隐性雄 × 显性雌”；XY 型反过来，选“隐性雌 × 显性雄”。"},{"ep":"bx2-08","n":"BX2-08","p":7,"a":"p7","id":"pd1","src":"assets/audio/BX2-08/pd1.mp3","sec":8.904,"t":"考点七，系谱图中遗传方式的判断。第一步，看是否伴 Y：患者全是男性、父子相传。"},{"ep":"bx2-08","n":"BX2-08","p":7,"a":"p7","id":"pd2","src":"assets/audio/BX2-08/pd2.mp3","sec":5.856,"t":"第二步，判断显隐：无中生有为隐性，有中生无为显性。"},{"ep":"bx2-08","n":"BX2-08","p":7,"a":"p7","id":"pd3","src":"assets/audio/BX2-08/pd3.mp3","sec":9.816,"t":"第三步，隐性看女病：女病而父或子正常，是常染色体隐性；女病父子都病，可能是伴 X 隐性。"},{"ep":"bx2-08","n":"BX2-08","p":7,"a":"p7","id":"pd4","src":"assets/audio/BX2-08/pd4.mp3","sec":9.048,"t":"显性看男病：男病而母或女正常，是常染色体显性；男病母女都病，可能是伴 X 显性。"},{"ep":"bx2-08","n":"BX2-08","p":7,"a":"p7","id":"pd5","src":"assets/audio/BX2-08/pd5.mp3","sec":9.144,"t":"解题方法：口诀——无中生有为隐性，隐性遗传看女病；有中生无为显性，显性遗传看男病。"},{"ep":"bx2-08","n":"BX2-08","p":8,"a":"p8","id":"dg1","src":"assets/audio/BX2-08/dg1.mp3","sec":10.008,"t":"考点八，判断基因位于常染色体还是 X 染色体上的实验。已知显隐性时，选隐性雌 × 显性雄。"},{"ep":"bx2-08","n":"BX2-08","p":8,"a":"p8","id":"dg2","src":"assets/audio/BX2-08/dg2.mp3","sec":9.144,"t":"如果子代雌性全显、雄性全隐，基因在 X 染色体上；如果雌雄表现相同，在常染色体上。"},{"ep":"bx2-08","n":"BX2-08","p":8,"a":"p8","id":"dg3","src":"assets/audio/BX2-08/dg3.mp3","sec":10.512,"t":"未知显隐性时，用正交和反交：结果相同，在常染色体上；结果不同、并与性别有关，在 X 染色体上。"},{"ep":"bx2-08","n":"BX2-08","p":8,"a":"p8","id":"dg4","src":"assets/audio/BX2-08/dg4.mp3","sec":8.208,"t":"考法：实验设计题要写全实验思路和预期结果及结论，结论要和结果一一对应。"},{"ep":"bx2-08","n":"BX2-08","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-08/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-08","n":"BX2-08","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-08/rv2.mp3","sec":8.664,"t":"判断一？错，比如色盲基因就不决定性别。判断二？错，只能来自母亲。"},{"ep":"bx2-08","n":"BX2-08","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-08/rv3.mp3","sec":7.44,"t":"判断三？对，女病父子必病。判断四？对，男病母女必病。"},{"ep":"bx2-08","n":"BX2-08","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-08/rv4.mp3","sec":6.384,"t":"判断五？错，鸡是 ZW 型。判断六？对。"},{"ep":"bx2-08","n":"BX2-08","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-08/rv5.mp3","sec":6.84,"t":"八个考点串成一条线：隐性看女病，显性看男病。我们下期再见！"},{"ep":"bx2-09","n":"BX2-09","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-09/in1.mp3","sec":7.992,"t":"同学们好！这节课梳理人教版必修二第三章第一节——DNA 是主要的遗传物质。"},{"ep":"bx2-09","n":"BX2-09","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-09/in2.mp3","sec":7.68,"t":"高考常考肺炎链球菌的转化实验、噬菌体侵染细菌实验和放射性误差分析。"},{"ep":"bx2-09","n":"BX2-09","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-09/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-09","n":"BX2-09","p":1,"a":"p1","id":"ea1","src":"assets/audio/BX2-09/ea1.mp3","sec":8.88,"t":"考点一，对遗传物质的早期推测。20 世纪 20 年代，人们普遍认为蛋白质是遗传物质。"},{"ep":"bx2-09","n":"BX2-09","p":1,"a":"p1","id":"ea2","src":"assets/audio/BX2-09/ea2.mp3","sec":8.376,"t":"理由：蛋白质由多种氨基酸组成，氨基酸多种多样的排列顺序，可能蕴含着遗传信息。"},{"ep":"bx2-09","n":"BX2-09","p":1,"a":"p1","id":"ea3","src":"assets/audio/BX2-09/ea3.mp3","sec":12.864,"t":"到了 20 世纪 30 年代，人们才知道 DNA 由 4 种脱氧核苷酸聚合而成；但对 DNA 的结构了解不清，蛋白质是遗传物质的观点仍占主导。"},{"ep":"bx2-09","n":"BX2-09","p":1,"a":"p1","id":"ea4","src":"assets/audio/BX2-09/ea4.mp3","sec":10.152,"t":"考法：判断科学史的结论。思路是分别研究 DNA 和蛋白质的作用，下面两个经典实验都是这个思路。"},{"ep":"bx2-09","n":"BX2-09","p":2,"a":"p2","id":"gr1","src":"assets/audio/BX2-09/gr1.mp3","sec":12.168,"t":"考点二，格里菲思的体内转化实验。S 型细菌有荚膜，菌落光滑，有致病性；R 型细菌无荚膜，菌落粗糙，无致病性。"},{"ep":"bx2-09","n":"BX2-09","p":2,"a":"p2","id":"gr2","src":"assets/audio/BX2-09/gr2.mp3","sec":9.504,"t":"注射 R 型活菌，小鼠不死；注射 S 型活菌，小鼠死亡；注射加热致死的 S 型菌，小鼠不死。"},{"ep":"bx2-09","n":"BX2-09","p":2,"a":"p2","id":"gr3","src":"assets/audio/BX2-09/gr3.mp3","sec":9.0,"t":"把 R 型活菌和加热致死的 S 型菌混合注射，小鼠死亡，并从小鼠体内分离出了 S 型活菌。"},{"ep":"bx2-09","n":"BX2-09","p":2,"a":"p2","id":"gr4","src":"assets/audio/BX2-09/gr4.mp3","sec":9.888,"t":"结论：加热致死的 S 型细菌中，含有某种促使 R 型活菌转化为 S 型活菌的活性物质——转化因子。"},{"ep":"bx2-09","n":"BX2-09","p":2,"a":"p2","id":"gr5","src":"assets/audio/BX2-09/gr5.mp3","sec":10.584,"t":"易错：格里菲思没有证明 DNA 是遗传物质；转化来的 S 型细菌，后代也是 S 型，说明转化是可遗传的。"},{"ep":"bx2-09","n":"BX2-09","p":3,"a":"p3","id":"av1","src":"assets/audio/BX2-09/av1.mp3","sec":9.408,"t":"考点三，艾弗里的体外转化实验。把 S 型细菌的细胞提取物分成几组，分别用不同的酶处理。"},{"ep":"bx2-09","n":"BX2-09","p":3,"a":"p3","id":"av2","src":"assets/audio/BX2-09/av2.mp3","sec":9.0,"t":"不处理、加蛋白酶、加 RNA 酶、加酯酶的组，与 R 型活菌混合培养，都出现了 S 型细菌。"},{"ep":"bx2-09","n":"BX2-09","p":3,"a":"p3","id":"av3","src":"assets/audio/BX2-09/av3.mp3","sec":6.528,"t":"只有加 DNA 酶的那一组，DNA 被水解，培养基上只有 R 型细菌。"},{"ep":"bx2-09","n":"BX2-09","p":3,"a":"p3","id":"av4","src":"assets/audio/BX2-09/av4.mp3","sec":8.856,"t":"结论：DNA 才是使 R 型细菌产生稳定遗传变化的物质，也就是说，DNA 是遗传物质。"},{"ep":"bx2-09","n":"BX2-09","p":4,"a":"p4","id":"pp1","src":"assets/audio/BX2-09/pp1.mp3","sec":8.64,"t":"考点四，控制自变量的两种方法。加法原理：与常态比较，人为增加某种影响因素。"},{"ep":"bx2-09","n":"BX2-09","p":4,"a":"p4","id":"pp2","src":"assets/audio/BX2-09/pp2.mp3","sec":7.8,"t":"比如“比较过氧化氢在不同条件下的分解”，分别加热、加氯化铁、加肝脏研磨液。"},{"ep":"bx2-09","n":"BX2-09","p":4,"a":"p4","id":"pp3","src":"assets/audio/BX2-09/pp3.mp3","sec":9.936,"t":"减法原理：与常态比较，人为去除某种影响因素。艾弗里用酶分别去除某种物质，就是减法原理。"},{"ep":"bx2-09","n":"BX2-09","p":4,"a":"p4","id":"pp4","src":"assets/audio/BX2-09/pp4.mp3","sec":9.864,"t":"解题方法：看实验组是“多了”还是“少了”一个因素。去除一种物质，看结果是否消失，从而确定它的作用。"},{"ep":"bx2-09","n":"BX2-09","p":5,"a":"p5","id":"ph1","src":"assets/audio/BX2-09/ph1.mp3","sec":9.408,"t":"考点五，T2 噬菌体。它只由蛋白质外壳和头部的 DNA组成，专门寄生在大肠杆菌体内。"},{"ep":"bx2-09","n":"BX2-09","p":5,"a":"p5","id":"ph2","src":"assets/audio/BX2-09/ph2.mp3","sec":9.552,"t":"元素上：仅蛋白质含 S，磷几乎都在 DNA 中。所以能用 [35]S 和 [32]P 分别标记。"},{"ep":"bx2-09","n":"BX2-09","p":5,"a":"p5","id":"ph3","src":"assets/audio/BX2-09/ph3.mp3","sec":11.952,"t":"增殖过程：吸附、注入、合成、组装、释放。注入的只有 DNA，合成子代所用的原料、酶和场所，都来自大肠杆菌。"},{"ep":"bx2-09","n":"BX2-09","p":5,"a":"p5","id":"ph4","src":"assets/audio/BX2-09/ph4.mp3","sec":12.744,"t":"易错：病毒不能用培养基直接培养。要标记噬菌体，先用含 [35]S 或 [32]P 的培养基培养大肠杆菌，再用噬菌体去侵染它。"},{"ep":"bx2-09","n":"BX2-09","p":6,"a":"p6","id":"hs1","src":"assets/audio/BX2-09/hs1.mp3","sec":11.904,"t":"考点六，赫尔希和蔡斯的实验。一组用 [35]S 标记蛋白质，一组用 [32]P 标记 DNA，分别侵染未标记的大肠杆菌。"},{"ep":"bx2-09","n":"BX2-09","p":6,"a":"p6","id":"hs2","src":"assets/audio/BX2-09/hs2.mp3","sec":11.088,"t":"短时间保温后，搅拌使吸附在细菌上的噬菌体外壳与细菌分离，离心后，较轻的噬菌体在上清液，细菌在沉淀物。"},{"ep":"bx2-09","n":"BX2-09","p":6,"a":"p6","id":"hs3","src":"assets/audio/BX2-09/hs3.mp3","sec":10.104,"t":"结果：[35]S 组放射性主要在上清液；[32]P 组放射性主要在沉淀物，部分子代噬菌体含 [32]P。"},{"ep":"bx2-09","n":"BX2-09","p":6,"a":"p6","id":"hs4","src":"assets/audio/BX2-09/hs4.mp3","sec":11.88,"t":"结论：DNA 是噬菌体的遗传物质。易错：不能用 C、H、O、N 标记，因为两种物质都含有；两种标记要分开做。"},{"ep":"bx2-09","n":"BX2-09","p":7,"a":"p7","id":"er1","src":"assets/audio/BX2-09/er1.mp3","sec":8.4,"t":"考点七，放射性误差分析。[32]P 组，上清液也有少量放射性，原因有两个。"},{"ep":"bx2-09","n":"BX2-09","p":7,"a":"p7","id":"er2","src":"assets/audio/BX2-09/er2.mp3","sec":10.656,"t":"保温时间过短，部分噬菌体还没把 DNA 注入细菌；保温时间过长，细菌裂解，子代噬菌体被释放到上清液。"},{"ep":"bx2-09","n":"BX2-09","p":7,"a":"p7","id":"er3","src":"assets/audio/BX2-09/er3.mp3","sec":9.408,"t":"[35]S 组，沉淀物也有少量放射性，原因是搅拌不充分，有些蛋白质外壳仍吸附在细菌表面。"},{"ep":"bx2-09","n":"BX2-09","p":7,"a":"p7","id":"er4","src":"assets/audio/BX2-09/er4.mp3","sec":10.152,"t":"解题方法：[32]P 组的误差看保温时间，[35]S 组的误差看搅拌；保温时间对 [35]S 组的结果基本没有影响。"},{"ep":"bx2-09","n":"BX2-09","p":8,"a":"p8","id":"mn1","src":"assets/audio/BX2-09/mn1.mp3","sec":12.024,"t":"考点八，为什么说 DNA 是主要的遗传物质。从烟草花叶病毒中提取的蛋白质不能使烟草感染，RNA却能使烟草感染。"},{"ep":"bx2-09","n":"BX2-09","p":8,"a":"p8","id":"mn2","src":"assets/audio/BX2-09/mn2.mp3","sec":4.368,"t":"说明烟草花叶病毒的遗传物质是 RNA。"},{"ep":"bx2-09","n":"BX2-09","p":8,"a":"p8","id":"mn3","src":"assets/audio/BX2-09/mn3.mp3","sec":12.096,"t":"细胞生物和 DNA 病毒的遗传物质是 DNA，只有少数 RNA 病毒的遗传物质是 RNA。所以说 DNA 是主要的遗传物质。"},{"ep":"bx2-09","n":"BX2-09","p":8,"a":"p8","id":"mn4","src":"assets/audio/BX2-09/mn4.mp3","sec":10.512,"t":"易错：“主要”是对所有生物而言的；对某一种生物，遗传物质只有一种。不能说细胞生物的遗传物质“主要是 DNA”。"},{"ep":"bx2-09","n":"BX2-09","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-09/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-09","n":"BX2-09","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-09/rv2.mp3","sec":9.24,"t":"判断一？错，只推出存在转化因子。判断二？对，用酶去除物质是减法原理。"},{"ep":"bx2-09","n":"BX2-09","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-09/rv3.mp3","sec":6.552,"t":"判断三？对。判断四？错，要先标记大肠杆菌。"},{"ep":"bx2-09","n":"BX2-09","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-09/rv4.mp3","sec":7.8,"t":"判断五？错，细胞生物的遗传物质就是 DNA。判断六？对。"},{"ep":"bx2-09","n":"BX2-09","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-09/rv5.mp3","sec":8.064,"t":"八个考点串成一条线：分开研究 DNA 和蛋白质，单独看作用。我们下期再见！"},{"ep":"bx2-10","n":"BX2-10","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-10/in1.mp3","sec":6.864,"t":"同学们好！这节课梳理人教版必修二第三章第二节——DNA 的结构。"},{"ep":"bx2-10","n":"BX2-10","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-10/in2.mp3","sec":6.744,"t":"高考常考模型构建的科学史、双螺旋结构的特点和碱基的相关计算。"},{"ep":"bx2-10","n":"BX2-10","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-10/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-10","n":"BX2-10","p":1,"a":"p1","id":"hi1","src":"assets/audio/BX2-10/hi1.mp3","sec":14.904,"t":"考点一，DNA 双螺旋结构模型的构建。威尔金斯和富兰克林获得了高质量的 DNA X 射线衍射图谱，沃森和克里克据此推算出 DNA 呈螺旋结构。"},{"ep":"bx2-10","n":"BX2-10","p":1,"a":"p1","id":"hi2","src":"assets/audio/BX2-10/hi2.mp3","sec":7.728,"t":"沃森和克里克尝试搭建了很多种不同的双螺旋和三螺旋结构模型，但都被否定了。"},{"ep":"bx2-10","n":"BX2-10","p":1,"a":"p1","id":"hi3","src":"assets/audio/BX2-10/hi3.mp3","sec":6.552,"t":"查哥夫发现：在 DNA 中，A 的量总是等于 T，G 的量总是等于 C。"},{"ep":"bx2-10","n":"BX2-10","p":1,"a":"p1","id":"hi4","src":"assets/audio/BX2-10/hi4.mp3","sec":10.608,"t":"1953 年，沃森和克里克让碱基在内侧、A 与 T 配对、G 与 C 配对，构建出了 DNA 双螺旋结构模型。"},{"ep":"bx2-10","n":"BX2-10","p":1,"a":"p1","id":"hi5","src":"assets/audio/BX2-10/hi5.mp3","sec":9.096,"t":"易错：模型是沃森和克里克构建的，富兰克林提供的是衍射图谱；他们构建的是物理模型。"},{"ep":"bx2-10","n":"BX2-10","p":2,"a":"p2","id":"un1","src":"assets/audio/BX2-10/un1.mp3","sec":9.48,"t":"考点二，DNA 的基本单位——脱氧核苷酸，由一分子磷酸、一分子脱氧核糖和一分子含氮碱基组成。"},{"ep":"bx2-10","n":"BX2-10","p":2,"a":"p2","id":"un2","src":"assets/audio/BX2-10/un2.mp3","sec":11.688,"t":"碱基有 4 种：A、T、G、C，所以脱氧核苷酸也有 4 种。碱基连在脱氧核糖的 1′ 碳上，磷酸连在 5′ 碳上。"},{"ep":"bx2-10","n":"BX2-10","p":2,"a":"p2","id":"un3","src":"assets/audio/BX2-10/un3.mp3","sec":7.416,"t":"相邻的脱氧核苷酸之间，前一个的脱氧核糖和后一个的磷酸相连，形成长链。"},{"ep":"bx2-10","n":"BX2-10","p":2,"a":"p2","id":"un4","src":"assets/audio/BX2-10/un4.mp3","sec":5.808,"t":"每条链有游离磷酸基团的一端叫 5′ 端，另一端叫 3′ 端。"},{"ep":"bx2-10","n":"BX2-10","p":2,"a":"p2","id":"un5","src":"assets/audio/BX2-10/un5.mp3","sec":7.992,"t":"易错：链中大多数脱氧核糖连着两个磷酸，但 3′ 端的那个脱氧核糖只连一个。"},{"ep":"bx2-10","n":"BX2-10","p":3,"a":"p3","id":"he1","src":"assets/audio/BX2-10/he1.mp3","sec":11.4,"t":"考点三，DNA 双螺旋结构的主要特点。第一，DNA 由两条链组成，两条链按反向平行方式盘旋成双螺旋。"},{"ep":"bx2-10","n":"BX2-10","p":3,"a":"p3","id":"he2","src":"assets/audio/BX2-10/he2.mp3","sec":6.528,"t":"第二，脱氧核糖和磷酸交替连接，排列在外侧，构成基本骨架。"},{"ep":"bx2-10","n":"BX2-10","p":3,"a":"p3","id":"he3","src":"assets/audio/BX2-10/he3.mp3","sec":6.792,"t":"第三，碱基排列在内侧，两条链上的碱基通过氢键连接成碱基对。"},{"ep":"bx2-10","n":"BX2-10","p":3,"a":"p3","id":"he4","src":"assets/audio/BX2-10/he4.mp3","sec":15.24,"t":"考法：看图识结构。易错：基本骨架在外侧，由脱氧核糖和磷酸构成，不含碱基；同一条链上相邻碱基之间不是氢键，而是“脱氧核糖—磷酸—脱氧核糖”。"},{"ep":"bx2-10","n":"BX2-10","p":4,"a":"p4","id":"pa1","src":"assets/audio/BX2-10/pa1.mp3","sec":6.0,"t":"考点四，碱基互补配对原则：A 与 T 配对，G 与 C 配对。"},{"ep":"bx2-10","n":"BX2-10","p":4,"a":"p4","id":"pa2","src":"assets/audio/BX2-10/pa2.mp3","sec":5.28,"t":"A 和 T 之间有两个氢键，G 和 C 之间有三个氢键。"},{"ep":"bx2-10","n":"BX2-10","p":4,"a":"p4","id":"pa3","src":"assets/audio/BX2-10/pa3.mp3","sec":8.304,"t":"配对的总是一个嘌呤和一个嘧啶，所以每个碱基对的宽度一样，DNA 的直径保持恒定。"},{"ep":"bx2-10","n":"BX2-10","p":4,"a":"p4","id":"pa4","src":"assets/audio/BX2-10/pa4.mp3","sec":7.056,"t":"考法：G 与 C 含量越高，氢键越多，DNA 结构越稳定，越耐高温。"},{"ep":"bx2-10","n":"BX2-10","p":5,"a":"p5","id":"c11","src":"assets/audio/BX2-10/c11.mp3","sec":10.872,"t":"考点五，碱基计算（一）。双链 DNA 中 A = T，G = C，所以嘌呤数 = 嘧啶数，各占 50%。"},{"ep":"bx2-10","n":"BX2-10","p":5,"a":"p5","id":"c12","src":"assets/audio/BX2-10/c12.mp3","sec":4.704,"t":"整个 DNA 中，(A+G)/(T+C) = 1。"},{"ep":"bx2-10","n":"BX2-10","p":5,"a":"p5","id":"c13","src":"assets/audio/BX2-10/c13.mp3","sec":9.216,"t":"如果一条链中 (A+G)/(T+C) = a，那么互补链中这个比值是 1/a，两条链互为倒数。"},{"ep":"bx2-10","n":"BX2-10","p":5,"a":"p5","id":"c14","src":"assets/audio/BX2-10/c14.mp3","sec":10.92,"t":"解题方法：画出两条链，标上 1 链、2 链，利用 A1 = T2、G1 = C2 逐项代换。"},{"ep":"bx2-10","n":"BX2-10","p":6,"a":"p6","id":"c21","src":"assets/audio/BX2-10/c21.mp3","sec":9.0,"t":"考点六，碱基计算（二）。(A+T)/(G+C) 在一条链、互补链和整个 DNA 中都相等。"},{"ep":"bx2-10","n":"BX2-10","p":6,"a":"p6","id":"c22","src":"assets/audio/BX2-10/c22.mp3","sec":14.016,"t":"同理，A+T 占整个 DNA 碱基的比例，等于它占每一条单链的比例。例：DNA 中 A+T 占 40%，每条链中 A+T 也占 40%。"},{"ep":"bx2-10","n":"BX2-10","p":6,"a":"p6","id":"c23","src":"assets/audio/BX2-10/c23.mp3","sec":13.776,"t":"例：1 链中 A 占该链的 20%，2 链中 A 占该链的 30%，整个 DNA 中 A 占 (20% + 30%) ÷ 2 = 25%。"},{"ep":"bx2-10","n":"BX2-10","p":6,"a":"p6","id":"c24","src":"assets/audio/BX2-10/c24.mp3","sec":8.208,"t":"易错：分清百分比是占单链还是占双链；占单链的比例换算成双链，要除以 2。"},{"ep":"bx2-10","n":"BX2-10","p":7,"a":"p7","id":"dv1","src":"assets/audio/BX2-10/dv1.mp3","sec":11.52,"t":"考点七，DNA 的多样性和特异性。多样性：碱基对的排列顺序千变万化，n 个碱基对有 4n 种排列方式。"},{"ep":"bx2-10","n":"BX2-10","p":7,"a":"p7","id":"dv2","src":"assets/audio/BX2-10/dv2.mp3","sec":5.184,"t":"特异性：每个 DNA 分子都有特定的碱基排列顺序。"},{"ep":"bx2-10","n":"BX2-10","p":7,"a":"p7","id":"dv3","src":"assets/audio/BX2-10/dv3.mp3","sec":7.44,"t":"稳定性：外侧的基本骨架稳定，碱基之间有氢键，双螺旋结构相对稳定。"},{"ep":"bx2-10","n":"BX2-10","p":7,"a":"p7","id":"dv4","src":"assets/audio/BX2-10/dv4.mp3","sec":8.856,"t":"易错：4n 中的 n 是碱基对数，不是碱基数；遗传信息蕴藏在碱基的排列顺序中。"},{"ep":"bx2-10","n":"BX2-10","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-10/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-10","n":"BX2-10","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-10/rv2.mp3","sec":7.152,"t":"判断一？错，模型是沃森和克里克构建的。判断二？对。"},{"ep":"bx2-10","n":"BX2-10","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-10/rv3.mp3","sec":7.752,"t":"判断三？错，3′ 端的脱氧核糖只连一个磷酸。判断四？对。"},{"ep":"bx2-10","n":"BX2-10","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-10/rv4.mp3","sec":7.176,"t":"判断五？错，互补链中是 2，互为倒数。判断六？对。"},{"ep":"bx2-10","n":"BX2-10","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-10/rv5.mp3","sec":7.968,"t":"七个考点串成一条线：A 配 T、G 配 C，计算先画两条链。我们下期再见！"},{"ep":"bx2-11","n":"BX2-11","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-11/in1.mp3","sec":6.984,"t":"同学们好！这节课梳理人教版必修二第三章第三节——DNA 的复制。"},{"ep":"bx2-11","n":"BX2-11","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-11/in2.mp3","sec":9.168,"t":"高考常考半保留复制的实验证据、复制的条件和特点、复制的计算和结合细胞分裂的标记问题。"},{"ep":"bx2-11","n":"BX2-11","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-11/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-11","n":"BX2-11","p":1,"a":"p1","id":"gu1","src":"assets/audio/BX2-11/gu1.mp3","sec":11.904,"t":"考点一，对 DNA 复制方式的推测。沃森和克里克提出半保留复制：子代 DNA 由一条母链和一条新合成的子链组成。"},{"ep":"bx2-11","n":"BX2-11","p":1,"a":"p1","id":"gu2","src":"assets/audio/BX2-11/gu2.mp3","sec":9.528,"t":"另一种假说是全保留复制：两条母链复制后又重新结合在一起，子代 DNA 的两条链都是新合成的。"},{"ep":"bx2-11","n":"BX2-11","p":1,"a":"p1","id":"gu3","src":"assets/audio/BX2-11/gu3.mp3","sec":8.736,"t":"考法：两种假说预测的实验结果不同，用实验结果就能判断真假——这就是下一个考点的实验。"},{"ep":"bx2-11","n":"BX2-11","p":2,"a":"p2","id":"ms1","src":"assets/audio/BX2-11/ms1.mp3","sec":12.336,"t":"考点二，梅塞尔森和斯塔尔的实验。让大肠杆菌在含 [15]N 的培养液中繁殖多代，DNA 都是 [15]N/[15]N，离心后在重带。"},{"ep":"bx2-11","n":"BX2-11","p":2,"a":"p2","id":"ms2","src":"assets/audio/BX2-11/ms2.mp3","sec":9.312,"t":"转到含 [14]N 的培养液中，繁殖第一代，DNA 全部在中带，是 [15]N/[14]N。"},{"ep":"bx2-11","n":"BX2-11","p":2,"a":"p2","id":"ms3","src":"assets/audio/BX2-11/ms3.mp3","sec":3.456,"t":"第二代，一半中带、一半轻带。"},{"ep":"bx2-11","n":"BX2-11","p":2,"a":"p2","id":"ms4","src":"assets/audio/BX2-11/ms4.mp3","sec":11.352,"t":"解题方法：如果是全保留复制，第一代应该是一条重带和一条轻带，没有中带。实验结果证明 DNA 是半保留复制。"},{"ep":"bx2-11","n":"BX2-11","p":3,"a":"p3","id":"me1","src":"assets/audio/BX2-11/me1.mp3","sec":10.224,"t":"考点三，实验中的科学方法。用 [15]N 和 [14]N 标记，区分亲代和子代的 DNA，这是同位素标记技术。"},{"ep":"bx2-11","n":"BX2-11","p":3,"a":"p3","id":"me2","src":"assets/audio/BX2-11/me2.mp3","sec":6.456,"t":"用密度梯度离心，让密度不同的 DNA 在离心管中分成不同的带。"},{"ep":"bx2-11","n":"BX2-11","p":3,"a":"p3","id":"me3","src":"assets/audio/BX2-11/me3.mp3","sec":8.088,"t":"整个研究用的是假说—演绎法：提出半保留假说，推出预期的离心结果，再用实验检验。"},{"ep":"bx2-11","n":"BX2-11","p":3,"a":"p3","id":"me4","src":"assets/audio/BX2-11/me4.mp3","sec":9.288,"t":"易错：[15]N 和 [14]N 都是稳定同位素，没有放射性；区分它们靠的是密度，不是检测放射性。"},{"ep":"bx2-11","n":"BX2-11","p":4,"a":"p4","id":"pr1","src":"assets/audio/BX2-11/pr1.mp3","sec":10.944,"t":"考点四，DNA 复制的过程。时间：细胞分裂前的间期，随着染色体的复制完成。场所：主要在细胞核。"},{"ep":"bx2-11","n":"BX2-11","p":4,"a":"p4","id":"pr2","src":"assets/audio/BX2-11/pr2.mp3","sec":5.016,"t":"首先，在解旋酶的作用下，两条螺旋的双链解开。"},{"ep":"bx2-11","n":"BX2-11","p":4,"a":"p4","id":"pr3","src":"assets/audio/BX2-11/pr3.mp3","sec":11.904,"t":"然后，以解开的每一条母链为模板，以 4 种脱氧核苷酸为原料，在 DNA 聚合酶等的作用下，按碱基互补配对原则合成子链。"},{"ep":"bx2-11","n":"BX2-11","p":4,"a":"p4","id":"pr4","src":"assets/audio/BX2-11/pr4.mp3","sec":3.336,"t":"复制需要能量，由 ATP 提供。"},{"ep":"bx2-11","n":"BX2-11","p":4,"a":"p4","id":"pr5","src":"assets/audio/BX2-11/pr5.mp3","sec":12.024,"t":"易错：解旋酶断开的是氢键；DNA 聚合酶连接的是脱氧核苷酸之间的磷酸二酯键；线粒体、叶绿体中也能进行 DNA 复制。"},{"ep":"bx2-11","n":"BX2-11","p":5,"a":"p5","id":"fe1","src":"assets/audio/BX2-11/fe1.mp3","sec":5.976,"t":"考点五，DNA 复制的特点：边解旋边复制，半保留复制。"},{"ep":"bx2-11","n":"BX2-11","p":5,"a":"p5","id":"fe2","src":"assets/audio/BX2-11/fe2.mp3","sec":10.704,"t":"准确复制的原因：DNA 独特的双螺旋结构，为复制提供了精确的模板；碱基互补配对，保证了复制能准确进行。"},{"ep":"bx2-11","n":"BX2-11","p":5,"a":"p5","id":"fe3","src":"assets/audio/BX2-11/fe3.mp3","sec":7.848,"t":"意义：将遗传信息从亲代细胞传递给子代细胞，从而保持了遗传信息的连续性。"},{"ep":"bx2-11","n":"BX2-11","p":5,"a":"p5","id":"fe4","src":"assets/audio/BX2-11/fe4.mp3","sec":10.464,"t":"易错：DNA 复制也可能出错，产生基因突变；一个 DNA 复制一次得到的两个子代 DNA，一般完全相同。"},{"ep":"bx2-11","n":"BX2-11","p":6,"a":"p6","id":"ca1","src":"assets/audio/BX2-11/ca1.mp3","sec":8.064,"t":"考点六，复制的相关计算。一个 DNA 复制 n 次，得到 2n 个 DNA。"},{"ep":"bx2-11","n":"BX2-11","p":6,"a":"p6","id":"ca2","src":"assets/audio/BX2-11/ca2.mp3","sec":7.056,"t":"其中含有母链的 DNA 只有 2 个，母链只占全部单链的 1/2n。"},{"ep":"bx2-11","n":"BX2-11","p":6,"a":"p6","id":"ca3","src":"assets/audio/BX2-11/ca3.mp3","sec":13.368,"t":"如果 DNA 中某种碱基有 m 个，复制 n 次共需要这种脱氧核苷酸 m(2n − 1) 个；第 n 次复制需要 m·2[n−1] 个。"},{"ep":"bx2-11","n":"BX2-11","p":6,"a":"p6","id":"ca4","src":"assets/audio/BX2-11/ca4.mp3","sec":10.968,"t":"易错：分清“复制 n 次”和“第 n 次复制”。例：含 100 个 A 的 DNA，复制 3 次共需 A 700 个，第 3 次需 400 个。"},{"ep":"bx2-11","n":"BX2-11","p":7,"a":"p7","id":"lb1","src":"assets/audio/BX2-11/lb1.mp3","sec":11.424,"t":"考点七，结合细胞分裂的标记问题。把 DNA 两条链都被 [3]H 标记的细胞，放到不含放射性的培养液中进行有丝分裂。"},{"ep":"bx2-11","n":"BX2-11","p":7,"a":"p7","id":"lb2","src":"assets/audio/BX2-11/lb2.mp3","sec":8.712,"t":"第一次分裂中期：每条染色体的两条染色单体都有标记，因为每个 DNA 都有一条标记的母链。"},{"ep":"bx2-11","n":"BX2-11","p":7,"a":"p7","id":"lb3","src":"assets/audio/BX2-11/lb3.mp3","sec":5.688,"t":"第二次分裂中期：每条染色体中只有一条染色单体有标记。"},{"ep":"bx2-11","n":"BX2-11","p":7,"a":"p7","id":"lb4","src":"assets/audio/BX2-11/lb4.mp3","sec":14.208,"t":"解题方法：画出 DNA 双链，按半保留复制一次一次推；第二次分裂后期姐妹染色单体分开后随机移向两极，子细胞中带标记的染色体数不确定。"},{"ep":"bx2-11","n":"BX2-11","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-11/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-11","n":"BX2-11","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-11/rv2.mp3","sec":9.024,"t":"判断一？错，是半保留复制。判断二？错，[15]N 没有放射性，靠密度区分。"},{"ep":"bx2-11","n":"BX2-11","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-11/rv3.mp3","sec":7.392,"t":"判断三？对。判断四？错，线粒体和叶绿体中也能复制。"},{"ep":"bx2-11","n":"BX2-11","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-11/rv4.mp3","sec":10.608,"t":"判断五？对，8 个 DNA 中 2 个含母链。判断六？错，第 n 次复制需要 m·2[n−1] 个。"},{"ep":"bx2-11","n":"BX2-11","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-11/rv5.mp3","sec":7.752,"t":"七个考点串成一条线：半保留复制，画出双链一次一次推。我们下期再见！"},{"ep":"bx2-12","n":"BX2-12","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-12/in1.mp3","sec":9.048,"t":"同学们好！这节课梳理人教版必修二第三章第四节——基因通常是有遗传效应的 DNA 片段。"},{"ep":"bx2-12","n":"BX2-12","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-12/in2.mp3","sec":7.008,"t":"高考常考基因的本质、基因、DNA、染色体的关系和 DNA 指纹技术。"},{"ep":"bx2-12","n":"BX2-12","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-12/in3.mp3","sec":5.448,"t":"我们按五个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-12","n":"BX2-12","p":1,"a":"p1","id":"ex1","src":"assets/audio/BX2-12/ex1.mp3","sec":12.528,"t":"考点一，说明基因与 DNA 关系的实例。大肠杆菌一个 DNA 上分布着大约 4400 个基因，但基因的总长度小于 DNA 的长度。"},{"ep":"bx2-12","n":"BX2-12","p":1,"a":"p1","id":"ex2","src":"assets/audio/BX2-12/ex2.mp3","sec":9.6,"t":"水母的绿色荧光蛋白基因转入小鼠，小鼠在紫外线下也能像水母一样发光——说明基因具有遗传效应。"},{"ep":"bx2-12","n":"BX2-12","p":1,"a":"p1","id":"ex3","src":"assets/audio/BX2-12/ex3.mp3","sec":8.808,"t":"人类基因组计划测定的 24 个 DNA 分子中，构成基因的碱基数不超过碱基总数的 2%。"},{"ep":"bx2-12","n":"BX2-12","p":1,"a":"p1","id":"ex4","src":"assets/audio/BX2-12/ex4.mp3","sec":8.352,"t":"考法：由这些实例推出——基因是 DNA 的片段，但 DNA 上并非所有片段都是基因。"},{"ep":"bx2-12","n":"BX2-12","p":2,"a":"p2","id":"es1","src":"assets/audio/BX2-12/es1.mp3","sec":8.328,"t":"考点二，基因的本质。对 DNA 生物来说，基因通常是有遗传效应的 DNA 片段。"},{"ep":"bx2-12","n":"BX2-12","p":2,"a":"p2","id":"es2","src":"assets/audio/BX2-12/es2.mp3","sec":5.736,"t":"对 RNA 病毒来说，基因是有遗传效应的 RNA 片段。"},{"ep":"bx2-12","n":"BX2-12","p":2,"a":"p2","id":"es3","src":"assets/audio/BX2-12/es3.mp3","sec":6.36,"t":"基因是控制生物性状的基本单位，也是遗传物质的结构和功能单位。"},{"ep":"bx2-12","n":"BX2-12","p":2,"a":"p2","id":"es4","src":"assets/audio/BX2-12/es4.mp3","sec":10.368,"t":"易错：说“基因就是 DNA 片段”不够准确，关键词是“有遗传效应”；“所有生物的基因都是 DNA 片段”是错的。"},{"ep":"bx2-12","n":"BX2-12","p":3,"a":"p3","id":"if1","src":"assets/audio/BX2-12/if1.mp3","sec":5.376,"t":"考点三，遗传信息蕴藏在 4 种碱基的排列顺序之中。"},{"ep":"bx2-12","n":"BX2-12","p":3,"a":"p3","id":"if2","src":"assets/audio/BX2-12/if2.mp3","sec":9.6,"t":"碱基排列顺序的千变万化，构成了 DNA 的多样性；碱基特定的排列顺序，构成了每个 DNA 的特异性。"},{"ep":"bx2-12","n":"BX2-12","p":3,"a":"p3","id":"if3","src":"assets/audio/BX2-12/if3.mp3","sec":6.168,"t":"DNA 的多样性和特异性，是生物体多样性和特异性的物质基础。"},{"ep":"bx2-12","n":"BX2-12","p":3,"a":"p3","id":"if4","src":"assets/audio/BX2-12/if4.mp3","sec":11.184,"t":"易错：遗传信息在碱基排列顺序中，不是在碱基种类或数量中；脱氧核糖和磷酸的交替排列是固定的，不储存信息。"},{"ep":"bx2-12","n":"BX2-12","p":4,"a":"p4","id":"re1","src":"assets/audio/BX2-12/re1.mp3","sec":12.528,"t":"考点四，脱氧核苷酸、基因、DNA、染色体的关系。脱氧核苷酸是基因的基本单位，每个基因含有成百上千个脱氧核苷酸。"},{"ep":"bx2-12","n":"BX2-12","p":4,"a":"p4","id":"re2","src":"assets/audio/BX2-12/re2.mp3","sec":3.264,"t":"每个 DNA 分子上有许多个基因。"},{"ep":"bx2-12","n":"BX2-12","p":4,"a":"p4","id":"re3","src":"assets/audio/BX2-12/re3.mp3","sec":11.136,"t":"染色体是 DNA 的主要载体：一条染色体上通常有一个 DNA，复制后有两个 DNA；基因在染色体上呈线性排列。"},{"ep":"bx2-12","n":"BX2-12","p":4,"a":"p4","id":"re4","src":"assets/audio/BX2-12/re4.mp3","sec":9.24,"t":"易错：染色体是主要载体，线粒体、叶绿体中的 DNA 不在染色体上；原核细胞没有染色体。"},{"ep":"bx2-12","n":"BX2-12","p":5,"a":"p5","id":"fp1","src":"assets/audio/BX2-12/fp1.mp3","sec":8.736,"t":"考点五，DNA 指纹技术。每个人的 DNA 都有特定的碱基序列，就像指纹一样独一无二。"},{"ep":"bx2-12","n":"BX2-12","p":5,"a":"p5","id":"fp2","src":"assets/audio/BX2-12/fp2.mp3","sec":7.44,"t":"把 DNA 切成片段，电泳后形成特定的条带图谱，比对条带就能确定身份。"},{"ep":"bx2-12","n":"BX2-12","p":5,"a":"p5","id":"fp3","src":"assets/audio/BX2-12/fp3.mp3","sec":5.328,"t":"应用：刑侦破案、亲子鉴定、遇难者身份鉴定等。"},{"ep":"bx2-12","n":"BX2-12","p":5,"a":"p5","id":"fp4","src":"assets/audio/BX2-12/fp4.mp3","sec":9.456,"t":"解题方法：亲子鉴定时，孩子的每一条带，要么来自母亲，要么来自父亲；原理是 DNA 的特异性。"},{"ep":"bx2-12","n":"BX2-12","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-12/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-12","n":"BX2-12","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-12/rv2.mp3","sec":7.464,"t":"判断一？错，只有有遗传效应的片段才是基因。判断二？对。"},{"ep":"bx2-12","n":"BX2-12","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-12/rv3.mp3","sec":9.888,"t":"判断三？错，RNA 病毒的基因是 RNA 片段。判断四？错，复制后有两个 DNA。"},{"ep":"bx2-12","n":"BX2-12","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-12/rv4.mp3","sec":4.68,"t":"判断五？对。判断六？对。"},{"ep":"bx2-12","n":"BX2-12","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-12/rv5.mp3","sec":6.864,"t":"五个考点串成一条线：有遗传效应的片段才叫基因。我们下期再见！"},{"ep":"bx2-13","n":"BX2-13","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-13/in1.mp3","sec":8.016,"t":"同学们好！这节课梳理人教版必修二第四章第一节的上半部分——RNA 与转录。"},{"ep":"bx2-13","n":"BX2-13","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-13/in2.mp3","sec":7.656,"t":"高考常考三种 RNA 的功能、转录的条件和过程，以及转录与 DNA 复制的比较。"},{"ep":"bx2-13","n":"BX2-13","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-13/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-13","n":"BX2-13","p":1,"a":"p1","id":"rn1","src":"assets/audio/BX2-13/rn1.mp3","sec":10.248,"t":"考点一，RNA 的组成和结构。RNA 的基本单位是核糖核苷酸，由磷酸、核糖和含氮碱基组成。"},{"ep":"bx2-13","n":"BX2-13","p":1,"a":"p1","id":"rn2","src":"assets/audio/BX2-13/rn2.mp3","sec":4.752,"t":"RNA 的碱基是 A、U、G、C，没有 T。"},{"ep":"bx2-13","n":"BX2-13","p":1,"a":"p1","id":"rn3","src":"assets/audio/BX2-13/rn3.mp3","sec":7.128,"t":"RNA 一般是单链，比 DNA 短，能通过核孔从细胞核转移到细胞质中。"},{"ep":"bx2-13","n":"BX2-13","p":1,"a":"p1","id":"rn4","src":"assets/audio/BX2-13/rn4.mp3","sec":10.008,"t":"易错：RNA 一般是单链，但 tRNA 的单链会折叠，局部形成碱基对，所以 tRNA 中也有氢键。"},{"ep":"bx2-13","n":"BX2-13","p":2,"a":"p2","id":"ty1","src":"assets/audio/BX2-13/ty1.mp3","sec":10.032,"t":"考点二，三种 RNA。mRNA，信使 RNA，携带从 DNA 转录来的遗传信息，是翻译的模板。"},{"ep":"bx2-13","n":"BX2-13","p":2,"a":"p2","id":"ty2","src":"assets/audio/BX2-13/ty2.mp3","sec":6.768,"t":"tRNA，转运 RNA，三叶草形，能识别密码子并转运氨基酸。"},{"ep":"bx2-13","n":"BX2-13","p":2,"a":"p2","id":"ty3","src":"assets/audio/BX2-13/ty3.mp3","sec":5.712,"t":"rRNA，核糖体 RNA，和蛋白质一起组成核糖体。"},{"ep":"bx2-13","n":"BX2-13","p":2,"a":"p2","id":"ty4","src":"assets/audio/BX2-13/ty4.mp3","sec":8.856,"t":"考法：三种 RNA 都是转录产生的，都参与翻译；少数 RNA 还具有催化作用，是酶。"},{"ep":"bx2-13","n":"BX2-13","p":3,"a":"p3","id":"co1","src":"assets/audio/BX2-13/co1.mp3","sec":11.256,"t":"考点三，转录的概念：RNA 是在细胞核中，通过 RNA 聚合酶以 DNA 的一条链为模板合成的，这个过程叫转录。"},{"ep":"bx2-13","n":"BX2-13","p":3,"a":"p3","id":"co2","src":"assets/audio/BX2-13/co2.mp3","sec":5.496,"t":"场所：主要在细胞核，线粒体和叶绿体中也能转录。"},{"ep":"bx2-13","n":"BX2-13","p":3,"a":"p3","id":"co3","src":"assets/audio/BX2-13/co3.mp3","sec":8.592,"t":"模板：DNA 的一条链；原料：4 种核糖核苷酸；酶：RNA 聚合酶；还需要能量。"},{"ep":"bx2-13","n":"BX2-13","p":3,"a":"p3","id":"co4","src":"assets/audio/BX2-13/co4.mp3","sec":10.44,"t":"易错：转录的原料是核糖核苷酸，不是脱氧核苷酸；RNA 聚合酶兼有解旋作用，转录不需要另加解旋酶。"},{"ep":"bx2-13","n":"BX2-13","p":4,"a":"p4","id":"pr1","src":"assets/audio/BX2-13/pr1.mp3","sec":6.792,"t":"考点四，转录的过程。第一步，DNA 双链解开，碱基暴露出来。"},{"ep":"bx2-13","n":"BX2-13","p":4,"a":"p4","id":"pr2","src":"assets/audio/BX2-13/pr2.mp3","sec":9.528,"t":"第二步，游离的核糖核苷酸与模板链上的碱基互补配对：A 配 U、T 配 A、G 配 C、C 配 G。"},{"ep":"bx2-13","n":"BX2-13","p":4,"a":"p4","id":"pr3","src":"assets/audio/BX2-13/pr3.mp3","sec":9.312,"t":"第三步，在 RNA 聚合酶的作用下，核糖核苷酸依次连接，RNA 链从 5′ 端向 3′ 端延伸。"},{"ep":"bx2-13","n":"BX2-13","p":4,"a":"p4","id":"pr4","src":"assets/audio/BX2-13/pr4.mp3","sec":6.384,"t":"第四步，合成的 RNA 从 DNA 链上释放，DNA 双链恢复。"},{"ep":"bx2-13","n":"BX2-13","p":4,"a":"p4","id":"pr5","src":"assets/audio/BX2-13/pr5.mp3","sec":10.8,"t":"解题方法：由模板链写 mRNA，把 T 换成 U 再配对；mRNA 的序列与非模板链基本相同，只是 T 换成 U。"},{"ep":"bx2-13","n":"BX2-13","p":5,"a":"p5","id":"cp1","src":"assets/audio/BX2-13/cp1.mp3","sec":9.0,"t":"考点五，转录与 DNA 复制的比较。模板：复制以两条链为模板，转录只以一条链为模板。"},{"ep":"bx2-13","n":"BX2-13","p":5,"a":"p5","id":"cp2","src":"assets/audio/BX2-13/cp2.mp3","sec":11.064,"t":"原料：复制用脱氧核苷酸，转录用核糖核苷酸；酶：复制用解旋酶和 DNA 聚合酶，转录用 RNA 聚合酶。"},{"ep":"bx2-13","n":"BX2-13","p":5,"a":"p5","id":"cp3","src":"assets/audio/BX2-13/cp3.mp3","sec":8.76,"t":"配对：转录特有 A—U 配对；产物：复制得到两个 DNA，转录得到一条单链 RNA。"},{"ep":"bx2-13","n":"BX2-13","p":5,"a":"p5","id":"cp4","src":"assets/audio/BX2-13/cp4.mp3","sec":9.504,"t":"考法：常用表格比较。易错：已高度分化的细胞不再进行 DNA 复制，但仍能转录和翻译。"},{"ep":"bx2-13","n":"BX2-13","p":6,"a":"p6","id":"pf1","src":"assets/audio/BX2-13/pf1.mp3","sec":8.16,"t":"考点六，转录的易错点。转录是以基因为单位进行的，不是整个 DNA 一起转录。"},{"ep":"bx2-13","n":"BX2-13","p":6,"a":"p6","id":"pf2","src":"assets/audio/BX2-13/pf2.mp3","sec":6.336,"t":"一个 DNA 上有许多基因，不同基因的模板链不一定是同一条链。"},{"ep":"bx2-13","n":"BX2-13","p":6,"a":"p6","id":"pf3","src":"assets/audio/BX2-13/pf3.mp3","sec":6.288,"t":"同一个基因在不同细胞中不一定都转录，这就是基因的选择性表达。"},{"ep":"bx2-13","n":"BX2-13","p":6,"a":"p6","id":"pf4","src":"assets/audio/BX2-13/pf4.mp3","sec":13.536,"t":"易错：一个 DNA 可转录出多种 RNA；实际 mRNA 碱基数少于基因碱基数的一半，因为基因中有不转录的部分，计算题中一般忽略这一点。"},{"ep":"bx2-13","n":"BX2-13","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-13/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-13","n":"BX2-13","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-13/rv2.mp3","sec":7.416,"t":"判断一？对。判断二？错，tRNA 由许多核苷酸组成。"},{"ep":"bx2-13","n":"BX2-13","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-13/rv3.mp3","sec":9.6,"t":"判断三？错，只以 DNA 的一条链为模板。判断四？错，转录用的是 RNA 聚合酶。"},{"ep":"bx2-13","n":"BX2-13","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-13/rv4.mp3","sec":8.016,"t":"判断五？对。判断六？错，以基因为单位，可转录出多种 RNA。"},{"ep":"bx2-13","n":"BX2-13","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-13/rv5.mp3","sec":6.48,"t":"六个考点串成一条线：一条链作模板，A 配 U。我们下期再见！"},{"ep":"bx2-14","n":"BX2-14","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-14/in1.mp3","sec":8.064,"t":"同学们好！这节课梳理人教版必修二第四章第一节的下半部分——翻译与中心法则。"},{"ep":"bx2-14","n":"BX2-14","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-14/in2.mp3","sec":7.272,"t":"高考常考密码子和反密码子、翻译过程的图像、数量计算和中心法则。"},{"ep":"bx2-14","n":"BX2-14","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-14/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-14","n":"BX2-14","p":1,"a":"p1","id":"co1","src":"assets/audio/BX2-14/co1.mp3","sec":9.768,"t":"考点一，翻译：游离在细胞质中的各种氨基酸，以 mRNA 为模板合成具有一定氨基酸顺序的蛋白质。"},{"ep":"bx2-14","n":"BX2-14","p":1,"a":"p1","id":"co2","src":"assets/audio/BX2-14/co2.mp3","sec":10.224,"t":"场所：核糖体；模板：mRNA；原料：21 种氨基酸；运载工具：tRNA；还需要酶和能量。"},{"ep":"bx2-14","n":"BX2-14","p":1,"a":"p1","id":"co3","src":"assets/audio/BX2-14/co3.mp3","sec":6.696,"t":"产物：多肽链，再经过盘曲折叠，形成有一定空间结构的蛋白质。"},{"ep":"bx2-14","n":"BX2-14","p":1,"a":"p1","id":"co4","src":"assets/audio/BX2-14/co4.mp3","sec":10.464,"t":"易错：翻译的直接产物是多肽，不一定直接具有生物活性；翻译时碱基配对发生在 mRNA 和 tRNA 之间。"},{"ep":"bx2-14","n":"BX2-14","p":2,"a":"p2","id":"cd1","src":"assets/audio/BX2-14/cd1.mp3","sec":6.216,"t":"考点二，密码子：mRNA 上决定一个氨基酸的 3 个相邻碱基。"},{"ep":"bx2-14","n":"BX2-14","p":2,"a":"p2","id":"cd2","src":"assets/audio/BX2-14/cd2.mp3","sec":9.792,"t":"密码子共有 64 种。AUG 是起始密码子，也编码甲硫氨酸；UAA、UAG、UGA 是终止密码子。"},{"ep":"bx2-14","n":"BX2-14","p":2,"a":"p2","id":"cd3","src":"assets/audio/BX2-14/cd3.mp3","sec":7.368,"t":"一种氨基酸可以对应一种或几种密码子，这叫密码子的简并，能增强容错性。"},{"ep":"bx2-14","n":"BX2-14","p":2,"a":"p2","id":"cd4","src":"assets/audio/BX2-14/cd4.mp3","sec":6.552,"t":"密码子在几乎所有生物中都是通用的，这说明生物有共同的起源。"},{"ep":"bx2-14","n":"BX2-14","p":2,"a":"p2","id":"cd5","src":"assets/audio/BX2-14/cd5.mp3","sec":8.568,"t":"易错：终止密码子一般不决定氨基酸；但在特殊情况下，UGA 可以编码硒代半胱氨酸。"},{"ep":"bx2-14","n":"BX2-14","p":3,"a":"p3","id":"tr1","src":"assets/audio/BX2-14/tr1.mp3","sec":10.464,"t":"考点三，tRNA。tRNA 呈三叶草形，一端是携带氨基酸的部位，另一端有 3 个碱基，叫反密码子。"},{"ep":"bx2-14","n":"BX2-14","p":3,"a":"p3","id":"tr2","src":"assets/audio/BX2-14/tr2.mp3","sec":4.752,"t":"反密码子能与 mRNA 上的密码子互补配对。"},{"ep":"bx2-14","n":"BX2-14","p":3,"a":"p3","id":"tr3","src":"assets/audio/BX2-14/tr3.mp3","sec":8.616,"t":"每种 tRNA 只能识别并转运一种氨基酸；但一种氨基酸可以由一种或几种 tRNA 转运。"},{"ep":"bx2-14","n":"BX2-14","p":3,"a":"p3","id":"tr4","src":"assets/audio/BX2-14/tr4.mp3","sec":10.512,"t":"易错：密码子在 mRNA 上，反密码子在 tRNA 上；tRNA 不是只有 3 个碱基，而是由许多核苷酸组成。"},{"ep":"bx2-14","n":"BX2-14","p":4,"a":"p4","id":"pr1","src":"assets/audio/BX2-14/pr1.mp3","sec":11.208,"t":"考点四，翻译的过程。mRNA 进入细胞质，与核糖体结合。携带甲硫氨酸的 tRNA 识别起始密码子 AUG。"},{"ep":"bx2-14","n":"BX2-14","p":4,"a":"p4","id":"pr2","src":"assets/audio/BX2-14/pr2.mp3","sec":7.152,"t":"携带下一个氨基酸的 tRNA 进入，两个氨基酸之间脱水缩合形成肽键。"},{"ep":"bx2-14","n":"BX2-14","p":4,"a":"p4","id":"pr3","src":"assets/audio/BX2-14/pr3.mp3","sec":8.472,"t":"核糖体沿着 mRNA 移动，读取下一个密码子，空载的 tRNA 离开，再去转运氨基酸。"},{"ep":"bx2-14","n":"BX2-14","p":4,"a":"p4","id":"pr4","src":"assets/audio/BX2-14/pr4.mp3","sec":5.592,"t":"核糖体遇到终止密码子，合成停止，肽链脱离核糖体。"},{"ep":"bx2-14","n":"BX2-14","p":4,"a":"p4","id":"pr5","src":"assets/audio/BX2-14/pr5.mp3","sec":13.8,"t":"考法：读图判断核糖体移动方向——肽链越长的核糖体，越早开始翻译，所以核糖体向肽链长的一侧移动，即沿 mRNA 的 5′→3′ 方向。"},{"ep":"bx2-14","n":"BX2-14","p":5,"a":"p5","id":"po1","src":"assets/audio/BX2-14/po1.mp3","sec":8.928,"t":"考点五，多聚核糖体。一个 mRNA 上可以相继结合多个核糖体，同时合成多条肽链。"},{"ep":"bx2-14","n":"BX2-14","p":5,"a":"p5","id":"po2","src":"assets/audio/BX2-14/po2.mp3","sec":5.976,"t":"意义：少量的 mRNA 分子就可以迅速合成大量的蛋白质。"},{"ep":"bx2-14","n":"BX2-14","p":5,"a":"p5","id":"po3","src":"assets/audio/BX2-14/po3.mp3","sec":6.264,"t":"由于模板是同一条 mRNA，合成的多条肽链氨基酸序列相同。"},{"ep":"bx2-14","n":"BX2-14","p":5,"a":"p5","id":"po4","src":"assets/audio/BX2-14/po4.mp3","sec":12.192,"t":"易错：多个核糖体是各自合成一条肽链，不是共同合成一条；它缩短的是合成大量蛋白质的时间，不是缩短合成一条肽链的时间。"},{"ep":"bx2-14","n":"BX2-14","p":6,"a":"p6","id":"pk1","src":"assets/audio/BX2-14/pk1.mp3","sec":10.968,"t":"考点六，原核细胞边转录边翻译。原核细胞没有核膜，mRNA 还没转录完，核糖体就结合上去开始翻译。"},{"ep":"bx2-14","n":"BX2-14","p":6,"a":"p6","id":"pk2","src":"assets/audio/BX2-14/pk2.mp3","sec":10.104,"t":"真核细胞的核基因，转录在细胞核，翻译在细胞质的核糖体上，先转录、后翻译，在时间和空间上分开。"},{"ep":"bx2-14","n":"BX2-14","p":6,"a":"p6","id":"pk3","src":"assets/audio/BX2-14/pk3.mp3","sec":12.144,"t":"解题方法：看图中 DNA 和核糖体是否在一起——转录和翻译同时同地进行的，是原核细胞，或者真核细胞的线粒体、叶绿体。"},{"ep":"bx2-14","n":"BX2-14","p":7,"a":"p7","id":"ra1","src":"assets/audio/BX2-14/ra1.mp3","sec":10.632,"t":"考点七，基因表达中的数量关系。mRNA 上 3 个碱基决定 1 个氨基酸，mRNA 是由 DNA 一条链转录的。"},{"ep":"bx2-14","n":"BX2-14","p":7,"a":"p7","id":"ra2","src":"assets/audio/BX2-14/ra2.mp3","sec":6.576,"t":"所以 DNA 碱基数∶mRNA 碱基数∶氨基酸数 = 6∶3∶1。"},{"ep":"bx2-14","n":"BX2-14","p":7,"a":"p7","id":"ra3","src":"assets/audio/BX2-14/ra3.mp3","sec":9.864,"t":"例：一个蛋白质含 100 个氨基酸，控制它合成的基因至少有 600 个碱基，mRNA 至少 300 个碱基。"},{"ep":"bx2-14","n":"BX2-14","p":7,"a":"p7","id":"ra4","src":"assets/audio/BX2-14/ra4.mp3","sec":13.248,"t":"易错：要写“至少”，因为没算终止密码子和不翻译的序列；问 tRNA 时，氨基酸数 = 需要转运的 tRNA 次数，而不是 tRNA 的种类。"},{"ep":"bx2-14","n":"BX2-14","p":8,"a":"p8","id":"dg1","src":"assets/audio/BX2-14/dg1.mp3","sec":14.376,"t":"考点八，中心法则。克里克提出：遗传信息可以从 DNA 流向 DNA，即复制；也可以从 DNA 流向 RNA，进而流向蛋白质，即转录和翻译。"},{"ep":"bx2-14","n":"BX2-14","p":8,"a":"p8","id":"dg2","src":"assets/audio/BX2-14/dg2.mp3","sec":7.2,"t":"后来发现，一些 RNA 病毒能进行 RNA 复制，比如烟草花叶病毒。"},{"ep":"bx2-14","n":"BX2-14","p":8,"a":"p8","id":"dg3","src":"assets/audio/BX2-14/dg3.mp3","sec":8.424,"t":"有些病毒能以 RNA 为模板合成 DNA，即逆转录，需要逆转录酶，比如 HIV。"},{"ep":"bx2-14","n":"BX2-14","p":8,"a":"p8","id":"dg4","src":"assets/audio/BX2-14/dg4.mp3","sec":11.136,"t":"易错：RNA 复制和逆转录发生在被病毒侵染的宿主细胞中，病毒自己不能独立完成；正常细胞中一般没有这两个过程。"},{"ep":"bx2-14","n":"BX2-14","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-14/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-14","n":"BX2-14","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-14/rv2.mp3","sec":7.488,"t":"判断一？错，终止密码子一般不决定氨基酸。判断二？对。"},{"ep":"bx2-14","n":"BX2-14","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-14/rv3.mp3","sec":9.6,"t":"判断三？错，反密码子在 tRNA 上。判断四？错，每个核糖体各合成一条肽链。"},{"ep":"bx2-14","n":"BX2-14","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-14/rv4.mp3","sec":7.248,"t":"判断五？错，原核细胞才边转录边翻译。判断六？对。"},{"ep":"bx2-14","n":"BX2-14","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-14/rv5.mp3","sec":7.728,"t":"八个考点串成一条线：mRNA 是模板，tRNA 来搬运。我们下期再见！"},{"ep":"bx2-15","n":"BX2-15","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-15/in1.mp3","sec":7.752,"t":"同学们好！这节课梳理人教版必修二第四章第二节——基因表达与性状的关系。"},{"ep":"bx2-15","n":"BX2-15","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-15/in2.mp3","sec":6.6,"t":"高考常考基因控制性状的两条途径、细胞分化的实质和表观遗传。"},{"ep":"bx2-15","n":"BX2-15","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-15/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-15","n":"BX2-15","p":1,"a":"p1","id":"en1","src":"assets/audio/BX2-15/en1.mp3","sec":7.584,"t":"考点一，基因通过控制酶的合成来控制代谢过程，进而间接控制生物体的性状。"},{"ep":"bx2-15","n":"BX2-15","p":1,"a":"p1","id":"en2","src":"assets/audio/BX2-15/en2.mp3","sec":8.784,"t":"例一，白化病：控制酪氨酸酶的基因异常，不能合成酪氨酸酶，酪氨酸不能转变为黑色素。"},{"ep":"bx2-15","n":"BX2-15","p":1,"a":"p1","id":"en3","src":"assets/audio/BX2-15/en3.mp3","sec":14.424,"t":"例二，皱粒豌豆：编码淀粉分支酶的基因被插入了一段外来 DNA 序列，淀粉分支酶异常、活性大大降低，淀粉含量降低，豌豆成熟时失水皱缩。"},{"ep":"bx2-15","n":"BX2-15","p":1,"a":"p1","id":"en4","src":"assets/audio/BX2-15/en4.mp3","sec":6.768,"t":"解题方法：题中出现“某种酶”不能合成、代谢受阻，就是间接控制。"},{"ep":"bx2-15","n":"BX2-15","p":2,"a":"p2","id":"st1","src":"assets/audio/BX2-15/st1.mp3","sec":6.048,"t":"考点二，基因通过控制蛋白质的结构，直接控制生物体的性状。"},{"ep":"bx2-15","n":"BX2-15","p":2,"a":"p2","id":"st2","src":"assets/audio/BX2-15/st2.mp3","sec":14.544,"t":"例一，囊性纤维化：编码 CFTR 蛋白的基因缺失了 3 个碱基对，CFTR 蛋白第 508 位缺少苯丙氨酸，空间结构改变，转运氯离子的功能异常。"},{"ep":"bx2-15","n":"BX2-15","p":2,"a":"p2","id":"st3","src":"assets/audio/BX2-15/st3.mp3","sec":7.56,"t":"例二，镰状细胞贫血：血红蛋白中一个氨基酸被替换，红细胞变成镰刀状。"},{"ep":"bx2-15","n":"BX2-15","p":2,"a":"p2","id":"st4","src":"assets/audio/BX2-15/st4.mp3","sec":8.28,"t":"解题方法：结构蛋白、载体蛋白、血红蛋白这类非酶蛋白结构改变，是直接控制。"},{"ep":"bx2-15","n":"BX2-15","p":3,"a":"p3","id":"se1","src":"assets/audio/BX2-15/se1.mp3","sec":10.32,"t":"考点三，基因的选择性表达与细胞分化。同一个体的不同细胞，遗传物质相同，但表达的基因不完全相同。"},{"ep":"bx2-15","n":"BX2-15","p":3,"a":"p3","id":"se2","src":"assets/audio/BX2-15/se2.mp3","sec":13.776,"t":"一类基因在所有细胞中都表达，比如核糖体蛋白基因、ATP 合成酶基因；另一类只在某类细胞中特异性表达，比如卵清蛋白基因、胰岛素基因。"},{"ep":"bx2-15","n":"BX2-15","p":3,"a":"p3","id":"se3","src":"assets/audio/BX2-15/se3.mp3","sec":4.2,"t":"细胞分化的实质，就是基因的选择性表达。"},{"ep":"bx2-15","n":"BX2-15","p":3,"a":"p3","id":"se4","src":"assets/audio/BX2-15/se4.mp3","sec":9.432,"t":"易错：鸡的胰岛细胞中也有卵清蛋白基因和珠蛋白基因，只是不表达；细胞分化不改变遗传物质。"},{"ep":"bx2-15","n":"BX2-15","p":4,"a":"p4","id":"ep1","src":"assets/audio/BX2-15/ep1.mp3","sec":9.432,"t":"考点四，表观遗传的实例。柳穿鱼两种花形不同的植株，Lcyc 基因的碱基序列完全相同。"},{"ep":"bx2-15","n":"BX2-15","p":4,"a":"p4","id":"ep2","src":"assets/audio/BX2-15/ep2.mp3","sec":7.584,"t":"区别是：一种植株的 Lcyc 基因被高度甲基化，不能表达，花形就不同。"},{"ep":"bx2-15","n":"BX2-15","p":4,"a":"p4","id":"ep3","src":"assets/audio/BX2-15/ep3.mp3","sec":8.904,"t":"小鼠毛色也是这样：Avy 基因前端的甲基化程度不同，小鼠毛色从黄色到黑色深浅不一。"},{"ep":"bx2-15","n":"BX2-15","p":4,"a":"p4","id":"ep4","src":"assets/audio/BX2-15/ep4.mp3","sec":9.072,"t":"考法：表观遗传是生物体基因的碱基序列保持不变，但基因表达和表型发生可遗传变化的现象。"},{"ep":"bx2-15","n":"BX2-15","p":5,"a":"p5","id":"eq1","src":"assets/audio/BX2-15/eq1.mp3","sec":9.648,"t":"考点五，表观遗传的机制。DNA 甲基化：DNA 的某些碱基连接上甲基基团，抑制基因的表达。"},{"ep":"bx2-15","n":"BX2-15","p":5,"a":"p5","id":"eq2","src":"assets/audio/BX2-15/eq2.mp3","sec":7.584,"t":"此外，构成染色体的组蛋白发生甲基化、乙酰化等修饰，也会影响基因表达。"},{"ep":"bx2-15","n":"BX2-15","p":5,"a":"p5","id":"eq3","src":"assets/audio/BX2-15/eq3.mp3","sec":10.704,"t":"表观遗传的特点：可遗传；碱基序列不变；而且可能受环境影响，比如吸烟会使精子 DNA 甲基化水平升高。"},{"ep":"bx2-15","n":"BX2-15","p":5,"a":"p5","id":"eq4","src":"assets/audio/BX2-15/eq4.mp3","sec":9.24,"t":"易错：甲基化不改变碱基序列，所以不是基因突变；它主要抑制的是转录，而不是 DNA 复制。"},{"ep":"bx2-15","n":"BX2-15","p":6,"a":"p6","id":"re1","src":"assets/audio/BX2-15/re1.mp3","sec":6.864,"t":"考点六，基因与性状的关系。基因与性状不是简单的一一对应关系。"},{"ep":"bx2-15","n":"BX2-15","p":6,"a":"p6","id":"re2","src":"assets/audio/BX2-15/re2.mp3","sec":7.416,"t":"一个基因可以影响多个性状；一个性状也可以受多个基因的影响，比如人的身高。"},{"ep":"bx2-15","n":"BX2-15","p":6,"a":"p6","id":"re3","src":"assets/audio/BX2-15/re3.mp3","sec":8.352,"t":"基因与基因、基因与基因产物、基因与环境之间相互作用，精细地调控着生物体的性状。"},{"ep":"bx2-15","n":"BX2-15","p":6,"a":"p6","id":"re4","src":"assets/audio/BX2-15/re4.mp3","sec":9.192,"t":"考法：表型 = 基因型 + 环境。同一株水毛茛，水中和空气中的叶形不同，就是环境的影响。"},{"ep":"bx2-15","n":"BX2-15","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-15/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-15","n":"BX2-15","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-15/rv2.mp3","sec":7.992,"t":"判断一？错，白化病是通过控制酶的合成间接控制。判断二？对。"},{"ep":"bx2-15","n":"BX2-15","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-15/rv3.mp3","sec":8.328,"t":"判断三？错，遗传物质不变。判断四？错，甲基化不改变碱基序列。"},{"ep":"bx2-15","n":"BX2-15","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-15/rv4.mp3","sec":7.248,"t":"判断五？对。判断六？错，基因与性状不是一一对应的。"},{"ep":"bx2-15","n":"BX2-15","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-15/rv5.mp3","sec":6.408,"t":"六个考点串成一条线：序列不变，表达可变。我们下期再见！"},{"ep":"bx2-16","n":"BX2-16","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-16/in1.mp3","sec":7.752,"t":"同学们好！这节课梳理人教版必修二第五章第一节——基因突变和基因重组。"},{"ep":"bx2-16","n":"BX2-16","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-16/in2.mp3","sec":7.992,"t":"高考常考碱基变化对蛋白质的影响、细胞癌变、基因突变的特点和两种基因重组。"},{"ep":"bx2-16","n":"BX2-16","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-16/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-16","n":"BX2-16","p":1,"a":"p1","id":"sk1","src":"assets/audio/BX2-16/sk1.mp3","sec":9.0,"t":"考点一，镰状细胞贫血的病因。患者的红细胞呈镰刀状，容易破裂，使人患溶血性贫血。"},{"ep":"bx2-16","n":"BX2-16","p":1,"a":"p1","id":"sk2","src":"assets/audio/BX2-16/sk2.mp3","sec":5.232,"t":"直接原因：血红蛋白中一个谷氨酸被缬氨酸替换。"},{"ep":"bx2-16","n":"BX2-16","p":1,"a":"p1","id":"sk3","src":"assets/audio/BX2-16/sk3.mp3","sec":11.208,"t":"根本原因：血红蛋白基因中一个碱基对被替换，模板链上的 CTC 变成了 CAC，mRNA 上的 GAG 变成了 GUG。"},{"ep":"bx2-16","n":"BX2-16","p":1,"a":"p1","id":"sk4","src":"assets/audio/BX2-16/sk4.mp3","sec":9.6,"t":"考法：分清直接原因是蛋白质改变，根本原因是基因改变；可以用显微镜观察红细胞形态来诊断。"},{"ep":"bx2-16","n":"BX2-16","p":2,"a":"p2","id":"cn1","src":"assets/audio/BX2-16/cn1.mp3","sec":9.408,"t":"考点二，基因突变：DNA 分子中发生碱基的替换、增添或缺失，而引起的基因碱基序列的改变。"},{"ep":"bx2-16","n":"BX2-16","p":2,"a":"p2","id":"cn2","src":"assets/audio/BX2-16/cn2.mp3","sec":5.544,"t":"基因突变的结果是产生新基因，往往是原基因的等位基因。"},{"ep":"bx2-16","n":"BX2-16","p":2,"a":"p2","id":"cn3","src":"assets/audio/BX2-16/cn3.mp3","sec":8.4,"t":"基因突变主要发生在 DNA 复制时，也就是有丝分裂前的间期和减数分裂Ⅰ前的间期。"},{"ep":"bx2-16","n":"BX2-16","p":2,"a":"p2","id":"cn4","src":"assets/audio/BX2-16/cn4.mp3","sec":9.48,"t":"易错：DNA 上不是基因的片段发生碱基改变，不叫基因突变；基因突变在光学显微镜下看不到。"},{"ep":"bx2-16","n":"BX2-16","p":3,"a":"p3","id":"ef1","src":"assets/audio/BX2-16/ef1.mp3","sec":10.032,"t":"考点三，替换、增添、缺失对蛋白质的影响。替换一个碱基对：只改变一个密码子，影响较小。"},{"ep":"bx2-16","n":"BX2-16","p":3,"a":"p3","id":"ef2","src":"assets/audio/BX2-16/ef2.mp3","sec":9.552,"t":"可能氨基酸不变，因为密码子的简并；可能换成另一个氨基酸；也可能变成终止密码子，肽链提前终止。"},{"ep":"bx2-16","n":"BX2-16","p":3,"a":"p3","id":"ef3","src":"assets/audio/BX2-16/ef3.mp3","sec":7.512,"t":"增添或缺失一个碱基对：插入或缺失位置后面的密码子全部改变，影响较大。"},{"ep":"bx2-16","n":"BX2-16","p":3,"a":"p3","id":"ef4","src":"assets/audio/BX2-16/ef4.mp3","sec":13.272,"t":"解题方法：看氨基酸序列——只有一个氨基酸改变，多半是替换；后面一串都变，是增添或缺失。增添或缺失 3 个碱基对，影响相对小。"},{"ep":"bx2-16","n":"BX2-16","p":4,"a":"p4","id":"ca1","src":"assets/audio/BX2-16/ca1.mp3","sec":11.472,"t":"考点四，细胞的癌变。原癌基因表达的蛋白质是细胞正常生长和增殖所必需的，突变或过量表达会使细胞增殖失控。"},{"ep":"bx2-16","n":"BX2-16","p":4,"a":"p4","id":"ca2","src":"assets/audio/BX2-16/ca2.mp3","sec":11.016,"t":"抑癌基因表达的蛋白质能抑制细胞生长和增殖，或促进细胞凋亡，它突变后活性减弱或失去活性，也可能引起癌变。"},{"ep":"bx2-16","n":"BX2-16","p":4,"a":"p4","id":"ca3","src":"assets/audio/BX2-16/ca3.mp3","sec":9.888,"t":"癌细胞的特征：能够无限增殖；形态结构发生显著变化；细胞膜上糖蛋白减少，容易分散和转移。"},{"ep":"bx2-16","n":"BX2-16","p":4,"a":"p4","id":"ca4","src":"assets/audio/BX2-16/ca4.mp3","sec":10.512,"t":"易错：原癌基因和抑癌基因在正常细胞中都存在；癌变是多个基因突变累积的结果，不是一个基因突变就癌变。"},{"ep":"bx2-16","n":"BX2-16","p":5,"a":"p5","id":"fe1","src":"assets/audio/BX2-16/fe1.mp3","sec":11.688,"t":"考点五，基因突变的原因：物理因素如紫外线、X 射线；化学因素如亚硝酸盐、碱基类似物；生物因素如某些病毒。"},{"ep":"bx2-16","n":"BX2-16","p":5,"a":"p5","id":"fe2","src":"assets/audio/BX2-16/fe2.mp3","sec":5.28,"t":"没有外界诱发，DNA 复制偶尔出错，也会自发突变。"},{"ep":"bx2-16","n":"BX2-16","p":5,"a":"p5","id":"fe3","src":"assets/audio/BX2-16/fe3.mp3","sec":10.584,"t":"特点：普遍性，所有生物都可能发生；随机性，任何时期、任何 DNA、任何部位；不定向性；低频性。"},{"ep":"bx2-16","n":"BX2-16","p":5,"a":"p5","id":"fe4","src":"assets/audio/BX2-16/fe4.mp3","sec":10.776,"t":"易错：基因突变是不定向的，一个基因可以突变成多个等位基因；外界因素只是提高突变频率，不能决定突变方向。"},{"ep":"bx2-16","n":"BX2-16","p":6,"a":"p6","id":"me1","src":"assets/audio/BX2-16/me1.mp3","sec":10.416,"t":"考点六，基因突变的意义：基因突变是产生新基因的途径，是生物变异的根本来源，为生物进化提供了原材料。"},{"ep":"bx2-16","n":"BX2-16","p":6,"a":"p6","id":"me2","src":"assets/audio/BX2-16/me2.mp3","sec":11.496,"t":"基因突变的利害：可能破坏生物体与现有环境的协调关系而有害，也可能有利，如抗病性、耐旱性突变；还有些是中性的。"},{"ep":"bx2-16","n":"BX2-16","p":6,"a":"p6","id":"me3","src":"assets/audio/BX2-16/me3.mp3","sec":12.384,"t":"能否遗传：发生在生殖细胞中的，可以遗传给后代；发生在体细胞中的，一般不能通过有性生殖遗传，但植物可以通过无性生殖传递。"},{"ep":"bx2-16","n":"BX2-16","p":6,"a":"p6","id":"me4","src":"assets/audio/BX2-16/me4.mp3","sec":11.136,"t":"考法：基因突变一定改变基因，但不一定改变性状——比如密码子简并，或者 AA 突变成 Aa 隐性突变。"},{"ep":"bx2-16","n":"BX2-16","p":7,"a":"p7","id":"rc1","src":"assets/audio/BX2-16/rc1.mp3","sec":8.568,"t":"考点七，基因重组：在生物体进行有性生殖的过程中，控制不同性状的基因的重新组合。"},{"ep":"bx2-16","n":"BX2-16","p":7,"a":"p7","id":"rc2","src":"assets/audio/BX2-16/rc2.mp3","sec":6.768,"t":"类型一：减数分裂Ⅰ后期，非同源染色体上的非等位基因自由组合。"},{"ep":"bx2-16","n":"BX2-16","p":7,"a":"p7","id":"rc3","src":"assets/audio/BX2-16/rc3.mp3","sec":9.792,"t":"类型二：减数分裂Ⅰ前期，四分体中非姐妹染色单体互换，导致同源染色体上的非等位基因重组。"},{"ep":"bx2-16","n":"BX2-16","p":7,"a":"p7","id":"rc4","src":"assets/audio/BX2-16/rc4.mp3","sec":11.76,"t":"易错：基因重组不产生新基因，只产生新的基因型；受精时雌雄配子随机结合不是基因重组；一对等位基因的分离也不是。"},{"ep":"bx2-16","n":"BX2-16","p":8,"a":"p8","id":"cm1","src":"assets/audio/BX2-16/cm1.mp3","sec":10.368,"t":"考点八，基因突变与基因重组的比较。本质：突变改变基因的碱基序列；重组是原有基因的重新组合。"},{"ep":"bx2-16","n":"BX2-16","p":8,"a":"p8","id":"cm2","src":"assets/audio/BX2-16/cm2.mp3","sec":5.064,"t":"结果：突变产生新基因；重组产生新基因型。"},{"ep":"bx2-16","n":"BX2-16","p":8,"a":"p8","id":"cm3","src":"assets/audio/BX2-16/cm3.mp3","sec":9.552,"t":"意义：突变是生物变异的根本来源；基因重组也是生物变异的来源之一，对生物的进化具有重要意义。"},{"ep":"bx2-16","n":"BX2-16","p":8,"a":"p8","id":"cm4","src":"assets/audio/BX2-16/cm4.mp3","sec":8.28,"t":"解题方法：后代出现亲代没有的基因，是基因突变；只是出现新的组合，是基因重组。"},{"ep":"bx2-16","n":"BX2-16","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-16/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-16","n":"BX2-16","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-16/rv2.mp3","sec":7.056,"t":"判断一？错，基因突变不一定改变性状。判断二？对。"},{"ep":"bx2-16","n":"BX2-16","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-16/rv3.mp3","sec":8.208,"t":"判断三？错，正常细胞中都有。判断四？错，基因突变是不定向的。"},{"ep":"bx2-16","n":"BX2-16","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-16/rv4.mp3","sec":8.232,"t":"判断五？对。判断六？错，受精时配子随机结合不是基因重组。"},{"ep":"bx2-16","n":"BX2-16","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-16/rv5.mp3","sec":7.776,"t":"八个考点串成一条线：突变产生新基因，重组产生新组合。我们下期再见！"},{"ep":"bx2-17","n":"BX2-17","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-17/in1.mp3","sec":8.232,"t":"同学们好！这节课梳理人教版必修二第五章第二节的上半部分——染色体数目的变异。"},{"ep":"bx2-17","n":"BX2-17","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-17/in2.mp3","sec":8.16,"t":"高考常考染色体组数的判断、单倍体和多倍体、秋水仙素的作用和低温诱导实验。"},{"ep":"bx2-17","n":"BX2-17","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-17/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-17","n":"BX2-17","p":1,"a":"p1","id":"ty1","src":"assets/audio/BX2-17/ty1.mp3","sec":6.576,"t":"考点一，染色体变异包括染色体数目的变异和染色体结构的变异。"},{"ep":"bx2-17","n":"BX2-17","p":1,"a":"p1","id":"ty2","src":"assets/audio/BX2-17/ty2.mp3","sec":12.96,"t":"数目变异又分两类：个别染色体的增加或减少，比如 21 三体综合征；以及以染色体组的形式成倍增加或减少，比如三倍体无子西瓜。"},{"ep":"bx2-17","n":"BX2-17","p":1,"a":"p1","id":"ty3","src":"assets/audio/BX2-17/ty3.mp3","sec":9.072,"t":"考法：染色体变异在光学显微镜下可以观察到，而基因突变看不到——这是区分它们的常用依据。"},{"ep":"bx2-17","n":"BX2-17","p":2,"a":"p2","id":"ge1","src":"assets/audio/BX2-17/ge1.mp3","sec":12.072,"t":"考点二，染色体组：细胞中的一组非同源染色体，它们在形态和功能上各不相同，但携带着控制生物生长发育的全部遗传信息。"},{"ep":"bx2-17","n":"BX2-17","p":2,"a":"p2","id":"ge2","src":"assets/audio/BX2-17/ge2.mp3","sec":7.368,"t":"判断方法一：看图——形态、大小相同的染色体有几条，就有几个染色体组。"},{"ep":"bx2-17","n":"BX2-17","p":2,"a":"p2","id":"ge3","src":"assets/audio/BX2-17/ge3.mp3","sec":12.048,"t":"判断方法二：看基因型——控制同一性状的基因出现几次，就有几个染色体组。比如 AAaBBb 有 3 个。"},{"ep":"bx2-17","n":"BX2-17","p":2,"a":"p2","id":"ge4","src":"assets/audio/BX2-17/ge4.mp3","sec":8.928,"t":"易错：一个染色体组中没有同源染色体；但含有同源染色体的细胞，不一定只有两个染色体组。"},{"ep":"bx2-17","n":"BX2-17","p":3,"a":"p3","id":"pl1","src":"assets/audio/BX2-17/pl1.mp3","sec":9.264,"t":"考点三，由受精卵发育而来的个体，体细胞中含两个染色体组的叫二倍体，比如人和果蝇。"},{"ep":"bx2-17","n":"BX2-17","p":3,"a":"p3","id":"pl2","src":"assets/audio/BX2-17/pl2.mp3","sec":10.272,"t":"体细胞中含三个或三个以上染色体组的叫多倍体，比如三倍体香蕉、四倍体马铃薯、六倍体普通小麦。"},{"ep":"bx2-17","n":"BX2-17","p":3,"a":"p3","id":"pl3","src":"assets/audio/BX2-17/pl3.mp3","sec":9.048,"t":"多倍体的特点：茎秆粗壮，叶片、果实和种子都比较大，糖类和蛋白质等营养物质的含量增加。"},{"ep":"bx2-17","n":"BX2-17","p":3,"a":"p3","id":"pl4","src":"assets/audio/BX2-17/pl4.mp3","sec":10.512,"t":"易错：多倍体也有缺点，比如发育延迟、结实率低；三倍体减数分裂时联会紊乱，一般不能形成可育配子。"},{"ep":"bx2-17","n":"BX2-17","p":4,"a":"p4","id":"ha1","src":"assets/audio/BX2-17/ha1.mp3","sec":10.44,"t":"考点四，单倍体：体细胞中的染色体数目与本物种配子染色体数目相同的个体，也就是由配子直接发育而来。"},{"ep":"bx2-17","n":"BX2-17","p":4,"a":"p4","id":"ha2","src":"assets/audio/BX2-17/ha2.mp3","sec":10.008,"t":"单倍体不一定只含一个染色体组。六倍体小麦的配子有三个染色体组，由它发育成的单倍体也有三个。"},{"ep":"bx2-17","n":"BX2-17","p":4,"a":"p4","id":"ha3","src":"assets/audio/BX2-17/ha3.mp3","sec":4.704,"t":"单倍体的特点：植株长得弱小，而且高度不育。"},{"ep":"bx2-17","n":"BX2-17","p":4,"a":"p4","id":"ha4","src":"assets/audio/BX2-17/ha4.mp3","sec":12.12,"t":"解题方法：判断几倍体，先看来源——由配子发育来的，不管有几个染色体组，都是单倍体；由受精卵发育来的，再数染色体组。"},{"ep":"bx2-17","n":"BX2-17","p":5,"a":"p5","id":"co1","src":"assets/audio/BX2-17/co1.mp3","sec":9.072,"t":"考点五，人工诱导多倍体。最常用、最有效的方法是用秋水仙素处理萌发的种子或幼苗。"},{"ep":"bx2-17","n":"BX2-17","p":5,"a":"p5","id":"co2","src":"assets/audio/BX2-17/co2.mp3","sec":9.192,"t":"原理：秋水仙素能抑制纺锤体的形成，染色体不能移向细胞两极，细胞中染色体数目加倍。"},{"ep":"bx2-17","n":"BX2-17","p":5,"a":"p5","id":"co3","src":"assets/audio/BX2-17/co3.mp3","sec":5.52,"t":"低温处理也能抑制纺锤体形成，诱导染色体数目加倍。"},{"ep":"bx2-17","n":"BX2-17","p":5,"a":"p5","id":"co4","src":"assets/audio/BX2-17/co4.mp3","sec":11.4,"t":"易错：秋水仙素作用于分裂前期，不影响着丝粒分裂；处理对象要选分裂旺盛的部位，比如萌发的种子、幼苗的芽尖。"},{"ep":"bx2-17","n":"BX2-17","p":6,"a":"p6","id":"lt1","src":"assets/audio/BX2-17/lt1.mp3","sec":12.12,"t":"考点六，低温诱导实验。蒜或洋葱长出约 1 厘米的不定根后，放入冰箱冷藏室，在 4 ℃ 下诱导培养 48～72 小时。"},{"ep":"bx2-17","n":"BX2-17","p":6,"a":"p6","id":"lt2","src":"assets/audio/BX2-17/lt2.mp3","sec":10.632,"t":"剪取根尖 0.5～1 厘米，放入卡诺氏液中浸泡，固定细胞形态，然后用体积分数 95% 的酒精冲洗两次。"},{"ep":"bx2-17","n":"BX2-17","p":6,"a":"p6","id":"lt3","src":"assets/audio/BX2-17/lt3.mp3","sec":9.528,"t":"制片：解离、漂洗、染色、制片，和观察有丝分裂的步骤一样，用甲紫溶液等碱性染料染色。"},{"ep":"bx2-17","n":"BX2-17","p":6,"a":"p6","id":"lt4","src":"assets/audio/BX2-17/lt4.mp3","sec":11.136,"t":"易错：视野中只有少数细胞染色体数目加倍，大多数细胞处于分裂间期；看不到加倍的动态过程，因为细胞已经死亡。"},{"ep":"bx2-17","n":"BX2-17","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-17/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-17","n":"BX2-17","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-17/rv2.mp3","sec":6.888,"t":"判断一？对。判断二？错，由配子发育来的是单倍体。"},{"ep":"bx2-17","n":"BX2-17","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-17/rv3.mp3","sec":7.608,"t":"判断三？错，单倍体不一定只含一个染色体组。判断四？对。"},{"ep":"bx2-17","n":"BX2-17","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-17/rv4.mp3","sec":8.112,"t":"判断五？错，卡诺氏液用于固定。判断六？错，只有少数细胞加倍。"},{"ep":"bx2-17","n":"BX2-17","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-17/rv5.mp3","sec":6.912,"t":"六个考点串成一条线：先看来源，再数染色体组。我们下期再见！"},{"ep":"bx2-18","n":"BX2-18","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-18/in1.mp3","sec":8.712,"t":"同学们好！这节课梳理人教版必修二第五章第二节的下半部分——染色体结构变异与育种。"},{"ep":"bx2-18","n":"BX2-18","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-18/in2.mp3","sec":8.544,"t":"高考常考结构变异的类型判断、易位与互换的区别，以及无子西瓜和单倍体育种的流程。"},{"ep":"bx2-18","n":"BX2-18","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-18/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-18","n":"BX2-18","p":1,"a":"p1","id":"ty1","src":"assets/audio/BX2-18/ty1.mp3","sec":7.488,"t":"考点一，染色体结构变异的四种类型。缺失：染色体的某一片段缺失。"},{"ep":"bx2-18","n":"BX2-18","p":1,"a":"p1","id":"ty2","src":"assets/audio/BX2-18/ty2.mp3","sec":3.6,"t":"重复：染色体中增加某一片段。"},{"ep":"bx2-18","n":"BX2-18","p":1,"a":"p1","id":"ty3","src":"assets/audio/BX2-18/ty3.mp3","sec":5.52,"t":"易位：染色体的某一片段移接到另一条非同源染色体上。"},{"ep":"bx2-18","n":"BX2-18","p":1,"a":"p1","id":"ty4","src":"assets/audio/BX2-18/ty4.mp3","sec":3.792,"t":"倒位：染色体的某一片段位置颠倒。"},{"ep":"bx2-18","n":"BX2-18","p":1,"a":"p1","id":"ty5","src":"assets/audio/BX2-18/ty5.mp3","sec":10.296,"t":"解题方法：对照基因字母顺序——少了是缺失，多了是重复，顺序反了是倒位，换成了别的染色体上的基因是易位。"},{"ep":"bx2-18","n":"BX2-18","p":2,"a":"p2","id":"rs1","src":"assets/audio/BX2-18/rs1.mp3","sec":9.312,"t":"考点二，结构变异的结果：使排列在染色体上的基因的数目或排列顺序发生改变，导致性状变异。"},{"ep":"bx2-18","n":"BX2-18","p":2,"a":"p2","id":"rs2","src":"assets/audio/BX2-18/rs2.mp3","sec":6.84,"t":"大多数染色体结构变异对生物体是不利的，有的甚至会导致生物体死亡。"},{"ep":"bx2-18","n":"BX2-18","p":2,"a":"p2","id":"rs3","src":"assets/audio/BX2-18/rs3.mp3","sec":8.712,"t":"实例：猫叫综合征，是人的 5 号染色体部分缺失引起的，患儿哭声轻、音调高，像猫叫。"},{"ep":"bx2-18","n":"BX2-18","p":2,"a":"p2","id":"rs4","src":"assets/audio/BX2-18/rs4.mp3","sec":10.416,"t":"考法：结构变异不改变基因的结构，改变的是基因的数目和排列顺序；而基因突变改变的是基因内部的碱基序列。"},{"ep":"bx2-18","n":"BX2-18","p":3,"a":"p3","id":"sw1","src":"assets/audio/BX2-18/sw1.mp3","sec":9.624,"t":"考点三，易位与互换的区别。互换：发生在同源染色体的非姐妹染色单体之间，属于基因重组。"},{"ep":"bx2-18","n":"BX2-18","p":3,"a":"p3","id":"sw2","src":"assets/audio/BX2-18/sw2.mp3","sec":5.784,"t":"易位：发生在非同源染色体之间，属于染色体结构变异。"},{"ep":"bx2-18","n":"BX2-18","p":3,"a":"p3","id":"sw3","src":"assets/audio/BX2-18/sw3.mp3","sec":4.968,"t":"互换在光学显微镜下观察不到；易位可以观察到。"},{"ep":"bx2-18","n":"BX2-18","p":3,"a":"p3","id":"sw4","src":"assets/audio/BX2-18/sw4.mp3","sec":12.216,"t":"解题方法：看交换片段的两条染色体形态大小是否相同——相同是同源染色体，属于互换；不同是非同源染色体，属于易位。"},{"ep":"bx2-18","n":"BX2-18","p":4,"a":"p4","id":"mv1","src":"assets/audio/BX2-18/mv1.mp3","sec":11.232,"t":"考点四，基因突变与染色体结构变异的区分。基因突变发生在基因内部，是碱基的变化，基因的数目和位置不变。"},{"ep":"bx2-18","n":"BX2-18","p":4,"a":"p4","id":"mv2","src":"assets/audio/BX2-18/mv2.mp3","sec":8.616,"t":"染色体结构变异是染色体片段的变化，涉及一个或多个基因，基因数目或排列顺序改变。"},{"ep":"bx2-18","n":"BX2-18","p":4,"a":"p4","id":"mv3","src":"assets/audio/BX2-18/mv3.mp3","sec":7.248,"t":"比如基因 A 变成 a，是基因突变；基因 A 所在的片段丢了，是缺失。"},{"ep":"bx2-18","n":"BX2-18","p":4,"a":"p4","id":"mv4","src":"assets/audio/BX2-18/mv4.mp3","sec":12.408,"t":"解题方法：出现了新的等位基因，是基因突变；基因的数目或位置变了，是染色体结构变异；能否在显微镜下看到也可以帮助判断。"},{"ep":"bx2-18","n":"BX2-18","p":5,"a":"p5","id":"sl1","src":"assets/audio/BX2-18/sl1.mp3","sec":10.104,"t":"考点五，多倍体育种：三倍体无子西瓜。第一年，用秋水仙素处理二倍体西瓜幼苗，得到四倍体。"},{"ep":"bx2-18","n":"BX2-18","p":5,"a":"p5","id":"sl2","src":"assets/audio/BX2-18/sl2.mp3","sec":7.296,"t":"以四倍体为母本、二倍体为父本杂交，母本上结的西瓜里的种子是三倍体。"},{"ep":"bx2-18","n":"BX2-18","p":5,"a":"p5","id":"sl3","src":"assets/audio/BX2-18/sl3.mp3","sec":7.848,"t":"第二年，种下三倍体种子，开花时授以二倍体的花粉，刺激子房发育成果实。"},{"ep":"bx2-18","n":"BX2-18","p":5,"a":"p5","id":"sl4","src":"assets/audio/BX2-18/sl4.mp3","sec":7.344,"t":"三倍体减数分裂时联会紊乱，不能形成正常配子，所以果实没有种子。"},{"ep":"bx2-18","n":"BX2-18","p":5,"a":"p5","id":"sl5","src":"assets/audio/BX2-18/sl5.mp3","sec":11.112,"t":"易错：第二年授粉是为了刺激子房发育，不是为了受精；四倍体植株上结的西瓜，果肉是四倍体，种子才是三倍体。"},{"ep":"bx2-18","n":"BX2-18","p":6,"a":"p6","id":"hp1","src":"assets/audio/BX2-18/hp1.mp3","sec":10.8,"t":"考点六，单倍体育种。以 AaBb 为例，先取它的花药进行花药离体培养，得到 AB、Ab、aB、ab 四种单倍体幼苗。"},{"ep":"bx2-18","n":"BX2-18","p":6,"a":"p6","id":"hp2","src":"assets/audio/BX2-18/hp2.mp3","sec":10.536,"t":"再用秋水仙素处理单倍体幼苗，使染色体数目加倍，得到 AABB、AAbb 等纯合子。"},{"ep":"bx2-18","n":"BX2-18","p":6,"a":"p6","id":"hp3","src":"assets/audio/BX2-18/hp3.mp3","sec":5.064,"t":"优点：后代都是纯合子，能明显缩短育种年限。"},{"ep":"bx2-18","n":"BX2-18","p":6,"a":"p6","id":"hp4","src":"assets/audio/BX2-18/hp4.mp3","sec":11.544,"t":"易错：秋水仙素处理的是单倍体幼苗，单倍体高度不育，没有种子；育种的最终目的是得到可育的纯合植株，不是单倍体。"},{"ep":"bx2-18","n":"BX2-18","p":7,"a":"p7","id":"br1","src":"assets/audio/BX2-18/br1.mp3","sec":11.808,"t":"考点七，几种育种方法的比较。杂交育种：原理是基因重组，方法是杂交、自交、选优，缺点是育种时间长。"},{"ep":"bx2-18","n":"BX2-18","p":7,"a":"p7","id":"br2","src":"assets/audio/BX2-18/br2.mp3","sec":10.296,"t":"诱变育种：原理是基因突变，用辐射或化学因素诱变，能提高突变率，但有利变异少，需要大量处理材料。"},{"ep":"bx2-18","n":"BX2-18","p":7,"a":"p7","id":"br3","src":"assets/audio/BX2-18/br3.mp3","sec":11.808,"t":"单倍体育种：原理是染色体变异，明显缩短育种年限。{多倍体育种|brown}：原理也是染色体变异，器官大、营养物质含量高。"},{"ep":"bx2-18","n":"BX2-18","p":7,"a":"p7","id":"br4","src":"assets/audio/BX2-18/br4.mp3","sec":10.416,"t":"解题方法：题目要求“最简便”，选杂交育种；要求“最快”，选单倍体育种；要求“产生新性状”，选诱变育种。"},{"ep":"bx2-18","n":"BX2-18","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-18/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-18","n":"BX2-18","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-18/rv2.mp3","sec":4.584,"t":"判断一？对。判断二？对。"},{"ep":"bx2-18","n":"BX2-18","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-18/rv3.mp3","sec":9.984,"t":"判断三？错，易位发生在非同源染色体之间。判断四？错，无子性状是可遗传的变异。"},{"ep":"bx2-18","n":"BX2-18","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-18/rv4.mp3","sec":7.296,"t":"判断五？错，目的是得到可育的纯合植株。判断六？对。"},{"ep":"bx2-18","n":"BX2-18","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-18/rv5.mp3","sec":7.656,"t":"七个考点串成一条线：易位找非同源，单倍体育种缩年限。我们下期再见！"},{"ep":"bx2-19","n":"BX2-19","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-19/in1.mp3","sec":6.84,"t":"同学们好！这节课梳理人教版必修二第五章第三节——人类遗传病。"},{"ep":"bx2-19","n":"BX2-19","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-19/in2.mp3","sec":8.088,"t":"高考常考遗传病的类型和实例、21 三体综合征的成因、调查方法和检测预防。"},{"ep":"bx2-19","n":"BX2-19","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-19/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-19","n":"BX2-19","p":1,"a":"p1","id":"ty1","src":"assets/audio/BX2-19/ty1.mp3","sec":5.928,"t":"考点一，人类遗传病：由遗传物质改变而引起的人类疾病。"},{"ep":"bx2-19","n":"BX2-19","p":1,"a":"p1","id":"ty2","src":"assets/audio/BX2-19/ty2.mp3","sec":6.576,"t":"主要分三类：单基因遗传病、多基因遗传病和染色体异常遗传病。"},{"ep":"bx2-19","n":"BX2-19","p":1,"a":"p1","id":"ty3","src":"assets/audio/BX2-19/ty3.mp3","sec":11.088,"t":"易错：单基因遗传病是受一对等位基因控制的遗传病，不是一个基因；多基因遗传病是受两对或两对以上等位基因控制。"},{"ep":"bx2-19","n":"BX2-19","p":2,"a":"p2","id":"si1","src":"assets/audio/BX2-19/si1.mp3","sec":8.256,"t":"考点二，单基因遗传病的归类。常染色体显性：多指、并指、软骨发育不全。"},{"ep":"bx2-19","n":"BX2-19","p":2,"a":"p2","id":"si2","src":"assets/audio/BX2-19/si2.mp3","sec":7.128,"t":"常染色体隐性：白化病、苯丙酮尿症、镰状细胞贫血、囊性纤维化。"},{"ep":"bx2-19","n":"BX2-19","p":2,"a":"p2","id":"si3","src":"assets/audio/BX2-19/si3.mp3","sec":9.288,"t":"伴 X 显性：抗维生素 D 佝偻病。伴 X 隐性：红绿色盲、血友病、进行性肌营养不良。"},{"ep":"bx2-19","n":"BX2-19","p":2,"a":"p2","id":"si4","src":"assets/audio/BX2-19/si4.mp3","sec":7.392,"t":"考法：常常给出病名，让你判断遗传方式或计算概率——这些实例要记熟。"},{"ep":"bx2-19","n":"BX2-19","p":3,"a":"p3","id":"mu1","src":"assets/audio/BX2-19/mu1.mp3","sec":6.624,"t":"考点三，多基因遗传病：受两对或两对以上等位基因控制的遗传病。"},{"ep":"bx2-19","n":"BX2-19","p":3,"a":"p3","id":"mu2","src":"assets/audio/BX2-19/mu2.mp3","sec":6.336,"t":"实例：原发性高血压、冠心病、哮喘、青少年型糖尿病。"},{"ep":"bx2-19","n":"BX2-19","p":3,"a":"p3","id":"mu3","src":"assets/audio/BX2-19/mu3.mp3","sec":7.92,"t":"特点：在群体中发病率较高；容易受环境因素影响；常表现出家族聚集现象。"},{"ep":"bx2-19","n":"BX2-19","p":3,"a":"p3","id":"mu4","src":"assets/audio/BX2-19/mu4.mp3","sec":13.248,"t":"易错：多基因遗传病不遵循孟德尔遗传规律那样简单的比例，所以调查遗传病时一般不选多基因遗传病，而选发病率较高的单基因遗传病。"},{"ep":"bx2-19","n":"BX2-19","p":4,"a":"p4","id":"ch1","src":"assets/audio/BX2-19/ch1.mp3","sec":5.904,"t":"考点四，染色体异常遗传病：由染色体变异引起的遗传病。"},{"ep":"bx2-19","n":"BX2-19","p":4,"a":"p4","id":"ch2","src":"assets/audio/BX2-19/ch2.mp3","sec":15.048,"t":"结构异常：如猫叫综合征，5 号染色体部分缺失。数目异常：如唐氏综合征（21 三体综合征），患者体细胞中多了一条 21 号染色体，共 47 条。"},{"ep":"bx2-19","n":"BX2-19","p":4,"a":"p4","id":"ch3","src":"assets/audio/BX2-19/ch3.mp3","sec":12.912,"t":"21 三体的成因：亲代形成配子时，减数分裂Ⅰ或减数分裂Ⅱ中 21 号染色体没有正常分离，产生了含两条 21 号染色体的配子。"},{"ep":"bx2-19","n":"BX2-19","p":4,"a":"p4","id":"ch4","src":"assets/audio/BX2-19/ch4.mp3","sec":10.272,"t":"易错：染色体异常遗传病患者不一定携带致病基因；它可以用显微镜观察染色体来诊断，而单基因病不能。"},{"ep":"bx2-19","n":"BX2-19","p":5,"a":"p5","id":"su1","src":"assets/audio/BX2-19/su1.mp3","sec":10.776,"t":"考点五，调查人群中的遗传病。选择群体中发病率较高的单基因遗传病，比如红绿色盲、白化病、高度近视。"},{"ep":"bx2-19","n":"BX2-19","p":5,"a":"p5","id":"su2","src":"assets/audio/BX2-19/su2.mp3","sec":6.264,"t":"调查发病率：在人群中随机抽样调查，调查的群体要足够大。"},{"ep":"bx2-19","n":"BX2-19","p":5,"a":"p5","id":"su3","src":"assets/audio/BX2-19/su3.mp3","sec":5.736,"t":"调查遗传方式：在患者家系中调查，绘制遗传系谱图。"},{"ep":"bx2-19","n":"BX2-19","p":5,"a":"p5","id":"su4","src":"assets/audio/BX2-19/su4.mp3","sec":5.208,"t":"发病率 = 患病人数 ÷ 被调查人数 × 100%。"},{"ep":"bx2-19","n":"BX2-19","p":5,"a":"p5","id":"su5","src":"assets/audio/BX2-19/su5.mp3","sec":6.024,"t":"解题方法：一句话记住——发病率在人群，遗传方式在家系。"},{"ep":"bx2-19","n":"BX2-19","p":6,"a":"p6","id":"pv1","src":"assets/audio/BX2-19/pv1.mp3","sec":6.888,"t":"考点六，遗传病的检测和预防，主要手段是遗传咨询和产前诊断。"},{"ep":"bx2-19","n":"BX2-19","p":6,"a":"p6","id":"pv2","src":"assets/audio/BX2-19/pv2.mp3","sec":9.936,"t":"遗传咨询：了解家族病史，分析遗传病的传递方式，推算后代的再发风险率，提出防治对策和建议。"},{"ep":"bx2-19","n":"BX2-19","p":6,"a":"p6","id":"pv3","src":"assets/audio/BX2-19/pv3.mp3","sec":10.752,"t":"产前诊断：羊水检查、B 超检查、孕妇血细胞检查和基因检测等，确定胎儿是否患有遗传病或先天性疾病。"},{"ep":"bx2-19","n":"BX2-19","p":6,"a":"p6","id":"pv4","src":"assets/audio/BX2-19/pv4.mp3","sec":12.288,"t":"易错：唐氏综合征是染色体数目异常，可以通过羊水检查做染色体分析来诊断；禁止近亲结婚主要降低隐性遗传病的发病率。"},{"ep":"bx2-19","n":"BX2-19","p":7,"a":"p7","id":"pf1","src":"assets/audio/BX2-19/pf1.mp3","sec":12.336,"t":"考点七，三个概念的辨析。先天性疾病：出生时就有的疾病，不一定是遗传病，比如母亲孕期感染风疹导致的先天性心脏病。"},{"ep":"bx2-19","n":"BX2-19","p":7,"a":"p7","id":"pf2","src":"assets/audio/BX2-19/pf2.mp3","sec":9.096,"t":"家族性疾病：一个家族中多个成员患病，不一定是遗传病，比如饮食缺碘引起的地方性甲状腺肿。"},{"ep":"bx2-19","n":"BX2-19","p":7,"a":"p7","id":"pf3","src":"assets/audio/BX2-19/pf3.mp3","sec":7.968,"t":"遗传病：不一定出生就发病，比如有些遗传病到成年才发病；也不一定有家族史。"},{"ep":"bx2-19","n":"BX2-19","p":7,"a":"p7","id":"pf4","src":"assets/audio/BX2-19/pf4.mp3","sec":6.528,"t":"解题方法：判断是不是遗传病，只看一点——遗传物质有没有改变。"},{"ep":"bx2-19","n":"BX2-19","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-19/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-19","n":"BX2-19","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-19/rv2.mp3","sec":6.432,"t":"判断一？错，是一对等位基因控制。判断二？对。"},{"ep":"bx2-19","n":"BX2-19","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-19/rv3.mp3","sec":7.656,"t":"判断三？对。判断四？错，遗传方式要在患者家系中调查。"},{"ep":"bx2-19","n":"BX2-19","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-19/rv4.mp3","sec":7.968,"t":"判断五？错，第一步是了解家族病史、作出诊断。判断六？对。"},{"ep":"bx2-19","n":"BX2-19","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-19/rv5.mp3","sec":7.464,"t":"七个考点串成一条线：发病率在人群，遗传方式在家系。我们下期再见！"},{"ep":"bx2-20","n":"BX2-20","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-20/in1.mp3","sec":7.776,"t":"同学们好！这节课梳理人教版必修二第六章第一节——生物有共同祖先的证据。"},{"ep":"bx2-20","n":"BX2-20","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-20/in2.mp3","sec":6.528,"t":"高考常考化石证据、同源器官，以及用分子差异判断亲缘关系。"},{"ep":"bx2-20","n":"BX2-20","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-20/in3.mp3","sec":5.448,"t":"我们按五个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-20","n":"BX2-20","p":1,"a":"p1","id":"fo1","src":"assets/audio/BX2-20/fo1.mp3","sec":9.504,"t":"考点一，化石证据。化石是通过自然作用保存在地层中的古代生物的遗体、遗物或生活痕迹。"},{"ep":"bx2-20","n":"BX2-20","p":1,"a":"p1","id":"fo2","src":"assets/audio/BX2-20/fo2.mp3","sec":4.536,"t":"化石是研究生物进化最直接、最重要的证据。"},{"ep":"bx2-20","n":"BX2-20","p":1,"a":"p1","id":"fo3","src":"assets/audio/BX2-20/fo3.mp3","sec":10.392,"t":"规律：越古老的地层中，生物越简单、低等，水生的多；越新近的地层中，生物越复杂、高等，陆生的多。"},{"ep":"bx2-20","n":"BX2-20","p":1,"a":"p1","id":"fo4","src":"assets/audio/BX2-20/fo4.mp3","sec":11.568,"t":"考法：赫氏近鸟龙化石的骨架与恐龙非常接近，周围又有清晰的羽毛印痕，为鸟类起源于恐龙的假说提供了有力证据。"},{"ep":"bx2-20","n":"BX2-20","p":2,"a":"p2","id":"an1","src":"assets/audio/BX2-20/an1.mp3","sec":9.648,"t":"考点二，比较解剖学证据。蝙蝠的翼、鲸的鳍、猫的前肢和人的上肢，外形和功能差别很大。"},{"ep":"bx2-20","n":"BX2-20","p":2,"a":"p2","id":"an2","src":"assets/audio/BX2-20/an2.mp3","sec":6.432,"t":"但它们的骨骼组成和排列方式很相似，这样的器官叫同源器官。"},{"ep":"bx2-20","n":"BX2-20","p":2,"a":"p2","id":"an3","src":"assets/audio/BX2-20/an3.mp3","sec":9.744,"t":"同源器官说明这些生物是由共同的原始祖先进化来的，在不同环境中适应不同的功能，才出现了差异。"},{"ep":"bx2-20","n":"BX2-20","p":2,"a":"p2","id":"an4","src":"assets/audio/BX2-20/an4.mp3","sec":10.632,"t":"易错：判断同源器官看起源和结构，不看功能；人的阑尾、鲸的后肢骨这类痕迹器官，也是比较解剖学证据。"},{"ep":"bx2-20","n":"BX2-20","p":3,"a":"p3","id":"em1","src":"assets/audio/BX2-20/em1.mp3","sec":8.376,"t":"考点三，胚胎学证据。人和鱼、鸡、猪等脊椎动物，胚胎发育早期都很相似。"},{"ep":"bx2-20","n":"BX2-20","p":3,"a":"p3","id":"em2","src":"assets/audio/BX2-20/em2.mp3","sec":6.408,"t":"比如胚胎早期都有鳃裂和尾；后来人的鳃裂消失，尾也消失了。"},{"ep":"bx2-20","n":"BX2-20","p":3,"a":"p3","id":"em3","src":"assets/audio/BX2-20/em3.mp3","sec":11.304,"t":"考法：胚胎早期越相似，说明它们有共同祖先；鱼的鳃裂发育成鳃，而人的消失，说明人和鱼的祖先都在水中生活。"},{"ep":"bx2-20","n":"BX2-20","p":4,"a":"p4","id":"mo1","src":"assets/audio/BX2-20/mo1.mp3","sec":10.488,"t":"考点四，细胞和分子水平的证据。细胞水平：生物都由细胞构成，细胞有共同的物质基础和结构基础。"},{"ep":"bx2-20","n":"BX2-20","p":4,"a":"p4","id":"mo2","src":"assets/audio/BX2-20/mo2.mp3","sec":6.0,"t":"分子水平：生物都以 DNA 为遗传物质，共用一套遗传密码。"},{"ep":"bx2-20","n":"BX2-20","p":4,"a":"p4","id":"mo3","src":"assets/audio/BX2-20/mo3.mp3","sec":13.536,"t":"不同生物的 DNA 和蛋白质等分子，既有共同点，又有差异。比如细胞色素 c：人和黑猩猩的氨基酸序列完全相同，人和酵母菌差异较大。"},{"ep":"bx2-20","n":"BX2-20","p":4,"a":"p4","id":"mo4","src":"assets/audio/BX2-20/mo4.mp3","sec":7.032,"t":"解题方法：分子差异越小，亲缘关系越近，在进化史上分开得越晚。"},{"ep":"bx2-20","n":"BX2-20","p":5,"a":"p5","id":"cb1","src":"assets/audio/BX2-20/cb1.mp3","sec":10.536,"t":"考点五，证据的综合运用。化石是直接证据；比较解剖学、胚胎学、细胞和分子水平的证据，相互印证。"},{"ep":"bx2-20","n":"BX2-20","p":5,"a":"p5","id":"cb2","src":"assets/audio/BX2-20/cb2.mp3","sec":4.968,"t":"分子证据还能定量判断亲缘关系，构建进化树。"},{"ep":"bx2-20","n":"BX2-20","p":5,"a":"p5","id":"cb3","src":"assets/audio/BX2-20/cb3.mp3","sec":10.848,"t":"考法：给出几种生物的氨基酸或碱基差异数，让你排出亲缘关系远近——差异数从小到大，就是亲缘关系从近到远。"},{"ep":"bx2-20","n":"BX2-20","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-20/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-20","n":"BX2-20","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-20/rv2.mp3","sec":7.8,"t":"判断一？对。判断二？错，越古老的地层生物越简单、低等。"},{"ep":"bx2-20","n":"BX2-20","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-20/rv3.mp3","sec":4.656,"t":"判断三？对。判断四？对。"},{"ep":"bx2-20","n":"BX2-20","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-20/rv4.mp3","sec":6.84,"t":"判断五？错，差异越小亲缘关系越近。判断六？对。"},{"ep":"bx2-20","n":"BX2-20","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-20/rv5.mp3","sec":6.408,"t":"五个考点串成一条线：差异越小，亲缘越近。我们下期再见！"},{"ep":"bx2-21","n":"BX2-21","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-21/in1.mp3","sec":7.776,"t":"同学们好！这节课梳理人教版必修二第六章第二节——自然选择与适应的形成。"},{"ep":"bx2-21","n":"BX2-21","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-21/in2.mp3","sec":6.936,"t":"高考常考拉马克与达尔文观点的辨析、自然选择的过程和抗药性的形成。"},{"ep":"bx2-21","n":"BX2-21","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-21/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-21","n":"BX2-21","p":1,"a":"p1","id":"ad1","src":"assets/audio/BX2-21/ad1.mp3","sec":11.808,"t":"考点一，适应：生物的形态结构适合于完成一定的功能，生物的形态结构及其功能适合于该生物在一定的环境中生存和繁殖。"},{"ep":"bx2-21","n":"BX2-21","p":1,"a":"p1","id":"ad2","src":"assets/audio/BX2-21/ad2.mp3","sec":8.448,"t":"适应具有普遍性：比如枯叶蝶像枯叶，仙人掌的叶变成刺，雷鸟冬季换上白色羽毛。"},{"ep":"bx2-21","n":"BX2-21","p":1,"a":"p1","id":"ad3","src":"assets/audio/BX2-21/ad3.mp3","sec":9.24,"t":"适应又具有相对性：雷鸟冬季白羽，如果降雪推迟，白色的雷鸟在褐色的地面上反而很显眼。"},{"ep":"bx2-21","n":"BX2-21","p":1,"a":"p1","id":"ad4","src":"assets/audio/BX2-21/ad4.mp3","sec":6.768,"t":"考法：适应的相对性来自遗传的稳定性与环境的不断变化之间的矛盾。"},{"ep":"bx2-21","n":"BX2-21","p":2,"a":"p2","id":"la1","src":"assets/audio/BX2-21/la1.mp3","sec":9.192,"t":"考点二，拉马克的进化学说。他认为生物是由更古老的生物进化来的，由低等到高等逐渐进化。"},{"ep":"bx2-21","n":"BX2-21","p":2,"a":"p2","id":"la2","src":"assets/audio/BX2-21/la2.mp3","sec":11.352,"t":"核心观点：用进废退和获得性遗传。器官经常使用就发达，不用就退化；这种后天获得的性状能遗传给后代。"},{"ep":"bx2-21","n":"BX2-21","p":2,"a":"p2","id":"la3","src":"assets/audio/BX2-21/la3.mp3","sec":8.04,"t":"例：长颈鹿的祖先经常伸长脖子吃高处的树叶，脖子越来越长，并遗传给后代。"},{"ep":"bx2-21","n":"BX2-21","p":2,"a":"p2","id":"la4","src":"assets/audio/BX2-21/la4.mp3","sec":8.28,"t":"解题方法：说法中出现“为了”“经常使用”“环境导致产生某种变异”，多半是拉马克的观点。"},{"ep":"bx2-21","n":"BX2-21","p":3,"a":"p3","id":"da1","src":"assets/audio/BX2-21/da1.mp3","sec":9.432,"t":"考点三，达尔文的自然选择学说，可以概括为四点。第一，过度繁殖：生物都有很强的繁殖能力。"},{"ep":"bx2-21","n":"BX2-21","p":3,"a":"p3","id":"da2","src":"assets/audio/BX2-21/da2.mp3","sec":5.88,"t":"第二，生存斗争：资源有限，个体之间为生存而斗争。"},{"ep":"bx2-21","n":"BX2-21","p":3,"a":"p3","id":"da3","src":"assets/audio/BX2-21/da3.mp3","sec":6.504,"t":"第三，遗传变异：个体之间存在差异，有的变异有利，有的不利。"},{"ep":"bx2-21","n":"BX2-21","p":3,"a":"p3","id":"da4","src":"assets/audio/BX2-21/da4.mp3","sec":8.448,"t":"第四，适者生存：具有有利变异的个体容易存活并留下后代，不利变异的个体被淘汰。"},{"ep":"bx2-21","n":"BX2-21","p":3,"a":"p3","id":"da5","src":"assets/audio/BX2-21/da5.mp3","sec":8.16,"t":"考法：过度繁殖是前提，生存斗争是动力，遗传变异是内因，适者生存是结果。"},{"ep":"bx2-21","n":"BX2-21","p":4,"a":"p4","id":"fm1","src":"assets/audio/BX2-21/fm1.mp3","sec":8.592,"t":"考点四，适应的形成。长颈鹿祖先中原本就有颈长的和颈短的，这是可遗传的变异。"},{"ep":"bx2-21","n":"BX2-21","p":4,"a":"p4","id":"fm2","src":"assets/audio/BX2-21/fm2.mp3","sec":7.512,"t":"食物缺乏时，颈长的能吃到高处的树叶，更容易存活和繁殖；颈短的被淘汰。"},{"ep":"bx2-21","n":"BX2-21","p":4,"a":"p4","id":"fm3","src":"assets/audio/BX2-21/fm3.mp3","sec":5.856,"t":"经过一代代自然选择，有利变异逐代积累，就形成了长颈鹿。"},{"ep":"bx2-21","n":"BX2-21","p":4,"a":"p4","id":"fm4","src":"assets/audio/BX2-21/fm4.mp3","sec":10.392,"t":"考法：适应是自然选择的结果；群体中出现可遗传的有利变异和环境的定向选择，是适应形成的必要条件。"},{"ep":"bx2-21","n":"BX2-21","p":5,"a":"p5","id":"ev1","src":"assets/audio/BX2-21/ev1.mp3","sec":13.824,"t":"考点五，达尔文学说的意义：使生物学第一次摆脱了神学的束缚，揭示了生物界的统一性是由于所有生物都有共同祖先，多样性和适应性是进化的结果。"},{"ep":"bx2-21","n":"BX2-21","p":5,"a":"p5","id":"ev2","src":"assets/audio/BX2-21/ev2.mp3","sec":5.256,"t":"局限性：对遗传和变异的本质不能做出科学的解释。"},{"ep":"bx2-21","n":"BX2-21","p":5,"a":"p5","id":"ev3","src":"assets/audio/BX2-21/ev3.mp3","sec":10.08,"t":"对生物进化的解释局限于个体水平；强调物种形成都是渐变的结果，不能很好地解释物种大爆发等现象。"},{"ep":"bx2-21","n":"BX2-21","p":5,"a":"p5","id":"ev4","src":"assets/audio/BX2-21/ev4.mp3","sec":8.856,"t":"易错：现代生物进化理论认为进化的基本单位是种群，不是个体——这是对达尔文学说的发展。"},{"ep":"bx2-21","n":"BX2-21","p":6,"a":"p6","id":"or1","src":"assets/audio/BX2-21/or1.mp3","sec":5.184,"t":"考点六，最常考的易错点：变异在前，选择在后。"},{"ep":"bx2-21","n":"BX2-21","p":6,"a":"p6","id":"or2","src":"assets/audio/BX2-21/or2.mp3","sec":8.664,"t":"以害虫抗药性为例：害虫群体中本来就存在抗药性个体，农药只是把不抗药的个体杀死。"},{"ep":"bx2-21","n":"BX2-21","p":6,"a":"p6","id":"or3","src":"assets/audio/BX2-21/or3.mp3","sec":6.84,"t":"抗药个体存活并繁殖，抗药基因的频率逐代升高，农药效果越来越差。"},{"ep":"bx2-21","n":"BX2-21","p":6,"a":"p6","id":"or4","src":"assets/audio/BX2-21/or4.mp3","sec":8.904,"t":"易错：“农药使害虫产生了抗药性变异”是错的。变异是不定向的，环境只起选择作用。"},{"ep":"bx2-21","n":"BX2-21","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-21/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-21","n":"BX2-21","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-21/rv2.mp3","sec":5.976,"t":"判断一？对。判断二？对，这是用进废退。"},{"ep":"bx2-21","n":"BX2-21","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-21/rv3.mp3","sec":10.104,"t":"判断三？错，变异不定向，环境只起选择作用。判断四？错，这正是达尔文学说的局限。"},{"ep":"bx2-21","n":"BX2-21","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-21/rv4.mp3","sec":7.032,"t":"判断五？错，抗药性变异原本就存在。判断六？对。"},{"ep":"bx2-21","n":"BX2-21","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-21/rv5.mp3","sec":6.36,"t":"六个考点串成一条线：变异在前，选择在后。我们下期再见！"},{"ep":"bx2-22","n":"BX2-22","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-22/in1.mp3","sec":8.52,"t":"同学们好！这节课梳理人教版必修二第六章第三节的上半部分——种群基因组成的变化。"},{"ep":"bx2-22","n":"BX2-22","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-22/in2.mp3","sec":5.808,"t":"高考常考基因频率的计算、遗传平衡定律和进化的实质。"},{"ep":"bx2-22","n":"BX2-22","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-22/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-22","n":"BX2-22","p":1,"a":"p1","id":"po1","src":"assets/audio/BX2-22/po1.mp3","sec":9.168,"t":"考点一，种群：生活在一定区域的同种生物全部个体的集合。种群是生物进化的基本单位。"},{"ep":"bx2-22","n":"BX2-22","p":1,"a":"p1","id":"po2","src":"assets/audio/BX2-22/po2.mp3","sec":5.016,"t":"基因库：一个种群中全部个体所含有的全部基因。"},{"ep":"bx2-22","n":"BX2-22","p":1,"a":"p1","id":"po3","src":"assets/audio/BX2-22/po3.mp3","sec":6.504,"t":"基因频率：在一个种群基因库中，某个基因占全部等位基因数的比值。"},{"ep":"bx2-22","n":"BX2-22","p":1,"a":"p1","id":"po4","src":"assets/audio/BX2-22/po4.mp3","sec":10.056,"t":"易错：基因库是全部个体的全部基因，不是某一个体的；个体会死亡，但基因库可以在繁殖中保留和发展。"},{"ep":"bx2-22","n":"BX2-22","p":2,"a":"p2","id":"fq1","src":"assets/audio/BX2-22/fq1.mp3","sec":8.904,"t":"考点二，基因频率的计算。方法一，数基因：A 的频率 = A 的个数 ÷ (A + a 的总数)。"},{"ep":"bx2-22","n":"BX2-22","p":2,"a":"p2","id":"fq2","src":"assets/audio/BX2-22/fq2.mp3","sec":15.264,"t":"例：100 个个体中 AA 30 个、Aa 60 个、aa 10 个。A 有 30 × 2 + 60 = 120 个，总共 200 个，A 的频率 = 60%。"},{"ep":"bx2-22","n":"BX2-22","p":2,"a":"p2","id":"fq3","src":"assets/audio/BX2-22/fq3.mp3","sec":13.152,"t":"方法二，用基因型频率：A 的频率 = AA 的频率 + 1/2 Aa 的频率 = 30% + 30% = 60%。"},{"ep":"bx2-22","n":"BX2-22","p":2,"a":"p2","id":"fq4","src":"assets/audio/BX2-22/fq4.mp3","sec":6.24,"t":"易错：A 和 a 的频率之和等于 1；基因型频率之和也等于 1。"},{"ep":"bx2-22","n":"BX2-22","p":3,"a":"p3","id":"hw1","src":"assets/audio/BX2-22/hw1.mp3","sec":10.08,"t":"考点三，遗传平衡定律，也叫哈迪—温伯格定律。设 A 的频率为 p，a 的频率为 q，p + q = 1。"},{"ep":"bx2-22","n":"BX2-22","p":3,"a":"p3","id":"hw2","src":"assets/audio/BX2-22/hw2.mp3","sec":11.904,"t":"在理想条件下，AA = p2，Aa = 2pq，aa = q2，基因频率和基因型频率都世代不变。"},{"ep":"bx2-22","n":"BX2-22","p":3,"a":"p3","id":"hw3","src":"assets/audio/BX2-22/hw3.mp3","sec":7.752,"t":"理想条件：种群非常大，随机交配，没有迁入迁出，没有自然选择，没有突变。"},{"ep":"bx2-22","n":"BX2-22","p":3,"a":"p3","id":"hw4","src":"assets/audio/BX2-22/hw4.mp3","sec":13.752,"t":"解题方法：已知隐性个体 aa 占 1%，则 q = 0.1，p = 0.9，携带者 Aa = 2 × 0.9 × 0.1 = 18%。"},{"ep":"bx2-22","n":"BX2-22","p":4,"a":"p4","id":"xf1","src":"assets/audio/BX2-22/xf1.mp3","sec":10.104,"t":"考点四，X 染色体上基因频率的计算。男性只有一条 X，Y 上没有对应的基因，所以男性只算一个。"},{"ep":"bx2-22","n":"BX2-22","p":4,"a":"p4","id":"xf2","src":"assets/audio/BX2-22/xf2.mp3","sec":6.48,"t":"X[b] 的频率 = X[b] 的个数 ÷ (女性人数 × 2 + 男性人数)。"},{"ep":"bx2-22","n":"BX2-22","p":4,"a":"p4","id":"xf3","src":"assets/audio/BX2-22/xf3.mp3","sec":17.328,"t":"规律：男性中色盲的发病率，就等于 X[b] 的基因频率。例：男性色盲约占 8%，则 X[b] 频率约为 8%，女性色盲约为 8% × 8% = 0.64%。"},{"ep":"bx2-22","n":"BX2-22","p":4,"a":"p4","id":"xf4","src":"assets/audio/BX2-22/xf4.mp3","sec":5.4,"t":"易错：分母不能写成“总人数 × 2”，男性只有一个 X。"},{"ep":"bx2-22","n":"BX2-22","p":5,"a":"p5","id":"mu1","src":"assets/audio/BX2-22/mu1.mp3","sec":8.856,"t":"考点五，突变和基因重组提供进化的原材料。这里的突变包括基因突变和染色体变异。"},{"ep":"bx2-22","n":"BX2-22","p":5,"a":"p5","id":"mu2","src":"assets/audio/BX2-22/mu2.mp3","sec":9.888,"t":"突变频率虽然低，但种群中个体数多，每一代都会产生大量突变；突变和重组都是随机的、不定向的。"},{"ep":"bx2-22","n":"BX2-22","p":5,"a":"p5","id":"mu3","src":"assets/audio/BX2-22/mu3.mp3","sec":9.96,"t":"易错：突变的有害或有利不是绝对的，取决于生物的生存环境；只有可遗传的变异才能为进化提供原材料。"},{"ep":"bx2-22","n":"BX2-22","p":6,"a":"p6","id":"se1","src":"assets/audio/BX2-22/se1.mp3","sec":12.432,"t":"考点六，自然选择决定生物进化的方向。以桦尺蛾为例：工业污染前，树干浅色，浅色蛾不易被鸟发现，s 基因频率高。"},{"ep":"bx2-22","n":"BX2-22","p":6,"a":"p6","id":"se2","src":"assets/audio/BX2-22/se2.mp3","sec":9.816,"t":"工业污染后，树干被熏黑，黑色蛾不易被发现，存活和繁殖的机会多，黑色基因 S 的频率逐代升高。"},{"ep":"bx2-22","n":"BX2-22","p":6,"a":"p6","id":"se3","src":"assets/audio/BX2-22/se3.mp3","sec":6.888,"t":"自然选择使种群的基因频率发生定向改变，生物朝着一定的方向进化。"},{"ep":"bx2-22","n":"BX2-22","p":6,"a":"p6","id":"se4","src":"assets/audio/BX2-22/se4.mp3","sec":9.912,"t":"考法：生物进化的实质是种群基因频率的改变，而不是基因型频率；只要基因频率改变，生物就进化了。"},{"ep":"bx2-22","n":"BX2-22","p":7,"a":"p7","id":"ab1","src":"assets/audio/BX2-22/ab1.mp3","sec":12.624,"t":"考点七，探究实验：抗生素对细菌的选择作用。在培养基上涂布细菌，放上含抗生素的纸片，培养后纸片周围出现抑菌圈。"},{"ep":"bx2-22","n":"BX2-22","p":7,"a":"p7","id":"ab2","src":"assets/audio/BX2-22/ab2.mp3","sec":5.424,"t":"从抑菌圈边缘的菌落挑取细菌，继续培养，重复几代。"},{"ep":"bx2-22","n":"BX2-22","p":7,"a":"p7","id":"ab3","src":"assets/audio/BX2-22/ab3.mp3","sec":6.0,"t":"结果：抑菌圈直径逐代变小，说明细菌的耐药性越来越强。"},{"ep":"bx2-22","n":"BX2-22","p":7,"a":"p7","id":"ab4","src":"assets/audio/BX2-22/ab4.mp3","sec":10.872,"t":"易错：耐药性变异在使用抗生素之前就存在，抗生素只起选择作用；从边缘挑菌，是因为那里的细菌可能耐药。"},{"ep":"bx2-22","n":"BX2-22","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-22/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-22","n":"BX2-22","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-22/rv2.mp3","sec":6.84,"t":"判断一？错，进化的基本单位是种群。判断二？对。"},{"ep":"bx2-22","n":"BX2-22","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-22/rv3.mp3","sec":10.368,"t":"判断三？错，Aa = 2pq = 0.32。判断四？错，实质是基因频率的改变。"},{"ep":"bx2-22","n":"BX2-22","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-22/rv4.mp3","sec":8.472,"t":"判断五？对。判断六？错，耐药突变本来就有，抗生素只起选择作用。"},{"ep":"bx2-22","n":"BX2-22","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-22/rv5.mp3","sec":7.2,"t":"七个考点串成一条线：进化的实质是基因频率的改变。我们下期再见！"},{"ep":"bx2-23","n":"BX2-23","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-23/in1.mp3","sec":8.256,"t":"同学们好！这节课梳理人教版必修二第六章第三节的下半部分——隔离与物种的形成。"},{"ep":"bx2-23","n":"BX2-23","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-23/in2.mp3","sec":7.968,"t":"高考常考物种的判断、两种隔离、物种形成的过程，以及进化与新物种形成的区别。"},{"ep":"bx2-23","n":"BX2-23","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-23/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-23","n":"BX2-23","p":1,"a":"p1","id":"sp1","src":"assets/audio/BX2-23/sp1.mp3","sec":7.344,"t":"考点一，物种：能够在自然状态下相互交配并且产生可育后代的一群生物。"},{"ep":"bx2-23","n":"BX2-23","p":1,"a":"p1","id":"sp2","src":"assets/audio/BX2-23/sp2.mp3","sec":6.816,"t":"例：马和驴能交配，产生骡，但骡不育，所以马和驴是两个物种。"},{"ep":"bx2-23","n":"BX2-23","p":1,"a":"p1","id":"sp3","src":"assets/audio/BX2-23/sp3.mp3","sec":8.496,"t":"解题方法：判断是否同一物种，看两点——能否自然交配，后代是否可育，缺一不可。"},{"ep":"bx2-23","n":"BX2-23","p":2,"a":"p2","id":"is1","src":"assets/audio/BX2-23/is1.mp3","sec":7.464,"t":"考点二，隔离：不同群体间的个体，在自然条件下基因不能自由交流的现象。"},{"ep":"bx2-23","n":"BX2-23","p":2,"a":"p2","id":"is2","src":"assets/audio/BX2-23/is2.mp3","sec":8.424,"t":"地理隔离：同一种生物由于地理障碍，分成不同的种群，使种群间不能发生基因交流。"},{"ep":"bx2-23","n":"BX2-23","p":2,"a":"p2","id":"is3","src":"assets/audio/BX2-23/is3.mp3","sec":8.496,"t":"生殖隔离：不同物种之间一般不能相互交配，即使交配成功，也不能产生可育的后代。"},{"ep":"bx2-23","n":"BX2-23","p":2,"a":"p2","id":"is4","src":"assets/audio/BX2-23/is4.mp3","sec":10.632,"t":"易错：地理隔离的种群如果重新相遇，仍能交配产生可育后代；生殖隔离一旦形成，就不能再交流基因了。"},{"ep":"bx2-23","n":"BX2-23","p":3,"a":"p3","id":"pr1","src":"assets/audio/BX2-23/pr1.mp3","sec":10.656,"t":"考点三，物种形成的一般过程，以加拉帕戈斯群岛的地雀为例。南美洲的地雀迁到各个岛上，形成地理隔离。"},{"ep":"bx2-23","n":"BX2-23","p":3,"a":"p3","id":"pr2","src":"assets/audio/BX2-23/pr2.mp3","sec":6.6,"t":"各岛种群出现不同的突变和基因重组，彼此之间没有基因交流。"},{"ep":"bx2-23","n":"BX2-23","p":3,"a":"p3","id":"pr3","src":"assets/audio/BX2-23/pr3.mp3","sec":7.032,"t":"各岛的食物和环境不同，自然选择使各种群的基因频率向不同方向改变。"},{"ep":"bx2-23","n":"BX2-23","p":3,"a":"p3","id":"pr4","src":"assets/audio/BX2-23/pr4.mp3","sec":8.04,"t":"久而久之，各种群的基因库出现很大差异，最终形成生殖隔离，成为不同的物种。"},{"ep":"bx2-23","n":"BX2-23","p":3,"a":"p3","id":"pr5","src":"assets/audio/BX2-23/pr5.mp3","sec":9.888,"t":"考法：顺序是 地理隔离 → 突变和重组 + 自然选择 → 基因库差异 → 生殖隔离。"},{"ep":"bx2-23","n":"BX2-23","p":4,"a":"p4","id":"ro1","src":"assets/audio/BX2-23/ro1.mp3","sec":5.496,"t":"考点四，隔离的作用。隔离是物种形成的必要条件。"},{"ep":"bx2-23","n":"BX2-23","p":4,"a":"p4","id":"ro2","src":"assets/audio/BX2-23/ro2.mp3","sec":3.384,"t":"生殖隔离是新物种形成的标志。"},{"ep":"bx2-23","n":"BX2-23","p":4,"a":"p4","id":"ro3","src":"assets/audio/BX2-23/ro3.mp3","sec":6.336,"t":"突变和基因重组、自然选择和隔离，是物种形成的三个基本环节。"},{"ep":"bx2-23","n":"BX2-23","p":4,"a":"p4","id":"ro4","src":"assets/audio/BX2-23/ro4.mp3","sec":9.24,"t":"易错：地理隔离不是必要条件，生殖隔离才是；“隔离是必要条件”中的隔离，主要指生殖隔离。"},{"ep":"bx2-23","n":"BX2-23","p":5,"a":"p5","id":"pp1","src":"assets/audio/BX2-23/pp1.mp3","sec":5.52,"t":"考点五，多倍体可以不经过地理隔离，直接形成新物种。"},{"ep":"bx2-23","n":"BX2-23","p":5,"a":"p5","id":"pp2","src":"assets/audio/BX2-23/pp2.mp3","sec":11.016,"t":"例：二倍体西瓜经秋水仙素处理，得到四倍体西瓜。四倍体与二倍体杂交，后代是三倍体，三倍体不育。"},{"ep":"bx2-23","n":"BX2-23","p":5,"a":"p5","id":"pp3","src":"assets/audio/BX2-23/pp3.mp3","sec":7.152,"t":"所以四倍体与二倍体之间存在生殖隔离，四倍体西瓜是一个新物种。"},{"ep":"bx2-23","n":"BX2-23","p":5,"a":"p5","id":"pp4","src":"assets/audio/BX2-23/pp4.mp3","sec":7.08,"t":"考法：这类物种形成速度快，没有经过地理隔离，但同样经过了生殖隔离。"},{"ep":"bx2-23","n":"BX2-23","p":6,"a":"p6","id":"cp1","src":"assets/audio/BX2-23/cp1.mp3","sec":7.68,"t":"考点六，进化与物种形成的辨析。生物进化的标志是种群基因频率的改变。"},{"ep":"bx2-23","n":"BX2-23","p":6,"a":"p6","id":"cp2","src":"assets/audio/BX2-23/cp2.mp3","sec":4.032,"t":"新物种形成的标志是生殖隔离的形成。"},{"ep":"bx2-23","n":"BX2-23","p":6,"a":"p6","id":"cp3","src":"assets/audio/BX2-23/cp3.mp3","sec":12.336,"t":"解题方法：进化不一定形成新物种，但新物种的形成一定发生了进化。比如桦尺蛾的黑色型增多，是进化，但没有形成新物种。"},{"ep":"bx2-23","n":"BX2-23","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-23/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-23","n":"BX2-23","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-23/rv2.mp3","sec":7.656,"t":"判断一？错，骡不育，马和驴存在生殖隔离。判断二？对。"},{"ep":"bx2-23","n":"BX2-23","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-23/rv3.mp3","sec":9.216,"t":"判断三？错，多倍体可以不经地理隔离。判断四？错，进化不一定形成新物种。"},{"ep":"bx2-23","n":"BX2-23","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-23/rv4.mp3","sec":8.016,"t":"判断五？对。判断六？错，二者杂交的三倍体不育，是两个物种。"},{"ep":"bx2-23","n":"BX2-23","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-23/rv5.mp3","sec":7.872,"t":"六个考点串成一条线：生殖隔离是标志，进化不一定成新种。我们下期再见！"},{"ep":"bx2-24","n":"BX2-24","p":0,"a":"intro","id":"in1","src":"assets/audio/BX2-24/in1.mp3","sec":10.728,"t":"同学们好！这节课梳理人教版必修二第六章第四节——协同进化与生物多样性的形成，也是必修二的最后一节。"},{"ep":"bx2-24","n":"BX2-24","p":0,"a":"intro","id":"in2","src":"assets/audio/BX2-24/in2.mp3","sec":7.536,"t":"高考常考协同进化的实例、生物多样性的三个层次和现代生物进化理论的要点。"},{"ep":"bx2-24","n":"BX2-24","p":0,"a":"intro","id":"in3","src":"assets/audio/BX2-24/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"bx2-24","n":"BX2-24","p":1,"a":"p1","id":"co1","src":"assets/audio/BX2-24/co1.mp3","sec":8.856,"t":"考点一，协同进化：不同物种之间、生物与无机环境之间在相互影响中不断进化和发展。"},{"ep":"bx2-24","n":"BX2-24","p":1,"a":"p1","id":"co2","src":"assets/audio/BX2-24/co2.mp3","sec":8.832,"t":"通过漫长的协同进化过程，地球上不仅出现了千姿百态的物种，而且形成了多种多样的生态系统。"},{"ep":"bx2-24","n":"BX2-24","p":1,"a":"p1","id":"co3","src":"assets/audio/BX2-24/co3.mp3","sec":10.08,"t":"易错：协同进化不只发生在生物之间，生物与无机环境之间也有；同种生物之间的斗争不属于协同进化。"},{"ep":"bx2-24","n":"BX2-24","p":2,"a":"p2","id":"ex1","src":"assets/audio/BX2-24/ex1.mp3","sec":13.968,"t":"考点二，协同进化的实例。达尔文发现一种兰花长着细长的花距，他推测一定有口器同样细长的昆虫为它传粉，约 50 年后果然发现了这种蛾。"},{"ep":"bx2-24","n":"BX2-24","p":2,"a":"p2","id":"ex2","src":"assets/audio/BX2-24/ex2.mp3","sec":11.112,"t":"捕食者和猎物：猎豹越跑越快，羚羊也越跑越快。斯坦利的“收割理论”认为，捕食者的存在有利于增加物种多样性。"},{"ep":"bx2-24","n":"BX2-24","p":2,"a":"p2","id":"ex3","src":"assets/audio/BX2-24/ex3.mp3","sec":9.408,"t":"生物与环境：最早的光合生物产生了氧气，使大气中出现氧气，为好氧生物的出现创造了条件。"},{"ep":"bx2-24","n":"BX2-24","p":2,"a":"p2","id":"ex4","src":"assets/audio/BX2-24/ex4.mp3","sec":7.536,"t":"考法：判断实例是否属于协同进化，看是否是两者相互影响、共同变化。"},{"ep":"bx2-24","n":"BX2-24","p":3,"a":"p3","id":"lv1","src":"assets/audio/BX2-24/lv1.mp3","sec":8.04,"t":"考点三，生物多样性的三个层次：遗传多样性、物种多样性、生态系统多样性。"},{"ep":"bx2-24","n":"BX2-24","p":3,"a":"p3","id":"lv2","src":"assets/audio/BX2-24/lv2.mp3","sec":6.6,"t":"遗传多样性也叫基因多样性，是同种生物不同个体之间基因的差异。"},{"ep":"bx2-24","n":"BX2-24","p":3,"a":"p3","id":"lv3","src":"assets/audio/BX2-24/lv3.mp3","sec":9.672,"t":"易错：生物多样性的形成不只是新物种不断形成的过程，还包括遗传多样性和生态系统多样性的形成。"},{"ep":"bx2-24","n":"BX2-24","p":4,"a":"p4","id":"hi1","src":"assets/audio/BX2-24/hi1.mp3","sec":4.944,"t":"考点四，生物多样性的形成是协同进化的结果。"},{"ep":"bx2-24","n":"BX2-24","p":4,"a":"p4","id":"hi2","src":"assets/audio/BX2-24/hi2.mp3","sec":9.864,"t":"进化历程：生物由原核到真核、由单细胞到多细胞、由水生到陆生、由简单到复杂、由低等到高等。"},{"ep":"bx2-24","n":"BX2-24","p":4,"a":"p4","id":"hi3","src":"assets/audio/BX2-24/hi3.mp3","sec":9.984,"t":"两个关键事件：有性生殖的出现，使生物进化速度明显加快；寒武纪大爆发，大量动物在短时间内出现。"},{"ep":"bx2-24","n":"BX2-24","p":4,"a":"p4","id":"hi4","src":"assets/audio/BX2-24/hi4.mp3","sec":8.184,"t":"考法：有性生殖实现了基因重组，增强了生物变异的多样性，所以进化速度加快。"},{"ep":"bx2-24","n":"BX2-24","p":5,"a":"p5","id":"th1","src":"assets/audio/BX2-24/th1.mp3","sec":13.08,"t":"考点五，生物进化理论在发展。中性学说：大量的基因突变是中性的，决定生物进化方向的是中性突变的逐渐积累，而不是自然选择。"},{"ep":"bx2-24","n":"BX2-24","p":5,"a":"p5","id":"th2","src":"assets/audio/BX2-24/th2.mp3","sec":9.504,"t":"间断平衡学说：物种形成并不都是渐变的过程，而是物种长期稳定与迅速形成新种交替出现的过程。"},{"ep":"bx2-24","n":"BX2-24","p":5,"a":"p5","id":"th3","src":"assets/audio/BX2-24/th3.mp3","sec":12.168,"t":"考法：这些观点仍有争论，更多学者认为不能否认自然选择的作用；以自然选择学说为核心的进化理论，仍是各方面研究的基础。"},{"ep":"bx2-24","n":"BX2-24","p":6,"a":"p6","id":"mo1","src":"assets/audio/BX2-24/mo1.mp3","sec":9.552,"t":"考点六，现代生物进化理论的主要内容。适应是自然选择的结果；种群是生物进化的基本单位。"},{"ep":"bx2-24","n":"BX2-24","p":6,"a":"p6","id":"mo2","src":"assets/audio/BX2-24/mo2.mp3","sec":10.224,"t":"突变和基因重组提供进化的原材料，自然选择导致种群基因频率的定向改变，进而通过隔离形成新的物种。"},{"ep":"bx2-24","n":"BX2-24","p":6,"a":"p6","id":"mo3","src":"assets/audio/BX2-24/mo3.mp3","sec":9.168,"t":"生物进化的过程，实际上是生物与生物、生物与无机环境协同进化的过程；进化导致生物多样性。"},{"ep":"bx2-24","n":"BX2-24","p":6,"a":"p6","id":"mo4","src":"assets/audio/BX2-24/mo4.mp3","sec":10.488,"t":"解题方法：答进化题，抓住一条主线——突变重组 → 自然选择 → 基因频率改变 → 隔离 → 新物种。"},{"ep":"bx2-24","n":"BX2-24","p":"review","a":"review","id":"rv1","src":"assets/audio/BX2-24/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"bx2-24","n":"BX2-24","p":"review","a":"review","id":"rv2","src":"assets/audio/BX2-24/rv2.mp3","sec":7.8,"t":"判断一？错，生物与无机环境之间也有协同进化。判断二？对。"},{"ep":"bx2-24","n":"BX2-24","p":"review","a":"review","id":"rv3","src":"assets/audio/BX2-24/rv3.mp3","sec":4.656,"t":"判断三？对。判断四？对。"},{"ep":"bx2-24","n":"BX2-24","p":"review","a":"review","id":"rv4","src":"assets/audio/BX2-24/rv4.mp3","sec":9.816,"t":"判断五？错，中性学说认为决定进化方向的是中性突变的逐渐积累。判断六？对。"},{"ep":"bx2-24","n":"BX2-24","p":"review","a":"review","id":"rv5","src":"assets/audio/BX2-24/rv5.mp3","sec":10.2,"t":"六个考点串成一条线：相互影响、共同进化，形成多样性。必修二到这里就全部梳理完了，我们下次再见！"},{"ep":"xb1-01","n":"XB1-01","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-01/in1.mp3","sec":7.728,"t":"同学们好！这节课梳理人教版选择性必修一第一章第一节——细胞生活的环境。"},{"ep":"xb1-01","n":"XB1-01","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-01/in2.mp3","sec":9.576,"t":"这一节是整本书的基础，高考常考内环境成分的判断、三种细胞外液的关系，以及组织水肿的分析。"},{"ep":"xb1-01","n":"XB1-01","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-01/in3.mp3","sec":5.544,"t":"我们按十个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-01","n":"XB1-01","p":1,"a":"p1","id":"fl1","src":"assets/audio/XB1-01/fl1.mp3","sec":2.616,"t":"考点一，体液的组成。"},{"ep":"xb1-01","n":"XB1-01","p":1,"a":"p1","id":"fl2","src":"assets/audio/XB1-01/fl2.mp3","sec":4.968,"t":"人体内含有大量以水为基础的液体，统称为体液。"},{"ep":"xb1-01","n":"XB1-01","p":1,"a":"p1","id":"fl3","src":"assets/audio/XB1-01/fl3.mp3","sec":9.984,"t":"体液分为两部分：存在于细胞内的细胞内液，约占三分之二；存在于细胞外的细胞外液，约占三分之一。"},{"ep":"xb1-01","n":"XB1-01","p":1,"a":"p1","id":"fl4","src":"assets/audio/XB1-01/fl4.mp3","sec":4.608,"t":"细胞外液主要包括血浆、组织液和淋巴液。"},{"ep":"xb1-01","n":"XB1-01","p":1,"a":"p1","id":"fl5","src":"assets/audio/XB1-01/fl5.mp3","sec":14.184,"t":"易错：消化液、泪液、汗液、尿液都不属于体液。它们存在于消化道、泪道、汗腺导管、膀胱等与外界相通的管腔中，相当于“体外”的液体。"},{"ep":"xb1-01","n":"XB1-01","p":2,"a":"p2","id":"re1","src":"assets/audio/XB1-01/re1.mp3","sec":5.088,"t":"考点二，内环境的概念，以及三种细胞外液的关系。"},{"ep":"xb1-01","n":"XB1-01","p":2,"a":"p2","id":"re2","src":"assets/audio/XB1-01/re2.mp3","sec":8.952,"t":"由细胞外液构成的液体环境叫作内环境。注意，内环境就是细胞外液，不包括细胞内液。"},{"ep":"xb1-01","n":"XB1-01","p":2,"a":"p2","id":"re3","src":"assets/audio/XB1-01/re3.mp3","sec":10.704,"t":"血浆和组织液之间可以相互渗透：血浆透过毛细血管壁进入组织间隙形成组织液，大部分组织液又渗回血浆。"},{"ep":"xb1-01","n":"XB1-01","p":2,"a":"p2","id":"re4","src":"assets/audio/XB1-01/re4.mp3","sec":10.368,"t":"少部分组织液进入毛细淋巴管，形成淋巴液；淋巴液经淋巴循环，最终汇入血浆。这两步都是单向的。"},{"ep":"xb1-01","n":"XB1-01","p":2,"a":"p2","id":"re5","src":"assets/audio/XB1-01/re5.mp3","sec":4.872,"t":"组织液和细胞内液之间，也在不断进行物质交换。"},{"ep":"xb1-01","n":"XB1-01","p":2,"a":"p2","id":"re6","src":"assets/audio/XB1-01/re6.mp3","sec":16.296,"t":"考法：给出四种体液的箭头关系图，判断名称。先找淋巴液：它只有一个箭头进、一个箭头出，箭头从组织液来，指向血浆；和组织液双向交换的另一个，就是细胞内液。"},{"ep":"xb1-01","n":"XB1-01","p":3,"a":"p3","id":"ce1","src":"assets/audio/XB1-01/ce1.mp3","sec":3.912,"t":"考点三，不同细胞生活的具体内环境。"},{"ep":"xb1-01","n":"XB1-01","p":3,"a":"p3","id":"ce2","src":"assets/audio/XB1-01/ce2.mp3","sec":7.056,"t":"体内绝大多数细胞是组织细胞，生活在组织液中；血细胞生活在血浆中。"},{"ep":"xb1-01","n":"XB1-01","p":3,"a":"p3","id":"ce3","src":"assets/audio/XB1-01/ce3.mp3","sec":5.904,"t":"淋巴细胞主要生活在淋巴液中，也会随淋巴循环进入血浆。"},{"ep":"xb1-01","n":"XB1-01","p":3,"a":"p3","id":"ce4","src":"assets/audio/XB1-01/ce4.mp3","sec":11.88,"t":"最容易错的是两种管壁细胞：毛细血管壁细胞一侧是血浆、一侧是组织液；毛细淋巴管壁细胞一侧是淋巴液、一侧是组织液。"},{"ep":"xb1-01","n":"XB1-01","p":3,"a":"p3","id":"ce5","src":"assets/audio/XB1-01/ce5.mp3","sec":7.416,"t":"考法：问某种细胞的内环境，先看它在哪里；管壁细胞要把两侧都写全。"},{"ep":"xb1-01","n":"XB1-01","p":4,"a":"p4","id":"co1","src":"assets/audio/XB1-01/co1.mp3","sec":5.496,"t":"考点四，内环境成分的判断，这是选择题的高频考点。"},{"ep":"xb1-01","n":"XB1-01","p":4,"a":"p4","id":"co2","src":"assets/audio/XB1-01/co2.mp3","sec":11.832,"t":"血浆中的水、无机盐、葡萄糖、氨基酸、血浆蛋白，以及激素、抗体、尿素、O2和CO2，都属于内环境的成分。"},{"ep":"xb1-01","n":"XB1-01","p":4,"a":"p4","id":"co3","src":"assets/audio/XB1-01/co3.mp3","sec":12.024,"t":"而血红蛋白在红细胞内，呼吸酶在细胞内，载体蛋白和受体在细胞膜上，消化液在与外界相通的管腔中，它们都不属于内环境。"},{"ep":"xb1-01","n":"XB1-01","p":4,"a":"p4","id":"co4","src":"assets/audio/XB1-01/co4.mp3","sec":12.36,"t":"解题方法：一看是不是在细胞内，二看是不是在细胞膜上，三看是不是在与外界相通的管腔里。三条都排除了，才属于内环境。"},{"ep":"xb1-01","n":"XB1-01","p":4,"a":"p4","id":"co5","src":"assets/audio/XB1-01/co5.mp3","sec":14.712,"t":"同理，抗原与抗体结合、乳酸与NaHCO3反应，发生在内环境中；而细胞呼吸、蛋白质合成发生在细胞内，食物消化发生在消化道，都不在内环境中。"},{"ep":"xb1-01","n":"XB1-01","p":5,"a":"p5","id":"pl1","src":"assets/audio/XB1-01/pl1.mp3","sec":5.4,"t":"考点五，血浆、组织液和淋巴液在成分上的差异。"},{"ep":"xb1-01","n":"XB1-01","p":5,"a":"p5","id":"pl2","src":"assets/audio/XB1-01/pl2.mp3","sec":13.68,"t":"血浆中约90%是水，蛋白质约占7%～9%，无机盐约占1%，此外还有血液运送的营养物质、代谢废物、气体和激素等。"},{"ep":"xb1-01","n":"XB1-01","p":5,"a":"p5","id":"pl3","src":"assets/audio/XB1-01/pl3.mp3","sec":11.496,"t":"组织液和淋巴液的成分与血浆相近，最主要的差别在于：血浆中含有较多的蛋白质，而组织液和淋巴液中蛋白质很少。"},{"ep":"xb1-01","n":"XB1-01","p":5,"a":"p5","id":"pl4","src":"assets/audio/XB1-01/pl4.mp3","sec":6.72,"t":"考法：给出几种液体的成分表，蛋白质含量明显较高的，就是血浆。"},{"ep":"xb1-01","n":"XB1-01","p":6,"a":"p6","id":"ph1","src":"assets/audio/XB1-01/ph1.mp3","sec":6.288,"t":"考点六到八，内环境的三个理化性质：渗透压、酸碱度和温度。"},{"ep":"xb1-01","n":"XB1-01","p":6,"a":"p6","id":"ph2","src":"assets/audio/XB1-01/ph2.mp3","sec":8.688,"t":"渗透压是指溶液中溶质微粒对水的吸引力，大小取决于单位体积溶液中溶质微粒的数目。"},{"ep":"xb1-01","n":"XB1-01","p":6,"a":"p6","id":"ph3","src":"assets/audio/XB1-01/ph3.mp3","sec":10.584,"t":"血浆渗透压的大小主要与无机盐和蛋白质的含量有关；细胞外液渗透压的90%以上来源于Na+和Cl-。"},{"ep":"xb1-01","n":"XB1-01","p":6,"a":"p6","id":"ph6","src":"assets/audio/XB1-01/ph6.mp3","sec":11.304,"t":"考法：输液为什么用0.9%的NaCl溶液？因为它和血浆渗透压相等，是等渗溶液，能维持细胞的正常形态。"},{"ep":"xb1-01","n":"XB1-01","p":7,"a":"p7","id":"ph4","src":"assets/audio/XB1-01/ph4.mp3","sec":9.72,"t":"正常人血浆的pH为7.35～7.45，能保持稳定，与其中的HCO3-、H2CO3等物质有关。"},{"ep":"xb1-01","n":"XB1-01","p":7,"a":"p7","id":"ph7","src":"assets/audio/XB1-01/ph7.mp3","sec":16.248,"t":"再比如，剧烈运动产生的乳酸进入血浆，会与NaHCO3反应，生成乳酸钠和H2CO3，H2CO3再分解成CO2和水，CO2通过呼吸排出，所以血浆pH不会明显下降。"},{"ep":"xb1-01","n":"XB1-01","p":8,"a":"p8","id":"ph5","src":"assets/audio/XB1-01/ph5.mp3","sec":4.8,"t":"人体细胞外液的温度一般维持在37 ℃左右。"},{"ep":"xb1-01","n":"XB1-01","p":9,"a":"p9","id":"ex1","src":"assets/audio/XB1-01/ex1.mp3","sec":5.928,"t":"考点九，内环境是细胞与外界环境进行物质交换的媒介。"},{"ep":"xb1-01","n":"XB1-01","p":9,"a":"p9","id":"ex2","src":"assets/audio/XB1-01/ex2.mp3","sec":9.792,"t":"营养物质经消化系统吸收进入内环境；O2经呼吸系统进入内环境，CO2也经呼吸系统排出。"},{"ep":"xb1-01","n":"XB1-01","p":9,"a":"p9","id":"ex3","src":"assets/audio/XB1-01/ex3.mp3","sec":11.568,"t":"细胞产生的尿素等代谢废物，主要经泌尿系统排出，少部分经皮肤排出。这些物质在体内的运输，都要依靠循环系统。"},{"ep":"xb1-01","n":"XB1-01","p":9,"a":"p9","id":"ex4","src":"assets/audio/XB1-01/ex4.mp3","sec":6.144,"t":"同时，细胞不仅依赖于内环境，也参与了内环境的形成和维持。"},{"ep":"xb1-01","n":"XB1-01","p":9,"a":"p9","id":"ex5","src":"assets/audio/XB1-01/ex5.mp3","sec":19.584,"t":"考法：O2从外界进入组织细胞并被利用，至少穿过几层生物膜？肺泡壁两层，进出毛细血管壁两层，进出红细胞两层，再出毛细血管壁两层，进入组织细胞一层，进入线粒体两层，一共11层。"},{"ep":"xb1-01","n":"XB1-01","p":10,"a":"p10","id":"ed1","src":"assets/audio/XB1-01/ed1.mp3","sec":3.384,"t":"考点十，组织水肿的成因分析。"},{"ep":"xb1-01","n":"XB1-01","p":10,"a":"p10","id":"ed2","src":"assets/audio/XB1-01/ed2.mp3","sec":12.192,"t":"组织水肿是组织液过多引起的。所有原因都可以归结为：血浆渗透压降低，或组织液渗透压升高，水分从血浆流向组织液。"},{"ep":"xb1-01","n":"XB1-01","p":10,"a":"p10","id":"ed3","src":"assets/audio/XB1-01/ed3.mp3","sec":10.296,"t":"长期营养不良，血浆蛋白减少；肾小球肾炎，蛋白质随尿液流失。这两种都使血浆渗透压降低。"},{"ep":"xb1-01","n":"XB1-01","p":10,"a":"p10","id":"ed4","src":"assets/audio/XB1-01/ed4.mp3","sec":13.728,"t":"过敏反应使毛细血管壁通透性增大，血浆蛋白进入组织液；淋巴循环受阻，组织液中的蛋白质不能回流。这两种都使组织液渗透压升高。"},{"ep":"xb1-01","n":"XB1-01","p":10,"a":"p10","id":"ed5","src":"assets/audio/XB1-01/ed5.mp3","sec":6.216,"t":"局部组织代谢旺盛，代谢产物增多，组织液渗透压也会升高。"},{"ep":"xb1-01","n":"XB1-01","p":10,"a":"p10","id":"ed6","src":"assets/audio/XB1-01/ed6.mp3","sec":9.84,"t":"解题方法：遇到水肿题，先判断是血浆渗透压降低，还是组织液渗透压升高，再把原因对号入座。"},{"ep":"xb1-01","n":"XB1-01","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-01/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-01","n":"XB1-01","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-01/rv2.mp3","sec":13.176,"t":"血浆、组织液、淋巴液都能相互转化？错，淋巴液只能单向流回血浆。血红蛋白属于内环境的成分？错，它在红细胞内。"},{"ep":"xb1-01","n":"XB1-01","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-01/rv3.mp3","sec":12.816,"t":"毛细淋巴管壁细胞的内环境是淋巴液和组织液？对。血浆渗透压主要来自蛋白质？错，主要与无机盐和蛋白质的含量有关。"},{"ep":"xb1-01","n":"XB1-01","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-01/rv4.mp3","sec":13.128,"t":"剧烈运动后血浆pH明显下降？错，缓冲物质使pH保持稳定。食物的消化发生在内环境中？错，消化道与外界相通。"},{"ep":"xb1-01","n":"XB1-01","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-01/rv5.mp3","sec":14.808,"t":"十个考点归结为一句话：细胞外液构成内环境，内环境是细胞与外界环境进行物质交换的媒介。掌握这条主线，这一节就能稳稳拿分！我们下期再见！"},{"ep":"xb1-02","n":"XB1-02","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-02/in1.mp3","sec":7.44,"t":"同学们好！这节课梳理人教版选择性必修一第一章第二节——内环境的稳态。"},{"ep":"xb1-02","n":"XB1-02","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-02/in2.mp3","sec":8.88,"t":"这一节高考常考模拟生物体维持pH稳定的实验、稳态的调节机制，以及稳态失调的实例分析。"},{"ep":"xb1-02","n":"XB1-02","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-02/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-02","n":"XB1-02","p":1,"a":"p1","id":"ep1","src":"assets/audio/XB1-02/ep1.mp3","sec":4.896,"t":"考点一，实验：模拟生物体维持pH的稳定。"},{"ep":"xb1-02","n":"XB1-02","p":1,"a":"p1","id":"ep2","src":"assets/audio/XB1-02/ep2.mp3","sec":16.44,"t":"实验分三组：自来水、缓冲液和生物材料，比如肝匀浆。每组取25 mL，先测起始pH，再逐滴加入0.1 mol/L的HCl，每加5滴测一次pH，一共加30滴。"},{"ep":"xb1-02","n":"XB1-02","p":1,"a":"p1","id":"ep3","src":"assets/audio/XB1-02/ep3.mp3","sec":10.608,"t":"充分冲洗烧杯后，再用0.1 mol/L的NaOH重复实验。以滴数为横坐标、pH为纵坐标画出曲线。"},{"ep":"xb1-02","n":"XB1-02","p":1,"a":"p1","id":"ep4","src":"assets/audio/XB1-02/ep4.mp3","sec":6.84,"t":"结果：自来水的pH变化明显；缓冲液和肝匀浆的pH变化很小。"},{"ep":"xb1-02","n":"XB1-02","p":1,"a":"p1","id":"ep5","src":"assets/audio/XB1-02/ep5.mp3","sec":10.824,"t":"结论：生物材料的性质类似于缓冲液而不同于自来水，说明生物材料内含有缓冲物质，能维持pH的相对稳定。"},{"ep":"xb1-02","n":"XB1-02","p":1,"a":"p1","id":"ep6","src":"assets/audio/XB1-02/ep6.mp3","sec":12.504,"t":"考法：自变量是材料的种类和滴加酸碱的量，因变量是pH的变化。自来水组和缓冲液组都是对照组，生物材料组是实验组。"},{"ep":"xb1-02","n":"XB1-02","p":2,"a":"p2","id":"cn1","src":"assets/audio/XB1-02/cn1.mp3","sec":2.664,"t":"考点二，稳态的概念。"},{"ep":"xb1-02","n":"XB1-02","p":2,"a":"p2","id":"cn2","src":"assets/audio/XB1-02/cn2.mp3","sec":7.704,"t":"十九世纪，法国生理学家贝尔纳推测，内环境的恒定主要依赖神经系统的调节。"},{"ep":"xb1-02","n":"XB1-02","p":2,"a":"p2","id":"cn3","src":"assets/audio/XB1-02/cn3.mp3","sec":14.832,"t":"后来，美国生理学家坎农提出了稳态的概念：内环境稳态是在神经调节和体液调节的共同作用下，通过机体各种器官、系统分工合作、协调统一而实现的。"},{"ep":"xb1-02","n":"XB1-02","p":2,"a":"p2","id":"cn4","src":"assets/audio/XB1-02/cn4.mp3","sec":11.256,"t":"现在把它表述为：正常机体通过调节作用，使各个器官、系统协调活动，共同维持内环境的相对稳定状态，叫作稳态。"},{"ep":"xb1-02","n":"XB1-02","p":2,"a":"p2","id":"cn5","src":"assets/audio/XB1-02/cn5.mp3","sec":9.912,"t":"易错：稳态不是恒定不变，而是一种动态平衡。内环境的化学成分和理化性质都在一定范围内波动。"},{"ep":"xb1-02","n":"XB1-02","p":3,"a":"p3","id":"mc1","src":"assets/audio/XB1-02/mc1.mp3","sec":3.024,"t":"考点三，稳态的调节机制。"},{"ep":"xb1-02","n":"XB1-02","p":3,"a":"p3","id":"mc2","src":"assets/audio/XB1-02/mc2.mp3","sec":9.912,"t":"直接参与维持内环境稳态的，有消化、呼吸、循环、泌尿四大系统，而它们的协调活动离不开调节。"},{"ep":"xb1-02","n":"XB1-02","p":3,"a":"p3","id":"mc3","src":"assets/audio/XB1-02/mc3.mp3","sec":6.864,"t":"目前普遍认为，神经—体液—免疫调节网络是机体维持稳态的主要调节机制。"},{"ep":"xb1-02","n":"XB1-02","p":4,"a":"p4","id":"mc4","src":"assets/audio/XB1-02/mc4.mp3","sec":14.016,"t":"考点四，人体维持稳态的调节能力是有一定限度的。当外界环境的变化过于剧烈，或者人体自身的调节功能出现障碍时，内环境稳态就会遭到破坏。"},{"ep":"xb1-02","n":"XB1-02","p":4,"a":"p4","id":"mc5","src":"assets/audio/XB1-02/mc5.mp3","sec":10.392,"t":"比如，到高海拔地区，有人会出现头痛、乏力、心跳加快等高原反应，就是外界环境的变化超出了调节能力。"},{"ep":"xb1-02","n":"XB1-02","p":4,"a":"p4","id":"mc6","src":"assets/audio/XB1-02/mc6.mp3","sec":6.312,"t":"考法：题目说“稳态能一直维持”或“调节能力是无限的”，都是错的。"},{"ep":"xb1-02","n":"XB1-02","p":5,"a":"p5","id":"ds1","src":"assets/audio/XB1-02/ds1.mp3","sec":3.72,"t":"考点五，内环境稳态失调与疾病。"},{"ep":"xb1-02","n":"XB1-02","p":5,"a":"p5","id":"ds2","src":"assets/audio/XB1-02/ds2.mp3","sec":10.104,"t":"先看成分失调：血糖浓度过低，会出现低血糖症状；尿素等代谢废物不能及时排出，会引起尿毒症。"},{"ep":"xb1-02","n":"XB1-02","p":5,"a":"p5","id":"ds3","src":"assets/audio/XB1-02/ds3.mp3","sec":14.112,"t":"再看理化性质失调：pH失调，引起酸中毒或碱中毒；体温失调，出现发烧或中暑；渗透压失调，细胞会吸水或失水，形态和功能出现异常。"},{"ep":"xb1-02","n":"XB1-02","p":5,"a":"p5","id":"ds4","src":"assets/audio/XB1-02/ds4.mp3","sec":7.704,"t":"还有一个常考点：血液中Ca2+含量过低会引起抽搐，过高则会引起肌无力。"},{"ep":"xb1-02","n":"XB1-02","p":5,"a":"p5","id":"ds5","src":"assets/audio/XB1-02/ds5.mp3","sec":6.336,"t":"考法：给出一种病症，判断是哪种成分或哪种理化性质失调。"},{"ep":"xb1-02","n":"XB1-02","p":6,"a":"p6","id":"mn1","src":"assets/audio/XB1-02/mn1.mp3","sec":7.344,"t":"考点六，稳态的意义：内环境稳态是机体进行正常生命活动的必要条件。"},{"ep":"xb1-02","n":"XB1-02","p":6,"a":"p6","id":"mn2","src":"assets/audio/XB1-02/mn2.mp3","sec":12.024,"t":"比如，细胞代谢离不开酶，酶的活性需要适宜的温度和pH；细胞呼吸需要血糖和O2的稳定供应，才能为生命活动提供能量。"},{"ep":"xb1-02","n":"XB1-02","p":7,"a":"p7","id":"mn3","src":"assets/audio/XB1-02/mn3.mp3","sec":10.368,"t":"考点七，稳态概念的发展。稳态已经成为生命科学的一大基本概念，在生命系统的各个层次都普遍存在。"},{"ep":"xb1-02","n":"XB1-02","p":7,"a":"p7","id":"mn4","src":"assets/audio/XB1-02/mn4.mp3","sec":6.216,"t":"分子水平：基因表达的稳态、激素分泌的稳态、酶活性的稳态。"},{"ep":"xb1-02","n":"XB1-02","p":7,"a":"p7","id":"mn5","src":"assets/audio/XB1-02/mn5.mp3","sec":11.424,"t":"细胞水平：细胞分裂和分化的稳态。器官水平：心脏活动的稳态，比如血压和心率；还有消化腺分泌消化液的稳态。"},{"ep":"xb1-02","n":"XB1-02","p":7,"a":"p7","id":"mn6","src":"assets/audio/XB1-02/mn6.mp3","sec":6.432,"t":"{群体水平|brown}：种群数量变化的稳态，生态系统结构和功能的稳态。"},{"ep":"xb1-02","n":"XB1-02","p":7,"a":"p7","id":"mn7","src":"assets/audio/XB1-02/mn7.mp3","sec":5.568,"t":"考法：“稳态只存在于人体内环境中”，这种说法是错的。"},{"ep":"xb1-02","n":"XB1-02","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-02/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-02","n":"XB1-02","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-02/rv2.mp3","sec":13.152,"t":"内环境稳态是指成分和理化性质恒定不变？错，它们处于动态平衡之中。神经—体液—免疫调节网络是稳态的主要调节机制？对。"},{"ep":"xb1-02","n":"XB1-02","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-02/rv3.mp3","sec":9.888,"t":"内环境稳态时，人一定不会患病？错，比如遗传病。模拟实验中，自来水组是对照组？对。"},{"ep":"xb1-02","n":"XB1-02","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-02/rv4.mp3","sec":12.528,"t":"人体维持稳态的调节能力是无限的？错，它有一定限度。稳态只存在于人体内环境中？错，各个生命层次都存在稳态。"},{"ep":"xb1-02","n":"XB1-02","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-02/rv5.mp3","sec":14.808,"t":"七个考点串成一条线：用实验认识稳态，理解稳态的概念、机制和限度，再看失调、意义和发展。掌握这些，这一节就能稳稳拿分！我们下期再见！"},{"ep":"xb1-03","n":"XB1-03","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-03/in1.mp3","sec":8.208,"t":"同学们好！这节课梳理人教版选择性必修一第二章第一节——神经调节的结构基础。"},{"ep":"xb1-03","n":"XB1-03","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-03/in2.mp3","sec":7.104,"t":"这一节高考常考脑的结构与功能定位、自主神经系统，以及神经元的结构。"},{"ep":"xb1-03","n":"XB1-03","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-03/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-03","n":"XB1-03","p":1,"a":"p1","id":"cs1","src":"assets/audio/XB1-03/cs1.mp3","sec":8.808,"t":"考点一，中枢神经系统，包括脑和脊髓。脑又包括大脑、小脑、脑干和下丘脑等。"},{"ep":"xb1-03","n":"XB1-03","p":1,"a":"p1","id":"cs2","src":"assets/audio/XB1-03/cs2.mp3","sec":5.424,"t":"大脑表面是大脑皮层，是调节机体活动的最高级中枢。"},{"ep":"xb1-03","n":"XB1-03","p":1,"a":"p1","id":"cs3","src":"assets/audio/XB1-03/cs3.mp3","sec":5.616,"t":"小脑位于大脑的后下方，能够协调运动、维持身体平衡。"},{"ep":"xb1-03","n":"XB1-03","p":1,"a":"p1","id":"cs4","src":"assets/audio/XB1-03/cs4.mp3","sec":9.648,"t":"脑干连接脊髓和脑的其他部分，有许多维持生命的必要中枢，比如调节呼吸和心脏功能的基本活动中枢。"},{"ep":"xb1-03","n":"XB1-03","p":1,"a":"p1","id":"cs5","src":"assets/audio/XB1-03/cs5.mp3","sec":7.128,"t":"{下丘脑|brown}有{体温调节中枢|brown}和{水平衡调节中枢|brown}，还与生物节律的控制有关。"},{"ep":"xb1-03","n":"XB1-03","p":1,"a":"p1","id":"cs6","src":"assets/audio/XB1-03/cs6.mp3","sec":6.312,"t":"脊髓是脑与躯干、内脏之间的联系通路，是调节运动的低级中枢。"},{"ep":"xb1-03","n":"XB1-03","p":1,"a":"p1","id":"cs7","src":"assets/audio/XB1-03/cs7.mp3","sec":12.48,"t":"考法：根据症状定位。喝醉后走路不稳，是小脑受影响；呼吸、心跳停止，是脑干受损；体温、水盐失衡，看{下丘脑|brown}。"},{"ep":"xb1-03","n":"XB1-03","p":2,"a":"p2","id":"ps1","src":"assets/audio/XB1-03/ps1.mp3","sec":2.952,"t":"考点二，外周神经系统。"},{"ep":"xb1-03","n":"XB1-03","p":2,"a":"p2","id":"ps2","src":"assets/audio/XB1-03/ps2.mp3","sec":14.016,"t":"按解剖位置，外周神经系统包括与脑相连的脑神经，共12对，主要分布在头面部；以及与脊髓相连的脊神经，共31对，主要分布在躯干和四肢。"},{"ep":"xb1-03","n":"XB1-03","p":2,"a":"p2","id":"ps3","src":"assets/audio/XB1-03/ps3.mp3","sec":5.304,"t":"注意，脑神经和脊神经中，都有支配内脏器官的神经。"},{"ep":"xb1-03","n":"XB1-03","p":2,"a":"p2","id":"ps4","src":"assets/audio/XB1-03/ps4.mp3","sec":8.16,"t":"按功能，外周神经分为传入神经，也叫感觉神经；以及传出神经，也叫运动神经。"},{"ep":"xb1-03","n":"XB1-03","p":2,"a":"p2","id":"ps5","src":"assets/audio/XB1-03/ps5.mp3","sec":8.856,"t":"传出神经又分为支配躯体运动的躯体运动神经，和支配内脏、血管、腺体的内脏运动神经。"},{"ep":"xb1-03","n":"XB1-03","p":2,"a":"p2","id":"ps6","src":"assets/audio/XB1-03/ps6.mp3","sec":6.888,"t":"易错：脑神经和脊神经都属于外周神经系统，不属于中枢神经系统。"},{"ep":"xb1-03","n":"XB1-03","p":3,"a":"p3","id":"au1","src":"assets/audio/XB1-03/au1.mp3","sec":10.968,"t":"考点三，自主神经系统。支配内脏、血管和腺体的传出神经，它们的活动不受意识支配，称为自主神经系统。"},{"ep":"xb1-03","n":"XB1-03","p":3,"a":"p3","id":"au2","src":"assets/audio/XB1-03/au2.mp3","sec":4.152,"t":"它由交感神经和副交感神经两部分组成。"},{"ep":"xb1-03","n":"XB1-03","p":3,"a":"p3","id":"au3","src":"assets/audio/XB1-03/au3.mp3","sec":11.304,"t":"易错：自主神经系统只包括传出神经，不包括传入神经；它的活动不受意识支配，所以我们无法随意让心跳变慢。"},{"ep":"xb1-03","n":"XB1-03","p":4,"a":"p4","id":"du1","src":"assets/audio/XB1-03/du1.mp3","sec":6.84,"t":"考点四，交感神经和副交感神经对同一器官的作用，通常是相反的。"},{"ep":"xb1-03","n":"XB1-03","p":4,"a":"p4","id":"du2","src":"assets/audio/XB1-03/du2.mp3","sec":13.44,"t":"交感神经使瞳孔扩张、心跳加快、支气管扩张，胃肠蠕动减弱；副交感神经则使瞳孔收缩、心跳减慢、支气管收缩，胃肠蠕动加强。"},{"ep":"xb1-03","n":"XB1-03","p":4,"a":"p4","id":"du3","src":"assets/audio/XB1-03/du3.mp3","sec":11.976,"t":"人处于兴奋状态时，交感神经活动占优势；处于安静状态时，副交感神经活动占优势，有利于食物的消化和营养物质的吸收。"},{"ep":"xb1-03","n":"XB1-03","p":4,"a":"p4","id":"du4","src":"assets/audio/XB1-03/du4.mp3","sec":7.896,"t":"这样的双重支配，可以使机体对外界刺激作出更精确的反应，更好地适应环境的变化。"},{"ep":"xb1-03","n":"XB1-03","p":4,"a":"p4","id":"du5","src":"assets/audio/XB1-03/du5.mp3","sec":12.576,"t":"考法：考试时紧张，心跳加快、食欲下降，是交感神经活动占优势；饭后安静休息，有利于消化，是副交感神经活动占优势。"},{"ep":"xb1-03","n":"XB1-03","p":5,"a":"p5","id":"nr1","src":"assets/audio/XB1-03/nr1.mp3","sec":10.056,"t":"考点五，神经元。神经元是神经系统结构与功能的基本单位，由细胞体、树突和轴突等部分构成。"},{"ep":"xb1-03","n":"XB1-03","p":5,"a":"p5","id":"nr2","src":"assets/audio/XB1-03/nr2.mp3","sec":6.672,"t":"树突通常短而粗，数量多，用来接受信息并将其传导到细胞体。"},{"ep":"xb1-03","n":"XB1-03","p":5,"a":"p5","id":"nr3","src":"assets/audio/XB1-03/nr3.mp3","sec":7.536,"t":"右边是西班牙科学家卡哈尔手绘的小脑浦肯野细胞，可以看到大量分支状的树突。"},{"ep":"xb1-03","n":"XB1-03","p":5,"a":"p5","id":"nr4","src":"assets/audio/XB1-03/nr4.mp3","sec":6.696,"t":"轴突长而较细，将信息从细胞体传向其他神经元、肌肉或腺体。"},{"ep":"xb1-03","n":"XB1-03","p":5,"a":"p5","id":"nr5","src":"assets/audio/XB1-03/nr5.mp3","sec":4.728,"t":"树突和轴突末端的细小分支，叫作神经末梢。"},{"ep":"xb1-03","n":"XB1-03","p":5,"a":"p5","id":"nr6","src":"assets/audio/XB1-03/nr6.mp3","sec":7.32,"t":"考法：信息在一个神经元内的传递方向，一般是树突→细胞体→轴突。"},{"ep":"xb1-03","n":"XB1-03","p":6,"a":"p6","id":"gl1","src":"assets/audio/XB1-03/gl1.mp3","sec":8.232,"t":"考点六，神经胶质细胞。它广泛分布于神经元之间，数量是神经元的10～50倍。"},{"ep":"xb1-03","n":"XB1-03","p":6,"a":"p6","id":"gl2","src":"assets/audio/XB1-03/gl2.mp3","sec":14.232,"t":"神经胶质细胞对神经元起辅助作用，具有支持、保护、营养和修复神经元等多种功能。在外周神经系统中，它还参与构成神经纤维表面的髓鞘。"},{"ep":"xb1-03","n":"XB1-03","p":7,"a":"p7","id":"gl3","src":"assets/audio/XB1-03/gl3.mp3","sec":9.552,"t":"考点七，神经纤维与神经的区别。轴突呈纤维状，外表大都套有一层髓鞘，构成神经纤维。"},{"ep":"xb1-03","n":"XB1-03","p":7,"a":"p7","id":"gl4","src":"assets/audio/XB1-03/gl4.mp3","sec":6.36,"t":"许多神经纤维集结成束，外面包有一层包膜，就构成一条神经。"},{"ep":"xb1-03","n":"XB1-03","p":7,"a":"p7","id":"gl5","src":"assets/audio/XB1-03/gl5.mp3","sec":11.232,"t":"易错：神经元、神经纤维、神经是三个层次。一个神经元一般只有一条轴突，而一条神经里有许多条神经纤维。"},{"ep":"xb1-03","n":"XB1-03","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-03/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-03","n":"XB1-03","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-03/rv2.mp3","sec":13.632,"t":"脑神经和脊神经属于中枢神经系统？错，属于外周神经系统。自主神经系统包括传入神经和传出神经？错，只包括传出神经。"},{"ep":"xb1-03","n":"XB1-03","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-03/rv3.mp3","sec":8.736,"t":"交感神经兴奋使胃肠蠕动加强？错，是减弱。呼吸中枢位于脑干？对。"},{"ep":"xb1-03","n":"XB1-03","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-03/rv4.mp3","sec":11.856,"t":"神经胶质细胞的数量比神经元少？错，是神经元的十到五十倍。神经元是神经系统结构与功能的基本单位？对。"},{"ep":"xb1-03","n":"XB1-03","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-03/rv5.mp3","sec":14.784,"t":"七个考点串起来：先分清中枢和外周，再掌握自主神经的双重支配，最后认识神经元和神经胶质细胞。掌握这些，这一节就能稳稳拿分！我们下期再见！"},{"ep":"xb1-04","n":"XB1-04","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-04/in1.mp3","sec":8.112,"t":"同学们好！这节课梳理人教版选择性必修一第二章第二节——神经调节的基本方式。"},{"ep":"xb1-04","n":"XB1-04","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-04/in2.mp3","sec":8.904,"t":"这一节高考常考反射弧的结构与判断、反射弧受损的分析，以及条件反射与非条件反射。"},{"ep":"xb1-04","n":"XB1-04","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-04/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-04","n":"XB1-04","p":1,"a":"p1","id":"rf1","src":"assets/audio/XB1-04/rf1.mp3","sec":5.856,"t":"考点一，反射的概念。神经调节的基本方式是反射。"},{"ep":"xb1-04","n":"XB1-04","p":1,"a":"p1","id":"rf2","src":"assets/audio/XB1-04/rf2.mp3","sec":7.536,"t":"反射是指在中枢神经系统参与下，机体对内外刺激所产生的规律性应答反应。"},{"ep":"xb1-04","n":"XB1-04","p":1,"a":"p1","id":"rf3","src":"assets/audio/XB1-04/rf3.mp3","sec":7.392,"t":"比如医生用小锤叩击膝盖下方的韧带，小腿会突然弹起，这就是膝跳反射。"},{"ep":"xb1-04","n":"XB1-04","p":1,"a":"p1","id":"rf4","src":"assets/audio/XB1-04/rf4.mp3","sec":6.216,"t":"完成反射需要两个条件：一是完整的反射弧，二是适宜的刺激。"},{"ep":"xb1-04","n":"XB1-04","p":1,"a":"p1","id":"rf5","src":"assets/audio/XB1-04/rf5.mp3","sec":12.576,"t":"易错：草履虫没有神经系统，它对刺激作出的反应不是反射；直接刺激传出神经引起肌肉收缩，没有经过完整的反射弧，也不是反射。"},{"ep":"xb1-04","n":"XB1-04","p":2,"a":"p2","id":"ac1","src":"assets/audio/XB1-04/ac1.mp3","sec":6.84,"t":"考点二，反射弧。反射的结构基础是反射弧，由五个部分组成。"},{"ep":"xb1-04","n":"XB1-04","p":2,"a":"p2","id":"ac2","src":"assets/audio/XB1-04/ac2.mp3","sec":3.336,"t":"感受器接受刺激，产生兴奋；"},{"ep":"xb1-04","n":"XB1-04","p":2,"a":"p2","id":"ac3","src":"assets/audio/XB1-04/ac3.mp3","sec":3.696,"t":"传入神经把兴奋传向神经中枢；"},{"ep":"xb1-04","n":"XB1-04","p":2,"a":"p2","id":"ac4","src":"assets/audio/XB1-04/ac4.mp3","sec":4.584,"t":"神经中枢对传入的信息进行分析和综合；"},{"ep":"xb1-04","n":"XB1-04","p":2,"a":"p2","id":"ac5","src":"assets/audio/XB1-04/ac5.mp3","sec":3.456,"t":"传出神经把兴奋传向效应器；"},{"ep":"xb1-04","n":"XB1-04","p":2,"a":"p2","id":"ac6","src":"assets/audio/XB1-04/ac6.mp3","sec":2.232,"t":"效应器作出应答。"},{"ep":"xb1-04","n":"XB1-04","p":2,"a":"p2","id":"ac7","src":"assets/audio/XB1-04/ac7.mp3","sec":8.04,"t":"易错：效应器不只是肌肉或腺体，而是传出神经末梢和它所支配的肌肉或腺体。"},{"ep":"xb1-04","n":"XB1-04","p":3,"a":"p3","id":"jd1","src":"assets/audio/XB1-04/jd1.mp3","sec":7.752,"t":"考点三，怎样判断传入神经和传出神经？这是高频考点，常用四种方法。"},{"ep":"xb1-04","n":"XB1-04","p":3,"a":"p3","id":"jd2","src":"assets/audio/XB1-04/jd2.mp3","sec":4.92,"t":"方法一，看神经节：有神经节的是传入神经。"},{"ep":"xb1-04","n":"XB1-04","p":3,"a":"p3","id":"jd3","src":"assets/audio/XB1-04/jd3.mp3","sec":11.112,"t":"方法二，看脊髓灰质：与前角，也就是较宽大的一侧相连的是传出神经；与后角，较狭窄的一侧相连的是传入神经。"},{"ep":"xb1-04","n":"XB1-04","p":3,"a":"p3","id":"jd4","src":"assets/audio/XB1-04/jd4.mp3","sec":11.4,"t":"方法三，看突触：兴奋在突触处只能由一个神经元的轴突末梢，传向下一个神经元，顺着这个方向，就能分出传入和传出。"},{"ep":"xb1-04","n":"XB1-04","p":3,"a":"p3","id":"jd5","src":"assets/audio/XB1-04/jd5.mp3","sec":14.016,"t":"方法四，切断实验：切断某条神经，刺激它靠近中枢的一端，效应器有反应，说明它是传入神经；刺激靠近效应器的一端有反应，它就是传出神经。"},{"ep":"xb1-04","n":"XB1-04","p":3,"a":"p3","id":"jd6","src":"assets/audio/XB1-04/jd6.mp3","sec":13.056,"t":"解题方法：先用神经节或前角、后角确定方向，再按“感受器→传入神经→神经中枢→传出神经→效应器”依次标出五个部分。"},{"ep":"xb1-04","n":"XB1-04","p":4,"a":"p4","id":"bk1","src":"assets/audio/XB1-04/bk1.mp3","sec":8.736,"t":"考点四，反射弧受损的分析。抓住两点：感觉在大脑皮层形成，反应由效应器完成。"},{"ep":"xb1-04","n":"XB1-04","p":4,"a":"p4","id":"bk2","src":"assets/audio/XB1-04/bk2.mp3","sec":8.304,"t":"如果感受器、传入神经或神经中枢受损，兴奋传不上去，既没有感觉，也没有反应。"},{"ep":"xb1-04","n":"XB1-04","p":4,"a":"p4","id":"bk3","src":"assets/audio/XB1-04/bk3.mp3","sec":8.688,"t":"如果传出神经或效应器受损，兴奋仍能经脊髓传到大脑皮层，所以有感觉，但没有反应。"},{"ep":"xb1-04","n":"XB1-04","p":4,"a":"p4","id":"bk4","src":"assets/audio/XB1-04/bk4.mp3","sec":11.088,"t":"如果脊髓里通向大脑的传导通路受损，反射弧本身完整，就没有感觉，但有反应，比如高位截瘫的病人仍有膝跳反射。"},{"ep":"xb1-04","n":"XB1-04","p":4,"a":"p4","id":"bk5","src":"assets/audio/XB1-04/bk5.mp3","sec":11.448,"t":"考法：题目说“有感觉、无反应”，受损部位在传出神经或效应器；“无感觉、有反应”，受损的是通向大脑的传导通路。"},{"ep":"xb1-04","n":"XB1-04","p":5,"a":"p5","id":"ty1","src":"assets/audio/XB1-04/ty1.mp3","sec":4.872,"t":"考点五，反射分为非条件反射和条件反射。"},{"ep":"xb1-04","n":"XB1-04","p":5,"a":"p5","id":"ty2","src":"assets/audio/XB1-04/ty2.mp3","sec":9.912,"t":"非条件反射是出生后无须训练就具有的，比如膝跳反射、眨眼反射、缩手反射，吃东西时分泌唾液。"},{"ep":"xb1-04","n":"XB1-04","p":5,"a":"p5","id":"ty3","src":"assets/audio/XB1-04/ty3.mp3","sec":8.544,"t":"条件反射是出生后在生活过程中通过学习和训练形成的，比如望梅止渴、谈虎色变。"},{"ep":"xb1-04","n":"XB1-04","p":5,"a":"p5","id":"ty4","src":"assets/audio/XB1-04/ty4.mp3","sec":13.344,"t":"非条件反射的神经中枢在大脑皮层以下，数量有限，终生存在；条件反射需要大脑皮层参与，数量几乎无限，需要不断强化，否则会消退。"},{"ep":"xb1-04","n":"XB1-04","p":5,"a":"p5","id":"ty5","src":"assets/audio/XB1-04/ty5.mp3","sec":11.592,"t":"考法：判断条件反射，抓住“后天学习、大脑皮层参与”。其中谈虎色变与语言文字有关，是人类特有的条件反射。"},{"ep":"xb1-04","n":"XB1-04","p":6,"a":"p6","id":"pv1","src":"assets/audio/XB1-04/pv1.mp3","sec":9.84,"t":"考点六，条件反射的建立与消退。照片是巴甫洛夫实验用过的一只狗，嘴边的导管用来收集唾液。"},{"ep":"xb1-04","n":"XB1-04","p":6,"a":"p6","id":"pv2","src":"assets/audio/XB1-04/pv2.mp3","sec":6.744,"t":"给狗喂食，狗会分泌唾液，这是非条件反射，食物是非条件刺激。"},{"ep":"xb1-04","n":"XB1-04","p":6,"a":"p6","id":"pv3","src":"assets/audio/XB1-04/pv3.mp3","sec":6.024,"t":"单独给狗听铃声，狗不会分泌唾液，这时铃声是{无关刺激|brown}。"},{"ep":"xb1-04","n":"XB1-04","p":6,"a":"p6","id":"pv4","src":"assets/audio/XB1-04/pv4.mp3","sec":12.384,"t":"每次喂食前先响铃，再给食物，重复多次以后，狗一听到铃声就分泌唾液。这时铃声已经变成条件刺激，条件反射就建立了。"},{"ep":"xb1-04","n":"XB1-04","p":6,"a":"p6","id":"pv5","src":"assets/audio/XB1-04/pv5.mp3","sec":8.616,"t":"如果反复只响铃、不喂食，唾液分泌会逐渐减少，直至消失，这就是条件反射的消退。"},{"ep":"xb1-04","n":"XB1-04","p":6,"a":"p6","id":"pv6","src":"assets/audio/XB1-04/pv6.mp3","sec":12.912,"t":"易错：消退不是条件反射的简单丧失，而是一个新的学习过程，需要大脑皮层参与，使铃声由引起兴奋的信号，变为产生抑制效应的信号。"},{"ep":"xb1-04","n":"XB1-04","p":7,"a":"p7","id":"mn1","src":"assets/audio/XB1-04/mn1.mp3","sec":9.096,"t":"考点七，条件反射的意义。条件反射是在非条件反射的基础上，通过学习和训练建立的。"},{"ep":"xb1-04","n":"XB1-04","p":7,"a":"p7","id":"mn2","src":"assets/audio/XB1-04/mn2.mp3","sec":8.448,"t":"它使机体具有更强的预见性、灵活性和适应性，大大提高了动物应对复杂环境变化的能力。"},{"ep":"xb1-04","n":"XB1-04","p":7,"a":"p7","id":"mn3","src":"assets/audio/XB1-04/mn3.mp3","sec":10.464,"t":"考法：问条件反射的意义，答出“使机体能识别刺激物的性质，预先作出反应，提高适应复杂环境变化的能力”。"},{"ep":"xb1-04","n":"XB1-04","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-04/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-04","n":"XB1-04","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-04/rv2.mp3","sec":13.488,"t":"只要反射弧完整，就能发生反射？错，还需要适宜的刺激。效应器就是肌肉或腺体？错，是传出神经末梢和它支配的肌肉或腺体。"},{"ep":"xb1-04","n":"XB1-04","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-04/rv3.mp3","sec":10.632,"t":"有神经节的是传入神经？对。传出神经受损，既无感觉又无反应？错，是有感觉、无反应。"},{"ep":"xb1-04","n":"XB1-04","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-04/rv4.mp3","sec":10.104,"t":"望梅止渴属于非条件反射？错，属于条件反射。条件反射的消退需要大脑皮层参与？对。"},{"ep":"xb1-04","n":"XB1-04","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-04/rv5.mp3","sec":15.264,"t":"七个考点串起来：反射靠反射弧完成，先学会判断传入和传出，再分析受损现象，最后分清两类反射。掌握这些，这一节就能稳稳拿分！我们下期再见！"},{"ep":"xb1-05","n":"XB1-05","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-05/in1.mp3","sec":9.576,"t":"同学们好！这节课梳理人教版选择性必修一第二章第三节的前半部分——兴奋在神经纤维上的传导。"},{"ep":"xb1-05","n":"XB1-05","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-05/in2.mp3","sec":9.936,"t":"这是神经调节的核心难点：静息电位和动作电位的离子机制、膜电位曲线、电表偏转，几乎年年都考。"},{"ep":"xb1-05","n":"XB1-05","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-05/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-05","n":"XB1-05","p":1,"a":"p1","id":"rs1","src":"assets/audio/XB1-05/rs1.mp3","sec":8.184,"t":"考点一，静息电位。神经纤维未受刺激时，膜两侧的电位表现为外正内负。"},{"ep":"xb1-05","n":"XB1-05","p":1,"a":"p1","id":"rs2","src":"assets/audio/XB1-05/rs2.mp3","sec":11.208,"t":"原因是：膜内K+浓度比膜外高，静息时膜主要对K+有通透性，K+外流，使膜外阳离子浓度高于膜内。"},{"ep":"xb1-05","n":"XB1-05","p":1,"a":"p1","id":"rs3","src":"assets/audio/XB1-05/rs3.mp3","sec":6.864,"t":"科学家正是用枪乌贼的巨大轴突，把微电极插进膜内，测出了这个电位。"},{"ep":"xb1-05","n":"XB1-05","p":1,"a":"p1","id":"rs4","src":"assets/audio/XB1-05/rs4.mp3","sec":8.712,"t":"易错：K+外流是顺浓度梯度、借助通道蛋白进行的，属于协助扩散，不消耗能量。"},{"ep":"xb1-05","n":"XB1-05","p":2,"a":"p2","id":"ap1","src":"assets/audio/XB1-05/ap1.mp3","sec":9.768,"t":"考点二，动作电位。神经纤维某一部位受到刺激时，膜对Na+的通透性增加，Na+迅速内流。"},{"ep":"xb1-05","n":"XB1-05","p":2,"a":"p2","id":"ap2","src":"assets/audio/XB1-05/ap2.mp3","sec":7.992,"t":"于是这个部位的膜电位变为外负内正，形成动作电位，这个部位就处于兴奋状态。"},{"ep":"xb1-05","n":"XB1-05","p":2,"a":"p2","id":"ap3","src":"assets/audio/XB1-05/ap3.mp3","sec":10.992,"t":"易错：Na+内流同样是顺浓度梯度、借助通道蛋白的协助扩散。记住口诀：静息钾外流，兴奋钠内流。"},{"ep":"xb1-05","n":"XB1-05","p":3,"a":"p3","id":"cu1","src":"assets/audio/XB1-05/cu1.mp3","sec":12.216,"t":"考点三，局部电流。兴奋部位外负内正，相邻的未兴奋部位仍是外正内负，两者之间有电位差，电荷移动形成局部电流。"},{"ep":"xb1-05","n":"XB1-05","p":3,"a":"p3","id":"cu2","src":"assets/audio/XB1-05/cu2.mp3","sec":8.712,"t":"在膜外，局部电流由未兴奋部位流向兴奋部位；在膜内，由兴奋部位流向未兴奋部位。"},{"ep":"xb1-05","n":"XB1-05","p":3,"a":"p3","id":"cu3","src":"assets/audio/XB1-05/cu3.mp3","sec":8.568,"t":"局部电流刺激相邻的未兴奋部位，使它也产生动作电位，兴奋就这样一段一段向前传导。"},{"ep":"xb1-05","n":"XB1-05","p":3,"a":"p3","id":"cu4","src":"assets/audio/XB1-05/cu4.mp3","sec":6.936,"t":"考法：兴奋的传导方向与膜内电流方向一致，与膜外电流方向相反。"},{"ep":"xb1-05","n":"XB1-05","p":4,"a":"p4","id":"cu5","src":"assets/audio/XB1-05/cu5.mp3","sec":9.888,"t":"考点四，传导方向。在离体的神经纤维上，刺激中间某一点，兴奋同时向两侧传导，是双向的。"},{"ep":"xb1-05","n":"XB1-05","p":4,"a":"p4","id":"cu6","src":"assets/audio/XB1-05/cu6.mp3","sec":9.456,"t":"易错：在生物体内的反射活动中，兴奋只能从感受器一端传来，所以在神经纤维上是单向传导的。"},{"ep":"xb1-05","n":"XB1-05","p":5,"a":"p5","id":"cv1","src":"assets/audio/XB1-05/cv1.mp3","sec":9.0,"t":"考点五，膜电位变化曲线。电极一个在膜内、一个在膜外，纵轴是膜内相对于膜外的电位。"},{"ep":"xb1-05","n":"XB1-05","p":5,"a":"p5","id":"cv2","src":"assets/audio/XB1-05/cv2.mp3","sec":5.856,"t":"ab段是静息电位，约−70 mV，由K+外流维持。"},{"ep":"xb1-05","n":"XB1-05","p":5,"a":"p5","id":"cv3","src":"assets/audio/XB1-05/cv3.mp3","sec":9.936,"t":"bc段，受到刺激后Na+通道开放，Na+大量内流，膜电位迅速上升到峰值，变成外负内正。"},{"ep":"xb1-05","n":"XB1-05","p":5,"a":"p5","id":"cv4","src":"assets/audio/XB1-05/cv4.mp3","sec":8.712,"t":"cd段，Na+通道关闭，K+通道开放，K+外流，膜电位恢复为外正内负。"},{"ep":"xb1-05","n":"XB1-05","p":5,"a":"p5","id":"cv5","src":"assets/audio/XB1-05/cv5.mp3","sec":10.224,"t":"{de段|brown}，{钠钾泵|brown}消耗ATP，泵出3个Na+、泵入2个K+，恢复膜内外的离子分布，属于{主动运输|brown}。"},{"ep":"xb1-05","n":"XB1-05","p":5,"a":"p5","id":"cv6","src":"assets/audio/XB1-05/cv6.mp3","sec":12.288,"t":"考法：问各段的运输方式，Na+内流、K+外流都是协助扩散，钠钾泵是{主动运输|brown}；峰值高低取决于Na+内流的量。"},{"ep":"xb1-05","n":"XB1-05","p":6,"a":"p6","id":"cc1","src":"assets/audio/XB1-05/cc1.mp3","sec":8.904,"t":"考点六，细胞外Na+、K+浓度改变，对膜电位有什么影响？关键看膜内外的浓度差。"},{"ep":"xb1-05","n":"XB1-05","p":6,"a":"p6","id":"cc2","src":"assets/audio/XB1-05/cc2.mp3","sec":11.184,"t":"细胞外Na+浓度升高，Na+浓度差变大，内流增多，动作电位峰值升高；细胞外Na+浓度降低，峰值降低。"},{"ep":"xb1-05","n":"XB1-05","p":6,"a":"p6","id":"cc3","src":"assets/audio/XB1-05/cc3.mp3","sec":8.376,"t":"细胞外Na+浓度改变，对静息电位基本没有影响，因为静息电位主要由K+外流决定。"},{"ep":"xb1-05","n":"XB1-05","p":6,"a":"p6","id":"cc4","src":"assets/audio/XB1-05/cc4.mp3","sec":12.72,"t":"细胞外K+浓度升高，K+浓度差变小，外流减少，静息电位的绝对值变小；细胞外K+浓度降低，静息电位的绝对值变大。"},{"ep":"xb1-05","n":"XB1-05","p":6,"a":"p6","id":"cc5","src":"assets/audio/XB1-05/cc5.mp3","sec":9.048,"t":"解题方法：先分清静息电位看K+、动作电位看Na+，再看浓度差是变大还是变小。"},{"ep":"xb1-05","n":"XB1-05","p":7,"a":"p7","id":"pb1","src":"assets/audio/XB1-05/pb1.mp3","sec":4.248,"t":"考点七，测量电位时，电极应该怎么放？"},{"ep":"xb1-05","n":"XB1-05","p":7,"a":"p7","id":"pb2","src":"assets/audio/XB1-05/pb2.mp3","sec":7.56,"t":"测静息电位，要把一个电极放在膜内，另一个放在膜外，电表才会显示出负电位。"},{"ep":"xb1-05","n":"XB1-05","p":7,"a":"p7","id":"pb3","src":"assets/audio/XB1-05/pb3.mp3","sec":8.856,"t":"如果两个电极都放在膜外，静息时膜外各处电位相等，电表指针不偏转，测不出静息电位。"},{"ep":"xb1-05","n":"XB1-05","p":7,"a":"p7","id":"pb4","src":"assets/audio/XB1-05/pb4.mp3","sec":10.008,"t":"易错：两个电极都在膜外的装置，测的是两点之间的电位差，用来研究兴奋的传导，不能用来测静息电位。"},{"ep":"xb1-05","n":"XB1-05","p":8,"a":"p8","id":"mt1","src":"assets/audio/XB1-05/mt1.mp3","sec":8.712,"t":"考点八，电表指针偏转问题。两个电极都放在神经纤维的膜外，分别在a、b两点。"},{"ep":"xb1-05","n":"XB1-05","p":8,"a":"p8","id":"mt2","src":"assets/audio/XB1-05/mt2.mp3","sec":12.768,"t":"在a点左侧给刺激，兴奋先到a点，指针偏转一次；兴奋传到b点时，指针向相反方向再偏转一次，共发生两次方向相反的偏转。"},{"ep":"xb1-05","n":"XB1-05","p":8,"a":"p8","id":"mt3","src":"assets/audio/XB1-05/mt3.mp3","sec":8.736,"t":"如果刺激点正好在a、b的中点，兴奋同时到达两点，两点之间没有电位差，指针不偏转。"},{"ep":"xb1-05","n":"XB1-05","p":8,"a":"p8","id":"mt4","src":"assets/audio/XB1-05/mt4.mp3","sec":8.064,"t":"如果刺激点在a、b之间、但不在中点，兴奋先后到达两点，指针仍然偏转两次。"},{"ep":"xb1-05","n":"XB1-05","p":8,"a":"p8","id":"mt5","src":"assets/audio/XB1-05/mt5.mp3","sec":9.792,"t":"解题方法：比较兴奋到达两个电极的先后——同时到达，不偏转；先后到达，偏转两次，方向相反。"},{"ep":"xb1-05","n":"XB1-05","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-05/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-05","n":"XB1-05","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-05/rv2.mp3","sec":11.88,"t":"静息电位的形成主要是Na+内流？错，主要是K+外流。产生动作电位时，膜电位表现为外负内正？对。"},{"ep":"xb1-05","n":"XB1-05","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-05/rv3.mp3","sec":12.528,"t":"兴奋的传导方向与膜外局部电流方向一致？错，与膜内电流方向一致。K+外流和Na+内流都属于协助扩散？对。"},{"ep":"xb1-05","n":"XB1-05","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-05/rv4.mp3","sec":12.048,"t":"细胞外Na+浓度升高，动作电位峰值升高？对。刺激两电极的中点，电表指针偏转两次？错，指针不偏转。"},{"ep":"xb1-05","n":"XB1-05","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-05/rv5.mp3","sec":14.304,"t":"八个考点串起来：静息看钾、兴奋看钠，局部电流推动兴奋传导，再学会读曲线、判电表。掌握这些，这一节就能稳稳拿分！我们下期再见！"},{"ep":"xb1-06","n":"XB1-06","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-06/in1.mp3","sec":9.504,"t":"同学们好！这节课梳理人教版选择性必修一第二章第三节的后半部分——兴奋在神经元之间的传递。"},{"ep":"xb1-06","n":"XB1-06","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-06/in2.mp3","sec":13.488,"t":"照片里是药理学家勒维，他用蛙心实验证明了神经靠化学物质传递信号。这一节常考突触的传递过程、药物作用机理和跨突触的电表偏转。"},{"ep":"xb1-06","n":"XB1-06","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-06/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-06","n":"XB1-06","p":1,"a":"p1","id":"sy1","src":"assets/audio/XB1-06/sy1.mp3","sec":12.696,"t":"考点一，突触的结构。轴突末梢经过多次分支，末端膨大形成突触小体，与其他神经元的细胞体或树突相接近，形成突触。"},{"ep":"xb1-06","n":"XB1-06","p":1,"a":"p1","id":"sy2","src":"assets/audio/XB1-06/sy2.mp3","sec":10.368,"t":"突触由突触前膜、{突触间隙|brown}和突触后膜三部分组成。突触小体内有许多突触小泡，里面装着神经递质。"},{"ep":"xb1-06","n":"XB1-06","p":1,"a":"p1","id":"sy3","src":"assets/audio/XB1-06/sy3.mp3","sec":7.128,"t":"右边是突触的电子显微镜照片，可以看到突触小体里密密麻麻的突触小泡。"},{"ep":"xb1-06","n":"XB1-06","p":1,"a":"p1","id":"sy4","src":"assets/audio/XB1-06/sy4.mp3","sec":5.688,"t":"常见的突触类型有两种：轴突—细胞体型和轴突—树突型。"},{"ep":"xb1-06","n":"XB1-06","p":1,"a":"p1","id":"sy5","src":"assets/audio/XB1-06/sy5.mp3","sec":10.968,"t":"易错：突触小体不等于突触。突触小体只是轴突末梢膨大的部分，突触则包括前膜、间隙、后膜三部分。"},{"ep":"xb1-06","n":"XB1-06","p":2,"a":"p2","id":"tp1","src":"assets/audio/XB1-06/tp1.mp3","sec":11.088,"t":"考点二，传递过程。兴奋传到突触小体，突触小泡移向突触前膜，与前膜融合，以胞吐的方式释放神经递质。"},{"ep":"xb1-06","n":"XB1-06","p":2,"a":"p2","id":"tp2","src":"assets/audio/XB1-06/tp2.mp3","sec":11.016,"t":"神经递质扩散通过突触间隙，与突触后膜上的特异性受体结合，引起后膜电位变化，使下一个神经元兴奋或抑制。"},{"ep":"xb1-06","n":"XB1-06","p":2,"a":"p2","id":"tp3","src":"assets/audio/XB1-06/tp3.mp3","sec":5.952,"t":"信号的转换是：电信号→化学信号→电信号。"},{"ep":"xb1-06","n":"XB1-06","p":2,"a":"p2","id":"tp4","src":"assets/audio/XB1-06/tp4.mp3","sec":7.776,"t":"考法：胞吐需要消耗能量，体现了膜的流动性，所以突触小体内线粒体较多。"},{"ep":"xb1-06","n":"XB1-06","p":2,"a":"p2","id":"tp5","src":"assets/audio/XB1-06/tp5.mp3","sec":8.52,"t":"易错：在突触小体完成的是“电信号→化学信号”，在突触后膜完成的是“化学信号→电信号”。"},{"ep":"xb1-06","n":"XB1-06","p":3,"a":"p3","id":"nt1","src":"assets/audio/XB1-06/nt1.mp3","sec":14.376,"t":"考点三，神经递质的种类与去向。常见的神经递质有乙酰胆碱，谷氨酸、甘氨酸等氨基酸类，多巴胺、去甲肾上腺素、5-羟色胺，还有一氧化氮等。"},{"ep":"xb1-06","n":"XB1-06","p":3,"a":"p3","id":"nt2","src":"assets/audio/XB1-06/nt2.mp3","sec":7.416,"t":"神经递质发挥作用后，会被降解，或被回收进突触前膜，以免持续发挥作用。"},{"ep":"xb1-06","n":"XB1-06","p":3,"a":"p3","id":"nt3","src":"assets/audio/XB1-06/nt3.mp3","sec":9.984,"t":"考法：如果递质不能被及时降解或回收，就会持续作用于后膜，使下一个神经元持续兴奋或持续抑制。"},{"ep":"xb1-06","n":"XB1-06","p":4,"a":"p4","id":"ih1","src":"assets/audio/XB1-06/ih1.mp3","sec":14.424,"t":"考点四，兴奋性递质和抑制性递质。兴奋性递质与受体结合后，后膜对Na+的通透性增加，Na+内流，后膜变为外负内正，产生动作电位。"},{"ep":"xb1-06","n":"XB1-06","p":4,"a":"p4","id":"ih2","src":"assets/audio/XB1-06/ih2.mp3","sec":11.568,"t":"抑制性递质与受体结合后，常使后膜的Cl-通道开放，Cl-内流，后膜仍是外正内负，而且电位差更大，更难兴奋。"},{"ep":"xb1-06","n":"XB1-06","p":4,"a":"p4","id":"ih3","src":"assets/audio/XB1-06/ih3.mp3","sec":9.144,"t":"易错：抑制性递质也使后膜的电位发生了变化，只是没有产生动作电位，后膜依然是外正内负。"},{"ep":"xb1-06","n":"XB1-06","p":5,"a":"p5","id":"ow1","src":"assets/audio/XB1-06/ow1.mp3","sec":4.656,"t":"考点五，兴奋在神经元之间只能单向传递。"},{"ep":"xb1-06","n":"XB1-06","p":5,"a":"p5","id":"ow2","src":"assets/audio/XB1-06/ow2.mp3","sec":9.336,"t":"原因是：神经递质只存在于突触前膜内的突触小泡中，只能由突触前膜释放，作用于突触后膜。"},{"ep":"xb1-06","n":"XB1-06","p":5,"a":"p5","id":"ow3","src":"assets/audio/XB1-06/ow3.mp3","sec":13.992,"t":"兴奋经过突触时，要经历递质的释放、扩散和与受体结合，需要较长时间，这叫{突触延搁|brown}。所以兴奋在突触处的传递比在神经纤维上的传导{慢|brown}。"},{"ep":"xb1-06","n":"XB1-06","p":5,"a":"p5","id":"ow4","src":"assets/audio/XB1-06/ow4.mp3","sec":10.8,"t":"考法：反射弧中的突触数目越多，完成反射所需的时间就越长；兴奋在反射弧中只能单向传递，原因就在突触。"},{"ep":"xb1-06","n":"XB1-06","p":6,"a":"p6","id":"dg1","src":"assets/audio/XB1-06/dg1.mp3","sec":6.24,"t":"考点六，药物和毒素怎样作用于突触？常见的有四种方式。"},{"ep":"xb1-06","n":"XB1-06","p":6,"a":"p6","id":"dg2","src":"assets/audio/XB1-06/dg2.mp3","sec":9.048,"t":"一是阻断受体：比如箭毒与乙酰胆碱受体结合，递质不能发挥作用，肌肉松弛，不能收缩。"},{"ep":"xb1-06","n":"XB1-06","p":6,"a":"p6","id":"dg3","src":"assets/audio/XB1-06/dg3.mp3","sec":10.824,"t":"二是抑制递质降解：比如有机磷农药抑制乙酰胆碱酯酶，乙酰胆碱持续作用，肌肉持续收缩，出现震颤、痉挛。"},{"ep":"xb1-06","n":"XB1-06","p":6,"a":"p6","id":"dg4","src":"assets/audio/XB1-06/dg4.mp3","sec":7.08,"t":"三是{抑制递质释放|brown}：比如肉毒毒素阻止乙酰胆碱释放，肌肉{无法收缩|brown}。"},{"ep":"xb1-06","n":"XB1-06","p":6,"a":"p6","id":"dg5","src":"assets/audio/XB1-06/dg5.mp3","sec":8.112,"t":"四是阻止递质回收，使突触间隙中的递质增多，作用增强，可卡因就是这样起作用的。"},{"ep":"xb1-06","n":"XB1-06","p":6,"a":"p6","id":"dg6","src":"assets/audio/XB1-06/dg6.mp3","sec":11.184,"t":"解题方法：先判断药物影响的是递质的{释放|brown}、与受体结合，还是降解和回收，再推出后膜是持续兴奋还是不能兴奋。"},{"ep":"xb1-06","n":"XB1-06","p":7,"a":"p7","id":"ad1","src":"assets/audio/XB1-06/ad1.mp3","sec":5.808,"t":"考点七，滥用兴奋剂、吸食毒品的危害，以可卡因为例。"},{"ep":"xb1-06","n":"XB1-06","p":7,"a":"p7","id":"ad2","src":"assets/audio/XB1-06/ad2.mp3","sec":6.888,"t":"正常情况下，多巴胺发挥作用后，会被突触前膜上的多巴胺转运体回收。"},{"ep":"xb1-06","n":"XB1-06","p":7,"a":"p7","id":"ad3","src":"assets/audio/XB1-06/ad3.mp3","sec":10.656,"t":"可卡因会使转运体失去回收多巴胺的功能，多巴胺留在突触间隙，持续刺激突触后膜，使人产生强烈的愉悦感。"},{"ep":"xb1-06","n":"XB1-06","p":7,"a":"p7","id":"ad4","src":"assets/audio/XB1-06/ad4.mp3","sec":11.568,"t":"长期这样，突触后膜上的多巴胺受体减少。一旦停药，多巴胺的作用减弱，人就需要更多毒品来维持兴奋，形成毒瘾。"},{"ep":"xb1-06","n":"XB1-06","p":7,"a":"p7","id":"ad5","src":"assets/audio/XB1-06/ad5.mp3","sec":11.04,"t":"考法：问可卡因成瘾的机理，答出“转运体失去回收功能→多巴胺持续作用→受体减少→需要更多毒品维持”。"},{"ep":"xb1-06","n":"XB1-06","p":8,"a":"p8","id":"mt1","src":"assets/audio/XB1-06/mt1.mp3","sec":9.792,"t":"考点八，跨突触的电表偏转。两个电极放在膜外：a在突触前的神经元上，b在突触后的神经元上。"},{"ep":"xb1-06","n":"XB1-06","p":8,"a":"p8","id":"mt2","src":"assets/audio/XB1-06/mt2.mp3","sec":7.368,"t":"刺激a左侧，兴奋先到a，再经过突触到b，指针偏转两次，方向相反。"},{"ep":"xb1-06","n":"XB1-06","p":8,"a":"p8","id":"mt3","src":"assets/audio/XB1-06/mt3.mp3","sec":6.864,"t":"刺激b右侧，兴奋只能到b，不能逆着突触传到a，指针只偏转一次。"},{"ep":"xb1-06","n":"XB1-06","p":8,"a":"p8","id":"mt4","src":"assets/audio/XB1-06/mt4.mp3","sec":9.552,"t":"刺激突触前、到a和b距离相等的一点，因为{突触延搁|brown}，兴奋先到a、后到b，指针仍然偏转两次。"},{"ep":"xb1-06","n":"XB1-06","p":8,"a":"p8","id":"mt5","src":"assets/audio/XB1-06/mt5.mp3","sec":10.608,"t":"解题方法：先看兴奋能不能过突触，只能从前膜传到后膜；再比较到达两电极的先后，经过突触的一侧要{更慢|brown}。"},{"ep":"xb1-06","n":"XB1-06","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-06/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-06","n":"XB1-06","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-06/rv2.mp3","sec":11.112,"t":"突触由突触前膜、突触间隙和突触后膜构成？对。神经递质以主动运输的方式释放？错，是胞吐。"},{"ep":"xb1-06","n":"XB1-06","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-06/rv3.mp3","sec":13.512,"t":"抑制性递质作用后，突触后膜电位不变？错，Cl-内流，外正内负的电位差增大。兴奋在突触处的传递比在神经纤维上慢？对。"},{"ep":"xb1-06","n":"XB1-06","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-06/rv4.mp3","sec":10.128,"t":"有机磷农药使肌肉持续收缩？对。可卡因使多巴胺受体增多而成瘾？错，是受体减少。"},{"ep":"xb1-06","n":"XB1-06","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-06/rv5.mp3","sec":14.424,"t":"八个考点串起来：看清突触结构，跟着递质走完释放、结合、降解或回收，再分析药物和电表。掌握这些，这一节就能稳稳拿分！我们下期再见！"},{"ep":"xb1-07","n":"XB1-07","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-07/in1.mp3","sec":8.232,"t":"同学们好！这节课梳理人教版选择性必修一第二章第四节——神经系统的分级调节。"},{"ep":"xb1-07","n":"XB1-07","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-07/in2.mp3","sec":8.136,"t":"这一节常考大脑皮层运动区的特点、排尿反射的分级调节，以及与排尿相关的病例分析。"},{"ep":"xb1-07","n":"XB1-07","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-07/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-07","n":"XB1-07","p":1,"a":"p1","id":"mo1","src":"assets/audio/XB1-07/mo1.mp3","sec":9.408,"t":"考点一，大脑皮层第一运动区。它位于中央前回，刺激它的不同部位，会引起身体相应部位的运动。"},{"ep":"xb1-07","n":"XB1-07","p":1,"a":"p1","id":"mo2","src":"assets/audio/XB1-07/mo2.mp3","sec":9.72,"t":"第一个特点：代表区的位置与躯体的关系是倒置的。下肢的代表区在顶部，头面部的代表区在底部。"},{"ep":"xb1-07","n":"XB1-07","p":1,"a":"p1","id":"mo3","src":"assets/audio/XB1-07/mo3.mp3","sec":5.64,"t":"不过头面部内部是正立的，比如眼的代表区在口的上方。"},{"ep":"xb1-07","n":"XB1-07","p":1,"a":"p1","id":"mo4","src":"assets/audio/XB1-07/mo4.mp3","sec":10.776,"t":"第二个特点：代表区的大小与躯体的大小无关，而与躯体运动的精细程度有关。手指、唇和舌的代表区特别大。"},{"ep":"xb1-07","n":"XB1-07","p":1,"a":"p1","id":"mo5","src":"assets/audio/XB1-07/mo5.mp3","sec":6.144,"t":"右边这个比例夸张的“小人”，就是按各部位代表区的大小画出来的。"},{"ep":"xb1-07","n":"XB1-07","p":1,"a":"p1","id":"mo6","src":"assets/audio/XB1-07/mo6.mp3","sec":10.032,"t":"易错：除头面部外，大脑皮层对躯体运动是交叉支配的：刺激右侧运动区，引起的是左侧肢体的运动。"},{"ep":"xb1-07","n":"XB1-07","p":2,"a":"p2","id":"sm1","src":"assets/audio/XB1-07/sm1.mp3","sec":9.096,"t":"考点二，躯体运动的分级调节。躯体的运动受大脑皮层、脑干、{小脑|brown}和脊髓等共同调控。"},{"ep":"xb1-07","n":"XB1-07","p":2,"a":"p2","id":"sm2","src":"assets/audio/XB1-07/sm2.mp3","sec":11.376,"t":"脊髓是机体运动的低级中枢，直接支配肌肉的运动；脑干连接低级中枢和高级中枢；{小脑|brown}协调运动、维持身体平衡。"},{"ep":"xb1-07","n":"XB1-07","p":2,"a":"p2","id":"sm3","src":"assets/audio/XB1-07/sm3.mp3","sec":9.528,"t":"大脑皮层是最高级中枢，它发出的指令通过脑干、脊髓传到肌肉，使运动更加有条不紊、精准。"},{"ep":"xb1-07","n":"XB1-07","p":2,"a":"p2","id":"sm4","src":"assets/audio/XB1-07/sm4.mp3","sec":10.752,"t":"考法：分级调节的核心是低级中枢受高级中枢的调控。题目中出现“受大脑皮层控制”，就要想到分级调节。"},{"ep":"xb1-07","n":"XB1-07","p":3,"a":"p3","id":"ur1","src":"assets/audio/XB1-07/ur1.mp3","sec":6.096,"t":"考点三，内脏活动的分级调节，最典型的例子是排尿反射。"},{"ep":"xb1-07","n":"XB1-07","p":3,"a":"p3","id":"ur2","src":"assets/audio/XB1-07/ur2.mp3","sec":10.656,"t":"排尿反射的低级中枢在脊髓。膀胱充盈时，膀胱壁内的感受器兴奋，经传入神经传到脊髓的排尿中枢。"},{"ep":"xb1-07","n":"XB1-07","p":3,"a":"p3","id":"ur3","src":"assets/audio/XB1-07/ur3.mp3","sec":9.576,"t":"兴奋一方面经传出神经引起膀胱收缩、排尿；另一方面经脊髓上传到大脑皮层，产生尿意。"},{"ep":"xb1-07","n":"XB1-07","p":3,"a":"p3","id":"ur4","src":"assets/audio/XB1-07/ur4.mp3","sec":8.232,"t":"大脑皮层可以通过脊髓控制排尿：有了尿意，如果条件不允许，人可以有意识地“憋尿”。"},{"ep":"xb1-07","n":"XB1-07","p":3,"a":"p3","id":"ur5","src":"assets/audio/XB1-07/ur5.mp3","sec":9.144,"t":"考法：排尿反射的低级中枢在脊髓，高级中枢在大脑皮层，脊髓的活动受大脑皮层调控。"},{"ep":"xb1-07","n":"XB1-07","p":4,"a":"p4","id":"cs1","src":"assets/audio/XB1-07/cs1.mp3","sec":7.056,"t":"考点四，病例分析。关键看大脑皮层与脊髓之间的联系是否完好。"},{"ep":"xb1-07","n":"XB1-07","p":4,"a":"p4","id":"cs2","src":"assets/audio/XB1-07/cs2.mp3","sec":6.48,"t":"成人能有意识地控制排尿，因为脊髓的低级中枢受大脑皮层调控。"},{"ep":"xb1-07","n":"XB1-07","p":4,"a":"p4","id":"cs3","src":"assets/audio/XB1-07/cs3.mp3","sec":6.576,"t":"婴儿经常尿床，是因为大脑发育尚未完善，对排尿的控制能力较弱。"},{"ep":"xb1-07","n":"XB1-07","p":4,"a":"p4","id":"cs4","src":"assets/audio/XB1-07/cs4.mp3","sec":12.048,"t":"截瘫病人脊髓受伤，大脑皮层与脊髓的联系中断，会出现尿失禁；但脊髓的排尿中枢完好，所以仍能排尿，只是不受意识控制。"},{"ep":"xb1-07","n":"XB1-07","p":4,"a":"p4","id":"cs5","src":"assets/audio/XB1-07/cs5.mp3","sec":15.312,"t":"解题方法：能不能排尿，看脊髓的反射弧是否完整；能不能有意识地控制，看大脑皮层与脊髓的联系。成人受惊吓时尿失禁，也是大脑暂时失去了对脊髓的控制。"},{"ep":"xb1-07","n":"XB1-07","p":5,"a":"p5","id":"au1","src":"assets/audio/XB1-07/au1.mp3","sec":4.2,"t":"考点五，自主神经系统并不完全“自主”。"},{"ep":"xb1-07","n":"XB1-07","p":5,"a":"p5","id":"au2","src":"assets/audio/XB1-07/au2.mp3","sec":13.56,"t":"内脏活动同样存在分级调节：脊髓是低级中枢，脑干有调节呼吸、心脏功能的基本中枢，{下丘脑|brown}是较高级中枢，大脑皮层是最高级中枢。"},{"ep":"xb1-07","n":"XB1-07","p":5,"a":"p5","id":"au3","src":"assets/audio/XB1-07/au3.mp3","sec":10.944,"t":"比如排尿时，副交感神经兴奋使膀胱缩小，交感神经兴奋不会导致膀胱缩小，而这一过程又受大脑皮层控制。"},{"ep":"xb1-07","n":"XB1-07","p":5,"a":"p5","id":"au4","src":"assets/audio/XB1-07/au4.mp3","sec":8.16,"t":"再比如，人紧张时会心跳加快、手心出汗，说明内脏活动也会受到情绪的影响。"},{"ep":"xb1-07","n":"XB1-07","p":5,"a":"p5","id":"au5","src":"assets/audio/XB1-07/au5.mp3","sec":7.368,"t":"易错：“自主”是指活动不受意识直接支配，并不是说它不受高级中枢调控。"},{"ep":"xb1-07","n":"XB1-07","p":6,"a":"p6","id":"se1","src":"assets/audio/XB1-07/se1.mp3","sec":8.28,"t":"考点六，感觉在哪里形成？痛觉、冷觉、渴觉等所有感觉，都在大脑皮层形成。"},{"ep":"xb1-07","n":"XB1-07","p":6,"a":"p6","id":"se2","src":"assets/audio/XB1-07/se2.mp3","sec":7.464,"t":"比如手被针扎，兴奋经传入神经到脊髓，再上传到大脑皮层，产生痛觉。"},{"ep":"xb1-07","n":"XB1-07","p":6,"a":"p6","id":"se3","src":"assets/audio/XB1-07/se3.mp3","sec":11.376,"t":"注意，感觉的形成不属于反射：它只经过感受器、传入神经和神经中枢，没有经过传出神经和效应器，反射弧不完整。"},{"ep":"xb1-07","n":"XB1-07","p":6,"a":"p6","id":"se4","src":"assets/audio/XB1-07/se4.mp3","sec":10.68,"t":"易错：缩手反射的中枢在脊髓，路径短；兴奋上传到大脑皮层的路径长，所以人往往先缩手、后感到疼。"},{"ep":"xb1-07","n":"XB1-07","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-07/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-07","n":"XB1-07","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-07/rv2.mp3","sec":11.184,"t":"刺激中央前回的顶部，可引起头面部运动？错，引起的是下肢运动。运动越精细的部位，代表区越大？对。"},{"ep":"xb1-07","n":"XB1-07","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-07/rv3.mp3","sec":12.912,"t":"排尿反射的高级中枢在脊髓？错，低级中枢在脊髓，高级中枢在大脑皮层。婴儿遗尿是因为大脑发育尚未完善？对。"},{"ep":"xb1-07","n":"XB1-07","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-07/rv4.mp3","sec":10.848,"t":"自主神经系统的活动不受大脑皮层调控？错。手被针扎产生痛觉，属于反射？错，反射弧不完整。"},{"ep":"xb1-07","n":"XB1-07","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-07/rv5.mp3","sec":15.096,"t":"六个考点串起来：高级中枢调控低级中枢，记住运动区倒置、排尿的两级中枢，病例题就能一眼看穿。掌握这些，这一节就能稳稳拿分！我们下期再见！"},{"ep":"xb1-08","n":"XB1-08","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-08/in1.mp3","sec":7.68,"t":"同学们好！这节课梳理人教版选择性必修一第二章第五节——人脑的高级功能。"},{"ep":"xb1-08","n":"XB1-08","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-08/in2.mp3","sec":12.792,"t":"照片里是1861年布罗卡研究过的一位病人的大脑：他能听懂别人说话，却几乎说不出话。这一节常考言语区、学习与记忆和情绪。"},{"ep":"xb1-08","n":"XB1-08","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-08/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-08","n":"XB1-08","p":1,"a":"p1","id":"lg1","src":"assets/audio/XB1-08/lg1.mp3","sec":8.184,"t":"考点一，语言功能。语言功能是人脑特有的高级功能，大脑皮层有四个言语区。"},{"ep":"xb1-08","n":"XB1-08","p":1,"a":"p1","id":"lg2","src":"assets/audio/XB1-08/lg2.mp3","sec":8.064,"t":"W区与书写有关，受损后不能写字；V区与阅读有关，受损后看不懂文字。"},{"ep":"xb1-08","n":"XB1-08","p":1,"a":"p1","id":"lg3","src":"assets/audio/XB1-08/lg3.mp3","sec":11.352,"t":"S区与说话有关，受损后不能讲话，这是布罗卡发现的区域；{H区|brown}与听有关，受损后{听不懂话|brown}，这是韦尼克发现的区域。"},{"ep":"xb1-08","n":"XB1-08","p":1,"a":"p1","id":"lg4","src":"assets/audio/XB1-08/lg4.mp3","sec":9.96,"t":"记忆方法：用英文首字母记——W是write，写；V是vision，看；S是speak，说；{H是hear，听|brown}。"},{"ep":"xb1-08","n":"XB1-08","p":2,"a":"p2","id":"hm1","src":"assets/audio/XB1-08/hm1.mp3","sec":8.112,"t":"考点二，大脑左右半球的功能侧重。大多数人主导语言功能的区域在左半球。"},{"ep":"xb1-08","n":"XB1-08","p":2,"a":"p2","id":"hm2","src":"assets/audio/XB1-08/hm2.mp3","sec":8.52,"t":"逻辑思维主要由左半球负责；右半球主要负责形象思维，比如音乐、绘画和空间识别。"},{"ep":"xb1-08","n":"XB1-08","p":2,"a":"p2","id":"hm3","src":"assets/audio/XB1-08/hm3.mp3","sec":6.024,"t":"两个半球通过胼胝体紧密联系、协同工作，并不是各干各的。"},{"ep":"xb1-08","n":"XB1-08","p":2,"a":"p2","id":"hm4","src":"assets/audio/XB1-08/hm4.mp3","sec":11.904,"t":"考法：病人左半球受损后出现失语，正是因为大多数人的言语区在左半球；右半球受损，更多影响空间识别等形象思维。"},{"ep":"xb1-08","n":"XB1-08","p":3,"a":"p3","id":"mm1","src":"assets/audio/XB1-08/mm1.mp3","sec":9.096,"t":"考点三，学习与记忆。学习和记忆相互联系、不可分割，人类的记忆过程分为四个阶段。"},{"ep":"xb1-08","n":"XB1-08","p":3,"a":"p3","id":"mm2","src":"assets/audio/XB1-08/mm2.mp3","sec":8.424,"t":"外界信息经感觉器官进入大脑，形成{感觉性记忆|brown}，保持时间很短，大部分会迅速消退。"},{"ep":"xb1-08","n":"XB1-08","p":3,"a":"p3","id":"mm3","src":"assets/audio/XB1-08/mm3.mp3","sec":8.328,"t":"经过注意，信息转入第一级记忆；第一级记忆经过反复运用、强化，转入第二级记忆；"},{"ep":"xb1-08","n":"XB1-08","p":3,"a":"p3","id":"mm4","src":"assets/audio/XB1-08/mm4.mp3","sec":7.536,"t":"再经过长年累月的运用，信息转入第三级记忆，可以保持终生，比如自己的名字。"},{"ep":"xb1-08","n":"XB1-08","p":3,"a":"p3","id":"mm5","src":"assets/audio/XB1-08/mm5.mp3","sec":9.048,"t":"易错：{感觉性记忆|brown}和第一级记忆属于短时记忆；第二级记忆和第三级记忆属于长时记忆。"},{"ep":"xb1-08","n":"XB1-08","p":4,"a":"p4","id":"mc1","src":"assets/audio/XB1-08/mc1.mp3","sec":4.296,"t":"考点四，短时记忆和长时记忆的机制。"},{"ep":"xb1-08","n":"XB1-08","p":4,"a":"p4","id":"mc2","src":"assets/audio/XB1-08/mc2.mp3","sec":9.24,"t":"短时记忆可能与神经元之间即时的信息交流有关，尤其是与大脑皮层下一个形状像海马的脑区有关。"},{"ep":"xb1-08","n":"XB1-08","p":4,"a":"p4","id":"mc3","src":"assets/audio/XB1-08/mc3.mp3","sec":6.264,"t":"长时记忆可能与突触形态及功能的改变，以及新突触的建立有关。"},{"ep":"xb1-08","n":"XB1-08","p":4,"a":"p4","id":"mc4","src":"assets/audio/XB1-08/mc4.mp3","sec":10.344,"t":"考法：问怎样把短时记忆变成长时记忆，答“反复运用、强化”；问长时记忆的结构基础，答“新突触的建立”。"},{"ep":"xb1-08","n":"XB1-08","p":5,"a":"p5","id":"em1","src":"assets/audio/XB1-08/em1.mp3","sec":7.536,"t":"考点五，情绪。情绪也是大脑的高级功能之一，是人对环境所作出的反应。"},{"ep":"xb1-08","n":"XB1-08","p":5,"a":"p5","id":"em2","src":"assets/audio/XB1-08/em2.mp3","sec":11.592,"t":"消极情绪达到一定程度时，就会产生抑郁。抑郁通常是短期的，可以通过自我调适、身边人的支持和心理咨询好转。"},{"ep":"xb1-08","n":"XB1-08","p":5,"a":"p5","id":"em3","src":"assets/audio/XB1-08/em3.mp3","sec":6.768,"t":"当抑郁持续下去而得不到缓解时，就可能形成抑郁症，需要专业的治疗。"},{"ep":"xb1-08","n":"XB1-08","p":5,"a":"p5","id":"em4","src":"assets/audio/XB1-08/em4.mp3","sec":14.496,"t":"抗抑郁药一般通过作用于突触来影响神经系统的功能。比如有些药物能抑制突触前膜对5-羟色胺的回收，使突触间隙中5-羟色胺的浓度维持在一定水平。"},{"ep":"xb1-08","n":"XB1-08","p":5,"a":"p5","id":"em5","src":"assets/audio/XB1-08/em5.mp3","sec":10.296,"t":"考法：这类题常和突触知识结合：抑制递质的回收，递质就在突触间隙中保留得更久，作用更持久。"},{"ep":"xb1-08","n":"XB1-08","p":6,"a":"p6","id":"sx1","src":"assets/audio/XB1-08/sx1.mp3","sec":6.528,"t":"考点六，题型：根据症状判断受损的脑区。看几个典型例子。"},{"ep":"xb1-08","n":"XB1-08","p":6,"a":"p6","id":"sx2","src":"assets/audio/XB1-08/sx2.mp3","sec":6.36,"t":"病人能看懂文字、能听懂别人说话，但不会讲话，受损的是S区。"},{"ep":"xb1-08","n":"XB1-08","p":6,"a":"p6","id":"sx3","src":"assets/audio/XB1-08/sx3.mp3","sec":5.88,"t":"病人能说话、能写字，但{听不懂别人讲话|brown}，受损的是{H区|brown}。"},{"ep":"xb1-08","n":"XB1-08","p":6,"a":"p6","id":"sx4","src":"assets/audio/XB1-08/sx4.mp3","sec":11.4,"t":"走路不稳、动作不协调，受损的是小脑；呼吸、心跳出现障碍，受损的是脑干；体温、水盐平衡失调，看下丘脑。"},{"ep":"xb1-08","n":"XB1-08","p":6,"a":"p6","id":"sx5","src":"assets/audio/XB1-08/sx5.mp3","sec":11.784,"t":"解题方法：先找出病人“不能”做的那件事，再对号入座：不能写看W区，看不懂看V区，不能说看S区，听不懂看H区。"},{"ep":"xb1-08","n":"XB1-08","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-08/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-08","n":"XB1-08","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-08/rv2.mp3","sec":12.528,"t":"语言功能是人脑特有的高级功能？对。S区受损的病人听不懂别人讲话？错，S区受损不能讲话，听不懂是H区受损。"},{"ep":"xb1-08","n":"XB1-08","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-08/rv3.mp3","sec":11.424,"t":"大多数人主导语言功能的区域在右半球？错，在左半球。第一级记忆属于长时记忆？错，属于短时记忆。"},{"ep":"xb1-08","n":"XB1-08","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-08/rv4.mp3","sec":9.192,"t":"长时记忆可能与新突触的建立有关？对。有些抗抑郁药能抑制五羟色胺的回收？对。"},{"ep":"xb1-08","n":"XB1-08","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-08/rv5.mp3","sec":15.888,"t":"六个考点串起来：记住W写、V看、S说、H听，分清短时记忆和长时记忆，再把情绪和突触联系起来。掌握这些，这一节就能稳稳拿分！我们下期再见！"},{"ep":"xb1-09","n":"XB1-09","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-09/in1.mp3","sec":8.616,"t":"同学们好！这节课一轮复习人教版选择性必修一第三章第一节——激素与内分泌系统。"},{"ep":"xb1-09","n":"XB1-09","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-09/in2.mp3","sec":8.856,"t":"这一节高考常考三类题：激素发现的实验分析、腺体与激素的对应，以及激素的作用与特点。"},{"ep":"xb1-09","n":"XB1-09","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-09/in3.mp3","sec":5.52,"t":"我们按九个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-09","n":"XB1-09","p":1,"a":"p1","id":"se1","src":"assets/audio/XB1-09/se1.mp3","sec":2.976,"t":"考点一，促胰液素的发现。"},{"ep":"xb1-09","n":"XB1-09","p":1,"a":"p1","id":"se2","src":"assets/audio/XB1-09/se2.mp3","sec":8.688,"t":"19世纪，人们普遍认为：胃酸刺激小肠的神经，神经把兴奋传给胰腺，胰腺分泌胰液。"},{"ep":"xb1-09","n":"XB1-09","p":1,"a":"p1","id":"se3","src":"assets/audio/XB1-09/se3.mp3","sec":9.168,"t":"沃泰默做了三组实验：稀盐酸注入小肠肠腔，胰腺分泌胰液；稀盐酸直接注入血液，不分泌；"},{"ep":"xb1-09","n":"XB1-09","p":1,"a":"p1","id":"se4","src":"assets/audio/XB1-09/se4.mp3","sec":7.104,"t":"切除通向这段小肠的神经，只留血管，再把稀盐酸注入小肠，仍然分泌。"},{"ep":"xb1-09","n":"XB1-09","p":1,"a":"p1","id":"se5","src":"assets/audio/XB1-09/se5.mp3","sec":7.464,"t":"但沃泰默固执地认为，这是小肠上的神经没有剔除干净，是一个“顽固的神经反射”。"},{"ep":"xb1-09","n":"XB1-09","p":1,"a":"p1","id":"se6","src":"assets/audio/XB1-09/se6.mp3","sec":10.464,"t":"斯他林和贝利斯大胆假设：这是化学调节。他们剪下小肠，刮下黏膜，与稀盐酸混合磨碎制成提取液，"},{"ep":"xb1-09","n":"XB1-09","p":1,"a":"p1","id":"se7","src":"assets/audio/XB1-09/se7.mp3","sec":8.568,"t":"注射到同一条狗的静脉中，胰腺分泌了胰液。这种物质叫促胰液素，是人们发现的第一种激素。"},{"ep":"xb1-09","n":"XB1-09","p":1,"a":"p1","id":"se8","src":"assets/audio/XB1-09/se8.mp3","sec":9.216,"t":"考法：常考实验对照的含义。第一组和第二组对照，说明胰液分泌不是盐酸直接作用于胰腺；"},{"ep":"xb1-09","n":"XB1-09","p":1,"a":"p1","id":"se9","src":"assets/audio/XB1-09/se9.mp3","sec":5.448,"t":"刮下黏膜再磨碎，目的是彻底排除神经调节的干扰。"},{"ep":"xb1-09","n":"XB1-09","p":1,"a":"p1","id":"se10","src":"assets/audio/XB1-09/se10.mp3","sec":9.24,"t":"易错：促胰液素由小肠黏膜分泌，作用于胰腺；而胰液是消化液，经导管排出，不是激素。"},{"ep":"xb1-09","n":"XB1-09","p":2,"a":"p2","id":"is1","src":"assets/audio/XB1-09/is1.mp3","sec":2.736,"t":"考点二，胰岛素的发现。"},{"ep":"xb1-09","n":"XB1-09","p":2,"a":"p2","id":"is2","src":"assets/audio/XB1-09/is2.mp3","sec":7.104,"t":"胰腺包括两部分：外分泌部分泌胰液，含胰蛋白酶；内分泌部就是胰岛。"},{"ep":"xb1-09","n":"XB1-09","p":2,"a":"p2","id":"is3","src":"assets/audio/XB1-09/is3.mp3","sec":7.416,"t":"科学家发现，切除胰腺的狗会患糖尿病，推测胰腺中有一种降血糖的物质。"},{"ep":"xb1-09","n":"XB1-09","p":2,"a":"p2","id":"is4","src":"assets/audio/XB1-09/is4.mp3","sec":6.528,"t":"可是把胰腺直接研磨制成提取液，注射给糖尿病狗，却收效甚微。"},{"ep":"xb1-09","n":"XB1-09","p":2,"a":"p2","id":"is5","src":"assets/audio/XB1-09/is5.mp3","sec":7.464,"t":"班廷想到：结扎胰管，让外分泌部萎缩，只剩下胰岛，再用它制备提取液，"},{"ep":"xb1-09","n":"XB1-09","p":2,"a":"p2","id":"is6","src":"assets/audio/XB1-09/is6.mp3","sec":6.168,"t":"注射给糖尿病狗，血糖迅速下降。这种物质就是胰岛素。"},{"ep":"xb1-09","n":"XB1-09","p":2,"a":"p2","id":"is7","src":"assets/audio/XB1-09/is7.mp3","sec":9.48,"t":"考法：为什么直接研磨胰腺提取不到胰岛素？因为胰岛素是蛋白质，会被胰液中的胰蛋白酶分解。"},{"ep":"xb1-09","n":"XB1-09","p":2,"a":"p2","id":"is8","src":"assets/audio/XB1-09/is8.mp3","sec":5.688,"t":"结扎胰管，就是为了让外分泌部萎缩，避免胰岛素被分解。"},{"ep":"xb1-09","n":"XB1-09","p":2,"a":"p2","id":"is9","src":"assets/audio/XB1-09/is9.mp3","sec":6.336,"t":"另外，切除胰腺属于减法原理，注射胰岛提取液属于加法原理。"},{"ep":"xb1-09","n":"XB1-09","p":3,"a":"p3","id":"ts1","src":"assets/audio/XB1-09/ts1.mp3","sec":6.912,"t":"考点三，睾丸分泌雄激素的研究，以及实验中的加法原理和减法原理。"},{"ep":"xb1-09","n":"XB1-09","p":3,"a":"p3","id":"ts2","src":"assets/audio/XB1-09/ts2.mp3","sec":9.312,"t":"1849年，科学家摘除公鸡的睾丸，公鸡的雄性性征明显消失，比如鸡冠萎缩、不再鸣啼求偶。"},{"ep":"xb1-09","n":"XB1-09","p":3,"a":"p3","id":"ts3","src":"assets/audio/XB1-09/ts3.mp3","sec":10.224,"t":"把睾丸重新移植回去，公鸡的雄性特征又逐步恢复。后来科学家从睾丸中提取出了睾酮，也就是雄激素。"},{"ep":"xb1-09","n":"XB1-09","p":3,"a":"p3","id":"ts4","src":"assets/audio/XB1-09/ts4.mp3","sec":6.864,"t":"与常态相比，人为去除某种影响因素，叫减法原理，比如摘除睾丸；"},{"ep":"xb1-09","n":"XB1-09","p":3,"a":"p3","id":"ts5","src":"assets/audio/XB1-09/ts5.mp3","sec":6.624,"t":"人为增加某种影响因素，叫加法原理，比如移植睾丸、注射激素。"},{"ep":"xb1-09","n":"XB1-09","p":3,"a":"p3","id":"ts6","src":"assets/audio/XB1-09/ts6.mp3","sec":10.728,"t":"考法：判断实验用了哪种原理。还要会跨章节迁移：艾弗里实验中，用DNA酶处理提取物，也是减法原理。"},{"ep":"xb1-09","n":"XB1-09","p":4,"a":"p4","id":"me1","src":"assets/audio/XB1-09/me1.mp3","sec":7.344,"t":"考点四，研究激素功能的常用方法和对照设计，这是实验大题的高频考点。"},{"ep":"xb1-09","n":"XB1-09","p":4,"a":"p4","id":"me2","src":"assets/audio/XB1-09/me2.mp3","sec":5.712,"t":"常用方法有四种：摘除法、移植法、注射法和饲喂法。"},{"ep":"xb1-09","n":"XB1-09","p":4,"a":"p4","id":"me3","src":"assets/audio/XB1-09/me3.mp3","sec":9.72,"t":"注意，饲喂法只适用于不会被消化的激素，比如用含甲状腺激素的饲料喂蝌蚪，它会提前变成小青蛙。"},{"ep":"xb1-09","n":"XB1-09","p":4,"a":"p4","id":"me4","src":"assets/audio/XB1-09/me4.mp3","sec":9.888,"t":"对照组怎么设？摘除实验的对照组要做假手术，即做相同手术但不摘除，排除手术本身的影响。"},{"ep":"xb1-09","n":"XB1-09","p":4,"a":"p4","id":"me5","src":"assets/audio/XB1-09/me5.mp3","sec":4.92,"t":"注射实验的对照组，注射等量的生理盐水或溶剂。"},{"ep":"xb1-09","n":"XB1-09","p":4,"a":"p4","id":"me6","src":"assets/audio/XB1-09/me6.mp3","sec":10.488,"t":"来看例题：探究甲状腺激素对小鼠代谢的影响。甲组切除甲状腺，乙组应如何处理？测什么指标？"},{"ep":"xb1-09","n":"XB1-09","p":4,"a":"p4","id":"me7","src":"assets/audio/XB1-09/me7.mp3","sec":8.712,"t":"乙组：做手术但不切除甲状腺。指标：耗氧量。预期甲组耗氧量低于乙组。"},{"ep":"xb1-09","n":"XB1-09","p":4,"a":"p4","id":"me8","src":"assets/audio/XB1-09/me8.mp3","sec":9.768,"t":"若要进一步证明是甲状腺激素的作用，可以给甲组注射甲状腺激素，耗氧量恢复。这就是“先减后加”。"},{"ep":"xb1-09","n":"XB1-09","p":5,"a":"p5","id":"gl1","src":"assets/audio/XB1-09/gl1.mp3","sec":8.544,"t":"考点五，内分泌系统的组成。它由内分泌腺和分散在一些器官中的内分泌细胞组成。"},{"ep":"xb1-09","n":"XB1-09","p":5,"a":"p5","id":"gl2","src":"assets/audio/XB1-09/gl2.mp3","sec":10.08,"t":"下丘脑：分泌多种促激素释放激素，如促甲状腺激素释放激素；还合成抗利尿激素，由垂体释放。"},{"ep":"xb1-09","n":"XB1-09","p":5,"a":"p5","id":"gl3","src":"assets/audio/XB1-09/gl3.mp3","sec":9.0,"t":"垂体：分泌生长激素，以及促甲状腺激素、促性腺激素、促肾上腺皮质激素等促激素。"},{"ep":"xb1-09","n":"XB1-09","p":5,"a":"p5","id":"gl4","src":"assets/audio/XB1-09/gl4.mp3","sec":4.512,"t":"甲状腺：分泌甲状腺激素，合成需要碘。"},{"ep":"xb1-09","n":"XB1-09","p":5,"a":"p5","id":"gl5","src":"assets/audio/XB1-09/gl5.mp3","sec":6.36,"t":"肾上腺：皮质分泌醛固酮、皮质醇，髓质分泌肾上腺素。"},{"ep":"xb1-09","n":"XB1-09","p":5,"a":"p5","id":"gl6","src":"assets/audio/XB1-09/gl6.mp3","sec":5.256,"t":"胰岛：A细胞分泌胰高血糖素，B细胞分泌胰岛素。"},{"ep":"xb1-09","n":"XB1-09","p":5,"a":"p5","id":"gl7","src":"assets/audio/XB1-09/gl7.mp3","sec":5.688,"t":"性腺：睾丸分泌雄激素，卵巢分泌雌激素和孕激素。"},{"ep":"xb1-09","n":"XB1-09","p":5,"a":"p5","id":"gl8","src":"assets/audio/XB1-09/gl8.mp3","sec":11.016,"t":"考法：腺体与激素的对应是基础送分题。易错：抗利尿激素由下丘脑合成、垂体释放，不是垂体合成的。"},{"ep":"xb1-09","n":"XB1-09","p":6,"a":"p6","id":"fn1","src":"assets/audio/XB1-09/fn1.mp3","sec":5.064,"t":"考点六，主要激素的功能，以及激素之间的相互作用。"},{"ep":"xb1-09","n":"XB1-09","p":6,"a":"p6","id":"fn2","src":"assets/audio/XB1-09/fn2.mp3","sec":7.584,"t":"甲状腺激素：调节有机物代谢，促进生长和发育，提高神经系统的兴奋性。"},{"ep":"xb1-09","n":"XB1-09","p":6,"a":"p6","id":"fn3","src":"assets/audio/XB1-09/fn3.mp3","sec":6.288,"t":"生长激素：调节生长发育，促进蛋白质合成和骨的生长。"},{"ep":"xb1-09","n":"XB1-09","p":6,"a":"p6","id":"fn4","src":"assets/audio/XB1-09/fn4.mp3","sec":7.2,"t":"胰岛素是唯一能降低血糖的激素；胰高血糖素和肾上腺素能升高血糖。"},{"ep":"xb1-09","n":"XB1-09","p":6,"a":"p6","id":"fn5","src":"assets/audio/XB1-09/fn5.mp3","sec":9.624,"t":"肾上腺素还能提高机体的应激能力；性激素促进生殖器官发育和生殖细胞形成，维持第二性征。"},{"ep":"xb1-09","n":"XB1-09","p":6,"a":"p6","id":"fn6","src":"assets/audio/XB1-09/fn6.mp3","sec":9.168,"t":"激素之间的关系：作用效果相同，叫协同作用，比如生长激素和甲状腺激素都促进生长发育；"},{"ep":"xb1-09","n":"XB1-09","p":6,"a":"p6","id":"fn7","src":"assets/audio/XB1-09/fn7.mp3","sec":5.544,"t":"作用效果相反，叫相抗衡，比如胰岛素和胰高血糖素。"},{"ep":"xb1-09","n":"XB1-09","p":6,"a":"p6","id":"fn8","src":"assets/audio/XB1-09/fn8.mp3","sec":11.256,"t":"考法：选择题常把激素和功能打乱配对。记住降血糖只有胰岛素，和促进发育、提高兴奋性的是甲状腺激素。"},{"ep":"xb1-09","n":"XB1-09","p":7,"a":"p7","id":"na1","src":"assets/audio/XB1-09/na1.mp3","sec":5.616,"t":"考点七，激素的化学本质，它决定了激素能不能口服。"},{"ep":"xb1-09","n":"XB1-09","p":7,"a":"p7","id":"na2","src":"assets/audio/XB1-09/na2.mp3","sec":7.92,"t":"蛋白质和多肽类：下丘脑和垂体分泌的激素、胰岛素、胰高血糖素、促胰液素。"},{"ep":"xb1-09","n":"XB1-09","p":7,"a":"p7","id":"na3","src":"assets/audio/XB1-09/na3.mp3","sec":4.656,"t":"氨基酸衍生物：甲状腺激素和肾上腺素。"},{"ep":"xb1-09","n":"XB1-09","p":7,"a":"p7","id":"na4","src":"assets/audio/XB1-09/na4.mp3","sec":4.224,"t":"类固醇：性激素、醛固酮、皮质醇。"},{"ep":"xb1-09","n":"XB1-09","p":7,"a":"p7","id":"na5","src":"assets/audio/XB1-09/na5.mp3","sec":9.12,"t":"蛋白质类激素口服会被消化酶分解，所以只能注射，不能口服；另外两类既可注射也可口服。"},{"ep":"xb1-09","n":"XB1-09","p":7,"a":"p7","id":"na6","src":"assets/audio/XB1-09/na6.mp3","sec":9.096,"t":"拓展：蛋白质类激素不能进入细胞，受体在细胞膜上；性激素是脂溶性的，受体在细胞内。"},{"ep":"xb1-09","n":"XB1-09","p":7,"a":"p7","id":"na7","src":"assets/audio/XB1-09/na7.mp3","sec":10.608,"t":"考法：糖尿病人为什么注射而不口服胰岛素？答：胰岛素是蛋白质，口服会在消化道中被分解而失效。"},{"ep":"xb1-09","n":"XB1-09","p":8,"a":"p8","id":"di1","src":"assets/audio/XB1-09/di1.mp3","sec":3.432,"t":"考点八，激素分泌异常与疾病。"},{"ep":"xb1-09","n":"XB1-09","p":8,"a":"p8","id":"di2","src":"assets/audio/XB1-09/di2.mp3","sec":11.352,"t":"幼年生长激素不足，患侏儒症，身材矮小但智力正常；幼年甲状腺激素不足，患呆小症，身材矮小且智力低下。"},{"ep":"xb1-09","n":"XB1-09","p":8,"a":"p8","id":"di3","src":"assets/audio/XB1-09/di3.mp3","sec":6.168,"t":"幼年生长激素过多，患巨人症；成年后过多，患肢端肥大症。"},{"ep":"xb1-09","n":"XB1-09","p":8,"a":"p8","id":"di4","src":"assets/audio/XB1-09/di4.mp3","sec":9.336,"t":"甲状腺激素过多，患甲亢，表现为消瘦、易激动；缺碘导致地方性甲状腺肿，俗称大脖子病。"},{"ep":"xb1-09","n":"XB1-09","p":8,"a":"p8","id":"di5","src":"assets/audio/XB1-09/di5.mp3","sec":5.112,"t":"胰岛B细胞受损，胰岛素分泌不足，导致糖尿病。"},{"ep":"xb1-09","n":"XB1-09","p":8,"a":"p8","id":"di6","src":"assets/audio/XB1-09/di6.mp3","sec":7.68,"t":"考法：侏儒症和呆小症的区别，关键看智力；病因要分清是幼年还是成年。"},{"ep":"xb1-09","n":"XB1-09","p":9,"a":"p9","id":"fe1","src":"assets/audio/XB1-09/fe1.mp3","sec":3.336,"t":"考点九，激素调节的四个特点。"},{"ep":"xb1-09","n":"XB1-09","p":9,"a":"p9","id":"fe2","src":"assets/audio/XB1-09/fe2.mp3","sec":6.48,"t":"第一，通过体液运输。激素弥散到体液中，随血液流到全身。"},{"ep":"xb1-09","n":"XB1-09","p":9,"a":"p9","id":"fe3","src":"assets/audio/XB1-09/fe3.mp3","sec":6.888,"t":"第二，作用于靶器官、靶细胞，因为只有靶细胞上有相应的特异性受体。"},{"ep":"xb1-09","n":"XB1-09","p":9,"a":"p9","id":"fe4","src":"assets/audio/XB1-09/fe4.mp3","sec":9.528,"t":"第三，作为信使传递信息。激素一经靶细胞接受并起作用后就失活了，所以需要源源不断地产生。"},{"ep":"xb1-09","n":"XB1-09","p":9,"a":"p9","id":"fe5","src":"assets/audio/XB1-09/fe5.mp3","sec":6.48,"t":"第四，微量和高效。血液中激素含量很低，作用却很显著。"},{"ep":"xb1-09","n":"XB1-09","p":9,"a":"p9","id":"fe6","src":"assets/audio/XB1-09/fe6.mp3","sec":10.8,"t":"易错：激素随血液运输到全身各处，不是只运输到靶细胞；激素不组成细胞结构、不提供能量、不起催化作用。"},{"ep":"xb1-09","n":"XB1-09","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-09/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-09","n":"XB1-09","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-09/rv2.mp3","sec":9.456,"t":"促胰液素由胰腺分泌？错，由小肠黏膜分泌。胰液属于激素？错，胰液是消化液。"},{"ep":"xb1-09","n":"XB1-09","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-09/rv3.mp3","sec":9.168,"t":"摘除睾丸利用了减法原理？对。胰岛素可以口服？错，它是蛋白质，只能注射。"},{"ep":"xb1-09","n":"XB1-09","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-09/rv4.mp3","sec":11.832,"t":"幼年缺乏甲状腺激素会患侏儒症？错，是呆小症。激素只运输到靶细胞？错，运输到全身，只作用于靶细胞。"},{"ep":"xb1-09","n":"XB1-09","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-09/rv5.mp3","sec":12.096,"t":"九个考点串成一条线：发现史、研究方法、腺体与激素、功能、本质、疾病与特点。把实验逻辑练熟，这一节稳稳拿分！"},{"ep":"xb1-10","n":"XB1-10","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-10/in1.mp3","sec":8.832,"t":"同学们好！这节课梳理人教版选择性必修一第三章第二节的前半部分——血糖平衡的调节。"},{"ep":"xb1-10","n":"XB1-10","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-10/in2.mp3","sec":8.76,"t":"这是激素调节最典型的例子，高考常考两种激素的作用、调节过程、曲线分析和糖尿病。"},{"ep":"xb1-10","n":"XB1-10","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-10/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-10","n":"XB1-10","p":1,"a":"p1","id":"sr1","src":"assets/audio/XB1-10/sr1.mp3","sec":8.4,"t":"考点一，血糖的来源与去路。正常人的血糖浓度在3.9～6.1 mmol/L之间。"},{"ep":"xb1-10","n":"XB1-10","p":1,"a":"p1","id":"sr2","src":"assets/audio/XB1-10/sr2.mp3","sec":9.624,"t":"血糖有三个来源：食物中的糖类消化吸收，这是主要来源；肝糖原分解；非糖物质转化为葡萄糖。"},{"ep":"xb1-10","n":"XB1-10","p":1,"a":"p1","id":"sr3","src":"assets/audio/XB1-10/sr3.mp3","sec":11.904,"t":"也有三个去路：氧化分解为二氧化碳和水，释放能量，这是主要去路；合成肝糖原、肌糖原；转化为甘油三酯等非糖物质。"},{"ep":"xb1-10","n":"XB1-10","p":1,"a":"p1","id":"sr4","src":"assets/audio/XB1-10/sr4.mp3","sec":8.448,"t":"易错：肌糖原不能直接分解成葡萄糖补充血糖，能直接分解补充血糖的只有肝糖原。"},{"ep":"xb1-10","n":"XB1-10","p":2,"a":"p2","id":"hm1","src":"assets/audio/XB1-10/hm1.mp3","sec":8.136,"t":"考点二，调节血糖的激素。胰岛素由胰岛B细胞分泌，是唯一能降低血糖的激素。"},{"ep":"xb1-10","n":"XB1-10","p":2,"a":"p2","id":"hm2","src":"assets/audio/XB1-10/hm2.mp3","sec":12.24,"t":"它一方面促进血糖进入组织细胞氧化分解、合成糖原、转化为甘油三酯；另一方面抑制肝糖原分解和非糖物质转化为葡萄糖。"},{"ep":"xb1-10","n":"XB1-10","p":2,"a":"p2","id":"hm3","src":"assets/audio/XB1-10/hm3.mp3","sec":9.216,"t":"胰高血糖素由胰岛A细胞分泌，主要作用于肝，促进肝糖原分解和非糖物质转化，使血糖升高。"},{"ep":"xb1-10","n":"XB1-10","p":2,"a":"p2","id":"hm4","src":"assets/audio/XB1-10/hm4.mp3","sec":5.256,"t":"此外，肾上腺髓质分泌的肾上腺素也能升高血糖。"},{"ep":"xb1-10","n":"XB1-10","p":2,"a":"p2","id":"hm5","src":"assets/audio/XB1-10/hm5.mp3","sec":8.976,"t":"考法：胰岛素与胰高血糖素作用相抗衡；胰高血糖素与肾上腺素在升血糖上是协同作用。"},{"ep":"xb1-10","n":"XB1-10","p":3,"a":"p3","id":"pr1","src":"assets/audio/XB1-10/pr1.mp3","sec":8.664,"t":"考点三，血糖调节的过程。血糖升高时，可以直接刺激胰岛B细胞，分泌胰岛素增加。"},{"ep":"xb1-10","n":"XB1-10","p":3,"a":"p3","id":"pr2","src":"assets/audio/XB1-10/pr2.mp3","sec":5.952,"t":"血糖降低时，可以直接刺激胰岛A细胞，分泌胰高血糖素增加。"},{"ep":"xb1-10","n":"XB1-10","p":3,"a":"p3","id":"pr3","src":"assets/audio/XB1-10/pr3.mp3","sec":10.128,"t":"神经系统也参与调节：血糖升高时，{下丘脑|brown}的某个区域兴奋，通过副交感神经使胰岛B细胞分泌胰岛素。"},{"ep":"xb1-10","n":"XB1-10","p":3,"a":"p3","id":"pr4","src":"assets/audio/XB1-10/pr4.mp3","sec":11.256,"t":"血糖降低时，下丘脑的另一个区域兴奋，通过交感神经使胰岛A细胞分泌胰高血糖素，还使肾上腺髓质分泌肾上腺素。"},{"ep":"xb1-10","n":"XB1-10","p":3,"a":"p3","id":"pr5","src":"assets/audio/XB1-10/pr5.mp3","sec":9.12,"t":"考法：血糖平衡是神经—体液调节，以激素调节为主；神经调节最终还是通过激素起作用。"},{"ep":"xb1-10","n":"XB1-10","p":4,"a":"p4","id":"fb1","src":"assets/audio/XB1-10/fb1.mp3","sec":12.432,"t":"考点四，反馈调节。在一个系统中，系统本身工作的效果，反过来又作为信息调节该系统的工作，这种调节方式叫作反馈调节。"},{"ep":"xb1-10","n":"XB1-10","p":4,"a":"p4","id":"fb2","src":"assets/audio/XB1-10/fb2.mp3","sec":7.824,"t":"比如胰岛素使血糖降低，血糖降低后，又会使胰岛素的分泌减少，这是负反馈。"},{"ep":"xb1-10","n":"XB1-10","p":4,"a":"p4","id":"fb3","src":"assets/audio/XB1-10/fb3.mp3","sec":7.968,"t":"负反馈调节是生命系统中非常普遍的调节机制，对于机体维持稳态具有重要意义。"},{"ep":"xb1-10","n":"XB1-10","p":4,"a":"p4","id":"fb4","src":"assets/audio/XB1-10/fb4.mp3","sec":10.632,"t":"易错：反馈调节也有正反馈，比如排尿反射、分娩、血液凝固，它使原来的变化越来越强，而不是维持稳定。"},{"ep":"xb1-10","n":"XB1-10","p":5,"a":"p5","id":"cu1","src":"assets/audio/XB1-10/cu1.mp3","sec":8.424,"t":"考点五，曲线分析。先看进食后：血糖浓度先升高，随后在胰岛素作用下回落。"},{"ep":"xb1-10","n":"XB1-10","p":5,"a":"p5","id":"cu2","src":"assets/audio/XB1-10/cu2.mp3","sec":7.896,"t":"胰岛素含量随血糖升高而升高，峰值出现得稍晚一点；胰高血糖素含量则下降。"},{"ep":"xb1-10","n":"XB1-10","p":5,"a":"p5","id":"cu3","src":"assets/audio/XB1-10/cu3.mp3","sec":9.936,"t":"再看运动或饥饿时：血糖被大量消耗，胰高血糖素含量升高，胰岛素含量降低，血糖基本维持稳定。"},{"ep":"xb1-10","n":"XB1-10","p":5,"a":"p5","id":"cu4","src":"assets/audio/XB1-10/cu4.mp3","sec":12.648,"t":"解题方法：先判断血糖的变化方向，再推激素：血糖高，胰岛素多；血糖低，胰高血糖素多。两条激素曲线往往一升一降。"},{"ep":"xb1-10","n":"XB1-10","p":6,"a":"p6","id":"db1","src":"assets/audio/XB1-10/db1.mp3","sec":9.648,"t":"考点六，糖尿病。1型糖尿病是胰岛B细胞受损，胰岛素分泌不足，可以通过注射胰岛素治疗。"},{"ep":"xb1-10","n":"XB1-10","p":6,"a":"p6","id":"db2","src":"assets/audio/XB1-10/db2.mp3","sec":15.72,"t":"2型糖尿病与遗传、环境、生活方式等有关，常见原因是靶细胞对胰岛素不敏感，比如受体异常，患者的胰岛素含量可能正常甚至偏高，注射胰岛素效果往往不佳。"},{"ep":"xb1-10","n":"XB1-10","p":6,"a":"p6","id":"db3","src":"assets/audio/XB1-10/db3.mp3","sec":6.744,"t":"糖尿病的典型症状是“三多一少”：多饮、多食、多尿，体重减少。"},{"ep":"xb1-10","n":"XB1-10","p":6,"a":"p6","id":"db4","src":"assets/audio/XB1-10/db4.mp3","sec":13.368,"t":"考法：解释“三多一少”：糖随尿排出带走大量水，所以多尿、多饮；细胞能量供应不足，所以多食；脂肪和蛋白质分解增加，所以消瘦。"},{"ep":"xb1-10","n":"XB1-10","p":7,"a":"p7","id":"ur1","src":"assets/audio/XB1-10/ur1.mp3","sec":13.512,"t":"考点七，尿糖检测。可以用斐林试剂检测尿液中的还原糖，水浴加热后出现砖红色沉淀，说明尿中有葡萄糖。也可以用尿糖试纸。"},{"ep":"xb1-10","n":"XB1-10","p":7,"a":"p7","id":"ur2","src":"assets/audio/XB1-10/ur2.mp3","sec":10.08,"t":"但要注意：尿中有糖不一定是糖尿病。一次吃糖过多，或者肾小管重吸收功能障碍，也会出现尿糖。"},{"ep":"xb1-10","n":"XB1-10","p":7,"a":"p7","id":"ur3","src":"assets/audio/XB1-10/ur3.mp3","sec":9.984,"t":"考法：判断是否患糖尿病，要看血糖浓度是否持续偏高，并结合胰岛素含量判断是1型还是2型。"},{"ep":"xb1-10","n":"XB1-10","p":8,"a":"p8","id":"ex1","src":"assets/audio/XB1-10/ex1.mp3","sec":5.448,"t":"考点八，实验设计：验证胰岛素有降低血糖的作用。"},{"ep":"xb1-10","n":"XB1-10","p":8,"a":"p8","id":"ex2","src":"assets/audio/XB1-10/ex2.mp3","sec":11.184,"t":"取生理状况相同的小鼠，先{饥饿处理|brown}，使实验现象更明显。实验组注射胰岛素溶液，对照组注射等量生理盐水。"},{"ep":"xb1-10","n":"XB1-10","p":8,"a":"p8","id":"ex3","src":"assets/audio/XB1-10/ex3.mp3","sec":8.496,"t":"一段时间后，实验组小鼠出现低血糖症状，比如活动减少、甚至昏迷；对照组正常。"},{"ep":"xb1-10","n":"XB1-10","p":8,"a":"p8","id":"ex4","src":"assets/audio/XB1-10/ex4.mp3","sec":8.832,"t":"再给出现症状的小鼠注射葡萄糖溶液，症状很快缓解，这就进一步证明症状是低血糖引起的。"},{"ep":"xb1-10","n":"XB1-10","p":8,"a":"p8","id":"ex5","src":"assets/audio/XB1-10/ex5.mp3","sec":12.672,"t":"解题方法：这是“先注射胰岛素，后注射葡萄糖”的两次对照：第一次证明胰岛素能降血糖，第二次通过自身前后对照，排除其他原因。"},{"ep":"xb1-10","n":"XB1-10","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-10/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-10","n":"XB1-10","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-10/rv2.mp3","sec":11.184,"t":"肌糖原可以直接分解成葡萄糖补充血糖？错，只有肝糖原可以。胰岛素是唯一能降低血糖的激素？对。"},{"ep":"xb1-10","n":"XB1-10","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-10/rv3.mp3","sec":14.016,"t":"胰高血糖素与肾上腺素在升血糖上相抗衡？错，是协同作用。血糖调节只有激素调节？错，下丘脑可通过自主神经调节胰岛。"},{"ep":"xb1-10","n":"XB1-10","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-10/rv4.mp3","sec":9.456,"t":"2型糖尿病患者注射胰岛素效果往往不佳？对。尿中有糖，一定是糖尿病？错。"},{"ep":"xb1-10","n":"XB1-10","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-10/rv5.mp3","sec":16.68,"t":"八个考点串起来：血糖三来源三去路，一种激素降、两种激素升，神经通过激素起作用，再加上反馈、曲线和糖尿病。掌握这些，这一节就能稳稳拿分！我们下期再见！"},{"ep":"xb1-11","n":"XB1-11","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-11/in1.mp3","sec":9.36,"t":"同学们好！这节课梳理人教版选择性必修一第三章第二节的后半部分——分级调节与反馈调节。"},{"ep":"xb1-11","n":"XB1-11","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-11/in2.mp3","sec":9.888,"t":"以甲状腺激素为例，高考常考分级调节和负反馈、缺碘与甲状腺肿，以及切除腺体后的激素变化。"},{"ep":"xb1-11","n":"XB1-11","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-11/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-11","n":"XB1-11","p":1,"a":"p1","id":"ax1","src":"assets/audio/XB1-11/ax1.mp3","sec":11.352,"t":"考点一，下丘脑—垂体—甲状腺轴。寒冷或紧张时，{下丘脑|brown}分泌促甲状腺激素释放激素，简称TRH。"},{"ep":"xb1-11","n":"XB1-11","p":1,"a":"p1","id":"ax2","src":"assets/audio/XB1-11/ax2.mp3","sec":7.2,"t":"TRH作用于垂体，促使垂体分泌促甲状腺激素，简称TSH。"},{"ep":"xb1-11","n":"XB1-11","p":1,"a":"p1","id":"ax3","src":"assets/audio/XB1-11/ax3.mp3","sec":5.784,"t":"TSH作用于甲状腺，促使甲状腺分泌甲状腺激素。"},{"ep":"xb1-11","n":"XB1-11","p":1,"a":"p1","id":"ax4","src":"assets/audio/XB1-11/ax4.mp3","sec":11.544,"t":"甲状腺激素几乎作用于全身细胞，能提高细胞代谢速率，使机体产热增加；还能提高神经系统的兴奋性，促进生长发育。"},{"ep":"xb1-11","n":"XB1-11","p":1,"a":"p1","id":"ax5","src":"assets/audio/XB1-11/ax5.mp3","sec":10.056,"t":"易错：TRH的靶器官是垂体，TSH的靶器官是甲状腺，而甲状腺激素的靶细胞几乎是全身细胞。"},{"ep":"xb1-11","n":"XB1-11","p":2,"a":"p2","id":"gr1","src":"assets/audio/XB1-11/gr1.mp3","sec":9.312,"t":"考点二，分级调节。人们把下丘脑、垂体和靶腺体之间存在的分层调控，称为分级调节。"},{"ep":"xb1-11","n":"XB1-11","p":2,"a":"p2","id":"gr2","src":"assets/audio/XB1-11/gr2.mp3","sec":10.608,"t":"分级调节能够放大激素的调节效应：少量的TRH，经过垂体、甲状腺层层放大，产生大量的甲状腺激素。"},{"ep":"xb1-11","n":"XB1-11","p":2,"a":"p2","id":"gr3","src":"assets/audio/XB1-11/gr3.mp3","sec":10.92,"t":"考法：问分级调节的意义，答“放大激素的调节效应，形成多级反馈调节，有利于精细调控，从而维持机体的稳态”。"},{"ep":"xb1-11","n":"XB1-11","p":3,"a":"p3","id":"nf1","src":"assets/audio/XB1-11/nf1.mp3","sec":12.024,"t":"考点三，负反馈调节。当血液中的甲状腺激素含量增加到一定程度时，又会抑制下丘脑和垂体分泌TRH和TSH。"},{"ep":"xb1-11","n":"XB1-11","p":3,"a":"p3","id":"nf2","src":"assets/audio/XB1-11/nf2.mp3","sec":7.536,"t":"于是TSH减少，甲状腺激素的分泌也随之减少，含量回到正常水平。"},{"ep":"xb1-11","n":"XB1-11","p":3,"a":"p3","id":"nf3","src":"assets/audio/XB1-11/nf3.mp3","sec":9.888,"t":"易错：甲状腺激素的负反馈同时作用于下丘脑和垂体两处，画图时有两条反馈箭头，不要漏画。"},{"ep":"xb1-11","n":"XB1-11","p":4,"a":"p4","id":"gt1","src":"assets/audio/XB1-11/gt1.mp3","sec":7.368,"t":"考点四，缺碘为什么会导致甲状腺肿？因为碘是合成甲状腺激素的原料。"},{"ep":"xb1-11","n":"XB1-11","p":4,"a":"p4","id":"gt2","src":"assets/audio/XB1-11/gt2.mp3","sec":6.744,"t":"缺碘时，甲状腺激素合成减少，对下丘脑和垂体的抑制作用减弱。"},{"ep":"xb1-11","n":"XB1-11","p":4,"a":"p4","id":"gt3","src":"assets/audio/XB1-11/gt3.mp3","sec":13.488,"t":"于是TRH和TSH分泌增加，TSH持续促进甲状腺增生，甲状腺就肿大了。照片中这位病人颈部的隆起，就是甲状腺肿。"},{"ep":"xb1-11","n":"XB1-11","p":4,"a":"p4","id":"gt4","src":"assets/audio/XB1-11/gt4.mp3","sec":10.848,"t":"解题方法：沿着反馈链一步步推：甲状腺激素减少，抑制减弱，TRH、TSH增加，甲状腺增生肿大。"},{"ep":"xb1-11","n":"XB1-11","p":5,"a":"p5","id":"ot1","src":"assets/audio/XB1-11/ot1.mp3","sec":10.416,"t":"考点五，其他调节轴。除了甲状腺轴，还有下丘脑—垂体—肾上腺皮质轴，调节糖皮质激素的分泌；"},{"ep":"xb1-11","n":"XB1-11","p":5,"a":"p5","id":"ot2","src":"assets/audio/XB1-11/ot2.mp3","sec":5.352,"t":"以及下丘脑—垂体—性腺轴，调节性激素的分泌。"},{"ep":"xb1-11","n":"XB1-11","p":5,"a":"p5","id":"ot3","src":"assets/audio/XB1-11/ot3.mp3","sec":9.984,"t":"考法：这几条轴遵循同样的规律：分级调节加负反馈调节。会分析一条轴，就会分析所有的轴。"},{"ep":"xb1-11","n":"XB1-11","p":6,"a":"p6","id":"op1","src":"assets/audio/XB1-11/op1.mp3","sec":6.624,"t":"考点六，切除某个腺体或注射某种激素后，各激素含量怎样变化？"},{"ep":"xb1-11","n":"XB1-11","p":6,"a":"p6","id":"op2","src":"assets/audio/XB1-11/op2.mp3","sec":9.072,"t":"切除甲状腺：甲状腺激素减少，对下丘脑和垂体的抑制减弱，TRH和TSH都增加。"},{"ep":"xb1-11","n":"XB1-11","p":6,"a":"p6","id":"op3","src":"assets/audio/XB1-11/op3.mp3","sec":8.304,"t":"注射甲状腺激素：甲状腺激素增加，反馈抑制增强，TRH和TSH都减少。"},{"ep":"xb1-11","n":"XB1-11","p":6,"a":"p6","id":"op4","src":"assets/audio/XB1-11/op4.mp3","sec":9.12,"t":"切除垂体：TSH减少，甲状腺激素也减少，而TRH因为失去反馈抑制而增加。"},{"ep":"xb1-11","n":"XB1-11","p":6,"a":"p6","id":"op5","src":"assets/audio/XB1-11/op5.mp3","sec":8.208,"t":"解题方法：先找直接改变的那个激素，再顺着分级调节往下推，逆着负反馈往上推。"},{"ep":"xb1-11","n":"XB1-11","p":7,"a":"p7","id":"fe1","src":"assets/audio/XB1-11/fe1.mp3","sec":7.944,"t":"考点七，激素调节的特点。在激素与内分泌系统那一期讲过，这里简要回顾。"},{"ep":"xb1-11","n":"XB1-11","p":7,"a":"p7","id":"fe2","src":"assets/audio/XB1-11/fe2.mp3","sec":8.064,"t":"一是通过体液进行运输；二是作用于靶器官、靶细胞，因为只有它们有相应的受体；"},{"ep":"xb1-11","n":"XB1-11","p":7,"a":"p7","id":"fe3","src":"assets/audio/XB1-11/fe3.mp3","sec":4.68,"t":"三是作为信使传递信息；四是微量和高效。"},{"ep":"xb1-11","n":"XB1-11","p":7,"a":"p7","id":"fe4","src":"assets/audio/XB1-11/fe4.mp3","sec":11.112,"t":"易错：激素一经靶细胞接受并起作用后就失活了，所以体内需要源源不断地产生激素，以维持激素含量的动态平衡。"},{"ep":"xb1-11","n":"XB1-11","p":8,"a":"p8","id":"dx1","src":"assets/audio/XB1-11/dx1.mp3","sec":8.784,"t":"考点八，例题：甲状腺激素偏低的病人，怎样判断病变在下丘脑、垂体还是甲状腺？"},{"ep":"xb1-11","n":"XB1-11","p":8,"a":"p8","id":"dx2","src":"assets/audio/XB1-11/dx2.mp3","sec":6.72,"t":"如果TSH偏高，说明垂体在拼命“催”甲状腺，病变在甲状腺。"},{"ep":"xb1-11","n":"XB1-11","p":8,"a":"p8","id":"dx3","src":"assets/audio/XB1-11/dx3.mp3","sec":10.68,"t":"如果TSH偏低，而TRH偏高，病变在垂体；如果TSH和TRH都偏低，病变在{下丘脑|brown}。"},{"ep":"xb1-11","n":"XB1-11","p":8,"a":"p8","id":"dx4","src":"assets/audio/XB1-11/dx4.mp3","sec":12.0,"t":"还可以注射TRH来判断：注射后TSH明显升高，说明垂体正常，病变在{下丘脑|brown}；TSH不升高，病变在垂体。"},{"ep":"xb1-11","n":"XB1-11","p":8,"a":"p8","id":"dx5","src":"assets/audio/XB1-11/dx5.mp3","sec":11.544,"t":"解题方法：找到含量偏低的最上面一级激素，如果它的上一级激素偏高，或者它本身就是TRH，病变就在分泌它的那一级。"},{"ep":"xb1-11","n":"XB1-11","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-11/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-11","n":"XB1-11","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-11/rv2.mp3","sec":9.864,"t":"TRH直接作用于甲状腺？错，作用于垂体。分级调节可以放大激素的调节效应？对。"},{"ep":"xb1-11","n":"XB1-11","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-11/rv3.mp3","sec":12.408,"t":"甲状腺激素只反馈抑制垂体？错，同时抑制下丘脑和垂体。缺碘时TSH分泌增加，导致甲状腺肿大？对。"},{"ep":"xb1-11","n":"XB1-11","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-11/rv4.mp3","sec":12.576,"t":"切除垂体后，TRH含量减少？错，失去反馈抑制，TRH增加。激素一经靶细胞接受并起作用后就失活？对。"},{"ep":"xb1-11","n":"XB1-11","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-11/rv5.mp3","sec":12.912,"t":"八个考点串起来：一条轴、两种调节——分级调节往下放大，负反馈往上抑制。掌握这些，这一节就能稳稳拿分！我们下期再见！"},{"ep":"xb1-12","n":"XB1-12","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-12/in1.mp3","sec":9.144,"t":"同学们好！这节课梳理人教版选择性必修一第三章第三节——体液调节与神经调节的关系。"},{"ep":"xb1-12","n":"XB1-12","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-12/in2.mp3","sec":9.432,"t":"这一节是第三章的综合，高考常考两种调节的比较、体温调节和水盐平衡调节，还常出曲线题。"},{"ep":"xb1-12","n":"XB1-12","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-12/in3.mp3","sec":5.544,"t":"我们按十个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-12","n":"XB1-12","p":1,"a":"p1","id":"cn1","src":"assets/audio/XB1-12/cn1.mp3","sec":10.008,"t":"考点一，体液调节。激素等化学物质，通过体液传送的方式对生命活动进行调节，叫作体液调节。"},{"ep":"xb1-12","n":"XB1-12","p":1,"a":"p1","id":"cn2","src":"assets/audio/XB1-12/cn2.mp3","sec":11.04,"t":"激素调节是体液调节的主要内容；除了激素，组胺、某些气体分子，以及CO2等代谢产物，也能参与体液调节。"},{"ep":"xb1-12","n":"XB1-12","p":1,"a":"p1","id":"cn3","src":"assets/audio/XB1-12/cn3.mp3","sec":12.48,"t":"考法：血液中CO2浓度升高，会刺激呼吸中枢，使呼吸加深加快。所以给病人输氧时，常混入约5%的CO2。"},{"ep":"xb1-12","n":"XB1-12","p":2,"a":"p2","id":"cp1","src":"assets/audio/XB1-12/cp1.mp3","sec":5.304,"t":"考点二，体液调节和神经调节的比较，从四个方面看。"},{"ep":"xb1-12","n":"XB1-12","p":2,"a":"p2","id":"cp2","src":"assets/audio/XB1-12/cp2.mp3","sec":6.24,"t":"作用途径：神经调节通过反射弧，体液调节通过体液运输。"},{"ep":"xb1-12","n":"XB1-12","p":2,"a":"p2","id":"cp3","src":"assets/audio/XB1-12/cp3.mp3","sec":4.872,"t":"反应速度：神经调节迅速，体液调节较缓慢。"},{"ep":"xb1-12","n":"XB1-12","p":2,"a":"p2","id":"cp4","src":"assets/audio/XB1-12/cp4.mp3","sec":10.416,"t":"作用范围：神经调节准确、比较局限，体液调节较广泛；作用时间：神经调节短暂，体液调节比较长。"},{"ep":"xb1-12","n":"XB1-12","p":2,"a":"p2","id":"cp5","src":"assets/audio/XB1-12/cp5.mp3","sec":9.504,"t":"考法：题目描述“反应快、时间短”，是神经调节；“反应慢、范围广、持续时间长”，是体液调节。"},{"ep":"xb1-12","n":"XB1-12","p":3,"a":"p3","id":"rl1","src":"assets/audio/XB1-12/rl1.mp3","sec":12.648,"t":"考点三，二者的联系。一方面，不少内分泌腺直接或间接地受中枢神经系统的调节，这时体液调节可以看作神经调节的一个环节。"},{"ep":"xb1-12","n":"XB1-12","p":3,"a":"p3","id":"rl2","src":"assets/audio/XB1-12/rl2.mp3","sec":14.496,"t":"另一方面，激素也能影响神经系统的发育和功能。比如幼年缺乏甲状腺激素，会影响脑的发育；成年时甲状腺激素不足，神经系统的兴奋性会降低。"},{"ep":"xb1-12","n":"XB1-12","p":3,"a":"p3","id":"rl3","src":"assets/audio/XB1-12/rl3.mp3","sec":7.032,"t":"考法：动物的生命活动，通常是神经调节和体液调节共同作用的结果。"},{"ep":"xb1-12","n":"XB1-12","p":4,"a":"p4","id":"cd1","src":"assets/audio/XB1-12/cd1.mp3","sec":6.744,"t":"考点四，体温调节。体温相对稳定，是因为产热量等于散热量。"},{"ep":"xb1-12","n":"XB1-12","p":4,"a":"p4","id":"cd2","src":"assets/audio/XB1-12/cd2.mp3","sec":6.864,"t":"寒冷时，皮肤的冷觉感受器兴奋，兴奋传到{下丘脑的体温调节中枢|brown}。"},{"ep":"xb1-12","n":"XB1-12","p":4,"a":"p4","id":"cd3","src":"assets/audio/XB1-12/cd3.mp3","sec":13.392,"t":"一方面减少散热：皮肤血管收缩，汗腺分泌减少；另一方面增加产热：骨骼肌战栗，甲状腺激素和肾上腺素分泌增多，细胞代谢增强。"},{"ep":"xb1-12","n":"XB1-12","p":4,"a":"p4","id":"cd4","src":"assets/audio/XB1-12/cd4.mp3","sec":5.904,"t":"同时，兴奋传到大脑皮层产生冷觉，人会主动添加衣物。"},{"ep":"xb1-12","n":"XB1-12","p":4,"a":"p4","id":"cd5","src":"assets/audio/XB1-12/cd5.mp3","sec":7.92,"t":"易错：寒冷环境中体温依然稳定，产热和散热都比炎热时多，二者仍然相等。"},{"ep":"xb1-12","n":"XB1-12","p":5,"a":"p5","id":"ht1","src":"assets/audio/XB1-12/ht1.mp3","sec":12.096,"t":"考点五，炎热环境。皮肤的热觉感受器兴奋，经下丘脑体温调节中枢，使皮肤血管舒张、汗腺分泌增加，散热增加。"},{"ep":"xb1-12","n":"XB1-12","p":5,"a":"p5","id":"ht2","src":"assets/audio/XB1-12/ht2.mp3","sec":3.888,"t":"炎热时增加散热，主要靠汗液蒸发。"},{"ep":"xb1-12","n":"XB1-12","p":5,"a":"p5","id":"ht3","src":"assets/audio/XB1-12/ht3.mp3","sec":8.232,"t":"人体的热量来自细胞代谢：安静时主要来自肝脏等器官，运动时主要来自骨骼肌。"},{"ep":"xb1-12","n":"XB1-12","p":5,"a":"p5","id":"ht4","src":"assets/audio/XB1-12/ht4.mp3","sec":7.032,"t":"易错：体温调节中枢在{下丘脑|brown}，而冷觉、热觉在大脑皮层形成。"},{"ep":"xb1-12","n":"XB1-12","p":6,"a":"p6","id":"wt1","src":"assets/audio/XB1-12/wt1.mp3","sec":9.456,"t":"考点六，水盐平衡调节。饮水不足、失水过多或吃的食物过咸时，细胞外液渗透压升高。"},{"ep":"xb1-12","n":"XB1-12","p":6,"a":"p6","id":"wt2","src":"assets/audio/XB1-12/wt2.mp3","sec":9.168,"t":"{下丘脑|brown}中的{渗透压感受器|brown}受到刺激，一方面把兴奋传到大脑皮层，产生渴觉，人主动饮水；"},{"ep":"xb1-12","n":"XB1-12","p":6,"a":"p6","id":"wt3","src":"assets/audio/XB1-12/wt3.mp3","sec":6.816,"t":"另一方面，由{下丘脑合成、分泌|brown}，再由垂体释放的抗利尿激素增加。"},{"ep":"xb1-12","n":"XB1-12","p":6,"a":"p6","id":"wt4","src":"assets/audio/XB1-12/wt4.mp3","sec":8.856,"t":"抗利尿激素促进肾小管和集合管对水的重吸收，尿量减少，细胞外液渗透压随之降低。"},{"ep":"xb1-12","n":"XB1-12","p":6,"a":"p6","id":"wt5","src":"assets/audio/XB1-12/wt5.mp3","sec":7.392,"t":"易错：抗利尿激素由下丘脑合成，垂体只是释放，不要说成“垂体合成”。"},{"ep":"xb1-12","n":"XB1-12","p":7,"a":"p7","id":"al1","src":"assets/audio/XB1-12/al1.mp3","sec":9.696,"t":"考点七，醛固酮。当细胞外液量减少，或者血钠含量降低时，肾上腺皮质分泌醛固酮增加。"},{"ep":"xb1-12","n":"XB1-12","p":7,"a":"p7","id":"al2","src":"assets/audio/XB1-12/al2.mp3","sec":11.832,"t":"醛固酮促进肾小管和集合管对Na+的重吸收，维持血钠含量的平衡；血钾含量升高时，醛固酮还能促进K+的排出。"},{"ep":"xb1-12","n":"XB1-12","p":7,"a":"p7","id":"al3","src":"assets/audio/XB1-12/al3.mp3","sec":7.632,"t":"记忆方法：醛固酮“保钠排钾”。注意它由肾上腺皮质分泌，不是肾上腺髓质。"},{"ep":"xb1-12","n":"XB1-12","p":8,"a":"p8","id":"hy1","src":"assets/audio/XB1-12/hy1.mp3","sec":5.832,"t":"考点八，下丘脑在稳态调节中的作用，可以概括为四个方面。"},{"ep":"xb1-12","n":"XB1-12","p":8,"a":"p8","id":"hy2","src":"assets/audio/XB1-12/hy2.mp3","sec":8.64,"t":"一是{感受|brown}：有渗透压感受器；二是{传导|brown}：把渗透压感受器产生的兴奋传到大脑皮层；"},{"ep":"xb1-12","n":"XB1-12","p":8,"a":"p8","id":"hy3","src":"assets/audio/XB1-12/hy3.mp3","sec":12.6,"t":"三是{分泌|brown}：分泌抗利尿激素和多种促激素释放激素；四是{调节中枢|brown}：有体温调节中枢、水平衡调节中枢和血糖调节中枢。"},{"ep":"xb1-12","n":"XB1-12","p":8,"a":"p8","id":"hy4","src":"assets/audio/XB1-12/hy4.mp3","sec":7.8,"t":"考法：题目问“下丘脑的作用”，就从感受、传导、分泌、调节这四个方面去找。"},{"ep":"xb1-12","n":"XB1-12","p":9,"a":"p9","id":"uc1","src":"assets/audio/XB1-12/uc1.mp3","sec":13.848,"t":"考点九，曲线题。一次饮用大量清水后，细胞外液渗透压降低，抗利尿激素分泌减少，尿量增加，大约一小时后达到高峰，然后逐渐恢复。"},{"ep":"xb1-12","n":"XB1-12","p":9,"a":"p9","id":"uc2","src":"assets/audio/XB1-12/uc2.mp3","sec":6.216,"t":"如果饮用的是等量的生理盐水，渗透压基本不变，尿量变化不大。"},{"ep":"xb1-12","n":"XB1-12","p":9,"a":"p9","id":"uc3","src":"assets/audio/XB1-12/uc3.mp3","sec":8.832,"t":"解题方法：抗利尿激素和尿量的曲线变化相反：激素多，尿就少；激素少，尿就多。"},{"ep":"xb1-12","n":"XB1-12","p":10,"a":"p10","id":"fv1","src":"assets/audio/XB1-12/fv1.mp3","sec":5.808,"t":"考点十，例题：发热时，体温的变化可以分为三个阶段。"},{"ep":"xb1-12","n":"XB1-12","p":10,"a":"p10","id":"fv2","src":"assets/audio/XB1-12/fv2.mp3","sec":6.024,"t":"体温上升期：产热量大于散热量，病人常感到冷、打寒战。"},{"ep":"xb1-12","n":"XB1-12","p":10,"a":"p10","id":"fv3","src":"assets/audio/XB1-12/fv3.mp3","sec":5.952,"t":"高温持续期：体温维持在较高水平，产热量等于散热量。"},{"ep":"xb1-12","n":"XB1-12","p":10,"a":"p10","id":"fv4","src":"assets/audio/XB1-12/fv4.mp3","sec":6.744,"t":"体温下降期：产热量小于散热量，病人大量出汗，皮肤血管舒张。"},{"ep":"xb1-12","n":"XB1-12","p":10,"a":"p10","id":"fv5","src":"assets/audio/XB1-12/fv5.mp3","sec":13.344,"t":"解题方法：体温升高，产热大于散热；体温稳定，二者相等；体温下降，产热小于散热。只要体温稳定，无论高低，产热都等于散热。"},{"ep":"xb1-12","n":"XB1-12","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-12/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-12","n":"XB1-12","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-12/rv2.mp3","sec":13.176,"t":"体液调节就是激素调节？错，还包括CO2等其他化学物质的调节。神经调节反应迅速，作用范围准确、比较局限？对。"},{"ep":"xb1-12","n":"XB1-12","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-12/rv3.mp3","sec":13.128,"t":"寒冷时散热量比炎热时少？错，寒冷时产热、散热都更多。抗利尿激素由垂体合成？错，由下丘脑合成，垂体释放。"},{"ep":"xb1-12","n":"XB1-12","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-12/rv4.mp3","sec":10.056,"t":"醛固酮的作用是保钠排钾？对。发热的高温持续期，产热量大于散热量？错，二者相等。"},{"ep":"xb1-12","n":"XB1-12","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-12/rv5.mp3","sec":16.152,"t":"十个考点串起来：先比较两种调节，再抓住下丘脑这个枢纽，体温看产热和散热，水盐看抗利尿激素和醛固酮。掌握这些，第三章就能稳稳拿分！我们下期再见！"},{"ep":"xb1-13","n":"XB1-13","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-13/in1.mp3","sec":8.328,"t":"同学们好！这节课梳理人教版选择性必修一第四章第一节——免疫系统的组成和功能。"},{"ep":"xb1-13","n":"XB1-13","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-13/in2.mp3","sec":9.48,"t":"这一节是整个免疫调节的基础，高考常考免疫细胞的来源、三道防线的判断和免疫系统的三大功能。"},{"ep":"xb1-13","n":"XB1-13","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-13/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-13","n":"XB1-13","p":1,"a":"p1","id":"og1","src":"assets/audio/XB1-13/og1.mp3","sec":8.448,"t":"考点一，免疫器官。免疫系统由免疫器官、免疫细胞和免疫活性物质三部分组成。"},{"ep":"xb1-13","n":"XB1-13","p":1,"a":"p1","id":"og2","src":"assets/audio/XB1-13/og2.mp3","sec":7.68,"t":"免疫器官主要由淋巴组织构成，包括扁桃体、胸腺、脾、淋巴结和骨髓。"},{"ep":"xb1-13","n":"XB1-13","p":1,"a":"p1","id":"og3","src":"assets/audio/XB1-13/og3.mp3","sec":11.256,"t":"骨髓是各种免疫细胞发生、分化、发育的场所；胸腺是T细胞分化、发育、成熟的场所，青春期以后会逐渐退化。"},{"ep":"xb1-13","n":"XB1-13","p":1,"a":"p1","id":"og4","src":"assets/audio/XB1-13/og4.mp3","sec":11.424,"t":"脾、淋巴结和扁桃体是免疫细胞集中分布的场所。淋巴结沿淋巴管遍布全身，能阻止和消灭侵入体内的微生物。"},{"ep":"xb1-13","n":"XB1-13","p":1,"a":"p1","id":"og5","src":"assets/audio/XB1-13/og5.mp3","sec":10.416,"t":"考法：骨髓和胸腺管免疫细胞的产生和成熟；脾、淋巴结、扁桃体管免疫细胞的集中分布和发挥作用。"},{"ep":"xb1-13","n":"XB1-13","p":2,"a":"p2","id":"cl1","src":"assets/audio/XB1-13/cl1.mp3","sec":8.4,"t":"考点二，免疫细胞。免疫细胞是执行免疫功能的细胞，都来自骨髓中的造血干细胞。"},{"ep":"xb1-13","n":"XB1-13","p":2,"a":"p2","id":"cl2","src":"assets/audio/XB1-13/cl2.mp3","sec":12.0,"t":"免疫细胞包括各种类型的白细胞，主要有淋巴细胞、树突状细胞和巨噬细胞等。淋巴细胞又分为B淋巴细胞和T淋巴细胞。"},{"ep":"xb1-13","n":"XB1-13","p":2,"a":"p2","id":"cl3","src":"assets/audio/XB1-13/cl3.mp3","sec":8.064,"t":"T细胞又分为辅助性T细胞和细胞毒性T细胞等，它们在特异性免疫中分工不同。"},{"ep":"xb1-13","n":"XB1-13","p":2,"a":"p2","id":"cl4","src":"assets/audio/XB1-13/cl4.mp3","sec":13.272,"t":"B细胞、树突状细胞和巨噬细胞都能摄取和加工处理抗原，并把抗原信息暴露在细胞表面，传递给其他免疫细胞，统称为抗原呈递细胞。"},{"ep":"xb1-13","n":"XB1-13","p":2,"a":"p2","id":"cl5","src":"assets/audio/XB1-13/cl5.mp3","sec":10.632,"t":"易错：抗原呈递细胞不只是巨噬细胞，B细胞也是；巨噬细胞既参与非特异性免疫，也参与特异性免疫。"},{"ep":"xb1-13","n":"XB1-13","p":3,"a":"p3","id":"bt1","src":"assets/audio/XB1-13/bt1.mp3","sec":5.304,"t":"考点三，B细胞和T细胞从哪里来，又在哪里成熟？"},{"ep":"xb1-13","n":"XB1-13","p":3,"a":"p3","id":"bt2","src":"assets/audio/XB1-13/bt2.mp3","sec":3.288,"t":"它们都来自骨髓中的造血干细胞。"},{"ep":"xb1-13","n":"XB1-13","p":3,"a":"p3","id":"bt3","src":"assets/audio/XB1-13/bt3.mp3","sec":5.28,"t":"一部分在骨髓中分化、发育、成熟，成为B细胞；"},{"ep":"xb1-13","n":"XB1-13","p":3,"a":"p3","id":"bt4","src":"assets/audio/XB1-13/bt4.mp3","sec":10.44,"t":"另一部分迁移到胸腺中成熟，成为T细胞。成熟以后，它们随血液和淋巴循环，分布到淋巴结、脾等处。"},{"ep":"xb1-13","n":"XB1-13","p":3,"a":"p3","id":"bt5","src":"assets/audio/XB1-13/bt5.mp3","sec":13.968,"t":"易错：B细胞和T细胞产生的场所都是骨髓，区别在于成熟的场所——B细胞在骨髓，T细胞在胸腺。所以切除胸腺，主要影响的是T细胞。"},{"ep":"xb1-13","n":"XB1-13","p":4,"a":"p4","id":"sb1","src":"assets/audio/XB1-13/sb1.mp3","sec":7.824,"t":"考点四，免疫活性物质，是由免疫细胞或其他细胞产生的、发挥免疫作用的物质。"},{"ep":"xb1-13","n":"XB1-13","p":4,"a":"p4","id":"sb2","src":"assets/audio/XB1-13/sb2.mp3","sec":5.952,"t":"抗体是机体产生的专门应对抗原的蛋白质，由浆细胞分泌。"},{"ep":"xb1-13","n":"XB1-13","p":4,"a":"p4","id":"sb3","src":"assets/audio/XB1-13/sb3.mp3","sec":8.232,"t":"细胞因子主要由辅助性T细胞分泌，包括白细胞介素、干扰素、肿瘤坏死因子等。"},{"ep":"xb1-13","n":"XB1-13","p":4,"a":"p4","id":"sb4","src":"assets/audio/XB1-13/sb4.mp3","sec":5.976,"t":"溶菌酶能溶解细菌的细胞壁，唾液、泪液和血浆中都有。"},{"ep":"xb1-13","n":"XB1-13","p":4,"a":"p4","id":"sb5","src":"assets/audio/XB1-13/sb5.mp3","sec":8.28,"t":"易错：免疫活性物质不一定由免疫细胞产生，唾液腺、泪腺细胞也能分泌溶菌酶。"},{"ep":"xb1-13","n":"XB1-13","p":5,"a":"p5","id":"ln1","src":"assets/audio/XB1-13/ln1.mp3","sec":2.952,"t":"考点五，人体的三道防线。"},{"ep":"xb1-13","n":"XB1-13","p":5,"a":"p5","id":"ln2","src":"assets/audio/XB1-13/ln2.mp3","sec":7.656,"t":"第一道防线是皮肤和黏膜，比如皮肤的阻挡作用，呼吸道黏膜上纤毛的清扫作用。"},{"ep":"xb1-13","n":"XB1-13","p":5,"a":"p5","id":"ln3","src":"assets/audio/XB1-13/ln3.mp3","sec":8.664,"t":"第二道防线是体液中的杀菌物质，如溶菌酶，以及吞噬细胞，如巨噬细胞和树突状细胞。"},{"ep":"xb1-13","n":"XB1-13","p":5,"a":"p5","id":"ln4","src":"assets/audio/XB1-13/ln4.mp3","sec":7.224,"t":"第三道防线主要由免疫器官和免疫细胞，借助血液循环和淋巴循环组成。"},{"ep":"xb1-13","n":"XB1-13","p":5,"a":"p5","id":"ln5","src":"assets/audio/XB1-13/ln5.mp3","sec":13.992,"t":"易错：唾液、泪液、胃液都在与外界相通的腔道里，其中的杀菌物质属于第一道防线。解题方法：先看物质在体表、腔道，还是在体液中。"},{"ep":"xb1-13","n":"XB1-13","p":6,"a":"p6","id":"ns1","src":"assets/audio/XB1-13/ns1.mp3","sec":4.32,"t":"考点六，非特异性免疫与特异性免疫。"},{"ep":"xb1-13","n":"XB1-13","p":6,"a":"p6","id":"ns2","src":"assets/audio/XB1-13/ns2.mp3","sec":10.944,"t":"第一、二道防线是人人生来就有的，不针对某一类特定的病原体，对多种病原体都有防御作用，叫做非特异性免疫。"},{"ep":"xb1-13","n":"XB1-13","p":6,"a":"p6","id":"ns3","src":"assets/audio/XB1-13/ns3.mp3","sec":8.832,"t":"第三道防线是出生后，在与病原体接触的过程中形成的，只针对特定的抗原，叫做特异性免疫。"},{"ep":"xb1-13","n":"XB1-13","p":6,"a":"p6","id":"ns4","src":"assets/audio/XB1-13/ns4.mp3","sec":7.824,"t":"二者紧密联系：非特异性免疫是特异性免疫的基础，二者共同完成免疫功能。"},{"ep":"xb1-13","n":"XB1-13","p":6,"a":"p6","id":"ns5","src":"assets/audio/XB1-13/ns5.mp3","sec":12.984,"t":"解题方法：看是否针对某种特定的病原体。患过麻疹不再患麻疹，属于特异性免疫；巨噬细胞吞噬多种病菌，属于非特异性免疫。"},{"ep":"xb1-13","n":"XB1-13","p":7,"a":"p7","id":"fn1","src":"assets/audio/XB1-13/fn1.mp3","sec":3.336,"t":"考点七，免疫系统的三大功能。"},{"ep":"xb1-13","n":"XB1-13","p":7,"a":"p7","id":"fn2","src":"assets/audio/XB1-13/fn2.mp3","sec":10.68,"t":"免疫防御：机体排除外来抗原性异物，是最基本的功能。功能过强会发生过敏反应，过弱则容易反复感染。"},{"ep":"xb1-13","n":"XB1-13","p":7,"a":"p7","id":"fn3","src":"assets/audio/XB1-13/fn3.mp3","sec":9.384,"t":"免疫自稳：清除衰老或损伤的细胞，维持内环境稳态。功能异常时，容易发生自身免疫病。"},{"ep":"xb1-13","n":"XB1-13","p":7,"a":"p7","id":"fn4","src":"assets/audio/XB1-13/fn4.mp3","sec":10.104,"t":"免疫监视：识别和清除突变的细胞，防止肿瘤发生。功能低下时，容易发生肿瘤或持续的病毒感染。"},{"ep":"xb1-13","n":"XB1-13","p":7,"a":"p7","id":"fn5","src":"assets/audio/XB1-13/fn5.mp3","sec":9.888,"t":"考法：根据实例判断功能——对付外来病原体是防御，清除衰老损伤的细胞是自稳，清除癌细胞是监视。"},{"ep":"xb1-13","n":"XB1-13","p":8,"a":"p8","id":"ag1","src":"assets/audio/XB1-13/ag1.mp3","sec":2.688,"t":"考点八，抗原与抗体。"},{"ep":"xb1-13","n":"XB1-13","p":8,"a":"p8","id":"ag2","src":"assets/audio/XB1-13/ag2.mp3","sec":7.968,"t":"抗原是能引发免疫反应的物质，大多数是蛋白质，比如病毒、细菌表面的蛋白质。"},{"ep":"xb1-13","n":"XB1-13","p":8,"a":"p8","id":"ag3","src":"assets/audio/XB1-13/ag3.mp3","sec":7.32,"t":"抗原不一定来自外界，自身衰老、损伤或癌变的细胞，也可能成为抗原。"},{"ep":"xb1-13","n":"XB1-13","p":8,"a":"p8","id":"ag4","src":"assets/audio/XB1-13/ag4.mp3","sec":10.248,"t":"抗体是浆细胞分泌的免疫球蛋白，能与相应抗原特异性结合，主要分布在血清中，组织液和外分泌液中也有。"},{"ep":"xb1-13","n":"XB1-13","p":8,"a":"p8","id":"ag5","src":"assets/audio/XB1-13/ag5.mp3","sec":11.304,"t":"易错：抗体与抗原结合后，形成沉淀或细胞集团，最终由其他免疫细胞吞噬消化，抗体本身不能直接清除病原体。"},{"ep":"xb1-13","n":"XB1-13","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-13/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-13","n":"XB1-13","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-13/rv2.mp3","sec":14.016,"t":"B细胞和T细胞都在骨髓中成熟？错，T细胞在胸腺中成熟。免疫活性物质都由免疫细胞产生？错，溶菌酶等也可以由其他细胞产生。"},{"ep":"xb1-13","n":"XB1-13","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-13/rv3.mp3","sec":10.704,"t":"胃液中的盐酸杀菌属于第一道防线？对。巨噬细胞只参与非特异性免疫？错，它也参与特异性免疫。"},{"ep":"xb1-13","n":"XB1-13","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-13/rv4.mp3","sec":10.32,"t":"清除体内癌变的细胞属于免疫自稳？错，属于免疫监视。抗体能与相应抗原特异性结合？对。"},{"ep":"xb1-13","n":"XB1-13","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-13/rv5.mp3","sec":14.856,"t":"八个考点串起来：先认清免疫系统的三个组成部分，再分清三道防线和两类免疫，最后记住三大功能。掌握这些，第四章就开了个好头！我们下期再见！"},{"ep":"xb1-14","n":"XB1-14","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-14/in1.mp3","sec":8.112,"t":"同学们好！这节课梳理人教版选择性必修一第四章第二节的上半部分——体液免疫。"},{"ep":"xb1-14","n":"XB1-14","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-14/in2.mp3","sec":9.888,"t":"体液免疫是免疫调节的核心，高考常考B细胞的激活、哪些细胞能识别抗原，以及二次免疫的曲线。"},{"ep":"xb1-14","n":"XB1-14","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-14/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-14","n":"XB1-14","p":1,"a":"p1","id":"rc1","src":"assets/audio/XB1-14/rc1.mp3","sec":3.936,"t":"考点一，免疫系统怎样识别病原体？"},{"ep":"xb1-14","n":"XB1-14","p":1,"a":"p1","id":"rc2","src":"assets/audio/XB1-14/rc2.mp3","sec":13.44,"t":"人体所有细胞的细胞膜表面，都有作为分子标签起作用的蛋白质，就像身份标志，能被自身的免疫细胞识别，所以免疫细胞一般不攻击自身细胞。"},{"ep":"xb1-14","n":"XB1-14","p":1,"a":"p1","id":"rc3","src":"assets/audio/XB1-14/rc3.mp3","sec":7.752,"t":"病毒、细菌等病原体也带有各自的身份标签，它们能引发免疫反应，就是抗原。"},{"ep":"xb1-14","n":"XB1-14","p":1,"a":"p1","id":"rc4","src":"assets/audio/XB1-14/rc4.mp3","sec":8.664,"t":"免疫细胞靠细胞表面的受体识别抗原。一个B细胞或T细胞，只能识别一种特定的抗原。"},{"ep":"xb1-14","n":"XB1-14","p":1,"a":"p1","id":"rc5","src":"assets/audio/XB1-14/rc5.mp3","sec":7.656,"t":"考法：识别的本质是受体与抗原的特异性结合；受体的化学本质是蛋白质。"},{"ep":"xb1-14","n":"XB1-14","p":2,"a":"p2","id":"pr1","src":"assets/audio/XB1-14/pr1.mp3","sec":8.568,"t":"考点二，体液免疫的过程。体液免疫主要靠B细胞产生抗体，消灭体液中的病原体。"},{"ep":"xb1-14","n":"XB1-14","p":2,"a":"p2","id":"pr2","src":"assets/audio/XB1-14/pr2.mp3","sec":6.888,"t":"一些病原体可以和B细胞直接接触，这为激活B细胞提供了第一个信号。"},{"ep":"xb1-14","n":"XB1-14","p":2,"a":"p2","id":"pr3","src":"assets/audio/XB1-14/pr3.mp3","sec":10.896,"t":"另一些病原体被树突状细胞、B细胞等抗原呈递细胞摄取、处理，呈递在细胞表面，然后传递给辅助性T细胞。"},{"ep":"xb1-14","n":"XB1-14","p":2,"a":"p2","id":"pr4","src":"assets/audio/XB1-14/pr4.mp3","sec":8.688,"t":"辅助性T细胞表面的特定分子发生变化，并与B细胞结合，这是激活B细胞的第二个信号。"},{"ep":"xb1-14","n":"XB1-14","p":2,"a":"p2","id":"pr5","src":"assets/audio/XB1-14/pr5.mp3","sec":9.624,"t":"辅助性T细胞开始分裂、分化，并分泌细胞因子，细胞因子能促进B细胞的分裂、分化过程。"},{"ep":"xb1-14","n":"XB1-14","p":2,"a":"p2","id":"pr6","src":"assets/audio/XB1-14/pr6.mp3","sec":10.056,"t":"易错：B细胞要受到两个信号的刺激才开始分裂、分化；细胞因子的作用是促进，它不是那两个信号之一。"},{"ep":"xb1-14","n":"XB1-14","p":3,"a":"p3","id":"pl1","src":"assets/audio/XB1-14/pl1.mp3","sec":9.24,"t":"考点三，B细胞活化以后，开始分裂、分化，大部分分化为浆细胞，小部分分化为记忆B细胞。"},{"ep":"xb1-14","n":"XB1-14","p":3,"a":"p3","id":"pl2","src":"assets/audio/XB1-14/pl2.mp3","sec":7.656,"t":"浆细胞产生和分泌大量抗体，抗体随体液在全身循环，与这种病原体结合。"},{"ep":"xb1-14","n":"XB1-14","p":3,"a":"p3","id":"pl3","src":"assets/audio/XB1-14/pl3.mp3","sec":7.296,"t":"抗体与病原体结合，可以抑制病原体的增殖，或者抑制它对人体细胞的黏附。"},{"ep":"xb1-14","n":"XB1-14","p":3,"a":"p3","id":"pl4","src":"assets/audio/XB1-14/pl4.mp3","sec":7.704,"t":"多数情况下，抗原和抗体结合后会形成沉淀等，进而被其他免疫细胞吞噬消化。"},{"ep":"xb1-14","n":"XB1-14","p":3,"a":"p3","id":"pl5","src":"assets/audio/XB1-14/pl5.mp3","sec":8.256,"t":"记忆B细胞可以存活几年甚至几十年，当再接触这种抗原时，能迅速增殖、分化。"},{"ep":"xb1-14","n":"XB1-14","p":3,"a":"p3","id":"pl6","src":"assets/audio/XB1-14/pl6.mp3","sec":6.408,"t":"易错：抗体只能由浆细胞产生，一个浆细胞只产生一种抗体。"},{"ep":"xb1-14","n":"XB1-14","p":4,"a":"p4","id":"rz1","src":"assets/audio/XB1-14/rz1.mp3","sec":6.024,"t":"考点四，哪些细胞能识别抗原？这是选择题的高频考点。"},{"ep":"xb1-14","n":"XB1-14","p":4,"a":"p4","id":"rz2","src":"assets/audio/XB1-14/rz2.mp3","sec":7.44,"t":"在体液免疫中，B细胞、辅助性T细胞和记忆B细胞都能特异性识别抗原。"},{"ep":"xb1-14","n":"XB1-14","p":4,"a":"p4","id":"rz3","src":"assets/audio/XB1-14/rz3.mp3","sec":6.96,"t":"抗原呈递细胞中的树突状细胞、巨噬细胞能识别抗原，但没有特异性。"},{"ep":"xb1-14","n":"XB1-14","p":4,"a":"p4","id":"rz4","src":"assets/audio/XB1-14/rz4.mp3","sec":4.416,"t":"浆细胞不能识别抗原，它只负责分泌抗体。"},{"ep":"xb1-14","n":"XB1-14","p":4,"a":"p4","id":"rz5","src":"assets/audio/XB1-14/rz5.mp3","sec":11.784,"t":"解题方法：浆细胞是唯一不能识别抗原的；巨噬细胞、树突状细胞能识别但不具特异性；其余的淋巴细胞都能特异性识别。"},{"ep":"xb1-14","n":"XB1-14","p":5,"a":"p5","id":"sc1","src":"assets/audio/XB1-14/sc1.mp3","sec":11.232,"t":"考点五，二次免疫。当同种抗原再次侵入机体时，记忆B细胞迅速增殖、分化，分化后快速产生大量抗体。"},{"ep":"xb1-14","n":"XB1-14","p":5,"a":"p5","id":"sc2","src":"assets/audio/XB1-14/sc2.mp3","sec":9.84,"t":"与初次免疫相比，二次免疫反应更快、更强，产生的抗体更多，往往在病原体致病之前就把它消灭了。"},{"ep":"xb1-14","n":"XB1-14","p":5,"a":"p5","id":"sc3","src":"assets/audio/XB1-14/sc3.mp3","sec":6.552,"t":"二次免疫中的浆细胞，主要来自记忆B细胞，也有一部分来自B细胞。"},{"ep":"xb1-14","n":"XB1-14","p":5,"a":"p5","id":"sc4","src":"assets/audio/XB1-14/sc4.mp3","sec":9.624,"t":"易错：记忆B细胞自己不产生抗体，它要先增殖、分化为浆细胞；记忆细胞只对同种抗原起作用。"},{"ep":"xb1-14","n":"XB1-14","p":6,"a":"p6","id":"cv1","src":"assets/audio/XB1-14/cv1.mp3","sec":8.208,"t":"考点六，二次免疫的曲线。第一次接触抗原后，抗体浓度上升较慢，峰值较低。"},{"ep":"xb1-14","n":"XB1-14","p":6,"a":"p6","id":"cv2","src":"assets/audio/XB1-14/cv2.mp3","sec":6.528,"t":"第二次接触同种抗原后，抗体浓度迅速上升，峰值远高于第一次。"},{"ep":"xb1-14","n":"XB1-14","p":6,"a":"p6","id":"cv3","src":"assets/audio/XB1-14/cv3.mp3","sec":7.08,"t":"患病程度的曲线正好相反：二次免疫时患病程度很轻，甚至不发病。"},{"ep":"xb1-14","n":"XB1-14","p":6,"a":"p6","id":"cv4","src":"assets/audio/XB1-14/cv4.mp3","sec":8.4,"t":"接种疫苗正是利用这个原理：相当于先让人体经历一次初次免疫，留下记忆细胞和抗体。"},{"ep":"xb1-14","n":"XB1-14","p":6,"a":"p6","id":"cv5","src":"assets/audio/XB1-14/cv5.mp3","sec":11.808,"t":"解题方法：抗体浓度上升更快、峰值更高的一段就是二次免疫；画曲线时，二次免疫要从第二次接触抗原的时间开始上升。"},{"ep":"xb1-14","n":"XB1-14","p":7,"a":"p7","id":"nt1","src":"assets/audio/XB1-14/nt1.mp3","sec":7.56,"t":"考点七，抗体的本质与分布。抗体的化学本质是蛋白质，也叫免疫球蛋白。"},{"ep":"xb1-14","n":"XB1-14","p":7,"a":"p7","id":"nt2","src":"assets/audio/XB1-14/nt2.mp3","sec":10.536,"t":"抗体属于分泌蛋白：在核糖体上合成，经内质网、高尔基体加工，以胞吐的方式分泌，整个过程由线粒体供能。"},{"ep":"xb1-14","n":"XB1-14","p":7,"a":"p7","id":"nt3","src":"assets/audio/XB1-14/nt3.mp3","sec":6.336,"t":"抗体主要分布在血清中，也分布在组织液和外分泌液中，比如乳汁。"},{"ep":"xb1-14","n":"XB1-14","p":7,"a":"p7","id":"nt4","src":"assets/audio/XB1-14/nt4.mp3","sec":10.824,"t":"考法：浆细胞的内质网和高尔基体发达；抗体在细胞外起作用，所以进入细胞内的病原体，要靠细胞免疫来对付。"},{"ep":"xb1-14","n":"XB1-14","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-14/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-14","n":"XB1-14","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-14/rv2.mp3","sec":9.768,"t":"浆细胞能特异性识别抗原？错，浆细胞不能识别抗原。激活B细胞需要两个信号？对。"},{"ep":"xb1-14","n":"XB1-14","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-14/rv3.mp3","sec":10.92,"t":"记忆B细胞能直接产生大量抗体？错，要先增殖分化为浆细胞。二次免疫反应更快、更强？对。"},{"ep":"xb1-14","n":"XB1-14","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-14/rv4.mp3","sec":10.752,"t":"一个浆细胞能产生多种抗体？错，只能产生一种。抗体主要分布在细胞内？错，主要分布在血清中。"},{"ep":"xb1-14","n":"XB1-14","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-14/rv5.mp3","sec":14.856,"t":"七个考点串起来：受体识别抗原，两个信号激活B细胞，浆细胞分泌抗体，记忆细胞带来二次免疫。掌握这些，体液免疫就能稳稳拿分！我们下期再见！"},{"ep":"xb1-15","n":"XB1-15","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-15/in1.mp3","sec":9.624,"t":"同学们好！这节课梳理人教版选择性必修一第四章第二节的下半部分——细胞免疫与免疫调节网络。"},{"ep":"xb1-15","n":"XB1-15","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-15/in2.mp3","sec":8.952,"t":"高考常考细胞免疫的过程、两种免疫的协调配合，以及切除胸腺和免疫流程图这类推理题。"},{"ep":"xb1-15","n":"XB1-15","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-15/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-15","n":"XB1-15","p":1,"a":"p1","id":"cp1","src":"assets/audio/XB1-15/cp1.mp3","sec":9.096,"t":"考点一，细胞免疫的过程。病原体一旦进入细胞内部，抗体无法进入细胞，就要靠细胞免疫。"},{"ep":"xb1-15","n":"XB1-15","p":1,"a":"p1","id":"cp2","src":"assets/audio/XB1-15/cp2.mp3","sec":7.512,"t":"被病原体感染的宿主细胞，叫做靶细胞，靶细胞膜表面的某些分子会发生变化。"},{"ep":"xb1-15","n":"XB1-15","p":1,"a":"p1","id":"cp3","src":"assets/audio/XB1-15/cp3.mp3","sec":9.288,"t":"细胞毒性T细胞识别这一变化信号，开始分裂、分化，形成新的细胞毒性T细胞和记忆T细胞。"},{"ep":"xb1-15","n":"XB1-15","p":1,"a":"p1","id":"cp4","src":"assets/audio/XB1-15/cp4.mp3","sec":5.04,"t":"辅助性T细胞分泌的细胞因子，能加速这一过程。"},{"ep":"xb1-15","n":"XB1-15","p":1,"a":"p1","id":"cp5","src":"assets/audio/XB1-15/cp5.mp3","sec":8.88,"t":"新形成的细胞毒性T细胞在体液中循环，识别并接触、裂解被同样病原体感染的靶细胞。"},{"ep":"xb1-15","n":"XB1-15","p":1,"a":"p1","id":"cp6","src":"assets/audio/XB1-15/cp6.mp3","sec":10.944,"t":"易错：细胞毒性T细胞的活化，需要靶细胞的信号和细胞因子；靶细胞的裂解死亡属于细胞凋亡，不是细胞坏死。"},{"ep":"xb1-15","n":"XB1-15","p":2,"a":"p2","id":"mt1","src":"assets/audio/XB1-15/mt1.mp3","sec":6.0,"t":"考点二，记忆T细胞。细胞免疫中也会产生记忆T细胞。"},{"ep":"xb1-15","n":"XB1-15","p":2,"a":"p2","id":"mt2","src":"assets/audio/XB1-15/mt2.mp3","sec":9.456,"t":"如果再次遇到相同的抗原，记忆T细胞会立即分化为细胞毒性T细胞，迅速、高效地产生免疫反应。"},{"ep":"xb1-15","n":"XB1-15","p":2,"a":"p2","id":"mt3","src":"assets/audio/XB1-15/mt3.mp3","sec":7.632,"t":"记忆T细胞可以长期存在，这和记忆B细胞一样，是二次免疫更快、更强的原因。"},{"ep":"xb1-15","n":"XB1-15","p":2,"a":"p2","id":"mt4","src":"assets/audio/XB1-15/mt4.mp3","sec":9.384,"t":"考法：二次免疫中，新的细胞毒性T细胞主要来自记忆T细胞的分化；记忆细胞只针对同种抗原。"},{"ep":"xb1-15","n":"XB1-15","p":3,"a":"p3","id":"af1","src":"assets/audio/XB1-15/af1.mp3","sec":4.032,"t":"考点三，靶细胞裂解以后，会发生什么？"},{"ep":"xb1-15","n":"XB1-15","p":3,"a":"p3","id":"af2","src":"assets/audio/XB1-15/af2.mp3","sec":4.968,"t":"靶细胞裂解，病原体失去了藏身之所，暴露出来。"},{"ep":"xb1-15","n":"XB1-15","p":3,"a":"p3","id":"af3","src":"assets/audio/XB1-15/af3.mp3","sec":8.28,"t":"暴露出来的病原体，可以与抗体结合，或者直接被巨噬细胞等其他免疫细胞吞噬、消灭。"},{"ep":"xb1-15","n":"XB1-15","p":3,"a":"p3","id":"af4","src":"assets/audio/XB1-15/af4.mp3","sec":11.088,"t":"易错：细胞毒性T细胞只能使靶细胞裂解，它不能直接消灭病原体；清除病原体，还要靠抗体和其他免疫细胞。"},{"ep":"xb1-15","n":"XB1-15","p":4,"a":"p4","id":"hp1","src":"assets/audio/XB1-15/hp1.mp3","sec":7.704,"t":"考点四，体液免疫和细胞免疫是怎样协调配合的？关键在于辅助性T细胞。"},{"ep":"xb1-15","n":"XB1-15","p":4,"a":"p4","id":"hp2","src":"assets/audio/XB1-15/hp2.mp3","sec":10.08,"t":"在体液免疫中，辅助性T细胞提供激活B细胞的第二个信号，并分泌细胞因子，促进B细胞的分裂、分化。"},{"ep":"xb1-15","n":"XB1-15","p":4,"a":"p4","id":"hp3","src":"assets/audio/XB1-15/hp3.mp3","sec":8.184,"t":"在细胞免疫中，辅助性T细胞分泌的细胞因子，加速细胞毒性T细胞的分裂、分化。"},{"ep":"xb1-15","n":"XB1-15","p":4,"a":"p4","id":"hp4","src":"assets/audio/XB1-15/hp4.mp3","sec":6.576,"t":"所以，辅助性T细胞在体液免疫和细胞免疫中都起着关键作用。"},{"ep":"xb1-15","n":"XB1-15","p":4,"a":"p4","id":"hp5","src":"assets/audio/XB1-15/hp5.mp3","sec":9.744,"t":"考法：辅助性T细胞大量死亡，比如感染HIV，细胞免疫几乎丧失，体液免疫也大大减弱。"},{"ep":"xb1-15","n":"XB1-15","p":5,"a":"p5","id":"vr1","src":"assets/audio/XB1-15/vr1.mp3","sec":5.088,"t":"考点五，以病毒入侵为例，看两种免疫怎样配合。"},{"ep":"xb1-15","n":"XB1-15","p":5,"a":"p5","id":"vr2","src":"assets/audio/XB1-15/vr2.mp3","sec":7.8,"t":"病毒进入细胞之前，先由体液免疫发挥作用：抗体与病毒结合，阻止它的扩散。"},{"ep":"xb1-15","n":"XB1-15","p":5,"a":"p5","id":"vr3","src":"assets/audio/XB1-15/vr3.mp3","sec":8.616,"t":"病毒一旦进入细胞，就需要细胞免疫：细胞毒性T细胞使靶细胞裂解，病毒被释放出来。"},{"ep":"xb1-15","n":"XB1-15","p":5,"a":"p5","id":"vr4","src":"assets/audio/XB1-15/vr4.mp3","sec":5.952,"t":"释放出来的病毒，再与抗体结合，或者被其他免疫细胞吞噬。"},{"ep":"xb1-15","n":"XB1-15","p":5,"a":"p5","id":"vr5","src":"assets/audio/XB1-15/vr5.mp3","sec":12.936,"t":"解题方法：病原体在细胞外，靠体液免疫；在细胞内，靠细胞免疫。病毒、结核杆菌这类胞内寄生的病原体，两种免疫都需要。"},{"ep":"xb1-15","n":"XB1-15","p":6,"a":"p6","id":"nw1","src":"assets/audio/XB1-15/nw1.mp3","sec":6.96,"t":"考点六，神经系统、内分泌系统与免疫系统之间，存在着相互调节。"},{"ep":"xb1-15","n":"XB1-15","p":6,"a":"p6","id":"nw2","src":"assets/audio/XB1-15/nw2.mp3","sec":9.744,"t":"它们通过信号分子联系起来：神经系统释放神经递质，内分泌系统分泌激素，免疫系统分泌细胞因子。"},{"ep":"xb1-15","n":"XB1-15","p":6,"a":"p6","id":"nw3","src":"assets/audio/XB1-15/nw3.mp3","sec":9.72,"t":"这些信号分子都要直接与受体接触，才能发挥作用。比如免疫细胞表面，就有神经递质和激素的受体。"},{"ep":"xb1-15","n":"XB1-15","p":6,"a":"p6","id":"nw4","src":"assets/audio/XB1-15/nw4.mp3","sec":8.28,"t":"举个例子：长期精神紧张、焦虑，会通过神经系统和内分泌系统，使免疫力下降。"},{"ep":"xb1-15","n":"XB1-15","p":6,"a":"p6","id":"nw5","src":"assets/audio/XB1-15/nw5.mp3","sec":12.792,"t":"考法：神经—体液—免疫调节网络是机体维持稳态的主要调节机制；信号分子的作用方式都是直接与受体接触，受体一般是蛋白质。"},{"ep":"xb1-15","n":"XB1-15","p":7,"a":"p7","id":"og1","src":"assets/audio/XB1-15/og1.mp3","sec":8.136,"t":"考点七，切除胸腺或破坏骨髓以后，免疫能力怎样变化？这是常考的推理题。"},{"ep":"xb1-15","n":"XB1-15","p":7,"a":"p7","id":"og2","src":"assets/audio/XB1-15/og2.mp3","sec":10.848,"t":"切除胸腺：T细胞不能成熟，细胞免疫全部丧失；没有了辅助性T细胞，体液免疫也大大减弱，只保留一小部分。"},{"ep":"xb1-15","n":"XB1-15","p":7,"a":"p7","id":"og3","src":"assets/audio/XB1-15/og3.mp3","sec":8.568,"t":"破坏骨髓：造血干细胞没有了，B细胞和T细胞都无法产生，特异性免疫全部丧失。"},{"ep":"xb1-15","n":"XB1-15","p":7,"a":"p7","id":"og4","src":"assets/audio/XB1-15/og4.mp3","sec":12.456,"t":"解题方法：抓住两点。B细胞、T细胞都产生于骨髓；T细胞成熟于胸腺，而且大多数体液免疫需要辅助性T细胞参与。"},{"ep":"xb1-15","n":"XB1-15","p":7,"a":"p7","id":"og5","src":"assets/audio/XB1-15/og5.mp3","sec":10.248,"t":"易错：切除胸腺后，体液免疫不是完全丧失，因为少数抗原可以直接刺激B细胞，所以还能保留一部分。"},{"ep":"xb1-15","n":"XB1-15","p":8,"a":"p8","id":"fl1","src":"assets/audio/XB1-15/fl1.mp3","sec":9.192,"t":"考点八，怎样看懂免疫流程图？题目常给一张只有字母的流程图，让你判断细胞和物质的名称。"},{"ep":"xb1-15","n":"XB1-15","p":8,"a":"p8","id":"fl2","src":"assets/audio/XB1-15/fl2.mp3","sec":9.384,"t":"第一步，找抗体：能与抗原结合的物质是抗体，分泌它的细胞就是浆细胞，这条路线是体液免疫。"},{"ep":"xb1-15","n":"XB1-15","p":8,"a":"p8","id":"fl3","src":"assets/audio/XB1-15/fl3.mp3","sec":9.432,"t":"第二步，找靶细胞：能与靶细胞接触、使它裂解的细胞，是细胞毒性T细胞，这条路线是细胞免疫。"},{"ep":"xb1-15","n":"XB1-15","p":8,"a":"p8","id":"fl4","src":"assets/audio/XB1-15/fl4.mp3","sec":7.896,"t":"第三步，找同时连着两条路线、还能分泌细胞因子的细胞，它就是辅助性T细胞。"},{"ep":"xb1-15","n":"XB1-15","p":8,"a":"p8","id":"fl5","src":"assets/audio/XB1-15/fl5.mp3","sec":9.672,"t":"解题方法：最后看再次接触抗原的箭头，能直接分化为浆细胞或细胞毒性T细胞的，就是记忆细胞。"},{"ep":"xb1-15","n":"XB1-15","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-15/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-15","n":"XB1-15","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-15/rv2.mp3","sec":12.0,"t":"细胞毒性T细胞能直接消灭靶细胞内的病原体？错，它只使靶细胞裂解。靶细胞的裂解死亡属于细胞凋亡？对。"},{"ep":"xb1-15","n":"XB1-15","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-15/rv3.mp3","sec":12.12,"t":"辅助性T细胞在体液免疫和细胞免疫中都起作用？对。切除胸腺后体液免疫完全丧失？错，还保留一小部分。"},{"ep":"xb1-15","n":"XB1-15","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-15/rv4.mp3","sec":13.44,"t":"记忆T细胞再遇相同抗原，会立即分化为细胞毒性T细胞？对。免疫系统不受神经和内分泌系统的调节？错，三者相互调节。"},{"ep":"xb1-15","n":"XB1-15","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-15/rv5.mp3","sec":16.368,"t":"八个考点串起来：细胞毒性T细胞裂解靶细胞，辅助性T细胞连接两种免疫，三大系统靠信号分子相互调节。掌握这些，特异性免疫就能稳稳拿分！我们下期再见！"},{"ep":"xb1-16","n":"XB1-16","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-16/in1.mp3","sec":7.296,"t":"同学们好！这节课梳理人教版选择性必修一第四章第三节——免疫失调。"},{"ep":"xb1-16","n":"XB1-16","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-16/in2.mp3","sec":7.704,"t":"高考常考过敏反应的机理、自身免疫病的判断，以及艾滋病的曲线和传播途径。"},{"ep":"xb1-16","n":"XB1-16","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-16/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-16","n":"XB1-16","p":1,"a":"p1","id":"al1","src":"assets/audio/XB1-16/al1.mp3","sec":12.96,"t":"考点一，过敏反应。已免疫的机体，在再次接触相同的抗原时，有时会发生引发组织损伤或功能紊乱的免疫反应，这就是过敏反应。"},{"ep":"xb1-16","n":"XB1-16","p":1,"a":"p1","id":"al2","src":"assets/audio/XB1-16/al2.mp3","sec":7.896,"t":"引起过敏反应的抗原物质叫做过敏原，比如花粉、室内尘土、青霉素、鱼虾等。"},{"ep":"xb1-16","n":"XB1-16","p":1,"a":"p1","id":"al3","src":"assets/audio/XB1-16/al3.mp3","sec":12.48,"t":"过敏原第一次进入人体，刺激机体产生抗体。这些抗体吸附在某些细胞的表面，比如皮肤、呼吸道或消化道黏膜中的某些细胞。"},{"ep":"xb1-16","n":"XB1-16","p":1,"a":"p1","id":"al4","src":"assets/audio/XB1-16/al4.mp3","sec":9.456,"t":"当相同的过敏原再次进入机体时，就会与吸附在细胞表面的抗体结合，使这些细胞释放组胺等物质。"},{"ep":"xb1-16","n":"XB1-16","p":1,"a":"p1","id":"al5","src":"assets/audio/XB1-16/al5.mp3","sec":11.712,"t":"组胺引起毛细血管扩张、血管壁通透性增强、平滑肌收缩和腺体分泌增多，于是出现皮肤红肿、发疹、哮喘等症状。"},{"ep":"xb1-16","n":"XB1-16","p":1,"a":"p1","id":"al6","src":"assets/audio/XB1-16/al6.mp3","sec":10.896,"t":"易错：过敏反应的抗体吸附在细胞表面，而一般的抗体主要分布在血清中；第一次接触过敏原不会发生过敏反应。"},{"ep":"xb1-16","n":"XB1-16","p":2,"a":"p2","id":"ft1","src":"assets/audio/XB1-16/ft1.mp3","sec":3.528,"t":"考点二，过敏反应的特点和预防。"},{"ep":"xb1-16","n":"XB1-16","p":2,"a":"p2","id":"ft2","src":"assets/audio/XB1-16/ft2.mp3","sec":8.28,"t":"过敏反应有快慢之分：有的在接触过敏原后几分钟内就出现，有的要在几十个小时后才出现。"},{"ep":"xb1-16","n":"XB1-16","p":2,"a":"p2","id":"ft3","src":"assets/audio/XB1-16/ft3.mp3","sec":4.8,"t":"许多过敏反应还有明显的遗传倾向和个体差异。"},{"ep":"xb1-16","n":"XB1-16","p":2,"a":"p2","id":"ft4","src":"assets/audio/XB1-16/ft4.mp3","sec":6.528,"t":"预防过敏反应的主要措施，是找出过敏原，并且尽量避免再次接触。"},{"ep":"xb1-16","n":"XB1-16","p":2,"a":"p2","id":"ft5","src":"assets/audio/XB1-16/ft5.mp3","sec":7.704,"t":"考法：过敏反应是免疫功能过强，属于免疫防御功能异常，不是免疫功能不足。"},{"ep":"xb1-16","n":"XB1-16","p":3,"a":"p3","id":"au1","src":"assets/audio/XB1-16/au1.mp3","sec":11.592,"t":"考点三，自身免疫病。免疫系统对自身成分发生反应，对组织和器官造成损伤并出现症状，就叫做自身免疫病。"},{"ep":"xb1-16","n":"XB1-16","p":3,"a":"p3","id":"au2","src":"assets/audio/XB1-16/au2.mp3","sec":6.216,"t":"常见的有风湿性心脏病、类风湿关节炎和系统性红斑狼疮。"},{"ep":"xb1-16","n":"XB1-16","p":3,"a":"p3","id":"au3","src":"assets/audio/XB1-16/au3.mp3","sec":16.296,"t":"以风湿性心脏病为例：某种链球菌表面的一种抗原分子，与心脏瓣膜上的一种物质结构十分相似。感染这种链球菌后，产生的抗体在攻击链球菌的同时，也会攻击心脏瓣膜。"},{"ep":"xb1-16","n":"XB1-16","p":3,"a":"p3","id":"au4","src":"assets/audio/XB1-16/au4.mp3","sec":9.408,"t":"易错：自身免疫病是免疫功能过强、“敌我不分”，属于免疫自稳功能异常；治疗时常用免疫抑制剂。"},{"ep":"xb1-16","n":"XB1-16","p":4,"a":"p4","id":"df1","src":"assets/audio/XB1-16/df1.mp3","sec":6.864,"t":"考点四，免疫缺陷病，是由机体免疫功能不足或缺乏而引起的疾病。"},{"ep":"xb1-16","n":"XB1-16","p":4,"a":"p4","id":"df2","src":"assets/audio/XB1-16/df2.mp3","sec":8.88,"t":"一类是由于遗传而生来就有免疫缺陷的，叫做先天性免疫缺陷病，比如重症联合免疫缺陷病。"},{"ep":"xb1-16","n":"XB1-16","p":4,"a":"p4","id":"df3","src":"assets/audio/XB1-16/df3.mp3","sec":8.04,"t":"另一类是由疾病和其他因素引起的，叫做获得性免疫缺陷病，最典型的就是艾滋病。"},{"ep":"xb1-16","n":"XB1-16","p":4,"a":"p4","id":"df4","src":"assets/audio/XB1-16/df4.mp3","sec":11.952,"t":"考法：免疫缺陷病是免疫功能不足，患者容易反复感染，甚至发生恶性肿瘤，和过敏反应、自身免疫病的“过强”正好相反。"},{"ep":"xb1-16","n":"XB1-16","p":5,"a":"p5","id":"hv1","src":"assets/audio/XB1-16/hv1.mp3","sec":9.312,"t":"考点五，艾滋病，全称获得性免疫缺陷综合征，由人类免疫缺陷病毒，也就是HIV引起。"},{"ep":"xb1-16","n":"XB1-16","p":5,"a":"p5","id":"hv2","src":"assets/audio/XB1-16/hv2.mp3","sec":12.6,"t":"HIV是RNA病毒，它能识别并结合辅助性T细胞表面的受体，进入细胞，经逆转录合成DNA，整合到宿主细胞的染色体上。"},{"ep":"xb1-16","n":"XB1-16","p":5,"a":"p5","id":"hv3","src":"assets/audio/XB1-16/hv3.mp3","sec":11.424,"t":"看曲线：HIV刚侵入时浓度迅速上升；随后免疫系统摧毁大多数HIV，HIV浓度下降，T细胞数量回升。"},{"ep":"xb1-16","n":"XB1-16","p":5,"a":"p5","id":"hv4","src":"assets/audio/XB1-16/hv4.mp3","sec":10.296,"t":"但HIV不能被完全清除。经过几年的潜伏期，HIV浓度逐渐升高，辅助性T细胞数量持续下降。"},{"ep":"xb1-16","n":"XB1-16","p":5,"a":"p5","id":"hv5","src":"assets/audio/XB1-16/hv5.mp3","sec":8.352,"t":"最后，患者的免疫功能几乎全部丧失，各种感染或恶性肿瘤乘虚而入，导致死亡。"},{"ep":"xb1-16","n":"XB1-16","p":5,"a":"p5","id":"hv6","src":"assets/audio/XB1-16/hv6.mp3","sec":14.304,"t":"解题方法：曲线分三段。初期HIV先升后降；潜伏期HIV缓慢上升，T细胞缓慢下降；后期HIV迅速上升，T细胞降到很低。"},{"ep":"xb1-16","n":"XB1-16","p":6,"a":"p6","id":"sp1","src":"assets/audio/XB1-16/sp1.mp3","sec":3.792,"t":"考点六，艾滋病的传播途径与预防。"},{"ep":"xb1-16","n":"XB1-16","p":6,"a":"p6","id":"sp2","src":"assets/audio/XB1-16/sp2.mp3","sec":11.088,"t":"HIV主要存在于感染者的血液、精液、乳汁等中，传播途径主要有三条：性接触传播、血液传播和母婴传播。"},{"ep":"xb1-16","n":"XB1-16","p":6,"a":"p6","id":"sp3","src":"assets/audio/XB1-16/sp3.mp3","sec":5.712,"t":"与感染者握手、拥抱、共同进餐，一般不会传染艾滋病。"},{"ep":"xb1-16","n":"XB1-16","p":6,"a":"p6","id":"sp4","src":"assets/audio/XB1-16/sp4.mp3","sec":10.416,"t":"预防：洁身自爱，不共用注射器、牙刷和剃须刀，输血要严格检测；对感染者要关心和帮助，不歧视。"},{"ep":"xb1-16","n":"XB1-16","p":6,"a":"p6","id":"sp5","src":"assets/audio/XB1-16/sp5.mp3","sec":10.536,"t":"易错：艾滋病患者的直接死因，往往是免疫功能丧失后发生的严重感染或恶性肿瘤，而不是HIV本身。"},{"ep":"xb1-16","n":"XB1-16","p":7,"a":"p7","id":"cm1","src":"assets/audio/XB1-16/cm1.mp3","sec":4.2,"t":"考点七，把三类免疫失调放在一起比较。"},{"ep":"xb1-16","n":"XB1-16","p":7,"a":"p7","id":"cm2","src":"assets/audio/XB1-16/cm2.mp3","sec":6.936,"t":"过敏反应：免疫功能过强，针对外来的过敏原，属于免疫防御功能异常。"},{"ep":"xb1-16","n":"XB1-16","p":7,"a":"p7","id":"cm3","src":"assets/audio/XB1-16/cm3.mp3","sec":7.536,"t":"自身免疫病：免疫功能过强，攻击自身的组织和器官，属于免疫自稳功能异常。"},{"ep":"xb1-16","n":"XB1-16","p":7,"a":"p7","id":"cm4","src":"assets/audio/XB1-16/cm4.mp3","sec":5.064,"t":"免疫缺陷病：免疫功能不足或缺乏，比如艾滋病。"},{"ep":"xb1-16","n":"XB1-16","p":7,"a":"p7","id":"cm5","src":"assets/audio/XB1-16/cm5.mp3","sec":9.504,"t":"解题方法：先问“免疫功能是过强还是不足”，再问“针对的是外来物质还是自身成分”，两步就能判断。"},{"ep":"xb1-16","n":"XB1-16","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-16/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-16","n":"XB1-16","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-16/rv2.mp3","sec":12.528,"t":"第一次接触过敏原就会发生过敏反应？错，再次接触相同过敏原时才发生。过敏反应中的抗体吸附在某些细胞表面？对。"},{"ep":"xb1-16","n":"XB1-16","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-16/rv3.mp3","sec":10.92,"t":"风湿性心脏病属于自身免疫病？对。HIV主要侵染细胞毒性T细胞？错，主要侵染辅助性T细胞。"},{"ep":"xb1-16","n":"XB1-16","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-16/rv4.mp3","sec":10.056,"t":"握手、共同进餐会传播艾滋病？错。过敏反应和自身免疫病都是免疫功能过强？对。"},{"ep":"xb1-16","n":"XB1-16","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-16/rv5.mp3","sec":15.048,"t":"七个考点串起来：过敏反应和自身免疫病是过强，免疫缺陷病是不足，艾滋病看曲线和传播途径。掌握这些，免疫失调就能稳稳拿分！我们下期再见！"},{"ep":"xb1-17","n":"XB1-17","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-17/in1.mp3","sec":7.488,"t":"同学们好！这节课梳理人教版选择性必修一第四章第四节——免疫学的应用。"},{"ep":"xb1-17","n":"XB1-17","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-17/in2.mp3","sec":9.936,"t":"这一节联系生活实际，高考常考疫苗的原理、免疫预防与免疫治疗的区别，以及抗原检测和抗体检测。"},{"ep":"xb1-17","n":"XB1-17","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-17/in3.mp3","sec":5.448,"t":"我们按五个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-17","n":"XB1-17","p":1,"a":"p1","id":"vc1","src":"assets/audio/XB1-17/vc1.mp3","sec":12.744,"t":"考点一，疫苗。疫苗通常是用灭活的或减毒的病原体制成的生物制品。图中是1796年，琴纳为男孩接种牛痘，预防天花。"},{"ep":"xb1-17","n":"XB1-17","p":1,"a":"p1","id":"vc2","src":"assets/audio/XB1-17/vc2.mp3","sec":8.28,"t":"疫苗保留了病原体的抗原性，但不会使人患病。接种后，人体产生抗体和记忆细胞。"},{"ep":"xb1-17","n":"XB1-17","p":1,"a":"p1","id":"vc3","src":"assets/audio/XB1-17/vc3.mp3","sec":8.52,"t":"当真正的病原体侵入时，记忆细胞迅速增殖、分化，发生二次免疫，从而起到预防作用。"},{"ep":"xb1-17","n":"XB1-17","p":1,"a":"p1","id":"vc4","src":"assets/audio/XB1-17/vc4.mp3","sec":9.744,"t":"为什么有的疫苗要多次接种？因为再次接种能刺激机体产生更多的抗体和记忆细胞，增强免疫效果。"},{"ep":"xb1-17","n":"XB1-17","p":1,"a":"p1","id":"vc5","src":"assets/audio/XB1-17/vc5.mp3","sec":10.608,"t":"易错：疫苗相当于抗原，不是抗体；两次接种的间隔太短，前一次产生的抗体会与疫苗结合，反而影响效果。"},{"ep":"xb1-17","n":"XB1-17","p":2,"a":"p2","id":"tr1","src":"assets/audio/XB1-17/tr1.mp3","sec":3.48,"t":"考点二，免疫预防与免疫治疗。"},{"ep":"xb1-17","n":"XB1-17","p":2,"a":"p2","id":"tr2","src":"assets/audio/XB1-17/tr2.mp3","sec":7.608,"t":"免疫预防是在患病前接种疫苗，让机体主动产生抗体和记忆细胞，作用持久。"},{"ep":"xb1-17","n":"XB1-17","p":2,"a":"p2","id":"tr3","src":"assets/audio/XB1-17/tr3.mp3","sec":10.296,"t":"免疫治疗是在患病后，输入抗体、细胞因子等，增强机体的免疫功能；也可以使用免疫抑制剂，降低免疫功能。"},{"ep":"xb1-17","n":"XB1-17","p":2,"a":"p2","id":"tr4","src":"assets/audio/XB1-17/tr4.mp3","sec":11.208,"t":"比如被毒蛇咬伤后注射抗蛇毒血清，其中的抗体能立即起作用，但会逐渐被分解，维持时间短，也不产生记忆细胞。"},{"ep":"xb1-17","n":"XB1-17","p":2,"a":"p2","id":"tr5","src":"assets/audio/XB1-17/tr5.mp3","sec":13.752,"t":"解题方法：注射的是抗原，也就是疫苗，属于预防，见效慢、持续久；注射的是抗体，见效快、持续短。被狂犬咬伤后，要两种都注射。"},{"ep":"xb1-17","n":"XB1-17","p":3,"a":"p3","id":"tp1","src":"assets/audio/XB1-17/tp1.mp3","sec":6.384,"t":"考点三，器官移植。器官移植面临的最大问题是免疫排斥。"},{"ep":"xb1-17","n":"XB1-17","p":3,"a":"p3","id":"tp2","src":"assets/audio/XB1-17/tp2.mp3","sec":10.488,"t":"每个人的细胞表面都带有一组与别人不同的蛋白质，叫做组织相容性抗原，也叫人类白细胞抗原，简称HLA。"},{"ep":"xb1-17","n":"XB1-17","p":3,"a":"p3","id":"tp3","src":"assets/audio/XB1-17/tp3.mp3","sec":9.624,"t":"如果供者与受者的HLA差别很大，受者的免疫系统，主要是细胞毒性T细胞，就会攻击移植的器官。"},{"ep":"xb1-17","n":"XB1-17","p":3,"a":"p3","id":"tp4","src":"assets/audio/XB1-17/tp4.mp3","sec":11.976,"t":"所以器官移植的成败，主要取决于供者与受者的HLA是否一致或相近。术后还要长期使用免疫抑制剂，提高成活率。"},{"ep":"xb1-17","n":"XB1-17","p":3,"a":"p3","id":"tp5","src":"assets/audio/XB1-17/tp5.mp3","sec":12.264,"t":"易错：使用免疫抑制剂后，病人免疫力降低，容易感染。用患者自己的干细胞培养出组织、器官进行移植，可以避免免疫排斥。"},{"ep":"xb1-17","n":"XB1-17","p":4,"a":"p4","id":"dt1","src":"assets/audio/XB1-17/dt1.mp3","sec":6.408,"t":"考点四，免疫诊断。以病毒感染为例，常用三种检测方法。"},{"ep":"xb1-17","n":"XB1-17","p":4,"a":"p4","id":"dt2","src":"assets/audio/XB1-17/dt2.mp3","sec":9.288,"t":"核酸检测：检测病毒的遗传物质，比如用PCR技术扩增，灵敏、准确，可用于早期诊断。"},{"ep":"xb1-17","n":"XB1-17","p":4,"a":"p4","id":"dt3","src":"assets/audio/XB1-17/dt3.mp3","sec":10.8,"t":"抗原检测：利用抗原和抗体特异性结合的原理，用已知的抗体去检测样本中的病毒蛋白质，速度快、操作简便。"},{"ep":"xb1-17","n":"XB1-17","p":4,"a":"p4","id":"dt4","src":"assets/audio/XB1-17/dt4.mp3","sec":13.152,"t":"抗体检测：用已知的抗原去检测血液中的抗体。抗体要在感染后一段时间才产生，阳性可能是正在或曾经感染，也可能是接种过疫苗。"},{"ep":"xb1-17","n":"XB1-17","p":4,"a":"p4","id":"dt5","src":"assets/audio/XB1-17/dt5.mp3","sec":9.624,"t":"易错：抗原检测用的是抗体，抗体检测用的是抗原，不要弄反；抗体检测阳性，不一定正在感染。"},{"ep":"xb1-17","n":"XB1-17","p":5,"a":"p5","id":"ex1","src":"assets/audio/XB1-17/ex1.mp3","sec":5.88,"t":"考点五，免疫学的实验题。最常见的是验证疫苗的效果。"},{"ep":"xb1-17","n":"XB1-17","p":5,"a":"p5","id":"ex2","src":"assets/audio/XB1-17/ex2.mp3","sec":12.864,"t":"选取生理状况相同的小鼠，分成两组。实验组接种疫苗；对照组注射等量的生理盐水。一段时间后，两组都注射同种病原体。"},{"ep":"xb1-17","n":"XB1-17","p":5,"a":"p5","id":"ex3","src":"assets/audio/XB1-17/ex3.mp3","sec":10.32,"t":"结果：实验组小鼠正常存活，对照组小鼠患病甚至死亡，说明疫苗能使小鼠获得对这种病原体的免疫力。"},{"ep":"xb1-17","n":"XB1-17","p":5,"a":"p5","id":"ex4","src":"assets/audio/XB1-17/ex4.mp3","sec":10.008,"t":"如果要证明起作用的是抗体，可以把已免疫小鼠的血清注射给未免疫的小鼠，再注射病原体，看它能否存活。"},{"ep":"xb1-17","n":"XB1-17","p":5,"a":"p5","id":"ex5","src":"assets/audio/XB1-17/ex5.mp3","sec":11.256,"t":"解题方法：找准自变量，比如是否接种疫苗；对照组要注射等量的生理盐水；因变量可以是存活率，也可以是抗体含量。"},{"ep":"xb1-17","n":"XB1-17","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-17/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-17","n":"XB1-17","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-17/rv2.mp3","sec":9.264,"t":"疫苗相当于抗体？错，疫苗相当于抗原。注射抗体见效快，但维持时间短？对。"},{"ep":"xb1-17","n":"XB1-17","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-17/rv3.mp3","sec":13.488,"t":"器官移植的成败，主要取决于HLA是否一致或相近？对。使用免疫抑制剂后病人免疫力增强？错，免疫力降低，容易感染。"},{"ep":"xb1-17","n":"XB1-17","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-17/rv4.mp3","sec":14.856,"t":"抗原检测是用已知抗原检测样本？错，是用已知抗体检测样本中的抗原。抗体检测阳性说明正在感染？错，也可能是曾经感染或接种过疫苗。"},{"ep":"xb1-17","n":"XB1-17","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-17/rv5.mp3","sec":17.04,"t":"五个考点串起来：疫苗是抗原，用来预防；抗体见效快，用来治疗；器官移植看HLA；检测时分清抗原和抗体。到这里，第四章免疫调节就全部讲完了！我们下期再见！"},{"ep":"xb1-18","n":"XB1-18","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-18/in1.mp3","sec":8.4,"t":"同学们好！这节课梳理人教版选择性必修一第五章第一节的上半部分——生长素的发现。"},{"ep":"xb1-18","n":"XB1-18","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-18/in2.mp3","sec":8.952,"t":"这一节是经典的实验史，高考常考每个实验的结论、向光性的原因，以及判断胚芽鞘怎样生长。"},{"ep":"xb1-18","n":"XB1-18","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-18/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-18","n":"XB1-18","p":1,"a":"p1","id":"dw1","src":"assets/audio/XB1-18/dw1.mp3","sec":10.176,"t":"考点一，达尔文的实验。照片中就是达尔文，1880年，他用禾本科植物的胚芽鞘研究植物的向光性。"},{"ep":"xb1-18","n":"XB1-18","p":1,"a":"p1","id":"dw2","src":"assets/audio/XB1-18/dw2.mp3","sec":7.872,"t":"单侧光照射，胚芽鞘向光弯曲生长；去掉尖端，胚芽鞘既不生长，也不弯曲。"},{"ep":"xb1-18","n":"XB1-18","p":1,"a":"p1","id":"dw3","src":"assets/audio/XB1-18/dw3.mp3","sec":8.88,"t":"用锡箔罩住尖端，胚芽鞘直立生长；用锡箔罩住尖端下面的一段，胚芽鞘仍然向光弯曲。"},{"ep":"xb1-18","n":"XB1-18","p":1,"a":"p1","id":"dw4","src":"assets/audio/XB1-18/dw4.mp3","sec":12.888,"t":"结论：感受光刺激的部位是尖端，向光弯曲的部位是尖端下面的一段。达尔文推想，尖端受单侧光刺激后，向下面传递了某种“影响”。"},{"ep":"xb1-18","n":"XB1-18","p":1,"a":"p1","id":"dw5","src":"assets/audio/XB1-18/dw5.mp3","sec":7.872,"t":"易错：达尔文只提出了“某种影响”，并没有发现生长素；实验中锡箔的作用是遮光。"},{"ep":"xb1-18","n":"XB1-18","p":2,"a":"p2","id":"bj1","src":"assets/audio/XB1-18/bj1.mp3","sec":10.176,"t":"考点二，鲍森·詹森的实验。他切下胚芽鞘的尖端，在尖端和下部之间隔一块琼脂片，再用单侧光照射。"},{"ep":"xb1-18","n":"XB1-18","p":2,"a":"p2","id":"bj2","src":"assets/audio/XB1-18/bj2.mp3","sec":3.504,"t":"结果胚芽鞘仍然向光弯曲生长。"},{"ep":"xb1-18","n":"XB1-18","p":2,"a":"p2","id":"bj3","src":"assets/audio/XB1-18/bj3.mp3","sec":6.12,"t":"结论：胚芽鞘尖端产生的影响可以透过琼脂片传递给下部。"},{"ep":"xb1-18","n":"XB1-18","p":2,"a":"p2","id":"bj4","src":"assets/audio/XB1-18/bj4.mp3","sec":11.808,"t":"考法：如果把琼脂片换成云母片，影响不能透过，胚芽鞘就不生长也不弯曲。琼脂片能让化学物质通过，云母片不能。"},{"ep":"xb1-18","n":"XB1-18","p":3,"a":"p3","id":"by1","src":"assets/audio/XB1-18/by1.mp3","sec":8.664,"t":"考点三，拜尔的实验。他切下胚芽鞘的尖端，把尖端放在切面的一侧，在黑暗中培养。"},{"ep":"xb1-18","n":"XB1-18","p":3,"a":"p3","id":"by2","src":"assets/audio/XB1-18/by2.mp3","sec":4.056,"t":"结果胚芽鞘向放尖端的对侧弯曲生长。"},{"ep":"xb1-18","n":"XB1-18","p":3,"a":"p3","id":"by3","src":"assets/audio/XB1-18/by3.mp3","sec":7.776,"t":"结论：胚芽鞘的弯曲生长，是因为尖端产生的影响在其下部分布不均匀造成的。"},{"ep":"xb1-18","n":"XB1-18","p":3,"a":"p3","id":"by4","src":"assets/audio/XB1-18/by4.mp3","sec":9.096,"t":"易错：拜尔的实验要在黑暗中进行，目的是排除光照的影响，说明弯曲不是光直接造成的。"},{"ep":"xb1-18","n":"XB1-18","p":4,"a":"p4","id":"wt1","src":"assets/audio/XB1-18/wt1.mp3","sec":8.256,"t":"考点四，温特的实验。他把切下的胚芽鞘尖端放在琼脂块上，几小时后移去尖端。"},{"ep":"xb1-18","n":"XB1-18","p":4,"a":"p4","id":"wt2","src":"assets/audio/XB1-18/wt2.mp3","sec":7.296,"t":"把这块琼脂块放在去掉尖端的胚芽鞘切面的一侧，胚芽鞘向对侧弯曲生长。"},{"ep":"xb1-18","n":"XB1-18","p":4,"a":"p4","id":"wt3","src":"assets/audio/XB1-18/wt3.mp3","sec":6.648,"t":"对照组放没有接触过尖端的空白琼脂块，胚芽鞘既不生长也不弯曲。"},{"ep":"xb1-18","n":"XB1-18","p":4,"a":"p4","id":"wt4","src":"assets/audio/XB1-18/wt4.mp3","sec":8.232,"t":"结论：胚芽鞘的弯曲生长，确实是由一种化学物质引起的，温特把它命名为生长素。"},{"ep":"xb1-18","n":"XB1-18","p":4,"a":"p4","id":"wt5","src":"assets/audio/XB1-18/wt5.mp3","sec":9.696,"t":"考法：空白琼脂块的作用是排除琼脂块本身的影响；温特没有提取出生长素，也不知道它的化学本质。"},{"ep":"xb1-18","n":"XB1-18","p":5,"a":"p5","id":"ia1","src":"assets/audio/XB1-18/ia1.mp3","sec":11.256,"t":"考点五，生长素的化学本质。1934年，科学家从人尿中分离出这种物质，确认它是吲哚乙酸，简称IAA。"},{"ep":"xb1-18","n":"XB1-18","p":5,"a":"p5","id":"ia2","src":"assets/audio/XB1-18/ia2.mp3","sec":7.152,"t":"后来又发现，植物体内具有生长素效应的物质，还有苯乙酸和吲哚丁酸等。"},{"ep":"xb1-18","n":"XB1-18","p":5,"a":"p5","id":"ia3","src":"assets/audio/XB1-18/ia3.mp3","sec":8.928,"t":"易错：生长素的化学本质是吲哚乙酸，不是蛋白质；它由色氨酸经过一系列反应转变而来。"},{"ep":"xb1-18","n":"XB1-18","p":6,"a":"p6","id":"pt1","src":"assets/audio/XB1-18/pt1.mp3","sec":3.192,"t":"考点六，植物向光性的原因。"},{"ep":"xb1-18","n":"XB1-18","p":6,"a":"p6","id":"pt2","src":"assets/audio/XB1-18/pt2.mp3","sec":7.392,"t":"在单侧光照射下，尖端的生长素由向光侧向背光侧运输，这叫横向运输。"},{"ep":"xb1-18","n":"XB1-18","p":6,"a":"p6","id":"pt3","src":"assets/audio/XB1-18/pt3.mp3","sec":6.864,"t":"生长素再向下运输到尖端下部，结果背光侧的生长素多于向光侧。"},{"ep":"xb1-18","n":"XB1-18","p":6,"a":"p6","id":"pt4","src":"assets/audio/XB1-18/pt4.mp3","sec":6.576,"t":"背光侧细胞生长得快，向光侧生长得慢，于是植物弯向光源生长。"},{"ep":"xb1-18","n":"XB1-18","p":6,"a":"p6","id":"pt5","src":"assets/audio/XB1-18/pt5.mp3","sec":11.304,"t":"易错：单侧光改变的是生长素的分布，不影响生长素的合成；感光和横向运输发生在尖端，弯曲发生在尖端下部。"},{"ep":"xb1-18","n":"XB1-18","p":7,"a":"p7","id":"cc1","src":"assets/audio/XB1-18/cc1.mp3","sec":11.424,"t":"考点七，植物激素的概念：由植物体内产生，能从产生部位运送到作用部位，对植物的生长发育有显著影响的微量有机物。"},{"ep":"xb1-18","n":"XB1-18","p":7,"a":"p7","id":"cc2","src":"assets/audio/XB1-18/cc2.mp3","sec":7.8,"t":"生长素、赤霉素、细胞分裂素、脱落酸、乙烯和油菜素内酯，都是植物激素。"},{"ep":"xb1-18","n":"XB1-18","p":7,"a":"p7","id":"cc3","src":"assets/audio/XB1-18/cc3.mp3","sec":7.488,"t":"和动物激素不同，植物没有专门的分泌器官，植物激素由一定部位的细胞产生。"},{"ep":"xb1-18","n":"XB1-18","p":7,"a":"p7","id":"cc4","src":"assets/audio/XB1-18/cc4.mp3","sec":10.272,"t":"易错：人工合成的2,4-D、萘乙酸等不是植物激素，而是植物生长调节剂，因为它们不是植物体内产生的。"},{"ep":"xb1-18","n":"XB1-18","p":8,"a":"p8","id":"jg1","src":"assets/audio/XB1-18/jg1.mp3","sec":6.024,"t":"考点八，判断胚芽鞘的生长和弯曲，是这一节最常考的题型。"},{"ep":"xb1-18","n":"XB1-18","p":8,"a":"p8","id":"jg2","src":"assets/audio/XB1-18/jg2.mp3","sec":9.552,"t":"第一步，看有没有生长素来源：有尖端，或者有含生长素的琼脂块，才能生长；都没有，就不生长。"},{"ep":"xb1-18","n":"XB1-18","p":8,"a":"p8","id":"jg3","src":"assets/audio/XB1-18/jg3.mp3","sec":10.104,"t":"第二步，看生长素分布是否均匀：分布均匀就直立生长；不均匀就弯曲生长，弯向生长素少的一侧。"},{"ep":"xb1-18","n":"XB1-18","p":8,"a":"p8","id":"jg4","src":"assets/audio/XB1-18/jg4.mp3","sec":8.616,"t":"尖端罩上锡箔，或者云母片纵向插入尖端阻断横向运输，即使有单侧光，也直立生长。"},{"ep":"xb1-18","n":"XB1-18","p":8,"a":"p8","id":"jg5","src":"assets/audio/XB1-18/jg5.mp3","sec":12.36,"t":"含生长素的琼脂块不能感光：放在切面一侧，不论有没有光，都弯向对侧。胚芽鞘匀速旋转，各侧受光均匀，也直立生长。"},{"ep":"xb1-18","n":"XB1-18","p":8,"a":"p8","id":"jg6","src":"assets/audio/XB1-18/jg6.mp3","sec":11.352,"t":"解题方法：一看有没有生长素来源，二看有没有尖端感光，三看生长素能不能横向运输。三步走完，结果就出来了。"},{"ep":"xb1-18","n":"XB1-18","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-18/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-18","n":"XB1-18","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-18/rv2.mp3","sec":11.688,"t":"达尔文的实验发现了生长素？错，他只提出尖端产生某种影响。感受单侧光刺激的部位是胚芽鞘尖端？对。"},{"ep":"xb1-18","n":"XB1-18","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-18/rv3.mp3","sec":10.392,"t":"拜尔的实验要在单侧光下进行？错，要在黑暗中进行。温特命名了生长素，但没有提取出它？对。"},{"ep":"xb1-18","n":"XB1-18","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-18/rv4.mp3","sec":12.36,"t":"单侧光使向光侧生长素合成减少？错，改变的是生长素的分布。2,4-D属于植物激素？错，属于植物生长调节剂。"},{"ep":"xb1-18","n":"XB1-18","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-18/rv5.mp3","sec":16.896,"t":"八个考点串起来：四个经典实验一步步找到生长素，向光性靠生长素分布不均，判断题先找生长素来源，再看分布。掌握这些，生长素的发现就能稳稳拿分！我们下期再见！"},{"ep":"xb1-19","n":"XB1-19","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-19/in1.mp3","sec":10.104,"t":"同学们好！这节课梳理人教版选择性必修一第五章第一节的下半部分——生长素的合成、运输与生理作用。"},{"ep":"xb1-19","n":"XB1-19","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-19/in2.mp3","sec":9.792,"t":"这一部分是植物激素的重中之重，高考常考极性运输、生长素浓度曲线、顶端优势和根的向地性。"},{"ep":"xb1-19","n":"XB1-19","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-19/in3.mp3","sec":5.52,"t":"我们按九个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-19","n":"XB1-19","p":1,"a":"p1","id":"sy1","src":"assets/audio/XB1-19/sy1.mp3","sec":8.28,"t":"考点一，生长素的合成。生长素主要的合成部位是芽、幼嫩的叶和发育中的种子。"},{"ep":"xb1-19","n":"XB1-19","p":1,"a":"p1","id":"sy2","src":"assets/audio/XB1-19/sy2.mp3","sec":5.376,"t":"在这些部位，色氨酸经过一系列反应，转变成生长素。"},{"ep":"xb1-19","n":"XB1-19","p":1,"a":"p1","id":"sy3","src":"assets/audio/XB1-19/sy3.mp3","sec":10.728,"t":"易错：生长素是由色氨酸转变来的小分子有机物，不是蛋白质；记合成部位，抓住“幼嫩”和“发育中”两个关键词。"},{"ep":"xb1-19","n":"XB1-19","p":2,"a":"p2","id":"tp1","src":"assets/audio/XB1-19/tp1.mp3","sec":3.792,"t":"考点二，生长素的运输，分三种。"},{"ep":"xb1-19","n":"XB1-19","p":2,"a":"p2","id":"tp2","src":"assets/audio/XB1-19/tp2.mp3","sec":13.296,"t":"极性运输：在胚芽鞘、芽、幼叶和幼根中，生长素只能从形态学上端运输到形态学下端，不能反过来。极性运输是一种主动运输。"},{"ep":"xb1-19","n":"XB1-19","p":2,"a":"p2","id":"tp3","src":"assets/audio/XB1-19/tp3.mp3","sec":7.416,"t":"非极性运输：在成熟组织中，生长素可以通过输导组织进行非极性运输。"},{"ep":"xb1-19","n":"XB1-19","p":2,"a":"p2","id":"tp4","src":"assets/audio/XB1-19/tp4.mp3","sec":8.304,"t":"横向运输：在尖端等部位，单侧光、重力等单一方向的刺激，会使生长素横向运输。"},{"ep":"xb1-19","n":"XB1-19","p":2,"a":"p2","id":"tp5","src":"assets/audio/XB1-19/tp5.mp3","sec":15.168,"t":"易错：极性运输的方向由形态学上下端决定，与重力无关。考法：缺氧或者加入呼吸抑制剂，极性运输会受到抑制，因为它是主动运输，需要消耗能量。"},{"ep":"xb1-19","n":"XB1-19","p":3,"a":"p3","id":"ds1","src":"assets/audio/XB1-19/ds1.mp3","sec":10.128,"t":"考点三，生长素的分布。生长素在植物体各器官中都有分布，但相对集中地分布在生长旺盛的部位。"},{"ep":"xb1-19","n":"XB1-19","p":3,"a":"p3","id":"ds2","src":"assets/audio/XB1-19/ds2.mp3","sec":7.176,"t":"比如胚芽鞘、芽和根尖的分生组织、形成层、发育中的种子和果实等处。"},{"ep":"xb1-19","n":"XB1-19","p":3,"a":"p3","id":"ds3","src":"assets/audio/XB1-19/ds3.mp3","sec":10.296,"t":"考法：生长素合成多和分布多的部位大体一致，都是幼嫩、生长旺盛的部位；衰老的组织中生长素较少。"},{"ep":"xb1-19","n":"XB1-19","p":4,"a":"p4","id":"ac1","src":"assets/audio/XB1-19/ac1.mp3","sec":3.144,"t":"考点四，生长素的生理作用。"},{"ep":"xb1-19","n":"XB1-19","p":4,"a":"p4","id":"ac2","src":"assets/audio/XB1-19/ac2.mp3","sec":6.192,"t":"在细胞水平上，生长素能促进细胞伸长生长，诱导细胞分化。"},{"ep":"xb1-19","n":"XB1-19","p":4,"a":"p4","id":"ac3","src":"assets/audio/XB1-19/ac3.mp3","sec":9.528,"t":"在器官水平上，它影响器官的生长和发育，比如促进侧根和不定根的发生，影响花、叶和果实的发育。"},{"ep":"xb1-19","n":"XB1-19","p":4,"a":"p4","id":"ac4","src":"assets/audio/XB1-19/ac4.mp3","sec":10.464,"t":"生长素发挥作用时，首先要与细胞内的生长素受体特异性结合，引发一系列信号转导，进而诱导特定基因的表达。"},{"ep":"xb1-19","n":"XB1-19","p":4,"a":"p4","id":"ac5","src":"assets/audio/XB1-19/ac5.mp3","sec":9.552,"t":"易错：生长素是传递信息的信号分子，它不直接参与细胞代谢，既不提供能量，也不起催化作用。"},{"ep":"xb1-19","n":"XB1-19","p":5,"a":"p5","id":"ft1","src":"assets/audio/XB1-19/ft1.mp3","sec":8.976,"t":"考点五，生长素作用的特点：一般情况下，浓度较低时促进生长，浓度过高时抑制生长。"},{"ep":"xb1-19","n":"XB1-19","p":5,"a":"p5","id":"ft2","src":"assets/audio/XB1-19/ft2.mp3","sec":9.072,"t":"看曲线：横轴是生长素浓度，纵轴是促进或抑制的程度，曲线最高点对应的是最适浓度。"},{"ep":"xb1-19","n":"XB1-19","p":5,"a":"p5","id":"ft3","src":"assets/audio/XB1-19/ft3.mp3","sec":5.28,"t":"在最适浓度两侧，存在促进效果相同的两个不同浓度。"},{"ep":"xb1-19","n":"XB1-19","p":5,"a":"p5","id":"ft4","src":"assets/audio/XB1-19/ft4.mp3","sec":7.752,"t":"曲线与横轴的交点，表示这个浓度既不促进也不抑制；超过这个浓度，才是抑制。"},{"ep":"xb1-19","n":"XB1-19","p":5,"a":"p5","id":"ft5","src":"assets/audio/XB1-19/ft5.mp3","sec":9.216,"t":"易错：曲线在横轴以上都是促进，最适浓度右侧下降的那一段，只是促进作用减弱，不是抑制。"},{"ep":"xb1-19","n":"XB1-19","p":6,"a":"p6","id":"or1","src":"assets/audio/XB1-19/or1.mp3","sec":7.92,"t":"考点六，不同器官对生长素的敏感程度不同：根最敏感，芽其次，茎最不敏感。"},{"ep":"xb1-19","n":"XB1-19","p":6,"a":"p6","id":"or2","src":"assets/audio/XB1-19/or2.mp3","sec":10.776,"t":"看三条曲线：根的最适浓度约为10的-10次方 mol/L，芽约为10的-8次方，茎约为10的-4次方。"},{"ep":"xb1-19","n":"XB1-19","p":6,"a":"p6","id":"or3","src":"assets/audio/XB1-19/or3.mp3","sec":9.648,"t":"同一浓度，比如10的-6次方 mol/L的生长素，促进茎的生长，对芽几乎没有影响，却抑制根的生长。"},{"ep":"xb1-19","n":"XB1-19","p":6,"a":"p6","id":"or4","src":"assets/audio/XB1-19/or4.mp3","sec":12.888,"t":"考法：同一浓度对不同器官的作用可能不同；另外，双子叶植物一般比单子叶植物对生长素更敏感，幼嫩的细胞比衰老的细胞更敏感。"},{"ep":"xb1-19","n":"XB1-19","p":7,"a":"p7","id":"ap1","src":"assets/audio/XB1-19/ap1.mp3","sec":6.648,"t":"考点七，顶端优势：顶芽优先生长，侧芽生长受到抑制的现象。"},{"ep":"xb1-19","n":"XB1-19","p":7,"a":"p7","id":"ap2","src":"assets/audio/XB1-19/ap2.mp3","sec":11.184,"t":"原因：顶芽产生的生长素向下运输，在侧芽部位积累。侧芽对生长素比较敏感，浓度过高，生长受到抑制。"},{"ep":"xb1-19","n":"XB1-19","p":7,"a":"p7","id":"ap3","src":"assets/audio/XB1-19/ap3.mp3","sec":10.032,"t":"而顶芽处生长素浓度较低，促进生长。所以顶端优势体现了生长素低浓度促进、高浓度抑制的特点。"},{"ep":"xb1-19","n":"XB1-19","p":7,"a":"p7","id":"ap4","src":"assets/audio/XB1-19/ap4.mp3","sec":9.624,"t":"应用：去掉顶芽，侧芽处的生长素浓度降低，侧芽就能发育成侧枝，比如棉花打顶、果树修剪。"},{"ep":"xb1-19","n":"XB1-19","p":7,"a":"p7","id":"ap5","src":"assets/audio/XB1-19/ap5.mp3","sec":12.912,"t":"易错：离顶芽越近的侧芽，生长素浓度越高，受抑制越明显。去掉顶芽后，如果在切口处放含生长素的琼脂块，侧芽仍然受抑制。"},{"ep":"xb1-19","n":"XB1-19","p":8,"a":"p8","id":"gv1","src":"assets/audio/XB1-19/gv1.mp3","sec":6.264,"t":"考点八，把幼苗横放，根会向地弯曲生长，茎会背地弯曲生长。"},{"ep":"xb1-19","n":"XB1-19","p":8,"a":"p8","id":"gv2","src":"assets/audio/XB1-19/gv2.mp3","sec":8.232,"t":"原因：在重力作用下，生长素发生横向运输，近地侧的生长素浓度高于远地侧。"},{"ep":"xb1-19","n":"XB1-19","p":8,"a":"p8","id":"gv3","src":"assets/audio/XB1-19/gv3.mp3","sec":8.016,"t":"茎对生长素不敏感：近地侧浓度高，促进作用更强，生长得快，所以茎背地生长。"},{"ep":"xb1-19","n":"XB1-19","p":8,"a":"p8","id":"gv4","src":"assets/audio/XB1-19/gv4.mp3","sec":9.504,"t":"根对生长素敏感：近地侧浓度高，反而抑制生长；远地侧浓度低，促进生长，所以根向地生长。"},{"ep":"xb1-19","n":"XB1-19","p":8,"a":"p8","id":"gv5","src":"assets/audio/XB1-19/gv5.mp3","sec":10.824,"t":"考法：根的向地性和顶端优势，都体现了低浓度促进、高浓度抑制；而茎的背地性和向光性，只体现了促进作用。"},{"ep":"xb1-19","n":"XB1-19","p":9,"a":"p9","id":"pl1","src":"assets/audio/XB1-19/pl1.mp3","sec":4.416,"t":"考点九，实验：验证生长素的极性运输。"},{"ep":"xb1-19","n":"XB1-19","p":9,"a":"p9","id":"pl2","src":"assets/audio/XB1-19/pl2.mp3","sec":12.552,"t":"取一段胚芽鞘，在形态学上端放含生长素的琼脂块，形态学下端放空白琼脂块。一段时间后，下面的琼脂块中含有生长素。"},{"ep":"xb1-19","n":"XB1-19","p":9,"a":"p9","id":"pl3","src":"assets/audio/XB1-19/pl3.mp3","sec":10.704,"t":"把这段胚芽鞘倒过来，让形态学下端朝上，在上面放含生长素的琼脂块，结果下面的琼脂块中检测不到生长素。"},{"ep":"xb1-19","n":"XB1-19","p":9,"a":"p9","id":"pl4","src":"assets/audio/XB1-19/pl4.mp3","sec":5.64,"t":"结论：生长素只能从形态学上端运输到形态学下端。"},{"ep":"xb1-19","n":"XB1-19","p":9,"a":"p9","id":"pl5","src":"assets/audio/XB1-19/pl5.mp3","sec":12.456,"t":"解题方法：检测琼脂块中有没有生长素，可以把它放在去尖端的胚芽鞘一侧，看是否弯曲；必须设置倒置的一组，才能排除重力的影响。"},{"ep":"xb1-19","n":"XB1-19","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-19/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-19","n":"XB1-19","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-19/rv2.mp3","sec":12.576,"t":"生长素主要在芽、幼嫩的叶和发育中的种子中合成？对。极性运输的方向由重力决定？错，由形态学上、下端决定。"},{"ep":"xb1-19","n":"XB1-19","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-19/rv3.mp3","sec":12.432,"t":"最适浓度右侧曲线下降的一段表示抑制？错，只要在横轴以上，就是促进作用减弱。根对生长素的敏感程度大于茎？对。"},{"ep":"xb1-19","n":"XB1-19","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-19/rv4.mp3","sec":10.224,"t":"茎的背地性体现了高浓度抑制生长？错，只体现促进作用。去掉顶芽可以解除顶端优势？对。"},{"ep":"xb1-19","n":"XB1-19","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-19/rv5.mp3","sec":16.752,"t":"九个考点串起来：芽和幼叶合成生长素，极性运输从上到下，作用特点是低促进、高抑制，根最敏感、茎最不敏感。掌握这些，生长素就能稳稳拿分！我们下期再见！"},{"ep":"xb1-20","n":"XB1-20","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-20/in1.mp3","sec":7.512,"t":"同学们好！这节课梳理人教版选择性必修一第五章第二节——其他植物激素。"},{"ep":"xb1-20","n":"XB1-20","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-20/in2.mp3","sec":8.496,"t":"高考常考各种激素的合成部位和作用、激素之间的相互作用，以及激素含量变化的曲线。"},{"ep":"xb1-20","n":"XB1-20","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-20/in3.mp3","sec":5.544,"t":"我们按十个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-20","n":"XB1-20","p":1,"a":"p1","id":"ga1","src":"assets/audio/XB1-20/ga1.mp3","sec":7.032,"t":"考点一，赤霉素。合成部位主要是幼芽、幼根和未成熟的种子。"},{"ep":"xb1-20","n":"XB1-20","p":1,"a":"p1","id":"ga2","src":"assets/audio/XB1-20/ga2.mp3","sec":10.392,"t":"主要作用：促进细胞伸长，从而引起植株增高；促进细胞分裂与分化；促进种子萌发、开花和果实发育。"},{"ep":"xb1-20","n":"XB1-20","p":1,"a":"p1","id":"ga3","src":"assets/audio/XB1-20/ga3.mp3","sec":8.28,"t":"水稻恶苗病就和赤霉素有关：赤霉菌产生的赤霉素使植株疯长，结实率反而降低。"},{"ep":"xb1-20","n":"XB1-20","p":1,"a":"p1","id":"ga4","src":"assets/audio/XB1-20/ga4.mp3","sec":7.224,"t":"易错：赤霉菌产生的赤霉素不是植物激素，因为它不是植物体内产生的。"},{"ep":"xb1-20","n":"XB1-20","p":2,"a":"p2","id":"ck1","src":"assets/audio/XB1-20/ck1.mp3","sec":5.184,"t":"考点二，细胞分裂素。合成部位主要是根尖。"},{"ep":"xb1-20","n":"XB1-20","p":2,"a":"p2","id":"ck2","src":"assets/audio/XB1-20/ck2.mp3","sec":6.984,"t":"主要作用：促进细胞分裂；促进芽的分化、侧枝发育和叶绿素合成。"},{"ep":"xb1-20","n":"XB1-20","p":2,"a":"p2","id":"ck3","src":"assets/audio/XB1-20/ck3.mp3","sec":9.6,"t":"考法：细胞分裂素能延缓叶片衰老，可用于蔬菜保鲜；它和生长素在促进细胞分裂上是协同的。"},{"ep":"xb1-20","n":"XB1-20","p":3,"a":"p3","id":"ab1","src":"assets/audio/XB1-20/ab1.mp3","sec":5.688,"t":"考点三，脱落酸。合成部位是根冠、萎蔫的叶片等。"},{"ep":"xb1-20","n":"XB1-20","p":3,"a":"p3","id":"ab2","src":"assets/audio/XB1-20/ab2.mp3","sec":8.928,"t":"主要作用：抑制细胞分裂；促进气孔关闭；促进叶和果实的衰老和脱落；维持种子休眠。"},{"ep":"xb1-20","n":"XB1-20","p":3,"a":"p3","id":"ab3","src":"assets/audio/XB1-20/ab3.mp3","sec":8.4,"t":"干旱时，叶片中的脱落酸增多，气孔关闭，减少水分散失，帮助植物度过不良环境。"},{"ep":"xb1-20","n":"XB1-20","p":3,"a":"p3","id":"ab4","src":"assets/audio/XB1-20/ab4.mp3","sec":12.432,"t":"考法：小麦即将成熟时，如果经历干热后又遇大雨，种子容易在穗上发芽，原因是高温使脱落酸降解，种子的休眠被解除。"},{"ep":"xb1-20","n":"XB1-20","p":4,"a":"p4","id":"et1","src":"assets/audio/XB1-20/et1.mp3","sec":7.008,"t":"考点四，乙烯。植物体各个部位都能合成乙烯，它是一种气体激素。"},{"ep":"xb1-20","n":"XB1-20","p":4,"a":"p4","id":"et2","src":"assets/audio/XB1-20/et2.mp3","sec":6.888,"t":"主要作用：促进果实成熟；促进开花；促进叶、花、果实脱落。"},{"ep":"xb1-20","n":"XB1-20","p":4,"a":"p4","id":"et3","src":"assets/audio/XB1-20/et3.mp3","sec":9.264,"t":"生活中，把成熟的苹果和青香蕉放在一起，香蕉会熟得更快，就是成熟苹果释放的乙烯在起作用。"},{"ep":"xb1-20","n":"XB1-20","p":4,"a":"p4","id":"et4","src":"assets/audio/XB1-20/et4.mp3","sec":10.584,"t":"易错：乙烯促进果实成熟，生长素促进果实发育，二者不要混淆；培育无子番茄用的是生长素，不是乙烯。"},{"ep":"xb1-20","n":"XB1-20","p":5,"a":"p5","id":"br1","src":"assets/audio/XB1-20/br1.mp3","sec":5.688,"t":"考点五，油菜素内酯，已被正式认定为第六类植物激素。"},{"ep":"xb1-20","n":"XB1-20","p":5,"a":"p5","id":"br2","src":"assets/audio/XB1-20/br2.mp3","sec":6.72,"t":"它能促进茎、叶细胞的扩展和分裂，促进花粉管生长和种子萌发等。"},{"ep":"xb1-20","n":"XB1-20","p":5,"a":"p5","id":"br3","src":"assets/audio/XB1-20/br3.mp3","sec":9.144,"t":"考法：六类植物激素中，脱落酸以抑制作用为主；常考的“促进脱落”有两种激素：脱落酸和乙烯。"},{"ep":"xb1-20","n":"XB1-20","p":6,"a":"p6","id":"sn1","src":"assets/audio/XB1-20/sn1.mp3","sec":5.064,"t":"考点六，激素之间的相互作用：协同与相抗衡。"},{"ep":"xb1-20","n":"XB1-20","p":6,"a":"p6","id":"sn2","src":"assets/audio/XB1-20/sn2.mp3","sec":11.856,"t":"协同：在促进细胞分裂方面，生长素主要促进细胞核的分裂，细胞分裂素主要促进细胞质的分裂，二者表现为协同作用。"},{"ep":"xb1-20","n":"XB1-20","p":6,"a":"p6","id":"sn3","src":"assets/audio/XB1-20/sn3.mp3","sec":8.832,"t":"相抗衡：在调节种子萌发方面，赤霉素促进萌发，脱落酸抑制萌发，二者作用相抗衡。"},{"ep":"xb1-20","n":"XB1-20","p":6,"a":"p6","id":"sn4","src":"assets/audio/XB1-20/sn4.mp3","sec":10.008,"t":"解题方法：先锁定同一生理过程，再看两种激素的作用方向是否一致：一致是协同，相反是相抗衡。"},{"ep":"xb1-20","n":"XB1-20","p":7,"a":"p7","id":"ae1","src":"assets/audio/XB1-20/ae1.mp3","sec":3.48,"t":"考点七，生长素和乙烯的关系。"},{"ep":"xb1-20","n":"XB1-20","p":7,"a":"p7","id":"ae2","src":"assets/audio/XB1-20/ae2.mp3","sec":5.304,"t":"当生长素浓度升高到一定值时，就会促进乙烯的合成；"},{"ep":"xb1-20","n":"XB1-20","p":7,"a":"p7","id":"ae3","src":"assets/audio/XB1-20/ae3.mp3","sec":4.944,"t":"而乙烯含量的升高，反过来又会抑制生长素的作用。"},{"ep":"xb1-20","n":"XB1-20","p":7,"a":"p7","id":"ae4","src":"assets/audio/XB1-20/ae4.mp3","sec":10.896,"t":"考法：这可以解释高浓度生长素为什么会抑制生长；题目常给出两种激素含量变化的曲线，让你分析这种相互作用。"},{"ep":"xb1-20","n":"XB1-20","p":8,"a":"p8","id":"rt1","src":"assets/audio/XB1-20/rt1.mp3","sec":8.448,"t":"考点八，决定器官生长发育的，往往不是某种激素的绝对含量，而是不同激素的相对含量。"},{"ep":"xb1-20","n":"XB1-20","p":8,"a":"p8","id":"rt2","src":"assets/audio/XB1-20/rt2.mp3","sec":10.056,"t":"例如，黄瓜茎端脱落酸与赤霉素的比值较高，有利于分化形成雌花；比值较低，有利于分化形成雄花。"},{"ep":"xb1-20","n":"XB1-20","p":8,"a":"p8","id":"rt3","src":"assets/audio/XB1-20/rt3.mp3","sec":9.72,"t":"又如植物组织培养中，生长素与细胞分裂素的比值高时，有利于根的分化；比值低时，有利于芽的分化。"},{"ep":"xb1-20","n":"XB1-20","p":8,"a":"p8","id":"rt4","src":"assets/audio/XB1-20/rt4.mp3","sec":6.384,"t":"易错：抓住“生长素多，生根”“细胞分裂素多，生芽”，不要记反。"},{"ep":"xb1-20","n":"XB1-20","p":9,"a":"p9","id":"od1","src":"assets/audio/XB1-20/od1.mp3","sec":4.032,"t":"考点九，激素调节在时间上的顺序性。"},{"ep":"xb1-20","n":"XB1-20","p":9,"a":"p9","id":"od2","src":"assets/audio/XB1-20/od2.mp3","sec":11.28,"t":"在猕猴桃果实的发育过程中，细胞分裂素、生长素、赤霉素、脱落酸等激素的含量，会像接力一样，按照次序出现高峰。"},{"ep":"xb1-20","n":"XB1-20","p":9,"a":"p9","id":"od3","src":"assets/audio/XB1-20/od3.mp3","sec":8.928,"t":"这说明植物的生长发育，不是受单一激素的调节，而是多种激素相互作用、共同调节的结果。"},{"ep":"xb1-20","n":"XB1-20","p":9,"a":"p9","id":"od4","src":"assets/audio/XB1-20/od4.mp3","sec":11.28,"t":"考法：看激素含量的曲线，先找各激素出现高峰的时间，再联系那个时期果实是在细胞分裂、细胞伸长还是成熟。"},{"ep":"xb1-20","n":"XB1-20","p":10,"a":"p10","id":"gn1","src":"assets/audio/XB1-20/gn1.mp3","sec":4.56,"t":"考点十，植物激素调节与基因表达的关系。"},{"ep":"xb1-20","n":"XB1-20","p":10,"a":"p10","id":"gn2","src":"assets/audio/XB1-20/gn2.mp3","sec":7.8,"t":"植物生长发育的调控，是由基因表达调控、激素调节和环境因素调节共同完成的。"},{"ep":"xb1-20","n":"XB1-20","p":10,"a":"p10","id":"gn3","src":"assets/audio/XB1-20/gn3.mp3","sec":11.256,"t":"激素作为信息分子，会影响细胞的基因表达；同时，激素的产生和分布，是基因表达调控的结果，也受环境因素的影响。"},{"ep":"xb1-20","n":"XB1-20","p":10,"a":"p10","id":"gn4","src":"assets/audio/XB1-20/gn4.mp3","sec":14.4,"t":"易错：植物激素不直接参与细胞代谢，而是给细胞传达调节代谢的信息；植物生长发育从根本上说，是基因组在一定时间和空间上程序性表达的结果。"},{"ep":"xb1-20","n":"XB1-20","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-20/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-20","n":"XB1-20","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-20/rv2.mp3","sec":10.416,"t":"赤霉素能促进细胞伸长，引起植株增高？对。脱落酸能促进种子萌发？错，它维持种子休眠。"},{"ep":"xb1-20","n":"XB1-20","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-20/rv3.mp3","sec":11.952,"t":"乙烯只在成熟的果实中合成？错，植物体各个部位都能合成。赤霉素与脱落酸在种子萌发方面作用相抗衡？对。"},{"ep":"xb1-20","n":"XB1-20","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-20/rv4.mp3","sec":13.512,"t":"生长素与细胞分裂素比值高时有利于芽的分化？错，有利于根的分化。植物激素直接参与细胞代谢？错，只传递调节代谢的信息。"},{"ep":"xb1-20","n":"XB1-20","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-20/rv5.mp3","sec":16.104,"t":"十个考点串起来：五类激素记准合成部位和作用，再看协同、相抗衡、相对含量和顺序性，最后回到基因表达。掌握这些，植物激素就能稳稳拿分！我们下期再见！"},{"ep":"xb1-21","n":"XB1-21","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-21/in1.mp3","sec":8.448,"t":"同学们好！这节课梳理人教版选择性必修一第五章第三节——植物生长调节剂的应用。"},{"ep":"xb1-21","n":"XB1-21","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-21/in2.mp3","sec":7.728,"t":"高考常考调节剂的应用实例、探究插条生根的最适浓度，以及2,4-D除草的原理。"},{"ep":"xb1-21","n":"XB1-21","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-21/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-21","n":"XB1-21","p":1,"a":"p1","id":"cp1","src":"assets/audio/XB1-21/cp1.mp3","sec":8.688,"t":"考点一，植物生长调节剂，是由人工合成的，对植物的生长、发育有调节作用的化学物质。"},{"ep":"xb1-21","n":"XB1-21","p":1,"a":"p1","id":"cp2","src":"assets/audio/XB1-21/cp2.mp3","sec":4.848,"t":"它的优点是原料广泛、容易合成、效果稳定。"},{"ep":"xb1-21","n":"XB1-21","p":1,"a":"p1","id":"cp3","src":"assets/audio/XB1-21/cp3.mp3","sec":7.896,"t":"效果为什么稳定？因为植物体内往往缺乏分解它的酶，它在体内作用的时间更长。"},{"ep":"xb1-21","n":"XB1-21","p":1,"a":"p1","id":"cp4","src":"assets/audio/XB1-21/cp4.mp3","sec":11.976,"t":"易错：植物生长调节剂是人工合成的，不属于植物激素。判断时看来源：植物体内产生的是激素，人工合成的是调节剂。"},{"ep":"xb1-21","n":"XB1-21","p":2,"a":"p2","id":"ty1","src":"assets/audio/XB1-21/ty1.mp3","sec":5.904,"t":"考点二，从分子结构来看，植物生长调节剂主要有两大类。"},{"ep":"xb1-21","n":"XB1-21","p":2,"a":"p2","id":"ty2","src":"assets/audio/XB1-21/ty2.mp3","sec":6.168,"t":"一类分子结构和生理效应都与植物激素类似，比如吲哚丁酸。"},{"ep":"xb1-21","n":"XB1-21","p":2,"a":"p2","id":"ty3","src":"assets/audio/XB1-21/ty3.mp3","sec":9.48,"t":"另一类分子结构与植物激素完全不同，但具有与植物激素类似的生理效应，比如α-萘乙酸和矮壮素。"},{"ep":"xb1-21","n":"XB1-21","p":2,"a":"p2","id":"ty4","src":"assets/audio/XB1-21/ty4.mp3","sec":7.944,"t":"考法：判断是不是植物生长调节剂，看来源；判断属于哪一类，才看分子结构。"},{"ep":"xb1-21","n":"XB1-21","p":3,"a":"p3","id":"ap1","src":"assets/audio/XB1-21/ap1.mp3","sec":2.52,"t":"考点三，应用实例。"},{"ep":"xb1-21","n":"XB1-21","p":3,"a":"p3","id":"ap2","src":"assets/audio/XB1-21/ap2.mp3","sec":5.904,"t":"用乙烯利催熟凤梨、香蕉等水果，乙烯利能释放出乙烯。"},{"ep":"xb1-21","n":"XB1-21","p":3,"a":"p3","id":"ap3","src":"assets/audio/XB1-21/ap3.mp3","sec":8.832,"t":"用赤霉素处理大麦种子，使它无须发芽就能产生α-淀粉酶，用于啤酒生产，降低成本。"},{"ep":"xb1-21","n":"XB1-21","p":3,"a":"p3","id":"ap4","src":"assets/audio/XB1-21/ap4.mp3","sec":7.944,"t":"用膨大剂使水果长势加快、个头变大，但可能影响口感，也不利于长时间储存。"},{"ep":"xb1-21","n":"XB1-21","p":3,"a":"p3","id":"ap5","src":"assets/audio/XB1-21/ap5.mp3","sec":11.016,"t":"考法：常问调节剂模拟了哪种激素：乙烯利对应乙烯，膨大剂多为细胞分裂素类，萘乙酸、2,4-D对应生长素。"},{"ep":"xb1-21","n":"XB1-21","p":4,"a":"p4","id":"ca1","src":"assets/audio/XB1-21/ca1.mp3","sec":4.944,"t":"考点四，施用植物生长调节剂，要注意哪些问题？"},{"ep":"xb1-21","n":"XB1-21","p":4,"a":"p4","id":"ca2","src":"assets/audio/XB1-21/ca2.mp3","sec":8.16,"t":"要选择恰当的种类，考虑施用的浓度、时间和部位，以及植物的生理状态和气候条件等。"},{"ep":"xb1-21","n":"XB1-21","p":4,"a":"p4","id":"ca3","src":"assets/audio/XB1-21/ca3.mp3","sec":5.352,"t":"还要注意调节剂的残留，以及对人体健康和环境的影响。"},{"ep":"xb1-21","n":"XB1-21","p":4,"a":"p4","id":"ca4","src":"assets/audio/XB1-21/ca4.mp3","sec":10.536,"t":"易错：调节剂不是越多越好，浓度不当会适得其反。比如赤霉素过量，水稻会疯长，结实率反而降低。"},{"ep":"xb1-21","n":"XB1-21","p":5,"a":"p5","id":"ex1","src":"assets/audio/XB1-21/ex1.mp3","sec":6.936,"t":"考点五，探究实践：探索生长素类调节剂促进插条生根的最适浓度。"},{"ep":"xb1-21","n":"XB1-21","p":5,"a":"p5","id":"ex2","src":"assets/audio/XB1-21/ex2.mp3","sec":10.728,"t":"先做预实验：在较大的浓度范围内设置浓度梯度，摸索最适浓度的大致范围，避免盲目开展实验，造成浪费。"},{"ep":"xb1-21","n":"XB1-21","p":5,"a":"p5","id":"ex3","src":"assets/audio/XB1-21/ex3.mp3","sec":11.184,"t":"处理插条有两种方法：浸泡法，溶液浓度较低，处理时间较长；沾蘸法，溶液浓度较高，处理时间较短，约5秒。"},{"ep":"xb1-21","n":"XB1-21","p":5,"a":"p5","id":"ex4","src":"assets/audio/XB1-21/ex4.mp3","sec":12.264,"t":"自变量是调节剂的浓度，因变量是插条生根的数目或长度；插条的长短、芽的数量、处理时间等是无关变量，要相同且适宜。"},{"ep":"xb1-21","n":"XB1-21","p":5,"a":"p5","id":"ex5","src":"assets/audio/XB1-21/ex5.mp3","sec":10.632,"t":"易错：预实验要设置蒸馏水的空白对照；正式实验在预实验确定的范围内缩小浓度梯度，各组之间相互对照。"},{"ep":"xb1-21","n":"XB1-21","p":6,"a":"p6","id":"rs1","src":"assets/audio/XB1-21/rs1.mp3","sec":8.4,"t":"考点六，实验结果分析。以调节剂浓度为横轴、生根数为纵轴，曲线先升后降。"},{"ep":"xb1-21","n":"XB1-21","p":6,"a":"p6","id":"rs2","src":"assets/audio/XB1-21/rs2.mp3","sec":8.688,"t":"曲线最高点对应的浓度是最适浓度；在最适浓度两侧，存在两个不同浓度，生根效果相同。"},{"ep":"xb1-21","n":"XB1-21","p":6,"a":"p6","id":"rs3","src":"assets/audio/XB1-21/rs3.mp3","sec":7.656,"t":"和蒸馏水对照组比：生根数多于对照组，是促进；少于对照组，才是抑制。"},{"ep":"xb1-21","n":"XB1-21","p":6,"a":"p6","id":"rs4","src":"assets/audio/XB1-21/rs4.mp3","sec":8.664,"t":"解题方法：判断促进还是抑制，一定要和空白对照比较，不能只看曲线是上升还是下降。"},{"ep":"xb1-21","n":"XB1-21","p":7,"a":"p7","id":"hb1","src":"assets/audio/XB1-21/hb1.mp3","sec":4.512,"t":"考点七，高浓度的2,4-D可以用作除草剂。"},{"ep":"xb1-21","n":"XB1-21","p":7,"a":"p7","id":"hb2","src":"assets/audio/XB1-21/hb2.mp3","sec":14.568,"t":"双子叶植物对生长素类调节剂比单子叶植物更敏感。在单子叶作物的农田里，用一定浓度的2,4-D，能抑制甚至杀死双子叶杂草，对作物却影响较小。"},{"ep":"xb1-21","n":"XB1-21","p":7,"a":"p7","id":"hb3","src":"assets/audio/XB1-21/hb3.mp3","sec":8.832,"t":"看曲线：选择的浓度，要落在双子叶植物曲线的抑制区，同时落在单子叶植物曲线的促进区。"},{"ep":"xb1-21","n":"XB1-21","p":7,"a":"p7","id":"hb4","src":"assets/audio/XB1-21/hb4.mp3","sec":11.328,"t":"易错：除草的原理是不同植物对它的敏感程度不同；小麦田、玉米田可以用，大豆田不能用，因为大豆也是双子叶植物。"},{"ep":"xb1-21","n":"XB1-21","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-21/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-21","n":"XB1-21","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-21/rv2.mp3","sec":12.096,"t":"植物生长调节剂具有原料广泛、容易合成、效果稳定等优点？对。施用浓度越高效果越好？错，浓度要适宜。"},{"ep":"xb1-21","n":"XB1-21","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-21/rv3.mp3","sec":13.512,"t":"用赤霉素处理大麦，可使其无须发芽就产生α-淀粉酶？对。浸泡法处理插条时溶液浓度较高？错，浓度较低、时间较长。"},{"ep":"xb1-21","n":"XB1-21","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-21/rv4.mp3","sec":11.52,"t":"预实验可以为正式实验摸索条件？对。可以用2,4-D除去大豆田中的双子叶杂草？错，大豆也是双子叶植物。"},{"ep":"xb1-21","n":"XB1-21","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-21/rv5.mp3","sec":16.176,"t":"七个考点串起来：调节剂人工合成、效果稳定，应用时浓度要适宜，探究最适浓度先做预实验，判断促抑看对照。掌握这些，这一节就能稳稳拿分！我们下期再见！"},{"ep":"xb1-22","n":"XB1-22","p":0,"a":"intro","id":"in1","src":"assets/audio/XB1-22/in1.mp3","sec":9.552,"t":"同学们好！这节课梳理人教版选择性必修一第五章第四节——环境因素参与调节植物的生命活动。"},{"ep":"xb1-22","n":"XB1-22","p":0,"a":"intro","id":"in2","src":"assets/audio/XB1-22/in2.mp3","sec":11.448,"t":"这一节是选择性必修一的最后一节，高考常考光敏色素、春化作用、淀粉体—平衡石假说，以及红光和远红光的实验分析。"},{"ep":"xb1-22","n":"XB1-22","p":0,"a":"intro","id":"in3","src":"assets/audio/XB1-22/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb1-22","n":"XB1-22","p":1,"a":"p1","id":"lt1","src":"assets/audio/XB1-22/lt1.mp3","sec":8.784,"t":"考点一，光不仅为光合作用提供能量，还作为一种信号，影响、调控植物生长发育的全过程。"},{"ep":"xb1-22","n":"XB1-22","p":1,"a":"p1","id":"lt2","src":"assets/audio/XB1-22/lt2.mp3","sec":10.8,"t":"植物接受光信号的分子之一是光敏色素，它是一类蛋白质，分布在植物的各个部位，在分生组织的细胞内比较丰富。"},{"ep":"xb1-22","n":"XB1-22","p":1,"a":"p1","id":"lt3","src":"assets/audio/XB1-22/lt3.mp3","sec":16.584,"t":"光敏色素主要吸收红光和远红光。受到光照射时，光敏色素的结构发生变化，这一信息经过信息传递系统传导到细胞核内，影响特定基因的表达，从而表现出生物学效应。"},{"ep":"xb1-22","n":"XB1-22","p":1,"a":"p1","id":"lt4","src":"assets/audio/XB1-22/lt4.mp3","sec":8.952,"t":"易错：光敏色素是蛋白质，和光合色素不同；在这里，光是一种信号，而不是能量来源。"},{"ep":"xb1-22","n":"XB1-22","p":2,"a":"p2","id":"fl1","src":"assets/audio/XB1-22/fl1.mp3","sec":4.008,"t":"考点二，光对种子萌发和开花的影响。"},{"ep":"xb1-22","n":"XB1-22","p":2,"a":"p2","id":"fl2","src":"assets/audio/XB1-22/fl2.mp3","sec":6.6,"t":"有些种子需要在有光的条件下才能萌发，比如莴苣、烟草的种子。"},{"ep":"xb1-22","n":"XB1-22","p":2,"a":"p2","id":"fl3","src":"assets/audio/XB1-22/fl3.mp3","sec":9.48,"t":"很多植物的开花与昼夜长短有关：比如菊花在短日照条件下开花，而小麦在长日照条件下开花。"},{"ep":"xb1-22","n":"XB1-22","p":2,"a":"p2","id":"fl4","src":"assets/audio/XB1-22/fl4.mp3","sec":10.248,"t":"考法：生产上常用人工延长或缩短光照时间的方法，控制植物的开花时间，比如让菊花提前或推迟开花。"},{"ep":"xb1-22","n":"XB1-22","p":3,"a":"p3","id":"tp1","src":"assets/audio/XB1-22/tp1.mp3","sec":4.248,"t":"考点三，温度参与调节植物的生长发育。"},{"ep":"xb1-22","n":"XB1-22","p":3,"a":"p3","id":"tp2","src":"assets/audio/XB1-22/tp2.mp3","sec":11.664,"t":"有的植物需要经过一段时间的低温之后才能开花，这种经历低温诱导促使植物开花的作用，叫做春化作用，比如冬小麦、冬大麦。"},{"ep":"xb1-22","n":"XB1-22","p":3,"a":"p3","id":"tp3","src":"assets/audio/XB1-22/tp3.mp3","sec":13.128,"t":"树木的年轮也和温度有关：春夏季细胞分裂快、细胞体积大，形成颜色较浅的带；秋冬季细胞分裂慢、细胞体积小，形成颜色较深的带。"},{"ep":"xb1-22","n":"XB1-22","p":3,"a":"p3","id":"tp4","src":"assets/audio/XB1-22/tp4.mp3","sec":11.232,"t":"考法：冬小麦如果在春季播种，没有经历低温，就不能正常开花结实；年轮的形成，体现了温度对植物生长速度的影响。"},{"ep":"xb1-22","n":"XB1-22","p":4,"a":"p4","id":"gv1","src":"assets/audio/XB1-22/gv1.mp3","sec":10.464,"t":"考点四，重力是调节植物生长方向的重要环境因素，根的向地生长、茎的背地生长，都是在重力的调节下形成的。"},{"ep":"xb1-22","n":"XB1-22","p":4,"a":"p4","id":"gv2","src":"assets/audio/XB1-22/gv2.mp3","sec":12.384,"t":"植物的根、茎中有感受重力的物质和细胞，能将重力信号转换成运输生长素的信号，造成生长素分布不均衡，从而调节生长方向。"},{"ep":"xb1-22","n":"XB1-22","p":4,"a":"p4","id":"gv3","src":"assets/audio/XB1-22/gv3.mp3","sec":11.064,"t":"目前比较认可的是淀粉体—平衡石假说：植物对重力的感受，是通过一类富含淀粉体的细胞，也就是平衡石细胞来实现的。"},{"ep":"xb1-22","n":"XB1-22","p":4,"a":"p4","id":"gv4","src":"assets/audio/XB1-22/gv4.mp3","sec":13.44,"t":"当植物的方向发生改变，平衡石细胞中的淀粉体就会沿着重力方向沉降，引起一系列信号分子的改变，使生长素沿着重力刺激的方向不对称分布。"},{"ep":"xb1-22","n":"XB1-22","p":4,"a":"p4","id":"gv5","src":"assets/audio/XB1-22/gv5.mp3","sec":12.12,"t":"易错：重力不是直接把生长素“压”下去，而是通过平衡石细胞转换成运输生长素的信号；在太空失重的条件下，根会失去向地性。"},{"ep":"xb1-22","n":"XB1-22","p":5,"a":"p5","id":"wh1","src":"assets/audio/XB1-22/wh1.mp3","sec":3.744,"t":"考点五，植物生长发育的整体调控。"},{"ep":"xb1-22","n":"XB1-22","p":5,"a":"p5","id":"wh2","src":"assets/audio/XB1-22/wh2.mp3","sec":7.8,"t":"植物生长发育的调控，是由基因表达调控、激素调节和环境因素调节共同完成的。"},{"ep":"xb1-22","n":"XB1-22","p":5,"a":"p5","id":"wh3","src":"assets/audio/XB1-22/wh3.mp3","sec":15.288,"t":"在个体层次上，植物的生长、发育、繁殖和休眠，实际上是植物响应环境变化，调控基因表达以及激素的产生和分布，最终表现在器官和个体水平上的变化。"},{"ep":"xb1-22","n":"XB1-22","p":5,"a":"p5","id":"wh4","src":"assets/audio/XB1-22/wh4.mp3","sec":13.776,"t":"考法：三者关系常以示意图出题：环境因素既能影响激素的产生和分布，也能通过光敏色素等受体影响基因表达；激素又反过来影响基因表达。"},{"ep":"xb1-22","n":"XB1-22","p":6,"a":"p6","id":"le1","src":"assets/audio/XB1-22/le1.mp3","sec":5.736,"t":"考点六，实验分析：红光、远红光与莴苣种子的萌发。"},{"ep":"xb1-22","n":"XB1-22","p":6,"a":"p6","id":"le2","src":"assets/audio/XB1-22/le2.mp3","sec":7.488,"t":"用红光照射莴苣种子，种子萌发；红光之后再用远红光照射，种子不萌发。"},{"ep":"xb1-22","n":"XB1-22","p":6,"a":"p6","id":"le3","src":"assets/audio/XB1-22/le3.mp3","sec":11.208,"t":"红光和远红光交替照射时，种子能否萌发，取决于最后一次照射的是哪种光：最后是红光就萌发，最后是远红光就不萌发。"},{"ep":"xb1-22","n":"XB1-22","p":6,"a":"p6","id":"le4","src":"assets/audio/XB1-22/le4.mp3","sec":14.616,"t":"原因是光敏色素吸收红光和远红光后，会在两种形式之间相互转化：吸收红光后转变为有活性的形式，促进萌发；吸收远红光后又转变为无活性的形式。"},{"ep":"xb1-22","n":"XB1-22","p":6,"a":"p6","id":"le5","src":"assets/audio/XB1-22/le5.mp3","sec":9.6,"t":"解题方法：看表格中每组最后一次照射的光：以红光结尾，萌发率高；以远红光结尾，萌发率低。"},{"ep":"xb1-22","n":"XB1-22","p":"review","a":"review","id":"rv1","src":"assets/audio/XB1-22/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb1-22","n":"XB1-22","p":"review","a":"review","id":"rv2","src":"assets/audio/XB1-22/rv2.mp3","sec":11.424,"t":"光敏色素是一类蛋白质？对。光对植物的作用只是为光合作用提供能量？错，光还作为信号调控生长发育。"},{"ep":"xb1-22","n":"XB1-22","p":"review","a":"review","id":"rv3","src":"assets/audio/XB1-22/rv3.mp3","sec":11.064,"t":"冬小麦需要经历春化作用才能开花？对。年轮中颜色较深的带在春夏季形成？错，在秋冬季形成。"},{"ep":"xb1-22","n":"XB1-22","p":"review","a":"review","id":"rv4","src":"assets/audio/XB1-22/rv4.mp3","sec":12.744,"t":"太空失重时根仍能向地生长？错，失重时根失去向地性。红光、远红光交替照射，萌发取决于最后一次照射的光？对。"},{"ep":"xb1-22","n":"XB1-22","p":"review","a":"review","id":"rv5","src":"assets/audio/XB1-22/rv5.mp3","sec":18.624,"t":"六个考点串起来：光通过光敏色素传递信号，温度带来春化和年轮，重力靠平衡石细胞感受，三者和激素、基因表达共同调控植物。到这里，选择性必修一就全部梳理完了！我们下期再见！"},{"ep":"xb2-01","n":"XB2-01","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-01/in1.mp3","sec":7.752,"t":"同学们好！这节课梳理人教版选择性必修二第一章第一节——种群的数量特征。"},{"ep":"xb2-01","n":"XB2-01","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-01/in2.mp3","sec":8.88,"t":"高考常考样方法和标记重捕法的计算与误差，以及年龄结构、性别比例对种群数量的影响。"},{"ep":"xb2-01","n":"XB2-01","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-01/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-01","n":"XB2-01","p":1,"a":"p1","id":"de1","src":"assets/audio/XB2-01/de1.mp3","sec":8.424,"t":"考点一，种群密度。种群是在一定的空间范围内，同种生物所有个体形成的集合。"},{"ep":"xb2-01","n":"XB2-01","p":1,"a":"p1","id":"de2","src":"assets/audio/XB2-01/de2.mp3","sec":5.736,"t":"种群在单位面积或单位体积中的个体数，就是种群密度。"},{"ep":"xb2-01","n":"XB2-01","p":1,"a":"p1","id":"de3","src":"assets/audio/XB2-01/de3.mp3","sec":6.912,"t":"种群密度是种群最基本的数量特征，它反映了种群在一定时期的数量。"},{"ep":"xb2-01","n":"XB2-01","p":1,"a":"p1","id":"de4","src":"assets/audio/XB2-01/de4.mp3","sec":11.04,"t":"易错：判断是不是一个种群，抓住三点：同一区域、同一物种、全部个体。一个池塘中的全部鱼不是一个种群。"},{"ep":"xb2-01","n":"XB2-01","p":2,"a":"p2","id":"qd1","src":"assets/audio/XB2-01/qd1.mp3","sec":10.728,"t":"考点二，样方法。适用于植物，以及活动能力弱、活动范围小的动物，比如蚯蚓、蚜虫、跳蝻和昆虫卵。"},{"ep":"xb2-01","n":"XB2-01","p":2,"a":"p2","id":"qd2","src":"assets/audio/XB2-01/qd2.mp3","sec":7.752,"t":"取样的关键是随机取样。方形地块用五点取样法，狭长地块用等距取样法。"},{"ep":"xb2-01","n":"XB2-01","p":2,"a":"p2","id":"qd3","src":"assets/audio/XB2-01/qd3.mp3","sec":11.352,"t":"计数时，样方内的个体全部计数；压在边线上的，只计相邻两边及其夹角上的个体，也就是“计上不计下，计左不计右”。"},{"ep":"xb2-01","n":"XB2-01","p":2,"a":"p2","id":"qd4","src":"assets/audio/XB2-01/qd4.mp3","sec":5.976,"t":"最后求出各样方种群密度的平均值，作为该种群密度的估算值。"},{"ep":"xb2-01","n":"XB2-01","p":2,"a":"p2","id":"qd5","src":"assets/audio/XB2-01/qd5.mp3","sec":10.824,"t":"考法：给出样方图数个体。解题方法：先数框内，再只数上边、左边和左上角的点，不要把四条边都算上。"},{"ep":"xb2-01","n":"XB2-01","p":3,"a":"p3","id":"mk1","src":"assets/audio/XB2-01/mk1.mp3","sec":9.024,"t":"考点三，标记重捕法。适用于活动能力强、活动范围大的动物，比如田鼠、鸟类、鱼类。"},{"ep":"xb2-01","n":"XB2-01","p":3,"a":"p3","id":"mk2","src":"assets/audio/XB2-01/mk2.mp3","sec":6.24,"t":"第一次捕获并标记M只，放回后让它们与其他个体充分混合。"},{"ep":"xb2-01","n":"XB2-01","p":3,"a":"p3","id":"mk3","src":"assets/audio/XB2-01/mk3.mp3","sec":5.4,"t":"一段时间后第二次捕获n只，其中带标记的有m只。"},{"ep":"xb2-01","n":"XB2-01","p":3,"a":"p3","id":"mk4","src":"assets/audio/XB2-01/mk4.mp3","sec":10.656,"t":"按比例相等，N = M × n ÷ m。比如 M = 50、n = 40、m = 10，N 就是 200 只。"},{"ep":"xb2-01","n":"XB2-01","p":3,"a":"p3","id":"mk5","src":"assets/audio/XB2-01/mk5.mp3","sec":8.688,"t":"误差分析看 m：标记物脱落、标记个体更难被再次捕获，都会让 m 偏小，估算值偏大。"},{"ep":"xb2-01","n":"XB2-01","p":3,"a":"p3","id":"mk6","src":"assets/audio/XB2-01/mk6.mp3","sec":8.616,"t":"易错：标记后马上重捕、未充分混合，标记个体容易被捕到，m 偏大，估算值偏小。"},{"ep":"xb2-01","n":"XB2-01","p":4,"a":"p4","id":"ot1","src":"assets/audio/XB2-01/ot1.mp3","sec":7.632,"t":"考点四，其他调查方法。分布范围较小、个体较大的种群，可以逐个计数。"},{"ep":"xb2-01","n":"XB2-01","p":4,"a":"p4","id":"ot2","src":"assets/audio/XB2-01/ot2.mp3","sec":4.752,"t":"有趋光性的昆虫，可以用黑光灯诱捕的方法调查。"},{"ep":"xb2-01","n":"XB2-01","p":4,"a":"p4","id":"ot3","src":"assets/audio/XB2-01/ot3.mp3","sec":7.104,"t":"对大型、警觉性强的动物，可以用红外触发相机拍摄，比如调查东北豹。"},{"ep":"xb2-01","n":"XB2-01","p":4,"a":"p4","id":"ot4","src":"assets/audio/XB2-01/ot4.mp3","sec":4.968,"t":"还可以通过粪便中的DNA，或者动物的声音来计数。"},{"ep":"xb2-01","n":"XB2-01","p":4,"a":"p4","id":"ot5","src":"assets/audio/XB2-01/ot5.mp3","sec":10.368,"t":"考法：根据生物的特点选方法。解题方法：先问它动不动、跑多远，再看有没有趋光性、是否难以接近。"},{"ep":"xb2-01","n":"XB2-01","p":5,"a":"p5","id":"rt1","src":"assets/audio/XB2-01/rt1.mp3","sec":7.416,"t":"考点五，出生率和死亡率、迁入率和迁出率。它们直接决定种群密度。"},{"ep":"xb2-01","n":"XB2-01","p":5,"a":"p5","id":"rt2","src":"assets/audio/XB2-01/rt2.mp3","sec":7.992,"t":"出生率是单位时间内新产生的个体数目占该种群个体总数的比值；死亡率同理。"},{"ep":"xb2-01","n":"XB2-01","p":5,"a":"p5","id":"rt3","src":"assets/audio/XB2-01/rt3.mp3","sec":7.608,"t":"迁入率和迁出率，是单位时间内迁入或迁出的个体占该种群个体总数的比值。"},{"ep":"xb2-01","n":"XB2-01","p":5,"a":"p5","id":"rt4","src":"assets/audio/XB2-01/rt4.mp3","sec":7.272,"t":"出生率加迁入率，大于死亡率加迁出率，种群密度就增大，反之就减小。"},{"ep":"xb2-01","n":"XB2-01","p":5,"a":"p5","id":"rt5","src":"assets/audio/XB2-01/rt5.mp3","sec":8.88,"t":"考法：春运期间大城市人口的变化，主要取决于迁入率和迁出率，而不是出生率和死亡率。"},{"ep":"xb2-01","n":"XB2-01","p":6,"a":"p6","id":"ag1","src":"assets/audio/XB2-01/ag1.mp3","sec":6.504,"t":"考点六，年龄结构。它是一个种群中各年龄期个体数目的比例。"},{"ep":"xb2-01","n":"XB2-01","p":6,"a":"p6","id":"ag2","src":"assets/audio/XB2-01/ag2.mp3","sec":7.872,"t":"增长型：幼年个体多、老年个体少，出生率大于死亡率，种群密度会越来越大。"},{"ep":"xb2-01","n":"XB2-01","p":6,"a":"p6","id":"ag3","src":"assets/audio/XB2-01/ag3.mp3","sec":6.336,"t":"稳定型：各年龄期比例适中，种群密度在一段时间内保持稳定。"},{"ep":"xb2-01","n":"XB2-01","p":6,"a":"p6","id":"ag4","src":"assets/audio/XB2-01/ag4.mp3","sec":6.096,"t":"衰退型：幼年个体少、老年个体多，种群密度会越来越小。"},{"ep":"xb2-01","n":"XB2-01","p":6,"a":"p6","id":"ag5","src":"assets/audio/XB2-01/ag5.mp3","sec":10.848,"t":"易错：年龄结构只能预测变化趋势。稳定型的种群，数量也不一定稳定，还受气候、食物、天敌等因素影响。"},{"ep":"xb2-01","n":"XB2-01","p":7,"a":"p7","id":"sx1","src":"assets/audio/XB2-01/sx1.mp3","sec":9.288,"t":"考点七，性别比例。它是种群中雌雄个体数目的比例，通过影响出生率来影响种群密度。"},{"ep":"xb2-01","n":"XB2-01","p":7,"a":"p7","id":"sx2","src":"assets/audio/XB2-01/sx2.mp3","sec":5.4,"t":"应用：用人工合成的性引诱剂诱杀害虫的雄性个体。"},{"ep":"xb2-01","n":"XB2-01","p":7,"a":"p7","id":"sx3","src":"assets/audio/XB2-01/sx3.mp3","sec":9.312,"t":"雄虫减少，性别比例失调，许多雌虫不能完成交配，出生率降低，害虫的种群密度明显降低。"},{"ep":"xb2-01","n":"XB2-01","p":7,"a":"p7","id":"sx4","src":"assets/audio/XB2-01/sx4.mp3","sec":9.336,"t":"易错：性别比例只影响出生率，不影响死亡率；诱杀雄虫不是通过提高死亡率来降低种群密度。"},{"ep":"xb2-01","n":"XB2-01","p":8,"a":"p8","id":"rl1","src":"assets/audio/XB2-01/rl1.mp3","sec":5.928,"t":"考点八，各数量特征之间的关系。种群密度处在中心。"},{"ep":"xb2-01","n":"XB2-01","p":8,"a":"p8","id":"rl2","src":"assets/audio/XB2-01/rl2.mp3","sec":5.928,"t":"出生率、死亡率、迁入率、迁出率，直接决定种群密度。"},{"ep":"xb2-01","n":"XB2-01","p":8,"a":"p8","id":"rl3","src":"assets/audio/XB2-01/rl3.mp3","sec":6.888,"t":"年龄结构既影响出生率，又影响死亡率，可以预测种群数量的变化趋势。"},{"ep":"xb2-01","n":"XB2-01","p":8,"a":"p8","id":"rl4","src":"assets/audio/XB2-01/rl4.mp3","sec":2.928,"t":"性别比例只影响出生率。"},{"ep":"xb2-01","n":"XB2-01","p":8,"a":"p8","id":"rl5","src":"assets/audio/XB2-01/rl5.mp3","sec":11.064,"t":"解题方法：遇到概念图，先找指向种群密度的四个“率”；同时指向两个率的是年龄结构，只指向一个率的是性别比例。"},{"ep":"xb2-01","n":"XB2-01","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-01/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-01","n":"XB2-01","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-01/rv2.mp3","sec":11.832,"t":"判断一：一个池塘中的全部鱼是一个种群？错，包含多个物种。判断二：种群密度是最基本的数量特征？对。"},{"ep":"xb2-01","n":"XB2-01","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-01/rv3.mp3","sec":12.264,"t":"判断三：调查蚜虫、跳蝻的密度用标记重捕法？错，用样方法。判断四：标记物脱落会使估算值偏大？对。"},{"ep":"xb2-01","n":"XB2-01","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-01/rv4.mp3","sec":12.192,"t":"判断五：年龄结构为稳定型，数量一定稳定？错。判断六：诱杀雄虫是通过改变性别比例降低出生率？对。"},{"ep":"xb2-01","n":"XB2-01","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-01/rv5.mp3","sec":7.704,"t":"八个考点串成一条线：直接决定看四率，预测趋势看年龄。我们下期再见！"},{"ep":"xb2-02","n":"XB2-02","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-02/in1.mp3","sec":7.752,"t":"同学们好！这节课梳理人教版选择性必修二第一章第二节——种群数量的变化。"},{"ep":"xb2-02","n":"XB2-02","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-02/in2.mp3","sec":8.712,"t":"高考常考“J”形和“S”形增长曲线、K值的含义与应用，以及培养液中酵母菌数量的探究。"},{"ep":"xb2-02","n":"XB2-02","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-02/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-02","n":"XB2-02","p":1,"a":"p1","id":"md1","src":"assets/audio/XB2-02/md1.mp3","sec":9.048,"t":"考点一，建构种群增长模型的方法。数学模型是用来描述一个系统或它的性质的数学形式。"},{"ep":"xb2-02","n":"XB2-02","p":1,"a":"p1","id":"md2","src":"assets/audio/XB2-02/md2.mp3","sec":8.976,"t":"建构步骤：观察研究对象，提出问题，提出合理的假设，用数学形式表达，再检验或修正。"},{"ep":"xb2-02","n":"XB2-02","p":1,"a":"p1","id":"md3","src":"assets/audio/XB2-02/md3.mp3","sec":9.456,"t":"比如，细菌每 20 分钟分裂一次，在资源和空间无限的条件下，n 代后的数量是 2 的 n 次方。"},{"ep":"xb2-02","n":"XB2-02","p":1,"a":"p1","id":"md4","src":"assets/audio/XB2-02/md4.mp3","sec":5.304,"t":"数学公式精确，曲线图直观，两种形式各有优点。"},{"ep":"xb2-02","n":"XB2-02","p":1,"a":"p1","id":"md5","src":"assets/audio/XB2-02/md5.mp3","sec":9.336,"t":"考法：给出建模的几个步骤让你排序，或者问“资源和空间无限”属于哪一步——它属于提出合理的假设。"},{"ep":"xb2-02","n":"XB2-02","p":2,"a":"p2","id":"jc1","src":"assets/audio/XB2-02/jc1.mp3","sec":10.392,"t":"考点二，“J”形增长。条件是食物和空间条件充裕、气候适宜、没有天敌和其他竞争物种等理想条件。"},{"ep":"xb2-02","n":"XB2-02","p":2,"a":"p2","id":"jc2","src":"assets/audio/XB2-02/jc2.mp3","sec":7.968,"t":"种群的数量每年以一定的倍数增长，第 t 年的数量 = 初始数量 × λ 的 t 次方。"},{"ep":"xb2-02","n":"XB2-02","p":2,"a":"p2","id":"jc3","src":"assets/audio/XB2-02/jc3.mp3","sec":9.528,"t":"λ 表示该种群数量是前一年种群数量的倍数。λ 大于 1 且保持不变，曲线就呈“J”形。"},{"ep":"xb2-02","n":"XB2-02","p":2,"a":"p2","id":"jc4","src":"assets/audio/XB2-02/jc4.mp3","sec":11.352,"t":"易错：增长率 = λ − 1，“J”形增长的增长率保持不变；但增长速率，也就是单位时间增加的个体数，越来越大。"},{"ep":"xb2-02","n":"XB2-02","p":3,"a":"p3","id":"sc1","src":"assets/audio/XB2-02/sc1.mp3","sec":6.048,"t":"考点三，“S”形增长。自然界的资源和空间总是有限的。"},{"ep":"xb2-02","n":"XB2-02","p":3,"a":"p3","id":"sc2","src":"assets/audio/XB2-02/sc2.mp3","sec":8.376,"t":"种群密度增大，种内竞争加剧，天敌数量也会增加，于是出生率降低、死亡率升高。"},{"ep":"xb2-02","n":"XB2-02","p":3,"a":"p3","id":"sc3","src":"assets/audio/XB2-02/sc3.mp3","sec":7.632,"t":"当出生率等于死亡率时，种群停止增长，数量稳定在一定水平，曲线呈“S”形。"},{"ep":"xb2-02","n":"XB2-02","p":3,"a":"p3","id":"sc4","src":"assets/audio/XB2-02/sc4.mp3","sec":7.08,"t":"一定的环境条件所能维持的种群最大数量，叫做环境容纳量，又称K值。"},{"ep":"xb2-02","n":"XB2-02","p":3,"a":"p3","id":"sc5","src":"assets/audio/XB2-02/sc5.mp3","sec":13.152,"t":"易错：K值不是固定不变的。环境遭到破坏，K值下降；环境改善，K值上升。种群数量达到K值后，会在K值附近上下波动。"},{"ep":"xb2-02","n":"XB2-02","p":4,"a":"p4","id":"rr1","src":"assets/audio/XB2-02/rr1.mp3","sec":7.464,"t":"考点四，增长速率曲线。“S”形增长中，增长速率先增大、后减小。"},{"ep":"xb2-02","n":"XB2-02","p":4,"a":"p4","id":"rr2","src":"assets/audio/XB2-02/rr2.mp3","sec":4.296,"t":"种群数量为 K/2 时，增长速率最大。"},{"ep":"xb2-02","n":"XB2-02","p":4,"a":"p4","id":"rr3","src":"assets/audio/XB2-02/rr3.mp3","sec":4.44,"t":"种群数量达到 K值 时，增长速率为零。"},{"ep":"xb2-02","n":"XB2-02","p":4,"a":"p4","id":"rr4","src":"assets/audio/XB2-02/rr4.mp3","sec":12.912,"t":"解题方法：增长速率曲线的最高点对应 K/2，降到零的点对应 K 值。不要把增长速率最大的时刻当成数量最多的时刻。"},{"ep":"xb2-02","n":"XB2-02","p":5,"a":"p5","id":"ka1","src":"assets/audio/XB2-02/ka1.mp3","sec":5.568,"t":"考点五，K值与K/2的应用。先看渔业捕捞。"},{"ep":"xb2-02","n":"XB2-02","p":5,"a":"p5","id":"ka2","src":"assets/audio/XB2-02/ka2.mp3","sec":8.64,"t":"捕捞后，让剩余量维持在 K/2 左右，种群增长速率最快，可以持续获得较大的捕捞量。"},{"ep":"xb2-02","n":"XB2-02","p":5,"a":"p5","id":"ka3","src":"assets/audio/XB2-02/ka3.mp3","sec":10.008,"t":"再看有害生物防治，比如灭鼠：硬化地面、储藏好粮食、养殖天敌，降低K值，从根本上控制鼠害。"},{"ep":"xb2-02","n":"XB2-02","p":5,"a":"p5","id":"ka4","src":"assets/audio/XB2-02/ka4.mp3","sec":5.496,"t":"防治要越早越好，在种群数量达到 K/2 之前进行。"},{"ep":"xb2-02","n":"XB2-02","p":5,"a":"p5","id":"ka5","src":"assets/audio/XB2-02/ka5.mp3","sec":6.336,"t":"保护濒危动物，要建立自然保护区，改善栖息环境，提高K值。"},{"ep":"xb2-02","n":"XB2-02","p":5,"a":"p5","id":"ka6","src":"assets/audio/XB2-02/ka6.mp3","sec":11.28,"t":"易错：是捕捞后剩余 K/2，不是数量达到 K/2 就开始捕；灭鼠的关键是降低K值，而不是把数量控制在 K/2。"},{"ep":"xb2-02","n":"XB2-02","p":6,"a":"p6","id":"fl1","src":"assets/audio/XB2-02/fl1.mp3","sec":8.16,"t":"考点六，种群数量的波动和下降。在自然界，大多数种群的数量总是在波动中。"},{"ep":"xb2-02","n":"XB2-02","p":6,"a":"p6","id":"fl2","src":"assets/audio/XB2-02/fl2.mp3","sec":9.936,"t":"有些种群会出现周期性波动，有些则会在短时间内大量增长，比如东亚飞蝗的爆发、赤潮中藻类的激增。"},{"ep":"xb2-02","n":"XB2-02","p":6,"a":"p6","id":"fl3","src":"assets/audio/XB2-02/fl3.mp3","sec":10.08,"t":"当种群长久处于不利条件下，比如遭遇人类乱捕滥杀和栖息地破坏，种群数量会持续下降，甚至灭亡。"},{"ep":"xb2-02","n":"XB2-02","p":6,"a":"p6","id":"fl4","src":"assets/audio/XB2-02/fl4.mp3","sec":10.992,"t":"考法：种群数量的变化包括增长、波动和下降。“S”形增长达到K值后并不是一条直线，而是在K值附近波动。"},{"ep":"xb2-02","n":"XB2-02","p":7,"a":"p7","id":"ys1","src":"assets/audio/XB2-02/ys1.mp3","sec":8.616,"t":"考点七，探究培养液中酵母菌种群数量的变化。用血细胞计数板在显微镜下计数。"},{"ep":"xb2-02","n":"XB2-02","p":7,"a":"p7","id":"ys2","src":"assets/audio/XB2-02/ys2.mp3","sec":9.048,"t":"操作顺序：先盖盖玻片，再把培养液滴在盖玻片边缘，让它自行渗入，吸去多余的培养液。"},{"ep":"xb2-02","n":"XB2-02","p":7,"a":"p7","id":"ys3","src":"assets/audio/XB2-02/ys3.mp3","sec":9.816,"t":"从试管中吸取培养液前要振荡，使酵母菌分布均匀；稍等片刻，待酵母菌沉降到计数室底部再计数。"},{"ep":"xb2-02","n":"XB2-02","p":7,"a":"p7","id":"ys4","src":"assets/audio/XB2-02/ys4.mp3","sec":13.416,"t":"计数室体积为 1 mm × 1 mm × 0.1 mm，每毫升酵母菌数 = 计数室中的菌数 × 10000 × 稀释倍数。"},{"ep":"xb2-02","n":"XB2-02","p":7,"a":"p7","id":"ys5","src":"assets/audio/XB2-02/ys5.mp3","sec":10.392,"t":"易错：顺序不能反；菌体过多要稀释；本实验不需要另设对照，前后自身对照，但要重复实验取平均值。"},{"ep":"xb2-02","n":"XB2-02","p":8,"a":"p8","id":"lb1","src":"assets/audio/XB2-02/lb1.mp3","sec":7.056,"t":"考点八，λ 曲线的判读。高考常给出 λ 随时间变化的曲线。"},{"ep":"xb2-02","n":"XB2-02","p":8,"a":"p8","id":"lb2","src":"assets/audio/XB2-02/lb2.mp3","sec":8.472,"t":"λ > 1，种群数量增加；λ = 1，数量不变；λ < 1，数量减少。"},{"ep":"xb2-02","n":"XB2-02","p":8,"a":"p8","id":"lb3","src":"assets/audio/XB2-02/lb3.mp3","sec":6.696,"t":"所以，λ 虽然在下降，但只要仍大于 1，种群数量就仍在增加。"},{"ep":"xb2-02","n":"XB2-02","p":8,"a":"p8","id":"lb4","src":"assets/audio/XB2-02/lb4.mp3","sec":10.656,"t":"数量最多：λ 从大于 1 降到等于 1 的时刻；数量最少：λ 从小于 1 回升到等于 1 的时刻。"},{"ep":"xb2-02","n":"XB2-02","p":8,"a":"p8","id":"lb5","src":"assets/audio/XB2-02/lb5.mp3","sec":5.568,"t":"解题方法：看 λ 和 1 比大小，不看 λ 升还是降。"},{"ep":"xb2-02","n":"XB2-02","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-02/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-02","n":"XB2-02","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-02/rv2.mp3","sec":12.888,"t":"判断一：“J”形增长的种群，增长率保持不变？对。判断二：种群数量达到K值后就不再变化？错，在K值附近波动。"},{"ep":"xb2-02","n":"XB2-02","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-02/rv3.mp3","sec":11.568,"t":"判断三：环境条件改变，K值不会改变？错。判断四：捕捞后种群数量应维持在 K/2 左右？对。"},{"ep":"xb2-02","n":"XB2-02","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-02/rv4.mp3","sec":12.528,"t":"判断五：计数时先滴培养液，再盖盖玻片？错，先盖后滴。判断六：λ 下降时，种群数量一定减少？错。"},{"ep":"xb2-02","n":"XB2-02","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-02/rv5.mp3","sec":8.112,"t":"八个考点串成一条线：K/2 增长最快，λ 和 1 比大小。我们下期再见！"},{"ep":"xb2-03","n":"XB2-03","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-03/in1.mp3","sec":8.64,"t":"同学们好！这节课梳理人教版选择性必修二第一章第三节——影响种群数量变化的因素。"},{"ep":"xb2-03","n":"XB2-03","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-03/in2.mp3","sec":8.712,"t":"高考常考密度制约因素与非密度制约因素的区分，以及捕食者与被捕食者的数量变化曲线。"},{"ep":"xb2-03","n":"XB2-03","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-03/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-03","n":"XB2-03","p":1,"a":"p1","id":"ab1","src":"assets/audio/XB2-03/ab1.mp3","sec":6.84,"t":"考点一，非生物因素。阳光、温度、水等都会影响种群数量。"},{"ep":"xb2-03","n":"XB2-03","p":1,"a":"p1","id":"ab2","src":"assets/audio/XB2-03/ab2.mp3","sec":8.832,"t":"阳光：森林中林下植物的种群密度，主要取决于林冠层的郁闭度，也就是林下的光照强度。"},{"ep":"xb2-03","n":"XB2-03","p":1,"a":"p1","id":"ab3","src":"assets/audio/XB2-03/ab3.mp3","sec":5.736,"t":"温度：蚊类等昆虫在寒冷季节到来时一般会全部死亡。"},{"ep":"xb2-03","n":"XB2-03","p":1,"a":"p1","id":"ab4","src":"assets/audio/XB2-03/ab4.mp3","sec":10.824,"t":"水：干旱缺水会使许多植物种群的死亡率升高；但对东亚飞蝗来说，气候干旱正是种群爆发式增长的主要原因。"},{"ep":"xb2-03","n":"XB2-03","p":1,"a":"p1","id":"ab5","src":"assets/audio/XB2-03/ab5.mp3","sec":12.264,"t":"考法：非生物因素的影响往往是综合性的。春夏时节种群迅速增长，除了气温升高，日照延长、降水增多也是重要原因。"},{"ep":"xb2-03","n":"XB2-03","p":2,"a":"p2","id":"bi1","src":"assets/audio/XB2-03/bi1.mp3","sec":5.856,"t":"考点二，生物因素。分为种群内部和种群外部两类。"},{"ep":"xb2-03","n":"XB2-03","p":2,"a":"p2","id":"bi2","src":"assets/audio/XB2-03/bi2.mp3","sec":7.632,"t":"种群内部：随着种群密度增大，种内竞争加剧，从而使种群的增长受到限制。"},{"ep":"xb2-03","n":"XB2-03","p":2,"a":"p2","id":"bi3","src":"assets/audio/XB2-03/bi3.mp3","sec":7.248,"t":"种群外部：其他生物通过捕食、种间竞争、寄生等关系影响种群数量。"},{"ep":"xb2-03","n":"XB2-03","p":2,"a":"p2","id":"bi4","src":"assets/audio/XB2-03/bi4.mp3","sec":7.584,"t":"比如，病原体和寄生虫的致病力和传播速度，会随着种群密度的增加而增加。"},{"ep":"xb2-03","n":"XB2-03","p":2,"a":"p2","id":"bi5","src":"assets/audio/XB2-03/bi5.mp3","sec":9.144,"t":"易错：种内竞争是种群内部的因素，不属于种间关系；捕食、竞争、寄生才是种间关系。"},{"ep":"xb2-03","n":"XB2-03","p":3,"a":"p3","id":"dn1","src":"assets/audio/XB2-03/dn1.mp3","sec":4.68,"t":"考点三，密度制约因素与非密度制约因素。"},{"ep":"xb2-03","n":"XB2-03","p":3,"a":"p3","id":"dn2","src":"assets/audio/XB2-03/dn2.mp3","sec":8.616,"t":"密度制约因素：对种群数量的作用强度与种群密度相关，一般是食物和天敌等生物因素。"},{"ep":"xb2-03","n":"XB2-03","p":3,"a":"p3","id":"dn3","src":"assets/audio/XB2-03/dn3.mp3","sec":10.056,"t":"非密度制约因素：作用强度与种群密度无关，比如气温、干旱等气候因素，以及地震、火灾等自然灾害。"},{"ep":"xb2-03","n":"XB2-03","p":3,"a":"p3","id":"dn4","src":"assets/audio/XB2-03/dn4.mp3","sec":7.848,"t":"比如一场寒潮，不论种群密度大小，冻死的比例都差不多，所以属于非密度制约因素。"},{"ep":"xb2-03","n":"XB2-03","p":3,"a":"p3","id":"dn5","src":"assets/audio/XB2-03/dn5.mp3","sec":9.744,"t":"解题方法：问自己“种群越密，它的影响是不是越大？”是，就是密度制约；不是，就是非密度制约。"},{"ep":"xb2-03","n":"XB2-03","p":4,"a":"p4","id":"pd1","src":"assets/audio/XB2-03/pd1.mp3","sec":7.584,"t":"考点四，捕食者与被捕食者的数量变化。经典例子是北美的猞猁和雪兔。"},{"ep":"xb2-03","n":"XB2-03","p":4,"a":"p4","id":"pd2","src":"assets/audio/XB2-03/pd2.mp3","sec":7.704,"t":"雪兔增多，猞猁因食物充足而增多；猞猁增多，雪兔被大量捕食而减少。"},{"ep":"xb2-03","n":"XB2-03","p":4,"a":"p4","id":"pd3","src":"assets/audio/XB2-03/pd3.mp3","sec":8.856,"t":"雪兔减少，猞猁因食物不足而减少；猞猁减少，雪兔又会增多，两者呈现周期性波动。"},{"ep":"xb2-03","n":"XB2-03","p":4,"a":"p4","id":"pd4","src":"assets/audio/XB2-03/pd4.mp3","sec":6.24,"t":"在曲线上，被捕食者先增加先减少，捕食者后增加后减少。"},{"ep":"xb2-03","n":"XB2-03","p":4,"a":"p4","id":"pd5","src":"assets/audio/XB2-03/pd5.mp3","sec":10.416,"t":"解题方法：先增先减的是被捕食者；一般来说，被捕食者的数量多于捕食者。这种调节属于负反馈。"},{"ep":"xb2-03","n":"XB2-03","p":5,"a":"p5","id":"pr1","src":"assets/audio/XB2-03/pr1.mp3","sec":4.872,"t":"考点五，种群研究的应用之一：濒危动物的保护。"},{"ep":"xb2-03","n":"XB2-03","p":5,"a":"p5","id":"pr2","src":"assets/audio/XB2-03/pr2.mp3","sec":7.416,"t":"先调查种群的数量、年龄结构和性别比例，分析影响它们数量变化的因素。"},{"ep":"xb2-03","n":"XB2-03","p":5,"a":"p5","id":"pr3","src":"assets/audio/XB2-03/pr3.mp3","sec":8.448,"t":"例如大熊猫，主要威胁来自栖息地被破坏和碎片化，食物竹子开花枯死也会造成影响。"},{"ep":"xb2-03","n":"XB2-03","p":5,"a":"p5","id":"pr4","src":"assets/audio/XB2-03/pr4.mp3","sec":7.944,"t":"措施：建立自然保护区、建设生态廊道连通栖息地，从根本上提高环境容纳量。"},{"ep":"xb2-03","n":"XB2-03","p":5,"a":"p5","id":"pr5","src":"assets/audio/XB2-03/pr5.mp3","sec":8.856,"t":"考法：保护措施要对准影响种群数量的关键因素；提高K值是保护濒危动物的根本措施。"},{"ep":"xb2-03","n":"XB2-03","p":6,"a":"p6","id":"ps1","src":"assets/audio/XB2-03/ps1.mp3","sec":4.944,"t":"考点六，有害生物的防治和渔业资源的合理利用。"},{"ep":"xb2-03","n":"XB2-03","p":6,"a":"p6","id":"ps2","src":"assets/audio/XB2-03/ps2.mp3","sec":7.392,"t":"防治有害生物，要监测和预报种群数量的变化，在数量较少时及早防治。"},{"ep":"xb2-03","n":"XB2-03","p":6,"a":"p6","id":"ps3","src":"assets/audio/XB2-03/ps3.mp3","sec":11.832,"t":"引入天敌进行生物防治，或破坏它们的生存条件、降低环境容纳量，比如防治东亚飞蝗时兴修水利、改造飞蝗滋生地。"},{"ep":"xb2-03","n":"XB2-03","p":6,"a":"p6","id":"ps4","src":"assets/audio/XB2-03/ps4.mp3","sec":9.48,"t":"渔业上，要控制捕捞强度和网眼大小，捕捞后让种群数量保持在适当水平，让鱼群持续高产。"},{"ep":"xb2-03","n":"XB2-03","p":6,"a":"p6","id":"ps5","src":"assets/audio/XB2-03/ps5.mp3","sec":10.68,"t":"考法：网眼过小会捕捞大量幼鱼，使年龄结构变为衰退型，种群数量下降。答题要联系年龄结构和K值。"},{"ep":"xb2-03","n":"XB2-03","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-03/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-03","n":"XB2-03","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-03/rv2.mp3","sec":13.128,"t":"判断一：林下植物的种群密度主要取决于光照？对。判断二：气温、干旱属于密度制约因素？错，属于非密度制约因素。"},{"ep":"xb2-03","n":"XB2-03","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-03/rv3.mp3","sec":11.4,"t":"判断三：食物和天敌属于密度制约因素？对。判断四：先增先减的是猞猁？错，是被捕食者雪兔。"},{"ep":"xb2-03","n":"XB2-03","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-03/rv4.mp3","sec":12.168,"t":"判断五：非生物因素的影响往往是综合性的？对。判断六：干旱年份东亚飞蝗数量往往下降？错，往往爆发。"},{"ep":"xb2-03","n":"XB2-03","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-03/rv5.mp3","sec":7.632,"t":"六个考点串成一条线：先增先减是猎物，气候灾害不制约。我们下期再见！"},{"ep":"xb2-04","n":"XB2-04","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-04/in1.mp3","sec":7.296,"t":"同学们好！这节课梳理人教版选择性必修二第二章第一节——群落的结构。"},{"ep":"xb2-04","n":"XB2-04","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-04/in2.mp3","sec":10.584,"t":"高考常考种间关系的判断与曲线、群落的垂直结构和水平结构、生态位，以及土壤小动物类群丰富度的调查。"},{"ep":"xb2-04","n":"XB2-04","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-04/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-04","n":"XB2-04","p":1,"a":"p1","id":"cp1","src":"assets/audio/XB2-04/cp1.mp3","sec":10.56,"t":"考点一，群落的物种组成。在相同时间聚集在一定地域中各种生物种群的集合，叫做生物群落，简称群落。"},{"ep":"xb2-04","n":"XB2-04","p":1,"a":"p1","id":"cp2","src":"assets/audio/XB2-04/cp2.mp3","sec":6.432,"t":"群落的物种组成是区别不同群落的重要特征，也决定了群落的性质。"},{"ep":"xb2-04","n":"XB2-04","p":1,"a":"p1","id":"cp3","src":"assets/audio/XB2-04/cp3.mp3","sec":8.064,"t":"一个群落中的物种数目，称为物种丰富度。一般越靠近热带地区，物种丰富度越高。"},{"ep":"xb2-04","n":"XB2-04","p":1,"a":"p1","id":"cp4","src":"assets/audio/XB2-04/cp4.mp3","sec":12.48,"t":"易错：物种丰富度说的是物种数目的多少，不是某种生物个体数目的多少；群落包括这一地域的全部生物，动物、植物、微生物都算。"},{"ep":"xb2-04","n":"XB2-04","p":2,"a":"p2","id":"dm1","src":"assets/audio/XB2-04/dm1.mp3","sec":9.768,"t":"考点二，优势种。在群落中，有些物种数量很多，对群落中其他物种的影响很大，它们就是优势种。"},{"ep":"xb2-04","n":"XB2-04","p":2,"a":"p2","id":"dm2","src":"assets/audio/XB2-04/dm2.mp3","sec":8.16,"t":"比如森林群落中的高大乔木，决定了林下的光照和湿度，影响着林下植物和动物的生存。"},{"ep":"xb2-04","n":"XB2-04","p":2,"a":"p2","id":"dm3","src":"assets/audio/XB2-04/dm3.mp3","sec":8.952,"t":"群落中的物种组成不是固定不变的，随着时间和环境的变化，原来的优势种可能逐渐失去优势。"},{"ep":"xb2-04","n":"XB2-04","p":2,"a":"p2","id":"dm4","src":"assets/audio/XB2-04/dm4.mp3","sec":9.384,"t":"易错：优势种不只看数量多，还要看对其他物种的影响大；数量多但影响小的物种，不是优势种。"},{"ep":"xb2-04","n":"XB2-04","p":3,"a":"p3","id":"rl1","src":"assets/audio/XB2-04/rl1.mp3","sec":4.776,"t":"考点三，种间关系。高考要求掌握五种。"},{"ep":"xb2-04","n":"XB2-04","p":3,"a":"p3","id":"rl2","src":"assets/audio/XB2-04/rl2.mp3","sec":10.32,"t":"原始合作：两种生物共同生活在一起，双方都受益，但分开后各自也能独立生活，比如海葵和寄居蟹。"},{"ep":"xb2-04","n":"XB2-04","p":3,"a":"p3","id":"rl3","src":"assets/audio/XB2-04/rl3.mp3","sec":11.064,"t":"互利共生：两种生物长期共同生活在一起，相互依存，分开后至少一方不能独立生活，比如豆科植物和根瘤菌。"},{"ep":"xb2-04","n":"XB2-04","p":3,"a":"p3","id":"rl4","src":"assets/audio/XB2-04/rl4.mp3","sec":10.44,"t":"种间竞争：争夺相同的资源和空间，比如大草履虫和双小核草履虫；捕食：一种生物以另一种生物为食。"},{"ep":"xb2-04","n":"XB2-04","p":3,"a":"p3","id":"rl5","src":"assets/audio/XB2-04/rl5.mp3","sec":8.544,"t":"{寄生|brown}：一种生物从另一种生物的体内或体表摄取养分，比如蛔虫和人、噬菌体和细菌。"},{"ep":"xb2-04","n":"XB2-04","p":3,"a":"p3","id":"rl6","src":"assets/audio/XB2-04/rl6.mp3","sec":6.672,"t":"易错：原始合作和互利共生的区别，就看分开后能不能独立生活。"},{"ep":"xb2-04","n":"XB2-04","p":4,"a":"p4","id":"cv1","src":"assets/audio/XB2-04/cv1.mp3","sec":8.952,"t":"考点四，种间关系曲线。高考常给出两种生物数量随时间变化的曲线，让你判断关系。"},{"ep":"xb2-04","n":"XB2-04","p":4,"a":"p4","id":"cv2","src":"assets/audio/XB2-04/cv2.mp3","sec":5.904,"t":"互利共生：两条曲线同步变化，同增同减，“同生共死”。"},{"ep":"xb2-04","n":"XB2-04","p":4,"a":"p4","id":"cv3","src":"assets/audio/XB2-04/cv3.mp3","sec":6.576,"t":"捕食：两条曲线不同步地周期性波动，先增先减的是被捕食者。"},{"ep":"xb2-04","n":"XB2-04","p":4,"a":"p4","id":"cv4","src":"assets/audio/XB2-04/cv4.mp3","sec":7.032,"t":"种间竞争：一种数量增加，另一种减少，甚至被淘汰，呈现“此消彼长”。"},{"ep":"xb2-04","n":"XB2-04","p":4,"a":"p4","id":"cv5","src":"assets/audio/XB2-04/cv5.mp3","sec":7.152,"t":"解题方法：同步变化是互利共生，交替波动是捕食，此消彼长是竞争。"},{"ep":"xb2-04","n":"XB2-04","p":5,"a":"p5","id":"sp1","src":"assets/audio/XB2-04/sp1.mp3","sec":5.736,"t":"考点五，群落的空间结构，包括垂直结构和水平结构。"},{"ep":"xb2-04","n":"XB2-04","p":5,"a":"p5","id":"sp2","src":"assets/audio/XB2-04/sp2.mp3","sec":9.936,"t":"垂直结构：在垂直方向上，大多数群落都具有明显的分层现象。植物的分层主要与对光的利用有关。"},{"ep":"xb2-04","n":"XB2-04","p":5,"a":"p5","id":"sp3","src":"assets/audio/XB2-04/sp3.mp3","sec":7.92,"t":"植物分层为动物创造了多种多样的栖息空间和食物条件，所以动物也有分层现象。"},{"ep":"xb2-04","n":"XB2-04","p":5,"a":"p5","id":"sp4","src":"assets/audio/XB2-04/sp4.mp3","sec":9.72,"t":"水平结构：由于地形变化、土壤湿度和盐碱度的差异、光照强度不同等因素，生物常呈镶嵌分布。"},{"ep":"xb2-04","n":"XB2-04","p":5,"a":"p5","id":"sp5","src":"assets/audio/XB2-04/sp5.mp3","sec":9.768,"t":"易错：竹林中的竹子高低错落，不是群落的垂直结构，因为竹子是一个种群；空间结构是群落的特征。"},{"ep":"xb2-04","n":"XB2-04","p":6,"a":"p6","id":"ss1","src":"assets/audio/XB2-04/ss1.mp3","sec":11.256,"t":"考点六，群落的季节性。由于阳光、温度和水分等随季节而变化，群落的外貌和结构也会随之发生有规律的变化。"},{"ep":"xb2-04","n":"XB2-04","p":6,"a":"p6","id":"ss2","src":"assets/audio/XB2-04/ss2.mp3","sec":8.04,"t":"比如，一些草原植物在春季发芽开花、秋季枯黄；候鸟在不同季节迁来迁去。"},{"ep":"xb2-04","n":"XB2-04","p":6,"a":"p6","id":"ss3","src":"assets/audio/XB2-04/ss3.mp3","sec":12.624,"t":"考法：季节性是群落的特征，常和空间结构一起考。答题时说清环境因素随季节变化，导致群落的外貌和结构随之变化。"},{"ep":"xb2-04","n":"XB2-04","p":7,"a":"p7","id":"nc1","src":"assets/audio/XB2-04/nc1.mp3","sec":11.28,"t":"考点七，生态位。一个物种在群落中的地位或作用，包括所处的空间位置、占用资源的情况，以及与其他物种的关系。"},{"ep":"xb2-04","n":"XB2-04","p":7,"a":"p7","id":"nc2","src":"assets/audio/XB2-04/nc2.mp3","sec":7.536,"t":"研究植物的生态位：出现频率、种群密度、植株高度，以及与其他物种的关系。"},{"ep":"xb2-04","n":"XB2-04","p":7,"a":"p7","id":"nc3","src":"assets/audio/XB2-04/nc3.mp3","sec":6.6,"t":"研究动物的生态位：栖息地、食物、天敌，以及与其他物种的关系。"},{"ep":"xb2-04","n":"XB2-04","p":7,"a":"p7","id":"nc4","src":"assets/audio/XB2-04/nc4.mp3","sec":6.912,"t":"两个物种的生态位重叠越多，对资源的争夺就越激烈，种间竞争越强。"},{"ep":"xb2-04","n":"XB2-04","p":7,"a":"p7","id":"nc5","src":"assets/audio/XB2-04/nc5.mp3","sec":10.728,"t":"考法：群落中每种生物都占据着相对稳定的生态位，有利于不同生物充分利用环境资源，这是协同进化的结果。"},{"ep":"xb2-04","n":"XB2-04","p":8,"a":"p8","id":"so1","src":"assets/audio/XB2-04/so1.mp3","sec":11.256,"t":"考点八，研究土壤中小动物类群的丰富度。土壤小动物活动能力较强、身体微小，不适合用样方法和标记重捕法。"},{"ep":"xb2-04","n":"XB2-04","p":8,"a":"p8","id":"so2","src":"assets/audio/XB2-04/so2.mp3","sec":4.2,"t":"常用取样器取样的方法进行采集和调查。"},{"ep":"xb2-04","n":"XB2-04","p":8,"a":"p8","id":"so3","src":"assets/audio/XB2-04/so3.mp3","sec":11.4,"t":"统计丰富度有两种方法：记名计算法，用于个体较大、种群数量有限的物种；目测估计法，按预先确定的多度等级来估计。"},{"ep":"xb2-04","n":"XB2-04","p":8,"a":"p8","id":"so4","src":"assets/audio/XB2-04/so4.mp3","sec":9.528,"t":"用诱虫器采集时，利用了土壤小动物趋暗、趋湿、避高温的特点；体型较小的，可以用吸虫器采集。"},{"ep":"xb2-04","n":"XB2-04","p":8,"a":"p8","id":"so5","src":"assets/audio/XB2-04/so5.mp3","sec":12.336,"t":"易错：诱虫器上方的电灯是为了驱赶小动物向下进入收集瓶，不是利用趋光性；收集瓶中通常加入体积分数为70%的酒精。"},{"ep":"xb2-04","n":"XB2-04","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-04/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-04","n":"XB2-04","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-04/rv2.mp3","sec":12.624,"t":"判断一：物种组成是区别不同群落的重要特征？对。判断二：物种丰富度指某种生物的个体数目？错，指物种数目。"},{"ep":"xb2-04","n":"XB2-04","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-04/rv3.mp3","sec":13.464,"t":"判断三：豆科植物与根瘤菌是原始合作？错，是互利共生。判断四：竹子高低错落体现垂直结构？错，竹子是一个种群。"},{"ep":"xb2-04","n":"XB2-04","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-04/rv4.mp3","sec":12.336,"t":"判断五：生态位重叠越多，竞争越激烈？对。判断六：诱虫器利用了趋光性？错，利用趋暗、趋湿、避高温。"},{"ep":"xb2-04","n":"XB2-04","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-04/rv5.mp3","sec":7.632,"t":"八个考点串成一条线：种间关系看曲线，生态位看资源。我们下期再见！"},{"ep":"xb2-05","n":"XB2-05","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-05/in1.mp3","sec":7.776,"t":"同学们好！这节课梳理人教版选择性必修二第二章第二节——群落的主要类型。"},{"ep":"xb2-05","n":"XB2-05","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-05/in2.mp3","sec":9.096,"t":"高考常考不同群落的分布特点，以及生物适应环境的形态结构特征，常常结合图片或情境来考。"},{"ep":"xb2-05","n":"XB2-05","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-05/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-05","n":"XB2-05","p":1,"a":"p1","id":"bs1","src":"assets/audio/XB2-05/bs1.mp3","sec":12.408,"t":"考点一，群落类型的划分。根据群落的外貌和物种组成等方面的差异，可以将陆地的群落大致分为荒漠、草原、森林等类型。"},{"ep":"xb2-05","n":"XB2-05","p":1,"a":"p1","id":"bs2","src":"assets/audio/XB2-05/bs2.mp3","sec":5.4,"t":"决定陆地群落类型的关键，是水分和温度等非生物因素。"},{"ep":"xb2-05","n":"XB2-05","p":1,"a":"p1","id":"bs3","src":"assets/audio/XB2-05/bs3.mp3","sec":8.904,"t":"一般来说，从干旱到湿润，依次出现荒漠、草原、森林，物种越来越多，结构越来越复杂。"},{"ep":"xb2-05","n":"XB2-05","p":1,"a":"p1","id":"bs4","src":"assets/audio/XB2-05/bs4.mp3","sec":11.4,"t":"考法：给出某地的降水量和群落特征，判断群落类型。解题方法：先看水分，再看物种多少和结构是否复杂。"},{"ep":"xb2-05","n":"XB2-05","p":2,"a":"p2","id":"ds1","src":"assets/audio/XB2-05/ds1.mp3","sec":10.776,"t":"考点二，荒漠生物群落。分布在极度干旱区，年降水量稀少且分布不均匀，物种少，群落结构非常简单。"},{"ep":"xb2-05","n":"XB2-05","p":2,"a":"p2","id":"ds2","src":"assets/audio/XB2-05/ds2.mp3","sec":7.344,"t":"植物耐旱：仙人掌属植物有肉质茎，叶呈针状；骆驼刺根系非常发达。"},{"ep":"xb2-05","n":"XB2-05","p":2,"a":"p2","id":"ds3","src":"assets/audio/XB2-05/ds3.mp3","sec":6.816,"t":"动物也耐旱：蜥蜴和蛇的表皮外有角质鳞片，有助于减少水分蒸发。"},{"ep":"xb2-05","n":"XB2-05","p":2,"a":"p2","id":"ds4","src":"assets/audio/XB2-05/ds4.mp3","sec":9.768,"t":"易错：荒漠中的爬行动物以固态尿酸盐的形式排泄含氮废物，而不是尿素，这样可以减少水分散失。"},{"ep":"xb2-05","n":"XB2-05","p":3,"a":"p3","id":"gl1","src":"assets/audio/XB2-05/gl1.mp3","sec":11.904,"t":"考点三，草原生物群落。主要分布在半干旱地区，不同年份或季节雨量不均匀，动植物种类较少，群落结构相对简单。"},{"ep":"xb2-05","n":"XB2-05","p":3,"a":"p3","id":"gl2","src":"assets/audio/XB2-05/gl2.mp3","sec":10.752,"t":"植物：耐寒的旱生多年生草本植物占优势，叶片狭窄，表面有茸毛或蜡质层，能抵抗干旱；乔木非常少见。"},{"ep":"xb2-05","n":"XB2-05","p":3,"a":"p3","id":"gl3","src":"assets/audio/XB2-05/gl3.mp3","sec":9.816,"t":"动物：大都具有挖洞或快速奔跑的特点，比如野兔、旱獭、黄羊；两栖类和水生动物非常少见。"},{"ep":"xb2-05","n":"XB2-05","p":3,"a":"p3","id":"gl4","src":"assets/audio/XB2-05/gl4.mp3","sec":13.392,"t":"考法：草原动物为什么善于挖洞或奔跑？解题方法：草原开阔、缺少树木遮蔽，挖洞便于躲避敌害，奔跑便于逃避捕食和寻找食物。"},{"ep":"xb2-05","n":"XB2-05","p":4,"a":"p4","id":"fr1","src":"assets/audio/XB2-05/fr1.mp3","sec":9.0,"t":"考点四，森林生物群落。分布在湿润或较湿润的地区，群落结构非常复杂且相对稳定。"},{"ep":"xb2-05","n":"XB2-05","p":4,"a":"p4","id":"fr2","src":"assets/audio/XB2-05/fr2.mp3","sec":7.68,"t":"动物：树栖和攀缘生活的动物种类特别多，比如松鼠、猿猴和多种鸟类。"},{"ep":"xb2-05","n":"XB2-05","p":4,"a":"p4","id":"fr3","src":"assets/audio/XB2-05/fr3.mp3","sec":8.112,"t":"林下光照较弱，生活着阴生植物：茎细长，叶薄，细胞壁薄，机械组织不发达。"},{"ep":"xb2-05","n":"XB2-05","p":4,"a":"p4","id":"fr4","src":"assets/audio/XB2-05/fr4.mp3","sec":9.432,"t":"易错：阴生植物的叶绿体颗粒大、呈深绿色，这是适应弱光环境的特征，不是颗粒小、颜色浅。"},{"ep":"xb2-05","n":"XB2-05","p":5,"a":"p5","id":"wt1","src":"assets/audio/XB2-05/wt1.mp3","sec":8.04,"t":"考点五，湿地和海洋中的群落。湿地生物群落中，既有水生生物，也有陆生生物。"},{"ep":"xb2-05","n":"XB2-05","p":5,"a":"p5","id":"wt2","src":"assets/audio/XB2-05/wt2.mp3","sec":7.968,"t":"比如芦苇、香蒲等挺水植物，鱼类、两栖类，以及大量在这里栖息、觅食的鸟类。"},{"ep":"xb2-05","n":"XB2-05","p":5,"a":"p5","id":"wt3","src":"assets/audio/XB2-05/wt3.mp3","sec":9.024,"t":"海洋生物群落中，生物的分布受光照、温度、盐度等因素的影响，藻类主要分布在有光的浅水层。"},{"ep":"xb2-05","n":"XB2-05","p":5,"a":"p5","id":"wt4","src":"assets/audio/XB2-05/wt4.mp3","sec":8.616,"t":"考法：湿地常和生物多样性的间接价值一起考，比如蓄洪防旱、净化水质、调节气候。"},{"ep":"xb2-05","n":"XB2-05","p":6,"a":"p6","id":"ad1","src":"assets/audio/XB2-05/ad1.mp3","sec":7.344,"t":"考点六，群落中的生物适应所处的环境。把三种陆地群落放在一起比较。"},{"ep":"xb2-05","n":"XB2-05","p":6,"a":"p6","id":"ad2","src":"assets/audio/XB2-05/ad2.mp3","sec":10.968,"t":"荒漠干旱：生物耐旱；草原半干旱：草本为主，动物挖洞或奔跑；森林湿润：分层明显，树栖攀缘动物多。"},{"ep":"xb2-05","n":"XB2-05","p":6,"a":"p6","id":"ad3","src":"assets/audio/XB2-05/ad3.mp3","sec":8.64,"t":"群落中的生物都是适应所处的非生物环境的，不同群落中生物适应环境的方式不尽相同。"},{"ep":"xb2-05","n":"XB2-05","p":6,"a":"p6","id":"ad4","src":"assets/audio/XB2-05/ad4.mp3","sec":12.6,"t":"解题方法：答适应性题目，用“结构与功能相适应、生物与环境相适应”的思路：先说环境特点，再说对应的结构特征，最后说它的作用。"},{"ep":"xb2-05","n":"XB2-05","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-05/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-05","n":"XB2-05","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-05/rv2.mp3","sec":13.464,"t":"判断一：荒漠爬行动物以尿素排出含氮废物？错，以固态尿酸盐排泄。判断二：草原动物大都善于挖洞或快速奔跑？对。"},{"ep":"xb2-05","n":"XB2-05","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-05/rv3.mp3","sec":12.288,"t":"判断三：阴生植物叶绿体颗粒小、呈浅绿色？错，颗粒大、呈深绿色。判断四：草原上乔木非常少见？对。"},{"ep":"xb2-05","n":"XB2-05","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-05/rv4.mp3","sec":11.664,"t":"判断五：群落类型主要依据外貌和物种组成划分？对。判断六：荒漠群落结构非常复杂？错，非常简单。"},{"ep":"xb2-05","n":"XB2-05","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-05/rv5.mp3","sec":7.296,"t":"六个考点串成一条线：看水分定类型，看结构找适应。我们下期再见！"},{"ep":"xb2-06","n":"XB2-06","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-06/in1.mp3","sec":7.464,"t":"同学们好！这节课梳理人教版选择性必修二第二章第三节——群落的演替。"},{"ep":"xb2-06","n":"XB2-06","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-06/in2.mp3","sec":8.712,"t":"高考常考初生演替和次生演替的判断、演替的过程和趋势，以及人类活动对演替的影响。"},{"ep":"xb2-06","n":"XB2-06","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-06/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-06","n":"XB2-06","p":1,"a":"p1","id":"cn1","src":"assets/audio/XB2-06/cn1.mp3","sec":9.144,"t":"考点一，演替的概念。随着时间的推移，一个群落被另一个群落代替的过程，叫做群落演替。"},{"ep":"xb2-06","n":"XB2-06","p":1,"a":"p1","id":"cn2","src":"assets/audio/XB2-06/cn2.mp3","sec":11.064,"t":"演替的原因：环境不断变化，生物本身不断进行繁殖、迁移等活动，种内和种间关系不断变化，还有人类活动的干扰。"},{"ep":"xb2-06","n":"XB2-06","p":1,"a":"p1","id":"cn3","src":"assets/audio/XB2-06/cn3.mp3","sec":10.512,"t":"易错：演替是优势取代，不是“取而代之”。新的优势种出现后，原来的物种不一定消失，往往只是不再占优势。"},{"ep":"xb2-06","n":"XB2-06","p":2,"a":"p2","id":"pm1","src":"assets/audio/XB2-06/pm1.mp3","sec":15.216,"t":"考点二，初生演替。在一个从来没有被植物覆盖的地面，或者原来存在过植被、但被彻底消灭了的地方发生的演替。比如沙丘、火山岩、冰川泥上的演替。"},{"ep":"xb2-06","n":"XB2-06","p":2,"a":"p2","id":"pm2","src":"assets/audio/XB2-06/pm2.mp3","sec":8.16,"t":"裸岩上的演替要经过：地衣阶段、苔藓阶段、草本植物阶段、灌木阶段和乔木阶段。"},{"ep":"xb2-06","n":"XB2-06","p":2,"a":"p2","id":"pm3","src":"assets/audio/XB2-06/pm3.mp3","sec":7.656,"t":"地衣分泌有机酸，加速岩石风化，逐渐形成土壤，为苔藓的生长创造了条件。"},{"ep":"xb2-06","n":"XB2-06","p":2,"a":"p2","id":"pm4","src":"assets/audio/XB2-06/pm4.mp3","sec":9.6,"t":"苔藓能取代地衣，是因为苔藓生长更高大，在争夺阳光中占优势。后面的阶段也是同样的道理。"},{"ep":"xb2-06","n":"XB2-06","p":2,"a":"p2","id":"pm5","src":"assets/audio/XB2-06/pm5.mp3","sec":10.152,"t":"考法：问某一阶段为什么能取代前一阶段。解题方法：答植株更高大，在争夺阳光的竞争中占优势。"},{"ep":"xb2-06","n":"XB2-06","p":3,"a":"p3","id":"sd1","src":"assets/audio/XB2-06/sd1.mp3","sec":12.36,"t":"考点三，次生演替。原有植被虽已不存在，但原有土壤条件基本保留，甚至还保留了植物的种子或其他繁殖体的地方发生的演替。"},{"ep":"xb2-06","n":"XB2-06","p":3,"a":"p3","id":"sd2","src":"assets/audio/XB2-06/sd2.mp3","sec":6.048,"t":"比如火灾过后的草原、过量砍伐的森林、弃耕的农田上的演替。"},{"ep":"xb2-06","n":"XB2-06","p":3,"a":"p3","id":"sd3","src":"assets/audio/XB2-06/sd3.mp3","sec":10.512,"t":"弃耕农田上，一般先长出一年生杂草，再到多年生杂草，然后是灌木，在适宜的条件下最终可能演替成森林。"},{"ep":"xb2-06","n":"XB2-06","p":3,"a":"p3","id":"sd4","src":"assets/audio/XB2-06/sd4.mp3","sec":11.184,"t":"解题方法：判断初生还是次生，就看起点有没有土壤条件和繁殖体。有，是次生演替；没有，是初生演替。"},{"ep":"xb2-06","n":"XB2-06","p":4,"a":"p4","id":"cm1","src":"assets/audio/XB2-06/cm1.mp3","sec":3.072,"t":"考点四，两种演替的比较。"},{"ep":"xb2-06","n":"XB2-06","p":4,"a":"p4","id":"cm2","src":"assets/audio/XB2-06/cm2.mp3","sec":8.664,"t":"起点：初生演替从没有土壤的地方开始；次生演替从有土壤、甚至有繁殖体的地方开始。"},{"ep":"xb2-06","n":"XB2-06","p":4,"a":"p4","id":"cm3","src":"assets/audio/XB2-06/cm3.mp3","sec":8.064,"t":"时间和速度：初生演替经历的时间长、速度慢；次生演替经历的时间短、速度快。"},{"ep":"xb2-06","n":"XB2-06","p":4,"a":"p4","id":"cm4","src":"assets/audio/XB2-06/cm4.mp3","sec":7.464,"t":"影响因素：初生演替主要是自然因素；次生演替受人类活动的影响较大。"},{"ep":"xb2-06","n":"XB2-06","p":4,"a":"p4","id":"cm5","src":"assets/audio/XB2-06/cm5.mp3","sec":8.424,"t":"易错：火灾后的森林、弃耕农田，地面看起来光秃秃，但土壤还在，属于次生演替。"},{"ep":"xb2-06","n":"XB2-06","p":5,"a":"p5","id":"tr1","src":"assets/audio/XB2-06/tr1.mp3","sec":8.712,"t":"考点五，演替的趋势。在自然条件下，演替一般朝着物种增多、结构复杂的方向发展。"},{"ep":"xb2-06","n":"XB2-06","p":5,"a":"p5","id":"tr2","src":"assets/audio/XB2-06/tr2.mp3","sec":11.952,"t":"群落中的物种丰富度、有机物总量逐渐增加，群落的结构越来越复杂，稳定性逐渐提高，最终达到与环境相适应的相对稳定状态。"},{"ep":"xb2-06","n":"XB2-06","p":5,"a":"p5","id":"tr3","src":"assets/audio/XB2-06/tr3.mp3","sec":10.608,"t":"但演替能否到达森林阶段，取决于气候等条件。在干旱的荒漠或草原地区，可能只发展到草本或灌木阶段。"},{"ep":"xb2-06","n":"XB2-06","p":5,"a":"p5","id":"tr4","src":"assets/audio/XB2-06/tr4.mp3","sec":10.104,"t":"易错：演替到相对稳定状态后，群落的物种组成仍在变化，并不是一成不变；演替的终点也不一定是森林。"},{"ep":"xb2-06","n":"XB2-06","p":6,"a":"p6","id":"hm1","src":"assets/audio/XB2-06/hm1.mp3","sec":10.752,"t":"考点六，人类活动对群落演替的影响。人类活动往往会使群落演替按照不同于自然演替的速度和方向进行。"},{"ep":"xb2-06","n":"XB2-06","p":6,"a":"p6","id":"hm2","src":"assets/audio/XB2-06/hm2.mp3","sec":8.52,"t":"不合理的活动，比如乱砍滥伐、过度放牧、围湖造田，会使群落退化，甚至出现荒漠化。"},{"ep":"xb2-06","n":"XB2-06","p":6,"a":"p6","id":"hm3","src":"assets/audio/XB2-06/hm3.mp3","sec":9.288,"t":"合理的活动，比如封山育林、治理沙漠、建立人工林，可以加快演替，使群落朝有利的方向发展。"},{"ep":"xb2-06","n":"XB2-06","p":6,"a":"p6","id":"hm4","src":"assets/audio/XB2-06/hm4.mp3","sec":9.384,"t":"考法：判断某项措施对演替的影响，答清楚它改变了演替的速度还是方向，以及是有利还是不利。"},{"ep":"xb2-06","n":"XB2-06","p":7,"a":"p7","id":"rs1","src":"assets/audio/XB2-06/rs1.mp3","sec":13.488,"t":"考点七，退耕还林、还草、还湖。为了恢复生态环境，我国在不适宜耕种的坡地、沙化土地等地方实施了退耕还林、还草、还湖。"},{"ep":"xb2-06","n":"XB2-06","p":7,"a":"p7","id":"rs2","src":"assets/audio/XB2-06/rs2.mp3","sec":7.68,"t":"这些措施利用了次生演替：土壤条件还在，演替速度较快，植被可以较快恢复。"},{"ep":"xb2-06","n":"XB2-06","p":7,"a":"p7","id":"rs3","src":"assets/audio/XB2-06/rs3.mp3","sec":9.96,"t":"植被恢复后，物种丰富度增加，群落结构变复杂，生态系统的稳定性提高，水土流失和沙化得到控制。"},{"ep":"xb2-06","n":"XB2-06","p":7,"a":"p7","id":"rs4","src":"assets/audio/XB2-06/rs4.mp3","sec":11.808,"t":"考法：题目问退耕还林属于哪种演替、有什么意义。答：属于次生演替；体现了人类活动可以改变演替的速度和方向。"},{"ep":"xb2-06","n":"XB2-06","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-06/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-06","n":"XB2-06","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-06/rv2.mp3","sec":13.032,"t":"判断一：冰川泥、火山岩上的演替是初生演替？对。判断二：弃耕农田上的演替属于初生演替？错，属于次生演替。"},{"ep":"xb2-06","n":"XB2-06","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-06/rv3.mp3","sec":12.192,"t":"判断三：演替过程中原有物种都会消失？错，是优势取代。判断四：次生演替的速度一般比初生演替快？对。"},{"ep":"xb2-06","n":"XB2-06","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-06/rv4.mp3","sec":12.432,"t":"判断五：群落演替最终都能到达森林阶段？错，取决于气候。判断六：人类活动能改变演替的速度和方向？对。"},{"ep":"xb2-06","n":"XB2-06","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-06/rv5.mp3","sec":7.776,"t":"七个考点串成一条线：有没有土壤定类型，能不能成林看气候。我们下期再见！"},{"ep":"xb2-07","n":"XB2-07","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-07/in1.mp3","sec":7.944,"t":"同学们好！这节课梳理人教版选择性必修二第三章第一节——生态系统的结构。"},{"ep":"xb2-07","n":"XB2-07","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-07/in2.mp3","sec":9.864,"t":"高考常考生态系统组成成分的判断、食物链和食物网的分析，以及某种生物数量变化对其他生物的影响。"},{"ep":"xb2-07","n":"XB2-07","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-07/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-07","n":"XB2-07","p":1,"a":"p1","id":"cc1","src":"assets/audio/XB2-07/cc1.mp3","sec":11.736,"t":"考点一，生态系统的概念。在一定空间内，由生物群落与它的非生物环境相互作用而形成的统一整体，叫做生态系统。"},{"ep":"xb2-07","n":"XB2-07","p":1,"a":"p1","id":"cc2","src":"assets/audio/XB2-07/cc2.mp3","sec":6.648,"t":"生态系统的空间范围有大有小，生物圈是地球上最大的生态系统。"},{"ep":"xb2-07","n":"XB2-07","p":1,"a":"p1","id":"cc3","src":"assets/audio/XB2-07/cc3.mp3","sec":10.416,"t":"生态系统可以分为自然生态系统，比如森林、草原、海洋；和人工生态系统，比如农田、果园、城市。"},{"ep":"xb2-07","n":"XB2-07","p":1,"a":"p1","id":"cc4","src":"assets/audio/XB2-07/cc4.mp3","sec":8.664,"t":"易错：生态系统 = 生物群落 + 非生物环境。只说“全部生物”是群落，不是生态系统。"},{"ep":"xb2-07","n":"XB2-07","p":2,"a":"p2","id":"pt1","src":"assets/audio/XB2-07/pt1.mp3","sec":11.208,"t":"考点二，生态系统的组成成分有四种。第一种，非生物的物质和能量，比如阳光、热能、水、空气、无机盐。"},{"ep":"xb2-07","n":"XB2-07","p":2,"a":"p2","id":"pt2","src":"assets/audio/XB2-07/pt2.mp3","sec":9.936,"t":"第二种，生产者，主要是绿色植物，属于自养生物。它把无机物转变成有机物，是生态系统的基石。"},{"ep":"xb2-07","n":"XB2-07","p":2,"a":"p2","id":"pt3","src":"assets/audio/XB2-07/pt3.mp3","sec":8.328,"t":"第三种，消费者，主要是动物。它能加快物质循环，还能帮助植物传粉和传播种子。"},{"ep":"xb2-07","n":"XB2-07","p":2,"a":"p2","id":"pt4","src":"assets/audio/XB2-07/pt4.mp3","sec":9.384,"t":"第四种，{分解者|brown}，主要是细菌和真菌。它把动植物遗体和动物排遗物中的有机物{分解成无机物|brown}。"},{"ep":"xb2-07","n":"XB2-07","p":2,"a":"p2","id":"pt5","src":"assets/audio/XB2-07/pt5.mp3","sec":10.776,"t":"考法：问哪种成分是生态系统的基石——生产者；哪种成分缺少了，生态系统就会崩溃——生产者和分解者。"},{"ep":"xb2-07","n":"XB2-07","p":3,"a":"p3","id":"tp1","src":"assets/audio/XB2-07/tp1.mp3","sec":5.112,"t":"考点三，成分判断的易错点。记住三个“不一定”。"},{"ep":"xb2-07","n":"XB2-07","p":3,"a":"p3","id":"tp2","src":"assets/audio/XB2-07/tp2.mp3","sec":5.712,"t":"植物不一定是生产者：菟丝子营寄生生活，属于消费者。"},{"ep":"xb2-07","n":"XB2-07","p":3,"a":"p3","id":"tp3","src":"assets/audio/XB2-07/tp3.mp3","sec":7.2,"t":"动物不一定是消费者：蚯蚓、蜣螂以腐殖质和粪便为食，属于分解者。"},{"ep":"xb2-07","n":"XB2-07","p":3,"a":"p3","id":"tp4","src":"assets/audio/XB2-07/tp4.mp3","sec":9.096,"t":"细菌不一定是分解者：硝化细菌能进行化能合成作用，属于生产者；寄生细菌属于消费者。"},{"ep":"xb2-07","n":"XB2-07","p":3,"a":"p3","id":"tp5","src":"assets/audio/XB2-07/tp5.mp3","sec":11.976,"t":"解题方法：只看营养方式。能自己合成有机物的是生产者；以活的生物为食的是消费者；以遗体和排遗物为食的是分解者。"},{"ep":"xb2-07","n":"XB2-07","p":4,"a":"p4","id":"lk1","src":"assets/audio/XB2-07/lk1.mp3","sec":10.032,"t":"考点四，各组成成分之间的关系。生产者通过光合作用，把非生物环境中的物质和能量引入生物群落。"},{"ep":"xb2-07","n":"XB2-07","p":4,"a":"p4","id":"lk2","src":"assets/audio/XB2-07/lk2.mp3","sec":4.992,"t":"消费者以生产者为食，有机物沿着食物链传递。"},{"ep":"xb2-07","n":"XB2-07","p":4,"a":"p4","id":"lk3","src":"assets/audio/XB2-07/lk3.mp3","sec":7.536,"t":"生产者和消费者的遗体、排遗物被{分解者|brown}分解，物质又回到非生物环境中。"},{"ep":"xb2-07","n":"XB2-07","p":4,"a":"p4","id":"lk4","src":"assets/audio/XB2-07/lk4.mp3","sec":10.584,"t":"考法：生产者和分解者是联系生物群落和非生物环境的两大“桥梁”；消费者不是必需的，但能加快物质循环。"},{"ep":"xb2-07","n":"XB2-07","p":5,"a":"p5","id":"ch1","src":"assets/audio/XB2-07/ch1.mp3","sec":8.784,"t":"考点五，食物链。生态系统中各种生物因食物关系而形成的一种联系，叫做食物链。"},{"ep":"xb2-07","n":"XB2-07","p":5,"a":"p5","id":"ch2","src":"assets/audio/XB2-07/ch2.mp3","sec":10.104,"t":"比如：草、蝗虫、青蛙、蛇、鹰。起点是生产者，终点是不被其他动物捕食的最高营养级。"},{"ep":"xb2-07","n":"XB2-07","p":5,"a":"p5","id":"ch3","src":"assets/audio/XB2-07/ch3.mp3","sec":9.912,"t":"生产者是第一营养级，初级消费者是第二营养级，以此类推。消费者的级别 = 营养级数 − 1。"},{"ep":"xb2-07","n":"XB2-07","p":5,"a":"p5","id":"ch4","src":"assets/audio/XB2-07/ch4.mp3","sec":10.128,"t":"易错：食物链中只有生产者和消费者，不包括分解者和非生物的物质和能量；食物链一般不超过五个营养级。"},{"ep":"xb2-07","n":"XB2-07","p":6,"a":"p6","id":"wb1","src":"assets/audio/XB2-07/wb1.mp3","sec":8.712,"t":"考点六，食物网。许多食物链彼此相互交错，连接成复杂的营养关系，就是食物网。"},{"ep":"xb2-07","n":"XB2-07","p":6,"a":"p6","id":"wb2","src":"assets/audio/XB2-07/wb2.mp3","sec":10.104,"t":"数食物链：从生产者出发，沿箭头一直数到最高营养级，不能中途停下。这个食物网有五条食物链。"},{"ep":"xb2-07","n":"XB2-07","p":6,"a":"p6","id":"wb3","src":"assets/audio/XB2-07/wb3.mp3","sec":10.944,"t":"同一种生物可以占不同的营养级：鹰在草、鼠、鹰中是第三营养级，在草、鼠、蛇、鹰中是第四营养级。"},{"ep":"xb2-07","n":"XB2-07","p":6,"a":"p6","id":"wb4","src":"assets/audio/XB2-07/wb4.mp3","sec":7.152,"t":"两种生物之间可能既有捕食，又有竞争：鹰吃蛇，鹰和蛇又都吃鼠。"},{"ep":"xb2-07","n":"XB2-07","p":6,"a":"p6","id":"wb5","src":"assets/audio/XB2-07/wb5.mp3","sec":11.616,"t":"考法：食物网越复杂，生态系统抵抗外界干扰的能力越强。数食物链、找营养级、判断种间关系，是三个必考动作。"},{"ep":"xb2-07","n":"XB2-07","p":7,"a":"p7","id":"cg1","src":"assets/audio/XB2-07/cg1.mp3","sec":4.2,"t":"考点七，食物网中生物数量变化的分析。"},{"ep":"xb2-07","n":"XB2-07","p":7,"a":"p7","id":"cg2","src":"assets/audio/XB2-07/cg2.mp3","sec":5.28,"t":"第一营养级减少：其他生物都会因食物减少而减少。"},{"ep":"xb2-07","n":"XB2-07","p":7,"a":"p7","id":"cg3","src":"assets/audio/XB2-07/cg3.mp3","sec":7.584,"t":"天敌减少：被捕食者先增加，后因种内竞争加剧而减少，最后趋于稳定。"},{"ep":"xb2-07","n":"XB2-07","p":7,"a":"p7","id":"cg4","src":"assets/audio/XB2-07/cg4.mp3","sec":10.536,"t":"中间营养级减少：比如蛇减少，鹰可以更多地捕食鼠，营养级降低，获得的能量反而更多，所以鹰的数量增加。"},{"ep":"xb2-07","n":"XB2-07","p":7,"a":"p7","id":"cg5","src":"assets/audio/XB2-07/cg5.mp3","sec":12.48,"t":"解题方法：先看减少的生物处在哪个营养级；中间环节变化时，抓住“食物来源是否多样”和“营养级越低获得的能量越多”两点分析。"},{"ep":"xb2-07","n":"XB2-07","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-07/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-07","n":"XB2-07","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-07/rv2.mp3","sec":11.52,"t":"判断一：生物圈是地球上最大的生态系统？对。判断二：细菌都是分解者？错，硝化细菌是生产者。"},{"ep":"xb2-07","n":"XB2-07","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-07/rv3.mp3","sec":11.616,"t":"判断三：蚯蚓、蜣螂属于分解者？对。判断四：食物链中包含分解者？错，只含生产者和消费者。"},{"ep":"xb2-07","n":"XB2-07","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-07/rv4.mp3","sec":11.616,"t":"判断五：同一生物在食物网中只占一个营养级？错。判断六：食物网越复杂，抵抗干扰的能力越强？对。"},{"ep":"xb2-07","n":"XB2-07","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-07/rv5.mp3","sec":8.112,"t":"七个考点串成一条线：成分看营养方式，链条从生产者数起。我们下期再见！"},{"ep":"xb2-08","n":"XB2-08","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-08/in1.mp3","sec":10.296,"t":"同学们好！这节课梳理人教版选择性必修二第三章第二节——生态系统的能量流动，上集讲过程和特点。"},{"ep":"xb2-08","n":"XB2-08","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-08/in2.mp3","sec":9.288,"t":"高考常考摄入量、同化量和粪便量的关系、能量去向的分析，以及单向流动、逐级递减的原因。"},{"ep":"xb2-08","n":"XB2-08","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-08/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-08","n":"XB2-08","p":1,"a":"p1","id":"co1","src":"assets/audio/XB2-08/co1.mp3","sec":9.936,"t":"考点一，能量流动的概念。生态系统中能量的输入、传递、转化和散失的过程，叫做能量流动。"},{"ep":"xb2-08","n":"XB2-08","p":1,"a":"p1","id":"co2","src":"assets/audio/XB2-08/co2.mp3","sec":10.728,"t":"输入：流经生态系统的总能量，是生产者固定的太阳能总量；人工生态系统还要加上人工输入的有机物中的能量。"},{"ep":"xb2-08","n":"XB2-08","p":1,"a":"p1","id":"co3","src":"assets/audio/XB2-08/co3.mp3","sec":5.952,"t":"传递：沿着食物链和食物网，以有机物中的化学能形式传递。"},{"ep":"xb2-08","n":"XB2-08","p":1,"a":"p1","id":"co4","src":"assets/audio/XB2-08/co4.mp3","sec":8.256,"t":"转化：太阳能、化学能、热能；散失：最终以热能形式，通过呼吸作用散失。"},{"ep":"xb2-08","n":"XB2-08","p":1,"a":"p1","id":"co5","src":"assets/audio/XB2-08/co5.mp3","sec":9.048,"t":"易错：总能量是生产者固定的太阳能，不是照射到生产者上的太阳能，也不是生产者积累的能量。"},{"ep":"xb2-08","n":"XB2-08","p":2,"a":"p2","id":"l11","src":"assets/audio/XB2-08/l11.mp3","sec":8.304,"t":"考点二，能量流经第一营养级。生产者通过光合作用，把太阳能固定在有机物中。"},{"ep":"xb2-08","n":"XB2-08","p":2,"a":"p2","id":"l12","src":"assets/audio/XB2-08/l12.mp3","sec":5.952,"t":"这些能量，一部分在生产者的呼吸作用中以热能的形式散失。"},{"ep":"xb2-08","n":"XB2-08","p":2,"a":"p2","id":"l13","src":"assets/audio/XB2-08/l13.mp3","sec":6.576,"t":"另一部分用于生产者的生长、发育和繁殖，储存在植物体的有机物中。"},{"ep":"xb2-08","n":"XB2-08","p":2,"a":"p2","id":"l14","src":"assets/audio/XB2-08/l14.mp3","sec":8.856,"t":"这部分能量中，一部分随残枝败叶流向{分解者|brown}，一部分被初级消费者摄入，流入第二营养级。"},{"ep":"xb2-08","n":"XB2-08","p":2,"a":"p2","id":"l15","src":"assets/audio/XB2-08/l15.mp3","sec":14.256,"t":"考法：给出能量流动图，让你填写各个箭头的含义。解题方法：每个营养级都按“固定或同化 → 呼吸散失 + 生长发育繁殖”拆开。"},{"ep":"xb2-08","n":"XB2-08","p":3,"a":"p3","id":"l21","src":"assets/audio/XB2-08/l21.mp3","sec":7.08,"t":"考点三，能量流经第二营养级。初级消费者吃进去的能量叫摄入量。"},{"ep":"xb2-08","n":"XB2-08","p":3,"a":"p3","id":"l22","src":"assets/audio/XB2-08/l22.mp3","sec":8.28,"t":"摄入量 = 同化量 + 粪便量。粪便中的能量没有被消化吸收，最终流向分解者。"},{"ep":"xb2-08","n":"XB2-08","p":3,"a":"p3","id":"l23","src":"assets/audio/XB2-08/l23.mp3","sec":9.312,"t":"同化量才是真正流入第二营养级的能量，它又分为呼吸作用散失和用于生长、发育和繁殖两部分。"},{"ep":"xb2-08","n":"XB2-08","p":3,"a":"p3","id":"l24","src":"assets/audio/XB2-08/l24.mp3","sec":10.728,"t":"易错：初级消费者粪便中的能量，不属于初级消费者的同化量，而是属于上一营养级，也就是生产者同化的能量。"},{"ep":"xb2-08","n":"XB2-08","p":4,"a":"p4","id":"ft1","src":"assets/audio/XB2-08/ft1.mp3","sec":5.928,"t":"考点四，同化量的去向。把每个营养级的能量拆开来看。"},{"ep":"xb2-08","n":"XB2-08","p":4,"a":"p4","id":"ft2","src":"assets/audio/XB2-08/ft2.mp3","sec":6.792,"t":"同化量 = 呼吸作用散失 + 用于生长、发育和繁殖。"},{"ep":"xb2-08","n":"XB2-08","p":4,"a":"p4","id":"ft3","src":"assets/audio/XB2-08/ft3.mp3","sec":8.664,"t":"用于生长、发育和繁殖 = 流入下一营养级 + 流向分解者 + 未利用。"},{"ep":"xb2-08","n":"XB2-08","p":4,"a":"p4","id":"ft4","src":"assets/audio/XB2-08/ft4.mp3","sec":9.48,"t":"所以，一定时间内，同化量的去向有四个：呼吸散失、流入下一营养级、流向分解者、未利用。"},{"ep":"xb2-08","n":"XB2-08","p":4,"a":"p4","id":"ft5","src":"assets/audio/XB2-08/ft5.mp3","sec":10.128,"t":"易错：最高营养级没有“流入下一营养级”这一项；“未利用”是指暂时没有被利用的能量，只在定时分析时出现。"},{"ep":"xb2-08","n":"XB2-08","p":5,"a":"p5","id":"lk1","src":"assets/audio/XB2-08/lk1.mp3","sec":7.872,"t":"考点五，赛达伯格湖的能量流动定量分析，这是美国生态学家林德曼的经典研究。"},{"ep":"xb2-08","n":"XB2-08","p":5,"a":"p5","id":"lk2","src":"assets/audio/XB2-08/lk2.mp3","sec":11.016,"t":"生产者固定 464.6，植食性动物同化 62.8，肉食性动物同化 12.6，单位是焦每平方厘米每年。"},{"ep":"xb2-08","n":"XB2-08","p":5,"a":"p5","id":"lk3","src":"assets/audio/XB2-08/lk3.mp3","sec":10.584,"t":"传递效率：62.8 ÷ 464.6 ≈ 13.5%；12.6 ÷ 62.8 ≈ 20%。"},{"ep":"xb2-08","n":"XB2-08","p":5,"a":"p5","id":"lk4","src":"assets/audio/XB2-08/lk4.mp3","sec":10.68,"t":"解题方法：传递效率 = 下一营养级同化量 ÷ 上一营养级同化量；分子分母都必须是同化量，不能用摄入量。"},{"ep":"xb2-08","n":"XB2-08","p":6,"a":"p6","id":"fe1","src":"assets/audio/XB2-08/fe1.mp3","sec":11.616,"t":"考点六，能量流动的特点。第一，单向流动：只能沿食物链由低营养级流向高营养级，不可逆转，也不能循环流动。"},{"ep":"xb2-08","n":"XB2-08","p":6,"a":"p6","id":"fe2","src":"assets/audio/XB2-08/fe2.mp3","sec":8.352,"t":"原因：捕食关系是长期自然选择的结果，不可逆转；散失的热能不能再被生物利用。"},{"ep":"xb2-08","n":"XB2-08","p":6,"a":"p6","id":"fe3","src":"assets/audio/XB2-08/fe3.mp3","sec":7.824,"t":"第二，逐级递减：相邻两个营养级之间的传递效率大约是10%到20%。"},{"ep":"xb2-08","n":"XB2-08","p":6,"a":"p6","id":"fe4","src":"assets/audio/XB2-08/fe4.mp3","sec":8.616,"t":"原因：每个营养级都有能量在呼吸作用中散失，还有一部分流向分解者，一部分未被利用。"},{"ep":"xb2-08","n":"XB2-08","p":6,"a":"p6","id":"fe5","src":"assets/audio/XB2-08/fe5.mp3","sec":10.248,"t":"易错：传递效率是相邻两个营养级之间的，不是两个个体之间的；一只狼吃一只兔，可能获得兔的大部分能量。"},{"ep":"xb2-08","n":"XB2-08","p":7,"a":"p7","id":"py1","src":"assets/audio/XB2-08/py1.mp3","sec":8.424,"t":"考点七，生态金字塔。把各营养级的数值，由低到高绘制成图，就是生态金字塔。"},{"ep":"xb2-08","n":"XB2-08","p":7,"a":"p7","id":"py2","src":"assets/audio/XB2-08/py2.mp3","sec":6.456,"t":"能量金字塔：由于能量逐级递减，通常都是上窄下宽的正金字塔。"},{"ep":"xb2-08","n":"XB2-08","p":7,"a":"p7","id":"py3","src":"assets/audio/XB2-08/py3.mp3","sec":6.312,"t":"数量金字塔：可能倒置，比如一棵树上生活着成千上万只昆虫。"},{"ep":"xb2-08","n":"XB2-08","p":7,"a":"p7","id":"py4","src":"assets/audio/XB2-08/py4.mp3","sec":9.528,"t":"生物量金字塔：一般是正的，但在海洋中，某一时刻浮游植物的生物量可能低于浮游动物，出现倒置。"},{"ep":"xb2-08","n":"XB2-08","p":7,"a":"p7","id":"py5","src":"assets/audio/XB2-08/py5.mp3","sec":8.712,"t":"考法：问哪种金字塔通常不会倒置——能量金字塔。数量和生物量金字塔都可能倒置。"},{"ep":"xb2-08","n":"XB2-08","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-08/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-08","n":"XB2-08","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-08/rv2.mp3","sec":15.672,"t":"判断一：总能量是照到生产者上的太阳能？错，是生产者固定的太阳能总量。判断二：初级消费者粪便中的能量属于它的同化量？错，属于上一营养级。"},{"ep":"xb2-08","n":"XB2-08","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-08/rv3.mp3","sec":13.8,"t":"判断三：同化量等于呼吸散失加用于生长发育和繁殖？对。判断四：传递效率指相邻两个个体之间？错，指相邻两个营养级。"},{"ep":"xb2-08","n":"XB2-08","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-08/rv4.mp3","sec":10.368,"t":"判断五：能量金字塔通常不会倒置？对。判断六：能量可以循环利用？错，能量单向流动。"},{"ep":"xb2-08","n":"XB2-08","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-08/rv5.mp3","sec":10.776,"t":"七个考点串成一条线：摄入减粪便是同化，粪便算上一级。下集讲能量流动的计算和实践意义，我们下期再见！"},{"ep":"xb2-09","n":"XB2-09","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-09/in1.mp3","sec":7.632,"t":"同学们好！这节课是生态系统的能量流动下集，讲相关计算和实践意义。"},{"ep":"xb2-09","n":"XB2-09","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-09/in2.mp3","sec":9.0,"t":"高考常考传递效率的计算、至少和最多消耗多少生产者，以及能量利用率和传递效率的区别。"},{"ep":"xb2-09","n":"XB2-09","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-09/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-09","n":"XB2-09","p":1,"a":"p1","id":"ef1","src":"assets/audio/XB2-09/ef1.mp3","sec":10.224,"t":"考点一，传递效率的计算。传递效率 = 下一营养级同化量 ÷ 上一营养级同化量 × 100%。"},{"ep":"xb2-09","n":"XB2-09","p":1,"a":"p1","id":"ef2","src":"assets/audio/XB2-09/ef2.mp3","sec":9.096,"t":"比如，生产者同化了 1000 kJ，初级消费者同化了 150 kJ，传递效率就是 15%。"},{"ep":"xb2-09","n":"XB2-09","p":1,"a":"p1","id":"ef3","src":"assets/audio/XB2-09/ef3.mp3","sec":9.648,"t":"注意三点：用同化量，不用摄入量；是营养级之间，不是个体之间；同一营养级的所有生物都要算进去。"},{"ep":"xb2-09","n":"XB2-09","p":1,"a":"p1","id":"ef4","src":"assets/audio/XB2-09/ef4.mp3","sec":7.848,"t":"易错：题目给出“摄入量”或“粪便量”时，要先算出同化量再代入，否则结果偏大。"},{"ep":"xb2-09","n":"XB2-09","p":2,"a":"p2","id":"mm1","src":"assets/audio/XB2-09/mm1.mp3","sec":10.2,"t":"考点二，至少和最多消耗多少生产者。这类题叫“知高求低”：已知最高营养级增加的量，求消耗的生产者。"},{"ep":"xb2-09","n":"XB2-09","p":2,"a":"p2","id":"mm2","src":"assets/audio/XB2-09/mm2.mp3","sec":14.928,"t":"求至少消耗：选最短的食物链，按 20% 计算。鹰增重 1 kg，草→兔→鹰，至少需草 1 ÷ 20% ÷ 20% = 25 kg。"},{"ep":"xb2-09","n":"XB2-09","p":2,"a":"p2","id":"mm3","src":"assets/audio/XB2-09/mm3.mp3","sec":12.744,"t":"求最多消耗：选最长的食物链，按 10% 计算。草→鼠→蛇→鹰，最多需草 1 ÷ 10% ÷ 10% ÷ 10% = 1000 kg。"},{"ep":"xb2-09","n":"XB2-09","p":2,"a":"p2","id":"mm4","src":"assets/audio/XB2-09/mm4.mp3","sec":14.328,"t":"解题方法：至少——短链 × 20%；最多——长链 × 10%。反过来“知低求高”求最多获得，同样选最短链、按 20%。"},{"ep":"xb2-09","n":"XB2-09","p":3,"a":"p3","id":"ra1","src":"assets/audio/XB2-09/ra1.mp3","sec":6.936,"t":"考点三，按比例分配的计算。题目会给出某种生物的食物来源比例。"},{"ep":"xb2-09","n":"XB2-09","p":3,"a":"p3","id":"ra2","src":"assets/audio/XB2-09/ra2.mp3","sec":9.72,"t":"例：鹰的食物 1/2 来自兔、1/2 来自蛇，传递效率按 10%。鹰增重 2 kg，需要多少草？"},{"ep":"xb2-09","n":"XB2-09","p":3,"a":"p3","id":"ra3","src":"assets/audio/XB2-09/ra3.mp3","sec":12.456,"t":"来自兔的 1 kg：需草 1 ÷ 10% ÷ 10% = 100 kg；来自蛇的 1 kg：需草 1000 kg；合计 1100 kg。"},{"ep":"xb2-09","n":"XB2-09","p":3,"a":"p3","id":"ra4","src":"assets/audio/XB2-09/ra4.mp3","sec":13.056,"t":"解题方法：分链计算，再相加。比例是“食物来源比例”时，从高营养级往低营养级逆推；比例是“能量分配比例”时，从低往高顺推。"},{"ep":"xb2-09","n":"XB2-09","p":4,"a":"p4","id":"mo1","src":"assets/audio/XB2-09/mo1.mp3","sec":6.648,"t":"考点四，能量流动模型图中各字母的关系。以第二营养级为例。"},{"ep":"xb2-09","n":"XB2-09","p":4,"a":"p4","id":"mo2","src":"assets/audio/XB2-09/mo2.mp3","sec":3.864,"t":"摄入量 a = 同化量 b + 粪便量 c。"},{"ep":"xb2-09","n":"XB2-09","p":4,"a":"p4","id":"mo3","src":"assets/audio/XB2-09/mo3.mp3","sec":6.144,"t":"同化量 b = 呼吸散失 d + 用于生长、发育和繁殖 e。"},{"ep":"xb2-09","n":"XB2-09","p":4,"a":"p4","id":"mo4","src":"assets/audio/XB2-09/mo4.mp3","sec":11.064,"t":"e = 流入下一营养级 f + 流向分解者 g + 未利用；第二到第三营养级的传递效率 = f ÷ b。"},{"ep":"xb2-09","n":"XB2-09","p":4,"a":"p4","id":"mo5","src":"assets/audio/XB2-09/mo5.mp3","sec":8.52,"t":"解题方法：先找同化量，再往下拆。粪便量 c 属于上一营养级流向分解者的能量。"},{"ep":"xb2-09","n":"XB2-09","p":5,"a":"p5","id":"me1","src":"assets/audio/XB2-09/me1.mp3","sec":14.856,"t":"考点五，研究能量流动的实践意义。第一，帮助人们将生物在时间、空间上进行合理配置，增大流入某个生态系统的总能量，比如间作套种、立体农业。"},{"ep":"xb2-09","n":"XB2-09","p":5,"a":"p5","id":"me2","src":"assets/audio/XB2-09/me2.mp3","sec":7.128,"t":"第二，帮助人们科学地规划和设计人工生态系统，使能量得到最有效的利用。"},{"ep":"xb2-09","n":"XB2-09","p":5,"a":"p5","id":"me3","src":"assets/audio/XB2-09/me3.mp3","sec":10.584,"t":"比如：秸秆喂牲畜，牲畜粪便进入沼气池，沼渣肥田。原本散失的能量被多级利用，提高了能量利用率。"},{"ep":"xb2-09","n":"XB2-09","p":5,"a":"p5","id":"me4","src":"assets/audio/XB2-09/me4.mp3","sec":9.264,"t":"易错：这样做提高的是能量利用率，不是能量传递效率。相邻营养级间的传递效率不会因此改变。"},{"ep":"xb2-09","n":"XB2-09","p":6,"a":"p6","id":"mn1","src":"assets/audio/XB2-09/mn1.mp3","sec":9.888,"t":"考点六，第三个实践意义：帮助人们合理地调整能量流动关系，使能量持续高效地流向对人类最有益的部分。"},{"ep":"xb2-09","n":"XB2-09","p":6,"a":"p6","id":"mn2","src":"assets/audio/XB2-09/mn2.mp3","sec":7.944,"t":"比如农田中除草、灭虫，让更多能量流向农作物；稻田除草，就是这个道理。"},{"ep":"xb2-09","n":"XB2-09","p":6,"a":"p6","id":"mn3","src":"assets/audio/XB2-09/mn3.mp3","sec":9.024,"t":"又比如草原放牧，要合理确定载畜量：太少浪费牧草，太多会破坏草原，都不能持续高效。"},{"ep":"xb2-09","n":"XB2-09","p":6,"a":"p6","id":"mn4","src":"assets/audio/XB2-09/mn4.mp3","sec":10.272,"t":"考法：问除草灭虫的意义。答题模板：调整能量流动关系，使能量持续高效地流向对人类最有益的部分。"},{"ep":"xb2-09","n":"XB2-09","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-09/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-09","n":"XB2-09","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-09/rv2.mp3","sec":13.416,"t":"判断一：传递效率可以用摄入量来计算？错，必须用同化量。判断二：求至少消耗生产者，选最短链、按 20%？对。"},{"ep":"xb2-09","n":"XB2-09","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-09/rv3.mp3","sec":14.448,"t":"判断三：求最多消耗生产者，选最短链、按 10%？错，选最长链。判断四：秸秆喂牲畜、粪便制沼气提高了能量利用率？对。"},{"ep":"xb2-09","n":"XB2-09","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-09/rv4.mp3","sec":13.44,"t":"判断五：生态农业提高了能量传递效率？错，提高的是能量利用率。判断六：除草灭虫使能量更多流向对人类有益的部分？对。"},{"ep":"xb2-09","n":"XB2-09","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-09/rv5.mp3","sec":7.704,"t":"六个考点串成一条线：至少短链乘二成，最多长链乘一成。我们下期再见！"},{"ep":"xb2-10","n":"XB2-10","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-10/in1.mp3","sec":8.328,"t":"同学们好！这节课梳理人教版选择性必修二第三章第三节——生态系统的物质循环。"},{"ep":"xb2-10","n":"XB2-10","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-10/in2.mp3","sec":10.032,"t":"高考常考碳循环图解的判断、生物富集、能量流动与物质循环的关系，以及土壤微生物分解作用的探究。"},{"ep":"xb2-10","n":"XB2-10","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-10/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-10","n":"XB2-10","p":1,"a":"p1","id":"cc1","src":"assets/audio/XB2-10/cc1.mp3","sec":15.48,"t":"考点一，物质循环的概念。组成生物体的碳、氢、氧、氮、磷、硫等元素，都不断进行着从非生物环境到生物群落，又从生物群落到非生物环境的循环过程。"},{"ep":"xb2-10","n":"XB2-10","p":1,"a":"p1","id":"cc2","src":"assets/audio/XB2-10/cc2.mp3","sec":7.032,"t":"这里的“物质”指的是化学元素，不是化合物；这里的“生态系统”指的是生物圈。"},{"ep":"xb2-10","n":"XB2-10","p":1,"a":"p1","id":"cc3","src":"assets/audio/XB2-10/cc3.mp3","sec":12.648,"t":"考法：物质循环的特点是全球性和循环往复。一个小的生态系统，比如农田，需要不断施肥，并不能在自身内部完成物质循环。"},{"ep":"xb2-10","n":"XB2-10","p":2,"a":"p2","id":"cb1","src":"assets/audio/XB2-10/cb1.mp3","sec":8.136,"t":"考点二，碳循环的过程。碳在非生物环境中主要以CO2和碳酸盐的形式存在。"},{"ep":"xb2-10","n":"XB2-10","p":2,"a":"p2","id":"cb2","src":"assets/audio/XB2-10/cb2.mp3","sec":9.936,"t":"碳在生物群落与非生物环境之间，主要以CO2的形式循环；在生物群落内部，以含碳有机物的形式传递。"},{"ep":"xb2-10","n":"XB2-10","p":2,"a":"p2","id":"cb3","src":"assets/audio/XB2-10/cb3.mp3","sec":6.144,"t":"碳进入生物群落，主要靠生产者的光合作用，还有化能合成作用。"},{"ep":"xb2-10","n":"XB2-10","p":2,"a":"p2","id":"cb4","src":"assets/audio/XB2-10/cb4.mp3","sec":8.112,"t":"碳返回非生物环境，靠动植物的呼吸作用、分解者的分解作用，以及化石燃料的燃烧。"},{"ep":"xb2-10","n":"XB2-10","p":2,"a":"p2","id":"cb5","src":"assets/audio/XB2-10/cb5.mp3","sec":9.168,"t":"易错：在生物群落内部，碳不是以CO2形式传递，而是以含碳有机物的形式沿食物链传递。"},{"ep":"xb2-10","n":"XB2-10","p":3,"a":"p3","id":"dg1","src":"assets/audio/XB2-10/dg1.mp3","sec":7.056,"t":"考点三，碳循环图解的判断。题目常把各成分换成字母，让你判断。"},{"ep":"xb2-10","n":"XB2-10","p":3,"a":"p3","id":"dg2","src":"assets/audio/XB2-10/dg2.mp3","sec":8.808,"t":"第一步，找双向箭头：双向箭头连接的两者，一个是生产者，一个是大气中的CO2库。"},{"ep":"xb2-10","n":"XB2-10","p":3,"a":"p3","id":"dg3","src":"assets/audio/XB2-10/dg3.mp3","sec":9.0,"t":"第二步，在这两者中，其他成分都有箭头指向它的是大气中的CO2库，另一个就是生产者。"},{"ep":"xb2-10","n":"XB2-10","p":3,"a":"p3","id":"dg4","src":"assets/audio/XB2-10/dg4.mp3","sec":9.672,"t":"第三步，除大气CO2库外，{生产者和消费者都有箭头指向它|brown}的，是分解者；剩下的是消费者。"},{"ep":"xb2-10","n":"XB2-10","p":3,"a":"p3","id":"dg5","src":"assets/audio/XB2-10/dg5.mp3","sec":14.232,"t":"解题方法：双向箭头定两者，箭头最多是大气，指向分解看遗体。图中 A 是生产者，B 是大气CO2库，C 是消费者，D 是分解者。"},{"ep":"xb2-10","n":"XB2-10","p":4,"a":"p4","id":"cl1","src":"assets/audio/XB2-10/cl1.mp3","sec":10.824,"t":"考点四，温室效应与碳中和。化石燃料的大量燃烧，以及森林等植被被破坏，使大气中的CO2浓度升高。"},{"ep":"xb2-10","n":"XB2-10","p":4,"a":"p4","id":"cl2","src":"assets/audio/XB2-10/cl2.mp3","sec":8.832,"t":"CO2等温室气体增多，导致温室效应加剧，全球气候变暖，冰川融化、海平面上升。"},{"ep":"xb2-10","n":"XB2-10","p":4,"a":"p4","id":"cl3","src":"assets/audio/XB2-10/cl3.mp3","sec":8.544,"t":"缓解措施：减少化石燃料的燃烧，开发清洁能源；植树造林，增加CO2的吸收。"},{"ep":"xb2-10","n":"XB2-10","p":4,"a":"p4","id":"cl4","src":"assets/audio/XB2-10/cl4.mp3","sec":15.624,"t":"考法：我国提出力争2030年前实现碳达峰、2060年前实现碳中和。碳中和是指一定时间内，CO2的排放量与吸收量相抵，实现净零排放。"},{"ep":"xb2-10","n":"XB2-10","p":5,"a":"p5","id":"ba1","src":"assets/audio/XB2-10/ba1.mp3","sec":12.312,"t":"考点五，生物富集。生物体从周围环境吸收、积蓄某种元素或难以降解的化合物，使其在机体内浓度超过环境浓度的现象。"},{"ep":"xb2-10","n":"XB2-10","p":5,"a":"p5","id":"ba2","src":"assets/audio/XB2-10/ba2.mp3","sec":7.2,"t":"常见物质：铅、镉、汞等重金属，以及DDT、六六六等有机化合物。"},{"ep":"xb2-10","n":"XB2-10","p":5,"a":"p5","id":"ba3","src":"assets/audio/XB2-10/ba3.mp3","sec":8.616,"t":"这些物质在生物体内难以降解、不易排出，会沿食物链逐级积累，营养级越高，浓度越高。"},{"ep":"xb2-10","n":"XB2-10","p":5,"a":"p5","id":"ba4","src":"assets/audio/XB2-10/ba4.mp3","sec":13.152,"t":"考法：生物富集也具有全球性。比如从未使用过DDT的南极，企鹅体内也检测到了DDT。根据浓度高低，可以反推营养级的高低。"},{"ep":"xb2-10","n":"XB2-10","p":6,"a":"p6","id":"rl1","src":"assets/audio/XB2-10/rl1.mp3","sec":7.92,"t":"考点六，能量流动与物质循环的关系。二者同时进行、相互依存、不可分割。"},{"ep":"xb2-10","n":"XB2-10","p":6,"a":"p6","id":"rl2","src":"assets/audio/XB2-10/rl2.mp3","sec":8.112,"t":"物质是能量的载体，能量沿着食物链流动，就储存在有机物中；能量是物质循环的动力。"},{"ep":"xb2-10","n":"XB2-10","p":6,"a":"p6","id":"rl3","src":"assets/audio/XB2-10/rl3.mp3","sec":6.744,"t":"区别：能量单向流动、逐级递减；物质循环往复、具有全球性。"},{"ep":"xb2-10","n":"XB2-10","p":6,"a":"p6","id":"rl4","src":"assets/audio/XB2-10/rl4.mp3","sec":10.224,"t":"易错：能量不能循环，所以生态系统需要不断输入能量，比如太阳能；而物质在生物圈范围内可以循环利用。"},{"ep":"xb2-10","n":"XB2-10","p":7,"a":"p7","id":"sl1","src":"assets/audio/XB2-10/sl1.mp3","sec":8.64,"t":"考点七，探究土壤微生物的分解作用。案例一：落叶是在土壤微生物的作用下腐烂的吗？"},{"ep":"xb2-10","n":"XB2-10","p":7,"a":"p7","id":"sl2","src":"assets/audio/XB2-10/sl2.mp3","sec":13.2,"t":"实验组：把土壤放在60 ℃恒温箱中处理1小时，尽可能排除土壤微生物的作用，又尽量不改变土壤的理化性质；对照组的土壤不做处理。"},{"ep":"xb2-10","n":"XB2-10","p":7,"a":"p7","id":"sl3","src":"assets/audio/XB2-10/sl3.mp3","sec":5.424,"t":"自变量是土壤微生物的有无，因变量是落叶的腐烂程度。"},{"ep":"xb2-10","n":"XB2-10","p":7,"a":"p7","id":"sl4","src":"assets/audio/XB2-10/sl4.mp3","sec":13.944,"t":"案例二：土壤浸出液加淀粉糊为 A 组，蒸馏水加淀粉糊为 B 组。一段时间后，A 组加碘液不变蓝，B 组变蓝，说明土壤微生物能分解淀粉。"},{"ep":"xb2-10","n":"XB2-10","p":7,"a":"p7","id":"sl5","src":"assets/audio/XB2-10/sl5.mp3","sec":11.136,"t":"易错：被处理的是实验组，自然状态的是对照组。60 ℃处理而不是高温灭菌，是为了避免土壤理化性质改变。"},{"ep":"xb2-10","n":"XB2-10","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-10/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-10","n":"XB2-10","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-10/rv2.mp3","sec":13.248,"t":"判断一：物质循环中的“物质”指化学元素？对。判断二：碳在生物群落内部以CO2形式传递？错，以含碳有机物形式。"},{"ep":"xb2-10","n":"XB2-10","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-10/rv3.mp3","sec":11.208,"t":"判断三：物质循环具有全球性？对。判断四：营养级越高，富集的有害物质浓度越低？错，越高。"},{"ep":"xb2-10","n":"XB2-10","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-10/rv4.mp3","sec":11.328,"t":"判断五：能量是物质循环的动力？对。判断六：对照组土壤要用60 ℃处理？错，处理的是实验组。"},{"ep":"xb2-10","n":"XB2-10","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-10/rv5.mp3","sec":8.04,"t":"七个考点串成一条线：双向箭头找生产者，营养级高富集多。我们下期再见！"},{"ep":"xb2-11","n":"XB2-11","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-11/in1.mp3","sec":8.376,"t":"同学们好！这节课梳理人教版选择性必修二第三章第四节——生态系统的信息传递。"},{"ep":"xb2-11","n":"XB2-11","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-11/in2.mp3","sec":8.256,"t":"高考常考信息种类的判断、信息传递作用的辨析，以及信息传递在农业生产中的应用。"},{"ep":"xb2-11","n":"XB2-11","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-11/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-11","n":"XB2-11","p":1,"a":"p1","id":"kd1","src":"assets/audio/XB2-11/kd1.mp3","sec":5.832,"t":"考点一，信息的种类。生态系统中的信息分为三类。"},{"ep":"xb2-11","n":"XB2-11","p":1,"a":"p1","id":"kd2","src":"assets/audio/XB2-11/kd2.mp3","sec":11.184,"t":"物理信息：光、声、温度、湿度、磁场等，通过物理过程传递的信息。它可以来自非生物环境，也可以来自生物。"},{"ep":"xb2-11","n":"XB2-11","p":1,"a":"p1","id":"kd3","src":"assets/audio/XB2-11/kd3.mp3","sec":10.68,"t":"化学信息：生物在生命活动中产生的、可以传递信息的化学物质，比如植物的生物碱、有机酸，动物的性外激素。"},{"ep":"xb2-11","n":"XB2-11","p":1,"a":"p1","id":"kd4","src":"assets/audio/XB2-11/kd4.mp3","sec":9.768,"t":"行为信息：动物的特殊行为，对于同种或异种生物也能够传递某种信息，比如蜜蜂跳舞、孔雀开屏。"},{"ep":"xb2-11","n":"XB2-11","p":1,"a":"p1","id":"kd5","src":"assets/audio/XB2-11/kd5.mp3","sec":10.2,"t":"考法：给出实例判断信息种类。物理信息可以来自非生物环境，化学信息和行为信息都来自生物。"},{"ep":"xb2-11","n":"XB2-11","p":2,"a":"p2","id":"jd1","src":"assets/audio/XB2-11/jd1.mp3","sec":6.096,"t":"考点二，信息种类的判断。关键看传递信息的载体是什么。"},{"ep":"xb2-11","n":"XB2-11","p":2,"a":"p2","id":"jd2","src":"assets/audio/XB2-11/jd2.mp3","sec":7.488,"t":"萤火虫发光、蝙蝠的回声定位、雄鸟的鸣叫，载体是光和声，都是物理信息。"},{"ep":"xb2-11","n":"XB2-11","p":2,"a":"p2","id":"jd3","src":"assets/audio/XB2-11/jd3.mp3","sec":7.056,"t":"狗用尿液标记领地、昆虫的性外激素，载体是化学物质，都是化学信息。"},{"ep":"xb2-11","n":"XB2-11","p":2,"a":"p2","id":"jd4","src":"assets/audio/XB2-11/jd4.mp3","sec":7.896,"t":"蜜蜂跳圆圈舞或摆尾舞、雄鸟求偶时的炫耀动作，载体是动作，都是行为信息。"},{"ep":"xb2-11","n":"XB2-11","p":2,"a":"p2","id":"jd5","src":"assets/audio/XB2-11/jd5.mp3","sec":8.808,"t":"易错：同一只雄鸟，鸣叫是物理信息，炫耀动作是行为信息。不要看生物，要看载体。"},{"ep":"xb2-11","n":"XB2-11","p":3,"a":"p3","id":"pc1","src":"assets/audio/XB2-11/pc1.mp3","sec":4.92,"t":"考点三，信息传递的过程。需要三个要素。"},{"ep":"xb2-11","n":"XB2-11","p":3,"a":"p3","id":"pc2","src":"assets/audio/XB2-11/pc2.mp3","sec":10.488,"t":"信息源：信息产生的部位；信道：信息传播的媒介，比如空气、水；信息受体：信息接收的生物或部位。"},{"ep":"xb2-11","n":"XB2-11","p":3,"a":"p3","id":"pc3","src":"assets/audio/XB2-11/pc3.mp3","sec":7.128,"t":"生物与生物之间的信息传递往往是双向的，比如捕食者和被捕食者之间。"},{"ep":"xb2-11","n":"XB2-11","p":3,"a":"p3","id":"pc4","src":"assets/audio/XB2-11/pc4.mp3","sec":11.232,"t":"易错：非生物环境可以作为信息源，比如光照；但它不能接收信息，所以生物与非生物环境之间的信息传递是单向的。"},{"ep":"xb2-11","n":"XB2-11","p":4,"a":"p4","id":"rl1","src":"assets/audio/XB2-11/rl1.mp3","sec":3.912,"t":"考点四，信息传递的作用，有三条。"},{"ep":"xb2-11","n":"XB2-11","p":4,"a":"p4","id":"rl2","src":"assets/audio/XB2-11/rl2.mp3","sec":12.936,"t":"第一，生命活动的正常进行离不开信息的作用。比如莴苣种子必须接受某种波长的光信息才能萌发，蝙蝠靠回声定位捕食和飞行。"},{"ep":"xb2-11","n":"XB2-11","p":4,"a":"p4","id":"rl3","src":"assets/audio/XB2-11/rl3.mp3","sec":10.392,"t":"第二，生物种群的繁衍离不开信息的传递。比如植物开花需要光信息的刺激，昆虫靠性外激素吸引异性。"},{"ep":"xb2-11","n":"XB2-11","p":4,"a":"p4","id":"rl4","src":"assets/audio/XB2-11/rl4.mp3","sec":12.888,"t":"第三，信息能够调节生物的种间关系，进而维持生态系统的平衡与稳定。比如狼根据兔留下的气味去追捕，兔也能根据狼的气味躲避。"},{"ep":"xb2-11","n":"XB2-11","p":4,"a":"p4","id":"rl5","src":"assets/audio/XB2-11/rl5.mp3","sec":13.68,"t":"解题方法：看信息作用于谁。作用于个体自身，是生命活动正常进行；涉及同种异性，是种群繁衍；涉及不同物种，是调节种间关系。"},{"ep":"xb2-11","n":"XB2-11","p":5,"a":"p5","id":"fm1","src":"assets/audio/XB2-11/fm1.mp3","sec":7.248,"t":"考点五，信息传递在农业生产中的应用。第一，提高农畜产品的产量。"},{"ep":"xb2-11","n":"XB2-11","p":5,"a":"p5","id":"fm2","src":"assets/audio/XB2-11/fm2.mp3","sec":10.584,"t":"比如用模拟的动物信息吸引大量传粉动物，提高果树的传粉率和结实率；延长光照时间，提高家禽的产蛋率。"},{"ep":"xb2-11","n":"XB2-11","p":5,"a":"p5","id":"fm3","src":"assets/audio/XB2-11/fm3.mp3","sec":10.32,"t":"第二，对有害动物进行控制。比如用人工合成的性引诱剂诱捕害虫，或者干扰害虫交配，降低出生率。"},{"ep":"xb2-11","n":"XB2-11","p":5,"a":"p5","id":"fm4","src":"assets/audio/XB2-11/fm4.mp3","sec":9.6,"t":"易错：利用信息素防治害虫属于生物防治，不是化学防治。生物防治对人类生存环境无污染。"},{"ep":"xb2-11","n":"XB2-11","p":6,"a":"p6","id":"cp1","src":"assets/audio/XB2-11/cp1.mp3","sec":7.272,"t":"考点六，生态系统三大功能的比较：能量流动、物质循环和信息传递。"},{"ep":"xb2-11","n":"XB2-11","p":6,"a":"p6","id":"cp2","src":"assets/audio/XB2-11/cp2.mp3","sec":9.984,"t":"范围：能量流动沿食物链和食物网；物质循环在生物圈；信息传递在生物与生物、生物与环境之间。"},{"ep":"xb2-11","n":"XB2-11","p":6,"a":"p6","id":"cp3","src":"assets/audio/XB2-11/cp3.mp3","sec":8.928,"t":"特点：能量单向流动、逐级递减；物质循环往复、全球性；信息传递往往是双向的。"},{"ep":"xb2-11","n":"XB2-11","p":6,"a":"p6","id":"cp4","src":"assets/audio/XB2-11/cp4.mp3","sec":10.632,"t":"考法：三者把生态系统的各个组分联系成一个统一的整体；信息传递决定着能量流动和物质循环的方向和状态。"},{"ep":"xb2-11","n":"XB2-11","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-11/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-11","n":"XB2-11","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-11/rv2.mp3","sec":10.848,"t":"判断一：蜜蜂跳舞属于物理信息？错，属于行为信息。判断二：萤火虫发光属于物理信息？对。"},{"ep":"xb2-11","n":"XB2-11","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-11/rv3.mp3","sec":14.688,"t":"判断三：信息只能在生物与生物之间传递？错，也可来自非生物环境。判断四：用性引诱剂诱杀害虫属于化学防治？错，属于生物防治。"},{"ep":"xb2-11","n":"XB2-11","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-11/rv4.mp3","sec":10.944,"t":"判断五：信息传递能调节生物的种间关系？对。判断六：生物之间的信息传递往往是双向的？对。"},{"ep":"xb2-11","n":"XB2-11","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-11/rv5.mp3","sec":7.104,"t":"六个考点串成一条线：看载体定种类，看对象定作用。我们下期再见！"},{"ep":"xb2-12","n":"XB2-12","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-12/in1.mp3","sec":8.16,"t":"同学们好！这节课梳理人教版选择性必修二第三章第五节——生态系统的稳定性。"},{"ep":"xb2-12","n":"XB2-12","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-12/in2.mp3","sec":8.352,"t":"高考常考负反馈调节、抵抗力稳定性与恢复力稳定性的比较，以及生态缸的设计要求。"},{"ep":"xb2-12","n":"XB2-12","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-12/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-12","n":"XB2-12","p":1,"a":"p1","id":"bl1","src":"assets/audio/XB2-12/bl1.mp3","sec":8.88,"t":"考点一，生态平衡。生态系统的结构和功能处于相对稳定的一种状态，就是生态平衡。"},{"ep":"xb2-12","n":"XB2-12","p":1,"a":"p1","id":"bl2","src":"assets/audio/XB2-12/bl2.mp3","sec":14.976,"t":"它有三个特征：结构平衡，各组分保持相对稳定；功能平衡，生产、消费、分解的生态过程正常进行；收支平衡，物质和能量的输入与输出基本相等。"},{"ep":"xb2-12","n":"XB2-12","p":1,"a":"p1","id":"bl3","src":"assets/audio/XB2-12/bl3.mp3","sec":10.704,"t":"维持生态平衡的机制是负反馈调节。比如森林中害虫增多，食虫鸟因食物充足而增多，害虫又被抑制。"},{"ep":"xb2-12","n":"XB2-12","p":1,"a":"p1","id":"bl4","src":"assets/audio/XB2-12/bl4.mp3","sec":10.704,"t":"易错：负反馈使系统趋于稳定；正反馈使系统偏离稳态，比如湖泊污染后鱼类死亡、腐烂，污染进一步加重。"},{"ep":"xb2-12","n":"XB2-12","p":2,"a":"p2","id":"sr1","src":"assets/audio/XB2-12/sr1.mp3","sec":11.736,"t":"考点二，生态系统的稳定性。生态系统维持或恢复自身结构与功能处于相对平衡状态的能力，叫做生态系统的稳定性。"},{"ep":"xb2-12","n":"XB2-12","p":2,"a":"p2","id":"sr2","src":"assets/audio/XB2-12/sr2.mp3","sec":9.72,"t":"生态系统之所以能维持相对稳定，是因为它具有自我调节能力，而负反馈调节是自我调节能力的基础。"},{"ep":"xb2-12","n":"XB2-12","p":2,"a":"p2","id":"sr3","src":"assets/audio/XB2-12/sr3.mp3","sec":12.432,"t":"易错：自我调节能力是有一定限度的。当外界干扰因素的强度超过一定限度时，自我调节能力会迅速丧失，生态系统就难以恢复。"},{"ep":"xb2-12","n":"XB2-12","p":3,"a":"p3","id":"tw1","src":"assets/audio/XB2-12/tw1.mp3","sec":4.44,"t":"考点三，抵抗力稳定性与恢复力稳定性。"},{"ep":"xb2-12","n":"XB2-12","p":3,"a":"p3","id":"tw2","src":"assets/audio/XB2-12/tw2.mp3","sec":7.872,"t":"抵抗力稳定性：生态系统抵抗外界干扰并使自身的结构与功能保持原状的能力。"},{"ep":"xb2-12","n":"XB2-12","p":3,"a":"p3","id":"tw3","src":"assets/audio/XB2-12/tw3.mp3","sec":7.416,"t":"恢复力稳定性：生态系统在受到外界干扰因素的破坏后恢复到原状的能力。"},{"ep":"xb2-12","n":"XB2-12","p":3,"a":"p3","id":"tw4","src":"assets/audio/XB2-12/tw4.mp3","sec":9.96,"t":"看曲线：偏离正常范围的幅度越小，抵抗力稳定性越强；恢复所需的时间越短，恢复力稳定性越强。"},{"ep":"xb2-12","n":"XB2-12","p":3,"a":"p3","id":"tw5","src":"assets/audio/XB2-12/tw5.mp3","sec":9.816,"t":"解题方法：区分两者，就看是“保持原状”还是“恢复原状”。被破坏之前比抵抗，被破坏之后比恢复。"},{"ep":"xb2-12","n":"XB2-12","p":4,"a":"p4","id":"rl1","src":"assets/audio/XB2-12/rl1.mp3","sec":10.296,"t":"考点四，两种稳定性的关系。一般来说，生态系统中的组分越多，食物网越复杂，自我调节能力就越强。"},{"ep":"xb2-12","n":"XB2-12","p":4,"a":"p4","id":"rl2","src":"assets/audio/XB2-12/rl2.mp3","sec":11.64,"t":"所以抵抗力稳定性越高，而恢复力稳定性往往越低。比如热带雨林抵抗力稳定性高，草原遭破坏后恢复得较快。"},{"ep":"xb2-12","n":"XB2-12","p":4,"a":"p4","id":"rl3","src":"assets/audio/XB2-12/rl3.mp3","sec":10.8,"t":"但也有例外：北极冻原和荒漠，物种少、结构简单，环境条件又恶劣，抵抗力稳定性和恢复力稳定性都很低。"},{"ep":"xb2-12","n":"XB2-12","p":4,"a":"p4","id":"rl4","src":"assets/audio/XB2-12/rl4.mp3","sec":9.816,"t":"易错：两者一般呈负相关，但不是绝对的。答题时不能说“抵抗力稳定性低，恢复力稳定性一定高”。"},{"ep":"xb2-12","n":"XB2-12","p":5,"a":"p5","id":"im1","src":"assets/audio/XB2-12/im1.mp3","sec":4.104,"t":"考点五，提高生态系统稳定性的措施。"},{"ep":"xb2-12","n":"XB2-12","p":5,"a":"p5","id":"im2","src":"assets/audio/XB2-12/im2.mp3","sec":9.12,"t":"第一，控制对生态系统的干扰强度，在不超过自我调节能力的范围内，合理适度地利用生态系统。"},{"ep":"xb2-12","n":"XB2-12","p":5,"a":"p5","id":"im3","src":"assets/audio/XB2-12/im3.mp3","sec":12.624,"t":"第二，对人类利用强度较大的生态系统，应给予相应的物质、能量的投入，保证内部结构与功能的协调。比如农田要施肥、灌溉。"},{"ep":"xb2-12","n":"XB2-12","p":5,"a":"p5","id":"im4","src":"assets/audio/XB2-12/im4.mp3","sec":11.448,"t":"考法：问如何提高稳定性。答：适当增加物种种类，使营养结构更复杂；控制干扰强度；给予物质和能量投入。"},{"ep":"xb2-12","n":"XB2-12","p":6,"a":"p6","id":"tk1","src":"assets/audio/XB2-12/tk1.mp3","sec":4.68,"t":"考点六，设计制作生态缸，观察其稳定性。"},{"ep":"xb2-12","n":"XB2-12","p":6,"a":"p6","id":"tk2","src":"assets/audio/XB2-12/tk2.mp3","sec":6.744,"t":"密封：生态缸必须是封闭的，防止外界生物和非生物因素的干扰。"},{"ep":"xb2-12","n":"XB2-12","p":6,"a":"p6","id":"tk3","src":"assets/audio/XB2-12/tk3.mp3","sec":9.288,"t":"成分齐全：要有非生物的物质和能量、生产者、消费者和分解者，各种生物之间要有营养关系。"},{"ep":"xb2-12","n":"XB2-12","p":6,"a":"p6","id":"tk4","src":"assets/audio/XB2-12/tk4.mp3","sec":6.696,"t":"比例适中：投放的动物不宜过多，个体也不宜太大，以免破坏食物链。"},{"ep":"xb2-12","n":"XB2-12","p":6,"a":"p6","id":"tk5","src":"assets/audio/XB2-12/tk5.mp3","sec":11.976,"t":"透明：生态缸的材料要透明，为光合作用提供光能；放置在室内通风、光线良好的地方，但要避免阳光直射，以免温度过高。"},{"ep":"xb2-12","n":"XB2-12","p":6,"a":"p6","id":"tk6","src":"assets/audio/XB2-12/tk6.mp3","sec":12.984,"t":"考法：生态缸的稳定性比自然生态系统低，因为物种少、营养结构简单、自我调节能力弱。观察记录生物的存活时间来判断稳定性。"},{"ep":"xb2-12","n":"XB2-12","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-12/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-12","n":"XB2-12","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-12/rv2.mp3","sec":12.528,"t":"判断一：负反馈调节是自我调节能力的基础？对。判断二：生态系统的自我调节能力是无限的？错，是有一定限度的。"},{"ep":"xb2-12","n":"XB2-12","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-12/rv3.mp3","sec":13.368,"t":"判断三：热带雨林的抵抗力稳定性比草原高？对。判断四：抵抗力稳定性低，恢复力稳定性一定高？错，冻原、荒漠都低。"},{"ep":"xb2-12","n":"XB2-12","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-12/rv4.mp3","sec":12.072,"t":"判断五：生态缸应放在阳光直射的地方？错，要避免阳光直射。判断六：生态缸中投放的动物不宜过多？对。"},{"ep":"xb2-12","n":"XB2-12","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-12/rv5.mp3","sec":7.992,"t":"六个考点串成一条线：结构越复杂越抗扰，冻原荒漠两头低。我们下期再见！"},{"ep":"xb2-13","n":"XB2-13","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-13/in1.mp3","sec":9.0,"t":"同学们好！这节课梳理人教版选择性必修二第四章第一节——人类活动对生态环境的影响。"},{"ep":"xb2-13","n":"XB2-13","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-13/in2.mp3","sec":7.68,"t":"高考常考生态足迹的含义与影响因素，以及全球性生态环境问题的成因和对策。"},{"ep":"xb2-13","n":"XB2-13","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-13/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-13","n":"XB2-13","p":1,"a":"p1","id":"fp1","src":"assets/audio/XB2-13/fp1.mp3","sec":14.928,"t":"考点一，生态足迹的概念。生态足迹，又叫生态占用，是指在现有技术条件下，维持某一人口单位生存所需的生产资源和吸纳废物的土地及水域的面积。"},{"ep":"xb2-13","n":"XB2-13","p":1,"a":"p1","id":"fp2","src":"assets/audio/XB2-13/fp2.mp3","sec":6.024,"t":"“某一人口单位”可以是一个人、一个城市、一个国家，甚至全人类。"},{"ep":"xb2-13","n":"XB2-13","p":1,"a":"p1","id":"fp3","src":"assets/audio/XB2-13/fp3.mp3","sec":7.344,"t":"生态足迹的值越大，代表人类所需的资源越多，对生态和环境的影响就越大。"},{"ep":"xb2-13","n":"XB2-13","p":1,"a":"p1","id":"fp4","src":"assets/audio/XB2-13/fp4.mp3","sec":13.896,"t":"易错：生态足迹包括两部分：生产资源所需的面积，以及吸纳废物所需的面积，比如吸收CO2所需的森林面积。只答一半是常见失分点。"},{"ep":"xb2-13","n":"XB2-13","p":2,"a":"p2","id":"fc1","src":"assets/audio/XB2-13/fc1.mp3","sec":7.968,"t":"考点二，生态足迹的影响因素。生态足迹的大小，与人的生活方式密切相关。"},{"ep":"xb2-13","n":"XB2-13","p":2,"a":"p2","id":"fc2","src":"assets/audio/XB2-13/fc2.mp3","sec":9.888,"t":"比如，与步行相比，开车出行会增大生态足迹，因为汽车要消耗资源，还要吸收尾气中的CO2。"},{"ep":"xb2-13","n":"XB2-13","p":2,"a":"p2","id":"fc3","src":"assets/audio/XB2-13/fc3.mp3","sec":11.688,"t":"又比如，多吃肉会比多吃蔬菜增大生态足迹，因为食物链越长，能量流动中散失的能量越多，需要的耕地和草场也越多。"},{"ep":"xb2-13","n":"XB2-13","p":2,"a":"p2","id":"fc4","src":"assets/audio/XB2-13/fc4.mp3","sec":13.464,"t":"考法：问怎样减小生态足迹。答：低碳出行、节约用水用电、减少浪费、适当多吃素食等。人口增长也会使总的生态足迹增大。"},{"ep":"xb2-13","n":"XB2-13","p":3,"a":"p3","id":"cl1","src":"assets/audio/XB2-13/cl1.mp3","sec":10.896,"t":"考点三，全球气候变化。成因：化石燃料的大量燃烧，以及植被破坏，使大气中CO2等温室气体增多。"},{"ep":"xb2-13","n":"XB2-13","p":3,"a":"p3","id":"cl2","src":"assets/audio/XB2-13/cl2.mp3","sec":9.216,"t":"后果：全球气候变暖，冰川融化、海平面上升，极端天气增多，影响农业生产和生物分布。"},{"ep":"xb2-13","n":"XB2-13","p":3,"a":"p3","id":"cl3","src":"assets/audio/XB2-13/cl3.mp3","sec":8.688,"t":"对策：减少化石燃料燃烧，开发清洁能源；大力植树造林，增加对CO2的吸收。"},{"ep":"xb2-13","n":"XB2-13","p":4,"a":"p4","id":"oz1","src":"assets/audio/XB2-13/oz1.mp3","sec":8.64,"t":"考点四，臭氧层破坏与酸雨。臭氧层能吸收太阳光中的紫外线，保护地球上的生物。"},{"ep":"xb2-13","n":"XB2-13","p":4,"a":"p4","id":"oz2","src":"assets/audio/XB2-13/oz2.mp3","sec":12.24,"t":"臭氧层破坏的主要原因是人类使用的氟氯烃等物质。臭氧层变薄，到达地面的紫外线增多，会使人类皮肤癌、白内障的发病率升高。"},{"ep":"xb2-13","n":"XB2-13","p":4,"a":"p4","id":"oz3","src":"assets/audio/XB2-13/oz3.mp3","sec":9.552,"t":"酸雨主要由燃烧煤、石油等释放的硫和氮的氧化物引起，会使水体和土壤酸化，危害植物和水生生物。"},{"ep":"xb2-13","n":"XB2-13","p":4,"a":"p4","id":"oz4","src":"assets/audio/XB2-13/oz4.mp3","sec":10.272,"t":"易错：三大问题的“元凶”不要混：温室效应——CO2；臭氧层破坏——氟氯烃；酸雨——硫和氮的氧化物。"},{"ep":"xb2-13","n":"XB2-13","p":5,"a":"p5","id":"wt1","src":"assets/audio/XB2-13/wt1.mp3","sec":3.84,"t":"考点五，其他全球性生态环境问题。"},{"ep":"xb2-13","n":"XB2-13","p":5,"a":"p5","id":"wt2","src":"assets/audio/XB2-13/wt2.mp3","sec":8.736,"t":"水资源短缺：人口增长、用水量增加，加上水体污染，使可利用的淡水资源越来越少。"},{"ep":"xb2-13","n":"XB2-13","p":5,"a":"p5","id":"wt3","src":"assets/audio/XB2-13/wt3.mp3","sec":11.544,"t":"土地荒漠化：主要原因是过度放牧、过度开垦、滥伐森林等不合理的人类活动，图片中的美国大平原沙尘暴就是典型例子。"},{"ep":"xb2-13","n":"XB2-13","p":5,"a":"p5","id":"wt4","src":"assets/audio/XB2-13/wt4.mp3","sec":6.144,"t":"还有生物多样性丧失和环境污染，比如海洋中的塑料垃圾污染。"},{"ep":"xb2-13","n":"XB2-13","p":5,"a":"p5","id":"wt5","src":"assets/audio/XB2-13/wt5.mp3","sec":8.712,"t":"解题方法：答环境问题题目，按“原因 → 危害 → 对策”三步写，原因多数指向不合理的人类活动。"},{"ep":"xb2-13","n":"XB2-13","p":6,"a":"p6","id":"su1","src":"assets/audio/XB2-13/su1.mp3","sec":9.936,"t":"考点六，可持续发展。可持续发展是指在不牺牲未来几代人需要的情况下，满足我们这代人的需要。"},{"ep":"xb2-13","n":"XB2-13","p":6,"a":"p6","id":"su2","src":"assets/audio/XB2-13/su2.mp3","sec":5.664,"t":"它追求的是自然、经济、社会的持久而协调的发展。"},{"ep":"xb2-13","n":"XB2-13","p":6,"a":"p6","id":"su3","src":"assets/audio/XB2-13/su3.mp3","sec":10.848,"t":"解决环境问题的思路：控制人口增长，转变生产和生活方式，减小生态足迹，提高资源利用率，保护生态环境。"},{"ep":"xb2-13","n":"XB2-13","p":6,"a":"p6","id":"su4","src":"assets/audio/XB2-13/su4.mp3","sec":8.904,"t":"易错：可持续发展不是禁止开发利用自然资源，而是合理利用，兼顾当代人和后代人的需要。"},{"ep":"xb2-13","n":"XB2-13","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-13/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-13","n":"XB2-13","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-13/rv2.mp3","sec":11.304,"t":"判断一：生态足迹越大，对生态环境的影响越大？对。判断二：生态足迹的值与生活方式无关？错。"},{"ep":"xb2-13","n":"XB2-13","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-13/rv3.mp3","sec":14.232,"t":"判断三：全球变暖主要由CO2等温室气体增多引起？对。判断四：臭氧层破坏主要由CO2引起？错，主要由氟氯烃引起。"},{"ep":"xb2-13","n":"XB2-13","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-13/rv4.mp3","sec":12.504,"t":"判断五：酸雨主要由硫和氮的氧化物引起？对。判断六：可持续发展就是禁止开发利用自然资源？错，是合理利用。"},{"ep":"xb2-13","n":"XB2-13","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-13/rv5.mp3","sec":8.112,"t":"六个考点串成一条线：足迹越大压力越大，合理利用才能持续。我们下期再见！"},{"ep":"xb2-14","n":"XB2-14","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-14/in1.mp3","sec":8.424,"t":"同学们好！这节课梳理人教版选择性必修二第四章第二节——生物多样性及其保护。"},{"ep":"xb2-14","n":"XB2-14","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-14/in2.mp3","sec":9.192,"t":"高考常考生物多样性价值类型的判断、生物多样性丧失的原因，以及就地保护和易地保护的区别。"},{"ep":"xb2-14","n":"XB2-14","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-14/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-14","n":"XB2-14","p":1,"a":"p1","id":"lv1","src":"assets/audio/XB2-14/lv1.mp3","sec":13.896,"t":"考点一，生物多样性的三个层次。生物圈内所有的植物、动物和微生物等，它们所拥有的全部基因以及各种各样的生态系统，共同构成了生物多样性。"},{"ep":"xb2-14","n":"XB2-14","p":1,"a":"p1","id":"lv2","src":"assets/audio/XB2-14/lv2.mp3","sec":8.928,"t":"遗传多样性，也叫基因多样性：同种生物的不同个体之间基因不同，比如水稻有许多品种。"},{"ep":"xb2-14","n":"XB2-14","p":1,"a":"p1","id":"lv3","src":"assets/audio/XB2-14/lv3.mp3","sec":6.936,"t":"物种多样性：地球上生物种类的多样，比如我国特有的大熊猫、金丝猴。"},{"ep":"xb2-14","n":"XB2-14","p":1,"a":"p1","id":"lv4","src":"assets/audio/XB2-14/lv4.mp3","sec":7.104,"t":"生态系统多样性：森林、草原、湿地、海洋等各种生态系统的多样。"},{"ep":"xb2-14","n":"XB2-14","p":1,"a":"p1","id":"lv5","src":"assets/audio/XB2-14/lv5.mp3","sec":13.464,"t":"考法：判断属于哪个层次。解题方法：同种内部不同，是遗传多样性；不同物种，是物种多样性；不同环境类型，是生态系统多样性。"},{"ep":"xb2-14","n":"XB2-14","p":2,"a":"p2","id":"va1","src":"assets/audio/XB2-14/va1.mp3","sec":3.936,"t":"考点二，生物多样性的价值有三种。"},{"ep":"xb2-14","n":"XB2-14","p":2,"a":"p2","id":"va2","src":"assets/audio/XB2-14/va2.mp3","sec":11.688,"t":"直接价值：对人类有食用、药用和作为工业原料等实用意义的，以及有旅游观赏、科学研究和文学艺术创作等非实用意义的。"},{"ep":"xb2-14","n":"XB2-14","p":2,"a":"p2","id":"va3","src":"assets/audio/XB2-14/va3.mp3","sec":11.664,"t":"间接价值：对生态系统起到重要调节作用的价值，也叫生态功能。比如保持水土、蓄洪防旱、调节气候、净化水质。"},{"ep":"xb2-14","n":"XB2-14","p":2,"a":"p2","id":"va4","src":"assets/audio/XB2-14/va4.mp3","sec":4.224,"t":"潜在价值：目前人类尚不太清楚的价值。"},{"ep":"xb2-14","n":"XB2-14","p":2,"a":"p2","id":"va5","src":"assets/audio/XB2-14/va5.mp3","sec":5.496,"t":"易错：生物多样性的间接价值明显大于它的直接价值。"},{"ep":"xb2-14","n":"XB2-14","p":3,"a":"p3","id":"jd1","src":"assets/audio/XB2-14/jd1.mp3","sec":4.704,"t":"考点三，价值类型的判断，这是高考最爱考的。"},{"ep":"xb2-14","n":"XB2-14","p":3,"a":"p3","id":"jd2","src":"assets/audio/XB2-14/jd2.mp3","sec":8.688,"t":"芦苇可以造纸、青蒿素治疟疾、到湿地旅游、根据蝙蝠回声定位发明雷达，都是直接价值。"},{"ep":"xb2-14","n":"XB2-14","p":3,"a":"p3","id":"jd3","src":"assets/audio/XB2-14/jd3.mp3","sec":7.416,"t":"湿地蓄洪防旱、森林保持水土、植物光合作用制造氧气，都是间接价值。"},{"ep":"xb2-14","n":"XB2-14","p":3,"a":"p3","id":"jd4","src":"assets/audio/XB2-14/jd4.mp3","sec":16.368,"t":"解题方法：问一句“是不是对生态系统起调节作用”？是，就是间接价值；对人类有直接用途，包括科研和观赏、文学艺术创作，是直接价值；还不知道的，是潜在价值。"},{"ep":"xb2-14","n":"XB2-14","p":4,"a":"p4","id":"ls1","src":"assets/audio/XB2-14/ls1.mp3","sec":3.6,"t":"考点四，生物多样性丧失的原因。"},{"ep":"xb2-14","n":"XB2-14","p":4,"a":"p4","id":"ls2","src":"assets/audio/XB2-14/ls2.mp3","sec":10.608,"t":"栖息地的丧失和碎片化，这是最主要的原因。比如道路把一片森林分割成若干小块，大型动物的种群被隔开。"},{"ep":"xb2-14","n":"XB2-14","p":4,"a":"p4","id":"ls3","src":"assets/audio/XB2-14/ls3.mp3","sec":5.208,"t":"对野生物种的掠夺式利用，比如乱捕滥杀、过度采伐。"},{"ep":"xb2-14","n":"XB2-14","p":4,"a":"p4","id":"ls4","src":"assets/audio/XB2-14/ls4.mp3","sec":9.024,"t":"还有环境污染、农业和林业品种的单一化，以及外来物种的盲目引入，比如水葫芦、福寿螺的入侵。"},{"ep":"xb2-14","n":"XB2-14","p":4,"a":"p4","id":"ls5","src":"assets/audio/XB2-14/ls5.mp3","sec":10.224,"t":"易错：外来物种入侵不是最主要的原因；而且引入外来物种不一定增加当地的生物多样性，往往会使其降低。"},{"ep":"xb2-14","n":"XB2-14","p":5,"a":"p5","id":"pt1","src":"assets/audio/XB2-14/pt1.mp3","sec":3.552,"t":"考点五，保护生物多样性的措施。"},{"ep":"xb2-14","n":"XB2-14","p":5,"a":"p5","id":"pt2","src":"assets/audio/XB2-14/pt2.mp3","sec":10.584,"t":"就地保护：在原地对被保护的生态系统或物种建立自然保护区以及国家公园等，这是对生物多样性最有效的保护。"},{"ep":"xb2-14","n":"XB2-14","p":5,"a":"p5","id":"pt3","src":"assets/audio/XB2-14/pt3.mp3","sec":10.824,"t":"易地保护：把待保护物种从原地迁出，在异地进行专门保护，比如建立植物园、动物园、濒危动植物繁育中心。"},{"ep":"xb2-14","n":"XB2-14","p":5,"a":"p5","id":"pt4","src":"assets/audio/XB2-14/pt4.mp3","sec":10.344,"t":"还可以利用生物技术保护，比如建立精子库、种子库、基因库，利用人工授精、组织培养和胚胎移植等技术。"},{"ep":"xb2-14","n":"XB2-14","p":5,"a":"p5","id":"pt5","src":"assets/audio/XB2-14/pt5.mp3","sec":10.08,"t":"考法：区分就地和易地，看有没有迁出原地。另外，加强立法、执法和宣传教育也是重要措施。"},{"ep":"xb2-14","n":"XB2-14","p":6,"a":"p6","id":"bl1","src":"assets/audio/XB2-14/bl1.mp3","sec":3.744,"t":"考点六，协调人与生态环境的关系。"},{"ep":"xb2-14","n":"XB2-14","p":6,"a":"p6","id":"bl2","src":"assets/audio/XB2-14/bl2.mp3","sec":8.928,"t":"保护生物多样性，只是反对盲目地、掠夺式地开发利用大自然，并不意味着禁止开发和利用。"},{"ep":"xb2-14","n":"XB2-14","p":6,"a":"p6","id":"bl3","src":"assets/audio/XB2-14/bl3.mp3","sec":9.192,"t":"合理利用就是最好的保护。比如在保护区周边发展生态旅游，适度、有计划地捕捞和采伐。"},{"ep":"xb2-14","n":"XB2-14","p":6,"a":"p6","id":"bl4","src":"assets/audio/XB2-14/bl4.mp3","sec":10.848,"t":"考法：问保护与利用的关系。答：保护和利用并不矛盾，要在保护的前提下合理开发利用，实现可持续发展。"},{"ep":"xb2-14","n":"XB2-14","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-14/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-14","n":"XB2-14","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-14/rv2.mp3","sec":13.56,"t":"判断一：生物多样性包括遗传、物种、生态系统多样性？对。判断二：湿地蓄洪防旱体现了直接价值？错，是间接价值。"},{"ep":"xb2-14","n":"XB2-14","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-14/rv3.mp3","sec":13.104,"t":"判断三：间接价值明显大于直接价值？对。判断四：外来物种入侵是最主要原因？错，最主要是栖息地丧失和碎片化。"},{"ep":"xb2-14","n":"XB2-14","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-14/rv4.mp3","sec":13.44,"t":"判断五：建立自然保护区是最有效的保护措施？对。判断六：保护生物多样性就是禁止开发利用？错，合理利用就是最好的保护。"},{"ep":"xb2-14","n":"XB2-14","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-14/rv5.mp3","sec":7.872,"t":"六个考点串成一条线：间接价值大于直接，就地保护最有效。我们下期再见！"},{"ep":"xb2-15","n":"XB2-15","p":0,"a":"intro","id":"in1","src":"assets/audio/XB2-15/in1.mp3","sec":9.456,"t":"同学们好！这节课梳理人教版选择性必修二第四章第三节——生态工程，也是选必二的最后一节。"},{"ep":"xb2-15","n":"XB2-15","p":0,"a":"intro","id":"in2","src":"assets/audio/XB2-15/in2.mp3","sec":9.576,"t":"高考常考生态工程四个基本原理的判断，以及农村综合发展型、湿地和矿区生态恢复工程的分析。"},{"ep":"xb2-15","n":"XB2-15","p":0,"a":"intro","id":"in3","src":"assets/audio/XB2-15/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb2-15","n":"XB2-15","p":1,"a":"p1","id":"cc1","src":"assets/audio/XB2-15/cc1.mp3","sec":15.816,"t":"考点一，生态工程的概念。应用生态学和系统学等学科的基本原理和方法，对人工生态系统进行分析、设计和调控，或对已被破坏的生态环境进行修复、重建。"},{"ep":"xb2-15","n":"XB2-15","p":1,"a":"p1","id":"cc2","src":"assets/audio/XB2-15/cc2.mp3","sec":4.728,"t":"它的目的是促进人类社会与自然环境和谐发展。"},{"ep":"xb2-15","n":"XB2-15","p":1,"a":"p1","id":"cc3","src":"assets/audio/XB2-15/cc3.mp3","sec":7.2,"t":"与传统工程相比，生态工程是一类少消耗、多效益、可持续的工程体系。"},{"ep":"xb2-15","n":"XB2-15","p":1,"a":"p1","id":"cc4","src":"assets/audio/XB2-15/cc4.mp3","sec":11.232,"t":"考法：生态工程的特点“少消耗、多效益、可持续”要记牢；它遵循的是自生、循环、协调、整体四个基本原理。"},{"ep":"xb2-15","n":"XB2-15","p":2,"a":"p2","id":"sf1","src":"assets/audio/XB2-15/sf1.mp3","sec":10.056,"t":"考点二，自生原理。由生物组分而产生的自组织、自我调节和自我更新、维持，就是系统的自生。"},{"ep":"xb2-15","n":"XB2-15","p":2,"a":"p2","id":"sf2","src":"assets/audio/XB2-15/sf2.mp3","sec":11.424,"t":"要实现自生，需要有效选择生物组分并合理布设，比如选择污染物净化能力较强的多种水生植物，并考虑它们的生态位差异。"},{"ep":"xb2-15","n":"XB2-15","p":2,"a":"p2","id":"sf3","src":"assets/audio/XB2-15/sf3.mp3","sec":7.608,"t":"还要创造有益于生物组分生长、发育、繁殖，以及它们形成互利共存关系的条件。"},{"ep":"xb2-15","n":"XB2-15","p":2,"a":"p2","id":"sf4","src":"assets/audio/XB2-15/sf4.mp3","sec":9.048,"t":"关键词：生物多样性、多种生物、合理布设、互利共存。看到这些，就想到自生原理。"},{"ep":"xb2-15","n":"XB2-15","p":3,"a":"p3","id":"cy1","src":"assets/audio/XB2-15/cy1.mp3","sec":13.224,"t":"考点三，循环原理。在生态工程中促进系统的物质迁移与转化，既保证各个环节的物质迁移顺畅，也保证主要物质或元素的转化率较高。"},{"ep":"xb2-15","n":"XB2-15","p":3,"a":"p3","id":"cy2","src":"assets/audio/XB2-15/cy2.mp3","sec":9.216,"t":"通过系统设计，使前一环节产生的废物尽可能地被后一环节利用，减少整个生产环节“废物”的产生。"},{"ep":"xb2-15","n":"XB2-15","p":3,"a":"p3","id":"cy3","src":"assets/audio/XB2-15/cy3.mp3","sec":9.6,"t":"典型例子是“无废弃物农业”：秸秆、粪便等进入沼气池，沼渣、沼液还田，实现物质的循环利用。"},{"ep":"xb2-15","n":"XB2-15","p":3,"a":"p3","id":"cy4","src":"assets/audio/XB2-15/cy4.mp3","sec":8.832,"t":"关键词：物质循环、废物利用、无废弃物、多级利用。看到这些，就想到循环原理。"},{"ep":"xb2-15","n":"XB2-15","p":4,"a":"p4","id":"hm1","src":"assets/audio/XB2-15/hm1.mp3","sec":6.984,"t":"考点四，协调原理。处理好生物与环境、生物与生物的协调与适应。"},{"ep":"xb2-15","n":"XB2-15","p":4,"a":"p4","id":"hm2","src":"assets/audio/XB2-15/hm2.mp3","sec":9.552,"t":"要考虑生物的适应性，比如在西北干旱地区，应种植耐旱的灌木和草，而不是大量种植需水较多的乔木。"},{"ep":"xb2-15","n":"XB2-15","p":4,"a":"p4","id":"hm3","src":"assets/audio/XB2-15/hm3.mp3","sec":7.704,"t":"还要考虑环境容纳量，比如草原放牧不能超过载畜量，否则会造成草场退化。"},{"ep":"xb2-15","n":"XB2-15","p":4,"a":"p4","id":"hm4","src":"assets/audio/XB2-15/hm4.mp3","sec":9.096,"t":"关键词：适应性、环境容纳量、适地适种、合理载畜量。看到这些，就想到协调原理。"},{"ep":"xb2-15","n":"XB2-15","p":5,"a":"p5","id":"wh1","src":"assets/audio/XB2-15/wh1.mp3","sec":5.64,"t":"考点五，整体原理。树立整体观，遵循整体原理。"},{"ep":"xb2-15","n":"XB2-15","p":5,"a":"p5","id":"wh2","src":"assets/audio/XB2-15/wh2.mp3","sec":9.936,"t":"一方面，要遵从自然生态系统的规律，各组分之间要有适当的比例，使系统各组分之间构成有序的结构。"},{"ep":"xb2-15","n":"XB2-15","p":5,"a":"p5","id":"wh3","src":"assets/audio/XB2-15/wh3.mp3","sec":9.24,"t":"另一方面，人类处在一个社会—经济—自然复合而成的巨大系统中，要兼顾生态、经济和社会效益。"},{"ep":"xb2-15","n":"XB2-15","p":5,"a":"p5","id":"wh4","src":"assets/audio/XB2-15/wh4.mp3","sec":9.48,"t":"关键词：整体、兼顾、社会—经济—自然、考虑农民收入和生活。看到这些，就想到整体原理。"},{"ep":"xb2-15","n":"XB2-15","p":6,"a":"p6","id":"jd1","src":"assets/audio/XB2-15/jd1.mp3","sec":5.136,"t":"考点六，生态工程原理的判断，这是高考的必考点。"},{"ep":"xb2-15","n":"XB2-15","p":6,"a":"p6","id":"jd2","src":"assets/audio/XB2-15/jd2.mp3","sec":5.52,"t":"湿地中种植多种净化能力强的水生植物：自生原理。"},{"ep":"xb2-15","n":"XB2-15","p":6,"a":"p6","id":"jd3","src":"assets/audio/XB2-15/jd3.mp3","sec":5.064,"t":"桑基鱼塘中，塘泥肥桑、蚕沙喂鱼：循环原理。"},{"ep":"xb2-15","n":"XB2-15","p":6,"a":"p6","id":"jd4","src":"assets/audio/XB2-15/jd4.mp3","sec":6.0,"t":"西北干旱地区种植杨树，结果大片死亡：违背了协调原理。"},{"ep":"xb2-15","n":"XB2-15","p":6,"a":"p6","id":"jd5","src":"assets/audio/XB2-15/jd5.mp3","sec":9.096,"t":"林业工程只注重种树，不考虑当地农民的生活，结果“前面造林、后面砍林”：违背了{整体原理|brown}。"},{"ep":"xb2-15","n":"XB2-15","p":6,"a":"p6","id":"jd6","src":"assets/audio/XB2-15/jd6.mp3","sec":12.888,"t":"解题方法：抓关键词。多物种、互利共存——自生；废物利用——循环；适应环境、不超载——协调；兼顾经济和社会——整体。"},{"ep":"xb2-15","n":"XB2-15","p":7,"a":"p7","id":"cs1","src":"assets/audio/XB2-15/cs1.mp3","sec":14.52,"t":"考点七，生态工程实例。第一，农村综合发展型生态工程：以沼气工程为中心，种植业、养殖业和加工业相结合，实现物质的多级循环利用。"},{"ep":"xb2-15","n":"XB2-15","p":7,"a":"p7","id":"cs2","src":"assets/audio/XB2-15/cs2.mp3","sec":15.768,"t":"第二，湿地生态恢复工程：采用工程和生态措施相结合的方法，比如退耕还湿，在湿地周围建立缓冲带，减少人类干扰，依靠自然演替等机制恢复湿地的生态功能。"},{"ep":"xb2-15","n":"XB2-15","p":7,"a":"p7","id":"cs3","src":"assets/audio/XB2-15/cs3.mp3","sec":10.176,"t":"第三，{矿区废弃地的生态恢复工程|brown}：关键在于植被恢复，以及植被恢复所必需的土壤微生物群落的重建。"},{"ep":"xb2-15","n":"XB2-15","p":7,"a":"p7","id":"cs4","src":"assets/audio/XB2-15/cs4.mp3","sec":12.216,"t":"易错：矿区恢复的关键不是种农作物，而是恢复植被和土壤微生物群落；人工制造表土、多层覆盖，再种植适应性强的植物。"},{"ep":"xb2-15","n":"XB2-15","p":"review","a":"review","id":"rv1","src":"assets/audio/XB2-15/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb2-15","n":"XB2-15","p":"review","a":"review","id":"rv2","src":"assets/audio/XB2-15/rv2.mp3","sec":15.168,"t":"判断一：生态工程的特点是少消耗、多效益、可持续？对。判断二：种植多种植物、提高生物多样性体现了循环原理？错，体现了自生原理。"},{"ep":"xb2-15","n":"XB2-15","p":"review","a":"review","id":"rv3","src":"assets/audio/XB2-15/rv3.mp3","sec":13.872,"t":"判断三：无废弃物农业主要体现了循环原理？对。判断四：西北干旱地区大量种植杨树体现协调原理？错，违背了协调原理。"},{"ep":"xb2-15","n":"XB2-15","p":"review","a":"review","id":"rv4","src":"assets/audio/XB2-15/rv4.mp3","sec":15.72,"t":"判断五：兼顾自然、经济、社会效益体现整体原理？对。判断六：矿区恢复的关键是尽快种植农作物？错，关键是恢复植被和土壤微生物群落。"},{"ep":"xb2-15","n":"XB2-15","p":"review","a":"review","id":"rv5","src":"assets/audio/XB2-15/rv5.mp3","sec":13.248,"t":"七个考点串成一条线：多物种讲自生，无废弃讲循环，适地适种讲协调，三效兼顾讲整体。选必二到这里就全部讲完了，我们下期再见！"},{"ep":"xb3-01","n":"XB3-01","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-01/in1.mp3","sec":8.16,"t":"同学们好！这节课梳理人教版选择性必修三第一章第一节——传统发酵技术的应用。"},{"ep":"xb3-01","n":"XB3-01","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-01/in2.mp3","sec":9.72,"t":"高考常考四种微生物的代谢类型、泡菜、果酒、果醋的制作条件，以及发酵装置和亚硝酸盐曲线。"},{"ep":"xb3-01","n":"XB3-01","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-01/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-01","n":"XB3-01","p":1,"a":"p1","id":"fe1","src":"assets/audio/XB3-01/fe1.mp3","sec":11.784,"t":"考点一，发酵与传统发酵技术。发酵是人们利用微生物，在适宜条件下，把原料通过微生物的代谢转化为所需产物的过程。"},{"ep":"xb3-01","n":"XB3-01","p":1,"a":"p1","id":"fe2","src":"assets/audio/XB3-01/fe2.mp3","sec":10.8,"t":"传统发酵技术，是直接利用原材料中天然存在的微生物，或者前一次发酵保存下来的面团、卤汁中的微生物来发酵。"},{"ep":"xb3-01","n":"XB3-01","p":1,"a":"p1","id":"fe3","src":"assets/audio/XB3-01/fe3.mp3","sec":7.392,"t":"它的特点是：以固体发酵和半固体发酵为主，通常是家庭式或作坊式的。"},{"ep":"xb3-01","n":"XB3-01","p":1,"a":"p1","id":"fe4","src":"assets/audio/XB3-01/fe4.mp3","sec":7.392,"t":"参与发酵的往往是多种微生物，也就是混合菌种，所以产品品质不太稳定。"},{"ep":"xb3-01","n":"XB3-01","p":1,"a":"p1","id":"fe5","src":"assets/audio/XB3-01/fe5.mp3","sec":9.264,"t":"考法：和发酵工程比较。易错：传统发酵用的是天然混合菌种，不是经过选育的单一菌种。"},{"ep":"xb3-01","n":"XB3-01","p":2,"a":"p2","id":"fu1","src":"assets/audio/XB3-01/fu1.mp3","sec":11.52,"t":"考点二，腐乳、酱等传统发酵食品。腐乳的制作有酵母、曲霉和毛霉等多种微生物参与，其中起主要作用的是毛霉。"},{"ep":"xb3-01","n":"XB3-01","p":2,"a":"p2","id":"fu2","src":"assets/audio/XB3-01/fu2.mp3","sec":6.672,"t":"毛霉产生的蛋白酶，把豆腐中的蛋白质分解成小分子的肽和氨基酸。"},{"ep":"xb3-01","n":"XB3-01","p":2,"a":"p2","id":"fu3","src":"assets/audio/XB3-01/fu3.mp3","sec":6.912,"t":"脂肪酶把脂肪水解为甘油和脂肪酸，所以腐乳味道鲜美、易于消化。"},{"ep":"xb3-01","n":"XB3-01","p":2,"a":"p2","id":"fu4","src":"assets/audio/XB3-01/fu4.mp3","sec":6.504,"t":"毛霉是一种丝状真菌，属于真核生物，代谢类型是异养需氧型。"},{"ep":"xb3-01","n":"XB3-01","p":2,"a":"p2","id":"fu5","src":"assets/audio/XB3-01/fu5.mp3","sec":15.408,"t":"考法：四种常见菌种的比较。解题方法：记住一张表——乳酸菌、醋酸菌是原核生物，酵母菌、毛霉是真核生物；只有乳酸菌严格厌氧，酵母菌兼性厌氧。"},{"ep":"xb3-01","n":"XB3-01","p":3,"a":"p3","id":"pk1","src":"assets/audio/XB3-01/pk1.mp3","sec":9.336,"t":"考点三，泡菜的制作。菌种是乳酸菌，它是厌氧细菌，在无氧条件下把葡萄糖分解为乳酸。"},{"ep":"xb3-01","n":"XB3-01","p":3,"a":"p3","id":"pk2","src":"assets/audio/XB3-01/pk2.mp3","sec":7.824,"t":"第一步，配制质量百分比为 5%～20% 的盐水，并且煮沸、冷却待用。"},{"ep":"xb3-01","n":"XB3-01","p":3,"a":"p3","id":"pk3","src":"assets/audio/XB3-01/pk3.mp3","sec":7.344,"t":"煮沸是为了杀灭杂菌、除去水中的氧气；冷却是为了防止高温杀死乳酸菌。"},{"ep":"xb3-01","n":"XB3-01","p":3,"a":"p3","id":"pk4","src":"assets/audio/XB3-01/pk4.mp3","sec":8.808,"t":"蔬菜装至八成满，倒入盐水没过全部菜料，盖好坛盖，再向坛盖边沿的水槽中注满水。"},{"ep":"xb3-01","n":"XB3-01","p":3,"a":"p3","id":"pk5","src":"assets/audio/XB3-01/pk5.mp3","sec":10.368,"t":"考法：问各步操作的目的。解题方法：泡菜的所有操作都围绕两件事——创造无氧环境、防止杂菌污染。"},{"ep":"xb3-01","n":"XB3-01","p":4,"a":"p4","id":"ni1","src":"assets/audio/XB3-01/ni1.mp3","sec":12.792,"t":"考点四，泡菜发酵中三种物质的变化。发酵初期，乳酸菌迅速繁殖，数量先增加，后期乳酸积累、pH下降，增长受到抑制。"},{"ep":"xb3-01","n":"XB3-01","p":4,"a":"p4","id":"ni2","src":"assets/audio/XB3-01/ni2.mp3","sec":5.376,"t":"乳酸的含量随着发酵进行不断增加，后期趋于稳定。"},{"ep":"xb3-01","n":"XB3-01","p":4,"a":"p4","id":"ni3","src":"assets/audio/XB3-01/ni3.mp3","sec":12.336,"t":"亚硝酸盐的含量先增加后减少：初期一些杂菌把硝酸盐还原成亚硝酸盐，后来在酸性环境中杂菌被抑制，亚硝酸盐被分解。"},{"ep":"xb3-01","n":"XB3-01","p":4,"a":"p4","id":"ni4","src":"assets/audio/XB3-01/ni4.mp3","sec":10.08,"t":"亚硝酸盐在特定条件下会转变为亚硝胺，这是一种致癌物，所以泡菜要在亚硝酸盐含量降低后再食用。"},{"ep":"xb3-01","n":"XB3-01","p":4,"a":"p4","id":"ni5","src":"assets/audio/XB3-01/ni5.mp3","sec":13.128,"t":"考法：看图判断三条曲线和最佳食用时间。易错：亚硝酸盐含量最高时并不是乳酸菌最多的时候，泡菜腌制时间过短最不安全。"},{"ep":"xb3-01","n":"XB3-01","p":5,"a":"p5","id":"wi1","src":"assets/audio/XB3-01/wi1.mp3","sec":10.776,"t":"考点五，果酒的制作。菌种是酵母菌，代谢类型是兼性厌氧：有氧时大量繁殖，无氧时进行酒精发酵。"},{"ep":"xb3-01","n":"XB3-01","p":5,"a":"p5","id":"wi2","src":"assets/audio/XB3-01/wi2.mp3","sec":3.216,"t":"温度控制在 18～30 ℃。"},{"ep":"xb3-01","n":"XB3-01","p":5,"a":"p5","id":"wi3","src":"assets/audio/XB3-01/wi3.mp3","sec":7.776,"t":"葡萄先冲洗、再去枝梗，而且不能反复冲洗，以免把葡萄皮上的野生酵母菌洗掉。"},{"ep":"xb3-01","n":"XB3-01","p":5,"a":"p5","id":"wi4","src":"assets/audio/XB3-01/wi4.mp3","sec":12.48,"t":"装瓶时要留大约1/3的空间：一是让酵母菌先有氧繁殖，二是防止产生的 CO2 使发酵液溢出。"},{"ep":"xb3-01","n":"XB3-01","p":5,"a":"p5","id":"wi5","src":"assets/audio/XB3-01/wi5.mp3","sec":6.504,"t":"发酵过程中，每隔 12 h 左右把瓶盖拧松一次，排出 CO2。"},{"ep":"xb3-01","n":"XB3-01","p":5,"a":"p5","id":"wi6","src":"assets/audio/XB3-01/wi6.mp3","sec":9.648,"t":"易错：是拧松瓶盖，不是打开瓶盖——打开会让空气和杂菌进入。考法：先通气后密封的原因。"},{"ep":"xb3-01","n":"XB3-01","p":6,"a":"p6","id":"vi1","src":"assets/audio/XB3-01/vi1.mp3","sec":10.008,"t":"考点六，果醋的制作。菌种是醋酸菌，它是好氧细菌，只有在氧气充足时才能进行旺盛的生命活动。"},{"ep":"xb3-01","n":"XB3-01","p":6,"a":"p6","id":"vi2","src":"assets/audio/XB3-01/vi2.mp3","sec":3.864,"t":"最适生长温度是 30～35 ℃。"},{"ep":"xb3-01","n":"XB3-01","p":6,"a":"p6","id":"vi3","src":"assets/audio/XB3-01/vi3.mp3","sec":5.304,"t":"当氧气、糖源都充足时，醋酸菌把糖分解成乙酸。"},{"ep":"xb3-01","n":"XB3-01","p":6,"a":"p6","id":"vi4","src":"assets/audio/XB3-01/vi4.mp3","sec":6.144,"t":"当缺少糖源时，醋酸菌把乙醇变为乙醛，再把乙醛变为乙酸。"},{"ep":"xb3-01","n":"XB3-01","p":6,"a":"p6","id":"vi5","src":"assets/audio/XB3-01/vi5.mp3","sec":8.616,"t":"易错：果酒变果醋，要改两个条件——温度升到30～35 ℃，并且通入无菌空气。"},{"ep":"xb3-01","n":"XB3-01","p":7,"a":"p7","id":"dv1","src":"assets/audio/XB3-01/dv1.mp3","sec":8.472,"t":"考点七，果酒与果醋发酵装置。这个装置有三个口：充气口、排气口和出料口。"},{"ep":"xb3-01","n":"XB3-01","p":7,"a":"p7","id":"dv2","src":"assets/audio/XB3-01/dv2.mp3","sec":6.984,"t":"充气口用来通入空气：果酒发酵时关闭，果醋发酵时通入无菌空气。"},{"ep":"xb3-01","n":"XB3-01","p":7,"a":"p7","id":"dv3","src":"assets/audio/XB3-01/dv3.mp3","sec":7.776,"t":"排气口排出CO2，它连接一根长而弯曲的胶管，防止空气中的微生物污染。"},{"ep":"xb3-01","n":"XB3-01","p":7,"a":"p7","id":"dv4","src":"assets/audio/XB3-01/dv4.mp3","sec":3.912,"t":"出料口用来取样，便于检测发酵情况。"},{"ep":"xb3-01","n":"XB3-01","p":7,"a":"p7","id":"dv5","src":"assets/audio/XB3-01/dv5.mp3","sec":12.6,"t":"考法：给出装置图问各口的作用。解题方法：先看是果酒还是果醋——果酒关充气口，果醋开充气口，排气口两种发酵都要开。"},{"ep":"xb3-01","n":"XB3-01","p":8,"a":"p8","id":"de1","src":"assets/audio/XB3-01/de1.mp3","sec":10.368,"t":"考点八，发酵结果的检测。果酒：在酸性条件下，重铬酸钾与酒精反应，颜色由橙色变成灰绿色。"},{"ep":"xb3-01","n":"XB3-01","p":8,"a":"p8","id":"de2","src":"assets/audio/XB3-01/de2.mp3","sec":7.416,"t":"果醋：可以检测pH，发酵液pH明显下降；也可以闻气味，有酸味。"},{"ep":"xb3-01","n":"XB3-01","p":8,"a":"p8","id":"de3","src":"assets/audio/XB3-01/de3.mp3","sec":5.064,"t":"还可以取发酵液制片，用显微镜观察菌种的形态。"},{"ep":"xb3-01","n":"XB3-01","p":8,"a":"p8","id":"de4","src":"assets/audio/XB3-01/de4.mp3","sec":10.032,"t":"易错：葡萄糖也能与酸性重铬酸钾反应变色，所以要适当延长发酵时间，耗尽葡萄糖后再检测酒精。"},{"ep":"xb3-01","n":"XB3-01","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-01/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-01","n":"XB3-01","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-01/rv2.mp3","sec":12.384,"t":"判断一：传统发酵一般用单一菌种？错，多为天然混合菌种。判断二：腐乳制作中起主要作用的是毛霉？对。"},{"ep":"xb3-01","n":"XB3-01","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-01/rv3.mp3","sec":11.88,"t":"判断三：泡菜盐水煮沸后要趁热倒入？错，要冷却。判断四：果酒发酵要定期拧松瓶盖排气？对。"},{"ep":"xb3-01","n":"XB3-01","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-01/rv4.mp3","sec":14.016,"t":"判断五：果酒变果醋只需升高温度？错，还要通入无菌空气。判断六：重铬酸钾变灰绿色一定有酒精？错，葡萄糖也能使它变色。"},{"ep":"xb3-01","n":"XB3-01","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-01/rv5.mp3","sec":6.936,"t":"八个考点串成一条线：先认菌种，再定氧气和温度。我们下期再见！"},{"ep":"xb3-02","n":"XB3-02","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-02/in1.mp3","sec":8.664,"t":"同学们好！这节课梳理人教版选择性必修三第一章第二节的上半部分——微生物的纯培养。"},{"ep":"xb3-02","n":"XB3-02","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-02/in2.mp3","sec":8.448,"t":"高考常考培养基的成分和类型、消毒与灭菌的区别，以及倒平板和平板划线的操作细节。"},{"ep":"xb3-02","n":"XB3-02","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-02/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-02","n":"XB3-02","p":1,"a":"p1","id":"md1","src":"assets/audio/XB3-02/md1.mp3","sec":10.992,"t":"考点一，培养基的成分。培养基是人们按照微生物对营养物质的不同需求，配制出的供其生长繁殖的营养基质。"},{"ep":"xb3-02","n":"XB3-02","p":1,"a":"p1","id":"md2","src":"assets/audio/XB3-02/md2.mp3","sec":6.528,"t":"培养基一般都含有水、碳源、氮源和无机盐这四类基本成分。"},{"ep":"xb3-02","n":"XB3-02","p":1,"a":"p1","id":"md3","src":"assets/audio/XB3-02/md3.mp3","sec":9.216,"t":"还要满足微生物对pH、特殊营养物质和氧气的要求。比如培养乳酸杆菌要添加维生素。"},{"ep":"xb3-02","n":"XB3-02","p":1,"a":"p1","id":"md4","src":"assets/audio/XB3-02/md4.mp3","sec":10.968,"t":"培养霉菌时，要把培养基调至酸性；培养细菌时，一般调至中性或弱碱性；培养厌氧微生物要提供无氧条件。"},{"ep":"xb3-02","n":"XB3-02","p":1,"a":"p1","id":"md5","src":"assets/audio/XB3-02/md5.mp3","sec":11.976,"t":"易错：并不是所有培养基都要加有机碳源。自养微生物，比如硝化细菌，能利用CO2，培养基里可以不加有机碳源。"},{"ep":"xb3-02","n":"XB3-02","p":2,"a":"p2","id":"ty1","src":"assets/audio/XB3-02/ty1.mp3","sec":7.368,"t":"考点二，培养基的类型。按物理状态分，有液体培养基和固体培养基。"},{"ep":"xb3-02","n":"XB3-02","p":2,"a":"p2","id":"ty2","src":"assets/audio/XB3-02/ty2.mp3","sec":9.768,"t":"在液体培养基中加入琼脂等凝固剂，就制成了固体培养基。琼脂是一种多糖，一般不能被微生物利用。"},{"ep":"xb3-02","n":"XB3-02","p":2,"a":"p2","id":"ty3","src":"assets/audio/XB3-02/ty3.mp3","sec":8.928,"t":"固体培养基用于微生物的分离、计数和观察菌落；液体培养基常用于扩大培养和工业生产。"},{"ep":"xb3-02","n":"XB3-02","p":2,"a":"p2","id":"ty4","src":"assets/audio/XB3-02/ty4.mp3","sec":5.904,"t":"按功能分，还有选择培养基和鉴别培养基，下期详细讲。"},{"ep":"xb3-02","n":"XB3-02","p":2,"a":"p2","id":"ty5","src":"assets/audio/XB3-02/ty5.mp3","sec":10.176,"t":"考法：给出配方判断类型。解题方法：有琼脂就是固体；只能让某一类微生物生长的就是选择培养基。"},{"ep":"xb3-02","n":"XB3-02","p":3,"a":"p3","id":"st1","src":"assets/audio/XB3-02/st1.mp3","sec":9.24,"t":"考点三，消毒和灭菌。获得纯净的微生物培养物，关键是防止杂菌污染，也就是无菌技术。"},{"ep":"xb3-02","n":"XB3-02","p":3,"a":"p3","id":"st2","src":"assets/audio/XB3-02/st2.mp3","sec":8.592,"t":"消毒，是使用较为温和的物理、化学或生物等方法，杀死物体表面或内部一部分微生物。"},{"ep":"xb3-02","n":"XB3-02","p":3,"a":"p3","id":"st3","src":"assets/audio/XB3-02/st3.mp3","sec":7.512,"t":"灭菌，是使用强烈的理化方法，杀死物体内外所有的微生物，包括芽孢和孢子。"},{"ep":"xb3-02","n":"XB3-02","p":3,"a":"p3","id":"st4","src":"assets/audio/XB3-02/st4.mp3","sec":10.512,"t":"解题方法：看对象能不能耐受——操作者的双手、牛奶这类不耐高温的对象只能消毒；培养基、器具要灭菌。"},{"ep":"xb3-02","n":"XB3-02","p":4,"a":"p4","id":"mt1","src":"assets/audio/XB3-02/mt1.mp3","sec":8.184,"t":"考点四，常用的灭菌和消毒方法。接种环、接种针、试管口，用灼烧灭菌。"},{"ep":"xb3-02","n":"XB3-02","p":4,"a":"p4","id":"mt2","src":"assets/audio/XB3-02/mt2.mp3","sec":5.808,"t":"玻璃器皿和金属用具，用干热灭菌，放在干热灭菌箱中。"},{"ep":"xb3-02","n":"XB3-02","p":4,"a":"p4","id":"mt3","src":"assets/audio/XB3-02/mt3.mp3","sec":10.704,"t":"培养基，用湿热灭菌，最常用的是高压蒸汽灭菌，在 100 kPa、121 ℃ 下维持 15～30 min。"},{"ep":"xb3-02","n":"XB3-02","p":4,"a":"p4","id":"mt4","src":"assets/audio/XB3-02/mt4.mp3","sec":7.992,"t":"消毒方法有：牛奶用巴氏消毒法，双手用酒精擦拭，接种室用紫外线照射。"},{"ep":"xb3-02","n":"XB3-02","p":4,"a":"p4","id":"mt5","src":"assets/audio/XB3-02/mt5.mp3","sec":7.92,"t":"易错：培养基不能用干热灭菌，因为它含水；玻璃器皿要先干燥再干热灭菌。"},{"ep":"xb3-02","n":"XB3-02","p":5,"a":"p5","id":"sp1","src":"assets/audio/XB3-02/sp1.mp3","sec":8.664,"t":"考点五，微生物纯培养的步骤。由单一个体繁殖所获得的微生物群体，叫作纯培养物。"},{"ep":"xb3-02","n":"XB3-02","p":5,"a":"p5","id":"sp2","src":"assets/audio/XB3-02/sp2.mp3","sec":6.408,"t":"步骤是：配制培养基、灭菌、倒平板、接种、分离和培养。"},{"ep":"xb3-02","n":"XB3-02","p":5,"a":"p5","id":"sp3","src":"assets/audio/XB3-02/sp3.mp3","sec":9.384,"t":"分散的微生物在固体培养基上繁殖，形成肉眼可见的、有一定形态结构的子细胞群体，叫作菌落。"},{"ep":"xb3-02","n":"XB3-02","p":5,"a":"p5","id":"sp4","src":"assets/audio/XB3-02/sp4.mp3","sec":7.992,"t":"考法：排序题。易错：是先灭菌、后倒平板，倒平板之后不能再灭菌。"},{"ep":"xb3-02","n":"XB3-02","p":6,"a":"p6","id":"po1","src":"assets/audio/XB3-02/po1.mp3","sec":8.016,"t":"考点六，倒平板。等培养基冷却到 50 ℃ 左右，在酒精灯火焰附近操作。"},{"ep":"xb3-02","n":"XB3-02","p":6,"a":"p6","id":"po2","src":"assets/audio/XB3-02/po2.mp3","sec":7.44,"t":"用左手打开培养皿盖的一条缝隙，右手把培养基倒入培养皿，立刻盖上皿盖。"},{"ep":"xb3-02","n":"XB3-02","p":6,"a":"p6","id":"po3","src":"assets/audio/XB3-02/po3.mp3","sec":6.936,"t":"等培养基冷却凝固后，把平板倒过来放置，使皿盖在下、皿底在上。"},{"ep":"xb3-02","n":"XB3-02","p":6,"a":"p6","id":"po4","src":"assets/audio/XB3-02/po4.mp3","sec":8.184,"t":"考法：问平板倒置的原因。答：防止皿盖上的冷凝水落入培养基，造成污染。"},{"ep":"xb3-02","n":"XB3-02","p":7,"a":"p7","id":"sk1","src":"assets/audio/XB3-02/sk1.mp3","sec":12.696,"t":"考点七，平板划线法。用接种环在固体培养基表面连续划线，把聚集的菌种逐步稀释分散，最终得到由单个细胞繁殖成的菌落。"},{"ep":"xb3-02","n":"XB3-02","p":7,"a":"p7","id":"sk2","src":"assets/audio/XB3-02/sk2.mp3","sec":7.704,"t":"第二次及以后的划线，都要从上一次划线的末端开始，最后一区不要与第一区相连。"},{"ep":"xb3-02","n":"XB3-02","p":7,"a":"p7","id":"sk3","src":"assets/audio/XB3-02/sk3.mp3","sec":6.864,"t":"接种环每次划线前后都要灼烧：第一次灼烧，杀死环上原有的微生物。"},{"ep":"xb3-02","n":"XB3-02","p":7,"a":"p7","id":"sk4","src":"assets/audio/XB3-02/sk4.mp3","sec":8.616,"t":"每次划线之前灼烧，是杀死上次残留的菌种，使每次划线的菌种都来自上次划线的末端。"},{"ep":"xb3-02","n":"XB3-02","p":7,"a":"p7","id":"sk5","src":"assets/audio/XB3-02/sk5.mp3","sec":9.552,"t":"划线结束后灼烧，是防止菌种污染环境和感染操作者。灼烧后要冷却再划线，以免烫死菌种。"},{"ep":"xb3-02","n":"XB3-02","p":7,"a":"p7","id":"sk6","src":"assets/audio/XB3-02/sk6.mp3","sec":7.8,"t":"考法：灼烧次数。解题方法：划了 N 个区域，接种环就要灼烧 N + 1 次。"},{"ep":"xb3-02","n":"XB3-02","p":8,"a":"p8","id":"ys1","src":"assets/audio/XB3-02/ys1.mp3","sec":10.896,"t":"考点八，实验：酵母菌的纯培养。步骤：制备马铃薯琼脂培养基、灭菌、倒平板，再用平板划线法接种。"},{"ep":"xb3-02","n":"XB3-02","p":8,"a":"p8","id":"ys2","src":"assets/audio/XB3-02/ys2.mp3","sec":6.912,"t":"把接种后的平板和一个未接种的平板一起倒置，放入恒温培养箱中培养。"},{"ep":"xb3-02","n":"XB3-02","p":8,"a":"p8","id":"ys3","src":"assets/audio/XB3-02/ys3.mp3","sec":6.768,"t":"未接种的平板是对照：如果它上面也长出菌落，说明培养基被污染了。"},{"ep":"xb3-02","n":"XB3-02","p":8,"a":"p8","id":"ys4","src":"assets/audio/XB3-02/ys4.mp3","sec":9.96,"t":"观察菌落时，看它的形状、大小、隆起程度和颜色。不同微生物的菌落特征不同，可以用来鉴别菌种。"},{"ep":"xb3-02","n":"XB3-02","p":8,"a":"p8","id":"ys5","src":"assets/audio/XB3-02/ys5.mp3","sec":10.056,"t":"考法：问设置未接种平板的目的。解题方法：答“检验培养基是否被污染”，也就是灭菌是否合格。"},{"ep":"xb3-02","n":"XB3-02","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-02/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-02","n":"XB3-02","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-02/rv2.mp3","sec":12.384,"t":"判断一：培养基都必须含有机碳源？错，自养微生物可以不加。判断二：琼脂是凝固剂，一般不被微生物利用？对。"},{"ep":"xb3-02","n":"XB3-02","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-02/rv3.mp3","sec":11.496,"t":"判断三：消毒能杀死物体内外所有微生物？错，那是灭菌。判断四：培养基常用高压蒸汽灭菌？对。"},{"ep":"xb3-02","n":"XB3-02","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-02/rv4.mp3","sec":14.328,"t":"判断五：平板划线只在开始前灼烧接种环？错，每次划线前后都要灼烧。判断六：平板倒置可防止冷凝水滴落造成污染？对。"},{"ep":"xb3-02","n":"XB3-02","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-02/rv5.mp3","sec":7.488,"t":"八个考点串成一条线：无菌贯穿始终，灼烧前后都要做。我们下期再见！"},{"ep":"xb3-03","n":"XB3-03","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-03/in1.mp3","sec":9.528,"t":"同学们好！这节课梳理人教版选择性必修三第一章第二节的下半部分——微生物的选择培养和计数。"},{"ep":"xb3-03","n":"XB3-03","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-03/in2.mp3","sec":8.16,"t":"高考常考选择培养基的设计、稀释涂布平板法的计数公式和误差，以及对照组的作用。"},{"ep":"xb3-03","n":"XB3-03","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-03/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-03","n":"XB3-03","p":1,"a":"p1","id":"se1","src":"assets/audio/XB3-03/se1.mp3","sec":9.36,"t":"考点一，选择培养基。它允许特定种类的微生物生长，同时抑制或阻止其他种类微生物生长。"},{"ep":"xb3-03","n":"XB3-03","p":1,"a":"p1","id":"se2","src":"assets/audio/XB3-03/se2.mp3","sec":5.52,"t":"以尿素为唯一氮源，只有能分解尿素的微生物才能生长。"},{"ep":"xb3-03","n":"XB3-03","p":1,"a":"p1","id":"se3","src":"assets/audio/XB3-03/se3.mp3","sec":6.12,"t":"加入青霉素，可以抑制细菌，从而筛选出酵母菌、霉菌等真菌。"},{"ep":"xb3-03","n":"XB3-03","p":1,"a":"p1","id":"se4","src":"assets/audio/XB3-03/se4.mp3","sec":4.344,"t":"不加氮源的培养基，可以筛选出固氮微生物。"},{"ep":"xb3-03","n":"XB3-03","p":1,"a":"p1","id":"se5","src":"assets/audio/XB3-03/se5.mp3","sec":9.264,"t":"解题方法：设计选择培养基，抓住目的菌独有的能力，把相应物质设为唯一碳源或唯一氮源。"},{"ep":"xb3-03","n":"XB3-03","p":2,"a":"p2","id":"ur1","src":"assets/audio/XB3-03/ur1.mp3","sec":8.976,"t":"考点二，土壤中分解尿素的细菌的分离与计数。这类细菌能合成脲酶，把尿素分解成氨。"},{"ep":"xb3-03","n":"XB3-03","p":2,"a":"p2","id":"ur2","src":"assets/audio/XB3-03/ur2.mp3","sec":7.56,"t":"所以培养基要以尿素为唯一氮源，其他微生物因为缺少氮源而不能生长。"},{"ep":"xb3-03","n":"XB3-03","p":2,"a":"p2","id":"ur3","src":"assets/audio/XB3-03/ur3.mp3","sec":6.648,"t":"实验步骤：取土样、样品稀释、涂布平板、培养、观察计数。"},{"ep":"xb3-03","n":"XB3-03","p":2,"a":"p2","id":"ur4","src":"assets/audio/XB3-03/ur4.mp3","sec":7.992,"t":"易错：培养基中不能再加牛肉膏、蛋白胨这类含氮的物质，否则就失去了选择作用。"},{"ep":"xb3-03","n":"XB3-03","p":3,"a":"p3","id":"sd1","src":"assets/audio/XB3-03/sd1.mp3","sec":6.792,"t":"考点三，稀释涂布平板法。分两步：梯度稀释和涂布平板。"},{"ep":"xb3-03","n":"XB3-03","p":3,"a":"p3","id":"sd2","src":"assets/audio/XB3-03/sd2.mp3","sec":10.032,"t":"梯度稀释：取 1 mL 菌液，加入 9 mL 无菌水中，就稀释了10倍；依次进行，得到一系列稀释液。"},{"ep":"xb3-03","n":"XB3-03","p":3,"a":"p3","id":"sd3","src":"assets/audio/XB3-03/sd3.mp3","sec":6.624,"t":"涂布：取 0.1 mL 稀释液滴到平板表面，用涂布器涂布均匀。"},{"ep":"xb3-03","n":"XB3-03","p":3,"a":"p3","id":"sd4","src":"assets/audio/XB3-03/sd4.mp3","sec":6.984,"t":"涂布器先浸在酒精中，再在火焰上引燃，待酒精燃尽、冷却后再涂布。"},{"ep":"xb3-03","n":"XB3-03","p":3,"a":"p3","id":"sd5","src":"assets/audio/XB3-03/sd5.mp3","sec":10.632,"t":"易错：涂布器是引燃酒精，不是在火焰上灼烧到烧红；涂布法既能分离，又能计数，平板划线法只能分离。"},{"ep":"xb3-03","n":"XB3-03","p":4,"a":"p4","id":"ct1","src":"assets/audio/XB3-03/ct1.mp3","sec":10.824,"t":"考点四，菌落计数。选择菌落数在 30～300 之间的平板计数，每个稀释度至少涂布 3个平板，取平均值。"},{"ep":"xb3-03","n":"XB3-03","p":4,"a":"p4","id":"ct2","src":"assets/audio/XB3-03/ct2.mp3","sec":11.28,"t":"公式：每克样品中的菌株数 = (C ÷ V) × M。C 是平均菌落数，V 是涂布的体积，M 是稀释倍数。"},{"ep":"xb3-03","n":"XB3-03","p":4,"a":"p4","id":"ct3","src":"assets/audio/XB3-03/ct3.mp3","sec":14.736,"t":"例如稀释 105 倍，三个平板分别是 156、178、191，平均 175 个，涂布 0.1 mL，结果是 1.75 × 108 个/g。"},{"ep":"xb3-03","n":"XB3-03","p":4,"a":"p4","id":"ct4","src":"assets/audio/XB3-03/ct4.mp3","sec":8.496,"t":"易错：不在 30～300 之间的平板不计；V 的单位是 mL，0.1 mL 要除，不要漏掉。"},{"ep":"xb3-03","n":"XB3-03","p":5,"a":"p5","id":"sm1","src":"assets/audio/XB3-03/sm1.mp3","sec":9.24,"t":"考点五，计数结果为什么偏小。当两个或多个细胞连在一起时，平板上观察到的只是一个菌落。"},{"ep":"xb3-03","n":"XB3-03","p":5,"a":"p5","id":"sm2","src":"assets/audio/XB3-03/sm2.mp3","sec":6.288,"t":"所以稀释涂布平板法统计的菌落数，往往比活菌的实际数目少。"},{"ep":"xb3-03","n":"XB3-03","p":5,"a":"p5","id":"sm3","src":"assets/audio/XB3-03/sm3.mp3","sec":5.352,"t":"因此，统计结果一般用菌落数而不是活菌数来表示。"},{"ep":"xb3-03","n":"XB3-03","p":5,"a":"p5","id":"sm4","src":"assets/audio/XB3-03/sm4.mp3","sec":10.416,"t":"考法：问结果偏小的原因。解题方法：标准答案就一句——两个或多个细胞连在一起时，只能形成一个菌落。"},{"ep":"xb3-03","n":"XB3-03","p":6,"a":"p6","id":"mi1","src":"assets/audio/XB3-03/mi1.mp3","sec":9.096,"t":"考点六，显微镜直接计数法。利用特定的细菌计数板或血细胞计数板，在显微镜下计数。"},{"ep":"xb3-03","n":"XB3-03","p":6,"a":"p6","id":"mi2","src":"assets/audio/XB3-03/mi2.mp3","sec":6.456,"t":"它统计的是活菌和死菌的总和，所以结果往往比实际的活菌数偏大。"},{"ep":"xb3-03","n":"XB3-03","p":6,"a":"p6","id":"mi3","src":"assets/audio/XB3-03/mi3.mp3","sec":6.888,"t":"稀释涂布平板法只统计活菌，结果偏小，但需要培养，耗时较长。"},{"ep":"xb3-03","n":"XB3-03","p":6,"a":"p6","id":"mi4","src":"assets/audio/XB3-03/mi4.mp3","sec":12.6,"t":"考法：比较两种方法的结果。解题方法：看能不能分辨死活——显微镜分不清死活，所以偏大；平板计数细胞重叠，所以偏小。"},{"ep":"xb3-03","n":"XB3-03","p":7,"a":"p7","id":"co1","src":"assets/audio/XB3-03/co1.mp3","sec":8.232,"t":"考点七，对照的设置。第一种：未接种的选择培养基平板，和实验组一起培养。"},{"ep":"xb3-03","n":"XB3-03","p":7,"a":"p7","id":"co2","src":"assets/audio/XB3-03/co2.mp3","sec":6.816,"t":"如果它长出菌落，说明培养基被污染，灭菌不合格，实验结果不可信。"},{"ep":"xb3-03","n":"XB3-03","p":7,"a":"p7","id":"co3","src":"assets/audio/XB3-03/co3.mp3","sec":7.488,"t":"第二种：用同样的土样接种牛肉膏蛋白胨培养基，它几乎能让各种细菌生长。"},{"ep":"xb3-03","n":"XB3-03","p":7,"a":"p7","id":"co4","src":"assets/audio/XB3-03/co4.mp3","sec":7.344,"t":"如果它上面的菌落数明显多于选择培养基，说明选择培养基起到了选择作用。"},{"ep":"xb3-03","n":"XB3-03","p":7,"a":"p7","id":"co5","src":"assets/audio/XB3-03/co5.mp3","sec":9.96,"t":"考法：问对照的目的。解题方法：空白平板看有没有污染，牛肉膏蛋白胨平板看有没有选择作用。"},{"ep":"xb3-03","n":"XB3-03","p":8,"a":"p8","id":"id1","src":"assets/audio/XB3-03/id1.mp3","sec":8.376,"t":"考点八，分解尿素的细菌的鉴定。在以尿素为唯一氮源的培养基中加入酚红指示剂。"},{"ep":"xb3-03","n":"XB3-03","p":8,"a":"p8","id":"id2","src":"assets/audio/XB3-03/id2.mp3","sec":6.288,"t":"细菌分解尿素产生氨，使培养基pH升高，酚红指示剂变红。"},{"ep":"xb3-03","n":"XB3-03","p":8,"a":"p8","id":"id3","src":"assets/audio/XB3-03/id3.mp3","sec":6.024,"t":"菌落周围出现红色，就可以初步鉴定这种细菌能分解尿素。"},{"ep":"xb3-03","n":"XB3-03","p":8,"a":"p8","id":"id4","src":"assets/audio/XB3-03/id4.mp3","sec":10.08,"t":"易错：选择培养基上长出的菌落不一定都是目的菌，所以要再用酚红鉴定；酚红是变红，不要记成别的颜色。"},{"ep":"xb3-03","n":"XB3-03","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-03/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-03","n":"XB3-03","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-03/rv2.mp3","sec":12.336,"t":"判断一：选择培养基上长出的都是目的菌？错，还要鉴定。判断二：分离尿素分解菌要以尿素为唯一氮源？对。"},{"ep":"xb3-03","n":"XB3-03","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-03/rv3.mp3","sec":12.696,"t":"判断三：平板划线法也能计数？错，计数用稀释涂布平板法。判断四：选菌落数在30～300的平板计数？对。"},{"ep":"xb3-03","n":"XB3-03","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-03/rv4.mp3","sec":11.808,"t":"判断五：稀释涂布平板法的结果往往偏大？错，偏小。判断六：尿素分解菌使酚红指示剂变红？对。"},{"ep":"xb3-03","n":"XB3-03","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-03/rv5.mp3","sec":8.064,"t":"八个考点串成一条线：唯一碳源氮源选菌，30～300个才计数。我们下期再见！"},{"ep":"xb3-04","n":"XB3-04","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-04/in1.mp3","sec":8.112,"t":"同学们好！这节课梳理人教版选择性必修三第一章第三节——发酵工程及其应用。"},{"ep":"xb3-04","n":"XB3-04","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-04/in2.mp3","sec":8.136,"t":"高考常考发酵工程的基本环节、发酵条件的控制，以及产品分离提纯和各领域应用。"},{"ep":"xb3-04","n":"XB3-04","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-04/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-04","n":"XB3-04","p":1,"a":"p1","id":"cp1","src":"assets/audio/XB3-04/cp1.mp3","sec":10.272,"t":"考点一，发酵工程。它是利用微生物的特定功能，通过现代工程技术，规模化生产对人类有用的产品。"},{"ep":"xb3-04","n":"XB3-04","p":1,"a":"p1","id":"cp2","src":"assets/audio/XB3-04/cp2.mp3","sec":6.528,"t":"发酵工程的特点：生产条件温和，原料来源丰富且价格低廉。"},{"ep":"xb3-04","n":"XB3-04","p":1,"a":"p1","id":"cp3","src":"assets/audio/XB3-04/cp3.mp3","sec":4.848,"t":"产物专一，废弃物对环境的污染小、容易处理。"},{"ep":"xb3-04","n":"XB3-04","p":1,"a":"p1","id":"cp4","src":"assets/audio/XB3-04/cp4.mp3","sec":11.064,"t":"易错：发酵工程用的是经过选育的优良单一菌种，通常在发酵罐中液体发酵，这正是它与传统发酵技术的主要区别。"},{"ep":"xb3-04","n":"XB3-04","p":2,"a":"p2","id":"pr1","src":"assets/audio/XB3-04/pr1.mp3","sec":7.872,"t":"考点二，发酵工程的基本环节。先选育菌种，再扩大培养，增加菌种的数量。"},{"ep":"xb3-04","n":"XB3-04","p":2,"a":"p2","id":"pr2","src":"assets/audio/XB3-04/pr2.mp3","sec":3.6,"t":"然后配制培养基、灭菌、接种。"},{"ep":"xb3-04","n":"XB3-04","p":2,"a":"p2","id":"pr3","src":"assets/audio/XB3-04/pr3.mp3","sec":4.896,"t":"接着在发酵罐内发酵，这是发酵工程的中心环节。"},{"ep":"xb3-04","n":"XB3-04","p":2,"a":"p2","id":"pr4","src":"assets/audio/XB3-04/pr4.mp3","sec":3.792,"t":"最后分离、提纯产物，获得产品。"},{"ep":"xb3-04","n":"XB3-04","p":2,"a":"p2","id":"pr5","src":"assets/audio/XB3-04/pr5.mp3","sec":9.216,"t":"考法：排序和找中心环节。易错：扩大培养的目的是增加菌种数量，不是为了获得产物。"},{"ep":"xb3-04","n":"XB3-04","p":3,"a":"p3","id":"br1","src":"assets/audio/XB3-04/br1.mp3","sec":6.816,"t":"考点三，菌种的选育。性状优良的菌种，可以从自然界中筛选出来。"},{"ep":"xb3-04","n":"XB3-04","p":3,"a":"p3","id":"br2","src":"assets/audio/XB3-04/br2.mp3","sec":6.816,"t":"也可以通过诱变育种获得，比如用诱变的方法选育高产青霉素的青霉菌。"},{"ep":"xb3-04","n":"XB3-04","p":3,"a":"p3","id":"br3","src":"assets/audio/XB3-04/br3.mp3","sec":8.256,"t":"还可以通过基因工程育种获得，比如把乙肝病毒的抗原基因导入酵母菌，生产乙肝疫苗。"},{"ep":"xb3-04","n":"XB3-04","p":3,"a":"p3","id":"br4","src":"assets/audio/XB3-04/br4.mp3","sec":12.096,"t":"考法：判断育种方法。解题方法：有“诱变”字样或用射线、化学药剂处理的是诱变育种；导入外源基因的是基因工程育种。"},{"ep":"xb3-04","n":"XB3-04","p":4,"a":"p4","id":"cl1","src":"assets/audio/XB3-04/cl1.mp3","sec":10.344,"t":"考点四，发酵过程的控制。要随时检测培养液中的微生物数量和产物浓度，并及时添加必需的营养组分。"},{"ep":"xb3-04","n":"XB3-04","p":4,"a":"p4","id":"cl2","src":"assets/audio/XB3-04/cl2.mp3","sec":4.776,"t":"还要严格控制温度、pH和溶解氧等发酵条件。"},{"ep":"xb3-04","n":"XB3-04","p":4,"a":"p4","id":"cl3","src":"assets/audio/XB3-04/cl3.mp3","sec":8.496,"t":"发酵罐上有搅拌叶轮、通入无菌空气的管道，还有温度、pH检测装置和冷却水夹套。"},{"ep":"xb3-04","n":"XB3-04","p":4,"a":"p4","id":"cl4","src":"assets/audio/XB3-04/cl4.mp3","sec":11.088,"t":"例如谷氨酸棒状杆菌，在中性和弱碱性条件下积累谷氨酸；在酸性条件下容易形成谷氨酰胺和N-乙酰谷氨酰胺。"},{"ep":"xb3-04","n":"XB3-04","p":4,"a":"p4","id":"cl5","src":"assets/audio/XB3-04/cl5.mp3","sec":10.752,"t":"考法：环境条件改变，产物也会改变。解题方法：答题时抓住“条件影响微生物的生长繁殖和代谢途径”。"},{"ep":"xb3-04","n":"XB3-04","p":5,"a":"p5","id":"sp1","src":"assets/audio/XB3-04/sp1.mp3","sec":10.44,"t":"考点五，产品的分离和提纯。产品如果是微生物细胞本身，可以采用过滤、沉淀等方法把菌体分离和干燥。"},{"ep":"xb3-04","n":"XB3-04","p":5,"a":"p5","id":"sp2","src":"assets/audio/XB3-04/sp2.mp3","sec":7.656,"t":"产品如果是代谢物，要根据产物的性质，采取适当的提取、分离和纯化措施。"},{"ep":"xb3-04","n":"XB3-04","p":5,"a":"p5","id":"sp3","src":"assets/audio/XB3-04/sp3.mp3","sec":9.672,"t":"解题方法：先判断产品是菌体还是代谢物，菌体用过滤、沉淀；代谢物用提取、分离、纯化。"},{"ep":"xb3-04","n":"XB3-04","p":6,"a":"p6","id":"be1","src":"assets/audio/XB3-04/be1.mp3","sec":8.52,"t":"考点六，在食品工业上的应用，以啤酒的工业化生产为例。大麦发芽，产生淀粉酶。"},{"ep":"xb3-04","n":"XB3-04","p":6,"a":"p6","id":"be2","src":"assets/audio/XB3-04/be2.mp3","sec":8.64,"t":"焙烤：加热杀死种子的胚，但不使淀粉酶失活；然后碾磨、糖化，淀粉分解成糖浆。"},{"ep":"xb3-04","n":"XB3-04","p":6,"a":"p6","id":"be3","src":"assets/audio/XB3-04/be3.mp3","sec":6.072,"t":"蒸煮：产生风味组分，终止酶的进一步作用，并对糖浆灭菌。"},{"ep":"xb3-04","n":"XB3-04","p":6,"a":"p6","id":"be4","src":"assets/audio/XB3-04/be4.mp3","sec":12.0,"t":"接种酵母菌发酵，分主发酵和后发酵：主发酵中酵母菌繁殖、糖大部分被分解；后发酵要在低温、密闭环境下储存一段时间。"},{"ep":"xb3-04","n":"XB3-04","p":6,"a":"p6","id":"be5","src":"assets/audio/XB3-04/be5.mp3","sec":9.288,"t":"发酵工程还能生产酱油等传统产品，生产柠檬酸、味精等食品添加剂，以及淀粉酶等酶制剂。"},{"ep":"xb3-04","n":"XB3-04","p":6,"a":"p6","id":"be6","src":"assets/audio/XB3-04/be6.mp3","sec":7.848,"t":"考法：问焙烤、蒸煮的目的。易错：焙烤要杀死胚，但淀粉酶不能失活。"},{"ep":"xb3-04","n":"XB3-04","p":7,"a":"p7","id":"ap1","src":"assets/audio/XB3-04/ap1.mp3","sec":11.352,"t":"考点七，在医药和农牧业上的应用。医药上，可以生产抗生素，比如青霉素；还可以用基因工程菌生产疫苗、激素等。"},{"ep":"xb3-04","n":"XB3-04","p":7,"a":"p7","id":"ap2","src":"assets/audio/XB3-04/ap2.mp3","sec":7.536,"t":"农牧业上，生产微生物肥料，比如根瘤菌肥、固氮菌肥，能增进土壤肥力。"},{"ep":"xb3-04","n":"XB3-04","p":7,"a":"p7","id":"ap3","src":"assets/audio/XB3-04/ap3.mp3","sec":5.904,"t":"生产微生物农药，比如用苏云金杆菌防治多种农林害虫。"},{"ep":"xb3-04","n":"XB3-04","p":7,"a":"p7","id":"ap4","src":"assets/audio/XB3-04/ap4.mp3","sec":11.04,"t":"生产微生物饲料：以淀粉或纤维素的水解液、制糖工业的废液为原料，发酵获得大量的微生物菌体，叫作单细胞蛋白。"},{"ep":"xb3-04","n":"XB3-04","p":7,"a":"p7","id":"ap5","src":"assets/audio/XB3-04/ap5.mp3","sec":7.992,"t":"易错：单细胞蛋白是微生物菌体本身，不是从微生物细胞中提取出来的蛋白质。"},{"ep":"xb3-04","n":"XB3-04","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-04/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-04","n":"XB3-04","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-04/rv2.mp3","sec":12.576,"t":"判断一：发酵工程的中心环节是菌种选育？错，是发酵罐内发酵。判断二：优良菌种可以通过诱变育种获得？对。"},{"ep":"xb3-04","n":"XB3-04","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-04/rv3.mp3","sec":13.92,"t":"判断三：谷氨酸发酵在酸性条件下积累谷氨酸？错，是中性和弱碱性。判断四：产品是菌体时可用过滤、沉淀分离？对。"},{"ep":"xb3-04","n":"XB3-04","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-04/rv4.mp3","sec":12.744,"t":"判断五：单细胞蛋白是从微生物中提取的蛋白质？错，是菌体本身。判断六：苏云金杆菌可以制作微生物农药？对。"},{"ep":"xb3-04","n":"XB3-04","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-04/rv5.mp3","sec":7.464,"t":"七个考点串成一条线：发酵罐是中心，条件控制是关键。我们下期再见！"},{"ep":"xb3-05","n":"XB3-05","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-05/in1.mp3","sec":9.432,"t":"同学们好！这节课梳理人教版选择性必修三第二章第一节的上半部分——植物细胞工程的基本技术。"},{"ep":"xb3-05","n":"XB3-05","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-05/in2.mp3","sec":8.712,"t":"高考常考植物组织培养的过程和条件、植物体细胞杂交的流程，以及杂种植株的染色体数目。"},{"ep":"xb3-05","n":"XB3-05","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-05/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-05","n":"XB3-05","p":1,"a":"p1","id":"tp1","src":"assets/audio/XB3-05/tp1.mp3","sec":14.64,"t":"考点一，细胞工程与细胞的全能性。细胞工程是在细胞器、细胞或组织水平上操作，有目的地获得特定的细胞、组织、器官、个体或其产品。"},{"ep":"xb3-05","n":"XB3-05","p":1,"a":"p1","id":"tp2","src":"assets/audio/XB3-05/tp2.mp3","sec":9.864,"t":"细胞的全能性：细胞经分裂和分化后，仍然具有产生完整生物体或分化成其他各种细胞的潜能和特性。"},{"ep":"xb3-05","n":"XB3-05","p":1,"a":"p1","id":"tp3","src":"assets/audio/XB3-05/tp3.mp3","sec":4.968,"t":"原因是：每个细胞都含有该物种的全套遗传信息。"},{"ep":"xb3-05","n":"XB3-05","p":1,"a":"p1","id":"tp4","src":"assets/audio/XB3-05/tp4.mp3","sec":9.744,"t":"但在生物体内，细胞并不表现全能性，因为基因的选择性表达。必须离体，并在一定条件下才能表现。"},{"ep":"xb3-05","n":"XB3-05","p":1,"a":"p1","id":"tp5","src":"assets/audio/XB3-05/tp5.mp3","sec":11.472,"t":"考法：判断是否体现全能性。解题方法：看终点——发育成完整个体，或分化成其他各种细胞，才算体现全能性。"},{"ep":"xb3-05","n":"XB3-05","p":2,"a":"p2","id":"cu1","src":"assets/audio/XB3-05/cu1.mp3","sec":7.368,"t":"考点二，植物组织培养。把离体的植物器官、组织或细胞，叫作外植体。"},{"ep":"xb3-05","n":"XB3-05","p":2,"a":"p2","id":"cu2","src":"assets/audio/XB3-05/cu2.mp3","sec":7.944,"t":"外植体经过脱分化，失去特有的结构和功能，转变成未分化的细胞，形成愈伤组织。"},{"ep":"xb3-05","n":"XB3-05","p":2,"a":"p2","id":"cu3","src":"assets/audio/XB3-05/cu3.mp3","sec":4.008,"t":"愈伤组织是一种不定形的薄壁组织团块。"},{"ep":"xb3-05","n":"XB3-05","p":2,"a":"p2","id":"cu4","src":"assets/audio/XB3-05/cu4.mp3","sec":7.272,"t":"愈伤组织经过再分化，重新分化出芽、根等器官，最终发育成完整植株。"},{"ep":"xb3-05","n":"XB3-05","p":2,"a":"p2","id":"cu5","src":"assets/audio/XB3-05/cu5.mp3","sec":7.896,"t":"易错：脱分化形成的是愈伤组织，再分化形成的是芽、根；不要把两个过程弄反。"},{"ep":"xb3-05","n":"XB3-05","p":3,"a":"p3","id":"cd1","src":"assets/audio/XB3-05/cd1.mp3","sec":8.4,"t":"考点三，植物组织培养的条件。首先要无菌：外植体消毒，培养基和器械灭菌。"},{"ep":"xb3-05","n":"XB3-05","p":3,"a":"p3","id":"cd2","src":"assets/audio/XB3-05/cd2.mp3","sec":6.84,"t":"其次要有营养：常用MS培养基，含有无机营养和蔗糖等有机营养。"},{"ep":"xb3-05","n":"XB3-05","p":3,"a":"p3","id":"cd3","src":"assets/audio/XB3-05/cd3.mp3","sec":4.584,"t":"关键是生长素和细胞分裂素的浓度和比例。"},{"ep":"xb3-05","n":"XB3-05","p":3,"a":"p3","id":"cd4","src":"assets/audio/XB3-05/cd4.mp3","sec":11.136,"t":"生长素用量比细胞分裂素用量的比值高，有利于根的分化；比值低，有利于芽的分化；比值适中，促进愈伤组织的形成。"},{"ep":"xb3-05","n":"XB3-05","p":3,"a":"p3","id":"cd5","src":"assets/audio/XB3-05/cd5.mp3","sec":7.272,"t":"光照：诱导愈伤组织期间一般不需要光照，再分化以后要给予适当光照。"},{"ep":"xb3-05","n":"XB3-05","p":3,"a":"p3","id":"cd6","src":"assets/audio/XB3-05/cd6.mp3","sec":6.024,"t":"解题方法：记口诀——生长素多生根，细胞分裂素多生芽。"},{"ep":"xb3-05","n":"XB3-05","p":4,"a":"p4","id":"ch1","src":"assets/audio/XB3-05/ch1.mp3","sec":10.344,"t":"考点四，实验：菊花的组织培养。第一步，外植体消毒：流水冲洗后，用酒精消毒，无菌水清洗。"},{"ep":"xb3-05","n":"XB3-05","p":4,"a":"p4","id":"ch2","src":"assets/audio/XB3-05/ch2.mp3","sec":6.984,"t":"再用次氯酸钠溶液处理，最后用无菌水清洗，以免消毒剂伤害外植体。"},{"ep":"xb3-05","n":"XB3-05","p":4,"a":"p4","id":"ch3","src":"assets/audio/XB3-05/ch3.mp3","sec":7.224,"t":"第二步，把茎段切成小段，接种到诱导愈伤组织的培养基上，注意不要倒插。"},{"ep":"xb3-05","n":"XB3-05","p":4,"a":"p4","id":"ch4","src":"assets/audio/XB3-05/ch4.mp3","sec":9.216,"t":"第三步，长出愈伤组织后，转接到诱导生芽的培养基上，长出芽后再转接到诱导生根的培养基上。"},{"ep":"xb3-05","n":"XB3-05","p":4,"a":"p4","id":"ch5","src":"assets/audio/XB3-05/ch5.mp3","sec":8.304,"t":"第四步，移栽：先移到消过毒的蛭石或珍珠岩中，等幼苗长壮后再移栽到土壤中。"},{"ep":"xb3-05","n":"XB3-05","p":4,"a":"p4","id":"ch6","src":"assets/audio/XB3-05/ch6.mp3","sec":9.0,"t":"易错：外植体只能消毒，不能灭菌，灭菌会杀死外植体细胞；培养基和器械才要灭菌。"},{"ep":"xb3-05","n":"XB3-05","p":5,"a":"p5","id":"pp1","src":"assets/audio/XB3-05/pp1.mp3","sec":10.44,"t":"考点五，植物体细胞杂交。它是把不同来源的植物体细胞融合成杂种细胞，再把杂种细胞培育成新植物体。"},{"ep":"xb3-05","n":"XB3-05","p":5,"a":"p5","id":"pp2","src":"assets/audio/XB3-05/pp2.mp3","sec":9.288,"t":"第一步是去除细胞壁。植物细胞壁的主要成分是纤维素和果胶，所以用纤维素酶和果胶酶处理。"},{"ep":"xb3-05","n":"XB3-05","p":5,"a":"p5","id":"pp3","src":"assets/audio/XB3-05/pp3.mp3","sec":4.224,"t":"去掉细胞壁后得到的结构，叫作原生质体。"},{"ep":"xb3-05","n":"XB3-05","p":5,"a":"p5","id":"pp4","src":"assets/audio/XB3-05/pp4.mp3","sec":9.864,"t":"考法：酶解去壁要在等渗或略高渗的溶液中进行。解题方法：原因是防止原生质体吸水涨破。"},{"ep":"xb3-05","n":"XB3-05","p":6,"a":"p6","id":"fu1","src":"assets/audio/XB3-05/fu1.mp3","sec":10.536,"t":"考点六，原生质体融合。物理法有电融合法、离心法；化学法有聚乙二醇融合法、高钙—高pH融合法。"},{"ep":"xb3-05","n":"XB3-05","p":6,"a":"p6","id":"fu2","src":"assets/audio/XB3-05/fu2.mp3","sec":6.768,"t":"融合后得到杂种细胞，杂种细胞再生出细胞壁，标志着融合成功。"},{"ep":"xb3-05","n":"XB3-05","p":6,"a":"p6","id":"fu3","src":"assets/audio/XB3-05/fu3.mp3","sec":7.968,"t":"然后，杂种细胞经过脱分化形成愈伤组织，再经过再分化，发育成杂种植株。"},{"ep":"xb3-05","n":"XB3-05","p":6,"a":"p6","id":"fu4","src":"assets/audio/XB3-05/fu4.mp3","sec":10.512,"t":"易错：融合的结果不止杂种细胞，还有同种细胞融合的，需要筛选；动物细胞融合可以用灭活病毒，植物不用。"},{"ep":"xb3-05","n":"XB3-05","p":7,"a":"p7","id":"cs1","src":"assets/audio/XB3-05/cs1.mp3","sec":7.752,"t":"考点七，杂种植株的染色体。设甲的体细胞有2m条染色体，乙有2n条。"},{"ep":"xb3-05","n":"XB3-05","p":7,"a":"p7","id":"cs2","src":"assets/audio/XB3-05/cs2.mp3","sec":8.28,"t":"体细胞杂交得到的杂种植株，染色体是两者之和，为2m + 2n，属于异源四倍体。"},{"ep":"xb3-05","n":"XB3-05","p":7,"a":"p7","id":"cs3","src":"assets/audio/XB3-05/cs3.mp3","sec":8.256,"t":"杂种植株含有两个物种各自的同源染色体，减数分裂时能正常联会，所以一般可育。"},{"ep":"xb3-05","n":"XB3-05","p":7,"a":"p7","id":"cs4","src":"assets/audio/XB3-05/cs4.mp3","sec":6.936,"t":"如果甲乙有性杂交，后代染色体是m + n，没有同源染色体，一般不育。"},{"ep":"xb3-05","n":"XB3-05","p":7,"a":"p7","id":"cs5","src":"assets/audio/XB3-05/cs5.mp3","sec":9.024,"t":"解题方法：体细胞杂交，染色体数直接相加，几倍体也相加；有性杂交，是两个配子相加。"},{"ep":"xb3-05","n":"XB3-05","p":8,"a":"p8","id":"mn1","src":"assets/audio/XB3-05/mn1.mp3","sec":10.944,"t":"考点八，植物体细胞杂交的意义。它在打破生殖隔离、实现远缘杂交育种、培育植物新品种方面有独特的优势。"},{"ep":"xb3-05","n":"XB3-05","p":8,"a":"p8","id":"mn2","src":"assets/audio/XB3-05/mn2.mp3","sec":5.328,"t":"例如番茄—马铃薯杂种植株，就是用这种方法获得的。"},{"ep":"xb3-05","n":"XB3-05","p":8,"a":"p8","id":"mn3","src":"assets/audio/XB3-05/mn3.mp3","sec":8.88,"t":"但它没有像人们设想的那样，地上结番茄、地下长马铃薯，因为两套遗传物质的表达相互影响。"},{"ep":"xb3-05","n":"XB3-05","p":8,"a":"p8","id":"mn4","src":"assets/audio/XB3-05/mn4.mp3","sec":8.712,"t":"考法：问意义。解题方法：答“打破生殖隔离，实现远缘杂交育种”，这是标准表述。"},{"ep":"xb3-05","n":"XB3-05","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-05/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-05","n":"XB3-05","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-05/rv2.mp3","sec":11.184,"t":"判断一：植物细胞在体内就能表现全能性？错，要离体。判断二：愈伤组织是脱分化形成的？对。"},{"ep":"xb3-05","n":"XB3-05","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-05/rv3.mp3","sec":11.208,"t":"判断三：生长素比例高有利于生芽？错，有利于生根。判断四：去壁用纤维素酶和果胶酶？对。"},{"ep":"xb3-05","n":"XB3-05","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-05/rv4.mp3","sec":12.528,"t":"判断五：原生质体融合完成的标志是核融合？错，是再生出细胞壁。判断六：体细胞杂交能打破生殖隔离？对。"},{"ep":"xb3-05","n":"XB3-05","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-05/rv5.mp3","sec":7.128,"t":"八个考点串成一条线：组培靠全能性，杂交先去壁。我们下期再见！"},{"ep":"xb3-06","n":"XB3-06","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-06/in1.mp3","sec":9.024,"t":"同学们好！这节课梳理人教版选择性必修三第二章第一节的下半部分——植物细胞工程的应用。"},{"ep":"xb3-06","n":"XB3-06","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-06/in2.mp3","sec":7.944,"t":"高考常考脱毒苗与抗毒苗的区别、单倍体育种的流程，以及细胞产物工厂化生产。"},{"ep":"xb3-06","n":"XB3-06","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-06/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-06","n":"XB3-06","p":1,"a":"p1","id":"ra1","src":"assets/audio/XB3-06/ra1.mp3","sec":8.64,"t":"考点一，快速繁殖，也叫微型繁殖。它是用于快速繁殖优良品种的植物组织培养技术。"},{"ep":"xb3-06","n":"XB3-06","p":1,"a":"p1","id":"ra2","src":"assets/audio/XB3-06/ra2.mp3","sec":5.496,"t":"优点一：属于无性繁殖，能保持优良品种的遗传特性。"},{"ep":"xb3-06","n":"XB3-06","p":1,"a":"p1","id":"ra3","src":"assets/audio/XB3-06/ra3.mp3","sec":7.368,"t":"优点二：高效、快速地实现种苗的大量繁殖，而且不受季节和气候的限制。"},{"ep":"xb3-06","n":"XB3-06","p":1,"a":"p1","id":"ra4","src":"assets/audio/XB3-06/ra4.mp3","sec":6.888,"t":"常用于优良的观赏植物、经济林木、无性繁殖作物和濒危植物的繁殖。"},{"ep":"xb3-06","n":"XB3-06","p":1,"a":"p1","id":"ra5","src":"assets/audio/XB3-06/ra5.mp3","sec":9.336,"t":"考法：问快速繁殖的优点。解题方法：答“保持优良品种的遗传特性，高效快速地大量繁殖”。"},{"ep":"xb3-06","n":"XB3-06","p":2,"a":"p2","id":"vr1","src":"assets/audio/XB3-06/vr1.mp3","sec":11.64,"t":"考点二，作物脱毒。马铃薯、草莓、香蕉等无性繁殖的作物，感染的病毒会逐代积累，导致产量降低、品质变差。"},{"ep":"xb3-06","n":"XB3-06","p":2,"a":"p2","id":"vr2","src":"assets/audio/XB3-06/vr2.mp3","sec":6.024,"t":"植物顶端分生区附近，比如茎尖，病毒极少，甚至没有病毒。"},{"ep":"xb3-06","n":"XB3-06","p":2,"a":"p2","id":"vr3","src":"assets/audio/XB3-06/vr3.mp3","sec":7.968,"t":"切取一定大小的茎尖进行组织培养，再生的植株就可能不带病毒，这就是脱毒苗。"},{"ep":"xb3-06","n":"XB3-06","p":2,"a":"p2","id":"vr4","src":"assets/audio/XB3-06/vr4.mp3","sec":11.784,"t":"易错：脱毒不等于抗毒。脱毒苗只是不含病毒，种下去仍可能被感染；抗病毒植株要靠基因工程导入抗病毒基因。"},{"ep":"xb3-06","n":"XB3-06","p":3,"a":"p3","id":"ha1","src":"assets/audio/XB3-06/ha1.mp3","sec":6.816,"t":"考点三，单倍体育种。先进行花药离体培养，得到单倍体植株。"},{"ep":"xb3-06","n":"XB3-06","p":3,"a":"p3","id":"ha2","src":"assets/audio/XB3-06/ha2.mp3","sec":9.384,"t":"再用秋水仙素处理单倍体幼苗，使染色体数目加倍，得到纯合的二倍体，最后从中选育新品种。"},{"ep":"xb3-06","n":"XB3-06","p":3,"a":"p3","id":"ha3","src":"assets/audio/XB3-06/ha3.mp3","sec":5.496,"t":"它的优点是：后代都是纯合子，能明显缩短育种年限。"},{"ep":"xb3-06","n":"XB3-06","p":3,"a":"p3","id":"ha4","src":"assets/audio/XB3-06/ha4.mp3","sec":10.68,"t":"易错：花药离体培养得到的只是单倍体，一般高度不育，必须再用秋水仙素处理，才能得到可育的纯合植株。"},{"ep":"xb3-06","n":"XB3-06","p":4,"a":"p4","id":"mu1","src":"assets/audio/XB3-06/mu1.mp3","sec":8.184,"t":"考点四，突变体的利用。在组织培养过程中，培养细胞一直处于不断增殖的状态。"},{"ep":"xb3-06","n":"XB3-06","p":4,"a":"p4","id":"mu2","src":"assets/audio/XB3-06/mu2.mp3","sec":7.776,"t":"所以它们容易受到培养条件和诱变因素，比如射线、化学物质的影响，产生突变。"},{"ep":"xb3-06","n":"XB3-06","p":4,"a":"p4","id":"mu3","src":"assets/audio/XB3-06/mu3.mp3","sec":8.88,"t":"从中筛选出对人们有用的突变体，培育成新品种，比如抗花叶病的甘蔗、抗盐碱的野生烟草。"},{"ep":"xb3-06","n":"XB3-06","p":4,"a":"p4","id":"mu4","src":"assets/audio/XB3-06/mu4.mp3","sec":12.504,"t":"考法：为什么选愈伤组织进行诱变？解题方法：答“细胞分裂旺盛，DNA复制时容易发生突变”；突变不定向，所以还要筛选。"},{"ep":"xb3-06","n":"XB3-06","p":5,"a":"p5","id":"pd1","src":"assets/audio/XB3-06/pd1.mp3","sec":9.936,"t":"考点五，细胞产物的工厂化生产。很多植物产物属于次生代谢物，比如酚类、萜类和含氮化合物。"},{"ep":"xb3-06","n":"XB3-06","p":5,"a":"p5","id":"pd2","src":"assets/audio/XB3-06/pd2.mp3","sec":5.928,"t":"次生代谢物不是植物基本生命活动所必需的，含量往往很低。"},{"ep":"xb3-06","n":"XB3-06","p":5,"a":"p5","id":"pd3","src":"assets/audio/XB3-06/pd3.mp3","sec":5.136,"t":"例如从红豆杉中提取的紫杉醇，是一种抗肿瘤药物。"},{"ep":"xb3-06","n":"XB3-06","p":5,"a":"p5","id":"pd4","src":"assets/audio/XB3-06/pd4.mp3","sec":10.464,"t":"利用植物细胞培养，在离体条件下让细胞增殖，就能大量生产，而且不占用耕地，几乎不受季节、天气限制。"},{"ep":"xb3-06","n":"XB3-06","p":5,"a":"p5","id":"pd5","src":"assets/audio/XB3-06/pd5.mp3","sec":8.808,"t":"易错：细胞产物的生产不需要培养成完整植株，一般培养到细胞或愈伤组织阶段就可以提取。"},{"ep":"xb3-06","n":"XB3-06","p":6,"a":"p6","id":"cm1","src":"assets/audio/XB3-06/cm1.mp3","sec":8.88,"t":"考点六，各种应用的比较。快速繁殖和作物脱毒，都要培养成完整植株，属于无性繁殖。"},{"ep":"xb3-06","n":"XB3-06","p":6,"a":"p6","id":"cm2","src":"assets/audio/XB3-06/cm2.mp3","sec":6.816,"t":"单倍体育种从花药开始培养，还要秋水仙素处理，也要得到完整植株。"},{"ep":"xb3-06","n":"XB3-06","p":6,"a":"p6","id":"cm3","src":"assets/audio/XB3-06/cm3.mp3","sec":6.36,"t":"突变体利用在愈伤组织阶段诱变、筛选，最后也要培育成植株。"},{"ep":"xb3-06","n":"XB3-06","p":6,"a":"p6","id":"cm4","src":"assets/audio/XB3-06/cm4.mp3","sec":6.504,"t":"只有细胞产物的工厂化生产，培养到细胞阶段就停止，不需要再分化。"},{"ep":"xb3-06","n":"XB3-06","p":6,"a":"p6","id":"cm5","src":"assets/audio/XB3-06/cm5.mp3","sec":8.448,"t":"解题方法：看目的——要新植株，就必须经过再分化；要细胞产物，停在细胞阶段就行。"},{"ep":"xb3-06","n":"XB3-06","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-06/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-06","n":"XB3-06","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-06/rv2.mp3","sec":12.264,"t":"判断一：快速繁殖能保持优良品种的遗传特性？对。判断二：脱毒苗具有抗病毒能力？错，脱毒不等于抗毒。"},{"ep":"xb3-06","n":"XB3-06","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-06/rv3.mp3","sec":13.272,"t":"判断三：花药离体培养得到的植株一般是纯合子？错，得到的是单倍体。判断四：愈伤组织细胞分裂旺盛，容易突变？对。"},{"ep":"xb3-06","n":"XB3-06","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-06/rv4.mp3","sec":13.584,"t":"判断五：生产紫杉醇要把细胞培养成完整植株？错，培养到细胞阶段即可。判断六：次生代谢物不是植物生长所必需的？对。"},{"ep":"xb3-06","n":"XB3-06","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-06/rv5.mp3","sec":7.536,"t":"六个考点串成一条线：要植株就再分化，要产物停在细胞。我们下期再见！"},{"ep":"xb3-07","n":"XB3-07","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-07/in1.mp3","sec":8.352,"t":"同学们好！这节课梳理人教版选择性必修三第二章第二节的第一部分——动物细胞培养。"},{"ep":"xb3-07","n":"XB3-07","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-07/in2.mp3","sec":7.92,"t":"高考常考动物细胞培养的条件、原代培养和传代培养，以及干细胞的类型和应用。"},{"ep":"xb3-07","n":"XB3-07","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-07/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-07","n":"XB3-07","p":1,"a":"p1","id":"ov1","src":"assets/audio/XB3-07/ov1.mp3","sec":9.528,"t":"考点一，动物细胞工程。常用的技术有动物细胞培养、动物细胞融合和动物体细胞核移植等。"},{"ep":"xb3-07","n":"XB3-07","p":1,"a":"p1","id":"ov2","src":"assets/audio/XB3-07/ov2.mp3","sec":4.608,"t":"其中，动物细胞培养是动物细胞工程的基础。"},{"ep":"xb3-07","n":"XB3-07","p":1,"a":"p1","id":"ov3","src":"assets/audio/XB3-07/ov3.mp3","sec":10.8,"t":"动物细胞培养，是从动物体中取出相关的组织，把它分散成单个细胞，在适宜条件下让这些细胞生长和增殖的技术。"},{"ep":"xb3-07","n":"XB3-07","p":1,"a":"p1","id":"ov4","src":"assets/audio/XB3-07/ov4.mp3","sec":8.328,"t":"考法：问原理。解题方法：动物细胞培养的原理是细胞增殖，不是细胞全能性。"},{"ep":"xb3-07","n":"XB3-07","p":2,"a":"p2","id":"cd1","src":"assets/audio/XB3-07/cd1.mp3","sec":11.544,"t":"考点二，动物细胞培养的条件。第一，营养：糖类、氨基酸、无机盐、维生素等，通常还要加入血清等天然成分。"},{"ep":"xb3-07","n":"XB3-07","p":2,"a":"p2","id":"cd2","src":"assets/audio/XB3-07/cd2.mp3","sec":8.664,"t":"第二，无菌、无毒的环境：培养液和用具要灭菌，还要定期更换培养液，清除代谢物。"},{"ep":"xb3-07","n":"XB3-07","p":2,"a":"p2","id":"cd3","src":"assets/audio/XB3-07/cd3.mp3","sec":10.104,"t":"第三，适宜的温度、pH和渗透压：哺乳动物细胞多在 36.5 ℃ 左右，pH 为 7.2～7.4。"},{"ep":"xb3-07","n":"XB3-07","p":2,"a":"p2","id":"cd4","src":"assets/audio/XB3-07/cd4.mp3","sec":8.928,"t":"第四，气体环境：95% 空气 + 5% CO2，放在 CO2 培养箱中培养。"},{"ep":"xb3-07","n":"XB3-07","p":2,"a":"p2","id":"cd5","src":"assets/audio/XB3-07/cd5.mp3","sec":7.68,"t":"易错：O2是细胞代谢所必需的；CO2的主要作用是维持培养液的pH。"},{"ep":"xb3-07","n":"XB3-07","p":3,"a":"p3","id":"ps1","src":"assets/audio/XB3-07/ps1.mp3","sec":11.856,"t":"考点三，动物细胞培养的过程。取动物组织，剪碎，用胰蛋白酶、胶原蛋白酶等处理，分散成单个细胞，制成细胞悬液。"},{"ep":"xb3-07","n":"XB3-07","p":3,"a":"p3","id":"ps2","src":"assets/audio/XB3-07/ps2.mp3","sec":7.056,"t":"把细胞悬液放入培养瓶中培养，这是原代培养，也就是分瓶之前的培养。"},{"ep":"xb3-07","n":"XB3-07","p":3,"a":"p3","id":"ps3","src":"assets/audio/XB3-07/ps3.mp3","sec":6.6,"t":"细胞长满后，再用胰蛋白酶处理，分瓶继续培养，这就是传代培养。"},{"ep":"xb3-07","n":"XB3-07","p":3,"a":"p3","id":"ps4","src":"assets/audio/XB3-07/ps4.mp3","sec":8.88,"t":"易错：不能用胃蛋白酶，因为胃蛋白酶的最适pH是酸性，而动物细胞培养液接近中性。"},{"ep":"xb3-07","n":"XB3-07","p":4,"a":"p4","id":"co1","src":"assets/audio/XB3-07/co1.mp3","sec":9.216,"t":"考点四，贴壁生长和接触抑制。悬液中分散的细胞很快就贴附在瓶壁上，这叫细胞贴壁。"},{"ep":"xb3-07","n":"XB3-07","p":4,"a":"p4","id":"co2","src":"assets/audio/XB3-07/co2.mp3","sec":8.328,"t":"贴壁细胞分裂生长，当细胞表面相互接触时，通常会停止分裂增殖，这叫接触抑制。"},{"ep":"xb3-07","n":"XB3-07","p":4,"a":"p4","id":"co3","src":"assets/audio/XB3-07/co3.mp3","sec":6.84,"t":"所以，原代培养的细胞长满瓶壁后，要用胰蛋白酶处理、分瓶传代。"},{"ep":"xb3-07","n":"XB3-07","p":4,"a":"p4","id":"co4","src":"assets/audio/XB3-07/co4.mp3","sec":9.744,"t":"考法：传代时为什么要用胰蛋白酶？解题方法：让贴壁的细胞从瓶壁上脱离，分散成单个细胞。"},{"ep":"xb3-07","n":"XB3-07","p":5,"a":"p5","id":"st1","src":"assets/audio/XB3-07/st1.mp3","sec":7.752,"t":"考点五，干细胞的类型。胚胎干细胞，简称ES细胞，存在于早期胚胎中。"},{"ep":"xb3-07","n":"XB3-07","p":5,"a":"p5","id":"st2","src":"assets/audio/XB3-07/st2.mp3","sec":9.072,"t":"它具有分化为成年动物体内任何一种类型的细胞，并形成机体所有组织和器官、甚至个体的潜能。"},{"ep":"xb3-07","n":"XB3-07","p":5,"a":"p5","id":"st3","src":"assets/audio/XB3-07/st3.mp3","sec":11.232,"t":"成体干细胞，存在于成体组织中，比如骨髓中的造血干细胞、神经干细胞。它们一般只能分化成特定的细胞或组织。"},{"ep":"xb3-07","n":"XB3-07","p":5,"a":"p5","id":"st4","src":"assets/audio/XB3-07/st4.mp3","sec":9.456,"t":"诱导多能干细胞，简称iPS细胞，是通过体外诱导成纤维细胞等，获得的类似胚胎干细胞的细胞。"},{"ep":"xb3-07","n":"XB3-07","p":5,"a":"p5","id":"st5","src":"assets/audio/XB3-07/st5.mp3","sec":7.584,"t":"易错：成体干细胞不具有发育成完整个体的能力；ES 细胞的分化潜能最大。"},{"ep":"xb3-07","n":"XB3-07","p":6,"a":"p6","id":"sa1","src":"assets/audio/XB3-07/sa1.mp3","sec":8.304,"t":"考点六，干细胞的应用。造血干细胞移植，比如骨髓移植，可以治疗白血病等疾病。"},{"ep":"xb3-07","n":"XB3-07","p":6,"a":"p6","id":"sa2","src":"assets/audio/XB3-07/sa2.mp3","sec":6.264,"t":"ES细胞必须从胚胎中获取，涉及伦理问题，应用受到限制。"},{"ep":"xb3-07","n":"XB3-07","p":6,"a":"p6","id":"sa3","src":"assets/audio/XB3-07/sa3.mp3","sec":10.368,"t":"iPS细胞可以来源于病人自身的体细胞，用它培育的细胞或器官移植回病人体内，理论上可以避免免疫排斥。"},{"ep":"xb3-07","n":"XB3-07","p":6,"a":"p6","id":"sa4","src":"assets/audio/XB3-07/sa4.mp3","sec":7.128,"t":"易错：iPS细胞也有风险，比如可能导致肿瘤的发生；不要只记优点。"},{"ep":"xb3-07","n":"XB3-07","p":7,"a":"p7","id":"vs1","src":"assets/audio/XB3-07/vs1.mp3","sec":12.024,"t":"考点七，动物细胞培养与植物组织培养的比较。原理不同：植物组织培养是细胞的全能性，动物细胞培养是细胞增殖。"},{"ep":"xb3-07","n":"XB3-07","p":7,"a":"p7","id":"vs2","src":"assets/audio/XB3-07/vs2.mp3","sec":8.016,"t":"培养基不同：植物用固体培养基，加植物激素；动物用液体培养基，常加血清。"},{"ep":"xb3-07","n":"XB3-07","p":7,"a":"p7","id":"vs3","src":"assets/audio/XB3-07/vs3.mp3","sec":8.304,"t":"结果不同：植物组织培养得到完整植株；动物细胞培养得到的是细胞群，不是个体。"},{"ep":"xb3-07","n":"XB3-07","p":7,"a":"p7","id":"vs4","src":"assets/audio/XB3-07/vs4.mp3","sec":7.008,"t":"易错：动物细胞培养不能体现细胞的全能性，因为没有发育成完整个体。"},{"ep":"xb3-07","n":"XB3-07","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-07/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-07","n":"XB3-07","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-07/rv2.mp3","sec":13.44,"t":"判断一：动物细胞培养常需加入血清等天然成分？对。判断二：CO2主要用于细胞呼吸？错，主要是维持培养液的pH。"},{"ep":"xb3-07","n":"XB3-07","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-07/rv3.mp3","sec":11.352,"t":"判断三：分散动物组织可以用胃蛋白酶？错，用胰蛋白酶。判断四：接触抑制时需要分瓶传代？对。"},{"ep":"xb3-07","n":"XB3-07","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-07/rv4.mp3","sec":11.064,"t":"判断五：成体干细胞能发育成完整个体？错。判断六：动物细胞培养不能体现细胞的全能性？对。"},{"ep":"xb3-07","n":"XB3-07","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-07/rv5.mp3","sec":8.304,"t":"七个考点串成一条线：胰酶分散、血清营养，CO2稳pH。我们下期再见！"},{"ep":"xb3-08","n":"XB3-08","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-08/in1.mp3","sec":10.152,"t":"同学们好！这节课梳理人教版选择性必修三第二章第二节的第二部分——动物细胞融合技术与单克隆抗体。"},{"ep":"xb3-08","n":"XB3-08","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-08/in2.mp3","sec":8.016,"t":"高考常考单克隆抗体的制备流程、两次筛选的目的和方法，以及杂交瘤细胞的特点。"},{"ep":"xb3-08","n":"XB3-08","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-08/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-08","n":"XB3-08","p":1,"a":"p1","id":"fu1","src":"assets/audio/XB3-08/fu1.mp3","sec":10.872,"t":"考点一，动物细胞融合。它是使两个或多个动物细胞结合形成一个细胞的技术，融合后形成的细胞叫杂交细胞。"},{"ep":"xb3-08","n":"XB3-08","p":1,"a":"p1","id":"fu2","src":"assets/audio/XB3-08/fu2.mp3","sec":4.44,"t":"杂交细胞具有原来两个或多个细胞的遗传信息。"},{"ep":"xb3-08","n":"XB3-08","p":1,"a":"p1","id":"fu3","src":"assets/audio/XB3-08/fu3.mp3","sec":7.8,"t":"诱导方法有：PEG融合法、电融合法和灭活病毒诱导法。"},{"ep":"xb3-08","n":"XB3-08","p":1,"a":"p1","id":"fu4","src":"assets/audio/XB3-08/fu4.mp3","sec":7.536,"t":"灭活病毒，是指用物理或化学手段使病毒失去感染能力，但保留了融合活性。"},{"ep":"xb3-08","n":"XB3-08","p":1,"a":"p1","id":"fu5","src":"assets/audio/XB3-08/fu5.mp3","sec":7.872,"t":"易错：灭活病毒诱导法是动物细胞融合特有的方法，不能用于植物原生质体融合。"},{"ep":"xb3-08","n":"XB3-08","p":2,"a":"p2","id":"cm1","src":"assets/audio/XB3-08/cm1.mp3","sec":11.808,"t":"考点二，动物细胞融合与植物体细胞杂交的比较。原理：都依赖细胞膜的流动性，植物体细胞杂交还要用到细胞的全能性。"},{"ep":"xb3-08","n":"XB3-08","p":2,"a":"p2","id":"cm2","src":"assets/audio/XB3-08/cm2.mp3","sec":8.976,"t":"前处理：植物要先用纤维素酶和果胶酶去除细胞壁；动物要用胰蛋白酶分散成单个细胞。"},{"ep":"xb3-08","n":"XB3-08","p":2,"a":"p2","id":"cm3","src":"assets/audio/XB3-08/cm3.mp3","sec":4.824,"t":"诱导方法：动物比植物多了一个灭活病毒诱导法。"},{"ep":"xb3-08","n":"XB3-08","p":2,"a":"p2","id":"cm4","src":"assets/audio/XB3-08/cm4.mp3","sec":7.608,"t":"结果：植物体细胞杂交得到杂种植株；动物细胞融合一般只得到杂交细胞。"},{"ep":"xb3-08","n":"XB3-08","p":2,"a":"p2","id":"cm5","src":"assets/audio/XB3-08/cm5.mp3","sec":8.592,"t":"考法：比较表格。解题方法：抓住三处不同——去壁、灭活病毒、能否得到个体。"},{"ep":"xb3-08","n":"XB3-08","p":3,"a":"p3","id":"pr1","src":"assets/audio/XB3-08/pr1.mp3","sec":7.92,"t":"考点三，单克隆抗体的制备流程。第一步，用特定的抗原对小鼠进行免疫。"},{"ep":"xb3-08","n":"XB3-08","p":3,"a":"p3","id":"pr2","src":"assets/audio/XB3-08/pr2.mp3","sec":5.664,"t":"第二步，从小鼠脾中获得能产生特定抗体的B淋巴细胞。"},{"ep":"xb3-08","n":"XB3-08","p":3,"a":"p3","id":"pr3","src":"assets/audio/XB3-08/pr3.mp3","sec":9.648,"t":"第三步，把B淋巴细胞和骨髓瘤细胞融合，用特定的选择培养基进行第一次筛选，得到杂交瘤细胞。"},{"ep":"xb3-08","n":"XB3-08","p":3,"a":"p3","id":"pr4","src":"assets/audio/XB3-08/pr4.mp3","sec":10.104,"t":"第四步，对杂交瘤细胞进行克隆化培养和抗体检测，第二次筛选，得到能产生所需抗体的杂交瘤细胞。"},{"ep":"xb3-08","n":"XB3-08","p":3,"a":"p3","id":"pr5","src":"assets/audio/XB3-08/pr5.mp3","sec":9.216,"t":"第五步，把它注射到小鼠腹腔内增殖，或者在体外培养，从腹水或培养液中获取单克隆抗体。"},{"ep":"xb3-08","n":"XB3-08","p":3,"a":"p3","id":"pr6","src":"assets/audio/XB3-08/pr6.mp3","sec":9.408,"t":"考法：流程图填空。解题方法：记住顺序——免疫、取细胞、融合、两次筛选、培养。"},{"ep":"xb3-08","n":"XB3-08","p":4,"a":"p4","id":"sc1","src":"assets/audio/XB3-08/sc1.mp3","sec":12.408,"t":"考点四，两次筛选。融合后的细胞有多种：未融合的细胞、同种细胞融合的细胞，以及B细胞和骨髓瘤细胞融合的杂交瘤细胞。"},{"ep":"xb3-08","n":"XB3-08","p":4,"a":"p4","id":"sc2","src":"assets/audio/XB3-08/sc2.mp3","sec":8.448,"t":"第一次筛选：用特定的选择培养基，在上面只有杂交瘤细胞才能生长，其他细胞都死亡。"},{"ep":"xb3-08","n":"XB3-08","p":4,"a":"p4","id":"sc3","src":"assets/audio/XB3-08/sc3.mp3","sec":8.112,"t":"但是，免疫小鼠的B细胞有很多种，所以得到的杂交瘤细胞产生的抗体也各不相同。"},{"ep":"xb3-08","n":"XB3-08","p":4,"a":"p4","id":"sc4","src":"assets/audio/XB3-08/sc4.mp3","sec":9.096,"t":"第二次筛选：进行克隆化培养和抗体检测，经多次筛选，得到能分泌所需抗体的杂交瘤细胞。"},{"ep":"xb3-08","n":"XB3-08","p":4,"a":"p4","id":"sc5","src":"assets/audio/XB3-08/sc5.mp3","sec":12.168,"t":"易错：两次筛选的方法和目的不同——第一次靠选择培养基，选出杂交瘤细胞；第二次靠抗体检测，选出能产生特定抗体的细胞。"},{"ep":"xb3-08","n":"XB3-08","p":5,"a":"p5","id":"hy1","src":"assets/audio/XB3-08/hy1.mp3","sec":7.464,"t":"考点五，杂交瘤细胞的特点。B淋巴细胞能产生抗体，但不能无限增殖。"},{"ep":"xb3-08","n":"XB3-08","p":5,"a":"p5","id":"hy2","src":"assets/audio/XB3-08/hy2.mp3","sec":4.512,"t":"骨髓瘤细胞能无限增殖，但不能产生抗体。"},{"ep":"xb3-08","n":"XB3-08","p":5,"a":"p5","id":"hy3","src":"assets/audio/XB3-08/hy3.mp3","sec":6.144,"t":"两者融合成的杂交瘤细胞，既能迅速大量增殖，又能产生抗体。"},{"ep":"xb3-08","n":"XB3-08","p":5,"a":"p5","id":"hy4","src":"assets/audio/XB3-08/hy4.mp3","sec":9.096,"t":"考法：问为什么选这两种细胞融合。解题方法：答各自的优点和缺点，融合后优点互补。"},{"ep":"xb3-08","n":"XB3-08","p":6,"a":"p6","id":"ap1","src":"assets/audio/XB3-08/ap1.mp3","sec":12.216,"t":"考点六，单克隆抗体的优点和应用。优点：能准确地识别抗原的细微差异，与特定抗原发生特异性结合，并且可以大量制备。"},{"ep":"xb3-08","n":"XB3-08","p":6,"a":"p6","id":"ap2","src":"assets/audio/XB3-08/ap2.mp3","sec":6.984,"t":"应用一：作为诊断试剂，比如快速准确地识别各种病原体，检测早孕。"},{"ep":"xb3-08","n":"XB3-08","p":6,"a":"p6","id":"ap3","src":"assets/audio/XB3-08/ap3.mp3","sec":6.552,"t":"应用二：用于运载药物，也就是抗体—药物偶联物，简称ADC。"},{"ep":"xb3-08","n":"XB3-08","p":6,"a":"p6","id":"ap4","src":"assets/audio/XB3-08/ap4.mp3","sec":8.736,"t":"ADC由抗体、接头和药物三部分组成：抗体负责识别、定位肿瘤细胞，药物负责杀伤。"},{"ep":"xb3-08","n":"XB3-08","p":6,"a":"p6","id":"ap5","src":"assets/audio/XB3-08/ap5.mp3","sec":8.496,"t":"易错：在ADC中，起治疗作用、杀伤肿瘤细胞的是药物，单克隆抗体起的是导向作用。"},{"ep":"xb3-08","n":"XB3-08","p":7,"a":"p7","id":"bc1","src":"assets/audio/XB3-08/bc1.mp3","sec":9.624,"t":"考点七，B淋巴细胞的来源。必须先用特定的抗原免疫小鼠，再从小鼠的脾中提取B淋巴细胞。"},{"ep":"xb3-08","n":"XB3-08","p":7,"a":"p7","id":"bc2","src":"assets/audio/XB3-08/bc2.mp3","sec":6.024,"t":"因为只有经过免疫的B淋巴细胞，才能产生针对这种抗原的抗体。"},{"ep":"xb3-08","n":"XB3-08","p":7,"a":"p7","id":"bc3","src":"assets/audio/XB3-08/bc3.mp3","sec":7.632,"t":"而且一般要多次免疫，并检测小鼠血清中的抗体，确认免疫成功后再取脾。"},{"ep":"xb3-08","n":"XB3-08","p":7,"a":"p7","id":"bc4","src":"assets/audio/XB3-08/bc4.mp3","sec":11.52,"t":"易错：未免疫小鼠的B细胞，不能产生所需的抗体；单克隆抗体中的“单克隆”，指的是由单个杂交瘤细胞增殖形成的细胞群。"},{"ep":"xb3-08","n":"XB3-08","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-08/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-08","n":"XB3-08","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-08/rv2.mp3","sec":13.152,"t":"判断一：灭活病毒可以诱导植物原生质体融合？错。判断二：动物细胞融合能形成杂种个体？错，一般只得到杂交细胞。"},{"ep":"xb3-08","n":"XB3-08","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-08/rv3.mp3","sec":13.344,"t":"判断三：第一次筛选用特定的选择培养基？对。判断四：选择培养基上存活的细胞都能产生所需抗体？错，还要抗体检测。"},{"ep":"xb3-08","n":"XB3-08","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-08/rv4.mp3","sec":11.448,"t":"判断五：单克隆抗体特异性强、灵敏度高？对。判断六：B淋巴细胞要从免疫过的小鼠脾中获取？对。"},{"ep":"xb3-08","n":"XB3-08","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-08/rv5.mp3","sec":7.368,"t":"七个考点串成一条线：先免疫再融合，两次筛选得单抗。我们下期再见！"},{"ep":"xb3-09","n":"XB3-09","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-09/in1.mp3","sec":10.368,"t":"同学们好！这节课梳理人教版选择性必修三第二章第二节的第三部分——动物体细胞核移植技术和克隆动物。"},{"ep":"xb3-09","n":"XB3-09","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-09/in2.mp3","sec":8.976,"t":"高考常考核移植的操作流程、卵母细胞为什么要培养到MⅡ期，以及克隆动物遗传物质的来源。"},{"ep":"xb3-09","n":"XB3-09","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-09/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-09","n":"XB3-09","p":1,"a":"p1","id":"co1","src":"assets/audio/XB3-09/co1.mp3","sec":12.816,"t":"考点一，核移植的概念。把动物一个细胞的细胞核，移入去核的卵母细胞中，使这个重新组合的细胞发育成新胚胎，继而发育成动物个体。"},{"ep":"xb3-09","n":"XB3-09","p":1,"a":"p1","id":"co2","src":"assets/audio/XB3-09/co2.mp3","sec":10.032,"t":"用核移植方法得到的动物，叫作克隆动物。1996年诞生的克隆羊多莉，是第一只体细胞克隆哺乳动物。"},{"ep":"xb3-09","n":"XB3-09","p":1,"a":"p1","id":"co3","src":"assets/audio/XB3-09/co3.mp3","sec":5.448,"t":"哺乳动物核移植分为胚胎细胞核移植和体细胞核移植。"},{"ep":"xb3-09","n":"XB3-09","p":1,"a":"p1","id":"co4","src":"assets/audio/XB3-09/co4.mp3","sec":7.92,"t":"体细胞核移植的难度明显更高，因为体细胞分化程度高，恢复其全能性十分困难。"},{"ep":"xb3-09","n":"XB3-09","p":1,"a":"p1","id":"co5","src":"assets/audio/XB3-09/co5.mp3","sec":9.744,"t":"考法：问原理。解题方法：核移植的原理是动物细胞核的全能性，注意是“细胞核”，不是动物细胞。"},{"ep":"xb3-09","n":"XB3-09","p":2,"a":"p2","id":"pr1","src":"assets/audio/XB3-09/pr1.mp3","sec":7.416,"t":"考点二，体细胞核移植的过程。采集卵母细胞，在体外培养到MⅡ期。"},{"ep":"xb3-09","n":"XB3-09","p":2,"a":"p2","id":"pr2","src":"assets/audio/XB3-09/pr2.mp3","sec":5.16,"t":"通过显微操作去核。另一边，培养供体的体细胞。"},{"ep":"xb3-09","n":"XB3-09","p":2,"a":"p2","id":"pr3","src":"assets/audio/XB3-09/pr3.mp3","sec":7.44,"t":"把供体细胞注入去核的卵母细胞，用电融合法使两细胞融合，形成重构胚。"},{"ep":"xb3-09","n":"XB3-09","p":2,"a":"p2","id":"pr4","src":"assets/audio/XB3-09/pr4.mp3","sec":9.888,"t":"用物理或化学方法激活重构胚，比如电刺激、钙离子载体、乙醇等，使它完成细胞分裂和发育进程。"},{"ep":"xb3-09","n":"XB3-09","p":2,"a":"p2","id":"pr5","src":"assets/audio/XB3-09/pr5.mp3","sec":4.968,"t":"最后，把胚胎移植到代孕母体中，生出克隆动物。"},{"ep":"xb3-09","n":"XB3-09","p":2,"a":"p2","id":"pr6","src":"assets/audio/XB3-09/pr6.mp3","sec":11.208,"t":"考法：流程排序。解题方法：记住六个关键词——培养到MⅡ期、去核、注入、融合、激活、胚胎移植。"},{"ep":"xb3-09","n":"XB3-09","p":3,"a":"p3","id":"mi1","src":"assets/audio/XB3-09/mi1.mp3","sec":8.184,"t":"考点三，为什么用MⅡ期卵母细胞做受体。第一，卵母细胞体积大，便于操作。"},{"ep":"xb3-09","n":"XB3-09","p":3,"a":"p3","id":"mi2","src":"assets/audio/XB3-09/mi2.mp3","sec":5.304,"t":"第二，细胞质中含有促使细胞核全能性表达的物质。"},{"ep":"xb3-09","n":"XB3-09","p":3,"a":"p3","id":"mi3","src":"assets/audio/XB3-09/mi3.mp3","sec":5.424,"t":"第三，营养物质丰富，能为早期胚胎发育提供营养。"},{"ep":"xb3-09","n":"XB3-09","p":3,"a":"p3","id":"mi4","src":"assets/audio/XB3-09/mi4.mp3","sec":8.304,"t":"另外，MⅡ期的卵母细胞没有核膜，所谓“去核”，去除的其实是纺锤体—染色体复合物。"},{"ep":"xb3-09","n":"XB3-09","p":3,"a":"p3","id":"mi5","src":"assets/audio/XB3-09/mi5.mp3","sec":6.192,"t":"易错：去核的目的，是保证克隆动物的核遗传物质全部来自供体。"},{"ep":"xb3-09","n":"XB3-09","p":4,"a":"p4","id":"ge1","src":"assets/audio/XB3-09/ge1.mp3","sec":6.768,"t":"考点四，克隆动物遗传物质的来源。核基因，全部来自供体细胞。"},{"ep":"xb3-09","n":"XB3-09","p":4,"a":"p4","id":"ge2","src":"assets/audio/XB3-09/ge2.mp3","sec":6.984,"t":"细胞质基因，比如线粒体DNA，主要来自去核的卵母细胞，也就是受体。"},{"ep":"xb3-09","n":"XB3-09","p":4,"a":"p4","id":"ge3","src":"assets/audio/XB3-09/ge3.mp3","sec":5.232,"t":"代孕母体只提供{胚胎发育的场所|brown}，不提供遗传物质。"},{"ep":"xb3-09","n":"XB3-09","p":4,"a":"p4","id":"ge4","src":"assets/audio/XB3-09/ge4.mp3","sec":8.4,"t":"解题方法：判断克隆动物的性别和主要性状，看供核的个体；克隆动物属于无性繁殖。"},{"ep":"xb3-09","n":"XB3-09","p":5,"a":"p5","id":"ap1","src":"assets/audio/XB3-09/ap1.mp3","sec":9.24,"t":"考点五，核移植技术的应用。畜牧业上，可以加速家畜遗传改良进程，促进优良畜群繁育。"},{"ep":"xb3-09","n":"XB3-09","p":5,"a":"p5","id":"ap2","src":"assets/audio/XB3-09/ap2.mp3","sec":10.128,"t":"医药卫生上，转基因克隆动物可以作为生物反应器，生产医用蛋白；克隆动物的组织器官可作为异种移植的供体。"},{"ep":"xb3-09","n":"XB3-09","p":5,"a":"p5","id":"ap3","src":"assets/audio/XB3-09/ap3.mp3","sec":9.552,"t":"治疗性克隆：用病人的体细胞核移植获得胚胎干细胞，诱导分化成所需的细胞、组织，用于治疗。"},{"ep":"xb3-09","n":"XB3-09","p":5,"a":"p5","id":"ap4","src":"assets/audio/XB3-09/ap4.mp3","sec":10.416,"t":"核移植还可以用来保护濒危物种，增加它们的存活数量。我国科学家还获得了体细胞克隆猴“中中”和“华华”。"},{"ep":"xb3-09","n":"XB3-09","p":5,"a":"p5","id":"ap5","src":"assets/audio/XB3-09/ap5.mp3","sec":7.704,"t":"易错：核移植技术还存在问题，比如成功率非常低，克隆动物存在健康问题。"},{"ep":"xb3-09","n":"XB3-09","p":6,"a":"p6","id":"df1","src":"assets/audio/XB3-09/df1.mp3","sec":10.08,"t":"考点六，克隆动物与供体的性状为什么不完全相同？原因一：克隆动物的细胞质基因来自受体卵母细胞。"},{"ep":"xb3-09","n":"XB3-09","p":6,"a":"p6","id":"df2","src":"assets/audio/XB3-09/df2.mp3","sec":8.304,"t":"原因二：生物的性状还受环境因素的影响，表现型是基因型和环境共同作用的结果。"},{"ep":"xb3-09","n":"XB3-09","p":6,"a":"p6","id":"df3","src":"assets/audio/XB3-09/df3.mp3","sec":5.16,"t":"原因三：在发育过程中，可能发生基因突变等变异。"},{"ep":"xb3-09","n":"XB3-09","p":6,"a":"p6","id":"df4","src":"assets/audio/XB3-09/df4.mp3","sec":9.048,"t":"考法：问原因。解题方法：从“细胞质遗传、环境影响”两个方面作答，就能拿到主要分数。"},{"ep":"xb3-09","n":"XB3-09","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-09/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-09","n":"XB3-09","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-09/rv2.mp3","sec":11.424,"t":"判断一：体细胞核移植比胚胎细胞核移植更容易？错。判断二：受体卵母细胞要培养到MⅡ期？对。"},{"ep":"xb3-09","n":"XB3-09","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-09/rv3.mp3","sec":12.864,"t":"判断三：去核去除的是完整的细胞核？错，是纺锤体—染色体复合物。判断四：克隆动物的性别与供核个体相同？对。"},{"ep":"xb3-09","n":"XB3-09","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-09/rv4.mp3","sec":11.424,"t":"判断五：克隆动物与供体性状完全相同？错。判断六：体细胞核移植体现了动物细胞核的全能性？对。"},{"ep":"xb3-09","n":"XB3-09","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-09/rv5.mp3","sec":6.768,"t":"六个考点串成一条线：核来自供体，质来自受体。我们下期再见！"},{"ep":"xb3-10","n":"XB3-10","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-10/in1.mp3","sec":9.24,"t":"同学们好！这节课梳理人教版选择性必修三第二章第三节的上半部分——胚胎工程的理论基础。"},{"ep":"xb3-10","n":"XB3-10","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-10/in2.mp3","sec":8.184,"t":"高考常考受精前的准备、防止多精入卵的两道屏障，以及早期胚胎发育各阶段的特点。"},{"ep":"xb3-10","n":"XB3-10","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-10/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-10","n":"XB3-10","p":1,"a":"p1","id":"co1","src":"assets/audio/XB3-10/co1.mp3","sec":14.808,"t":"考点一，胚胎工程的概念。它是对生殖细胞、受精卵或早期胚胎细胞进行多种显微操作和处理，然后将获得的胚胎移植到雌性动物体内生产后代的技术。"},{"ep":"xb3-10","n":"XB3-10","p":1,"a":"p1","id":"co2","src":"assets/audio/XB3-10/co2.mp3","sec":5.784,"t":"胚胎工程的技术包括体外受精、胚胎移植、胚胎分割等。"},{"ep":"xb3-10","n":"XB3-10","p":1,"a":"p1","id":"co3","src":"assets/audio/XB3-10/co3.mp3","sec":5.352,"t":"它的理论基础，是哺乳动物受精和早期胚胎发育的规律。"},{"ep":"xb3-10","n":"XB3-10","p":1,"a":"p1","id":"co4","src":"assets/audio/XB3-10/co4.mp3","sec":11.04,"t":"易错：胚胎工程的操作对象是生殖细胞、受精卵和早期胚胎，不是体细胞；最终都要经过胚胎移植才能获得后代。"},{"ep":"xb3-10","n":"XB3-10","p":2,"a":"p2","id":"pr1","src":"assets/audio/XB3-10/pr1.mp3","sec":10.08,"t":"考点二，受精前的准备。受精是精子与卵子结合形成合子，也就是受精卵的过程，在输卵管内完成。"},{"ep":"xb3-10","n":"XB3-10","p":2,"a":"p2","id":"pr2","src":"assets/audio/XB3-10/pr2.mp3","sec":11.304,"t":"精子获能：刚排出的精子不能立即与卵子受精，必须在雌性动物生殖道中发生相应的生理变化后，才能获得受精能力。"},{"ep":"xb3-10","n":"XB3-10","p":2,"a":"p2","id":"pr3","src":"assets/audio/XB3-10/pr3.mp3","sec":8.424,"t":"卵子的准备：卵子要在输卵管内进一步成熟，到MⅡ期时，才具备与精子受精的能力。"},{"ep":"xb3-10","n":"XB3-10","p":2,"a":"p2","id":"pr4","src":"assets/audio/XB3-10/pr4.mp3","sec":8.88,"t":"易错：获能不是获得能量，而是获得受精能力；体外受精时，精子也要先进行获能处理。"},{"ep":"xb3-10","n":"XB3-10","p":3,"a":"p3","id":"fe1","src":"assets/audio/XB3-10/fe1.mp3","sec":13.008,"t":"考点三，受精过程。获能后的精子与卵子相遇时，释放多种酶，溶解卵细胞膜外的一些结构，同时借助自身的运动接触卵细胞膜。"},{"ep":"xb3-10","n":"XB3-10","p":3,"a":"p3","id":"fe2","src":"assets/audio/XB3-10/fe2.mp3","sec":9.864,"t":"精子触及卵细胞膜的瞬间，透明带迅速发生生理反应，阻止后来的精子进入透明带，这是第一道屏障。"},{"ep":"xb3-10","n":"XB3-10","p":3,"a":"p3","id":"fe3","src":"assets/audio/XB3-10/fe3.mp3","sec":9.048,"t":"精子入卵后，卵细胞膜也会立即发生生理反应，拒绝其他精子再进入卵内，这是第二道屏障。"},{"ep":"xb3-10","n":"XB3-10","p":3,"a":"p3","id":"fe4","src":"assets/audio/XB3-10/fe4.mp3","sec":11.04,"t":"精子入卵后，形成雄原核；卵子完成减数分裂Ⅱ，排出第二极体，形成雌原核。两者融合，形成受精卵。"},{"ep":"xb3-10","n":"XB3-10","p":3,"a":"p3","id":"fe5","src":"assets/audio/XB3-10/fe5.mp3","sec":9.792,"t":"考法：问如何防止多精入卵。解题方法：答透明带的生理反应和卵细胞膜的生理反应两道屏障。"},{"ep":"xb3-10","n":"XB3-10","p":4,"a":"p4","id":"si1","src":"assets/audio/XB3-10/si1.mp3","sec":11.904,"t":"考点四，受精的标志。卵子受精的重要标志，是在透明带和卵细胞膜之间观察到两个极体，或者观察到雌、雄原核。"},{"ep":"xb3-10","n":"XB3-10","p":4,"a":"p4","id":"si2","src":"assets/audio/XB3-10/si2.mp3","sec":7.752,"t":"两个极体：一个是减数分裂Ⅰ排出的第一极体，另一个是受精时排出的第二极体。"},{"ep":"xb3-10","n":"XB3-10","p":4,"a":"p4","id":"si3","src":"assets/audio/XB3-10/si3.mp3","sec":5.784,"t":"而雌、雄原核融合形成合子，标志着受精过程的完成。"},{"ep":"xb3-10","n":"XB3-10","p":4,"a":"p4","id":"si4","src":"assets/audio/XB3-10/si4.mp3","sec":10.224,"t":"易错：区分“受精的标志”和“受精完成的标志”——前者是看到两个极体或雌雄原核，后者是雌雄原核融合。"},{"ep":"xb3-10","n":"XB3-10","p":5,"a":"p5","id":"de1","src":"assets/audio/XB3-10/de1.mp3","sec":12.408,"t":"考点五，早期胚胎发育。受精卵进行有丝分裂，进入卵裂期：细胞数量不断增加，但胚胎的总体积并不增加，或略有缩小。"},{"ep":"xb3-10","n":"XB3-10","p":5,"a":"p5","id":"de2","src":"assets/audio/XB3-10/de2.mp3","sec":9.6,"t":"细胞数目达到 32 个左右时，形成实心的桑葚胚，这一阶段前的每个细胞都具有发育成完整胚胎的潜能。"},{"ep":"xb3-10","n":"XB3-10","p":5,"a":"p5","id":"de3","src":"assets/audio/XB3-10/de3.mp3","sec":5.064,"t":"接着细胞开始分化，形成囊胚，出现了囊胚腔。"},{"ep":"xb3-10","n":"XB3-10","p":5,"a":"p5","id":"de4","src":"assets/audio/XB3-10/de4.mp3","sec":7.704,"t":"囊胚继续发育，形成原肠胚，出现外胚层、内胚层等胚层分化和原肠腔。"},{"ep":"xb3-10","n":"XB3-10","p":5,"a":"p5","id":"de5","src":"assets/audio/XB3-10/de5.mp3","sec":11.256,"t":"易错：卵裂期，单个细胞的体积变小，细胞总DNA量增加，但有机物总量减少，因为胚胎还不能从外界获取营养。"},{"ep":"xb3-10","n":"XB3-10","p":6,"a":"p6","id":"bl1","src":"assets/audio/XB3-10/bl1.mp3","sec":10.248,"t":"考点六，囊胚的结构。聚集在胚胎一端、个体较大的细胞，叫作内细胞团，将来发育成胎儿的各种组织。"},{"ep":"xb3-10","n":"XB3-10","p":6,"a":"p6","id":"bl2","src":"assets/audio/XB3-10/bl2.mp3","sec":8.328,"t":"沿透明带内壁扩展和排列、个体较小的细胞，叫作滋养层，将来发育成胎膜和胎盘。"},{"ep":"xb3-10","n":"XB3-10","p":6,"a":"p6","id":"bl3","src":"assets/audio/XB3-10/bl3.mp3","sec":9.768,"t":"中间的腔叫囊胚腔。囊胚进一步扩大，会导致透明带破裂，胚胎从中伸展出来，这个过程叫孵化。"},{"ep":"xb3-10","n":"XB3-10","p":6,"a":"p6","id":"bl4","src":"assets/audio/XB3-10/bl4.mp3","sec":12.816,"t":"考法：识图填结构和去向。解题方法：记住“内细胞团成胎儿，滋养层成胎膜胎盘”；胚胎分割、取ES细胞都和内细胞团有关。"},{"ep":"xb3-10","n":"XB3-10","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-10/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-10","n":"XB3-10","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-10/rv2.mp3","sec":11.448,"t":"判断一：刚排出的精子能立即受精？错，要先获能。判断二：卵子要发育到MⅡ期才能受精？对。"},{"ep":"xb3-10","n":"XB3-10","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-10/rv3.mp3","sec":12.12,"t":"判断三：透明带反应和卵细胞膜反应能防止多精入卵？对。判断四：卵裂期胚胎总体积不断增大？错。"},{"ep":"xb3-10","n":"XB3-10","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-10/rv4.mp3","sec":13.656,"t":"判断五：滋养层细胞发育成胎儿的各种组织？错，发育成胎膜和胎盘。判断六：观察到两个极体或雌雄原核是受精的标志？对。"},{"ep":"xb3-10","n":"XB3-10","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-10/rv5.mp3","sec":7.776,"t":"六个考点串成一条线：两道屏障防多精，内团成体滋养盘。我们下期再见！"},{"ep":"xb3-11","n":"XB3-11","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-11/in1.mp3","sec":9.72,"t":"同学们好！这节课梳理人教版选择性必修三第二章第三节的下半部分——胚胎工程技术及其应用。"},{"ep":"xb3-11","n":"XB3-11","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-11/in2.mp3","sec":9.216,"t":"高考常考胚胎移植的基本程序和生理学基础、胚胎分割的要点，以及试管动物和克隆动物的比较。"},{"ep":"xb3-11","n":"XB3-11","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-11/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-11","n":"XB3-11","p":1,"a":"p1","id":"iv1","src":"assets/audio/XB3-11/iv1.mp3","sec":7.92,"t":"考点一，体外受精。主要包括卵母细胞的采集、精子的获取和受精等步骤。"},{"ep":"xb3-11","n":"XB3-11","p":1,"a":"p1","id":"iv2","src":"assets/audio/XB3-11/iv2.mp3","sec":6.144,"t":"采集到的卵母细胞，要在体外培养到MⅡ期，才能与精子受精。"},{"ep":"xb3-11","n":"XB3-11","p":1,"a":"p1","id":"iv3","src":"assets/audio/XB3-11/iv3.mp3","sec":3.696,"t":"采集到的精子，要进行获能处理。"},{"ep":"xb3-11","n":"XB3-11","p":1,"a":"p1","id":"iv4","src":"assets/audio/XB3-11/iv4.mp3","sec":8.136,"t":"然后，在适当的培养液中让获能的精子和培养成熟的卵子共同培养，完成受精。"},{"ep":"xb3-11","n":"XB3-11","p":1,"a":"p1","id":"iv5","src":"assets/audio/XB3-11/iv5.mp3","sec":9.624,"t":"考法：问受精前的处理。解题方法：两句话答全——卵母细胞培养到MⅡ期，精子获能处理。"},{"ep":"xb3-11","n":"XB3-11","p":2,"a":"p2","id":"tr1","src":"assets/audio/XB3-11/tr1.mp3","sec":14.448,"t":"考点二，胚胎移植。它是指把通过体外受精及其他方式得到的胚胎，移植到同种的、生理状态相同的雌性动物体内，使之继续发育为新个体的技术。"},{"ep":"xb3-11","n":"XB3-11","p":2,"a":"p2","id":"tr2","src":"assets/audio/XB3-11/tr2.mp3","sec":5.904,"t":"提供胚胎的个体，叫作供体；接受胚胎的个体，叫作受体。"},{"ep":"xb3-11","n":"XB3-11","p":2,"a":"p2","id":"tr3","src":"assets/audio/XB3-11/tr3.mp3","sec":7.752,"t":"供体一般是遗传性状优良的个体；受体只要有健康的体质和正常繁殖能力就行。"},{"ep":"xb3-11","n":"XB3-11","p":2,"a":"p2","id":"tr4","src":"assets/audio/XB3-11/tr4.mp3","sec":10.008,"t":"易错：胚胎移植中，后代的遗传物质来自供体，受体只提供胚胎发育的场所，不影响后代的遗传特性。"},{"ep":"xb3-11","n":"XB3-11","p":3,"a":"p3","id":"sp1","src":"assets/audio/XB3-11/sp1.mp3","sec":7.944,"t":"考点三，胚胎移植的基本程序。第一步，对供体和受体进行同期发情处理。"},{"ep":"xb3-11","n":"XB3-11","p":3,"a":"p3","id":"sp2","src":"assets/audio/XB3-11/sp2.mp3","sec":5.88,"t":"第二步，用促性腺激素对供体母畜进行超数排卵处理。"},{"ep":"xb3-11","n":"XB3-11","p":3,"a":"p3","id":"sp3","src":"assets/audio/XB3-11/sp3.mp3","sec":8.928,"t":"第三步，对供体进行配种或人工授精。然后冲卵，也就是把供体子宫内的胚胎冲洗出来。"},{"ep":"xb3-11","n":"XB3-11","p":3,"a":"p3","id":"sp4","src":"assets/audio/XB3-11/sp4.mp3","sec":7.392,"t":"第四步，对胚胎进行质量检查，此时胚胎应发育到桑葚胚或囊胚阶段。"},{"ep":"xb3-11","n":"XB3-11","p":3,"a":"p3","id":"sp5","src":"assets/audio/XB3-11/sp5.mp3","sec":5.616,"t":"最后，把胚胎移植给受体，并对受体进行妊娠检查。"},{"ep":"xb3-11","n":"XB3-11","p":3,"a":"p3","id":"sp6","src":"assets/audio/XB3-11/sp6.mp3","sec":8.304,"t":"易错：超数排卵用的是促性腺激素，不是性激素；“冲卵”冲出的是胚胎，不是卵子。"},{"ep":"xb3-11","n":"XB3-11","p":4,"a":"p4","id":"ba1","src":"assets/audio/XB3-11/ba1.mp3","sec":12.768,"t":"考点四，胚胎移植的生理学基础。第一，同种动物的供体和受体，生殖器官的生理变化是相同的，为胚胎移入提供了相同的生理环境。"},{"ep":"xb3-11","n":"XB3-11","p":4,"a":"p4","id":"ba2","src":"assets/audio/XB3-11/ba2.mp3","sec":10.464,"t":"第二，早期胚胎在一定时间内处于游离状态，没有与母体子宫建立组织上的联系，这为胚胎的收集提供了可能。"},{"ep":"xb3-11","n":"XB3-11","p":4,"a":"p4","id":"ba3","src":"assets/audio/XB3-11/ba3.mp3","sec":9.624,"t":"第三，受体对移入子宫的外来胚胎基本上不发生免疫排斥反应，为胚胎在受体内的存活提供了可能。"},{"ep":"xb3-11","n":"XB3-11","p":4,"a":"p4","id":"ba4","src":"assets/audio/XB3-11/ba4.mp3","sec":9.384,"t":"第四，供体胚胎可与受体子宫建立正常的生理和组织联系，但遗传特性在孕育过程中不受影响。"},{"ep":"xb3-11","n":"XB3-11","p":4,"a":"p4","id":"ba5","src":"assets/audio/XB3-11/ba5.mp3","sec":15.552,"t":"考法：一个现象对应一条基础。解题方法：为什么能冲卵？游离状态。为什么能存活？不发生免疫排斥。为什么要同期发情？生理环境相同。"},{"ep":"xb3-11","n":"XB3-11","p":5,"a":"p5","id":"mn1","src":"assets/audio/XB3-11/mn1.mp3","sec":8.256,"t":"考点五，胚胎移植的意义。最主要的是：可以充分发挥雌性优良个体的繁殖潜力。"},{"ep":"xb3-11","n":"XB3-11","p":5,"a":"p5","id":"mn2","src":"assets/audio/XB3-11/mn2.mp3","sec":11.424,"t":"供体只负责产生具有优良遗传特性的胚胎，繁重而漫长的妊娠和育仔任务由受体承担，大大缩短了供体本身的繁殖周期。"},{"ep":"xb3-11","n":"XB3-11","p":5,"a":"p5","id":"mn3","src":"assets/audio/XB3-11/mn3.mp3","sec":11.04,"t":"胚胎移植是胚胎工程的最后一道工序：体外受精、胚胎分割、核移植得到的胚胎，都要经过胚胎移植才能获得后代。"},{"ep":"xb3-11","n":"XB3-11","p":5,"a":"p5","id":"mn4","src":"assets/audio/XB3-11/mn4.mp3","sec":8.784,"t":"解题方法：问意义，答“充分发挥雌性优良个体的繁殖潜力”这一句，几乎是必考的标准表述。"},{"ep":"xb3-11","n":"XB3-11","p":6,"a":"p6","id":"sl1","src":"assets/audio/XB3-11/sl1.mp3","sec":12.648,"t":"考点六，胚胎分割。它是采用机械方法把早期胚胎切割成2等份、4等份或8等份等，经移植获得同卵双胎或多胎的技术。"},{"ep":"xb3-11","n":"XB3-11","p":6,"a":"p6","id":"sl2","src":"assets/audio/XB3-11/sl2.mp3","sec":5.832,"t":"应选择发育良好、形态正常的桑葚胚或囊胚进行分割。"},{"ep":"xb3-11","n":"XB3-11","p":6,"a":"p6","id":"sl3","src":"assets/audio/XB3-11/sl3.mp3","sec":8.112,"t":"分割囊胚时，要将内细胞团均等分割，否则会影响分割后胚胎的恢复和进一步发育。"},{"ep":"xb3-11","n":"XB3-11","p":6,"a":"p6","id":"sl4","src":"assets/audio/XB3-11/sl4.mp3","sec":12.144,"t":"胚胎分割属于无性繁殖或克隆，后代的遗传物质相同。但分割的份数越多，成功率越低，实践中以二分胚胎的成功率最高。"},{"ep":"xb3-11","n":"XB3-11","p":6,"a":"p6","id":"sl5","src":"assets/audio/XB3-11/sl5.mp3","sec":9.696,"t":"易错：均等分割的是内细胞团，不是滋养层；还可以取滋养层细胞做DNA分析，进行性别鉴定。"},{"ep":"xb3-11","n":"XB3-11","p":7,"a":"p7","id":"vs1","src":"assets/audio/XB3-11/vs1.mp3","sec":11.448,"t":"考点七，试管动物与克隆动物的比较。试管动物：通过体外受精、早期胚胎培养和胚胎移植产生，属于有性生殖。"},{"ep":"xb3-11","n":"XB3-11","p":7,"a":"p7","id":"vs2","src":"assets/audio/XB3-11/vs2.mp3","sec":7.44,"t":"克隆动物：通过核移植、早期胚胎培养和胚胎移植产生，属于无性生殖。"},{"ep":"xb3-11","n":"XB3-11","p":7,"a":"p7","id":"vs3","src":"assets/audio/XB3-11/vs3.mp3","sec":6.912,"t":"试管动物的遗传物质来自双亲；克隆动物的核遗传物质只来自供核个体。"},{"ep":"xb3-11","n":"XB3-11","p":7,"a":"p7","id":"vs4","src":"assets/audio/XB3-11/vs4.mp3","sec":9.432,"t":"解题方法：看有没有精卵结合——有就是有性生殖；两者的共同技术是早期胚胎培养和胚胎移植。"},{"ep":"xb3-11","n":"XB3-11","p":8,"a":"p8","id":"ch1","src":"assets/audio/XB3-11/ch1.mp3","sec":8.448,"t":"考点八，胚胎工程流程图判读。看到卵母细胞和精子，想到体外受精，试管动物。"},{"ep":"xb3-11","n":"XB3-11","p":8,"a":"p8","id":"ch2","src":"assets/audio/XB3-11/ch2.mp3","sec":5.16,"t":"看到去核卵母细胞和体细胞，想到核移植，克隆动物。"},{"ep":"xb3-11","n":"XB3-11","p":8,"a":"p8","id":"ch3","src":"assets/audio/XB3-11/ch3.mp3","sec":4.488,"t":"看到切割胚胎，想到胚胎分割，同卵多胎。"},{"ep":"xb3-11","n":"XB3-11","p":8,"a":"p8","id":"ch4","src":"assets/audio/XB3-11/ch4.mp3","sec":5.184,"t":"所有路线最后都汇合到胚胎移植，由受体完成孕育。"},{"ep":"xb3-11","n":"XB3-11","p":8,"a":"p8","id":"ch5","src":"assets/audio/XB3-11/ch5.mp3","sec":10.992,"t":"解题方法：先找起点材料判断技术，再看终点都是胚胎移植；有激素处理的步骤，记住同期发情和超数排卵。"},{"ep":"xb3-11","n":"XB3-11","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-11/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-11","n":"XB3-11","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-11/rv2.mp3","sec":12.552,"t":"判断一：采集的卵母细胞可直接受精？错，要培养到MⅡ期。判断二：移植前对供体和受体同期发情处理？对。"},{"ep":"xb3-11","n":"XB3-11","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-11/rv3.mp3","sec":11.904,"t":"判断三：超数排卵用性激素？错，用促性腺激素。判断四：受体对外来胚胎基本不发生免疫排斥？对。"},{"ep":"xb3-11","n":"XB3-11","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-11/rv4.mp3","sec":11.28,"t":"判断五：胚胎分割要均等分割滋养层？错，是内细胞团。判断六：试管动物属于有性生殖？对。"},{"ep":"xb3-11","n":"XB3-11","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-11/rv5.mp3","sec":6.888,"t":"八个考点串成一条线：供体出胚胎，受体只孕育。我们下期再见！"},{"ep":"xb3-12","n":"XB3-12","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-12/in1.mp3","sec":8.976,"t":"同学们好！这节课梳理人教版选择性必修三第三章第一节——重组DNA技术的基本工具。"},{"ep":"xb3-12","n":"XB3-12","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-12/in2.mp3","sec":8.232,"t":"高考常考限制酶的识别和切割、两种DNA连接酶的区别，以及载体应具备的条件。"},{"ep":"xb3-12","n":"XB3-12","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-12/in3.mp3","sec":5.52,"t":"我们按八个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-12","n":"XB3-12","p":1,"a":"p1","id":"co1","src":"assets/audio/XB3-12/co1.mp3","sec":14.184,"t":"考点一，基因工程的概念。它是指按照人们的愿望，通过转基因等技术，赋予生物以新的遗传特性，创造出更符合人们需要的新的生物类型和生物产品。"},{"ep":"xb3-12","n":"XB3-12","p":1,"a":"p1","id":"co2","src":"assets/audio/XB3-12/co2.mp3","sec":8.184,"t":"基因工程是在DNA分子水平上进行设计和施工的，所以又叫作重组DNA技术。"},{"ep":"xb3-12","n":"XB3-12","p":1,"a":"p1","id":"co3","src":"assets/audio/XB3-12/co3.mp3","sec":9.384,"t":"它需要三种基本工具：限制酶是“分子手术刀”，DNA连接酶是“分子缝合针”，载体是“分子运输车”。"},{"ep":"xb3-12","n":"XB3-12","p":1,"a":"p1","id":"co4","src":"assets/audio/XB3-12/co4.mp3","sec":9.888,"t":"易错：载体不是酶；基因工程的原理是基因重组，能定向改造生物的遗传性状，并且能打破物种界限。"},{"ep":"xb3-12","n":"XB3-12","p":2,"a":"p2","id":"en1","src":"assets/audio/XB3-12/en1.mp3","sec":8.544,"t":"考点二，限制性内切核酸酶，简称限制酶。它主要是从原核生物中分离纯化出来的。"},{"ep":"xb3-12","n":"XB3-12","p":2,"a":"p2","id":"en2","src":"assets/audio/XB3-12/en2.mp3","sec":9.408,"t":"限制酶能够识别双链DNA分子的特定核苷酸序列，并且使每一条链中特定部位的磷酸二酯键断开。"},{"ep":"xb3-12","n":"XB3-12","p":2,"a":"p2","id":"en3","src":"assets/audio/XB3-12/en3.mp3","sec":9.096,"t":"大多数限制酶的识别序列由6个核苷酸组成，也有少数由4个、8个或其他数量的核苷酸组成。"},{"ep":"xb3-12","n":"XB3-12","p":2,"a":"p2","id":"en4","src":"assets/audio/XB3-12/en4.mp3","sec":7.08,"t":"比如EcoRI，识别的序列是GAATTC，在G和A之间切开。"},{"ep":"xb3-12","n":"XB3-12","p":2,"a":"p2","id":"en5","src":"assets/audio/XB3-12/en5.mp3","sec":9.696,"t":"易错：限制酶切的是磷酸二酯键，不是氢键；它在原核生物中的作用是切割外源DNA，保护自身。"},{"ep":"xb3-12","n":"XB3-12","p":3,"a":"p3","id":"ed1","src":"assets/audio/XB3-12/ed1.mp3","sec":11.28,"t":"考点三，黏性末端和平末端。限制酶在识别序列的中心轴线两侧将DNA两条链分别切开时，产生黏性末端。"},{"ep":"xb3-12","n":"XB3-12","p":3,"a":"p3","id":"ed2","src":"assets/audio/XB3-12/ed2.mp3","sec":5.664,"t":"在中心轴线处切开时，产生的是平末端，比如SmaI。"},{"ep":"xb3-12","n":"XB3-12","p":3,"a":"p3","id":"ed3","src":"assets/audio/XB3-12/ed3.mp3","sec":8.616,"t":"限制酶的识别序列大多是回文序列：两条链从5′到3′方向读，碱基顺序相同。"},{"ep":"xb3-12","n":"XB3-12","p":3,"a":"p3","id":"ed4","src":"assets/audio/XB3-12/ed4.mp3","sec":15.048,"t":"考法：给出识别序列，问末端类型或能否连接。解题方法：同一种限制酶切出的黏性末端一定能互补连接；不同的限制酶，只要末端碱基互补也能连接。"},{"ep":"xb3-12","n":"XB3-12","p":4,"a":"p4","id":"li1","src":"assets/audio/XB3-12/li1.mp3","sec":7.632,"t":"考点四，DNA连接酶。它把两个DNA片段之间的磷酸二酯键连接起来。"},{"ep":"xb3-12","n":"XB3-12","p":4,"a":"p4","id":"li2","src":"assets/audio/XB3-12/li2.mp3","sec":6.144,"t":"E. coli DNA连接酶，来源于大肠杆菌，只能连接黏性末端。"},{"ep":"xb3-12","n":"XB3-12","p":4,"a":"p4","id":"li3","src":"assets/audio/XB3-12/li3.mp3","sec":9.648,"t":"T​4 DNA连接酶，来源于T​4噬菌体，黏性末端和平末端都能连接，但连接平末端的效率比较低。"},{"ep":"xb3-12","n":"XB3-12","p":4,"a":"p4","id":"li4","src":"assets/audio/XB3-12/li4.mp3","sec":11.4,"t":"易错：DNA连接酶连接的是两个DNA片段，不能把单个脱氧核苷酸连到DNA链上，那是DNA聚合酶的工作。"},{"ep":"xb3-12","n":"XB3-12","p":5,"a":"p5","id":"pl1","src":"assets/audio/XB3-12/pl1.mp3","sec":14.544,"t":"考点五，载体——质粒。质粒是一种裸露的、结构简单、独立于真核细胞细胞核或原核细胞拟核DNA之外，并具有自我复制能力的环状双链DNA分子。"},{"ep":"xb3-12","n":"XB3-12","p":5,"a":"p5","id":"pl2","src":"assets/audio/XB3-12/pl2.mp3","sec":9.384,"t":"作为载体，必须具备：第一，能在受体细胞中进行自我复制，或整合到受体DNA上随之复制。"},{"ep":"xb3-12","n":"XB3-12","p":5,"a":"p5","id":"pl3","src":"assets/audio/XB3-12/pl3.mp3","sec":6.024,"t":"第二，有一个至多个限制酶切割位点，供外源DNA片段插入。"},{"ep":"xb3-12","n":"XB3-12","p":5,"a":"p5","id":"pl4","src":"assets/audio/XB3-12/pl4.mp3","sec":7.992,"t":"第三，有特殊的标记基因，比如抗生素抗性基因，便于重组DNA分子的筛选。"},{"ep":"xb3-12","n":"XB3-12","p":5,"a":"p5","id":"pl5","src":"assets/audio/XB3-12/pl5.mp3","sec":9.336,"t":"易错：质粒不是细胞器，也不只存在于细菌中，酵母菌等真核生物也有；载体对受体细胞应无害。"},{"ep":"xb3-12","n":"XB3-12","p":6,"a":"p6","id":"ve1","src":"assets/audio/XB3-12/ve1.mp3","sec":7.512,"t":"考点六，其他载体。除了质粒，常用的载体还有噬菌体和动植物病毒。"},{"ep":"xb3-12","n":"XB3-12","p":6,"a":"p6","id":"ve2","src":"assets/audio/XB3-12/ve2.mp3","sec":6.816,"t":"在基因工程中使用的载体，往往是在天然载体的基础上经过人工改造的。"},{"ep":"xb3-12","n":"XB3-12","p":6,"a":"p6","id":"ve3","src":"assets/audio/XB3-12/ve3.mp3","sec":8.424,"t":"比如作为载体的病毒，要去除致病性，保留侵染宿主细胞和把DNA整合进去的能力。"},{"ep":"xb3-12","n":"XB3-12","p":6,"a":"p6","id":"ve4","src":"assets/audio/XB3-12/ve4.mp3","sec":7.608,"t":"解题方法：判断能不能作载体，就看三个条件——能复制、有切点、有标记。"},{"ep":"xb3-12","n":"XB3-12","p":7,"a":"p7","id":"ex1","src":"assets/audio/XB3-12/ex1.mp3","sec":13.032,"t":"考点七，探究实践：DNA的粗提取与鉴定。原理一：DNA不溶于酒精，但某些蛋白质溶于酒精，可以初步分离DNA和蛋白质。"},{"ep":"xb3-12","n":"XB3-12","p":7,"a":"p7","id":"ex2","src":"assets/audio/XB3-12/ex2.mp3","sec":6.24,"t":"原理二：DNA能溶于物质的量浓度为 2 mol/L 的 NaCl 溶液。"},{"ep":"xb3-12","n":"XB3-12","p":7,"a":"p7","id":"ex3","src":"assets/audio/XB3-12/ex3.mp3","sec":10.632,"t":"步骤：洋葱研磨、过滤，取上清液；加入等体积的、预冷的酒精，析出白色丝状物，就是粗提取的DNA。"},{"ep":"xb3-12","n":"XB3-12","p":7,"a":"p7","id":"ex4","src":"assets/audio/XB3-12/ex4.mp3","sec":8.328,"t":"鉴定：把丝状物溶于NaCl溶液，加入二苯胺试剂，沸水浴加热，溶液变成蓝色。"},{"ep":"xb3-12","n":"XB3-12","p":7,"a":"p7","id":"ex5","src":"assets/audio/XB3-12/ex5.mp3","sec":10.176,"t":"易错：不选哺乳动物成熟红细胞，因为它没有细胞核；二苯胺鉴定要沸水浴，而且要设置不加DNA的对照。"},{"ep":"xb3-12","n":"XB3-12","p":8,"a":"p8","id":"cm1","src":"assets/audio/XB3-12/cm1.mp3","sec":6.624,"t":"考点八，几种酶的比较。限制酶：断开特定部位的磷酸二酯键。"},{"ep":"xb3-12","n":"XB3-12","p":8,"a":"p8","id":"cm2","src":"assets/audio/XB3-12/cm2.mp3","sec":5.832,"t":"DNA连接酶：连接两个DNA片段之间的磷酸二酯键。"},{"ep":"xb3-12","n":"XB3-12","p":8,"a":"p8","id":"cm3","src":"assets/audio/XB3-12/cm3.mp3","sec":7.872,"t":"DNA聚合酶：把单个脱氧核苷酸加到已有DNA链的3′端，形成磷酸二酯键。"},{"ep":"xb3-12","n":"XB3-12","p":8,"a":"p8","id":"cm4","src":"assets/audio/XB3-12/cm4.mp3","sec":3.624,"t":"{解旋酶|brown}：断开两条链之间的{氢键|brown}。"},{"ep":"xb3-12","n":"XB3-12","p":8,"a":"p8","id":"cm5","src":"assets/audio/XB3-12/cm5.mp3","sec":6.984,"t":"解题方法：先问作用的键，再问作用的对象——是片段还是单个核苷酸。"},{"ep":"xb3-12","n":"XB3-12","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-12/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-12","n":"XB3-12","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-12/rv2.mp3","sec":11.256,"t":"判断一：限制酶主要从原核生物中分离纯化？对。判断二：限制酶切割的是氢键？错，是磷酸二酯键。"},{"ep":"xb3-12","n":"XB3-12","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-12/rv3.mp3","sec":13.104,"t":"判断三：E. coli DNA连接酶能连接平末端？错。判断四：质粒是存在于拟核中的DNA？错，是拟核外的环状DNA。"},{"ep":"xb3-12","n":"XB3-12","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-12/rv4.mp3","sec":13.464,"t":"判断五：DNA不溶于酒精，某些蛋白质溶于酒精？对。判断六：DNA连接酶和DNA聚合酶都形成磷酸二酯键？对。"},{"ep":"xb3-12","n":"XB3-12","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-12/rv5.mp3","sec":7.128,"t":"八个考点串成一条线：剪刀切、针缝合、车运输。我们下期再见！"},{"ep":"xb3-13","n":"XB3-13","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-13/in1.mp3","sec":10.416,"t":"同学们好！这节课梳理人教版选择性必修三第三章第二节的上半部分——获取目的基因与构建基因表达载体。"},{"ep":"xb3-13","n":"XB3-13","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-13/in2.mp3","sec":7.848,"t":"高考常考PCR的原理、条件和计算，基因表达载体的组成，以及限制酶的选择。"},{"ep":"xb3-13","n":"XB3-13","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-13/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-13","n":"XB3-13","p":1,"a":"p1","id":"st1","src":"assets/audio/XB3-13/st1.mp3","sec":8.16,"t":"考点一，基因工程的基本操作程序，一共四步。第一步，目的基因的筛选与获取。"},{"ep":"xb3-13","n":"XB3-13","p":1,"a":"p1","id":"st2","src":"assets/audio/XB3-13/st2.mp3","sec":5.136,"t":"第二步，基因表达载体的构建，这是基因工程的核心。"},{"ep":"xb3-13","n":"XB3-13","p":1,"a":"p1","id":"st3","src":"assets/audio/XB3-13/st3.mp3","sec":3.768,"t":"第三步，将目的基因导入受体细胞。"},{"ep":"xb3-13","n":"XB3-13","p":1,"a":"p1","id":"st4","src":"assets/audio/XB3-13/st4.mp3","sec":3.504,"t":"第四步，目的基因的检测与鉴定。"},{"ep":"xb3-13","n":"XB3-13","p":1,"a":"p1","id":"st5","src":"assets/audio/XB3-13/st5.mp3","sec":10.296,"t":"易错：核心步骤是构建基因表达载体，不是获取目的基因；其中只有导入受体细胞这一步不涉及碱基互补配对。"},{"ep":"xb3-13","n":"XB3-13","p":2,"a":"p2","id":"ta1","src":"assets/audio/XB3-13/ta1.mp3","sec":12.216,"t":"考点二，目的基因的筛选与获取。在基因工程中，目的基因主要是指编码蛋白质的基因，比如苏云金杆菌的Bt抗虫蛋白基因。"},{"ep":"xb3-13","n":"XB3-13","p":2,"a":"p2","id":"ta2","src":"assets/audio/XB3-13/ta2.mp3","sec":7.728,"t":"筛选：从相关的已知结构和功能清晰的基因中进行筛选，是较为有效的方法。"},{"ep":"xb3-13","n":"XB3-13","p":2,"a":"p2","id":"ta3","src":"assets/audio/XB3-13/ta3.mp3","sec":9.384,"t":"获取：常用PCR特异性地快速扩增目的基因；也可以人工合成，或通过构建基因文库来获取。"},{"ep":"xb3-13","n":"XB3-13","p":2,"a":"p2","id":"ta4","src":"assets/audio/XB3-13/ta4.mp3","sec":9.192,"t":"考法：问获取方法。解题方法：已知目的基因两端的序列、需要大量扩增时，首选PCR。"},{"ep":"xb3-13","n":"XB3-13","p":3,"a":"p3","id":"pc1","src":"assets/audio/XB3-13/pc1.mp3","sec":9.312,"t":"考点三，PCR的原理与过程。PCR是聚合酶链式反应，原理是DNA半保留复制。"},{"ep":"xb3-13","n":"XB3-13","p":3,"a":"p3","id":"pc2","src":"assets/audio/XB3-13/pc2.mp3","sec":7.08,"t":"第一步，变性：温度上升到 90 ℃以上，双链DNA解聚为单链。"},{"ep":"xb3-13","n":"XB3-13","p":3,"a":"p3","id":"pc3","src":"assets/audio/XB3-13/pc3.mp3","sec":9.096,"t":"第二步，复性：温度下降到 50 ℃左右，两种引物通过碱基互补配对与两条单链结合。"},{"ep":"xb3-13","n":"XB3-13","p":3,"a":"p3","id":"pc4","src":"assets/audio/XB3-13/pc4.mp3","sec":10.968,"t":"第三步，延伸：温度上升到 72 ℃左右，耐高温的DNA聚合酶从引物的3′端开始，合成新的DNA链。"},{"ep":"xb3-13","n":"XB3-13","p":3,"a":"p3","id":"pc5","src":"assets/audio/XB3-13/pc5.mp3","sec":7.704,"t":"易错：PCR不用解旋酶，靠高温解旋；子链的延伸方向是5′到3′。"},{"ep":"xb3-13","n":"XB3-13","p":4,"a":"p4","id":"ca1","src":"assets/audio/XB3-13/ca1.mp3","sec":14.16,"t":"考点四，PCR的条件与计算。需要：模板DNA、两种引物、4种脱氧核苷酸、耐高温的DNA聚合酶，缓冲液中一般还要添加Mg2+。"},{"ep":"xb3-13","n":"XB3-13","p":4,"a":"p4","id":"ca2","src":"assets/audio/XB3-13/ca2.mp3","sec":12.384,"t":"引物是一小段能与DNA母链的一段碱基序列互补配对的短单链核酸，使DNA聚合酶能够从引物的3′端开始连接脱氧核苷酸。"},{"ep":"xb3-13","n":"XB3-13","p":4,"a":"p4","id":"ca3","src":"assets/audio/XB3-13/ca3.mp3","sec":10.656,"t":"计算：1个DNA分子经过n轮循环，得到 2n 个DNA分子，共消耗引物 2[n+1] − 2 个。"},{"ep":"xb3-13","n":"XB3-13","p":4,"a":"p4","id":"ca4","src":"assets/audio/XB3-13/ca4.mp3","sec":9.264,"t":"第3轮循环开始出现两条链等长的目的基因片段；n轮后，这样的片段有 2n − 2n 个。"},{"ep":"xb3-13","n":"XB3-13","p":4,"a":"p4","id":"ca5","src":"assets/audio/XB3-13/ca5.mp3","sec":7.584,"t":"解题方法：引物数等于新合成的子链数——总链数减去2条母链，再一一对应。"},{"ep":"xb3-13","n":"XB3-13","p":5,"a":"p5","id":"ve1","src":"assets/audio/XB3-13/ve1.mp3","sec":9.576,"t":"考点五，基因表达载体的组成。除了目的基因，还要有启动子、终止子、标记基因和复制原点。"},{"ep":"xb3-13","n":"XB3-13","p":5,"a":"p5","id":"ve2","src":"assets/audio/XB3-13/ve2.mp3","sec":9.048,"t":"启动子：位于基因上游，是RNA聚合酶识别和结合的部位，驱动基因转录出mRNA。"},{"ep":"xb3-13","n":"XB3-13","p":5,"a":"p5","id":"ve3","src":"assets/audio/XB3-13/ve3.mp3","sec":5.616,"t":"{终止子|brown}：位于基因下游，使{转录在所需要的地方停下来|brown}。"},{"ep":"xb3-13","n":"XB3-13","p":5,"a":"p5","id":"ve4","src":"assets/audio/XB3-13/ve4.mp3","sec":7.032,"t":"标记基因：便于鉴别和筛选含有目的基因的细胞，常用抗生素抗性基因。"},{"ep":"xb3-13","n":"XB3-13","p":5,"a":"p5","id":"ve5","src":"assets/audio/XB3-13/ve5.mp3","sec":13.896,"t":"考法：问构建表达载体的目的。解题方法：答“使目的基因在受体细胞中稳定存在，并且可以遗传给下一代，同时使目的基因能够表达和发挥作用”。"},{"ep":"xb3-13","n":"XB3-13","p":6,"a":"p6","id":"bu1","src":"assets/audio/XB3-13/bu1.mp3","sec":11.64,"t":"考点六，基因表达载体的构建。先用同种限制酶或能产生相同末端的限制酶，切割载体和含目的基因的DNA片段。"},{"ep":"xb3-13","n":"XB3-13","p":6,"a":"p6","id":"bu2","src":"assets/audio/XB3-13/bu2.mp3","sec":6.744,"t":"再用DNA连接酶把目的基因和载体连接起来，形成重组DNA。"},{"ep":"xb3-13","n":"XB3-13","p":6,"a":"p6","id":"bu3","src":"assets/audio/XB3-13/bu3.mp3","sec":10.656,"t":"常用两种不同的限制酶同时切割，也就是双酶切：可以防止目的基因和载体自身环化，还能防止目的基因反向连接。"},{"ep":"xb3-13","n":"XB3-13","p":6,"a":"p6","id":"bu4","src":"assets/audio/XB3-13/bu4.mp3","sec":10.464,"t":"选限制酶的原则：不能破坏目的基因；也不能破坏载体上的启动子、终止子、复制原点，至少保留一个标记基因。"},{"ep":"xb3-13","n":"XB3-13","p":6,"a":"p6","id":"bu5","src":"assets/audio/XB3-13/bu5.mp3","sec":9.288,"t":"解题方法：看图选酶时，先把切点在目的基因内部的酶排除，再排除会切坏载体必需结构的酶。"},{"ep":"xb3-13","n":"XB3-13","p":7,"a":"p7","id":"cd1","src":"assets/audio/XB3-13/cd1.mp3","sec":11.88,"t":"考点七，启动子与起始密码子、终止子与终止密码子的区别。启动子和终止子，是DNA上的一段序列，控制的是转录。"},{"ep":"xb3-13","n":"XB3-13","p":7,"a":"p7","id":"cd2","src":"assets/audio/XB3-13/cd2.mp3","sec":7.32,"t":"起始密码子和终止密码子，位于mRNA上，控制的是翻译的开始和结束。"},{"ep":"xb3-13","n":"XB3-13","p":7,"a":"p7","id":"cd3","src":"assets/audio/XB3-13/cd3.mp3","sec":10.728,"t":"易错：启动子不是起始密码子；终止子不是终止密码子。一个看DNA和转录，一个看mRNA和翻译。"},{"ep":"xb3-13","n":"XB3-13","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-13/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-13","n":"XB3-13","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-13/rv2.mp3","sec":12.144,"t":"判断一：基因工程的核心是构建基因表达载体？对。判断二：PCR用解旋酶解开双链？错，靠高温变性。"},{"ep":"xb3-13","n":"XB3-13","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-13/rv3.mp3","sec":14.064,"t":"判断三：PCR需要耐高温的DNA聚合酶？对。判断四：n轮循环需要2n个引物？错，是2[n+1] − 2个。"},{"ep":"xb3-13","n":"XB3-13","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-13/rv4.mp3","sec":11.016,"t":"判断五：启动子是mRNA上起始翻译的序列？错。判断六：双酶切可以防止自身环化？对。"},{"ep":"xb3-13","n":"XB3-13","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-13/rv5.mp3","sec":7.152,"t":"七个考点串成一条线：核心是构建，PCR靠温度。我们下期再见！"},{"ep":"xb3-14","n":"XB3-14","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-14/in1.mp3","sec":12.0,"t":"同学们好！这节课梳理人教版选择性必修三第三章第二节的下半部分——将目的基因导入受体细胞，以及目的基因的检测与鉴定。"},{"ep":"xb3-14","n":"XB3-14","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-14/in2.mp3","sec":8.664,"t":"高考常考农杆菌转化法的原理、不同受体细胞的导入方法，以及分子检测和电泳结果的判读。"},{"ep":"xb3-14","n":"XB3-14","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-14/in3.mp3","sec":5.568,"t":"我们按七个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-14","n":"XB3-14","p":1,"a":"p1","id":"pl1","src":"assets/audio/XB3-14/pl1.mp3","sec":6.792,"t":"考点一，将目的基因导入植物细胞。最常用的是农杆菌转化法。"},{"ep":"xb3-14","n":"XB3-14","p":1,"a":"p1","id":"pl2","src":"assets/audio/XB3-14/pl2.mp3","sec":8.4,"t":"农杆菌的Ti质粒上有一段T-DNA，它可以转移并整合到受体细胞的染色体DNA上。"},{"ep":"xb3-14","n":"XB3-14","p":1,"a":"p1","id":"pl3","src":"assets/audio/XB3-14/pl3.mp3","sec":8.928,"t":"所以把目的基因插入Ti质粒的T-DNA中，就能随T-DNA整合到植物细胞的染色体上。"},{"ep":"xb3-14","n":"XB3-14","p":1,"a":"p1","id":"pl4","src":"assets/audio/XB3-14/pl4.mp3","sec":11.088,"t":"农杆菌能侵染双子叶植物和裸子植物，对大多数单子叶植物没有侵染能力。我国科学家还独创了花粉管通道法。"},{"ep":"xb3-14","n":"XB3-14","p":1,"a":"p1","id":"pl5","src":"assets/audio/XB3-14/pl5.mp3","sec":10.296,"t":"易错：目的基因要插在T-DNA内部，不是Ti质粒的任意位置；整合的位置是植物细胞的染色体DNA。"},{"ep":"xb3-14","n":"XB3-14","p":2,"a":"p2","id":"an1","src":"assets/audio/XB3-14/an1.mp3","sec":5.856,"t":"考点二，将目的基因导入动物细胞。常用显微注射法。"},{"ep":"xb3-14","n":"XB3-14","p":2,"a":"p2","id":"an2","src":"assets/audio/XB3-14/an2.mp3","sec":8.568,"t":"受体细胞常用受精卵：将含有目的基因的表达载体提纯后，用显微注射仪注入受精卵中。"},{"ep":"xb3-14","n":"XB3-14","p":2,"a":"p2","id":"an3","src":"assets/audio/XB3-14/an3.mp3","sec":8.856,"t":"然后把受精卵培养成早期胚胎，再移植到雌性动物的输卵管或子宫内，发育成转基因动物。"},{"ep":"xb3-14","n":"XB3-14","p":2,"a":"p2","id":"an4","src":"assets/audio/XB3-14/an4.mp3","sec":12.648,"t":"考法：为什么用受精卵作受体？解题方法：受精卵全能性最高，能发育成完整个体，而且由它发育来的每个细胞都含有目的基因。"},{"ep":"xb3-14","n":"XB3-14","p":3,"a":"p3","id":"mi1","src":"assets/audio/XB3-14/mi1.mp3","sec":11.04,"t":"考点三，将目的基因导入微生物细胞。原核生物常作受体，因为它们繁殖快、多为单细胞、遗传物质相对较少。"},{"ep":"xb3-14","n":"XB3-14","p":3,"a":"p3","id":"mi2","src":"assets/audio/XB3-14/mi2.mp3","sec":9.816,"t":"以大肠杆菌为例，一般先用Ca2+处理细胞，使细胞处于一种能吸收周围环境中DNA分子的生理状态。"},{"ep":"xb3-14","n":"XB3-14","p":3,"a":"p3","id":"mi3","src":"assets/audio/XB3-14/mi3.mp3","sec":3.744,"t":"再将重组的基因表达载体导入其中。"},{"ep":"xb3-14","n":"XB3-14","p":3,"a":"p3","id":"mi4","src":"assets/audio/XB3-14/mi4.mp3","sec":11.28,"t":"易错：大肠杆菌没有内质网和高尔基体，产生的蛋白质无法加工；需要加工的蛋白质，可以选酵母菌等真核生物作受体。"},{"ep":"xb3-14","n":"XB3-14","p":4,"a":"p4","id":"de1","src":"assets/audio/XB3-14/de1.mp3","sec":10.632,"t":"考点四，分子水平的检测。第一查：受体细胞的染色体DNA上是否插入了目的基因，用PCR检测。"},{"ep":"xb3-14","n":"XB3-14","p":4,"a":"p4","id":"de2","src":"assets/audio/XB3-14/de2.mp3","sec":6.792,"t":"第二查：目的基因是否转录出了mRNA，也用PCR等技术检测。"},{"ep":"xb3-14","n":"XB3-14","p":4,"a":"p4","id":"de3","src":"assets/audio/XB3-14/de3.mp3","sec":6.6,"t":"第三查：目的基因是否翻译成蛋白质，用抗原—抗体杂交检测。"},{"ep":"xb3-14","n":"XB3-14","p":4,"a":"p4","id":"de4","src":"assets/audio/XB3-14/de4.mp3","sec":9.552,"t":"解题方法：按中心法则对号入座——DNA和mRNA用PCR，蛋白质用抗原—抗体杂交。"},{"ep":"xb3-14","n":"XB3-14","p":5,"a":"p5","id":"in4","src":"assets/audio/XB3-14/in4.mp3","sec":8.064,"t":"考点五，个体生物学水平的鉴定。分子检测成功，还不能说明基因工程就成功了。"},{"ep":"xb3-14","n":"XB3-14","p":5,"a":"p5","id":"in5","src":"assets/audio/XB3-14/in5.mp3","sec":6.24,"t":"比如抗虫棉，要做抗虫接种实验，看棉花是否具有抗虫特性。"},{"ep":"xb3-14","n":"XB3-14","p":5,"a":"p5","id":"in6","src":"assets/audio/XB3-14/in6.mp3","sec":7.992,"t":"抗病植物做抗病接种实验；基因工程产品还要与天然产品的功能活性进行比较。"},{"ep":"xb3-14","n":"XB3-14","p":5,"a":"p5","id":"in7","src":"assets/audio/XB3-14/in7.mp3","sec":8.88,"t":"易错：检测到目的基因甚至蛋白质，不等于获得了所需性状；最终要在个体水平上鉴定。"},{"ep":"xb3-14","n":"XB3-14","p":6,"a":"p6","id":"am1","src":"assets/audio/XB3-14/am1.mp3","sec":14.952,"t":"考点六，实验：DNA片段的扩增及电泳鉴定。在微量离心管中依次加入缓冲液、模板DNA、引物、4种脱氧核苷酸和耐高温的DNA聚合酶。"},{"ep":"xb3-14","n":"XB3-14","p":6,"a":"p6","id":"am2","src":"assets/audio/XB3-14/am2.mp3","sec":6.12,"t":"放入PCR仪中，按照变性、复性、延伸的程序循环扩增。"},{"ep":"xb3-14","n":"XB3-14","p":6,"a":"p6","id":"am3","src":"assets/audio/XB3-14/am3.mp3","sec":5.832,"t":"电泳鉴定：DNA分子带负电荷，在电场中向正极移动。"},{"ep":"xb3-14","n":"XB3-14","p":6,"a":"p6","id":"am4","src":"assets/audio/XB3-14/am4.mp3","sec":9.744,"t":"在凝胶中，DNA分子的迁移速率与凝胶浓度、DNA分子大小和构象有关；分子越小，迁移越快。"},{"ep":"xb3-14","n":"XB3-14","p":6,"a":"p6","id":"am5","src":"assets/audio/XB3-14/am5.mp3","sec":7.824,"t":"易错：加样孔要放在负极一侧；用到的离心管、枪头和蒸馏水都要高压灭菌。"},{"ep":"xb3-14","n":"XB3-14","p":7,"a":"p7","id":"ge1","src":"assets/audio/XB3-14/ge1.mp3","sec":10.632,"t":"考点七，电泳结果的判读。第一个泳道通常是标准参照物，也叫DNA分子标准，用来估计片段的大小。"},{"ep":"xb3-14","n":"XB3-14","p":7,"a":"p7","id":"ge2","src":"assets/audio/XB3-14/ge2.mp3","sec":7.536,"t":"离加样孔越远的条带，DNA分子越小；离加样孔越近，DNA分子越大。"},{"ep":"xb3-14","n":"XB3-14","p":7,"a":"p7","id":"ge3","src":"assets/audio/XB3-14/ge3.mp3","sec":7.512,"t":"样品条带与目的基因的大小一致，说明扩增成功，或者受体中含有目的基因。"},{"ep":"xb3-14","n":"XB3-14","p":7,"a":"p7","id":"ge4","src":"assets/audio/XB3-14/ge4.mp3","sec":9.888,"t":"还要设置阳性对照和阴性对照：阳性对照以目的基因为模板，阴性对照不加模板或用非转基因材料。"},{"ep":"xb3-14","n":"XB3-14","p":7,"a":"p7","id":"ge5","src":"assets/audio/XB3-14/ge5.mp3","sec":8.28,"t":"解题方法：先看标准参照物定大小，再看对照排除污染，最后比较样品的条带位置。"},{"ep":"xb3-14","n":"XB3-14","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-14/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-14","n":"XB3-14","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-14/rv2.mp3","sec":12.888,"t":"判断一：农杆菌转化时目的基因插入T-DNA中？对。判断二：培育转基因动物常以体细胞为受体？错，用受精卵。"},{"ep":"xb3-14","n":"XB3-14","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-14/rv3.mp3","sec":12.72,"t":"判断三：Ca2+处理大肠杆菌使其易吸收DNA？对。判断四：检测是否翻译用PCR？错，用抗原—抗体杂交。"},{"ep":"xb3-14","n":"XB3-14","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-14/rv4.mp3","sec":11.952,"t":"判断五：检测出目的基因就说明成功？错，还要个体鉴定。判断六：电泳时DNA分子越小迁移越快？对。"},{"ep":"xb3-14","n":"XB3-14","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-14/rv5.mp3","sec":8.376,"t":"七个考点串成一条线：分子三查PCR加杂交，个体再看性状。我们下期再见！"},{"ep":"xb3-15","n":"XB3-15","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-15/in1.mp3","sec":7.944,"t":"同学们好！这节课梳理人教版选择性必修三第三章第三节——基因工程的应用。"},{"ep":"xb3-15","n":"XB3-15","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-15/in2.mp3","sec":7.824,"t":"高考常考转基因抗虫植物的原理、乳腺生物反应器的构建，以及工程菌生产药物。"},{"ep":"xb3-15","n":"XB3-15","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-15/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-15","n":"XB3-15","p":1,"a":"p1","id":"re1","src":"assets/audio/XB3-15/re1.mp3","sec":7.416,"t":"考点一，在农牧业方面的应用：培育抗虫、抗病、抗除草剂的转基因植物。"},{"ep":"xb3-15","n":"XB3-15","p":1,"a":"p1","id":"re2","src":"assets/audio/XB3-15/re2.mp3","sec":10.176,"t":"抗虫：转入Bt抗虫蛋白基因等，害虫取食后，抗虫蛋白破坏其消化系统，比如我国的转基因抗虫棉。"},{"ep":"xb3-15","n":"XB3-15","p":1,"a":"p1","id":"re3","src":"assets/audio/XB3-15/re3.mp3","sec":7.8,"t":"抗病：转入抗病毒、抗真菌的基因，比如病毒外壳蛋白基因，培育抗病植物。"},{"ep":"xb3-15","n":"XB3-15","p":1,"a":"p1","id":"re4","src":"assets/audio/XB3-15/re4.mp3","sec":7.08,"t":"抗除草剂：转入抗除草剂基因，作物不受除草剂伤害，杂草被清除。"},{"ep":"xb3-15","n":"XB3-15","p":1,"a":"p1","id":"re5","src":"assets/audio/XB3-15/re5.mp3","sec":10.776,"t":"易错：Bt抗虫蛋白只对特定的害虫有毒，对人和畜无害；长期种植可能使害虫产生抗性，要合理种植。"},{"ep":"xb3-15","n":"XB3-15","p":2,"a":"p2","id":"qu1","src":"assets/audio/XB3-15/qu1.mp3","sec":11.064,"t":"考点二，改良农产品的品质、提高动物的生长速度。比如“黄金大米”，转入相关基因后，胚乳中富含β-胡萝卜素。"},{"ep":"xb3-15","n":"XB3-15","p":2,"a":"p2","id":"qu2","src":"assets/audio/XB3-15/qu2.mp3","sec":7.776,"t":"转入肠乳糖酶基因的奶牛，乳汁中乳糖含量大大降低，适合乳糖不耐受的人群。"},{"ep":"xb3-15","n":"XB3-15","p":2,"a":"p2","id":"qu3","src":"assets/audio/XB3-15/qu3.mp3","sec":5.232,"t":"转入外源生长激素基因的鲤鱼等，生长速度明显加快。"},{"ep":"xb3-15","n":"XB3-15","p":2,"a":"p2","id":"qu4","src":"assets/audio/XB3-15/qu4.mp3","sec":8.136,"t":"解题方法：判断应用类型，先看转入的是什么基因、想得到什么性状，就能对号入座。"},{"ep":"xb3-15","n":"XB3-15","p":3,"a":"p3","id":"ma1","src":"assets/audio/XB3-15/ma1.mp3","sec":7.152,"t":"考点三，在医药卫生领域的应用：乳腺生物反应器，也叫乳房生物反应器。"},{"ep":"xb3-15","n":"XB3-15","p":3,"a":"p3","id":"ma2","src":"assets/audio/XB3-15/ma2.mp3","sec":7.92,"t":"构建：将药用蛋白基因与乳腺中特异表达的基因的启动子等调控元件重组在一起。"},{"ep":"xb3-15","n":"XB3-15","p":3,"a":"p3","id":"ma3","src":"assets/audio/XB3-15/ma3.mp3","sec":4.68,"t":"通过显微注射等方法，导入哺乳动物的受精卵中。"},{"ep":"xb3-15","n":"XB3-15","p":3,"a":"p3","id":"ma4","src":"assets/audio/XB3-15/ma4.mp3","sec":7.752,"t":"受精卵发育成转基因动物，进入泌乳期后，通过分泌的乳汁来生产所需要的药物。"},{"ep":"xb3-15","n":"XB3-15","p":3,"a":"p3","id":"ma5","src":"assets/audio/XB3-15/ma5.mp3","sec":9.984,"t":"易错：目的基因存在于转基因动物的所有体细胞中，但只在乳腺细胞中表达，因为用的是乳腺特异性启动子。"},{"ep":"xb3-15","n":"XB3-15","p":4,"a":"p4","id":"dr1","src":"assets/audio/XB3-15/dr1.mp3","sec":9.624,"t":"考点四，基因工程菌生产药物。把药用蛋白基因导入大肠杆菌、酵母菌等微生物，构建工程菌。"},{"ep":"xb3-15","n":"XB3-15","p":4,"a":"p4","id":"dr2","src":"assets/audio/XB3-15/dr2.mp3","sec":6.576,"t":"可以生产胰岛素、干扰素、白细胞介素、溶血栓剂、乙肝疫苗等。"},{"ep":"xb3-15","n":"XB3-15","p":4,"a":"p4","id":"dr3","src":"assets/audio/XB3-15/dr3.mp3","sec":16.752,"t":"建立移植器官工厂：在器官供体的基因组中导入某种调节因子，抑制抗原决定基因的表达，或设法除去抗原决定基因，再结合克隆技术，培育没有免疫排斥反应的转基因克隆猪器官。"},{"ep":"xb3-15","n":"XB3-15","p":4,"a":"p4","id":"dr4","src":"assets/audio/XB3-15/dr4.mp3","sec":12.24,"t":"考法：工程菌选大肠杆菌还是酵母菌？解题方法：蛋白质需要加工修饰，比如糖基化，就选有内质网、高尔基体的酵母菌。"},{"ep":"xb3-15","n":"XB3-15","p":5,"a":"p5","id":"fo1","src":"assets/audio/XB3-15/fo1.mp3","sec":10.056,"t":"考点五，在食品工业方面的应用。利用基因工程菌生产食品工业用酶，比如生产奶酪用的凝乳酶。"},{"ep":"xb3-15","n":"XB3-15","p":5,"a":"p5","id":"fo2","src":"assets/audio/XB3-15/fo2.mp3","sec":4.368,"t":"还可以生产氨基酸、维生素等食品添加剂。"},{"ep":"xb3-15","n":"XB3-15","p":5,"a":"p5","id":"fo3","src":"assets/audio/XB3-15/fo3.mp3","sec":8.184,"t":"与从动物组织中提取相比，工程菌生产产量高、成本低，而且不受原料来源的限制。"},{"ep":"xb3-15","n":"XB3-15","p":5,"a":"p5","id":"fo4","src":"assets/audio/XB3-15/fo4.mp3","sec":6.072,"t":"解题方法：答优点时，从“产量、成本、原料”三个角度作答。"},{"ep":"xb3-15","n":"XB3-15","p":6,"a":"p6","id":"bl1","src":"assets/audio/XB3-15/bl1.mp3","sec":8.232,"t":"考点六，乳腺生物反应器与膀胱生物反应器的比较。两者的受体细胞都是受精卵。"},{"ep":"xb3-15","n":"XB3-15","p":6,"a":"p6","id":"bl2","src":"assets/audio/XB3-15/bl2.mp3","sec":9.216,"t":"乳腺生物反应器：用乳腺蛋白基因的启动子，从乳汁中提取，只能是雌性个体，而且要到泌乳期。"},{"ep":"xb3-15","n":"XB3-15","p":6,"a":"p6","id":"bl3","src":"assets/audio/XB3-15/bl3.mp3","sec":10.128,"t":"膀胱生物反应器：用在膀胱上皮细胞中特异表达的基因的启动子，从尿液中提取，不受性别和年龄的限制。"},{"ep":"xb3-15","n":"XB3-15","p":6,"a":"p6","id":"bl4","src":"assets/audio/XB3-15/bl4.mp3","sec":10.584,"t":"易错：两种反应器的区别在于启动子不同、产物来源不同；受体细胞都是受精卵，不是乳腺细胞或膀胱细胞。"},{"ep":"xb3-15","n":"XB3-15","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-15/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-15","n":"XB3-15","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-15/rv2.mp3","sec":12.048,"t":"判断一：转基因抗虫棉对所有害虫都有抗性？错。判断二：乳腺生物反应器要用乳腺蛋白基因的启动子？对。"},{"ep":"xb3-15","n":"XB3-15","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-15/rv3.mp3","sec":12.816,"t":"判断三：乳腺生物反应器的受体细胞是乳腺细胞？错，是受精卵。判断四：大肠杆菌可作生产胰岛素的工程菌？对。"},{"ep":"xb3-15","n":"XB3-15","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-15/rv4.mp3","sec":12.792,"t":"判断五：雄性转基因动物也能用乳腺生物反应器生产药物？错。判断六：膀胱生物反应器不受性别和年龄限制？对。"},{"ep":"xb3-15","n":"XB3-15","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-15/rv5.mp3","sec":7.344,"t":"六个考点串成一条线：乳腺看启动子，受体选受精卵。我们下期再见！"},{"ep":"xb3-16","n":"XB3-16","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-16/in1.mp3","sec":8.76,"t":"同学们好！这节课梳理人教版选择性必修三第三章第四节——蛋白质工程的原理和应用。"},{"ep":"xb3-16","n":"XB3-16","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-16/in2.mp3","sec":7.968,"t":"高考常考蛋白质工程的基本思路、操作对象，以及蛋白质工程和基因工程的区别。"},{"ep":"xb3-16","n":"XB3-16","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-16/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-16","n":"XB3-16","p":1,"a":"p1","id":"co1","src":"assets/audio/XB3-16/co1.mp3","sec":9.36,"t":"考点一，蛋白质工程的概念。它是指以蛋白质分子的结构规律及其与生物功能的关系作为基础。"},{"ep":"xb3-16","n":"XB3-16","p":1,"a":"p1","id":"co2","src":"assets/audio/XB3-16/co2.mp3","sec":9.504,"t":"通过改造或合成基因，来改造现有蛋白质，或制造一种新的蛋白质，以满足人类生产和生活的需求。"},{"ep":"xb3-16","n":"XB3-16","p":1,"a":"p1","id":"co3","src":"assets/audio/XB3-16/co3.mp3","sec":7.032,"t":"蛋白质工程是在基因工程的基础上延伸出来的，所以被称为第二代基因工程。"},{"ep":"xb3-16","n":"XB3-16","p":1,"a":"p1","id":"co4","src":"assets/audio/XB3-16/co4.mp3","sec":10.536,"t":"为什么需要它？因为基因工程原则上只能生产自然界已存在的蛋白质，而天然蛋白质不一定完全符合人类的需要。"},{"ep":"xb3-16","n":"XB3-16","p":1,"a":"p1","id":"co5","src":"assets/audio/XB3-16/co5.mp3","sec":9.984,"t":"考法：问概念中的关键词。解题方法：抓住“改造或合成基因”，蛋白质工程的落脚点永远是基因。"},{"ep":"xb3-16","n":"XB3-16","p":2,"a":"p2","id":"id1","src":"assets/audio/XB3-16/id1.mp3","sec":6.936,"t":"考点二，蛋白质工程的基本思路。第一步，从预期的蛋白质功能出发。"},{"ep":"xb3-16","n":"XB3-16","p":2,"a":"p2","id":"id2","src":"assets/audio/XB3-16/id2.mp3","sec":3.528,"t":"第二步，设计预期的蛋白质结构。"},{"ep":"xb3-16","n":"XB3-16","p":2,"a":"p2","id":"id3","src":"assets/audio/XB3-16/id3.mp3","sec":3.552,"t":"第三步，推测应有的氨基酸序列。"},{"ep":"xb3-16","n":"XB3-16","p":2,"a":"p2","id":"id4","src":"assets/audio/XB3-16/id4.mp3","sec":7.872,"t":"第四步，找到并改变相对应的脱氧核苷酸序列，也就是基因，或者合成新的基因。"},{"ep":"xb3-16","n":"XB3-16","p":2,"a":"p2","id":"id5","src":"assets/audio/XB3-16/id5.mp3","sec":4.512,"t":"最后，通过基因工程获得所需要的蛋白质。"},{"ep":"xb3-16","n":"XB3-16","p":2,"a":"p2","id":"id6","src":"assets/audio/XB3-16/id6.mp3","sec":9.384,"t":"易错：这条思路与中心法则的方向相反；由于密码子的简并，推出的脱氧核苷酸序列不是唯一的。"},{"ep":"xb3-16","n":"XB3-16","p":3,"a":"p3","id":"ta1","src":"assets/audio/XB3-16/ta1.mp3","sec":6.456,"t":"考点三，蛋白质工程的操作对象是基因，而不是直接改造蛋白质。"},{"ep":"xb3-16","n":"XB3-16","p":3,"a":"p3","id":"ta2","src":"assets/audio/XB3-16/ta2.mp3","sec":6.72,"t":"原因一：蛋白质的结构十分复杂，直接改造蛋白质分子非常困难。"},{"ep":"xb3-16","n":"XB3-16","p":3,"a":"p3","id":"ta3","src":"assets/audio/XB3-16/ta3.mp3","sec":9.336,"t":"原因二：改造后的蛋白质不能遗传；而改造基因后，改造过的蛋白质可以通过基因遗传给下一代。"},{"ep":"xb3-16","n":"XB3-16","p":3,"a":"p3","id":"ta4","src":"assets/audio/XB3-16/ta4.mp3","sec":9.336,"t":"考法：为什么改造基因而不直接改造蛋白质？解题方法：从可遗传和操作难度两方面作答。"},{"ep":"xb3-16","n":"XB3-16","p":4,"a":"p4","id":"cm1","src":"assets/audio/XB3-16/cm1.mp3","sec":10.68,"t":"考点四，蛋白质工程与基因工程的比较。基因工程：遵循中心法则，从DNA到mRNA到蛋白质。"},{"ep":"xb3-16","n":"XB3-16","p":4,"a":"p4","id":"cm2","src":"assets/audio/XB3-16/cm2.mp3","sec":6.792,"t":"蛋白质工程：从预期功能出发，倒推出基因，再通过基因工程实现。"},{"ep":"xb3-16","n":"XB3-16","p":4,"a":"p4","id":"cm3","src":"assets/audio/XB3-16/cm3.mp3","sec":9.048,"t":"结果：基因工程原则上只能生产自然界已有的蛋白质；蛋白质工程可以生产自然界没有的蛋白质。"},{"ep":"xb3-16","n":"XB3-16","p":4,"a":"p4","id":"cm4","src":"assets/audio/XB3-16/cm4.mp3","sec":8.352,"t":"联系：蛋白质工程是在基因工程基础上延伸出来的，最终还要通过基因工程来实现。"},{"ep":"xb3-16","n":"XB3-16","p":4,"a":"p4","id":"cm5","src":"assets/audio/XB3-16/cm5.mp3","sec":10.512,"t":"解题方法：判断用哪种工程，就看产品——天然蛋白质用基因工程，改造过的或全新的蛋白质用蛋白质工程。"},{"ep":"xb3-16","n":"XB3-16","p":5,"a":"p5","id":"ap1","src":"assets/audio/XB3-16/ap1.mp3","sec":13.08,"t":"考点五，蛋白质工程的应用。医药上：天然胰岛素易形成二聚体或六聚体，起效慢；改变其中的氨基酸序列，得到速效胰岛素类似物。"},{"ep":"xb3-16","n":"XB3-16","p":5,"a":"p5","id":"ap2","src":"assets/audio/XB3-16/ap2.mp3","sec":6.84,"t":"干扰素：把其中一个半胱氨酸替换成丝氨酸，可以提高它的储存稳定性。"},{"ep":"xb3-16","n":"XB3-16","p":5,"a":"p5","id":"ap3","src":"assets/audio/XB3-16/ap3.mp3","sec":8.688,"t":"工业上：改造酶的结构，提高酶的热稳定性，比如提高洗涤剂中蛋白酶的耐热、耐碱能力。"},{"ep":"xb3-16","n":"XB3-16","p":5,"a":"p5","id":"ap4","src":"assets/audio/XB3-16/ap4.mp3","sec":6.384,"t":"农业上：改造参与调控光合作用的酶，提高植物的光合作用效率。"},{"ep":"xb3-16","n":"XB3-16","p":5,"a":"p5","id":"ap5","src":"assets/audio/XB3-16/ap5.mp3","sec":9.576,"t":"考法：给一个改造实例，问思路。解题方法：按“功能、结构、氨基酸序列、基因”四步说清楚。"},{"ep":"xb3-16","n":"XB3-16","p":6,"a":"p6","id":"np1","src":"assets/audio/XB3-16/np1.mp3","sec":6.312,"t":"考点六，蛋白质工程能生产自然界不存在的蛋白质吗？能。"},{"ep":"xb3-16","n":"XB3-16","p":6,"a":"p6","id":"np2","src":"assets/audio/XB3-16/np2.mp3","sec":7.176,"t":"通过合成新的基因，蛋白质工程可以制造出自然界中原本没有的新蛋白质。"},{"ep":"xb3-16","n":"XB3-16","p":6,"a":"p6","id":"np3","src":"assets/audio/XB3-16/np3.mp3","sec":8.184,"t":"而基因工程只是把已有的基因转移到别的生物中表达，得到的仍是天然存在的蛋白质。"},{"ep":"xb3-16","n":"XB3-16","p":6,"a":"p6","id":"np4","src":"assets/audio/XB3-16/np4.mp3","sec":9.624,"t":"易错：能产生自然界不存在的蛋白质的是蛋白质工程，不是基因工程；但两者都要改造或操作基因。"},{"ep":"xb3-16","n":"XB3-16","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-16/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-16","n":"XB3-16","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-16/rv2.mp3","sec":12.672,"t":"判断一：蛋白质工程被称为第二代基因工程？对。判断二：蛋白质工程直接改造蛋白质分子？错，改造的是基因。"},{"ep":"xb3-16","n":"XB3-16","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-16/rv3.mp3","sec":11.904,"t":"判断三：蛋白质工程从预期的蛋白质功能出发？对。判断四：基因工程能生产自然界不存在的蛋白质？错。"},{"ep":"xb3-16","n":"XB3-16","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-16/rv4.mp3","sec":12.336,"t":"判断五：速效胰岛素改变了氨基酸序列？对。判断六：推出的脱氧核苷酸序列是唯一的？错，密码子有简并性。"},{"ep":"xb3-16","n":"XB3-16","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-16/rv5.mp3","sec":7.152,"t":"六个考点串成一条线：从功能倒推，最终改的是基因。我们下期再见！"},{"ep":"xb3-17","n":"XB3-17","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-17/in1.mp3","sec":8.232,"t":"同学们好！这节课梳理人教版选择性必修三第四章第一节——转基因产品的安全性。"},{"ep":"xb3-17","n":"XB3-17","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-17/in2.mp3","sec":8.448,"t":"高考常考转基因安全性争论的三个方面、防止基因污染的措施，以及辩证分析类的论述题。"},{"ep":"xb3-17","n":"XB3-17","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-17/in3.mp3","sec":5.448,"t":"我们按五个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-17","n":"XB3-17","p":1,"a":"p1","id":"pr1","src":"assets/audio/XB3-17/pr1.mp3","sec":10.776,"t":"考点一，转基因成果与利弊。在农业上，转基因抗虫棉、抗除草剂作物等，提高了产量、减少了农药的使用。"},{"ep":"xb3-17","n":"XB3-17","p":1,"a":"p1","id":"pr2","src":"assets/audio/XB3-17/pr2.mp3","sec":7.584,"t":"在医药上，基因工程药物如胰岛素、干扰素，缓解了药物短缺，降低了成本。"},{"ep":"xb3-17","n":"XB3-17","p":1,"a":"p1","id":"pr3","src":"assets/audio/XB3-17/pr3.mp3","sec":7.248,"t":"但人们也担心：转基因产品是否会危害人体健康，是否会破坏生态环境。"},{"ep":"xb3-17","n":"XB3-17","p":1,"a":"p1","id":"pr4","src":"assets/audio/XB3-17/pr4.mp3","sec":8.352,"t":"考法：判断转基因技术的意义和风险。解题方法：利和弊都要写，不能只答一面。"},{"ep":"xb3-17","n":"XB3-17","p":2,"a":"p2","id":"de1","src":"assets/audio/XB3-17/de1.mp3","sec":12.936,"t":"考点二，对转基因产品安全性的争论，主要集中在三个方面。食物安全：会不会产生新的过敏原或毒性蛋白，营养成分会不会改变。"},{"ep":"xb3-17","n":"XB3-17","p":2,"a":"p2","id":"de2","src":"assets/audio/XB3-17/de2.mp3","sec":10.272,"t":"生物安全：外源基因会不会通过花粉扩散到近缘物种，转基因生物会不会成为“入侵物种”，影响生物多样性。"},{"ep":"xb3-17","n":"XB3-17","p":2,"a":"p2","id":"de3","src":"assets/audio/XB3-17/de3.mp3","sec":9.168,"t":"环境安全：会不会打破生态平衡，比如抗除草剂基因转移到杂草，产生难以清除的“超级杂草”。"},{"ep":"xb3-17","n":"XB3-17","p":2,"a":"p2","id":"de4","src":"assets/audio/XB3-17/de4.mp3","sec":10.752,"t":"减少基因污染的一个方法：把目的基因导入叶绿体DNA中，因为花粉中一般不含叶绿体，目的基因不会随花粉扩散。"},{"ep":"xb3-17","n":"XB3-17","p":2,"a":"p2","id":"de5","src":"assets/audio/XB3-17/de5.mp3","sec":13.08,"t":"考法：给出一种担忧，判断属于哪类安全。解题方法：看影响对象——人是食物安全，其他生物是生物安全，生态系统是环境安全。"},{"ep":"xb3-17","n":"XB3-17","p":3,"a":"p3","id":"po1","src":"assets/audio/XB3-17/po1.mp3","sec":10.44,"t":"考点三，我国对转基因产品的管理。我国制定了《农业转基因生物安全管理条例》等法规，实行安全评价制度。"},{"ep":"xb3-17","n":"XB3-17","p":3,"a":"p3","id":"po2","src":"assets/audio/XB3-17/po2.mp3","sec":6.696,"t":"对农业转基因生物实行标识制度，保障消费者的知情权和选择权。"},{"ep":"xb3-17","n":"XB3-17","p":3,"a":"p3","id":"po3","src":"assets/audio/XB3-17/po3.mp3","sec":7.848,"t":"对转基因技术，我国的方针是：研究上要大胆，推广上要慎重，管理上要严格。"},{"ep":"xb3-17","n":"XB3-17","p":3,"a":"p3","id":"po4","src":"assets/audio/XB3-17/po4.mp3","sec":7.08,"t":"易错：标识制度是为了保障知情权和选择权，不代表这种产品不安全。"},{"ep":"xb3-17","n":"XB3-17","p":4,"a":"p4","id":"ra1","src":"assets/audio/XB3-17/ra1.mp3","sec":9.144,"t":"考点四，理性看待转基因技术。首先，要靠确凿的证据和严谨的逻辑进行思考和辩论。"},{"ep":"xb3-17","n":"XB3-17","p":4,"a":"p4","id":"ra2","src":"assets/audio/XB3-17/ra2.mp3","sec":6.696,"t":"其次，要看到人们的观点受到社会、文化、经济等多种因素的影响。"},{"ep":"xb3-17","n":"XB3-17","p":4,"a":"p4","id":"ra3","src":"assets/audio/XB3-17/ra3.mp3","sec":7.008,"t":"最后，既不盲目肯定，也不盲目否定，在依法监管的前提下，趋利避害。"},{"ep":"xb3-17","n":"XB3-17","p":4,"a":"p4","id":"ra4","src":"assets/audio/XB3-17/ra4.mp3","sec":9.936,"t":"易错：“转基因食品一定有害”和“转基因食品绝对安全”都是绝对化的说法，判断题里出现，一般都是错的。"},{"ep":"xb3-17","n":"XB3-17","p":5,"a":"p5","id":"me1","src":"assets/audio/XB3-17/me1.mp3","sec":9.672,"t":"考点五，答题方法：辩证分析，有理有据。第一步，表明态度，比如“支持在严格监管下推广”。"},{"ep":"xb3-17","n":"XB3-17","p":5,"a":"p5","id":"me2","src":"assets/audio/XB3-17/me2.mp3","sec":6.504,"t":"第二步，说明好处：比如提高产量、减少农药使用、改善品质。"},{"ep":"xb3-17","n":"XB3-17","p":5,"a":"p5","id":"me3","src":"assets/audio/XB3-17/me3.mp3","sec":8.208,"t":"第三步，指出可能的风险：从食物安全、生物安全、环境安全三个方面选一两点。"},{"ep":"xb3-17","n":"XB3-17","p":5,"a":"p5","id":"me4","src":"assets/audio/XB3-17/me4.mp3","sec":8.448,"t":"第四步，提出措施：安全评价、标识管理、设置隔离带、把目的基因导入叶绿体等。"},{"ep":"xb3-17","n":"XB3-17","p":5,"a":"p5","id":"me5","src":"assets/audio/XB3-17/me5.mp3","sec":7.68,"t":"解题方法：记住四步——态度、好处、风险、措施，论述题就不会跑偏。"},{"ep":"xb3-17","n":"XB3-17","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-17/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-17","n":"XB3-17","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-17/rv2.mp3","sec":11.304,"t":"判断一：转基因作物都对人体有害？错，要靠科学证据。判断二：外源基因可能通过花粉扩散？对。"},{"ep":"xb3-17","n":"XB3-17","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-17/rv3.mp3","sec":11.952,"t":"判断三：把目的基因导入叶绿体可减少基因污染？对。判断四：我国对农业转基因生物实行标识制度？对。"},{"ep":"xb3-17","n":"XB3-17","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-17/rv4.mp3","sec":13.128,"t":"判断五：转基因安全争论已有定论，无需评价？错。判断六：面对转基因应全盘接受或全盘否定？错，要理性看待。"},{"ep":"xb3-17","n":"XB3-17","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-17/rv5.mp3","sec":6.72,"t":"五个考点串成一条线：靠证据说话，趋利又避害。我们下期再见！"},{"ep":"xb3-18","n":"XB3-18","p":0,"a":"intro","id":"in1","src":"assets/audio/XB3-18/in1.mp3","sec":10.536,"t":"同学们好！这节课梳理人教版选择性必修三第四章第二节和第三节——关注生殖性克隆人，禁止生物武器。"},{"ep":"xb3-18","n":"XB3-18","p":0,"a":"intro","id":"in2","src":"assets/audio/XB3-18/in2.mp3","sec":7.632,"t":"高考常考生殖性克隆与治疗性克隆的区别、我国的态度，以及伦理问题的论述。"},{"ep":"xb3-18","n":"XB3-18","p":0,"a":"intro","id":"in3","src":"assets/audio/XB3-18/in3.mp3","sec":5.544,"t":"我们按六个考点梳理，每个考点都讲清楚怎么考、怎么做。"},{"ep":"xb3-18","n":"XB3-18","p":1,"a":"p1","id":"cl1","src":"assets/audio/XB3-18/cl1.mp3","sec":9.84,"t":"考点一，生殖性克隆与治疗性克隆。生殖性克隆，是指通过克隆技术产生独立生存的新个体。"},{"ep":"xb3-18","n":"XB3-18","p":1,"a":"p1","id":"cl2","src":"assets/audio/XB3-18/cl2.mp3","sec":12.888,"t":"治疗性克隆，是指利用克隆技术产生特定的细胞、组织和器官，用它们来修复或替代受损的细胞、组织和器官，从而达到治疗疾病的目的。"},{"ep":"xb3-18","n":"XB3-18","p":1,"a":"p1","id":"cl3","src":"assets/audio/XB3-18/cl3.mp3","sec":7.392,"t":"两者都用到了核移植技术，区别在于目的：一个是产生个体，一个是治疗疾病。"},{"ep":"xb3-18","n":"XB3-18","p":1,"a":"p1","id":"cl4","src":"assets/audio/XB3-18/cl4.mp3","sec":9.408,"t":"解题方法：看结果——产生个体就是生殖性克隆；只得到细胞、组织、器官就是治疗性克隆。"},{"ep":"xb3-18","n":"XB3-18","p":2,"a":"p2","id":"at1","src":"assets/audio/XB3-18/at1.mp3","sec":7.32,"t":"考点二，我国对克隆人的态度。我国政府的态度是：禁止生殖性克隆人。"},{"ep":"xb3-18","n":"XB3-18","p":2,"a":"p2","id":"at2","src":"assets/audio/XB3-18/at2.mp3","sec":7.728,"t":"坚持“四不”原则：不赞成、不允许、不支持、不接受任何生殖性克隆人的实验。"},{"ep":"xb3-18","n":"XB3-18","p":2,"a":"p2","id":"at3","src":"assets/audio/XB3-18/at3.mp3","sec":6.312,"t":"但不反对治疗性克隆，前提是要进行有效的监控和严格审查。"},{"ep":"xb3-18","n":"XB3-18","p":2,"a":"p2","id":"at4","src":"assets/audio/XB3-18/at4.mp3","sec":10.344,"t":"反对克隆人的理由：克隆人严重违反了人类伦理道德；克隆技术尚不成熟，可能孕育出有严重生理缺陷的孩子。"},{"ep":"xb3-18","n":"XB3-18","p":2,"a":"p2","id":"at5","src":"assets/audio/XB3-18/at5.mp3","sec":7.152,"t":"易错：我国禁止的是生殖性克隆，不是所有克隆；对治疗性克隆不反对。"},{"ep":"xb3-18","n":"XB3-18","p":3,"a":"p3","id":"iv1","src":"assets/audio/XB3-18/iv1.mp3","sec":10.008,"t":"考点三，试管婴儿与设计试管婴儿。试管婴儿：通过体外受精和胚胎移植，解决不孕不育的问题。"},{"ep":"xb3-18","n":"XB3-18","p":3,"a":"p3","id":"iv2","src":"assets/audio/XB3-18/iv2.mp3","sec":8.808,"t":"设计试管婴儿：在胚胎移植前，要对胚胎进行遗传学诊断，选择符合要求的胚胎再移植。"},{"ep":"xb3-18","n":"XB3-18","p":3,"a":"p3","id":"iv3","src":"assets/audio/XB3-18/iv3.mp3","sec":8.496,"t":"设计试管婴儿可用于避免遗传病，或者为患病的哥哥姐姐提供配型相合的造血干细胞等。"},{"ep":"xb3-18","n":"XB3-18","p":3,"a":"p3","id":"iv4","src":"assets/audio/XB3-18/iv4.mp3","sec":6.864,"t":"两者都属于有性生殖，都用到体外受精、早期胚胎培养和胚胎移植。"},{"ep":"xb3-18","n":"XB3-18","p":3,"a":"p3","id":"iv5","src":"assets/audio/XB3-18/iv5.mp3","sec":9.456,"t":"易错：两者的区别在于设计试管婴儿多了遗传学诊断；不能借此随意选择性别等非医学需要的性状。"},{"ep":"xb3-18","n":"XB3-18","p":4,"a":"p4","id":"we1","src":"assets/audio/XB3-18/we1.mp3","sec":9.336,"t":"考点四，生物武器的种类和特点。生物武器的种类包括：致病菌类、病毒类和生化毒剂类等。"},{"ep":"xb3-18","n":"XB3-18","p":4,"a":"p4","id":"we2","src":"assets/audio/XB3-18/we2.mp3","sec":8.736,"t":"还可以通过转基因技术，把致病能力、抗药性等基因转入病原体，制造出新的“超级”病原体。"},{"ep":"xb3-18","n":"XB3-18","p":4,"a":"p4","id":"we3","src":"assets/audio/XB3-18/we3.mp3","sec":8.472,"t":"生物武器的特点：致病能力强、攻击范围广，可以通过空气、水、食物等多种途径传播。"},{"ep":"xb3-18","n":"XB3-18","p":4,"a":"p4","id":"we4","src":"assets/audio/XB3-18/we4.mp3","sec":13.344,"t":"考法：判断哪些属于生物武器。解题方法：看它是不是利用生物或其毒素来致病、致死，比如炭疽杆菌、天花病毒、肉毒杆菌毒素。"},{"ep":"xb3-18","n":"XB3-18","p":5,"a":"p5","id":"ba1","src":"assets/audio/XB3-18/ba1.mp3","sec":7.968,"t":"考点五，我国对生物武器的态度。1972年，多国签署了《禁止生物武器公约》。"},{"ep":"xb3-18","n":"XB3-18","p":5,"a":"p5","id":"ba2","src":"assets/audio/XB3-18/ba2.mp3","sec":6.696,"t":"我国的态度是：在任何情况下，不发展、不生产、不储存生物武器。"},{"ep":"xb3-18","n":"XB3-18","p":5,"a":"p5","id":"ba3","src":"assets/audio/XB3-18/ba3.mp3","sec":4.176,"t":"并反对生物武器及其技术和设备的扩散。"},{"ep":"xb3-18","n":"XB3-18","p":5,"a":"p5","id":"ba4","src":"assets/audio/XB3-18/ba4.mp3","sec":10.8,"t":"易错：克隆人是“四不”——不赞成、不允许、不支持、不接受；生物武器是“三不”加反对扩散。两组不要记混。"},{"ep":"xb3-18","n":"XB3-18","p":6,"a":"p6","id":"et1","src":"assets/audio/XB3-18/et1.mp3","sec":8.592,"t":"考点六，生物技术伦理问题的答题思路。第一，明确技术本身：它是什么、能做什么。"},{"ep":"xb3-18","n":"XB3-18","p":6,"a":"p6","id":"et2","src":"assets/audio/XB3-18/et2.mp3","sec":6.768,"t":"第二，分析利与弊：对个人、社会、生态可能带来的好处和风险。"},{"ep":"xb3-18","n":"XB3-18","p":6,"a":"p6","id":"et3","src":"assets/audio/XB3-18/et3.mp3","sec":7.056,"t":"第三，联系法规和我国态度：比如禁止生殖性克隆、禁止生物武器。"},{"ep":"xb3-18","n":"XB3-18","p":6,"a":"p6","id":"et4","src":"assets/audio/XB3-18/et4.mp3","sec":9.0,"t":"第四，表明理性立场：科学技术是一把“双刃剑”，要趋利避害，在伦理和法律的框架内发展。"},{"ep":"xb3-18","n":"XB3-18","p":6,"a":"p6","id":"et5","src":"assets/audio/XB3-18/et5.mp3","sec":8.064,"t":"解题方法：伦理题四步走——技术、利弊、法规、立场，观点明确，有理有据。"},{"ep":"xb3-18","n":"XB3-18","p":"review","a":"review","id":"rv1","src":"assets/audio/XB3-18/rv1.mp3","sec":3.576,"t":"最后，用六道判断题检验一下。"},{"ep":"xb3-18","n":"XB3-18","p":"review","a":"review","id":"rv2","src":"assets/audio/XB3-18/rv2.mp3","sec":10.176,"t":"判断一：治疗性克隆的目的是产生新个体？错。判断二：我国不反对治疗性克隆？对。"},{"ep":"xb3-18","n":"XB3-18","p":"review","a":"review","id":"rv3","src":"assets/audio/XB3-18/rv3.mp3","sec":14.136,"t":"判断三：设计试管婴儿与试管婴儿技术完全相同？错，多了遗传学诊断。判断四：生物武器包括致病菌、病毒、生化毒剂等？对。"},{"ep":"xb3-18","n":"XB3-18","p":"review","a":"review","id":"rv4","src":"assets/audio/XB3-18/rv4.mp3","sec":11.304,"t":"判断五：我国在特殊情况下可以发展生物武器？错。判断六：设计试管婴儿可以用于选择性别？错。"},{"ep":"xb3-18","n":"XB3-18","p":"review","a":"review","id":"rv5","src":"assets/audio/XB3-18/rv5.mp3","sec":9.744,"t":"六个考点串成一条线：四不三不记牢，伦理题有理有据。选择性必修三全部讲完，我们下次再见！"}];
